window.__TOPIC_JS=window.__TOPIC_JS||{};window.__TOPIC_JS["副詞"]={
"_note": "1. 副詞 (phó từ) — mỗi từ một dòng. LEVEL: a1 = 副詞 dạng と／に (gốc Hán, văn viết); b1 = từ tượng thanh/tượng hình khẩu ngữ (擬音語・擬態語); c1 = 陳述副詞 (phó từ đi cặp với cấu trúc cố định: ～ない, ～ようだ, ～ても…); d1 = phó từ chỉ mức độ, thời gian, tần suất; e1 = phó từ chỉ ý kiến, suy đoán, nối ý. THỨ TỰ: các nhóm xếp a1, b1, c1, d1, e1, không trộn lẫn; trong mỗi nhóm từ hay dùng đứng trước, từ hiếm/văn chương đứng sau (từ mới chèn đúng vị trí theo tần suất, không nối cuối nhóm). ĐỊNH DẠNG MỖI TỪ: word, reading, meaning, hanviet (chỉ khi từ có chữ Hán), note, example, example_reading, example_meaning (ba trường này là bản sao ví dụ 1), examples [đúng 2 ví dụ khác ngữ cảnh/cách dùng], level. note viết ngắn bằng tiếng Việt; với 陳述副詞 ghi rõ cấu trúc đi kèm. example_reading viết bằng hiragana, từ ngoại lai giữ katakana; không còn chữ Hán. Không được trùng trường word. TRƯỜNG antonym (tuỳ chọn): từ trái nghĩa, dạng \"từ（cách đọc）: nghĩa\", nhiều từ cách nhau bằng \" / \". TRƯỜNG antonym_hanviet (tuỳ chọn, đi kèm antonym): âm Hán Việt của từng từ trái nghĩa, viết thường như trường hanviet, cùng thứ tự và cách nhau bằng \" / \" (từ chỉ có kana, không có chữ Hán, để trống). SỐ LƯỢNG: a1 205 (gồm mục pair 自然（と／に）; 57 cũ + 148 mới), b1 430 (63 cũ + 367 mới), c1 117, d1 331, e1 267; tổng 1350 mục. TRẠNG THÁI: Tất cả mục (kể cả 120 mục a1/b1 cũ) đã có đủ 2 ví dụ trong 'examples'; riêng mục pair 自然（と／に） có 2 ví dụ ở mỗi từ con (自然と, 自然に). Trường antonym hiện có cho 785/1350 từ (324 từ gốc + 455 từ mới; 83 từ gốc được bổ sung thêm chiều ngược lại); antonym_hanviet có cho 504 từ (từ chỉ có kana thì không có). Phần còn lại là từ không có trái nghĩa rõ ràng (từ tượng thanh/tượng hình đơn lẻ, liên từ, từ chỉ thời điểm…). Bảng trái nghĩa tự soạn, chưa đối chiếu từ điển. Ghi chú: file gốc chưa có _note; phần quy tắc này được lập lại theo yêu cầu biên soạn.",
"id": "1. 副詞",
"title": "副詞",
"icon": "💬",
"category": "ref",
"kind": "adverb",
"vocab": [
{"word":"自然（と／に）","reading":"しぜん","meaning":"phó từ gốc 自然: dùng と hoặc に, nghĩa khác nhau","hanviet":"tự nhiên","antonym":"不自然に（ふしぜんに）: không tự nhiên","antonym_hanviet":"bất tự nhiên","pair":[{"word":"自然と","reading":"しぜんと","hanviet":"tự nhiên","meaning":"tự khắc, theo lẽ tự nhiên (không cần cố ý)","notes":["Tiến trình / quy luật khách quan. Hay đi với なる, ～てくる, ～ようになる. Dùng nhiều trong văn viết."],"examples":[{"example":"長く住むうちに、自然と日本語が話せるようになりました。","example_reading":"ながくすむうちに、しぜんとにほんごがはなせるようになりました。","example_meaning":"Sống lâu rồi thì tự khắc nói được tiếng Nhật."},{"example":"子どもの話を聞いていると、自然と笑顔になる。","example_reading":"こどものはなしをきいていると、しぜんとえがおになる。","example_meaning":"Nghe con kể chuyện, tự khắc nở nụ cười."}]},{"word":"自然に","reading":"しぜんに","hanviet":"tự nhiên","meaning":"một cách tự nhiên, không gượng gạo","notes":["Trạng thái / cách thức của hành động. Trái nghĩa: 不自然に (gượng gạo)."],"examples":[{"example":"緊張しないで、自然に笑ってください。","example_reading":"きんちょうしないで、しぜんにわらってください。","example_meaning":"Đừng căng thẳng, hãy cười thật tự nhiên."},{"example":"彼女はカメラの前でも自然に振る舞っていた。","example_reading":"かのじょはカメラのまえでもしぜんにふるまっていた。","example_meaning":"Cô ấy cư xử tự nhiên ngay cả trước ống kính."}]}],"pair_label":"と／に の使い分け","level":"a1"},
{"word":"漠然と","reading":"ばくぜんと","meaning":"mơ hồ, mông lung, không rõ ràng","hanviet":"mạc nhiên","antonym":"明確に（めいかくに）: rõ ràng / はっきり: rõ ràng / 歴然と（れきぜんと）: rõ rệt","antonym_hanviet":"minh xác /  / lịch nhiên","note":"Dạng と. Hay đi với 考える, 感じる, 不安. Dùng nhiều trong văn viết.","example":"将来について漠然と不安を感じています。","example_reading":"しょうらいについてばくぜんとふあんをかんじています。","example_meaning":"Tôi cảm thấy bất an mơ hồ về tương lai.","examples":[{"example":"将来について漠然と不安を感じています。","example_reading":"しょうらいについてばくぜんとふあんをかんじています。","example_meaning":"Tôi cảm thấy bất an mơ hồ về tương lai."},{"example":"彼は漠然とした夢を持っているだけで、具体的な計画はない。","example_reading":"かれはばくぜんとしたゆめをもっているだけで、ぐたいてきなけいかくはない。","example_meaning":"Anh ấy chỉ có một ước mơ mơ hồ, chưa có kế hoạch cụ thể."}],"level":"a1"},
{"word":"淡々と","reading":"たんたんと","meaning":"điềm nhiên, thản nhiên, không biểu lộ cảm xúc","hanviet":"đạm đạm","antonym":"感情的に（かんじょうてきに）: đầy cảm xúc","antonym_hanviet":"cảm tình đích","note":"Dạng と. Làm việc hoặc kể chuyện một cách bình thản, không chen cảm xúc.","example":"彼は淡々と事実だけを話した。","example_reading":"かれはたんたんとじじつだけをはなした。","example_meaning":"Anh ấy chỉ thản nhiên kể lại sự thật.","examples":[{"example":"彼は淡々と事実だけを話した。","example_reading":"かれはたんたんとじじつだけをはなした。","example_meaning":"Anh ấy chỉ thản nhiên kể lại sự thật."},{"example":"彼女は淡々とした口調で、悲しいニュースを伝えた。","example_reading":"かのじょはたんたんとしたくちょうで、かなしいニュースをつたえた。","example_meaning":"Cô ấy truyền đạt tin buồn bằng giọng thản nhiên."}],"level":"a1"},
{"word":"黙々と","reading":"もくもくと","meaning":"lặng lẽ, miệt mài (làm mà không nói)","hanviet":"mặc mặc","antonym":"ぺちゃくちゃ: nói huyên thuyên / べらべら: nói liến thoắng","note":"Dạng と. Hay đi với 働く, 練習する, 食べる.","example":"彼は毎日黙々と練習を続けている。","example_reading":"かれはまいにちもくもくとれんしゅうをつづけている。","example_meaning":"Anh ấy ngày nào cũng lặng lẽ miệt mài luyện tập.","examples":[{"example":"彼は毎日黙々と練習を続けている。","example_reading":"かれはまいにちもくもくとれんしゅうをつづけている。","example_meaning":"Anh ấy ngày nào cũng lặng lẽ miệt mài luyện tập."},{"example":"学生たちは黙々と試験問題を解いている。","example_reading":"がくせいたちはもくもくとしけんもんだいをといている。","example_meaning":"Các sinh viên lặng lẽ làm bài thi."}],"level":"a1"},
{"word":"堂々と","reading":"どうどうと","meaning":"đường hoàng, hiên ngang, không e dè","hanviet":"đường đường","antonym":"こっそり: lén lút / びくびく: hoảng sợ / おろおろ: luống cuống","note":"Dạng と. Thái độ tự tin, không rụt rè hay giấu giếm.","example":"自信を持って、堂々と発表してください。","example_reading":"じしんをもって、どうどうとはっぴょうしてください。","example_meaning":"Hãy tự tin, phát biểu thật đường hoàng.","examples":[{"example":"自信を持って、堂々と発表してください。","example_reading":"じしんをもって、どうどうとはっぴょうしてください。","example_meaning":"Hãy tự tin, phát biểu thật đường hoàng."},{"example":"彼は堂々とした態度で、記者の質問に答えた。","example_reading":"かれはどうどうとしたたいどで、きしゃのしつもんにこたえた。","example_meaning":"Anh ấy trả lời câu hỏi của phóng viên với thái độ đường hoàng."}],"level":"a1"},
{"word":"着々と","reading":"ちゃくちゃくと","meaning":"từng bước chắc chắn, đều đặn","hanviet":"trước trước","antonym":"遅々として（ちちとして）: chậm chạp","antonym_hanviet":"trì trì","note":"Dạng と. Hay đi với 進む, 進める (công việc, chuẩn bị).","example":"準備は着々と進んでいます。","example_reading":"じゅんびはちゃくちゃくとすすんでいます。","example_meaning":"Việc chuẩn bị đang tiến triển đều đặn.","examples":[{"example":"準備は着々と進んでいます。","example_reading":"じゅんびはちゃくちゃくとすすんでいます。","example_meaning":"Việc chuẩn bị đang tiến triển đều đặn."},{"example":"新しい駅の工事が着々と進んでいる。","example_reading":"あたらしいえきのこうじがちゃくちゃくとすすんでいる。","example_meaning":"Công trình nhà ga mới đang tiến triển đều đặn."}],"level":"a1"},
{"word":"刻々と","reading":"こくこくと","meaning":"từng giây từng phút (thay đổi liên tục)","hanviet":"khắc khắc","note":"Dạng と. Hay đi với 変わる, 近づく. Văn viết, bản tin.","example":"台風の状況は刻々と変わっています。","example_reading":"たいふうのじょうきょうはこくこくとかわっています。","example_meaning":"Tình hình bão thay đổi từng phút.","examples":[{"example":"台風の状況は刻々と変わっています。","example_reading":"たいふうのじょうきょうはこくこくとかわっています。","example_meaning":"Tình hình bão thay đổi từng phút."},{"example":"刻々と近づく発表の時間に、緊張が高まった。","example_reading":"こくこくとちかづくはっぴょうのじかんに、きんちょうがたかまった。","example_meaning":"Giờ thuyết trình đến gần từng phút khiến sự căng thẳng tăng lên."}],"level":"a1"},
{"word":"平然と","reading":"へいぜんと","meaning":"bình thản, thản nhiên (như không có chuyện gì)","hanviet":"bình nhiên","antonym":"動揺して（どうようして）: bối rối, dao động / びっくり: giật mình","antonym_hanviet":"động dao / ","note":"Dạng と. Thường dùng khi người ta lẽ ra phải bối rối hoặc áy náy.","example":"彼は平然と嘘をついた。","example_reading":"かれはへいぜんとうそをついた。","example_meaning":"Anh ta thản nhiên nói dối.","examples":[{"example":"彼は平然と嘘をついた。","example_reading":"かれはへいぜんとうそをついた。","example_meaning":"Anh ta thản nhiên nói dối."},{"example":"彼女は叱られても平然としていた。","example_reading":"かのじょはしかられてもへいぜんとしていた。","example_meaning":"Dù bị mắng, cô ấy vẫn thản nhiên."}],"level":"a1"},
{"word":"整然と","reading":"せいぜんと","meaning":"ngăn nắp, trật tự, ngay hàng thẳng lối","hanviet":"chỉnh nhiên","antonym":"雑然と（ざつぜんと）: bừa bộn, lộn xộn","antonym_hanviet":"tạp nhiên","note":"Dạng と. Hay đi với 並ぶ, 並べる.","example":"生徒たちは整然と並んで待っていた。","example_reading":"せいとたちはせいぜんとならんでまっていた。","example_meaning":"Học sinh xếp hàng ngay ngắn chờ đợi.","examples":[{"example":"生徒たちは整然と並んで待っていた。","example_reading":"せいとたちはせいぜんとならんでまっていた。","example_meaning":"Học sinh xếp hàng ngay ngắn chờ đợi."},{"example":"机と椅子が整然と並べられた教室だ。","example_reading":"つくえといすがせいぜんとならべられたきょうしつだ。","example_meaning":"Đó là lớp học có bàn ghế xếp ngay ngắn."}],"level":"a1"},
{"word":"簡単に","reading":"かんたんに","meaning":"một cách đơn giản, dễ dàng","hanviet":"giản đơn","antonym":"複雑に（ふくざつに）: phức tạp / 難しく（むずかしく）: khó khăn","antonym_hanviet":"phức tạp / nan","note":"Dạng に. Hay đi với できる, 説明する, 済ませる, 諦める. 簡単に済ませる = giải quyết qua loa.","example":"このアプリを使えば、誰でも簡単に写真を編集できる。","example_reading":"このアプリをつかえば、だれでもかんたんにしゃしんをへんしゅうできる。","example_meaning":"Dùng ứng dụng này thì ai cũng chỉnh sửa ảnh dễ dàng.","examples":[{"example":"このアプリを使えば、誰でも簡単に写真を編集できる。","example_reading":"このアプリをつかえば、だれでもかんたんにしゃしんをへんしゅうできる。","example_meaning":"Dùng ứng dụng này thì ai cũng chỉnh sửa ảnh dễ dàng."},{"example":"自己紹介は簡単にお願いします。","example_reading":"じこしょうかいはかんたんにおねがいします。","example_meaning":"Xin hãy giới thiệu bản thân ngắn gọn thôi."}],"level":"a1"},
{"word":"次第に","reading":"しだいに","meaning":"dần dần (tự biến đổi theo thời gian)","hanviet":"thứ đệ","note":"Dạng に. Sự việc tự thay đổi từ từ, hay đi với なる, ～てくる.","antonym":"急に（きゅうに）: đột ngột","antonym_hanviet":"cấp","example":"夜になって、次第に寒くなってきました。","example_reading":"よるになって、しだいにさむくなってきました。","example_meaning":"Về đêm trời dần lạnh đi.","examples":[{"example":"夜になって、次第に寒くなってきました。","example_reading":"よるになって、しだいにさむくなってきました。","example_meaning":"Về đêm trời dần lạnh đi."},{"example":"彼の日本語は次第に上手になっていった。","example_reading":"かれのにほんごはしだいにじょうずになっていった。","example_meaning":"Tiếng Nhật của anh ấy dần dần giỏi lên."}],"level":"a1"},
{"word":"徐々に","reading":"じょじょに","meaning":"từ từ, dần dần (từng bước nhỏ)","hanviet":"từ từ","antonym":"突然（とつぜん）: đột nhiên / 急に（きゅうに）: đột ngột / 即座に（そくざに）: ngay lập tức","antonym_hanviet":"đột nhiên / cấp / tức tọa","note":"Dạng に. Nhấn mạnh tiến độ chậm, từng chút một.","example":"徐々に新しい生活に慣れてきました。","example_reading":"じょじょにあたらしいせいかつになれてきました。","example_meaning":"Tôi dần quen với cuộc sống mới.","examples":[{"example":"徐々に新しい生活に慣れてきました。","example_reading":"じょじょにあたらしいせいかつになれてきました。","example_meaning":"Tôi dần quen với cuộc sống mới."},{"example":"車は徐々にスピードを落として止まった。","example_reading":"くるまはじょじょにスピードをおとしてとまった。","example_meaning":"Chiếc xe từ từ giảm tốc rồi dừng lại."}],"level":"a1"},
{"word":"気軽に","reading":"きがるに","meaning":"một cách thoải mái, không câu nệ","hanviet":"khí khinh","antonym":"堅苦しく（かたくるしく）: cứng nhắc, câu nệ","antonym_hanviet":"kiên khổ","note":"Dạng に. Hay đi với 話す, 相談する, 立ち寄る, 声をかける.","example":"困ったことがあれば、気軽に相談してください。","example_reading":"こまったことがあれば、きがるにそうだんしてください。","example_meaning":"Nếu có chuyện gì khó, cứ thoải mái trao đổi nhé.","examples":[{"example":"困ったことがあれば、気軽に相談してください。","example_reading":"こまったことがあれば、きがるにそうだんしてください。","example_meaning":"Nếu có chuyện gì khó, cứ thoải mái trao đổi nhé."},{"example":"近くに来たら、気軽に立ち寄ってね。","example_reading":"ちかくにきたら、きがるにたちよってね。","example_meaning":"Khi ghé gần đây thì cứ ghé chơi nhé."}],"level":"a1"},
{"word":"真剣に","reading":"しんけんに","meaning":"một cách nghiêm túc, hết sức nghiêm chỉnh","hanviet":"chân kiếm","antonym":"適当に（てきとうに）: qua loa / ふざけて: đùa cợt","antonym_hanviet":"thích đương / ","note":"Dạng に. Hay đi với 考える, 聞く, 取り組む. Thái độ nghiêm túc, không đùa cợt.","example":"将来のことを真剣に考えなければならない時期だ。","example_reading":"しょうらいのことをしんけんにかんがえなければならないじきだ。","example_meaning":"Đã đến lúc phải nghiêm túc suy nghĩ về tương lai.","examples":[{"example":"将来のことを真剣に考えなければならない時期だ。","example_reading":"しょうらいのことをしんけんにかんがえなければならないじきだ。","example_meaning":"Đã đến lúc phải nghiêm túc suy nghĩ về tương lai."},{"example":"彼女は先生の話を真剣に聞いていた。","example_reading":"かのじょはせんせいのはなしをしんけんにきいていた。","example_meaning":"Cô ấy chăm chú nghe thầy nói."}],"level":"a1"},
{"word":"自由に","reading":"じゆうに","meaning":"một cách tự do, thoải mái, không bị ràng buộc","hanviet":"tự do","antonym":"不自由に（ふじゆうに）: không tự do, bất tiện","antonym_hanviet":"bất tự do","note":"Dạng に. Hay đi với 使う, 選ぶ, 動く, 話す. Rất thường dùng.","example":"ここにある本は自由に読んでください。","example_reading":"ここにあるほんはじゆうによんでください。","example_meaning":"Sách ở đây xin cứ tự do đọc.","examples":[{"example":"ここにある本は自由に読んでください。","example_reading":"ここにあるほんはじゆうによんでください。","example_meaning":"Sách ở đây xin cứ tự do đọc."},{"example":"大学では自由に時間割を組むことができる。","example_reading":"だいがくではじゆうにじかんわりをくむことができる。","example_meaning":"Ở đại học có thể tự do sắp xếp thời khóa biểu."}],"level":"a1"},
{"word":"十分に","reading":"じゅうぶんに","meaning":"một cách đầy đủ, thỏa đáng","hanviet":"thập phân","antonym":"不十分に（ふじゅうぶんに）: không đầy đủ","antonym_hanviet":"bất thập phân","note":"Dạng に. Hay đi với 休む, 準備する, 理解する. Đọc じゅうぶん, không phải じっぷん.","example":"試験の前に十分に睡眠をとっておきましょう。","example_reading":"しけんのまえにじゅうぶんにすいみんをとっておきましょう。","example_meaning":"Trước kỳ thi hãy ngủ cho đủ giấc.","examples":[{"example":"試験の前に十分に睡眠をとっておきましょう。","example_reading":"しけんのまえにじゅうぶんにすいみんをとっておきましょう。","example_meaning":"Trước kỳ thi hãy ngủ cho đủ giấc."},{"example":"彼の説明で、問題は十分に理解できた。","example_reading":"かれのせつめいで、もんだいはじゅうぶんにりかいできた。","example_meaning":"Nhờ lời giải thích của anh ấy, tôi đã hiểu thấu đáo vấn đề."}],"level":"a1"},
{"word":"特別に","reading":"とくべつに","meaning":"đặc biệt, ngoại lệ","hanviet":"đặc biệt","antonym":"普通に（ふつうに）: bình thường / 一般的に（いっぱんてきに）: nói chung / 普通は（ふつうは）: bình thường thì","antonym_hanviet":"phổ thông / nhất ban đích / phổ thông","note":"Dạng に. Hay đi với 許す, 用意する, 扱う. Làm điều vượt ngoài quy định thông thường.","example":"今回だけ特別に、締め切りを延ばしてあげましょう。","example_reading":"こんかいだけとくべつに、しめきりをのばしてあげましょう。","example_meaning":"Chỉ lần này thôi, tôi sẽ đặc biệt gia hạn cho.","examples":[{"example":"今回だけ特別に、締め切りを延ばしてあげましょう。","example_reading":"こんかいだけとくべつに、しめきりをのばしてあげましょう。","example_meaning":"Chỉ lần này thôi, tôi sẽ đặc biệt gia hạn cho."},{"example":"誕生日なので、特別に大きなケーキを注文した。","example_reading":"たんじょうびなので、とくべつにおおきなケーキをちゅうもんした。","example_meaning":"Vì là sinh nhật nên tôi đặt một chiếc bánh đặc biệt to."}],"level":"a1"},
{"word":"完全に","reading":"かんぜんに","meaning":"hoàn toàn, trọn vẹn","hanviet":"hoàn toàn","antonym":"不完全に（ふかんぜんに）: không hoàn chỉnh / 部分的に（ぶぶんてきに）: một phần","antonym_hanviet":"bất hoàn toàn / bộ phân đích","note":"Dạng に. Hay đi với 忘れる, 治る, 違う, 失敗する. Nhấn mạnh mức độ tuyệt đối.","example":"風邪は一週間で完全に治りました。","example_reading":"かぜはいっしゅうかんでかんぜんになおりました。","example_meaning":"Bệnh cảm đã khỏi hoàn toàn sau một tuần.","examples":[{"example":"風邪は一週間で完全に治りました。","example_reading":"かぜはいっしゅうかんでかんぜんになおりました。","example_meaning":"Bệnh cảm đã khỏi hoàn toàn sau một tuần."},{"example":"彼の名前を完全に忘れてしまった。","example_reading":"かれのなまえをかんぜんにわすれてしまった。","example_meaning":"Tôi quên hẳn tên anh ấy mất rồi."}],"level":"a1"},
{"word":"大切に","reading":"たいせつに","meaning":"một cách cẩn thận, trân trọng","hanviet":"đại thiết","antonym":"粗末に（そまつに）: cẩu thả, không trân trọng","antonym_hanviet":"thô mạt","note":"Dạng に. Hay đi với 使う, 扱う, 育てる, 保管する.","example":"祖母からもらった指輪を大切にしています。","example_reading":"そぼからもらったゆびわをたいせつにしています。","example_meaning":"Tôi trân trọng giữ gìn chiếc nhẫn bà tặng.","examples":[{"example":"祖母からもらった指輪を大切にしています。","example_reading":"そぼからもらったゆびわをたいせつにしています。","example_meaning":"Tôi trân trọng giữ gìn chiếc nhẫn bà tặng."},{"example":"本は大切に扱ってください。","example_reading":"ほんはたいせつにあつかってください。","example_meaning":"Hãy cẩn thận khi dùng sách."}],"level":"a1"},
{"word":"丁寧に","reading":"ていねいに","meaning":"cẩn thận, tỉ mỉ, lịch sự","hanviet":"đinh ninh","antonym":"乱暴に（らんぼうに）: thô bạo / 雑に（ざつに）: qua loa, cẩu thả / 無造作に（むぞうさに）: tùy tiện","antonym_hanviet":"loạn bạo / tạp / vô tạo tác","note":"Dạng に. Hay đi với 説明する, 洗う, 書く, 断る. Vừa chu đáo vừa lịch sự.","example":"先生は質問に丁寧に答えてくれた。","example_reading":"せんせいはしつもんにていねいにこたえてくれた。","example_meaning":"Thầy đã tận tình trả lời câu hỏi.","examples":[{"example":"先生は質問に丁寧に答えてくれた。","example_reading":"せんせいはしつもんにていねいにこたえてくれた。","example_meaning":"Thầy đã tận tình trả lời câu hỏi."},{"example":"お皿を一枚ずつ丁寧に洗った。","example_reading":"おさらをいちまいずつていねいにあらった。","example_meaning":"Tôi rửa từng chiếc đĩa một cách cẩn thận."}],"level":"a1"},
{"word":"正直に","reading":"しょうじきに","meaning":"một cách thành thật, thẳng thắn","hanviet":"chính trực","antonym":"偽って（いつわって）: giả dối","antonym_hanviet":"ngụy","note":"Dạng に. Hay đi với 話す, 言う, 認める, 答える.","example":"本当のことを正直に話してください。","example_reading":"ほんとうのことをしょうじきにはなしてください。","example_meaning":"Xin hãy nói thật lòng.","examples":[{"example":"本当のことを正直に話してください。","example_reading":"ほんとうのことをしょうじきにはなしてください。","example_meaning":"Xin hãy nói thật lòng."},{"example":"間違いを正直に認めたら、先生は許してくれた。","example_reading":"まちがいをしょうじきにみとめたら、せんせいはゆるしてくれた。","example_meaning":"Khi tôi thành thật nhận lỗi, thầy đã tha thứ."}],"level":"a1"},
{"word":"一生懸命に","reading":"いっしょうけんめいに","meaning":"hết sức mình, chăm chỉ miệt mài","hanviet":"nhất sinh huyền mệnh","antonym":"いい加減に（いいかげんに）: qua loa","antonym_hanviet":"gia giảm","note":"Dạng に. Hay đi với 働く, 勉強する, 頑張る. Cũng dùng dạng 一生懸命 không に.","example":"合格するために一生懸命に勉強しています。","example_reading":"ごうかくするためにいっしょうけんめいにべんきょうしています。","example_meaning":"Tôi đang học hết sức để đỗ.","examples":[{"example":"合格するために一生懸命に勉強しています。","example_reading":"ごうかくするためにいっしょうけんめいにべんきょうしています。","example_meaning":"Tôi đang học hết sức để đỗ."},{"example":"彼女は子どもたちのために一生懸命に働いている。","example_reading":"かのじょはこどもたちのためにいっしょうけんめいにはたらいている。","example_meaning":"Cô ấy làm việc hết mình vì các con."}],"level":"a1"},
{"word":"親切に","reading":"しんせつに","meaning":"một cách tử tế, tận tình","hanviet":"thân thiết","antonym":"不親切に（ふしんせつに）: thiếu tử tế / 冷たく（つめたく）: lạnh nhạt","antonym_hanviet":"bất thân thiết / lãnh","note":"Dạng に. Hay đi với 教える, 説明する, 案内する, 対応する.","example":"道に迷っていたら、親切に駅まで案内してくれた。","example_reading":"みちにまよっていたら、しんせつにえきまであんないしてくれた。","example_meaning":"Khi tôi lạc đường, người ấy tử tế dẫn tôi tới tận ga.","examples":[{"example":"道に迷っていたら、親切に駅まで案内してくれた。","example_reading":"みちにまよっていたら、しんせつにえきまであんないしてくれた。","example_meaning":"Khi tôi lạc đường, người ấy tử tế dẫn tôi tới tận ga."},{"example":"店員は商品の使い方を親切に教えてくれた。","example_reading":"てんいんはしょうひんのつかいかたをしんせつにおしえてくれた。","example_meaning":"Nhân viên đã tận tình hướng dẫn cách dùng sản phẩm."}],"level":"a1"},
{"word":"新たに","reading":"あらたに","meaning":"một cách mới, làm thêm lần nữa","hanviet":"tân","antonym":"従来どおり（じゅうらいどおり）: như cũ","antonym_hanviet":"tòng lai","note":"Dạng に. Hay đi với 始める, 作る, 加わる. Dùng nhiều trong văn viết và thông báo.","example":"来月から新たに三人の社員が加わります。","example_reading":"らいげつからあらたにさんにんのしゃいんがくわわります。","example_meaning":"Từ tháng sau sẽ có thêm ba nhân viên mới gia nhập.","examples":[{"example":"来月から新たに三人の社員が加わります。","example_reading":"らいげつからあらたにさんにんのしゃいんがくわわります。","example_meaning":"Từ tháng sau sẽ có thêm ba nhân viên mới gia nhập."},{"example":"市は駅前に新たに図書館を建てる計画だ。","example_reading":"しはえきまえにあらたにとしょかんをたてるけいかくだ。","example_meaning":"Thành phố có kế hoạch xây mới một thư viện trước ga."}],"level":"a1"},
{"word":"安全に","reading":"あんぜんに","meaning":"một cách an toàn","hanviet":"an toàn","antonym":"危険に（きけんに）: nguy hiểm","antonym_hanviet":"nguy hiểm","note":"Dạng に. Hay đi với 運転する, 使う, 避難する, 届ける.","example":"子どもたちが安全に遊べる公園を作りたい。","example_reading":"こどもたちがあんぜんにあそべるこうえんをつくりたい。","example_meaning":"Tôi muốn làm một công viên mà trẻ em có thể chơi an toàn.","examples":[{"example":"子どもたちが安全に遊べる公園を作りたい。","example_reading":"こどもたちがあんぜんにあそべるこうえんをつくりたい。","example_meaning":"Tôi muốn làm một công viên mà trẻ em có thể chơi an toàn."},{"example":"雨の日は特に安全に運転するよう心がけている。","example_reading":"あめのひはとくにあんぜんにうんてんするようこころがけている。","example_meaning":"Những ngày mưa tôi đặc biệt chú ý lái xe an toàn."}],"level":"a1"},
{"word":"気楽に","reading":"きらくに","meaning":"thong thả, nhẹ nhàng, không lo nghĩ","hanviet":"khí lạc","antonym":"深刻に（しんこくに）: nặng nề, nghiêm trọng / 必死に（ひっしに）: hết sức","antonym_hanviet":"thâm khắc / tất tử","note":"Dạng に. Hay đi với 考える, 構える, 過ごす. Hay dùng khuyên người khác bớt căng thẳng.","example":"失敗してもいいから、気楽に挑戦してみよう。","example_reading":"しっぱいしてもいいから、きらくにちょうせんしてみよう。","example_meaning":"Thất bại cũng được, cứ thử sức một cách nhẹ nhàng đi.","examples":[{"example":"失敗してもいいから、気楽に挑戦してみよう。","example_reading":"しっぱいしてもいいから、きらくにちょうせんしてみよう。","example_meaning":"Thất bại cũng được, cứ thử sức một cách nhẹ nhàng đi."},{"example":"試験のことは忘れて、今日は気楽に過ごそう。","example_reading":"しけんのことはわすれて、きょうはきらくにすごそう。","example_meaning":"Quên chuyện thi đi, hôm nay cứ thong thả thôi."}],"level":"a1"},
{"word":"懸命に","reading":"けんめいに","meaning":"hết sức, nỗ lực","hanviet":"huyền mệnh","antonym":"適当に（てきとうに）: qua loa","antonym_hanviet":"thích đương","note":"Dạng に. Hay đi với 努力する, 働く, 探す. Gần 一生懸命に nhưng trang trọng hơn.","example":"救助隊は懸命に生存者を探した。","example_reading":"きゅうじょたいはけんめいにせいぞんしゃをさがした。","example_meaning":"Đội cứu hộ hết sức tìm kiếm người sống sót.","examples":[{"example":"救助隊は懸命に生存者を探した。","example_reading":"きゅうじょたいはけんめいにせいぞんしゃをさがした。","example_meaning":"Đội cứu hộ hết sức tìm kiếm người sống sót."},{"example":"彼女は懸命に働いて、家族を支えた。","example_reading":"かのじょはけんめいにはたらいて、かぞくをささえた。","example_meaning":"Cô ấy làm việc hết mình để nuôi gia đình."}],"level":"a1"},
{"word":"偶然に","reading":"ぐうぜんに","meaning":"tình cờ, ngẫu nhiên","hanviet":"ngẫu nhiên","note":"Dạng に (hoặc dùng trơn: 偶然). Trái nghĩa: わざと, 故意に.","antonym":"必然的に（ひつぜんてきに）: tất yếu / わざと: cố ý / 故意に（こいに）: cố ý","antonym_hanviet":"tất nhiên đích /  / cố ý","example":"駅で偶然、昔の友達に会いました。","example_reading":"えきでぐうぜん、むかしのともだちにあいました。","example_meaning":"Tôi tình cờ gặp bạn cũ ở nhà ga.","examples":[{"example":"駅で偶然、昔の友達に会いました。","example_reading":"えきでぐうぜん、むかしのともだちにあいました。","example_meaning":"Tôi tình cờ gặp bạn cũ ở nhà ga."},{"example":"試験に出た問題は、偶然にも昨日勉強したところだった。","example_reading":"しけんにでたもんだいは、ぐうぜんにもきのうべんきょうしたところだった。","example_meaning":"Đề thi ra đúng phần tôi vừa học hôm qua, thật tình cờ."}],"level":"a1"},
{"word":"確実に","reading":"かくじつに","meaning":"chắc chắn, một cách chắc chắn","hanviet":"xác thực","antonym":"不確実に（ふかくじつに）: không chắc chắn","antonym_hanviet":"bất xác thực","note":"Dạng に. Hay đi với できる, 増える, 届く.","example":"この方法なら、確実に合格できます。","example_reading":"このほうほうなら、かくじつにごうかくできます。","example_meaning":"Nếu dùng cách này thì chắc chắn đậu.","examples":[{"example":"この方法なら、確実に合格できます。","example_reading":"このほうほうなら、かくじつにごうかくできます。","example_meaning":"Nếu dùng cách này thì chắc chắn đậu."},{"example":"荷物は明日の午前中に確実に届きます。","example_reading":"にもつはあしたのごぜんちゅうにかくじつにとどきます。","example_meaning":"Hành lý chắc chắn sẽ đến vào sáng mai."}],"level":"a1"},
{"word":"着実に","reading":"ちゃくじつに","meaning":"vững chắc, chắc chắn từng bước","hanviet":"trước thực","antonym":"場当たり的に（ばあたりてきに）: tùy cơ ứng biến","antonym_hanviet":"trường đương đích","note":"Dạng に. Tiến lên đều đặn, không vội, không bỏ bước.","example":"売り上げは着実に伸びています。","example_reading":"うりあげはちゃくじつにのびています。","example_meaning":"Doanh thu đang tăng đều và vững chắc.","examples":[{"example":"売り上げは着実に伸びています。","example_reading":"うりあげはちゃくじつにのびています。","example_meaning":"Doanh thu đang tăng đều và vững chắc."},{"example":"彼は着実に実績を積み重ねてきた。","example_reading":"かれはちゃくじつにじっせきをつみかさねてきた。","example_meaning":"Anh ấy đã tích lũy thành tích một cách vững chắc."}],"level":"a1"},
{"word":"地道に","reading":"じみちに","meaning":"một cách bền bỉ, kiên trì","hanviet":"địa đạo","antonym":"派手に（はでに）: hào nhoáng","antonym_hanviet":"phái thủ","note":"Dạng に. Hay đi với 努力する, 続ける, 働く. Làm đều đặn, không phô trương.","example":"地道に努力を続ければ、必ず結果が出る。","example_reading":"じみちにどりょくをつづければ、かならずけっかがでる。","example_meaning":"Nếu kiên trì nỗ lực thì chắc chắn sẽ có kết quả.","examples":[{"example":"地道に努力を続ければ、必ず結果が出る。","example_reading":"じみちにどりょくをつづければ、かならずけっかがでる。","example_meaning":"Nếu kiên trì nỗ lực thì chắc chắn sẽ có kết quả."},{"example":"彼は地道に研究を重ねてきた。","example_reading":"かれはじみちにけんきゅうをかさねてきた。","example_meaning":"Anh ấy đã kiên trì nghiên cứu suốt nhiều năm."}],"level":"a1"},
{"word":"無理に","reading":"むりに","meaning":"cưỡng ép, cố gắng quá sức","hanviet":"vô lý","antonym":"自然に（しぜんに）: tự nhiên","antonym_hanviet":"tự nhiên","note":"Dạng に. Hay đi với 勧める, 笑う, 頑張る, ～なくてもいい. Ép làm điều khó hoặc không muốn.","example":"食べたくなければ、無理に食べなくてもいいですよ。","example_reading":"たべたくなければ、むりにたべなくてもいいですよ。","example_meaning":"Nếu không muốn ăn thì không cần cố ăn đâu.","examples":[{"example":"食べたくなければ、無理に食べなくてもいいですよ。","example_reading":"たべたくなければ、むりにたべなくてもいいですよ。","example_meaning":"Nếu không muốn ăn thì không cần cố ăn đâu."},{"example":"疲れているときに無理に仕事を続けると、体を壊す。","example_reading":"つかれているときにむりにしごとをつづけると、からだをこわす。","example_meaning":"Khi mệt mà cố làm tiếp thì sẽ hỏng cả người."}],"level":"a1"},
{"word":"無事に","reading":"ぶじに","meaning":"bình an, suôn sẻ, không xảy ra chuyện gì","hanviet":"vô sự","antonym":"不幸にも（ふこうにも）: không may","antonym_hanviet":"bất hạnh","note":"Dạng に. Hay đi với 着く, 届く, 終わる.","example":"荷物は無事に届きました。","example_reading":"にもつはぶじにとどきました。","example_meaning":"Hành lý đã đến nơi an toàn.","examples":[{"example":"荷物は無事に届きました。","example_reading":"にもつはぶじにとどきました。","example_meaning":"Hành lý đã đến nơi an toàn."},{"example":"無事に帰ってきて、本当によかった。","example_reading":"ぶじにかえってきて、ほんとうによかった。","example_meaning":"Bạn trở về bình an, thật tốt quá."}],"level":"a1"},
{"word":"別々に","reading":"べつべつに","meaning":"riêng rẽ, tách ra từng cái","hanviet":"biệt biệt","note":"Dạng に. Hay dùng khi thanh toán, gửi đồ, xử lý riêng từng phần.","antonym":"一斉に（いっせいに）: đồng loạt / 一緒に（いっしょに）: cùng nhau / 同時に（どうじに）: đồng thời","antonym_hanviet":"nhất tề / nhất tự / đồng thời","example":"会計は別々にお願いします。","example_reading":"かいけいはべつべつにおねがいします。","example_meaning":"Cho tôi tính tiền riêng từng người.","examples":[{"example":"会計は別々にお願いします。","example_reading":"かいけいはべつべつにおねがいします。","example_meaning":"Cho tôi tính tiền riêng từng người."},{"example":"二人は別々に会場へ向かった。","example_reading":"ふたりはべつべつにかいじょうへむかった。","example_meaning":"Hai người đi riêng đến hội trường."}],"level":"a1"},
{"word":"必死に","reading":"ひっしに","meaning":"hết sức, liều mạng, cuống cuồng","hanviet":"tất tử","antonym":"気楽に（きらくに）: thong thả","antonym_hanviet":"khí lạc","note":"Dạng に. Hay đi với 走る, 探す, 頑張る, 抵抗する. Mạnh hơn 懸命に, có sắc thái bị dồn vào đường cùng.","example":"電車に間に合うように、必死に走った。","example_reading":"でんしゃにまにあうように、ひっしにはしった。","example_meaning":"Tôi chạy hết sức để kịp chuyến tàu.","examples":[{"example":"電車に間に合うように、必死に走った。","example_reading":"でんしゃにまにあうように、ひっしにはしった。","example_meaning":"Tôi chạy hết sức để kịp chuyến tàu."},{"example":"子どもは泣きながら必死に母親を探していた。","example_reading":"こどもはなきながらひっしにははおやをさがしていた。","example_meaning":"Đứa bé vừa khóc vừa cuống cuồng tìm mẹ."}],"level":"a1"},
{"word":"手軽に","reading":"てがるに","meaning":"một cách đơn giản, dễ dàng","hanviet":"thủ khinh","antonym":"本格的に（ほんかくてきに）: bài bản, nghiêm túc","antonym_hanviet":"bản cách đích","note":"Dạng に. Hay đi với 楽しむ, 作る, 買える. Không tốn công sức hay tiền bạc.","example":"このアプリで手軽に英語が勉強できる。","example_reading":"このアプリでてがるにえいごがべんきょうできる。","example_meaning":"Với ứng dụng này có thể học tiếng Anh dễ dàng.","examples":[{"example":"このアプリで手軽に英語が勉強できる。","example_reading":"このアプリでてがるにえいごがべんきょうできる。","example_meaning":"Với ứng dụng này có thể học tiếng Anh dễ dàng."},{"example":"手軽に作れる朝ご飯を紹介します。","example_reading":"てがるにつくれるあさごはんをしょうかいします。","example_meaning":"Tôi xin giới thiệu bữa sáng làm đơn giản."}],"level":"a1"},
{"word":"派手に","reading":"はでに","meaning":"một cách sặc sỡ, rầm rộ","hanviet":"phái thủ","antonym":"地味に（じみに）: giản dị, kín đáo","antonym_hanviet":"địa vị","note":"Dạng に. Hay đi với 飾る, 祝う, 転ぶ, 遊ぶ. Trái nghĩa: 地味に.","example":"クリスマスには、家を派手に飾り付けた。","example_reading":"クリスマスには、いえをはでにかざりつけた。","example_meaning":"Dịp Giáng sinh, chúng tôi trang trí nhà thật rực rỡ.","examples":[{"example":"クリスマスには、家を派手に飾り付けた。","example_reading":"クリスマスには、いえをはでにかざりつけた。","example_meaning":"Dịp Giáng sinh, chúng tôi trang trí nhà thật rực rỡ."},{"example":"彼は自転車で派手に転んで、膝を擦りむいた。","example_reading":"かれはじてんしゃではでにころんで、ひざをすりむいた。","example_meaning":"Anh ấy ngã xe đạp một cú đau điếng, trầy cả đầu gối."}],"level":"a1"},
{"word":"一気に","reading":"いっきに","meaning":"một mạch, một hơi, dồn một lần","hanviet":"nhất khí","antonym":"少しずつ（すこしずつ）: từng chút một / じわじわ: từ từ nhưng chắc chắn / 段階的に（だんかいてきに）: từng giai đoạn","antonym_hanviet":"thiểu /  / đoạn giai đích","note":"Dạng に. Làm hoặc xảy ra liền một lần, không ngắt quãng.","example":"疲れが一気に出てきました。","example_reading":"つかれがいっきにでてきました。","example_meaning":"Mệt mỏi ập đến cùng một lúc.","examples":[{"example":"疲れが一気に出てきました。","example_reading":"つかれがいっきにでてきました。","example_meaning":"Mệt mỏi ập đến cùng một lúc."},{"example":"暑くなって、一気にビールの売れ行きが伸びた。","example_reading":"あつくなって、いっきにビールのうれゆきがのびた。","example_meaning":"Trời nóng lên nên lượng bia bán ra tăng vọt một lèo."}],"level":"a1"},
{"word":"具体的に","reading":"ぐたいてきに","meaning":"một cách cụ thể","hanviet":"cụ thể đích","antonym":"抽象的に（ちゅうしょうてきに）: trừu tượng","antonym_hanviet":"trừu tượng đích","note":"Dạng に. Hay đi với 説明する, 示す, 話す. Trái nghĩa: 抽象的に.","example":"問題点を具体的に説明してください。","example_reading":"もんだいてんをぐたいてきにせつめいしてください。","example_meaning":"Xin hãy giải thích cụ thể các điểm vấn đề.","examples":[{"example":"問題点を具体的に説明してください。","example_reading":"もんだいてんをぐたいてきにせつめいしてください。","example_meaning":"Xin hãy giải thích cụ thể các điểm vấn đề."},{"example":"来年の目標を具体的に決めておくといい。","example_reading":"らいねんのもくひょうをぐたいてきにきめておくといい。","example_meaning":"Nên định sẵn mục tiêu năm sau một cách cụ thể."}],"level":"a1"},
{"word":"続々と","reading":"ぞくぞくと","meaning":"lần lượt, dồn dập, liên tiếp không dứt","hanviet":"tục tục","antonym":"散発的に（さんぱつてきに）: lẻ tẻ","antonym_hanviet":"tán phát đích","note":"Dạng と. Người hoặc vật xuất hiện nối tiếp nhau, hay đi với 現れる, 集まる, 登場する.","example":"新しい店が続々と開店しています。","example_reading":"あたらしいみせがぞくぞくとかいてんしています。","example_meaning":"Các cửa hàng mới liên tục mở ra.","examples":[{"example":"新しい店が続々と開店しています。","example_reading":"あたらしいみせがぞくぞくとかいてんしています。","example_meaning":"Các cửa hàng mới liên tục mở ra."},{"example":"会場には、続々とお客さんが集まってきた。","example_reading":"かいじょうには、ぞくぞくとおきゃくさんがあつまってきた。","example_meaning":"Khách lần lượt đổ về hội trường."}],"level":"a1"},
{"word":"次々に","reading":"つぎつぎに","meaning":"lần lượt hết cái này đến cái khác","hanviet":"thứ thứ","antonym":"散発的に（さんぱつてきに）: lẻ tẻ","antonym_hanviet":"tán phát đích","note":"Dạng に (cũng nói 次々と). Nhấn mạnh việc nối tiếp nhau theo thứ tự.","example":"問題が次々に起こって、困っています。","example_reading":"もんだいがつぎつぎにおこって、こまっています。","example_meaning":"Vấn đề cứ lần lượt xảy ra, tôi rất rối.","examples":[{"example":"問題が次々に起こって、困っています。","example_reading":"もんだいがつぎつぎにおこって、こまっています。","example_meaning":"Vấn đề cứ lần lượt xảy ra, tôi rất rối."},{"example":"次々に新しい商品が発売されている。","example_reading":"つぎつぎにあたらしいしょうひんがはつばいされている。","example_meaning":"Sản phẩm mới liên tiếp được tung ra thị trường."}],"level":"a1"},
{"word":"熱心に","reading":"ねっしんに","meaning":"một cách nhiệt tình, hăng say","hanviet":"nhiệt tâm","antonym":"いい加減に（いいかげんに）: qua loa","antonym_hanviet":"gia giảm","note":"Dạng に. Hay đi với 勉強する, 働く, 聞く, 勧める.","example":"彼は毎晩、熱心に日本語を勉強している。","example_reading":"かれはまいばん、ねっしんににほんごをべんきょうしている。","example_meaning":"Anh ấy tối nào cũng hăng say học tiếng Nhật.","examples":[{"example":"彼は毎晩、熱心に日本語を勉強している。","example_reading":"かれはまいばん、ねっしんににほんごをべんきょうしている。","example_meaning":"Anh ấy tối nào cũng hăng say học tiếng Nhật."},{"example":"店員が熱心に新しい商品を勧めてきた。","example_reading":"てんいんがねっしんにあたらしいしょうひんをすすめてきた。","example_meaning":"Nhân viên nhiệt tình giới thiệu sản phẩm mới."}],"level":"a1"},
{"word":"悠々と","reading":"ゆうゆうと","meaning":"ung dung, thong dong, thoải mái","hanviet":"du du","antonym":"慌てて（あわてて）: hoảng hốt, vội vàng","antonym_hanviet":"hoảng","note":"Dạng と. Thái độ thong thả, dư dả, không vội.","example":"彼は悠々と泳いでゴールした。","example_reading":"かれはゆうゆうとおよいでゴールした。","example_meaning":"Anh ấy bơi ung dung về đích.","examples":[{"example":"彼は悠々と泳いでゴールした。","example_reading":"かれはゆうゆうとおよいでゴールした。","example_meaning":"Anh ấy bơi ung dung về đích."},{"example":"老人は悠々と散歩を楽しんでいた。","example_reading":"ろうじんはゆうゆうとさんぽをたのしんでいた。","example_meaning":"Ông cụ thong thả tận hưởng cuộc dạo bước."}],"level":"a1"},
{"word":"密かに","reading":"ひそかに","meaning":"lén lút, âm thầm (không để ai biết)","hanviet":"mật","note":"Dạng に. Viết bằng kanji 密か, hay dùng khi giữ kín ý định hoặc cảm xúc.","antonym":"公然と（こうぜんと）: công khai","antonym_hanviet":"công nhiên","example":"彼女は密かに留学の準備を進めていた。","example_reading":"かのじょはひそかにりゅうがくのじゅんびをすすめていた。","example_meaning":"Cô ấy âm thầm chuẩn bị đi du học.","examples":[{"example":"彼女は密かに留学の準備を進めていた。","example_reading":"かのじょはひそかにりゅうがくのじゅんびをすすめていた。","example_meaning":"Cô ấy âm thầm chuẩn bị đi du học."},{"example":"私は密かに彼のことが好きだった。","example_reading":"わたしはひそかにかれのことがすきだった。","example_meaning":"Tôi đã thầm thích anh ấy."}],"level":"a1"},
{"word":"明らかに","reading":"あきらかに","meaning":"rõ ràng, hiển nhiên","hanviet":"minh","antonym":"曖昧に（あいまいに）: mơ hồ","antonym_hanviet":"ái muội","note":"Dạng に. Dùng khi sự thật quá rõ, hay đi với 違う, 間違い.","example":"この答えは明らかに間違っています。","example_reading":"このこたえはあきらかにまちがっています。","example_meaning":"Đáp án này rõ ràng là sai.","examples":[{"example":"この答えは明らかに間違っています。","example_reading":"このこたえはあきらかにまちがっています。","example_meaning":"Đáp án này rõ ràng là sai."},{"example":"彼の態度は明らかに怒っているようだった。","example_reading":"かれのたいどはあきらかにおこっているようだった。","example_meaning":"Thái độ của anh ấy rõ ràng là đang giận."}],"level":"a1"},
{"word":"地味に","reading":"じみに","meaning":"một cách giản dị, kín đáo, âm thầm","hanviet":"địa vị","antonym":"派手に（はでに）: sặc sỡ, rầm rộ / 鮮やかに（あざやかに）: rực rỡ","antonym_hanviet":"phái thủ / tiên","note":"Dạng に. Hay đi với 暮らす, 続ける, 努力する. Không phô trương.","example":"彼女は地味に暮らしているが、実はとても裕福だ。","example_reading":"かのじょはじみにくらしているが、じつはとてもゆうふくだ。","example_meaning":"Cô ấy sống giản dị nhưng thật ra rất giàu có.","examples":[{"example":"彼女は地味に暮らしているが、実はとても裕福だ。","example_reading":"かのじょはじみにくらしているが、じつはとてもゆうふくだ。","example_meaning":"Cô ấy sống giản dị nhưng thật ra rất giàu có."},{"example":"地味に続けてきた努力が、ようやく実を結んだ。","example_reading":"じみにつづけてきたどりょくが、ようやくみをむすんだ。","example_meaning":"Nỗ lực âm thầm bao lâu nay cuối cùng đã đơm hoa kết trái."}],"level":"a1"},
{"word":"誠実に","reading":"せいじつに","meaning":"một cách thành thật, chân thành","hanviet":"thành thực","antonym":"不誠実に（ふせいじつに）: không thành thật","antonym_hanviet":"bất thành thực","note":"Dạng に. Hay đi với 対応する, 答える, 取り組む, 生きる.","example":"お客様のご意見には、誠実に対応いたします。","example_reading":"おきゃくさまのごいけんには、せいじつにたいおういたします。","example_meaning":"Chúng tôi sẽ đáp lại chân thành mọi ý kiến của quý khách.","examples":[{"example":"お客様のご意見には、誠実に対応いたします。","example_reading":"おきゃくさまのごいけんには、せいじつにたいおういたします。","example_meaning":"Chúng tôi sẽ đáp lại chân thành mọi ý kiến của quý khách."},{"example":"彼は何事にも誠実に取り組む人だ。","example_reading":"かれはなにごとにもせいじつにとりくむひとだ。","example_meaning":"Anh ấy là người làm việc gì cũng chân thành, nghiêm túc."}],"level":"a1"},
{"word":"順調に","reading":"じゅんちょうに","meaning":"một cách thuận lợi, suôn sẻ","hanviet":"thuận điệu","antonym":"不調に（ふちょうに）: không suôn sẻ","antonym_hanviet":"bất điều","note":"Dạng に. Hay đi với 進む, 回復する, 育つ, 伸びる.","example":"工事は順調に進んでいて、予定通りに終わりそうだ。","example_reading":"こうじはじゅんちょうにすすんでいて、よていどおりにおわりそうだ。","example_meaning":"Công trình đang tiến triển suôn sẻ, có vẻ sẽ xong đúng kế hoạch.","examples":[{"example":"工事は順調に進んでいて、予定通りに終わりそうだ。","example_reading":"こうじはじゅんちょうにすすんでいて、よていどおりにおわりそうだ。","example_meaning":"Công trình đang tiến triển suôn sẻ, có vẻ sẽ xong đúng kế hoạch."},{"example":"手術のあと、父は順調に回復している。","example_reading":"しゅじゅつのあと、ちちはじゅんちょうにかいふくしている。","example_meaning":"Sau phẫu thuật, bố tôi đang hồi phục tốt."}],"level":"a1"},
{"word":"微かに","reading":"かすかに","meaning":"mờ nhạt, thoang thoảng, yếu ớt","hanviet":"vi","antonym":"はっきり: rõ ràng","note":"Dạng に. Hay đi với 聞こえる, 見える, 匂う, 震える.","example":"遠くから微かに音楽が聞こえてきた。","example_reading":"とおくからかすかにおんがくがきこえてきた。","example_meaning":"Từ xa vọng lại tiếng nhạc thoang thoảng.","examples":[{"example":"遠くから微かに音楽が聞こえてきた。","example_reading":"とおくからかすかにおんがくがきこえてきた。","example_meaning":"Từ xa vọng lại tiếng nhạc thoang thoảng."},{"example":"部屋に微かにコーヒーの香りが残っていた。","example_reading":"へやにかすかにコーヒーのかおりがのこっていた。","example_meaning":"Trong phòng còn vương mùi cà phê thoang thoảng."}],"level":"a1"},
{"word":"呆然と","reading":"ぼうぜんと","meaning":"ngây người, thẫn thờ (vì quá sốc)","hanviet":"ngai nhiên","note":"Dạng と. Hay đi với 立ち尽くす, 見つめる. Trạng thái đứng hình khi bất ngờ.","example":"突然の知らせに、彼は呆然と立ち尽くした。","example_reading":"とつぜんのしらせに、かれはぼうぜんとたちつくした。","example_meaning":"Nghe tin đột ngột, anh ấy đứng sững ngây người.","examples":[{"example":"突然の知らせに、彼は呆然と立ち尽くした。","example_reading":"とつぜんのしらせに、かれはぼうぜんとたちつくした。","example_meaning":"Nghe tin đột ngột, anh ấy đứng sững ngây người."},{"example":"彼女は燃える家を呆然と見つめていた。","example_reading":"かのじょはもえるいえをぼうぜんとみつめていた。","example_meaning":"Cô ấy ngẩn người nhìn ngôi nhà đang cháy."}],"level":"a1"},
{"word":"一般的に","reading":"いっぱんてきに","meaning":"nói chung, một cách phổ biến","hanviet":"nhất ban đích","antonym":"個人的に（こじんてきに）: về mặt cá nhân / 特別に（とくべつに）: đặc biệt","antonym_hanviet":"cá nhân đích / đặc biệt","note":"Dạng に. Hay đứng đầu câu: 一般的に言って～. Gần 一般に nhưng khẩu ngữ hơn.","example":"一般的に、日本人は時間に正確だと言われている。","example_reading":"いっぱんてきに、にほんじんはじかんにせいかくだといわれている。","example_meaning":"Nhìn chung, người Nhật được cho là rất đúng giờ.","examples":[{"example":"一般的に、日本人は時間に正確だと言われている。","example_reading":"いっぱんてきに、にほんじんはじかんにせいかくだといわれている。","example_meaning":"Nhìn chung, người Nhật được cho là rất đúng giờ."},{"example":"この方法は一般的に広く使われている。","example_reading":"このほうほうはいっぱんてきにひろくつかわれている。","example_meaning":"Phương pháp này được dùng rộng rãi một cách phổ biến."}],"level":"a1"},
{"word":"愕然と","reading":"がくぜんと","meaning":"sững sờ, kinh hoàng","hanviet":"ngạc nhiên","note":"Dạng と. Thường đi với する (愕然とする). Sốc mạnh hơn 呆然と.","example":"結果を見て、愕然としました。","example_reading":"けっかをみて、がくぜんとしました。","example_meaning":"Nhìn kết quả tôi sững sờ.","examples":[{"example":"結果を見て、愕然としました。","example_reading":"けっかをみて、がくぜんとしました。","example_meaning":"Nhìn kết quả tôi sững sờ."},{"example":"彼は変わり果てた故郷の姿に愕然とした。","example_reading":"かれはかわりはてたこきょうのすがたにがくぜんとした。","example_meaning":"Anh ấy sững sờ trước diện mạo đổi khác của quê hương."}],"level":"a1"},
{"word":"手短に","reading":"てみじかに","meaning":"ngắn gọn, tóm tắt","hanviet":"thủ đoản","antonym":"詳しく（くわしく）: chi tiết / 長々と（ながながと）: dài dòng","antonym_hanviet":"tường / trưởng trưởng","note":"Dạng に. Hay đi với 話す, 説明する, 済ませる. Nói gọn vì ít thời gian.","example":"時間がないので、手短に説明します。","example_reading":"じかんがないので、てみじかにせつめいします。","example_meaning":"Vì không có thời gian nên tôi sẽ giải thích ngắn gọn.","examples":[{"example":"時間がないので、手短に説明します。","example_reading":"じかんがないので、てみじかにせつめいします。","example_meaning":"Vì không có thời gian nên tôi sẽ giải thích ngắn gọn."},{"example":"要点だけ手短に教えてもらえますか。","example_reading":"ようてんだけてみじかにおしえてもらえますか。","example_meaning":"Bạn có thể cho tôi biết ngắn gọn chỉ những điểm chính không?"}],"level":"a1"},
{"word":"個人的に","reading":"こじんてきに","meaning":"về mặt cá nhân, riêng tôi","hanviet":"cá nhân đích","antonym":"一般的に（いっぱんてきに）: nói chung / 組織的に（そしきてきに）: có tổ chức","antonym_hanviet":"nhất ban đích / tổ chức đích","note":"Dạng に. Hay đi với 思う, 好き, 連絡する. Nói ý riêng, không đại diện cho ai.","example":"個人的には、この案のほうがいいと思う。","example_reading":"こじんてきには、このあんのほうがいいとおもう。","example_meaning":"Riêng tôi thì thấy phương án này tốt hơn.","examples":[{"example":"個人的には、この案のほうがいいと思う。","example_reading":"こじんてきには、このあんのほうがいいとおもう。","example_meaning":"Riêng tôi thì thấy phương án này tốt hơn."},{"example":"彼とは個人的に連絡を取り合っている。","example_reading":"かれとはこじんてきにれんらくをとりあっている。","example_meaning":"Tôi liên lạc riêng với anh ấy."}],"level":"a1"},
{"word":"正式に","reading":"せいしきに","meaning":"một cách chính thức","hanviet":"chính thức","antonym":"非公式に（ひこうしきに）: không chính thức / 仮に（かりに）: tạm thời","antonym_hanviet":"phi công thức / giả","note":"Dạng に. Hay đi với 発表する, 決まる, 認める. Trái nghĩa: 非公式に.","example":"来月から、正式に新しい制度が始まる。","example_reading":"らいげつから、せいしきにあたらしいせいどがはじまる。","example_meaning":"Từ tháng sau, chế độ mới sẽ chính thức bắt đầu.","examples":[{"example":"来月から、正式に新しい制度が始まる。","example_reading":"らいげつから、せいしきにあたらしいせいどがはじまる。","example_meaning":"Từ tháng sau, chế độ mới sẽ chính thức bắt đầu."},{"example":"二人は正式に婚約を発表した。","example_reading":"ふたりはせいしきにこんやくをはっぴょうした。","example_meaning":"Hai người đã chính thức công bố đính hôn."}],"level":"a1"},
{"word":"軽快に","reading":"けいかいに","meaning":"một cách nhẹ nhàng, nhịp nhàng","hanviet":"khinh khoái","antonym":"ぎこちなく: gượng gạo, vụng về","note":"Dạng に. Hay đi với 走る, 弾む, 動く, 響く.","example":"彼は軽快に階段を駆け上がっていった。","example_reading":"かれはけいかいにかいだんをかけあがっていった。","example_meaning":"Anh ấy nhẹ nhàng chạy lên cầu thang.","examples":[{"example":"彼は軽快に階段を駆け上がっていった。","example_reading":"かれはけいかいにかいだんをかけあがっていった。","example_meaning":"Anh ấy nhẹ nhàng chạy lên cầu thang."},{"example":"軽快に響くリズムに合わせて、みんなが踊り出した。","example_reading":"けいかいにひびくリズムにあわせて、みんながおどりだした。","example_meaning":"Theo nhịp điệu vang lên sảng khoái, mọi người bắt đầu nhảy."}],"level":"a1"},
{"word":"健全に","reading":"けんぜんに","meaning":"một cách lành mạnh","hanviet":"kiện toàn","antonym":"不健全に（ふけんぜんに）: không lành mạnh","antonym_hanviet":"bất kiện toàn","note":"Dạng に. Hay đi với 育つ, 保つ, 運営する.","example":"子どもたちが健全に育つ環境を整えたい。","example_reading":"こどもたちがけんぜんにそだつかんきょうをととのえたい。","example_meaning":"Tôi muốn tạo môi trường để trẻ em lớn lên lành mạnh.","examples":[{"example":"子どもたちが健全に育つ環境を整えたい。","example_reading":"こどもたちがけんぜんにそだつかんきょうをととのえたい。","example_meaning":"Tôi muốn tạo môi trường để trẻ em lớn lên lành mạnh."},{"example":"会社の経営を健全に保つには、無駄な支出を減らすことが大切だ。","example_reading":"かいしゃのけいえいをけんぜんにたもつには、むだなししゅつをへらすことがたいせつだ。","example_meaning":"Để giữ cho việc điều hành công ty lành mạnh, điều quan trọng là cắt giảm chi tiêu lãng phí."}],"level":"a1"},
{"word":"冷静に","reading":"れいせいに","meaning":"một cách bình tĩnh, điềm tĩnh","hanviet":"lãnh tĩnh","antonym":"感情的に（かんじょうてきに）: theo cảm xúc / 取り乱して（とりみだして）: hoảng loạn / かっと: nóng bừng","antonym_hanviet":"cảm tình đích / thủ loạn / ","note":"Dạng に. Hay đi với 考える, 判断する, 対応する, 見る.","example":"事故が起きても、冷静に行動することが大切だ。","example_reading":"じこがおきても、れいせいにこうどうすることがたいせつだ。","example_meaning":"Dù xảy ra tai nạn, điều quan trọng là hành động bình tĩnh.","examples":[{"example":"事故が起きても、冷静に行動することが大切だ。","example_reading":"じこがおきても、れいせいにこうどうすることがたいせつだ。","example_meaning":"Dù xảy ra tai nạn, điều quan trọng là hành động bình tĩnh."},{"example":"感情的にならず、冷静に話し合いましょう。","example_reading":"かんじょうてきにならず、れいせいにはなしあいましょう。","example_meaning":"Đừng kích động, hãy bình tĩnh bàn bạc."}],"level":"a1"},
{"word":"毅然と","reading":"きぜんと","meaning":"kiên quyết, cương nghị, không nao núng","hanviet":"nghị nhiên","antonym":"優柔不断に（ゆうじゅうふだんに）: do dự","antonym_hanviet":"ưu nhu bất đoạn","note":"Dạng と. Hay đi với 断る, 対応する. Thái độ vững vàng trước áp lực.","example":"彼女は不当な要求を毅然と断った。","example_reading":"かのじょはふとうなようきゅうをきぜんとことわった。","example_meaning":"Cô ấy kiên quyết từ chối yêu cầu vô lý.","examples":[{"example":"彼女は不当な要求を毅然と断った。","example_reading":"かのじょはふとうなようきゅうをきぜんとことわった。","example_meaning":"Cô ấy kiên quyết từ chối yêu cầu vô lý."},{"example":"彼は毅然とした態度で、不正を告発した。","example_reading":"かれはきぜんとしたたいどで、ふせいをこくはつした。","example_meaning":"Anh ấy kiên quyết tố cáo sự gian lận."}],"level":"a1"},
{"word":"歴然と","reading":"れきぜんと","meaning":"rõ rệt, hiển nhiên, không thể chối cãi","hanviet":"lịch nhiên","antonym":"漠然と（ばくぜんと）: mơ hồ","antonym_hanviet":"mạc nhiên","note":"Dạng と. Hay dùng với 差, 違い, 事実 (歴然とした差).","example":"二つのチームには歴然とした力の差がある。","example_reading":"ふたつのチームにはれきぜんとしたちからのさがある。","example_meaning":"Hai đội có khoảng cách sức mạnh rõ rệt.","examples":[{"example":"二つのチームには歴然とした力の差がある。","example_reading":"ふたつのチームにはれきぜんとしたちからのさがある。","example_meaning":"Hai đội có khoảng cách sức mạnh rõ rệt."},{"example":"努力した人としなかった人の差が、歴然と表れた。","example_reading":"どりょくしたひととしなかったひとのさが、れきぜんとあらわれた。","example_meaning":"Khoảng cách giữa người nỗ lực và người không nỗ lực đã lộ rõ."}],"level":"a1"},
{"word":"漫然と","reading":"まんぜんと","meaning":"lơ đãng, vô định, không có mục đích","hanviet":"mạn nhiên","antonym":"意識的に（いしきてきに）: có ý thức","antonym_hanviet":"ý thức đích","note":"Dạng と. Sắc thái hơi tiêu cực, làm gì đó mà không ý thức rõ.","example":"漫然と過ごさず、目標を持って勉強しよう。","example_reading":"まんぜんとすごさず、もくひょうをもってべんきょうしよう。","example_meaning":"Đừng sống lơ đãng, hãy học với mục tiêu.","examples":[{"example":"漫然と過ごさず、目標を持って勉強しよう。","example_reading":"まんぜんとすごさず、もくひょうをもってべんきょうしよう。","example_meaning":"Đừng sống lơ đãng, hãy học với mục tiêu."},{"example":"漫然とテレビを見て、一日が終わってしまった。","example_reading":"まんぜんとテレビをみて、いちにちがおわってしまった。","example_meaning":"Xem tivi vu vơ mà một ngày đã trôi qua."}],"level":"a1"},
{"word":"計画的に","reading":"けいかくてきに","meaning":"một cách có kế hoạch","hanviet":"kế hoạch đích","antonym":"無計画に（むけいかくに）: không có kế hoạch / ふらっと: tình cờ","antonym_hanviet":"vô kế họa / ","note":"Dạng に. Hay đi với 進める, 使う, 貯金する. Trái nghĩa: 無計画に.","example":"お金は計画的に使わないと、月末に困るよ。","example_reading":"おかねはけいかくてきにつかわないと、げつまつにこまるよ。","example_meaning":"Không dùng tiền có kế hoạch thì cuối tháng sẽ khổ đấy.","examples":[{"example":"お金は計画的に使わないと、月末に困るよ。","example_reading":"おかねはけいかくてきにつかわないと、げつまつにこまるよ。","example_meaning":"Không dùng tiền có kế hoạch thì cuối tháng sẽ khổ đấy."},{"example":"工事は計画的に進められている。","example_reading":"こうじはけいかくてきにすすめられている。","example_meaning":"Công trình đang được tiến hành theo kế hoạch."}],"level":"a1"},
{"word":"無意識に","reading":"むいしきに","meaning":"một cách vô thức, không hay biết","hanviet":"vô ý thức","antonym":"意識的に（いしきてきに）: có ý thức","antonym_hanviet":"ý thức đích","note":"Dạng に. Hay đi với ～してしまう, 動く. Làm mà không nhận ra. Trái nghĩa: 意識的に.","example":"緊張すると、無意識に髪を触ってしまう。","example_reading":"きんちょうすると、むいしきにかみをさわってしまう。","example_meaning":"Khi căng thẳng, tôi vô thức vuốt tóc.","examples":[{"example":"緊張すると、無意識に髪を触ってしまう。","example_reading":"きんちょうすると、むいしきにかみをさわってしまう。","example_meaning":"Khi căng thẳng, tôi vô thức vuốt tóc."},{"example":"気がつくと、無意識に彼女の名前を呼んでいた。","example_reading":"きがつくと、むいしきにかのじょのなまえをよんでいた。","example_meaning":"Chợt nhận ra, tôi đã vô thức gọi tên cô ấy."}],"level":"a1"},
{"word":"騒然と","reading":"そうぜんと","meaning":"nhốn nháo, ồn ào náo động","hanviet":"tao nhiên","antonym":"静かに（しずかに）: yên tĩnh / 粛々と（しゅくしゅくと）: trang nghiêm, lặng lẽ / 平穏に（へいおんに）: yên ổn","antonym_hanviet":"tĩnh / túc túc / bình ổn","note":"Dạng と. Hay đi với なる (騒然となる). Không khí xáo động vì sự cố.","example":"事故の知らせで、会場は騒然となった。","example_reading":"じこのしらせで、かいじょうはそうぜんとなった。","example_meaning":"Vì tin tai nạn, hội trường trở nên nhốn nháo.","examples":[{"example":"事故の知らせで、会場は騒然となった。","example_reading":"じこのしらせで、かいじょうはそうぜんとなった。","example_meaning":"Vì tin tai nạn, hội trường trở nên nhốn nháo."},{"example":"突然の停電で、店内は騒然とした。","example_reading":"とつぜんのていでんで、てんないはそうぜんとした。","example_meaning":"Do mất điện đột ngột, trong cửa hàng nhốn nháo cả lên."}],"level":"a1"},
{"word":"全体的に","reading":"ぜんたいてきに","meaning":"nhìn tổng thể, nói chung","hanviet":"toàn thể đích","antonym":"部分的に（ぶぶんてきに）: một phần","antonym_hanviet":"bộ phân đích","note":"Dạng に. Dùng khi đánh giá chung. Trái nghĩa: 部分的に.","example":"全体的に見ると、今年の売り上げは悪くない。","example_reading":"ぜんたいてきにみると、ことしのうりあげはわるくない。","example_meaning":"Nhìn tổng thể, doanh thu năm nay không tệ.","examples":[{"example":"全体的に見ると、今年の売り上げは悪くない。","example_reading":"ぜんたいてきにみると、ことしのうりあげはわるくない。","example_meaning":"Nhìn tổng thể, doanh thu năm nay không tệ."},{"example":"この映画は全体的にとても面白かった。","example_reading":"このえいがはぜんたいてきにとてもおもしろかった。","example_meaning":"Phim này nhìn chung rất hay."}],"level":"a1"},
{"word":"快適に","reading":"かいてきに","meaning":"một cách thoải mái, dễ chịu","hanviet":"khoái thích","antonym":"不快に（ふかいに）: khó chịu","antonym_hanviet":"bất khoái","note":"Dạng に. Hay đi với 過ごす, 使う, 暮らす.","example":"エアコンのおかげで、夏でも快適に過ごせる。","example_reading":"エアコンのおかげで、なつでもかいてきにすごせる。","example_meaning":"Nhờ có điều hòa, mùa hè cũng sống thoải mái.","examples":[{"example":"エアコンのおかげで、夏でも快適に過ごせる。","example_reading":"エアコンのおかげで、なつでもかいてきにすごせる。","example_meaning":"Nhờ có điều hòa, mùa hè cũng sống thoải mái."},{"example":"このソファは、長時間座っていても快適に使える。","example_reading":"このソファは、ちょうじかんすわっていてもかいてきにつかえる。","example_meaning":"Chiếc sofa này ngồi lâu vẫn dùng thoải mái."}],"level":"a1"},
{"word":"不当に","reading":"ふとうに","meaning":"một cách bất công, không chính đáng","hanviet":"bất đương","antonym":"正当に（せいとうに）: chính đáng / 公正に（こうせいに）: công bằng","antonym_hanviet":"chính đương / công chính","note":"Dạng に. Hay đi với 扱う, 解雇する, 高い, 安い.","example":"社員は、不当に給料を減らされたと訴えた。","example_reading":"しゃいんは、ふとうにきゅうりょうをへらされたとうったえた。","example_meaning":"Nhân viên kêu oan rằng lương bị cắt giảm bất công.","examples":[{"example":"社員は、不当に給料を減らされたと訴えた。","example_reading":"しゃいんは、ふとうにきゅうりょうをへらされたとうったえた。","example_meaning":"Nhân viên kêu oan rằng lương bị cắt giảm bất công."},{"example":"不当に高い値段で売るのは、法律違反だ。","example_reading":"ふとうにたかいねだんでうるのは、ほうりついはんだ。","example_meaning":"Bán với giá cao một cách bất chính là vi phạm pháp luật."}],"level":"a1"},
{"word":"鮮明に","reading":"せんめいに","meaning":"một cách rõ nét, sống động","hanviet":"tiên minh","antonym":"不鮮明に（ふせんめいに）: mờ nhạt / ぼんやり: mơ hồ","antonym_hanviet":"bất tiên minh / ","note":"Dạng に. Hay đi với 覚える, 写る, 思い出す.","example":"十年前の出来事を、今でも鮮明に覚えている。","example_reading":"じゅうねんまえのできごとを、いまでもせんめいにおぼえている。","example_meaning":"Tôi vẫn nhớ rõ nét chuyện mười năm trước.","examples":[{"example":"十年前の出来事を、今でも鮮明に覚えている。","example_reading":"じゅうねんまえのできごとを、いまでもせんめいにおぼえている。","example_meaning":"Tôi vẫn nhớ rõ nét chuyện mười năm trước."},{"example":"この写真は、夜景が鮮明に写っている。","example_reading":"このしゃしんは、やけいがせんめいにうつっている。","example_meaning":"Bức ảnh này chụp cảnh đêm rất rõ nét."}],"level":"a1"},
{"word":"無駄に","reading":"むだに","meaning":"một cách vô ích, lãng phí","hanviet":"vô đà","antonym":"有効に（ゆうこうに）: hiệu quả / 有意義に（ゆういぎに）: có ý nghĩa / 効率的に（こうりつてきに）: hiệu quả","antonym_hanviet":"hữu hiệu / hữu ý nghĩa / hiệu suất đích","note":"Dạng に. Hay đi với 使う, 過ごす, ～ならない. 無駄にならない = không uổng công.","example":"努力が無駄にならないように、最後まで続けよう。","example_reading":"どりょくがむだにならないように、さいごまでつづけよう。","example_meaning":"Hãy tiếp tục đến cùng để công sức không uổng phí.","examples":[{"example":"努力が無駄にならないように、最後まで続けよう。","example_reading":"どりょくがむだにならないように、さいごまでつづけよう。","example_meaning":"Hãy tiếp tục đến cùng để công sức không uổng phí."},{"example":"時間を無駄に使わないよう、予定を立てている。","example_reading":"じかんをむだにつかわないよう、よていをたてている。","example_meaning":"Tôi lập kế hoạch để không dùng phí thời gian."}],"level":"a1"},
{"word":"完璧に","reading":"かんぺきに","meaning":"một cách hoàn hảo, trọn vẹn","hanviet":"hoàn bích","antonym":"不完全に（ふかんぜんに）: không hoàn chỉnh / 中途半端に（ちゅうとはんぱに）: nửa vời","antonym_hanviet":"bất hoàn toàn / trung đồ bán đoan","note":"Dạng に. Hay đi với こなす, 覚える, 仕上げる.","example":"彼女は難しい曲を完璧に弾きこなした。","example_reading":"かのじょはむずかしいきょくをかんぺきにひきこなした。","example_meaning":"Cô ấy đã chơi hoàn hảo bản nhạc khó.","examples":[{"example":"彼女は難しい曲を完璧に弾きこなした。","example_reading":"かのじょはむずかしいきょくをかんぺきにひきこなした。","example_meaning":"Cô ấy đã chơi hoàn hảo bản nhạc khó."},{"example":"全ての単語を完璧に覚えるのは難しい。","example_reading":"すべてのたんごをかんぺきにおぼえるのはむずかしい。","example_meaning":"Nhớ hoàn hảo toàn bộ từ vựng là điều khó."}],"level":"a1"},
{"word":"猛然と","reading":"もうぜんと","meaning":"dữ dội, hùng hổ, mãnh liệt","hanviet":"mãnh nhiên","note":"Dạng と. Hay đi với 走る, 反論する, 襲いかかる.","example":"犬は猛然と走ってきた。","example_reading":"いぬはもうぜんとはしってきた。","example_meaning":"Con chó lao tới dữ dội.","examples":[{"example":"犬は猛然と走ってきた。","example_reading":"いぬはもうぜんとはしってきた。","example_meaning":"Con chó lao tới dữ dội."},{"example":"彼は猛然と反論を始めた。","example_reading":"かれはもうぜんとはんろんをはじめた。","example_meaning":"Anh ấy hùng hổ bắt đầu phản bác."}],"level":"a1"},
{"word":"延々と","reading":"えんえんと","meaning":"dài dằng dặc, kéo dài lê thê","hanviet":"diên diên","antonym":"手短に（てみじかに）: ngắn gọn","antonym_hanviet":"thủ đoản","note":"Dạng と. Chỉ việc kéo dài mãi, thường mang sắc thái chán ngán.","example":"会議は延々と続いた。","example_reading":"かいぎはえんえんとつづいた。","example_meaning":"Cuộc họp kéo dài lê thê.","examples":[{"example":"会議は延々と続いた。","example_reading":"かいぎはえんえんとつづいた。","example_meaning":"Cuộc họp kéo dài lê thê."},{"example":"校長先生の話は延々と続いた。","example_reading":"こうちょうせんせいのはなしはえんえんとつづいた。","example_meaning":"Bài nói của thầy hiệu trưởng kéo dài lê thê."}],"level":"a1"},
{"word":"脈々と","reading":"みゃくみゃくと","meaning":"liên tục, nối tiếp không đứt đoạn","hanviet":"mạch mạch","antonym":"断続的に（だんぞくてきに）: gián đoạn","antonym_hanviet":"đoạn tục đích","note":"Dạng と. Hay đi với 受け継ぐ, 続く (truyền thống, huyết thống).","example":"伝統は今も脈々と受け継がれている。","example_reading":"でんとうはいまもみゃくみゃくとうけつがれている。","example_meaning":"Truyền thống vẫn được kế thừa không ngừng.","examples":[{"example":"伝統は今も脈々と受け継がれている。","example_reading":"でんとうはいまもみゃくみゃくとうけつがれている。","example_meaning":"Truyền thống vẫn được kế thừa không ngừng."},{"example":"この地域では、古い祭りが脈々と守られてきた。","example_reading":"このちいきでは、ふるいまつりがみゃくみゃくとまもられてきた。","example_meaning":"Ở vùng này, lễ hội cổ vẫn được gìn giữ nối tiếp qua nhiều đời."}],"level":"a1"},
{"word":"効率的に","reading":"こうりつてきに","meaning":"một cách hiệu quả, năng suất","hanviet":"hiệu suất đích","antonym":"非効率的に（ひこうりつてきに）: kém hiệu quả / 無駄に（むだに）: vô ích","antonym_hanviet":"phi hiệu suất đích / vô đà","note":"Dạng に. Hay đi với 働く, 勉強する, 進める, 使う.","example":"時間を効率的に使うために、毎朝予定を整理している。","example_reading":"じかんをこうりつてきにつかうために、まいあさよていをせいりしている。","example_meaning":"Để dùng thời gian hiệu quả, sáng nào tôi cũng sắp xếp lịch trình.","examples":[{"example":"時間を効率的に使うために、毎朝予定を整理している。","example_reading":"じかんをこうりつてきにつかうために、まいあさよていをせいりしている。","example_meaning":"Để dùng thời gian hiệu quả, sáng nào tôi cũng sắp xếp lịch trình."},{"example":"新しいシステムのおかげで、仕事が効率的にできるようになった。","example_reading":"あたらしいシステムのおかげで、しごとがこうりつてきにできるようになった。","example_meaning":"Nhờ hệ thống mới, công việc đã làm được hiệu quả hơn."}],"level":"a1"},
{"word":"劇的に","reading":"げきてきに","meaning":"một cách kịch tính, đột biến","hanviet":"kịch đích","antonym":"緩やかに（ゆるやかに）: chậm rãi / 徐々に（じょじょに）: dần dần","antonym_hanviet":"hoãn / từ từ","note":"Dạng に. Hay đi với 変わる, 改善する, 増える.","example":"新しい薬のおかげで、症状が劇的に良くなった。","example_reading":"あたらしいくすりのおかげで、しょうじょうがげきてきによくなった。","example_meaning":"Nhờ thuốc mới, triệu chứng đã cải thiện rõ rệt.","examples":[{"example":"新しい薬のおかげで、症状が劇的に良くなった。","example_reading":"あたらしいくすりのおかげで、しょうじょうがげきてきによくなった。","example_meaning":"Nhờ thuốc mới, triệu chứng đã cải thiện rõ rệt."},{"example":"引っ越してから、彼の生活は劇的に変わった。","example_reading":"ひっこしてから、かれのせいかつはげきてきにかわった。","example_meaning":"Từ khi chuyển nhà, cuộc sống của anh ấy đã thay đổi đột biến."}],"level":"a1"},
{"word":"論理的に","reading":"ろんりてきに","meaning":"một cách logic, có lý lẽ","hanviet":"luận lý đích","antonym":"感情的に（かんじょうてきに）: theo cảm xúc / 直感的に（ちょっかんてきに）: theo trực giác","antonym_hanviet":"cảm tình đích / trực cảm đích","note":"Dạng に. Hay đi với 考える, 説明する, 話す. Trái nghĩa: 感情的に.","example":"自分の意見は、論理的に説明しなければ伝わらない。","example_reading":"じぶんのいけんは、ろんりてきにせつめいしなければつたわらない。","example_meaning":"Ý kiến của mình nếu không giải thích có logic thì không truyền đạt được.","examples":[{"example":"自分の意見は、論理的に説明しなければ伝わらない。","example_reading":"じぶんのいけんは、ろんりてきにせつめいしなければつたわらない。","example_meaning":"Ý kiến của mình nếu không giải thích có logic thì không truyền đạt được."},{"example":"彼女は何事も論理的に考える人だ。","example_reading":"かのじょはなにごともろんりてきにかんがえるひとだ。","example_meaning":"Cô ấy là người việc gì cũng suy nghĩ có logic."}],"level":"a1"},
{"word":"自主的に","reading":"じしゅてきに","meaning":"một cách tự giác, chủ động","hanviet":"tự chủ đích","antonym":"強制的に（きょうせいてきに）: cưỡng chế / 受動的に（じゅどうてきに）: thụ động","antonym_hanviet":"cường chế đích / thụ động đích","note":"Dạng に. Hay đi với 参加する, 勉強する, 行う. Không bị ai ép buộc.","example":"この活動には、生徒たちが自主的に参加している。","example_reading":"このかつどうには、せいとたちがじしゅてきにさんかしている。","example_meaning":"Học sinh tự giác tham gia hoạt động này.","examples":[{"example":"この活動には、生徒たちが自主的に参加している。","example_reading":"このかつどうには、せいとたちがじしゅてきにさんかしている。","example_meaning":"Học sinh tự giác tham gia hoạt động này."},{"example":"社員が自主的に勉強会を開くようになった。","example_reading":"しゃいんがじしゅてきにべんきょうかいをひらくようになった。","example_meaning":"Nhân viên đã chủ động mở các buổi học nhóm."}],"level":"a1"},
{"word":"無責任に","reading":"むせきにんに","meaning":"một cách vô trách nhiệm","hanviet":"vô trách nhiệm","antonym":"責任を持って（せきにんをもって）: có trách nhiệm","antonym_hanviet":"trách nhiệm trì","note":"Dạng に. Hay đi với 言う, 放り出す, 噂を広める.","example":"事実を確かめずに、無責任に噂を広めてはいけない。","example_reading":"じじつをたしかめずに、むせきにんにうわさをひろめてはいけない。","example_meaning":"Không được tung tin đồn vô trách nhiệm khi chưa xác thực sự việc.","examples":[{"example":"事実を確かめずに、無責任に噂を広めてはいけない。","example_reading":"じじつをたしかめずに、むせきにんにうわさをひろめてはいけない。","example_meaning":"Không được tung tin đồn vô trách nhiệm khi chưa xác thực sự việc."},{"example":"彼は仕事を無責任に放り出して、行方をくらました。","example_reading":"かれはしごとをむせきにんにほうりだして、ゆくえをくらました。","example_meaning":"Anh ta vô trách nhiệm bỏ dở công việc rồi biến mất."}],"level":"a1"},
{"word":"明快に","reading":"めいかいに","meaning":"một cách rõ ràng, mạch lạc","hanviet":"minh khoái","antonym":"不明瞭に（ふめいりょうに）: mơ hồ / 曖昧に（あいまいに）: mập mờ","antonym_hanviet":"bất minh liễu / ái muội","note":"Dạng に. Hay đi với 答える, 説明する, 整理する.","example":"彼の説明は、複雑な問題を明快に整理していた。","example_reading":"かれのせつめいは、ふくざつなもんだいをめいかいにせいりしていた。","example_meaning":"Lời giải thích của anh ấy sắp xếp mạch lạc vấn đề phức tạp.","examples":[{"example":"彼の説明は、複雑な問題を明快に整理していた。","example_reading":"かれのせつめいは、ふくざつなもんだいをめいかいにせいりしていた。","example_meaning":"Lời giải thích của anh ấy sắp xếp mạch lạc vấn đề phức tạp."},{"example":"質問に明快に答えてくれたので、よく理解できた。","example_reading":"しつもんにめいかいにこたえてくれたので、よくりかいできた。","example_meaning":"Vì anh ấy trả lời câu hỏi rõ ràng nên tôi hiểu rất rõ."}],"level":"a1"},
{"word":"機械的に","reading":"きかいてきに","meaning":"một cách máy móc","hanviet":"cơ giới đích","antonym":"人間的に（にんげんてきに）: giàu tính người / 創造的に（そうぞうてきに）: sáng tạo","antonym_hanviet":"nhân gian đích / sang tạo đích","note":"Dạng に. Hay đi với こなす, 読む, 処理する. Làm không suy nghĩ, không cảm xúc.","example":"毎日同じ作業を、機械的にこなしている。","example_reading":"まいにちおなじさぎょうを、きかいてきにこなしている。","example_meaning":"Mỗi ngày tôi làm cùng một công việc một cách máy móc.","examples":[{"example":"毎日同じ作業を、機械的にこなしている。","example_reading":"まいにちおなじさぎょうを、きかいてきにこなしている。","example_meaning":"Mỗi ngày tôi làm cùng một công việc một cách máy móc."},{"example":"マニュアルを機械的に読み上げるだけでは、客に気持ちが伝わらない。","example_reading":"マニュアルをきかいてきによみあげるだけでは、きゃくにきもちがつたわらない。","example_meaning":"Chỉ đọc sổ tay một cách máy móc thì không truyền được tấm lòng đến khách."}],"level":"a1"},
{"word":"活発に","reading":"かっぱつに","meaning":"một cách sôi nổi, năng động","hanviet":"hoạt bát","antonym":"不活発に（ふかっぱつに）: trì trệ / 消極的に（しょうきょくてきに）: tiêu cực","antonym_hanviet":"bất hoạt phát / tiêu cực đích","note":"Dạng に. Hay đi với 議論する, 動く, 活動する.","example":"会議では、活発に意見が交わされた。","example_reading":"かいぎでは、かっぱつにいけんがかわされた。","example_meaning":"Trong cuộc họp, các ý kiến được trao đổi sôi nổi.","examples":[{"example":"会議では、活発に意見が交わされた。","example_reading":"かいぎでは、かっぱつにいけんがかわされた。","example_meaning":"Trong cuộc họp, các ý kiến được trao đổi sôi nổi."},{"example":"子どもたちは、公園で活発に走り回っている。","example_reading":"こどもたちは、こうえんでかっぱつにはしりまわっている。","example_meaning":"Bọn trẻ chạy nhảy sôi nổi trong công viên."}],"level":"a1"},
{"word":"転々と","reading":"てんてんと","meaning":"chuyển từ nơi này sang nơi khác","hanviet":"chuyển chuyển","note":"Dạng と. Hay đi với 変える, 移る (nơi ở, công việc).","example":"彼は仕事を転々と変えてきた。","example_reading":"かれはしごとをてんてんとかえてきた。","example_meaning":"Anh ấy đã đổi việc liên tục.","examples":[{"example":"彼は仕事を転々と変えてきた。","example_reading":"かれはしごとをてんてんとかえてきた。","example_meaning":"Anh ấy đã đổi việc liên tục."},{"example":"子どもの頃、父の仕事の都合で各地を転々とした。","example_reading":"こどものころ、ちちのしごとのつごうでかくちをてんてんとした。","example_meaning":"Hồi nhỏ, vì công việc của bố, tôi chuyển nhà khắp nơi."}],"level":"a1"},
{"word":"点々と","reading":"てんてんと","meaning":"rải rác, từng chấm từng chấm","hanviet":"điểm điểm","antonym":"一面に（いちめんに）: khắp một mảng","antonym_hanviet":"nhất diện","note":"Dạng と. Hay đi với 続く, 散らばる. Chú ý phân biệt với 転々と.","example":"雪の上に足跡が点々と続いている。","example_reading":"ゆきのうえにあしあとがてんてんとつづいている。","example_meaning":"Dấu chân rải rác kéo dài trên tuyết.","examples":[{"example":"雪の上に足跡が点々と続いている。","example_reading":"ゆきのうえにあしあとがてんてんとつづいている。","example_meaning":"Dấu chân rải rác kéo dài trên tuyết."},{"example":"空には、白い雲が点々と浮かんでいる。","example_reading":"そらには、しろいくもがてんてんとうかんでいる。","example_meaning":"Trên bầu trời, những đám mây trắng rải rác trôi."}],"level":"a1"},
{"word":"適切に","reading":"てきせつに","meaning":"một cách thích hợp, đúng mức","hanviet":"thích thiết","antonym":"不適切に（ふてきせつに）: không thích hợp","antonym_hanviet":"bất thích thiết","note":"Dạng に. Hay đi với 対応する, 処理する, 判断する, 使う. Dùng nhiều trong công việc, văn viết.","example":"問題が起きたときは、適切に対応してください。","example_reading":"もんだいがおきたときは、てきせつにたいおうしてください。","example_meaning":"Khi xảy ra vấn đề, hãy xử lý cho thích hợp.","examples":[{"example":"問題が起きたときは、適切に対応してください。","example_reading":"もんだいがおきたときは、てきせつにたいおうしてください。","example_meaning":"Khi xảy ra vấn đề, hãy xử lý cho thích hợp."},{"example":"薬は医者の指示どおりに適切に使う必要がある。","example_reading":"くすりはいしゃのしじどおりにてきせつにつかうひつようがある。","example_meaning":"Thuốc cần được dùng đúng cách theo chỉ định của bác sĩ."}],"level":"a1"},
{"word":"自ずと","reading":"おのずと","meaning":"tự nhiên mà thành, tự khắc","hanviet":"tự","antonym":"無理やり（むりやり）: ép buộc","antonym_hanviet":"vô lý","note":"Dạng と. Hay đi với 分かる, 見えてくる, 決まる. Văn viết, sắc thái trang trọng.","example":"努力を続ければ、結果は自ずとついてくる。","example_reading":"どりょくをつづければ、けっかはおのずとついてくる。","example_meaning":"Nếu cứ nỗ lực thì kết quả tự khắc sẽ đến.","examples":[{"example":"努力を続ければ、結果は自ずとついてくる。","example_reading":"どりょくをつづければ、けっかはおのずとついてくる。","example_meaning":"Nếu cứ nỗ lực thì kết quả tự khắc sẽ đến."},{"example":"しばらく考えれば、答えは自ずと見えてくるはずだ。","example_reading":"しばらくかんがえれば、こたえはおのずとみえてくるはずだ。","example_meaning":"Nghĩ một lúc thì câu trả lời hẳn sẽ tự hiện ra."}],"level":"a1"},
{"word":"容易に","reading":"よういに","meaning":"một cách dễ dàng","hanviet":"dung dị","antonym":"困難に（こんなんに）: khó khăn / 苦労して（くろうして）: vất vả","antonym_hanviet":"khốn nạn / khổ lao","note":"Dạng に. Hay đi với 想像できる, 理解できる, 手に入る, ～ではない. Trang trọng hơn 簡単に.","example":"彼の性格なら、結果は容易に想像できる。","example_reading":"かれのせいかくなら、けっかはよういにそうぞうできる。","example_meaning":"Với tính cách của anh ấy thì dễ dàng đoán được kết quả.","examples":[{"example":"彼の性格なら、結果は容易に想像できる。","example_reading":"かれのせいかくなら、けっかはよういにそうぞうできる。","example_meaning":"Với tính cách của anh ấy thì dễ dàng đoán được kết quả."},{"example":"今のやり方では、目標を容易に達成することはできない。","example_reading":"いまのやりかたでは、もくひょうをよういにたっせいすることはできない。","example_meaning":"Với cách làm hiện tại thì không thể dễ dàng đạt mục tiêu."}],"level":"a1"},
{"word":"滔々と","reading":"とうとうと","meaning":"thao thao, lưu loát liền mạch","hanviet":"thao thao","antonym":"たどたどしく: ấp úng","note":"Dạng と. Hay đi với 述べる, 語る. Văn viết, sắc thái trang trọng.","example":"彼は滔々と持論を述べた。","example_reading":"かれはとうとうとじろんをのべた。","example_meaning":"Anh ấy thao thao trình bày quan điểm của mình.","examples":[{"example":"彼は滔々と持論を述べた。","example_reading":"かれはとうとうとじろんをのべた。","example_meaning":"Anh ấy thao thao trình bày quan điểm của mình."},{"example":"彼女は滔々と自分の夢を語り始めた。","example_reading":"かのじょはとうとうとじぶんのゆめをかたりはじめた。","example_meaning":"Cô ấy bắt đầu thao thao kể về ước mơ của mình."}],"level":"a1"},
{"word":"詳細に","reading":"しょうさいに","meaning":"một cách chi tiết, tỉ mỉ","hanviet":"tường tế","antonym":"大まかに（おおまかに）: đại khái / 簡潔に（かんけつに）: ngắn gọn","antonym_hanviet":"đại / giản khiết","note":"Dạng に. Hay đi với 説明する, 調べる, 記録する. Văn viết, báo cáo.","example":"事故の原因は、専門家が詳細に調べている。","example_reading":"じこのげんいんは、せんもんかがしょうさいにしらべている。","example_meaning":"Nguyên nhân tai nạn đang được chuyên gia điều tra chi tiết.","examples":[{"example":"事故の原因は、専門家が詳細に調べている。","example_reading":"じこのげんいんは、せんもんかがしょうさいにしらべている。","example_meaning":"Nguyên nhân tai nạn đang được chuyên gia điều tra chi tiết."},{"example":"実験の結果は、ノートに詳細に記録しておいた。","example_reading":"じっけんのけっかは、ノートにしょうさいにきろくしておいた。","example_meaning":"Kết quả thí nghiệm tôi đã ghi chép chi tiết vào vở."}],"level":"a1"},
{"word":"精密に","reading":"せいみつに","meaning":"một cách tinh vi, chính xác cao","hanviet":"tinh mật","antonym":"大雑把に（おおざっぱに）: đại khái / 粗く（あらく）: thô","antonym_hanviet":"đại tạp bả / thô","note":"Dạng に. Hay đi với 加工する, 測定する, 調べる.","example":"この機械は、部品を精密に加工することができる。","example_reading":"このきかいは、ぶひんをせいみつにかこうすることができる。","example_meaning":"Chiếc máy này có thể gia công linh kiện với độ chính xác cao.","examples":[{"example":"この機械は、部品を精密に加工することができる。","example_reading":"このきかいは、ぶひんをせいみつにかこうすることができる。","example_meaning":"Chiếc máy này có thể gia công linh kiện với độ chính xác cao."},{"example":"実験のデータは、精密に測定しなければならない。","example_reading":"じっけんのデータは、せいみつにそくていしなければならない。","example_meaning":"Dữ liệu thí nghiệm phải được đo chính xác tỉ mỉ."}],"level":"a1"},
{"word":"不規則に","reading":"ふきそくに","meaning":"một cách bất thường, không đều","hanviet":"bất quy tắc","antonym":"規則的に（きそくてきに）: đều đặn / 定期的に（ていきてきに）: định kỳ","antonym_hanviet":"quy tắc đích / định kỳ đích","note":"Dạng に. Hay đi với なる, 動く, 並ぶ. Trái nghĩa: 規則的に.","example":"夜勤が多く、生活が不規則になりがちだ。","example_reading":"やきんがおおく、せいかつがふきそくになりがちだ。","example_meaning":"Làm ca đêm nhiều nên sinh hoạt hay bị thất thường.","examples":[{"example":"夜勤が多く、生活が不規則になりがちだ。","example_reading":"やきんがおおく、せいかつがふきそくになりがちだ。","example_meaning":"Làm ca đêm nhiều nên sinh hoạt hay bị thất thường."},{"example":"彼の心臓は、ときどき不規則に動くことがある。","example_reading":"かれのしんぞうは、ときどきふきそくにうごくことがある。","example_meaning":"Tim anh ấy thỉnh thoảng đập không đều."}],"level":"a1"},
{"word":"包括的に","reading":"ほうかつてきに","meaning":"một cách bao quát, tổng thể","hanviet":"bao quát đích","antonym":"部分的に（ぶぶんてきに）: một phần / 限定的に（げんていてきに）: hạn chế","antonym_hanviet":"bộ phân đích / hạn định đích","note":"Dạng に. Hay đi với 解決する, 見る, 捉える. Xét toàn bộ nhiều mặt cùng lúc.","example":"この制度は、社会の問題を包括的に解決することを目指している。","example_reading":"このせいどは、しゃかいのもんだいをほうかつてきにかいけつすることをめざしている。","example_meaning":"Chế độ này nhằm giải quyết toàn diện các vấn đề xã hội.","examples":[{"example":"この制度は、社会の問題を包括的に解決することを目指している。","example_reading":"このせいどは、しゃかいのもんだいをほうかつてきにかいけつすることをめざしている。","example_meaning":"Chế độ này nhằm giải quyết toàn diện các vấn đề xã hội."},{"example":"包括的に見ると、この地域の経済は安定している。","example_reading":"ほうかつてきにみると、このちいきのけいざいはあんていしている。","example_meaning":"Nhìn một cách bao quát, kinh tế khu vực này đang ổn định."}],"level":"a1"},
{"word":"忠実に","reading":"ちゅうじつに","meaning":"một cách trung thành, đúng nguyên bản","hanviet":"trung thực","note":"Dạng に. Hay đi với 守る, 再現する, 従う.","example":"彼は上司の指示を忠実に守って作業を進めた。","example_reading":"かれはじょうしのしじをちゅうじつにまもってさぎょうをすすめた。","example_meaning":"Anh ấy làm việc trung thành theo chỉ thị của cấp trên.","examples":[{"example":"彼は上司の指示を忠実に守って作業を進めた。","example_reading":"かれはじょうしのしじをちゅうじつにまもってさぎょうをすすめた。","example_meaning":"Anh ấy làm việc trung thành theo chỉ thị của cấp trên."},{"example":"この映画は、原作を忠実に再現している。","example_reading":"このえいがは、げんさくをちゅうじつにさいげんしている。","example_meaning":"Bộ phim này tái hiện trung thành nguyên tác."}],"level":"a1"},
{"word":"独自に","reading":"どくじに","meaning":"một cách riêng, độc lập","hanviet":"độc tự","antonym":"共同で（きょうどうで）: cùng nhau / 一緒に（いっしょに）: cùng nhau","antonym_hanviet":"cộng đồng / nhất tự","note":"Dạng に. Hay đi với 開発する, 調査する, 判断する.","example":"この会社は、独自に技術を開発している。","example_reading":"このかいしゃは、どくじにぎじゅつをかいはつしている。","example_meaning":"Công ty này tự phát triển công nghệ riêng.","examples":[{"example":"この会社は、独自に技術を開発している。","example_reading":"このかいしゃは、どくじにぎじゅつをかいはつしている。","example_meaning":"Công ty này tự phát triển công nghệ riêng."},{"example":"私たちは独自に調査を進めることにした。","example_reading":"わたしたちはどくじにちょうさをすすめることにした。","example_meaning":"Chúng tôi quyết định tiến hành điều tra độc lập."}],"level":"a1"},
{"word":"客観的に","reading":"きゃっかんてきに","meaning":"một cách khách quan","hanviet":"khách quan đích","antonym":"主観的に（しゅかんてきに）: chủ quan","antonym_hanviet":"chủ quan đích","note":"Dạng に. Hay đi với 見る, 判断する, 評価する. Trái nghĩa: 主観的に.","example":"自分の作品を客観的に見るのは難しい。","example_reading":"じぶんのさくひんをきゃっかんてきにみるのはむずかしい。","example_meaning":"Nhìn tác phẩm của chính mình một cách khách quan thì khó.","examples":[{"example":"自分の作品を客観的に見るのは難しい。","example_reading":"じぶんのさくひんをきゃっかんてきにみるのはむずかしい。","example_meaning":"Nhìn tác phẩm của chính mình một cách khách quan thì khó."},{"example":"審判は両チームを客観的に評価しなければならない。","example_reading":"しんぱんはりょうチームをきゃっかんてきにひょうかしなければならない。","example_meaning":"Trọng tài phải đánh giá hai đội một cách khách quan."}],"level":"a1"},
{"word":"意識的に","reading":"いしきてきに","meaning":"một cách có ý thức, chủ ý","hanviet":"ý thức đích","antonym":"無意識に（むいしきに）: vô thức / 反射的に（はんしゃてきに）: theo phản xạ","antonym_hanviet":"vô ý thức / phản xạ đích","note":"Dạng に. Hay đi với 避ける, 使う, 心がける. Trái nghĩa: 無意識に.","example":"健康のために、意識的に階段を使うようにしている。","example_reading":"けんこうのために、いしきてきにかいだんをつかうようにしている。","example_meaning":"Vì sức khỏe, tôi chủ động dùng cầu thang bộ.","examples":[{"example":"健康のために、意識的に階段を使うようにしている。","example_reading":"けんこうのために、いしきてきにかいだんをつかうようにしている。","example_meaning":"Vì sức khỏe, tôi chủ động dùng cầu thang bộ."},{"example":"彼は私を意識的に避けているようだ。","example_reading":"かれはわたしをいしきてきにさけているようだ。","example_meaning":"Có vẻ anh ấy cố ý tránh mặt tôi."}],"level":"a1"},
{"word":"現実的に","reading":"げんじつてきに","meaning":"một cách thực tế","hanviet":"hiện thực đích","antonym":"非現実的に（ひげんじつてきに）: phi thực tế / 理想的に（りそうてきに）: lý tưởng","antonym_hanviet":"phi hiện thực đích / lý tưởng đích","note":"Dạng に. Hay đi với 考える, 難しい, 可能. 現実的に無理 = thực tế thì không thể.","example":"予算を考えると、現実的に実現するのは難しい。","example_reading":"よさんをかんがえると、げんじつてきにじつげんするのはむずかしい。","example_meaning":"Xét ngân sách thì thực tế khó mà thực hiện được.","examples":[{"example":"予算を考えると、現実的に実現するのは難しい。","example_reading":"よさんをかんがえると、げんじつてきにじつげんするのはむずかしい。","example_meaning":"Xét ngân sách thì thực tế khó mà thực hiện được."},{"example":"夢を追う前に、現実的に生活を考えなければならない。","example_reading":"ゆめをおうまえに、げんじつてきにせいかつをかんがえなければならない。","example_meaning":"Trước khi theo đuổi ước mơ, phải tính chuyện sinh hoạt một cách thực tế."}],"level":"a1"},
{"word":"颯爽と","reading":"さっそうと","meaning":"oai phong, nhanh nhẹn, phong thái","hanviet":"táp sảng","antonym":"もたもた: lóng ngóng, chậm chạp","note":"Dạng と. Hình ảnh người đi hoặc xuất hiện với dáng vẻ gọn gàng, tự tin.","example":"彼女は颯爽と会場に現れた。","example_reading":"かのじょはさっそうとかいじょうにあらわれた。","example_meaning":"Cô ấy xuất hiện ở hội trường với phong thái oai phong.","examples":[{"example":"彼女は颯爽と会場に現れた。","example_reading":"かのじょはさっそうとかいじょうにあらわれた。","example_meaning":"Cô ấy xuất hiện ở hội trường với phong thái oai phong."},{"example":"彼は颯爽と自転車で走り去った。","example_reading":"かれはさっそうとじてんしゃではしりさった。","example_meaning":"Anh ấy phóng xe đạp đi một cách oai phong."}],"level":"a1"},
{"word":"本格的に","reading":"ほんかくてきに","meaning":"một cách chính thức, đúng nghĩa","hanviet":"bản cách đích","note":"Dạng に. Hay đi với 始める, 取り組む, 動き出す. Bắt đầu hẳn hoi, ở mức nghiêm túc.","antonym":"手軽に（てがるに）: đơn giản, dễ dàng","antonym_hanviet":"thủ khinh","example":"来月から本格的にダイエットを始めるつもりだ。","example_reading":"らいげつからほんかくてきにダイエットをはじめるつもりだ。","example_meaning":"Từ tháng sau tôi định bắt đầu ăn kiêng nghiêm túc.","examples":[{"example":"来月から本格的にダイエットを始めるつもりだ。","example_reading":"らいげつからほんかくてきにダイエットをはじめるつもりだ。","example_meaning":"Từ tháng sau tôi định bắt đầu ăn kiêng nghiêm túc."},{"example":"来週から新しいプロジェクトが本格的に動き出す。","example_reading":"らいしゅうからあたらしいプロジェクトがほんかくてきにうごきだす。","example_meaning":"Từ tuần sau dự án mới sẽ chính thức vận hành."}],"level":"a1"},
{"word":"粛々と","reading":"しゅくしゅくと","meaning":"trang nghiêm, lặng lẽ và đúng quy trình","hanviet":"túc túc","antonym":"騒然と（そうぜんと）: nhốn nháo","antonym_hanviet":"tao nhiên","note":"Dạng と. Hay đi với 進める, 行う. Tiến hành điềm tĩnh, không ồn ào.","example":"式は粛々と進められた。","example_reading":"しきはしゅくしゅくとすすめられた。","example_meaning":"Buổi lễ được tiến hành trang nghiêm.","examples":[{"example":"式は粛々と進められた。","example_reading":"しきはしゅくしゅくとすすめられた。","example_meaning":"Buổi lễ được tiến hành trang nghiêm."},{"example":"会議は粛々と進められ、無事に終わった。","example_reading":"かいぎはしゅくしゅくとすすめられ、ぶじにおわった。","example_meaning":"Cuộc họp được tiến hành trang nghiêm và kết thúc suôn sẻ."}],"level":"a1"},
{"word":"悠然と","reading":"ゆうぜんと","meaning":"điềm tĩnh, ung dung, bình thản","hanviet":"du nhiên","antonym":"慌てて（あわてて）: hoảng hốt, vội vàng","antonym_hanviet":"hoảng","note":"Dạng と. Gần với 悠々と nhưng nhấn mạnh sự điềm tĩnh, thản nhiên.","example":"彼は悠然とコーヒーを飲んでいた。","example_reading":"かれはゆうぜんとコーヒーをのんでいた。","example_meaning":"Anh ấy ung dung uống cà phê.","examples":[{"example":"彼は悠然とコーヒーを飲んでいた。","example_reading":"かれはゆうぜんとコーヒーをのんでいた。","example_meaning":"Anh ấy ung dung uống cà phê."},{"example":"犬は悠然と道の真ん中を歩いていった。","example_reading":"いぬはゆうぜんとみちのまんなかをあるいていった。","example_meaning":"Con chó thong thả đi giữa đường."}],"level":"a1"},
{"word":"無邪気に","reading":"むじゃきに","meaning":"một cách ngây thơ, vô tư","hanviet":"vô tà khí","antonym":"計算高く（けいさんだかく）: tính toán","antonym_hanviet":"kế toán cao","note":"Dạng に. Hay đi với 笑う, 遊ぶ, 喜ぶ.","example":"子どもたちは、無邪気に砂遊びを楽しんでいる。","example_reading":"こどもたちは、むじゃきにすなあそびをたのしんでいる。","example_meaning":"Bọn trẻ vô tư vui chơi với cát.","examples":[{"example":"子どもたちは、無邪気に砂遊びを楽しんでいる。","example_reading":"こどもたちは、むじゃきにすなあそびをたのしんでいる。","example_meaning":"Bọn trẻ vô tư vui chơi với cát."},{"example":"彼女は無邪気に笑って、「また来るね」と言った。","example_reading":"かのじょはむじゃきにわらって、「またくるね」といった。","example_meaning":"Cô ấy cười ngây thơ và nói \"Mình sẽ lại đến nhé\"."}],"level":"a1"},
{"word":"不器用に","reading":"ぶきように","meaning":"một cách vụng về","hanviet":"bất khí dụng","antonym":"器用に（きように）: khéo léo / 巧みに（たくみに）: điêu luyện","antonym_hanviet":"khí dụng / xảo","note":"Dạng に. Hay đi với 握る, 生きる, 笑う.","example":"彼は不器用に包丁を握って、野菜を切り始めた。","example_reading":"かれはぶきようにほうちょうをにぎって、やさいをきりはじめた。","example_meaning":"Anh ấy cầm dao một cách vụng về và bắt đầu cắt rau.","examples":[{"example":"彼は不器用に包丁を握って、野菜を切り始めた。","example_reading":"かれはぶきようにほうちょうをにぎって、やさいをきりはじめた。","example_meaning":"Anh ấy cầm dao một cách vụng về và bắt đầu cắt rau."},{"example":"不器用に生きることしかできないが、それが私の生き方だ。","example_reading":"ぶきようにいきることしかできないが、それがわたしのいきかただ。","example_meaning":"Tôi chỉ biết sống vụng về, nhưng đó chính là cách sống của tôi."}],"level":"a1"},
{"word":"謙虚に","reading":"けんきょに","meaning":"một cách khiêm tốn","hanviet":"khiêm hư","antonym":"傲慢に（ごうまんに）: kiêu ngạo / 偉そうに（えらそうに）: ra vẻ ta đây","antonym_hanviet":"ngạo mạn / (không có âm Hán Việt)","note":"Dạng に. Hay đi với 受け止める, 学ぶ, 耳を傾ける.","example":"批判を謙虚に受け止める姿勢が大切だ。","example_reading":"ひはんをけんきょにうけとめるしせいがたいせつだ。","example_meaning":"Thái độ tiếp nhận lời phê bình một cách khiêm tốn là điều quan trọng.","examples":[{"example":"批判を謙虚に受け止める姿勢が大切だ。","example_reading":"ひはんをけんきょにうけとめるしせいがたいせつだ。","example_meaning":"Thái độ tiếp nhận lời phê bình một cách khiêm tốn là điều quan trọng."},{"example":"成功しても、謙虚に学び続けたい。","example_reading":"せいこうしても、けんきょにまなびつづけたい。","example_meaning":"Dù thành công, tôi vẫn muốn khiêm tốn học hỏi mãi."}],"level":"a1"},
{"word":"一方的に","reading":"いっぽうてきに","meaning":"một cách đơn phương, một chiều","hanviet":"nhất phương đích","antonym":"相互に（そうごに）: qua lại / 話し合って（はなしあって）: bàn bạc / 互いに（たがいに）: lẫn nhau","antonym_hanviet":"tương hỗ / thoại hợp / (không có âm Hán Việt)","note":"Dạng に. Hay đi với 決める, 言う, 断る, 攻められる. Thường mang sắc thái tiêu cực.","example":"会社は一方的に契約を打ち切った。","example_reading":"かいしゃはいっぽうてきにけいやくをうちきった。","example_meaning":"Công ty đơn phương chấm dứt hợp đồng.","examples":[{"example":"会社は一方的に契約を打ち切った。","example_reading":"かいしゃはいっぽうてきにけいやくをうちきった。","example_meaning":"Công ty đơn phương chấm dứt hợp đồng."},{"example":"自分の意見を一方的に話すだけでは、会話にならない。","example_reading":"じぶんのいけんをいっぽうてきにはなすだけでは、かいわにならない。","example_meaning":"Chỉ nói một chiều ý kiến của mình thì không thành cuộc trò chuyện."}],"level":"a1"},
{"word":"自在に","reading":"じざいに","meaning":"tự do tự tại, tùy ý","hanviet":"tự tại","antonym":"不自由に（ふじゆうに）: không tự do, bất tiện","antonym_hanviet":"bất tự do","note":"Dạng に. Hay đi với 操る, 変える, 動かす. Điều khiển theo ý muốn; văn viết.","example":"彼は自在にロボットを操作できる。","example_reading":"かれはじざいにロボットをそうさできる。","example_meaning":"Anh ấy điều khiển robot tùy ý.","examples":[{"example":"彼は自在にロボットを操作できる。","example_reading":"かれはじざいにロボットをそうさできる。","example_meaning":"Anh ấy điều khiển robot tùy ý."},{"example":"この椅子は高さを自在に変えられる。","example_reading":"このいすはたかさをじざいにかえられる。","example_meaning":"Chiếc ghế này có thể thay đổi độ cao tùy ý."}],"level":"a1"},
{"word":"全面的に","reading":"ぜんめんてきに","meaning":"một cách toàn diện, hoàn toàn","hanviet":"toàn diện đích","antonym":"部分的に（ぶぶんてきに）: một phần","antonym_hanviet":"bộ phân đích","note":"Dạng に. Hay đi với 賛成する, 協力する, 認める.","example":"私は彼の意見に全面的に賛成だ。","example_reading":"わたしはかれのいけんにぜんめんてきにさんせいだ。","example_meaning":"Tôi hoàn toàn đồng ý với ý kiến của anh ấy.","examples":[{"example":"私は彼の意見に全面的に賛成だ。","example_reading":"わたしはかれのいけんにぜんめんてきにさんせいだ。","example_meaning":"Tôi hoàn toàn đồng ý với ý kiến của anh ấy."},{"example":"会社は新しい事業を全面的に支援すると発表した。","example_reading":"かいしゃはあたらしいじぎょうをぜんめんてきにしえんするとはっぴょうした。","example_meaning":"Công ty thông báo sẽ hỗ trợ toàn diện cho dự án mới."}],"level":"a1"},
{"word":"根本的に","reading":"こんぽんてきに","meaning":"về căn bản, tận gốc","hanviet":"căn bản đích","antonym":"表面的に（ひょうめんてきに）: bề ngoài / 部分的に（ぶぶんてきに）: một phần","antonym_hanviet":"biểu diện đích / bộ phân đích","note":"Dạng に. Hay đi với 違う, 解決する, 変える.","example":"二人の考え方は根本的に違っている。","example_reading":"ふたりのかんがえかたはこんぽんてきにちがっている。","example_meaning":"Cách nghĩ của hai người khác nhau về căn bản.","examples":[{"example":"二人の考え方は根本的に違っている。","example_reading":"ふたりのかんがえかたはこんぽんてきにちがっている。","example_meaning":"Cách nghĩ của hai người khác nhau về căn bản."},{"example":"問題を根本的に解決しなければ、また同じことが起きる。","example_reading":"もんだいをこんぽんてきにかいけつしなければ、またおなじことがおきる。","example_meaning":"Nếu không giải quyết vấn đề tận gốc thì sẽ lại xảy ra như cũ."}],"level":"a1"},
{"word":"総合的に","reading":"そうごうてきに","meaning":"một cách tổng hợp, toàn diện","hanviet":"tổng hợp đích","antonym":"個別に（こべつに）: riêng lẻ / 部分的に（ぶぶんてきに）: một phần","antonym_hanviet":"cá biệt / bộ phân đích","note":"Dạng に. Hay đi với 判断する, 評価する, 見る.","example":"成績だけでなく、人柄も総合的に判断します。","example_reading":"せいせきだけでなく、ひとがらもそうごうてきにはんだんします。","example_meaning":"Không chỉ thành tích, chúng tôi còn đánh giá tổng hợp cả nhân cách.","examples":[{"example":"成績だけでなく、人柄も総合的に判断します。","example_reading":"せいせきだけでなく、ひとがらもそうごうてきにはんだんします。","example_meaning":"Không chỉ thành tích, chúng tôi còn đánh giá tổng hợp cả nhân cách."},{"example":"総合的に考えると、この会社に入るのが一番いい。","example_reading":"そうごうてきにかんがえると、このかいしゃにはいるのがいちばんいい。","example_meaning":"Xét tổng thể thì vào công ty này là tốt nhất."}],"level":"a1"},
{"word":"感情的に","reading":"かんじょうてきに","meaning":"theo cảm xúc, nóng nảy","hanviet":"cảm tình đích","antonym":"理性的に（りせいてきに）: lý trí / 冷静に（れいせいに）: bình tĩnh / 論理的に（ろんりてきに）: logic","antonym_hanviet":"lý tính đích / lãnh tĩnh / luận lý đích","note":"Dạng に. Hay đi với なる, 怒る, 反論する. Trái nghĩa: 冷静に, 論理的に.","example":"彼女は感情的に反論して、話がまとまらなかった。","example_reading":"かのじょはかんじょうてきにはんろんして、はなしがまとまらなかった。","example_meaning":"Cô ấy phản bác bằng cảm xúc nên cuộc nói chuyện không đi đến đâu.","examples":[{"example":"彼女は感情的に反論して、話がまとまらなかった。","example_reading":"かのじょはかんじょうてきにはんろんして、はなしがまとまらなかった。","example_meaning":"Cô ấy phản bác bằng cảm xúc nên cuộc nói chuyện không đi đến đâu."},{"example":"感情的に判断すると、あとで後悔することもある。","example_reading":"かんじょうてきにはんだんすると、あとでこうかいすることもある。","example_meaning":"Phán đoán theo cảm xúc đôi khi sẽ hối hận về sau."}],"level":"a1"},
{"word":"端的に","reading":"たんてきに","meaning":"một cách thẳng thắn, ngắn gọn","hanviet":"đoan đích","antonym":"回りくどく（まわりくどく）: vòng vo / 遠回しに（とおまわしに）: nói bóng gió","antonym_hanviet":"hồi / viễn hồi","note":"Dạng に. Hay đi với 言う, 示す, 表す. 端的に言えば = nói thẳng ra.","example":"端的に言えば、この計画は費用がかかりすぎる。","example_reading":"たんてきにいえば、このけいかくはひようがかかりすぎる。","example_meaning":"Nói thẳng ra, kế hoạch này tốn quá nhiều chi phí.","examples":[{"example":"端的に言えば、この計画は費用がかかりすぎる。","example_reading":"たんてきにいえば、このけいかくはひようがかかりすぎる。","example_meaning":"Nói thẳng ra, kế hoạch này tốn quá nhiều chi phí."},{"example":"その一言が、彼の性格を端的に表している。","example_reading":"そのひとことが、かれのせいかくをたんてきにあらわしている。","example_meaning":"Câu nói đó thể hiện tính cách anh ấy một cách ngắn gọn mà rõ."}],"level":"a1"},
{"word":"軽々と","reading":"かるがると","meaning":"nhẹ nhàng, dễ dàng","hanviet":"khinh khinh","antonym":"苦労して（くろうして）: vất vả","antonym_hanviet":"khổ lao","note":"Dạng と. Hay đi với 持ち上げる, 跳ぶ, こなす.","example":"彼は重い荷物を軽々と持ち上げた。","example_reading":"かれはおもいにもつをかるがるともちあげた。","example_meaning":"Anh ấy nhấc hành lý nặng một cách nhẹ nhàng.","examples":[{"example":"彼は重い荷物を軽々と持ち上げた。","example_reading":"かれはおもいにもつをかるがるともちあげた。","example_meaning":"Anh ấy nhấc hành lý nặng một cách nhẹ nhàng."},{"example":"彼女は軽々と五メートルの壁を飛び越えた。","example_reading":"かのじょはかるがるとごメートルのかべをとびこえた。","example_meaning":"Cô ấy nhảy qua bức tường năm mét một cách nhẹ nhàng."}],"level":"a1"},
{"word":"無神経に","reading":"むしんけいに","meaning":"một cách vô tâm, thiếu tế nhị","hanviet":"vô thần kinh","antonym":"繊細に（せんさいに）: tinh tế / 気を遣って（きをつかって）: ý tứ","antonym_hanviet":"tiêm tế / khí khiển","note":"Dạng に. Hay đi với 言う, 笑う, 触れる.","example":"彼は人の悩みを無神経に笑い飛ばした。","example_reading":"かれはひとのなやみをむしんけいにわらいとばした。","example_meaning":"Anh ta vô tâm cười xòa nỗi lo của người khác.","examples":[{"example":"彼は人の悩みを無神経に笑い飛ばした。","example_reading":"かれはひとのなやみをむしんけいにわらいとばした。","example_meaning":"Anh ta vô tâm cười xòa nỗi lo của người khác."},{"example":"無神経に傷つくことを言って、後悔している。","example_reading":"むしんけいにきずつくことをいって、こうかいしている。","example_meaning":"Tôi hối hận vì đã vô tâm nói điều làm tổn thương người khác."}],"level":"a1"},
{"word":"気まぐれに","reading":"きまぐれに","meaning":"một cách thất thường, hứng lên","hanviet":"khí","antonym":"一貫して（いっかんして）: nhất quán / 規則的に（きそくてきに）: đều đặn","antonym_hanviet":"nhất quán / quy tắc đích","note":"Dạng に. Hay đi với 近づく, 出かける, 変わる.","example":"猫は気まぐれに近づいてきては、また離れていく。","example_reading":"ねこはきまぐれにちかづいてきては、またはなれていく。","example_meaning":"Con mèo hứng lên thì lại gần rồi lại bỏ đi.","examples":[{"example":"猫は気まぐれに近づいてきては、また離れていく。","example_reading":"ねこはきまぐれにちかづいてきては、またはなれていく。","example_meaning":"Con mèo hứng lên thì lại gần rồi lại bỏ đi."},{"example":"彼は気まぐれに旅に出て、一か月帰ってこなかった。","example_reading":"かれはきまぐれにたびにでて、いっかげつかえってこなかった。","example_meaning":"Anh ấy bốc đồng đi du lịch rồi cả tháng không về."}],"level":"a1"},
{"word":"質素に","reading":"しっそに","meaning":"một cách giản dị, tằn tiện","hanviet":"chất tố","antonym":"贅沢に（ぜいたくに）: xa hoa / 豪華に（ごうかに）: sang trọng / 盛大に（せいだいに）: long trọng","antonym_hanviet":"trế trạch / hào hoa / thịnh đại","note":"Dạng に. Hay đi với 暮らす, 生活する, 始まる.","example":"祖父は、お金があっても質素に暮らしていた。","example_reading":"そふは、おかねがあってもしっそにくらしていた。","example_meaning":"Ông tôi dù có tiền vẫn sống giản dị.","examples":[{"example":"祖父は、お金があっても質素に暮らしていた。","example_reading":"そふは、おかねがあってもしっそにくらしていた。","example_meaning":"Ông tôi dù có tiền vẫn sống giản dị."},{"example":"質素に始まった結婚生活も、今では三十年になる。","example_reading":"しっそにはじまったけっこんせいかつも、いまではさんじゅうねんになる。","example_meaning":"Cuộc sống hôn nhân bắt đầu giản dị ấy nay đã ba mươi năm."}],"level":"a1"},
{"word":"堅実に","reading":"けんじつに","meaning":"một cách chắc chắn, thận trọng","hanviet":"kiên thực","antonym":"軽率に（けいそつに）: khinh suất","antonym_hanviet":"khinh suất","note":"Dạng に. Hay đi với 貯める, 経営する, 働く. Không mạo hiểm.","example":"彼は堅実に貯金して、家を買った。","example_reading":"かれはけんじつにちょきんして、いえをかった。","example_meaning":"Anh ấy tiết kiệm chắc chắn rồi mua được nhà.","examples":[{"example":"彼は堅実に貯金して、家を買った。","example_reading":"かれはけんじつにちょきんして、いえをかった。","example_meaning":"Anh ấy tiết kiệm chắc chắn rồi mua được nhà."},{"example":"この会社は、堅実に経営を続けてきた。","example_reading":"このかいしゃは、けんじつにけいえいをつづけてきた。","example_meaning":"Công ty này vẫn điều hành vững chắc từ trước đến nay."}],"level":"a1"},
{"word":"入念に","reading":"にゅうねんに","meaning":"một cách cẩn thận, kỹ lưỡng","hanviet":"nhập niệm","antonym":"粗雑に（そざつに）: cẩu thả / いい加減に（いいかげんに）: qua loa","antonym_hanviet":"thô tạp / gia giảm","note":"Dạng に. Hay đi với 調べる, 手入れする, 点検する, 準備する.","example":"試合の前に、選手たちは入念に体をほぐした。","example_reading":"しあいのまえに、せんしゅたちはにゅうねんにからだをほぐした。","example_meaning":"Trước trận đấu, các cầu thủ khởi động kỹ lưỡng.","examples":[{"example":"試合の前に、選手たちは入念に体をほぐした。","example_reading":"しあいのまえに、せんしゅたちはにゅうねんにからだをほぐした。","example_meaning":"Trước trận đấu, các cầu thủ khởi động kỹ lưỡng."},{"example":"出発前に、車を入念に点検した。","example_reading":"しゅっぱつまえに、くるまをにゅうねんにてんけんした。","example_meaning":"Trước khi khởi hành, tôi kiểm tra xe kỹ lưỡng."}],"level":"a1"},
{"word":"無難に","reading":"ぶなんに","meaning":"một cách an toàn, không sai sót","hanviet":"vô nan","antonym":"冒険的に（ぼうけんてきに）: mạo hiểm / 大胆に（だいたんに）: táo bạo","antonym_hanviet":"mạo hiểm đích / đại đảm","note":"Dạng に. Hay đi với こなす, まとめる, 選ぶ. Tránh rủi ro, không đặc sắc nhưng ổn.","example":"初めての発表だったが、無難にこなすことができた。","example_reading":"はじめてのはっぴょうだったが、ぶなんにこなすことができた。","example_meaning":"Lần đầu thuyết trình nhưng tôi đã làm ổn thỏa.","examples":[{"example":"初めての発表だったが、無難にこなすことができた。","example_reading":"はじめてのはっぴょうだったが、ぶなんにこなすことができた。","example_meaning":"Lần đầu thuyết trình nhưng tôi đã làm ổn thỏa."},{"example":"プレゼントは、無難にハンカチを選んだ。","example_reading":"プレゼントは、ぶなんにハンカチをえらんだ。","example_meaning":"Quà tặng thì tôi chọn chiếc khăn tay cho an toàn."}],"level":"a1"},
{"word":"不意に","reading":"ふいに","meaning":"một cách đột ngột, bất ngờ","hanviet":"bất ý","antonym":"前もって（まえもって）: trước / 予定通りに（よていどおりに）: đúng dự định","antonym_hanviet":"tiền / dự định thông","note":"Dạng に. Hay đi với 現れる, 止まる, 言われる.","example":"不意に電話が鳴って、思わず飛び上がった。","example_reading":"ふいにでんわがなって、おもわずとびあがった。","example_meaning":"Điện thoại đột ngột reo, tôi giật nảy người.","examples":[{"example":"不意に電話が鳴って、思わず飛び上がった。","example_reading":"ふいにでんわがなって、おもわずとびあがった。","example_meaning":"Điện thoại đột ngột reo, tôi giật nảy người."},{"example":"彼は不意に立ち止まって、空を見上げた。","example_reading":"かれはふいにたちどまって、そらをみあげた。","example_meaning":"Anh ấy bỗng dừng lại và ngước nhìn trời."}],"level":"a1"},
{"word":"立派に","reading":"りっぱに","meaning":"một cách xuất sắc, đàng hoàng","hanviet":"lập phái","antonym":"みっともなく: khó coi / 情けなく（なさけなく）: thảm hại","antonym_hanviet":" / tình","note":"Dạng に. Hay đi với 育つ, 務める, 成長する, 果たす.","example":"息子は立派に社会人として働いている。","example_reading":"むすこはりっぱにしゃかいじんとしてはたらいている。","example_meaning":"Con trai tôi đang làm việc ra dáng một người trưởng thành.","examples":[{"example":"息子は立派に社会人として働いている。","example_reading":"むすこはりっぱにしゃかいじんとしてはたらいている。","example_meaning":"Con trai tôi đang làm việc ra dáng một người trưởng thành."},{"example":"彼女は議長の役目を立派に果たした。","example_reading":"かのじょはぎちょうのやくめをりっぱにはたした。","example_meaning":"Cô ấy đã hoàn thành xuất sắc vai trò chủ tọa."}],"level":"a1"},
{"word":"速やかに","reading":"すみやかに","meaning":"nhanh chóng, kịp thời","hanviet":"tốc","antonym":"ゆっくり: chậm rãi","note":"Dạng に. Viết bằng kanji 速やか. Lịch sự, dùng trong thông báo và công việc.","example":"問題があれば、速やかに報告してください。","example_reading":"もんだいがあれば、すみやかにほうこくしてください。","example_meaning":"Nếu có vấn đề, hãy báo cáo ngay.","examples":[{"example":"問題があれば、速やかに報告してください。","example_reading":"もんだいがあれば、すみやかにほうこくしてください。","example_meaning":"Nếu có vấn đề, hãy báo cáo ngay."},{"example":"事故が起きたら、速やかに避難してください。","example_reading":"じこがおきたら、すみやかにひなんしてください。","example_meaning":"Khi xảy ra tai nạn, xin hãy sơ tán nhanh chóng."}],"level":"a1"},
{"word":"見事に","reading":"みごとに","meaning":"một cách tuyệt vời, ngoạn mục","hanviet":"kiến sự","antonym":"無様に（ぶざまに）: thảm hại / 下手に（へたに）: vụng về","antonym_hanviet":"vô dạng / hạ thủ","note":"Dạng に. Hay đi với 成功する, 勝つ, 決まる. Cũng dùng mỉa mai khi thất bại hoàn toàn (見事に失敗する).","example":"彼は難しい試験に見事に合格した。","example_reading":"かれはむずかしいしけんにみごとにごうかくした。","example_meaning":"Anh ấy đã đỗ kỳ thi khó một cách ngoạn mục.","examples":[{"example":"彼は難しい試験に見事に合格した。","example_reading":"かれはむずかしいしけんにみごとにごうかくした。","example_meaning":"Anh ấy đã đỗ kỳ thi khó một cách ngoạn mục."},{"example":"私の予想は見事に外れてしまった。","example_reading":"わたしのよそうはみごとにはずれてしまった。","example_meaning":"Dự đoán của tôi trật lất hoàn toàn."}],"level":"a1"},
{"word":"静かに","reading":"しずかに","meaning":"yên lặng, lặng lẽ, nhẹ nhàng","hanviet":"tĩnh","antonym":"賑やかに（にぎやかに）: rộn ràng / 騒然と（そうぜんと）: nhốn nháo","antonym_hanviet":"chẩn / tao nhiên","note":"Dạng に. Hay đi với 話す, 歩く, 閉める, 待つ.","example":"赤ちゃんが寝ているので、静かに歩いてください。","example_reading":"あかちゃんがねているので、しずかにあるいてください。","example_meaning":"Em bé đang ngủ nên xin hãy đi nhẹ nhàng.","examples":[{"example":"赤ちゃんが寝ているので、静かに歩いてください。","example_reading":"あかちゃんがねているので、しずかにあるいてください。","example_meaning":"Em bé đang ngủ nên xin hãy đi nhẹ nhàng."},{"example":"彼は静かに部屋を出ていった。","example_reading":"かれはしずかにへやをでていった。","example_meaning":"Anh ấy lặng lẽ rời khỏi phòng."}],"level":"a1"},
{"word":"飛躍的に","reading":"ひやくてきに","meaning":"một cách nhảy vọt","hanviet":"phi dược đích","antonym":"緩やかに（ゆるやかに）: chậm rãi / 徐々に（じょじょに）: dần dần","antonym_hanviet":"hoãn / từ từ","note":"Dạng に. Hay đi với 向上する, 増える, 発展する.","example":"インターネットの普及で、情報量は飛躍的に増えた。","example_reading":"インターネットのふきゅうで、じょうほうりょうはひやくてきにふえた。","example_meaning":"Nhờ internet phổ biến, lượng thông tin đã tăng vọt.","examples":[{"example":"インターネットの普及で、情報量は飛躍的に増えた。","example_reading":"インターネットのふきゅうで、じょうほうりょうはひやくてきにふえた。","example_meaning":"Nhờ internet phổ biến, lượng thông tin đã tăng vọt."},{"example":"毎日練習を続けた結果、彼の技術は飛躍的に向上した。","example_reading":"まいにちれんしゅうをつづけたけっか、かれのぎじゅつはひやくてきにこうじょうした。","example_meaning":"Nhờ luyện tập đều mỗi ngày, kỹ thuật của anh ấy đã tiến bộ vượt bậc."}],"level":"a1"},
{"word":"網羅的に","reading":"もうらてきに","meaning":"một cách bao quát, đủ cả","hanviet":"võng la đích","antonym":"断片的に（だんぺんてきに）: rời rạc / 部分的に（ぶぶんてきに）: một phần","antonym_hanviet":"đoạn phiến đích / bộ phân đích","note":"Dạng に. Hay đi với 解説する, 集める, 調べる. Gồm đủ mọi mặt.","example":"この本は、日本の歴史を網羅的に解説している。","example_reading":"このほんは、にほんのれきしをもうらてきにかいせつしている。","example_meaning":"Cuốn sách này giải thích bao quát toàn bộ lịch sử Nhật Bản.","examples":[{"example":"この本は、日本の歴史を網羅的に解説している。","example_reading":"このほんは、にほんのれきしをもうらてきにかいせつしている。","example_meaning":"Cuốn sách này giải thích bao quát toàn bộ lịch sử Nhật Bản."},{"example":"関連する資料を網羅的に集めて、分析を始めた。","example_reading":"かんれんするしりょうをもうらてきにあつめて、ぶんせきをはじめた。","example_meaning":"Tôi thu thập đầy đủ tài liệu liên quan rồi bắt đầu phân tích."}],"level":"a1"},
{"word":"丁重に","reading":"ていちょうに","meaning":"một cách lễ độ, trang trọng","hanviet":"đinh trọng","antonym":"ぞんざいに: cẩu thả, thô lỗ / 乱暴に（らんぼうに）: thô bạo","antonym_hanviet":" / loạn bạo","note":"Dạng に. Hay đi với 扱う, 迎える, 断る.","example":"客は、丁重に迎えられて奥の部屋へ通された。","example_reading":"きゃくは、ていちょうにむかえられておくのへやへとおされた。","example_meaning":"Vị khách được đón tiếp trọng thị và dẫn vào phòng trong.","examples":[{"example":"客は、丁重に迎えられて奥の部屋へ通された。","example_reading":"きゃくは、ていちょうにむかえられておくのへやへとおされた。","example_meaning":"Vị khách được đón tiếp trọng thị và dẫn vào phòng trong."},{"example":"誘いは、丁重にお断りした。","example_reading":"さそいは、ていちょうにおことわりした。","example_meaning":"Tôi đã lịch sự từ chối lời mời."}],"level":"a1"},
{"word":"厳格に","reading":"げんかくに","meaning":"một cách nghiêm ngặt","hanviet":"nghiêm cách","antonym":"緩く（ゆるく）: lỏng lẻo / 寛大に（かんだいに）: khoan dung","antonym_hanviet":"hoãn / khoan đại","note":"Dạng に. Hay đi với 守る, 育てる, 管理する.","example":"この学校では、校則が厳格に守られている。","example_reading":"このがっこうでは、こうそくがげんかくにまもられている。","example_meaning":"Ở trường này nội quy được tuân thủ nghiêm ngặt.","examples":[{"example":"この学校では、校則が厳格に守られている。","example_reading":"このがっこうでは、こうそくがげんかくにまもられている。","example_meaning":"Ở trường này nội quy được tuân thủ nghiêm ngặt."},{"example":"父は私たちを厳格に育てた。","example_reading":"ちちはわたしたちをげんかくにそだてた。","example_meaning":"Bố tôi nuôi dạy chúng tôi rất nghiêm khắc."}],"level":"a1"},
{"word":"長期的に","reading":"ちょうきてきに","meaning":"về lâu dài","hanviet":"trường kỳ đích","antonym":"短期的に（たんきてきに）: ngắn hạn / 当面（とうめん）: trước mắt","antonym_hanviet":"đoản kỳ đích / đương diện","note":"Dạng に. Hay đi với 見る, 考える, 続ける. Trái nghĩa: 短期的に.","example":"長期的に見れば、この投資は利益になるはずだ。","example_reading":"ちょうきてきにみれば、このとうしはりえきになるはずだ。","example_meaning":"Xét về lâu dài thì khoản đầu tư này hẳn sẽ sinh lời.","examples":[{"example":"長期的に見れば、この投資は利益になるはずだ。","example_reading":"ちょうきてきにみれば、このとうしはりえきになるはずだ。","example_meaning":"Xét về lâu dài thì khoản đầu tư này hẳn sẽ sinh lời."},{"example":"病気を治すには、長期的に治療を続ける必要がある。","example_reading":"びょうきをなおすには、ちょうきてきにちりょうをつづけるひつようがある。","example_meaning":"Để chữa khỏi bệnh cần điều trị lâu dài."}],"level":"a1"},
{"word":"穏やかに","reading":"おだやかに","meaning":"hiền hòa, nhẹ nhàng, êm ả","hanviet":"ổn","antonym":"激しく（はげしく）: dữ dội / 辛辣に（しんらつに）: cay độc","antonym_hanviet":"kích / tân lạt","note":"Dạng に. Dùng cho cách nói chuyện, thời tiết, biển, tính cách.","example":"彼は穏やかに話す人です。","example_reading":"かれはおだやかにはなすひとです。","example_meaning":"Anh ấy là người nói chuyện nhẹ nhàng.","examples":[{"example":"彼は穏やかに話す人です。","example_reading":"かれはおだやかにはなすひとです。","example_meaning":"Anh ấy là người nói chuyện nhẹ nhàng."},{"example":"今日は海が穏やかに広がっている。","example_reading":"きょうはうみがおだやかにひろがっている。","example_meaning":"Hôm nay mặt biển trải rộng êm ả."}],"level":"a1"},
{"word":"規則的に","reading":"きそくてきに","meaning":"một cách đều đặn, có quy tắc","hanviet":"quy tắc đích","antonym":"不規則に（ふきそくに）: bất thường / 気まぐれに（きまぐれに）: thất thường","antonym_hanviet":"bất quy tắc / khí","note":"Dạng に. Hay đi với 運動する, 並ぶ, 繰り返す.","example":"規則的に運動することで、体調が整う。","example_reading":"きそくてきにうんどうすることで、たいちょうがととのう。","example_meaning":"Tập thể dục đều đặn sẽ giúp cơ thể khỏe hơn.","examples":[{"example":"規則的に運動することで、体調が整う。","example_reading":"きそくてきにうんどうすることで、たいちょうがととのう。","example_meaning":"Tập thể dục đều đặn sẽ giúp cơ thể khỏe hơn."},{"example":"木の葉が規則的に並んで生えている。","example_reading":"きのはがきそくてきにならんではえている。","example_meaning":"Lá cây mọc xếp thành hàng đều đặn."}],"level":"a1"},
{"word":"簡潔に","reading":"かんけつに","meaning":"một cách ngắn gọn, súc tích","hanviet":"giản khiết","antonym":"冗長に（じょうちょうに）: dài dòng / 詳しく（くわしく）: chi tiết / 詳細に（しょうさいに）: chi tiết","antonym_hanviet":"nhũng trưởng / tường / tường tế","note":"Dạng に. Hay đi với 述べる, まとめる, 書く.","example":"報告は、要点を簡潔にまとめてください。","example_reading":"ほうこくは、ようてんをかんけつにまとめてください。","example_meaning":"Xin hãy tóm gọn các điểm chính trong báo cáo.","examples":[{"example":"報告は、要点を簡潔にまとめてください。","example_reading":"ほうこくは、ようてんをかんけつにまとめてください。","example_meaning":"Xin hãy tóm gọn các điểm chính trong báo cáo."},{"example":"彼は質問に、簡潔に答えた。","example_reading":"かれはしつもんに、かんけつにこたえた。","example_meaning":"Anh ấy trả lời câu hỏi một cách ngắn gọn."}],"level":"a1"},
{"word":"鮮やかに","reading":"あざやかに","meaning":"rực rỡ, sống động; khéo léo","hanviet":"tiên","antonym":"地味に（じみに）: giản dị / くすんで: xỉn màu","antonym_hanviet":"địa vị / ","note":"Dạng に. Hai nghĩa: màu sắc rực rỡ, hoặc thao tác điêu luyện.","example":"桜が鮮やかに咲いています。","example_reading":"さくらがあざやかにさいています。","example_meaning":"Hoa anh đào nở rực rỡ.","examples":[{"example":"桜が鮮やかに咲いています。","example_reading":"さくらがあざやかにさいています。","example_meaning":"Hoa anh đào nở rực rỡ."},{"example":"彼は鮮やかにシュートを決めた。","example_reading":"かれはあざやかにシュートをきめた。","example_meaning":"Anh ấy ghi bàn một cách điêu luyện."}],"level":"a1"},
{"word":"部分的に","reading":"ぶぶんてきに","meaning":"một phần, từng phần","hanviet":"bộ phận đích","antonym":"全面的に（ぜんめんてきに）: toàn diện / 全体的に（ぜんたいてきに）: tổng thể / 包括的に（ほうかつてきに）: bao quát","antonym_hanviet":"toàn diện đích / toàn thể đích / bao quát đích","note":"Dạng に. Hay đi với 修正する, 認める, 賛成する. Trái nghĩa: 全体的に.","example":"契約書の内容を部分的に修正することになった。","example_reading":"けいやくしょのないようをぶぶんてきにしゅうせいすることになった。","example_meaning":"Đã quyết định chỉnh sửa một phần nội dung hợp đồng.","examples":[{"example":"契約書の内容を部分的に修正することになった。","example_reading":"けいやくしょのないようをぶぶんてきにしゅうせいすることになった。","example_meaning":"Đã quyết định chỉnh sửa một phần nội dung hợp đồng."},{"example":"彼の意見には部分的に賛成だ。","example_reading":"かれのいけんにはぶぶんてきにさんせいだ。","example_meaning":"Tôi đồng tình một phần với ý kiến của anh ấy."}],"level":"a1"},
{"word":"巧みに","reading":"たくみに","meaning":"khéo léo, điêu luyện","hanviet":"xảo","antonym":"下手に（へたに）: vụng về / 不器用に（ぶきように）: vụng về","antonym_hanviet":"hạ thủ / bất khí dụng","note":"Dạng に. Hay đi với 操る, 避ける, 使い分ける. Chỉ kỹ thuật cao.","example":"彼は三か国語を巧みに使い分ける。","example_reading":"かれはさんかこくごをたくみにつかいわける。","example_meaning":"Anh ấy dùng ba ngoại ngữ một cách điêu luyện.","examples":[{"example":"彼は三か国語を巧みに使い分ける。","example_reading":"かれはさんかこくごをたくみにつかいわける。","example_meaning":"Anh ấy dùng ba ngoại ngữ một cách điêu luyện."},{"example":"運転手は狭い道を巧みに通り抜けた。","example_reading":"うんてんしゅはせまいみちをたくみにとおりぬけた。","example_meaning":"Tài xế khéo léo lách qua con đường hẹp."}],"level":"a1"},
{"word":"滑らかに","reading":"なめらかに","meaning":"trơn tru, mượt mà","hanviet":"hoạt","antonym":"ぎこちなく: gượng gạo","note":"Dạng に. Dùng cho bề mặt, chuyển động, cách nói trôi chảy.","example":"この機械は滑らかに動きます。","example_reading":"このきかいはなめらかにうごきます。","example_meaning":"Cỗ máy này chạy trơn tru.","examples":[{"example":"この機械は滑らかに動きます。","example_reading":"このきかいはなめらかにうごきます。","example_meaning":"Cỗ máy này chạy trơn tru."},{"example":"彼は日本語を滑らかに話す。","example_reading":"かれはにほんごをなめらかにはなす。","example_meaning":"Anh ấy nói tiếng Nhật trôi chảy."}],"level":"a1"},
{"word":"公正に","reading":"こうせいに","meaning":"một cách công bằng, chính trực","hanviet":"công chính","antonym":"不公正に（ふこうせいに）: không công bằng / 不当に（ふとうに）: bất công","antonym_hanviet":"bất công chính / bất đương","note":"Dạng に. Hay đi với 評価する, 行う, 扱う.","example":"審査員は、すべての作品を公正に評価した。","example_reading":"しんさいんは、すべてのさくひんをこうせいにひょうかした。","example_meaning":"Giám khảo đánh giá mọi tác phẩm một cách công bằng.","examples":[{"example":"審査員は、すべての作品を公正に評価した。","example_reading":"しんさいんは、すべてのさくひんをこうせいにひょうかした。","example_meaning":"Giám khảo đánh giá mọi tác phẩm một cách công bằng."},{"example":"裁判は公正に行われなければならない。","example_reading":"さいばんはこうせいにおこなわれなければならない。","example_meaning":"Phiên tòa phải được tiến hành công bằng."}],"level":"a1"},
{"word":"重点的に","reading":"じゅうてんてきに","meaning":"một cách có trọng tâm","hanviet":"trọng điểm đích","antonym":"満遍なく（まんべんなく）: đồng đều / 均等に（きんとうに）: đều nhau","antonym_hanviet":"mãn biến / quân đẳng","note":"Dạng に. Hay đi với 復習する, 調べる, 取り組む.","example":"苦手な分野を重点的に復習することにした。","example_reading":"にがてなぶんやをじゅうてんてきにふくしゅうすることにした。","example_meaning":"Tôi quyết định ôn tập tập trung vào mảng mình yếu.","examples":[{"example":"苦手な分野を重点的に復習することにした。","example_reading":"にがてなぶんやをじゅうてんてきにふくしゅうすることにした。","example_meaning":"Tôi quyết định ôn tập tập trung vào mảng mình yếu."},{"example":"警察は、事件現場の周辺を重点的に調べている。","example_reading":"けいさつは、じけんげんばのしゅうへんをじゅうてんてきにしらべている。","example_meaning":"Cảnh sát đang điều tra trọng điểm khu vực quanh hiện trường."}],"level":"a1"},
{"word":"集中的に","reading":"しゅうちゅうてきに","meaning":"một cách tập trung","hanviet":"tập trung đích","antonym":"分散して（ぶんさんして）: phân tán / 散発的に（さんぱつてきに）: lẻ tẻ","antonym_hanviet":"phân tán / tán phát đích","note":"Dạng に. Hay đi với 勉強する, 降る, 行う. Dồn vào một thời gian hay địa điểm.","example":"試験の前に、集中的に勉強して知識を詰め込んだ。","example_reading":"しけんのまえに、しゅうちゅうてきにべんきょうしてちしきをつめこんだ。","example_meaning":"Trước kỳ thi, tôi học dồn dập để nhồi kiến thức.","examples":[{"example":"試験の前に、集中的に勉強して知識を詰め込んだ。","example_reading":"しけんのまえに、しゅうちゅうてきにべんきょうしてちしきをつめこんだ。","example_meaning":"Trước kỳ thi, tôi học dồn dập để nhồi kiến thức."},{"example":"大雨が、この地域に集中的に降った。","example_reading":"おおあめが、このちいきにしゅうちゅうてきにふった。","example_meaning":"Mưa lớn tập trung đổ xuống khu vực này."}],"level":"a1"},
{"word":"持続的に","reading":"じぞくてきに","meaning":"một cách bền vững, liên tục","hanviet":"trì tục đích","antonym":"一時的に（いちじてきに）: tạm thời / 断続的に（だんぞくてきに）: gián đoạn","antonym_hanviet":"nhất thời đích / đoạn tục đích","note":"Dạng に. Hay đi với 成長する, 発展する, 利益を生む.","example":"持続的に成長できる社会を作ることが目標だ。","example_reading":"じぞくてきにせいちょうできるしゃかいをつくることがもくひょうだ。","example_meaning":"Mục tiêu là xây dựng một xã hội có thể phát triển bền vững.","examples":[{"example":"持続的に成長できる社会を作ることが目標だ。","example_reading":"じぞくてきにせいちょうできるしゃかいをつくることがもくひょうだ。","example_meaning":"Mục tiêu là xây dựng một xã hội có thể phát triển bền vững."},{"example":"この事業は、持続的に利益を生み出す仕組みになっている。","example_reading":"このじぎょうは、じぞくてきにりえきをうみだすしくみになっている。","example_meaning":"Dự án này có cơ chế tạo ra lợi nhuận liên tục."}],"level":"a1"},
{"word":"柔軟に","reading":"じゅうなんに","meaning":"một cách linh hoạt, mềm dẻo","hanviet":"nhu nhuyễn","antonym":"硬直的に（こうちょくてきに）: cứng nhắc / 頑固に（がんこに）: bướng bỉnh","antonym_hanviet":"ngạnh trực đích / ngoan cố","note":"Dạng に. Hay đi với 対応する, 考える, 変える. Hay dùng trong công việc.","example":"状況に合わせて、柔軟に対応することが求められる。","example_reading":"じょうきょうにあわせて、じゅうなんにたいおうすることがもとめられる。","example_meaning":"Cần ứng phó linh hoạt theo tình huống.","examples":[{"example":"状況に合わせて、柔軟に対応することが求められる。","example_reading":"じょうきょうにあわせて、じゅうなんにたいおうすることがもとめられる。","example_meaning":"Cần ứng phó linh hoạt theo tình huống."},{"example":"若い人は新しい考え方を柔軟に受け入れやすい。","example_reading":"わかいひとはあたらしいかんがえかたをじゅうなんにうけいれやすい。","example_meaning":"Người trẻ dễ tiếp nhận cách nghĩ mới một cách linh hoạt."}],"level":"a1"},
{"word":"反射的に","reading":"はんしゃてきに","meaning":"theo phản xạ","hanviet":"phản xạ đích","antonym":"熟考して（じゅっこうして）: suy nghĩ kỹ / 意識的に（いしきてきに）: có ý thức","antonym_hanviet":"thục khảo / ý thức đích","note":"Dạng に. Hay đi với 避ける, 謝る, 手を出す. Hành động ngay không kịp nghĩ.","example":"ボールが飛んできて、反射的に顔をかばった。","example_reading":"ボールがとんできて、はんしゃてきにかおをかばった。","example_meaning":"Bóng bay tới, tôi theo phản xạ che mặt lại.","examples":[{"example":"ボールが飛んできて、反射的に顔をかばった。","example_reading":"ボールがとんできて、はんしゃてきにかおをかばった。","example_meaning":"Bóng bay tới, tôi theo phản xạ che mặt lại."},{"example":"大きな音がして、反射的に振り返った。","example_reading":"おおきなおとがして、はんしゃてきにふりかえった。","example_meaning":"Có tiếng động lớn, tôi quay lại theo phản xạ."}],"level":"a1"},
{"word":"段階的に","reading":"だんかいてきに","meaning":"từng giai đoạn, từng bước","hanviet":"đoạn giai đích","antonym":"一気に（いっきに）: một mạch / 一挙に（いっきょに）: một lần","antonym_hanviet":"nhất khí / nhất cử","note":"Dạng に. Hay đi với 進める, 緩和する, 導入する.","example":"規制は段階的に緩和されていく予定だ。","example_reading":"きせいはだんかいてきにかんわされていくよていだ。","example_meaning":"Dự định các quy định sẽ được nới lỏng dần theo từng giai đoạn.","examples":[{"example":"規制は段階的に緩和されていく予定だ。","example_reading":"きせいはだんかいてきにかんわされていくよていだ。","example_meaning":"Dự định các quy định sẽ được nới lỏng dần theo từng giai đoạn."},{"example":"新しいシステムは、段階的に導入していきます。","example_reading":"あたらしいシステムは、だんかいてきにどうにゅうしていきます。","example_meaning":"Hệ thống mới sẽ được đưa vào từng bước."}],"level":"a1"},
{"word":"円満に","reading":"えんまんに","meaning":"một cách hòa thuận, êm đẹp","hanviet":"viên mãn","antonym":"険悪に（けんあくに）: căng thẳng","antonym_hanviet":"hiểm ác","note":"Dạng に. Hay đi với 解決する, 終わる, 別れる.","example":"話し合いの結果、問題は円満に解決した。","example_reading":"はなしあいのけっか、もんだいはえんまんにかいけつした。","example_meaning":"Sau khi trao đổi, vấn đề đã được giải quyết êm đẹp.","examples":[{"example":"話し合いの結果、問題は円満に解決した。","example_reading":"はなしあいのけっか、もんだいはえんまんにかいけつした。","example_meaning":"Sau khi trao đổi, vấn đề đã được giải quyết êm đẹp."},{"example":"二人は円満に離婚し、今も友人として付き合っている。","example_reading":"ふたりはえんまんにりこんし、いまもゆうじんとしてつきあっている。","example_meaning":"Hai người ly hôn êm thấm và giờ vẫn giữ quan hệ bạn bè."}],"level":"a1"},
{"word":"万全に","reading":"ばんぜんに","meaning":"một cách vạn toàn, chu đáo","hanviet":"vạn toàn","antonym":"不十分に（ふじゅうぶんに）: chưa đầy đủ / 手薄に（てうすに）: sơ sài","antonym_hanviet":"bất thập phân / thủ bạc","note":"Dạng に. Hay đi với 備える, 整える, する. Chuẩn bị không thiếu sót.","example":"台風に備えて、対策を万全に整えた。","example_reading":"たいふうにそなえて、たいさくをばんぜんにととのえた。","example_meaning":"Để chuẩn bị cho bão, chúng tôi đã sắp xếp đối sách chu đáo.","examples":[{"example":"台風に備えて、対策を万全に整えた。","example_reading":"たいふうにそなえて、たいさくをばんぜんにととのえた。","example_meaning":"Để chuẩn bị cho bão, chúng tôi đã sắp xếp đối sách chu đáo."},{"example":"体調を万全にして、試験に臨みたい。","example_reading":"たいちょうをばんぜんにして、しけんにのぞみたい。","example_meaning":"Tôi muốn giữ sức khỏe thật tốt để bước vào kỳ thi."}],"level":"a1"},
{"word":"丹念に","reading":"たんねんに","meaning":"một cách tỉ mỉ, công phu","hanviet":"đan niệm","antonym":"雑に（ざつに）: cẩu thả / 適当に（てきとうに）: qua loa","antonym_hanviet":"tạp / thích đương","note":"Dạng に. Hay đi với 磨く, 調べる, 作る.","example":"職人は、一つ一つ丹念に器を磨いている。","example_reading":"しょくにんは、ひとつひとつたんねんにうつわをみがいている。","example_meaning":"Người thợ mài từng chiếc bát một cách tỉ mỉ.","examples":[{"example":"職人は、一つ一つ丹念に器を磨いている。","example_reading":"しょくにんは、ひとつひとつたんねんにうつわをみがいている。","example_meaning":"Người thợ mài từng chiếc bát một cách tỉ mỉ."},{"example":"彼女は古い資料を丹念に調べて、論文を書いた。","example_reading":"かのじょはふるいしりょうをたんねんにしらべて、ろんぶんをかいた。","example_meaning":"Cô ấy tra cứu tài liệu cũ kỹ lưỡng rồi viết luận văn."}],"level":"a1"},
{"word":"不自然に","reading":"ふしぜんに","meaning":"một cách không tự nhiên, gượng gạo","hanviet":"bất tự nhiên","antonym":"自然に（しぜんに）: tự nhiên","antonym_hanviet":"tự nhiên","note":"Dạng に. Hay đi với 笑う, 見える, 途切れる.","example":"彼女は不自然に明るく振る舞っていた。","example_reading":"かのじょはふしぜんにあかるくふるまっていた。","example_meaning":"Cô ấy cư xử vui vẻ một cách gượng gạo.","examples":[{"example":"彼女は不自然に明るく振る舞っていた。","example_reading":"かのじょはふしぜんにあかるくふるまっていた。","example_meaning":"Cô ấy cư xử vui vẻ một cách gượng gạo."},{"example":"二人の会話が、不自然に途切れた。","example_reading":"ふたりのかいわが、ふしぜんにとぎれた。","example_meaning":"Cuộc trò chuyện của hai người bỗng đứt quãng một cách kỳ lạ."}],"level":"a1"},
{"word":"爽やかに","reading":"さわやかに","meaning":"sảng khoái, tươi mát, dễ chịu","hanviet":"sảng","antonym":"重苦しく（おもくるしく）: nặng nề, ngột ngạt","antonym_hanviet":"trọng khổ","note":"Dạng に. Hay đi với 笑う, 挨拶する, 吹く. Gợi cảm giác trong lành.","example":"彼は爽やかに笑って、手を振った。","example_reading":"かれはさわやかにわらって、てをふった。","example_meaning":"Anh ấy cười tươi rồi vẫy tay.","examples":[{"example":"彼は爽やかに笑って、手を振った。","example_reading":"かれはさわやかにわらって、てをふった。","example_meaning":"Anh ấy cười tươi rồi vẫy tay."},{"example":"朝の風が爽やかに吹いている。","example_reading":"あさのかぜがさわやかにふいている。","example_meaning":"Gió buổi sáng thổi mát lành."}],"level":"a1"},
{"word":"賑やかに","reading":"にぎやかに","meaning":"rộn ràng, náo nhiệt, vui nhộn","hanviet":"chẩn","note":"Dạng に. Nghĩa tích cực: nhiều người, nhiều âm thanh vui vẻ.","antonym":"静かに（しずかに）: yên lặng / 厳粛に（げんしゅくに）: trang nghiêm","antonym_hanviet":"tĩnh / nghiêm túc","example":"子供たちが賑やかに遊んでいます。","example_reading":"こどもたちがにぎやかにあそんでいます。","example_meaning":"Bọn trẻ đang chơi đùa náo nhiệt.","examples":[{"example":"子供たちが賑やかに遊んでいます。","example_reading":"こどもたちがにぎやかにあそんでいます。","example_meaning":"Bọn trẻ đang chơi đùa náo nhiệt."},{"example":"家族みんなで賑やかに新年を迎えた。","example_reading":"かぞくみんなでにぎやかにしんねんをむかえた。","example_meaning":"Cả nhà rộn ràng đón năm mới."}],"level":"a1"},
{"word":"断続的に","reading":"だんぞくてきに","meaning":"một cách gián đoạn, lúc có lúc không","hanviet":"đoạn tục đích","antonym":"連続的に（れんぞくてきに）: liên tục / 絶え間なく（たえまなく）: không ngừng / 脈々と（みゃくみゃくと）: liên tục","antonym_hanviet":"liên tục đích / tuyệt gian / mạch mạch","note":"Dạng に. Hay đi với 降る, 続く, 痛む.","example":"夜中から、断続的に雨が降っている。","example_reading":"よなかから、だんぞくてきにあめがふっている。","example_meaning":"Từ nửa đêm, mưa rơi lúc có lúc không.","examples":[{"example":"夜中から、断続的に雨が降っている。","example_reading":"よなかから、だんぞくてきにあめがふっている。","example_meaning":"Từ nửa đêm, mưa rơi lúc có lúc không."},{"example":"頭痛が断続的に続いて、仕事に集中できない。","example_reading":"ずつうがだんぞくてきにつづいて、しごとにしゅうちゅうできない。","example_meaning":"Đau đầu kéo dài từng đợt nên tôi không tập trung làm việc được."}],"level":"a1"},
{"word":"暫定的に","reading":"ざんていてきに","meaning":"một cách tạm thời","hanviet":"tạm định đích","antonym":"恒久的に（こうきゅうてきに）: lâu dài / 最終的に（さいしゅうてきに）: cuối cùng","antonym_hanviet":"hằng cửu đích / tối chung đích","note":"Dạng に. Hay đi với 決める, 適用する, 引き継ぐ.","example":"新しい規則は、暫定的に来月から適用される。","example_reading":"あたらしいきそくは、ざんていてきにらいげつからてきようされる。","example_meaning":"Quy tắc mới sẽ được áp dụng tạm thời từ tháng sau.","examples":[{"example":"新しい規則は、暫定的に来月から適用される。","example_reading":"あたらしいきそくは、ざんていてきにらいげつからてきようされる。","example_meaning":"Quy tắc mới sẽ được áp dụng tạm thời từ tháng sau."},{"example":"担当者が決まるまで、私が暫定的に仕事を引き継ぐ。","example_reading":"たんとうしゃがきまるまで、わたしがざんていてきにしごとをひきつぐ。","example_meaning":"Cho đến khi chọn được người phụ trách, tôi tạm thời tiếp quản công việc."}],"level":"a1"},
{"word":"迅速に","reading":"じんそくに","meaning":"một cách nhanh chóng, mau lẹ","hanviet":"tấn tốc","antonym":"緩慢に（かんまんに）: chậm chạp / ゆっくり: chậm rãi","antonym_hanviet":"hoãn mạn / ","note":"Dạng に. Hay đi với 対応する, 処理する, 行動する. Trang trọng, hay gặp trong thông báo.","example":"災害が起きたら、迅速に情報を伝えることが重要だ。","example_reading":"さいがいがおきたら、じんそくにじょうほうをつたえることがじゅうようだ。","example_meaning":"Khi có thiên tai, truyền đạt thông tin nhanh chóng là rất quan trọng.","examples":[{"example":"災害が起きたら、迅速に情報を伝えることが重要だ。","example_reading":"さいがいがおきたら、じんそくにじょうほうをつたえることがじゅうようだ。","example_meaning":"Khi có thiên tai, truyền đạt thông tin nhanh chóng là rất quan trọng."},{"example":"お客様からの苦情に迅速に対応いたします。","example_reading":"おきゃくさまからのくじょうにじんそくにたいおういたします。","example_meaning":"Chúng tôi sẽ xử lý nhanh chóng khiếu nại của quý khách."}],"level":"a1"},
{"word":"豊かに","reading":"ゆたかに","meaning":"phong phú, dồi dào, sung túc","hanviet":"phong","antonym":"貧しく（まずしく）: nghèo nàn","antonym_hanviet":"bần","note":"Dạng に. Hay đi với 暮らす, 育つ, 表現する, 実る.","example":"この地域では、人々が豊かに暮らしている。","example_reading":"このちいきでは、ひとびとがゆたかにくらしている。","example_meaning":"Ở khu vực này mọi người sống sung túc.","examples":[{"example":"この地域では、人々が豊かに暮らしている。","example_reading":"このちいきでは、ひとびとがゆたかにくらしている。","example_meaning":"Ở khu vực này mọi người sống sung túc."},{"example":"子どもの感情を豊かに育てることが大切だ。","example_reading":"こどものかんじょうをゆたかにそだてることがたいせつだ。","example_meaning":"Nuôi dưỡng cảm xúc phong phú cho trẻ là điều quan trọng."}],"level":"a1"},
{"word":"華やかに","reading":"はなやかに","meaning":"lộng lẫy, rực rỡ, hoa lệ","hanviet":"hoa","antonym":"地味に（じみに）: giản dị, kín đáo","antonym_hanviet":"địa vị","note":"Dạng に. Hay đi với 飾る, 着飾る, 彩る.","example":"会場は華やかに飾られていました。","example_reading":"かいじょうははなやかにかざられていました。","example_meaning":"Hội trường được trang trí lộng lẫy.","examples":[{"example":"会場は華やかに飾られていました。","example_reading":"かいじょうははなやかにかざられていました。","example_meaning":"Hội trường được trang trí lộng lẫy."},{"example":"彼女は華やかにドレスを着こなしていた。","example_reading":"かのじょははなやかにドレスをきこなしていた。","example_meaning":"Cô ấy mặc chiếc váy một cách lộng lẫy."}],"level":"a1"},
{"word":"強引に","reading":"ごういんに","meaning":"một cách cưỡng ép, bất chấp","hanviet":"cưỡng dẫn","antonym":"穏便に（おんびんに）: êm thấm / 自然に（しぜんに）: tự nhiên","antonym_hanviet":"ổn tiện / tự nhiên","note":"Dạng に. Hay đi với 誘う, 進める, 押し切る. Làm bằng sức ép, bỏ qua ý người khác.","example":"彼は嫌がる私を強引に車に乗せた。","example_reading":"かれはいやがるわたしをごういんにくるまにのせた。","example_meaning":"Anh ta ép tôi lên xe dù tôi không muốn.","examples":[{"example":"彼は嫌がる私を強引に車に乗せた。","example_reading":"かれはいやがるわたしをごういんにくるまにのせた。","example_meaning":"Anh ta ép tôi lên xe dù tôi không muốn."},{"example":"反対意見があったのに、部長は計画を強引に進めた。","example_reading":"はんたいいけんがあったのに、ぶちょうはけいかくをごういんにすすめた。","example_meaning":"Dù có ý kiến phản đối, trưởng phòng vẫn cưỡng ép tiến hành kế hoạch."}],"level":"a1"},
{"word":"抜本的に","reading":"ばっぽんてきに","meaning":"một cách triệt để, từ gốc","hanviet":"bạt bản đích","antonym":"部分的に（ぶぶんてきに）: một phần / 表面的に（ひょうめんてきに）: bề ngoài","antonym_hanviet":"bộ phân đích / biểu diện đích","note":"Dạng に. Hay đi với 見直す, 改革する, 改善する. Sửa tận gốc chứ không vá víu.","example":"会社は営業の仕組みを抜本的に見直すことにした。","example_reading":"かいしゃはえいぎょうのしくみをばっぽんてきにみなおすことにした。","example_meaning":"Công ty quyết định xem xét lại triệt để cơ chế kinh doanh.","examples":[{"example":"会社は営業の仕組みを抜本的に見直すことにした。","example_reading":"かいしゃはえいぎょうのしくみをばっぽんてきにみなおすことにした。","example_meaning":"Công ty quyết định xem xét lại triệt để cơ chế kinh doanh."},{"example":"問題を解決するには、制度を抜本的に改革する必要がある。","example_reading":"もんだいをかいけつするには、せいどをばっぽんてきにかいかくするひつようがある。","example_meaning":"Để giải quyết vấn đề cần cải cách chế độ từ gốc."}],"level":"a1"},
{"word":"平穏に","reading":"へいおんに","meaning":"một cách yên ổn, bình lặng","hanviet":"bình ổn","antonym":"騒然と（そうぜんと）: nhốn nháo","antonym_hanviet":"tao nhiên","note":"Dạng に. Hay đi với 暮らす, 過ごす, 終わる.","example":"退職後は、田舎で平穏に暮らしたい。","example_reading":"たいしょくごは、いなかでへいおんにくらしたい。","example_meaning":"Sau khi nghỉ hưu, tôi muốn sống yên bình ở quê.","examples":[{"example":"退職後は、田舎で平穏に暮らしたい。","example_reading":"たいしょくごは、いなかでへいおんにくらしたい。","example_meaning":"Sau khi nghỉ hưu, tôi muốn sống yên bình ở quê."},{"example":"祭りは平穏に終わり、大きな問題はなかった。","example_reading":"まつりはへいおんにおわり、おおきなもんだいはなかった。","example_meaning":"Lễ hội kết thúc yên ổn, không có vấn đề lớn."}],"level":"a1"},
{"word":"消極的に","reading":"しょうきょくてきに","meaning":"một cách tiêu cực, thụ động","hanviet":"tiêu cực đích","antonym":"積極的に（せっきょくてきに）: tích cực / 活発に（かっぱつに）: sôi nổi","antonym_hanviet":"tích cực đích / hoạt phát","note":"Dạng に. Hay đi với 対応する, 参加する, 取り組む. Trái nghĩa: 積極的に.","example":"彼は新しい仕事に消極的に取り組んでいる。","example_reading":"かれはあたらしいしごとにしょうきょくてきにとりくんでいる。","example_meaning":"Anh ấy làm công việc mới một cách thụ động.","examples":[{"example":"彼は新しい仕事に消極的に取り組んでいる。","example_reading":"かれはあたらしいしごとにしょうきょくてきにとりくんでいる。","example_meaning":"Anh ấy làm công việc mới một cách thụ động."},{"example":"失敗が怖くて、消極的に行動してしまう。","example_reading":"しっぱいがこわくて、しょうきょくてきにこうどうしてしまう。","example_meaning":"Vì sợ thất bại nên tôi hành động rụt rè."}],"level":"a1"},
{"word":"緩やかに","reading":"ゆるやかに","meaning":"thoai thoải, từ từ, chậm rãi","hanviet":"hoãn","antonym":"急激に（きゅうげきに）: đột ngột, nhanh chóng / 劇的に（げきてきに）: kịch tính / 飛躍的に（ひやくてきに）: nhảy vọt","antonym_hanviet":"cấp kích / kịch đích / phi dược đích","note":"Dạng に. Dùng cho dốc, dòng chảy, quy định hoặc biến đổi nhẹ.","example":"川は緩やかに流れています。","example_reading":"かわはゆるやかにながれています。","example_meaning":"Con sông chảy chậm rãi.","examples":[{"example":"川は緩やかに流れています。","example_reading":"かわはゆるやかにながれています。","example_meaning":"Con sông chảy chậm rãi."},{"example":"この道は緩やかに坂になっている。","example_reading":"このみちはゆるやかにさかになっている。","example_meaning":"Con đường này dốc thoai thoải."}],"level":"a1"},
{"word":"正確に","reading":"せいかくに","meaning":"một cách chính xác, đúng đắn","hanviet":"chính xác","antonym":"不正確に（ふせいかくに）: không chính xác / 大雑把に（おおざっぱに）: đại khái / 大体（だいたい）: Đại khái","antonym_hanviet":"bất chính xác / đại tạp bả / đại thể","note":"Dạng に. Hay đi với 伝える, 測る, 覚える, 答える. Thiên về không sai số.","example":"質問には正確に答えてください。","example_reading":"しつもんにはせいかくにこたえてください。","example_meaning":"Hãy trả lời câu hỏi một cách chính xác.","examples":[{"example":"質問には正確に答えてください。","example_reading":"しつもんにはせいかくにこたえてください。","example_meaning":"Hãy trả lời câu hỏi một cách chính xác."},{"example":"時間を正確に測るために、専用の時計を使っている。","example_reading":"じかんをせいかくにはかるために、せんようのとけいをつかっている。","example_meaning":"Tôi dùng đồng hồ chuyên dụng để đo thời gian cho chính xác."}],"level":"a1"},
{"word":"勤勉に","reading":"きんべんに","meaning":"một cách cần cù, chăm chỉ","hanviet":"cần miễn","antonym":"怠惰に（たいだに）: lười biếng / 怠けて（なまけて）: lười","antonym_hanviet":"đãi nọa / đãi","note":"Dạng に. Hay đi với 働く, 学ぶ, 生きる.","example":"彼は毎日、勤勉に働いて家族を養っている。","example_reading":"かれはまいにち、きんべんにはたらいてかぞくをやしなっている。","example_meaning":"Anh ấy làm việc cần cù mỗi ngày để nuôi gia đình.","examples":[{"example":"彼は毎日、勤勉に働いて家族を養っている。","example_reading":"かれはまいにち、きんべんにはたらいてかぞくをやしなっている。","example_meaning":"Anh ấy làm việc cần cù mỗi ngày để nuôi gia đình."},{"example":"日本人は勤勉に学ぶ国民だと言われてきた。","example_reading":"にほんじんはきんべんにまなぶこくみんだといわれてきた。","example_meaning":"Người Nhật từ lâu được cho là dân tộc chăm chỉ học tập."}],"level":"a1"},
{"word":"必然的に","reading":"ひつぜんてきに","meaning":"một cách tất yếu","hanviet":"tất nhiên đích","antonym":"偶然に（ぐうぜんに）: tình cờ","antonym_hanviet":"ngẫu nhiên","note":"Dạng に. Hay đi với なる, 高まる, 起こる.","example":"人口が増えれば、必然的に住宅の需要も高まる。","example_reading":"じんこうがふえれば、ひつぜんてきにじゅうたくのじゅようもたかまる。","example_meaning":"Dân số tăng thì tất yếu nhu cầu nhà ở cũng tăng.","examples":[{"example":"人口が増えれば、必然的に住宅の需要も高まる。","example_reading":"じんこうがふえれば、ひつぜんてきにじゅうたくのじゅようもたかまる。","example_meaning":"Dân số tăng thì tất yếu nhu cầu nhà ở cũng tăng."},{"example":"努力を続けた結果、必然的にこの結果にたどり着いた。","example_reading":"どりょくをつづけたけっか、ひつぜんてきにこのけっかにたどりついた。","example_meaning":"Nhờ kiên trì nỗ lực, tất yếu đã đạt đến kết quả này."}],"level":"a1"},
{"word":"円滑に","reading":"えんかつに","meaning":"một cách trôi chảy, suôn sẻ","hanviet":"viên hoạt","antonym":"滞って（とどこおって）: ứ đọng / 難航して（なんこうして）: gặp khó khăn","antonym_hanviet":"trệ / nạn hàng","note":"Dạng に. Hay đi với 進む, 進める, 運営する. Văn viết, trang trọng.","example":"会議が円滑に進むように、資料を事前に配った。","example_reading":"かいぎがえんかつにすすむように、しりょうをじぜんにくばった。","example_meaning":"Tôi phát tài liệu trước để cuộc họp diễn ra suôn sẻ.","examples":[{"example":"会議が円滑に進むように、資料を事前に配った。","example_reading":"かいぎがえんかつにすすむように、しりょうをじぜんにくばった。","example_meaning":"Tôi phát tài liệu trước để cuộc họp diễn ra suôn sẻ."},{"example":"人間関係を円滑にするには、あいさつが大切だ。","example_reading":"にんげんかんけいをえんかつにするには、あいさつがたいせつだ。","example_meaning":"Để quan hệ giữa người với người trôi chảy, lời chào hỏi rất quan trọng."}],"level":"a1"},
{"word":"的確に","reading":"てきかくに","meaning":"chính xác, đúng trọng tâm","hanviet":"đích xác","antonym":"的外れに（まとはずれに）: lạc đề, trật mục tiêu","antonym_hanviet":"đích ngoại","note":"Dạng に. Hay đi với 答える, 判断する, 指示する.","example":"質問に的確に答えてください。","example_reading":"しつもんにてきかくにこたえてください。","example_meaning":"Hãy trả lời đúng trọng tâm câu hỏi.","examples":[{"example":"質問に的確に答えてください。","example_reading":"しつもんにてきかくにこたえてください。","example_meaning":"Hãy trả lời đúng trọng tâm câu hỏi."},{"example":"彼は状況を的確に判断した。","example_reading":"かれはじょうきょうをてきかくにはんだんした。","example_meaning":"Anh ấy đã phán đoán tình hình một cách chính xác."}],"level":"a1"},
{"word":"積極的に","reading":"せっきょくてきに","meaning":"một cách tích cực, chủ động","hanviet":"tích cực đích","note":"Dạng 的に. Hay đi với 参加する, 発言する, 取り組む. Trái nghĩa: 消極的に.","antonym":"消極的に（しょうきょくてきに）: tiêu cực","antonym_hanviet":"tiêu cực đích","example":"会議では積極的に意見を言うようにしている。","example_reading":"かいぎではせっきょくてきにいけんをいうようにしている。","example_meaning":"Trong cuộc họp tôi cố gắng chủ động phát biểu ý kiến.","examples":[{"example":"会議では積極的に意見を言うようにしている。","example_reading":"かいぎではせっきょくてきにいけんをいうようにしている。","example_meaning":"Trong cuộc họp tôi cố gắng chủ động phát biểu ý kiến."},{"example":"学生たちは地域の活動に積極的に参加している。","example_reading":"がくせいたちはちいきのかつどうにせっきょくてきにさんかしている。","example_meaning":"Sinh viên tích cực tham gia hoạt động của địa phương."}],"level":"a1"},
{"word":"徹底的に","reading":"てっていてきに","meaning":"triệt để, đến nơi đến chốn","hanviet":"triệt để đích","antonym":"中途半端に（ちゅうとはんぱに）: nửa vời / 一応（いちおう）: tạm","antonym_hanviet":"trung đồ bán đoan / nhất ứng","note":"Dạng 的に. Hay đi với 調べる, 掃除する, 話し合う.","example":"事故の原因を徹底的に調べる必要がある。","example_reading":"じこのげんいんをてっていてきにしらべるひつようがある。","example_meaning":"Cần điều tra triệt để nguyên nhân tai nạn.","examples":[{"example":"事故の原因を徹底的に調べる必要がある。","example_reading":"じこのげんいんをてっていてきにしらべるひつようがある。","example_meaning":"Cần điều tra triệt để nguyên nhân tai nạn."},{"example":"週末に部屋を徹底的に掃除した。","example_reading":"しゅうまつにへやをてっていてきにそうじした。","example_meaning":"Cuối tuần tôi đã dọn phòng thật kỹ."}],"level":"a1"},
{"word":"克明に","reading":"こくめいに","meaning":"một cách tỉ mỉ, rõ từng chi tiết","hanviet":"khắc minh","antonym":"大まかに（おおまかに）: đại khái","antonym_hanviet":"đại","note":"Dạng に. Hay đi với 記録する, 描く, 覚えている. Ghi nhớ hoặc miêu tả rất rõ từng điểm nhỏ.","example":"彼は戦争の体験を克明に日記に書き残した。","example_reading":"かれはせんそうのたいけんをこくめいににっきにかきのこした。","example_meaning":"Anh ấy đã ghi lại tỉ mỉ trải nghiệm chiến tranh trong nhật ký.","examples":[{"example":"彼は戦争の体験を克明に日記に書き残した。","example_reading":"かれはせんそうのたいけんをこくめいににっきにかきのこした。","example_meaning":"Anh ấy đã ghi lại tỉ mỉ trải nghiệm chiến tranh trong nhật ký."},{"example":"十年前の事故のことを、今でも克明に覚えている。","example_reading":"じゅうねんまえのじこのことを、いまでもこくめいにおぼえている。","example_meaning":"Tôi vẫn nhớ rõ từng chi tiết vụ tai nạn mười năm trước."}],"level":"a1"},
{"word":"綿密に","reading":"めんみつに","meaning":"một cách tỉ mỉ, kỹ lưỡng","hanviet":"miên mật","antonym":"大雑把に（おおざっぱに）: đại khái / ずさんに: cẩu thả","antonym_hanviet":"đại tạp bả / ","note":"Dạng に. Hay đi với 計画する, 調べる, 打ち合わせる.","example":"旅行の日程を綿密に計画した。","example_reading":"りょこうのにっていをめんみつにけいかくした。","example_meaning":"Tôi đã lên kế hoạch lịch trình chuyến đi rất tỉ mỉ.","examples":[{"example":"旅行の日程を綿密に計画した。","example_reading":"りょこうのにっていをめんみつにけいかくした。","example_meaning":"Tôi đã lên kế hoạch lịch trình chuyến đi rất tỉ mỉ."},{"example":"事件の現場は、警察が綿密に調べている。","example_reading":"じけんのげんばは、けいさつがめんみつにしらべている。","example_meaning":"Hiện trường vụ án đang được cảnh sát điều tra kỹ lưỡng."}],"level":"a1"},
{"word":"軽率に","reading":"けいそつに","meaning":"một cách khinh suất, hấp tấp","hanviet":"khinh suất","antonym":"慎重に（しんちょうに）: thận trọng / 堅実に（けんじつに）: chắc chắn","antonym_hanviet":"thận trọng / kiên thực","note":"Dạng に. Hay đi với 行動する, 判断する, 発言する.","example":"軽率に人を信じると、後で痛い目にあうこともある。","example_reading":"けいそつにひとをしんじると、あとでいたいめにあうこともある。","example_meaning":"Tin người một cách khinh suất, đôi khi sau này sẽ chịu thiệt.","examples":[{"example":"軽率に人を信じると、後で痛い目にあうこともある。","example_reading":"けいそつにひとをしんじると、あとでいたいめにあうこともある。","example_meaning":"Tin người một cách khinh suất, đôi khi sau này sẽ chịu thiệt."},{"example":"事情を知らずに軽率に発言したことを、後悔している。","example_reading":"じじょうをしらずにけいそつにはつげんしたことを、こうかいしている。","example_meaning":"Tôi hối hận vì đã phát ngôn hấp tấp khi chưa biết tình hình."}],"level":"a1"},
{"word":"切実に","reading":"せつじつに","meaning":"một cách tha thiết, cấp bách","hanviet":"thiết thực","antonym":"他人事のように（ひとごとのように）: như chuyện người khác","antonym_hanviet":"tha nhân sự","note":"Dạng に. Hay đi với 願う, 感じる, 訴える.","example":"被災者は、一日も早い復旧を切実に願っている。","example_reading":"ひさいしゃは、いちにちもはやいふっきゅうをせつじつにねがっている。","example_meaning":"Người bị nạn tha thiết mong sớm được khôi phục.","examples":[{"example":"被災者は、一日も早い復旧を切実に願っている。","example_reading":"ひさいしゃは、いちにちもはやいふっきゅうをせつじつにねがっている。","example_meaning":"Người bị nạn tha thiết mong sớm được khôi phục."},{"example":"人手不足の問題を、現場の人は切実に感じている。","example_reading":"ひとでぶそくのもんだいを、げんばのひとはせつじつにかんじている。","example_meaning":"Những người ở hiện trường cảm nhận rất cấp bách vấn đề thiếu nhân lực."}],"level":"a1"},
{"word":"如実に","reading":"にょじつに","meaning":"một cách rõ ràng, phản ánh đúng thực tế","hanviet":"như thực","note":"Dạng に. Hay đi với 表れる, 示す, 物語る. Văn viết.","example":"数字は景気の悪化を如実に示している。","example_reading":"すうじはけいきのあっかをにょじつにしめしている。","example_meaning":"Con số cho thấy rõ sự xấu đi của nền kinh tế.","examples":[{"example":"数字は景気の悪化を如実に示している。","example_reading":"すうじはけいきのあっかをにょじつにしめしている。","example_meaning":"Con số cho thấy rõ sự xấu đi của nền kinh tế."},{"example":"彼の表情には、不安が如実に表れていた。","example_reading":"かれのひょうじょうには、ふあんがにょじつにあらわれていた。","example_meaning":"Nỗi bất an hiện rõ trên nét mặt anh ấy."}],"level":"a1"},
{"word":"辛辣に","reading":"しんらつに","meaning":"một cách cay độc, gay gắt","hanviet":"tân lạt","antonym":"優しく（やさしく）: dịu dàng / 穏やかに（おだやかに）: hiền hòa","antonym_hanviet":"ưu / ổn","note":"Dạng に. Hay đi với 批判する, 指摘する, 言う.","example":"その批評家は、新作を辛辣に批判した。","example_reading":"そのひひょうかは、しんさくをしんらつにひはんした。","example_meaning":"Nhà phê bình đã chỉ trích gay gắt tác phẩm mới.","examples":[{"example":"その批評家は、新作を辛辣に批判した。","example_reading":"そのひひょうかは、しんさくをしんらつにひはんした。","example_meaning":"Nhà phê bình đã chỉ trích gay gắt tác phẩm mới."},{"example":"上司は部下のミスを辛辣に指摘した。","example_reading":"じょうしはぶかのミスをしんらつにしてきした。","example_meaning":"Sếp chỉ ra lỗi của cấp dưới một cách cay nghiệt."}],"level":"a1"},
{"word":"潜在的に","reading":"せんざいてきに","meaning":"một cách tiềm tàng","hanviet":"tiềm tại đích","antonym":"顕在的に（けんざいてきに）: hiển hiện","antonym_hanviet":"hiển tại đích","note":"Dạng に. Hay đi với 持つ, 存在する, 抱える.","example":"彼は、潜在的に大きな可能性を持っている。","example_reading":"かれは、せんざいてきにおおきなかのうせいをもっている。","example_meaning":"Anh ấy mang trong mình tiềm năng lớn chưa lộ ra.","examples":[{"example":"彼は、潜在的に大きな可能性を持っている。","example_reading":"かれは、せんざいてきにおおきなかのうせいをもっている。","example_meaning":"Anh ấy mang trong mình tiềm năng lớn chưa lộ ra."},{"example":"この市場には、潜在的に多くの需要がある。","example_reading":"このしじょうには、せんざいてきにおおくのじゅようがある。","example_meaning":"Thị trường này tiềm ẩn nhiều nhu cầu."}],"level":"a1"},
{"word":"無造作に","reading":"むぞうさに","meaning":"một cách tùy tiện, thản nhiên, không chăm chút","hanviet":"vô tạo tác","antonym":"念入りに（ねんいりに）: kỹ lưỡng / 丁寧に（ていねいに）: cẩn thận","antonym_hanviet":"niệm nhập / đinh ninh","note":"Dạng に. Hay đi với 置く, 投げる, 束ねる. Làm tự nhiên, không cầu kỳ hoặc hơi qua loa.","example":"机の上に、書類が無造作に置かれていた。","example_reading":"つくえのうえに、しょるいがむぞうさにおかれていた。","example_meaning":"Trên bàn, giấy tờ được đặt tùy tiện.","examples":[{"example":"机の上に、書類が無造作に置かれていた。","example_reading":"つくえのうえに、しょるいがむぞうさにおかれていた。","example_meaning":"Trên bàn, giấy tờ được đặt tùy tiện."},{"example":"彼女は長い髪を無造作に束ねて出かけた。","example_reading":"かのじょはながいかみをむぞうさにたばねてでかけた。","example_meaning":"Cô ấy buộc tóc dài qua loa rồi ra ngoài."}],"level":"a1"},
{"word":"純粋に","reading":"じゅんすいに","meaning":"một cách thuần túy, đơn thuần","hanviet":"thuần túy","antonym":"不純に（ふじゅんに）: không thuần","antonym_hanviet":"bất thuần","note":"Dạng に. Hay đi với 楽しむ, 興味がある, 考える. Không lẫn động cơ nào khác.","example":"私は純粋に音楽が好きで、ピアノを弾いている。","example_reading":"わたしはじゅんすいにおんがくがすきで、ピアノをひいている。","example_meaning":"Tôi chơi piano chỉ đơn thuần vì yêu âm nhạc.","examples":[{"example":"私は純粋に音楽が好きで、ピアノを弾いている。","example_reading":"わたしはじゅんすいにおんがくがすきで、ピアノをひいている。","example_meaning":"Tôi chơi piano chỉ đơn thuần vì yêu âm nhạc."},{"example":"利益ではなく、純粋に研究への興味から始めた。","example_reading":"りえきではなく、じゅんすいにけんきゅうへのきょうみからはじめた。","example_meaning":"Tôi bắt đầu hoàn toàn vì hứng thú nghiên cứu chứ không vì lợi ích."}],"level":"a1"},
{"word":"慎重に","reading":"しんちょうに","meaning":"thận trọng, cẩn thận","hanviet":"thận trọng","note":"Dạng に. Hay đi với 運転する, 選ぶ, 考える.","antonym":"大胆に（だいたんに）: táo bạo / 軽率に（けいそつに）: khinh suất","antonym_hanviet":"đại đảm / khinh suất","example":"雪道では慎重に運転してください。","example_reading":"ゆきみちではしんちょうにうんてんしてください。","example_meaning":"Trên đường tuyết hãy lái xe cẩn thận.","examples":[{"example":"雪道では慎重に運転してください。","example_reading":"ゆきみちではしんちょうにうんてんしてください。","example_meaning":"Trên đường tuyết hãy lái xe cẩn thận."},{"example":"ガラスの器を慎重に運んだ。","example_reading":"ガラスのうつわをしんちょうにはこんだ。","example_meaning":"Tôi mang chiếc bát thủy tinh một cách cẩn thận."}],"level":"a1"},
{"word":"決然と","reading":"けつぜんと","meaning":"dứt khoát, quyết tâm không lay chuyển","hanviet":"quyết nhiên","antonym":"優柔不断に（ゆうじゅうふだんに）: do dự","antonym_hanviet":"ưu nhu bất đoạn","note":"Dạng と. Hay đi với 立ち上がる, 断る, 宣言する. Văn viết.","example":"彼は決然と立ち上がり、反対意見を述べた。","example_reading":"かれはけつぜんとたちあがり、はんたいいけんをのべた。","example_meaning":"Anh ấy dứt khoát đứng dậy nêu ý kiến phản đối.","examples":[{"example":"彼は決然と立ち上がり、反対意見を述べた。","example_reading":"かれはけつぜんとたちあがり、はんたいいけんをのべた。","example_meaning":"Anh ấy dứt khoát đứng dậy nêu ý kiến phản đối."},{"example":"彼女は決然と首を横に振った。","example_reading":"かのじょはけつぜんとくびをよこにふった。","example_meaning":"Cô ấy dứt khoát lắc đầu."}],"level":"a1"},
{"word":"盛大に","reading":"せいだいに","meaning":"một cách long trọng, linh đình","hanviet":"thịnh đại","antonym":"質素に（しっそに）: giản dị / ひっそりと: lặng lẽ","antonym_hanviet":"chất tố / ","note":"Dạng に. Hay đi với 祝う, 行う, 開く. Dùng cho lễ hội, tiệc lớn.","example":"創立百周年を盛大に祝うことになった。","example_reading":"そうりつひゃくしゅうねんをせいだいにいわうことになった。","example_meaning":"Đã quyết định tổ chức long trọng lễ kỷ niệm 100 năm thành lập.","examples":[{"example":"創立百周年を盛大に祝うことになった。","example_reading":"そうりつひゃくしゅうねんをせいだいにいわうことになった。","example_meaning":"Đã quyết định tổ chức long trọng lễ kỷ niệm 100 năm thành lập."},{"example":"友人の結婚式は盛大に行われた。","example_reading":"ゆうじんのけっこんしきはせいだいにおこなわれた。","example_meaning":"Đám cưới của người bạn được tổ chức linh đình."}],"level":"a1"},
{"word":"厳然と","reading":"げんぜんと","meaning":"nghiêm nhiên, rành rành, không thể lay chuyển","hanviet":"nghiêm nhiên","note":"Dạng と. Hay dùng với 事実, 存在 (厳然とした事実). Văn viết.","example":"厳然とした事実を受け入れなければならない。","example_reading":"げんぜんとしたじじつをうけいれなければならない。","example_meaning":"Phải chấp nhận sự thật rành rành.","examples":[{"example":"厳然とした事実を受け入れなければならない。","example_reading":"げんぜんとしたじじつをうけいれなければならない。","example_meaning":"Phải chấp nhận sự thật rành rành."},{"example":"その規則は今も厳然と存在している。","example_reading":"そのきそくはいまもげんぜんとそんざいしている。","example_meaning":"Quy tắc đó đến nay vẫn tồn tại rành rành."}],"level":"a1"},
{"word":"周到に","reading":"しゅうとうに","meaning":"một cách chu đáo, kỹ càng","hanviet":"chu đáo","antonym":"不用意に（ふよういに）: bất cẩn / ずさんに: cẩu thả","antonym_hanviet":"bất dụng ý / ","note":"Dạng に. Hay đi với 準備する, 計画する, 練る.","example":"彼は周到に準備を重ねて、計画を実行した。","example_reading":"かれはしゅうとうにじゅんびをかさねて、けいかくをじっこうした。","example_meaning":"Anh ấy chuẩn bị chu đáo rồi mới thực hiện kế hoạch.","examples":[{"example":"彼は周到に準備を重ねて、計画を実行した。","example_reading":"かれはしゅうとうにじゅんびをかさねて、けいかくをじっこうした。","example_meaning":"Anh ấy chuẩn bị chu đáo rồi mới thực hiện kế hoạch."},{"example":"周到に練られた作戦が、見事に成功した。","example_reading":"しゅうとうにねられたさくせんが、みごとにせいこうした。","example_meaning":"Kế hoạch được vạch kỹ lưỡng đã thành công ngoạn mục."}],"level":"a1"},
{"word":"内密に","reading":"ないみつに","meaning":"một cách bí mật, kín đáo","hanviet":"nội mật","antonym":"公然と（こうぜんと）: công khai / 公に（おおやけに）: công khai","antonym_hanviet":"công nhiên / công","note":"Dạng に. Hay đi với 相談する, 進める, 伝える.","example":"この件は、内密にお願いします。","example_reading":"このけんは、ないみつにおねがいします。","example_meaning":"Việc này xin hãy giữ kín.","examples":[{"example":"この件は、内密にお願いします。","example_reading":"このけんは、ないみつにおねがいします。","example_meaning":"Việc này xin hãy giữ kín."},{"example":"社長に内密に相談したいことがある。","example_reading":"しゃちょうにないみつにそうだんしたいことがある。","example_meaning":"Tôi có chuyện muốn bàn riêng, kín đáo với giám đốc."}],"level":"a1"},
{"word":"体系的に","reading":"たいけいてきに","meaning":"một cách có hệ thống","hanviet":"thể hệ đích","antonym":"場当たり的に（ばあたりてきに）: tùy cơ / 断片的に（だんぺんてきに）: rời rạc","antonym_hanviet":"trường đương đích / đoạn phiến đích","note":"Dạng に. Hay đi với 学ぶ, まとめる, 整理する.","example":"文法を体系的に学ぶと、理解しやすくなる。","example_reading":"ぶんぽうをたいけいてきにまなぶと、りかいしやすくなる。","example_meaning":"Học ngữ pháp có hệ thống thì dễ hiểu hơn.","examples":[{"example":"文法を体系的に学ぶと、理解しやすくなる。","example_reading":"ぶんぽうをたいけいてきにまなぶと、りかいしやすくなる。","example_meaning":"Học ngữ pháp có hệ thống thì dễ hiểu hơn."},{"example":"これまでの研究を、体系的にまとめた本が出版された。","example_reading":"これまでのけんきゅうを、たいけいてきにまとめたほんがしゅっぱんされた。","example_meaning":"Cuốn sách tổng hợp có hệ thống các nghiên cứu từ trước đến nay đã được xuất bản."}],"level":"a1"},
{"word":"痛切に","reading":"つうせつに","meaning":"một cách thấm thía, sâu sắc","hanviet":"thống thiết","note":"Dạng に. Hay đi với 感じる, 実感する, 訴える.","example":"失敗して初めて、準備の大切さを痛切に感じた。","example_reading":"しっぱいしてはじめて、じゅんびのたいせつさをつうせつにかんじた。","example_meaning":"Chỉ sau khi thất bại, tôi mới thấm thía tầm quan trọng của sự chuẩn bị.","examples":[{"example":"失敗して初めて、準備の大切さを痛切に感じた。","example_reading":"しっぱいしてはじめて、じゅんびのたいせつさをつうせつにかんじた。","example_meaning":"Chỉ sau khi thất bại, tôi mới thấm thía tầm quan trọng của sự chuẩn bị."},{"example":"今回の災害で、備えの重要さを痛切に実感した。","example_reading":"こんかいのさいがいで、そなえのじゅうようさをつうせつにじっかんした。","example_meaning":"Qua thiên tai lần này, tôi thấm thía tầm quan trọng của việc phòng bị."}],"level":"a1"},
{"word":"公然と","reading":"こうぜんと","meaning":"công khai, trắng trợn, không giấu giếm","hanviet":"công nhiên","note":"Dạng と. Thường mang sắc thái tiêu cực: làm điều xấu một cách lộ liễu.","antonym":"密かに（ひそかに）: lén lút / 内密に（ないみつに）: bí mật","antonym_hanviet":"mật / nội mật","example":"彼は上司を公然と批判した。","example_reading":"かれはじょうしをこうぜんとひはんした。","example_meaning":"Anh ta công khai chỉ trích cấp trên.","examples":[{"example":"彼は上司を公然と批判した。","example_reading":"かれはじょうしをこうぜんとひはんした。","example_meaning":"Anh ta công khai chỉ trích cấp trên."},{"example":"彼は公然と規則を無視している。","example_reading":"かれはこうぜんときそくをむしている。","example_meaning":"Anh ta công khai phớt lờ quy tắc."}],"level":"a1"},
{"word":"素直に","reading":"すなおに","meaning":"ngoan ngoãn, thẳng thắn, không gượng ép","hanviet":"tố trực","antonym":"反抗的に（はんこうてきに）: chống đối","antonym_hanviet":"phản kháng đích","note":"Dạng に. Hay đi với 認める, 聞く, 喜ぶ, 謝る.","example":"自分の間違いを素直に認めることが大切だ。","example_reading":"じぶんのまちがいをすなおにみとめることがたいせつだ。","example_meaning":"Thẳng thắn nhận lỗi của mình là điều quan trọng.","examples":[{"example":"自分の間違いを素直に認めることが大切だ。","example_reading":"じぶんのまちがいをすなおにみとめることがたいせつだ。","example_meaning":"Thẳng thắn nhận lỗi của mình là điều quan trọng."},{"example":"彼女の褒め言葉を素直に喜べなかった。","example_reading":"かのじょのほめことばをすなおによろこべなかった。","example_meaning":"Tôi đã không thể vui vẻ đón nhận lời khen của cô ấy."}],"level":"a1"},
{"word":"大胆に","reading":"だいたんに","meaning":"một cách táo bạo, mạnh dạn","hanviet":"đại đảm","note":"Dạng に. Hay đi với 挑戦する, 変える, 言う. Không e ngại rủi ro.","antonym":"慎重に（しんちょうに）: thận trọng / 無難に（ぶなんに）: an toàn","antonym_hanviet":"thận trọng / vô nạn","example":"新しい方法に大胆に挑戦してみよう。","example_reading":"あたらしいほうほうにだいたんにちょうせんしてみよう。","example_meaning":"Hãy mạnh dạn thử thách phương pháp mới.","examples":[{"example":"新しい方法に大胆に挑戦してみよう。","example_reading":"あたらしいほうほうにだいたんにちょうせんしてみよう。","example_meaning":"Hãy mạnh dạn thử thách phương pháp mới."},{"example":"彼女は大胆に髪を短く切った。","example_reading":"かのじょはだいたんにかみをみじかくきった。","example_meaning":"Cô ấy táo bạo cắt tóc ngắn."}],"level":"a1"},
{"word":"厳密に","reading":"げんみつに","meaning":"một cách nghiêm ngặt, chặt chẽ, chính xác","hanviet":"nghiêm mật","antonym":"大まかに（おおまかに）: đại khái / 緩く（ゆるく）: lỏng lẻo / おおよそ: đại khái","antonym_hanviet":"đại / hoãn / ","note":"Dạng に. Hay đi với 言えば, 定義する, 守る, 管理する. 厳密に言うと = nói chính xác thì.","example":"厳密に言うと、この二つの言葉は意味が少し違う。","example_reading":"げんみつにいうと、このふたつのことばはいみがすこしちがう。","example_meaning":"Nói chính xác thì hai từ này khác nghĩa đôi chút.","examples":[{"example":"厳密に言うと、この二つの言葉は意味が少し違う。","example_reading":"げんみつにいうと、このふたつのことばはいみがすこしちがう。","example_meaning":"Nói chính xác thì hai từ này khác nghĩa đôi chút."},{"example":"個人情報は厳密に管理されている。","example_reading":"こじんじょうほうはげんみつにかんりされている。","example_meaning":"Thông tin cá nhân được quản lý chặt chẽ."}],"level":"a1"},
{"word":"公平に","reading":"こうへいに","meaning":"một cách công bằng","hanviet":"công bình","antonym":"不公平に（ふこうへいに）: không công bằng","antonym_hanviet":"bất công bình","note":"Dạng に. Hay đi với 扱う, 分ける, 判断する. Không thiên vị.","example":"先生は生徒を公平に扱っている。","example_reading":"せんせいはせいとをこうへいにあつかっている。","example_meaning":"Thầy đối xử với học sinh một cách công bằng.","examples":[{"example":"先生は生徒を公平に扱っている。","example_reading":"せんせいはせいとをこうへいにあつかっている。","example_meaning":"Thầy đối xử với học sinh một cách công bằng."},{"example":"お菓子を全員に公平に分けた。","example_reading":"おかしをぜんいんにこうへいにわけた。","example_meaning":"Tôi chia bánh cho mọi người công bằng."}],"level":"a1"},
{"word":"率直に","reading":"そっちょくに","meaning":"thẳng thắn, bộc trực","hanviet":"suất trực","antonym":"遠回しに（とおまわしに）: quanh co, nói vòng","antonym_hanviet":"viễn hồi","note":"Dạng に. Hay đi với 言う, 話す, 認める. Mở đầu câu: 率直に言うと.","example":"率直に言うと、この計画には反対です。","example_reading":"そっちょくにいうと、このけいかくにははんたいです。","example_meaning":"Nói thẳng ra thì tôi phản đối kế hoạch này.","examples":[{"example":"率直に言うと、この計画には反対です。","example_reading":"そっちょくにいうと、このけいかくにははんたいです。","example_meaning":"Nói thẳng ra thì tôi phản đối kế hoạch này."},{"example":"彼は自分の失敗を率直に認めた。","example_reading":"かれはじぶんのしっぱいをそっちょくにみとめた。","example_meaning":"Anh ấy thẳng thắn thừa nhận thất bại của mình."}],"level":"a1"},
{"word":"刻一刻と","reading":"こくいっこくと","meaning":"từng giờ từng phút","hanviet":"khắc nhất khắc","note":"Dạng と. Hay đi với 近づく, 変わる, 迫る. Gần 刻々と nhưng nhấn mạnh thời gian đang trôi.","example":"試験の日が、刻一刻と近づいてくる。","example_reading":"しけんのひが、こくいっこくとちかづいてくる。","example_meaning":"Ngày thi đang đến gần từng giờ từng phút.","examples":[{"example":"試験の日が、刻一刻と近づいてくる。","example_reading":"しけんのひが、こくいっこくとちかづいてくる。","example_meaning":"Ngày thi đang đến gần từng giờ từng phút."},{"example":"日が沈み、空の色が刻一刻と変わっていった。","example_reading":"ひがしずみ、そらのいろがこくいっこくとかわっていった。","example_meaning":"Mặt trời lặn, màu trời đổi từng phút một."}],"level":"a1"},
{"word":"無残に","reading":"むざんに","meaning":"một cách thảm khốc, tàn nhẫn","hanviet":"vô tàn","note":"Dạng に. Hay đi với 壊される, 敗れる, 荒れ果てる.","example":"台風で、畑の作物が無残に倒されてしまった。","example_reading":"たいふうで、はたけのさくもつがむざんにたおされてしまった。","example_meaning":"Bão làm hoa màu ngoài đồng đổ rạp thảm hại.","examples":[{"example":"台風で、畑の作物が無残に倒されてしまった。","example_reading":"たいふうで、はたけのさくもつがむざんにたおされてしまった。","example_meaning":"Bão làm hoa màu ngoài đồng đổ rạp thảm hại."},{"example":"地震のあと、町は無残に崩れ落ちていた。","example_reading":"じしんのあと、まちはむざんにくずれおちていた。","example_meaning":"Sau trận động đất, thị trấn sụp đổ thảm khốc."}],"level":"a1"},
{"word":"組織的に","reading":"そしきてきに","meaning":"một cách có tổ chức","hanviet":"tổ chức đích","antonym":"個人的に（こじんてきに）: cá nhân / 無秩序に（むちつじょに）: vô trật tự","antonym_hanviet":"cá nhân đích / vô trật tự","note":"Dạng に. Hay đi với 行う, 隠す, 進める. Thường gặp trong 組織的犯行.","example":"その事件は、組織的に行われた犯罪だった。","example_reading":"そのじけんは、そしきてきにおこなわれたはんざいだった。","example_meaning":"Vụ việc đó là tội phạm được thực hiện có tổ chức.","examples":[{"example":"その事件は、組織的に行われた犯罪だった。","example_reading":"そのじけんは、そしきてきにおこなわれたはんざいだった。","example_meaning":"Vụ việc đó là tội phạm được thực hiện có tổ chức."},{"example":"災害時には、組織的に救助活動を進める必要がある。","example_reading":"さいがいじには、そしきてきにきゅうじょかつどうをすすめるひつようがある。","example_meaning":"Khi có thiên tai, cần triển khai cứu hộ một cách có tổ chức."}],"level":"a1"},
{"word":"厳粛に","reading":"げんしゅくに","meaning":"một cách trang nghiêm","hanviet":"nghiêm túc","antonym":"賑やかに（にぎやかに）: náo nhiệt / 軽々しく（かるがるしく）: khinh suất","antonym_hanviet":"chẩn / khinh khinh","note":"Dạng に. Hay đi với 行う, 受け止める.","example":"式典は厳粛に執り行われた。","example_reading":"しきてんはげんしゅくにとりおこなわれた。","example_meaning":"Buổi lễ được tiến hành trang nghiêm.","examples":[{"example":"式典は厳粛に執り行われた。","example_reading":"しきてんはげんしゅくにとりおこなわれた。","example_meaning":"Buổi lễ được tiến hành trang nghiêm."},{"example":"私たちはこの事実を、厳粛に受け止めなければならない。","example_reading":"わたしたちはこのじじつを、げんしゅくにうけとめなければならない。","example_meaning":"Chúng ta phải nghiêm túc đón nhận sự thật này."}],"level":"a1"},
{"word":"切々と","reading":"せつせつと","meaning":"một cách thiết tha, tha thiết","hanviet":"thiết thiết","note":"Dạng と. Hay đi với 訴える, 語る, 述べる. Nói hoặc viết chân thành, làm động lòng.","example":"被害者の母親は、娘への思いを切々と語った。","example_reading":"ひがいしゃのははおやは、むすめへのおもいをせつせつとかたった。","example_meaning":"Người mẹ nạn nhân tha thiết kể về tình cảm dành cho con gái.","examples":[{"example":"被害者の母親は、娘への思いを切々と語った。","example_reading":"ひがいしゃのははおやは、むすめへのおもいをせつせつとかたった。","example_meaning":"Người mẹ nạn nhân tha thiết kể về tình cảm dành cho con gái."},{"example":"彼は手紙の中で、感謝の気持ちを切々と綴っていた。","example_reading":"かれはてがみのなかで、かんしゃのきもちをせつせつとつづっていた。","example_meaning":"Trong thư, anh ấy tha thiết viết lên lòng biết ơn."}],"level":"a1"},
{"word":"敢然と","reading":"かんぜんと","meaning":"một cách dũng cảm, quả quyết","hanviet":"cảm nhiên","antonym":"おずおずと: rụt rè / 尻込みして（しりごみして）: chùn bước","antonym_hanviet":" / nhập","note":"Dạng と. Hay đi với 立ち向かう, 反対する, 挑む. Văn viết.","example":"彼女は不正に対して、敢然と立ち向かった。","example_reading":"かのじょはふせいにたいして、かんぜんとたちむかった。","example_meaning":"Cô ấy dũng cảm đứng lên chống lại sự gian lận.","examples":[{"example":"彼女は不正に対して、敢然と立ち向かった。","example_reading":"かのじょはふせいにたいして、かんぜんとたちむかった。","example_meaning":"Cô ấy dũng cảm đứng lên chống lại sự gian lận."},{"example":"市長は圧力に屈せず、敢然と改革を進めた。","example_reading":"しちょうはあつりょくにくっせず、かんぜんとかいかくをすすめた。","example_meaning":"Thị trưởng không khuất phục trước áp lực mà quả quyết thúc đẩy cải cách."}],"level":"a1"},
{"word":"明確に","reading":"めいかくに","meaning":"rõ ràng, minh bạch","hanviet":"minh xác","antonym":"曖昧に（あいまいに）: mơ hồ / 漠然と（ばくぜんと）: mơ hồ","antonym_hanviet":"ái muội / mạc nhiên","note":"Dạng に. Hay đi với 説明する, 示す, 区別する.","example":"目的を明確に説明してください。","example_reading":"もくてきをめいかくにせつめいしてください。","example_meaning":"Hãy giải thích rõ ràng mục đích.","examples":[{"example":"目的を明確に説明してください。","example_reading":"もくてきをめいかくにせつめいしてください。","example_meaning":"Hãy giải thích rõ ràng mục đích."},{"example":"責任の所在を明確にする必要がある。","example_reading":"せきにんのしょざいをめいかくにするひつようがある。","example_meaning":"Cần làm rõ trách nhiệm thuộc về ai."}],"level":"a1"},
{"word":"唖然と","reading":"あぜんと","meaning":"há hốc miệng, sững sờ không nói nên lời","hanviet":"á nhiên","note":"Dạng と. Hay đi với する (唖然とする). Ngạc nhiên đến cạn lời.","example":"彼の言い訳に、みんなが唖然とした。","example_reading":"かれのいいわけに、みんながあぜんとした。","example_meaning":"Trước lời bào chữa của anh ta, ai cũng há hốc miệng.","examples":[{"example":"彼の言い訳に、みんなが唖然とした。","example_reading":"かれのいいわけに、みんながあぜんとした。","example_meaning":"Trước lời bào chữa của anh ta, ai cũng há hốc miệng."},{"example":"教室の全員が唖然と先生を見つめていた。","example_reading":"きょうしつのぜんいんがあぜんとせんせいをみつめていた。","example_meaning":"Cả lớp há hốc miệng nhìn thầy giáo."}],"level":"a1"},
{"word":"露骨に","reading":"ろこつに","meaning":"một cách lộ liễu, trắng trợn","hanviet":"lộ cốt","antonym":"婉曲に（えんきょくに）: úp mở / さりげなく: kín đáo, tự nhiên","antonym_hanviet":"uyển khúc / ","note":"Dạng に. Hay đi với 嫌な顔をする, 態度に出す, 言う. Sắc thái tiêu cực.","example":"彼女は私を見て、露骨に嫌な顔をした。","example_reading":"かのじょはわたしをみて、ろこつにいやなかおをした。","example_meaning":"Cô ấy nhìn tôi rồi lộ rõ vẻ khó chịu.","examples":[{"example":"彼女は私を見て、露骨に嫌な顔をした。","example_reading":"かのじょはわたしをみて、ろこつにいやなかおをした。","example_meaning":"Cô ấy nhìn tôi rồi lộ rõ vẻ khó chịu."},{"example":"上司は露骨に一部の部下だけをひいきしている。","example_reading":"じょうしはろこつにいちぶのぶかだけをひいきしている。","example_meaning":"Sếp thiên vị ra mặt, chỉ ưu ái một số cấp dưới."}],"level":"a1"},
{"word":"憮然と","reading":"ぶぜんと","meaning":"bực dọc ỉu xìu, mặt sượng vì bất mãn","hanviet":"vũ nhiên","note":"Dạng と. Hay dùng với 表情 (憮然とした表情). Không vui nhưng không nói ra.","example":"彼は憮然とした表情で席を立った。","example_reading":"かれはぶぜんとしたひょうじょうでせきをたった。","example_meaning":"Anh ấy đứng dậy với vẻ mặt bực dọc.","examples":[{"example":"彼は憮然とした表情で席を立った。","example_reading":"かれはぶぜんとしたひょうじょうでせきをたった。","example_meaning":"Anh ấy đứng dậy với vẻ mặt bực dọc."},{"example":"彼女は不満を口にせず、憮然と窓の外を見ていた。","example_reading":"かのじょはふまんをくちにせず、ぶぜんとまどのそとをみていた。","example_meaning":"Cô ấy không nói ra bất mãn, chỉ ỉu xìu nhìn ra cửa sổ."}],"level":"a1"},
{"word":"一斉に","reading":"いっせいに","meaning":"đồng loạt, cùng một lúc","hanviet":"nhất tề","note":"Dạng に. Nhiều người hoặc vật cùng làm một việc vào cùng thời điểm.","antonym":"別々に（べつべつに）: riêng rẽ / 順番に（じゅんばんに）: lần lượt / 順々に（じゅんじゅんに）: lần lượt","antonym_hanviet":"biệt biệt / thuận phiên / thuận thuận","example":"ベルが鳴ると、生徒たちが一斉に立ち上がった。","example_reading":"ベルがなると、せいとたちがいっせいにたちあがった。","example_meaning":"Chuông reo, học sinh đồng loạt đứng dậy.","examples":[{"example":"ベルが鳴ると、生徒たちが一斉に立ち上がった。","example_reading":"ベルがなると、せいとたちがいっせいにたちあがった。","example_meaning":"Chuông reo, học sinh đồng loạt đứng dậy."},{"example":"合図とともに、鳥が一斉に飛び立った。","example_reading":"あいずとともに、とりがいっせいにとびたった。","example_meaning":"Theo hiệu lệnh, đàn chim đồng loạt bay lên."}],"level":"a1"},
{"word":"日に日に","reading":"ひにひに","meaning":"ngày qua ngày, mỗi ngày một","hanviet":"nhật nhật","note":"Dạng に. Chỉ sự thay đổi tăng dần theo từng ngày, hay đi với なる.","example":"日に日に寒くなってきました。","example_reading":"ひにひにさむくなってきました。","example_meaning":"Trời mỗi ngày một lạnh hơn.","examples":[{"example":"日に日に寒くなってきました。","example_reading":"ひにひにさむくなってきました。","example_meaning":"Trời mỗi ngày một lạnh hơn."},{"example":"赤ちゃんは日に日に重くなっている。","example_reading":"あかちゃんはひにひにおもくなっている。","example_meaning":"Em bé nặng thêm từng ngày."}],"level":"a1"},
{"word":"燦々と","reading":"さんさんと","meaning":"một cách chói chang, rực rỡ","hanviet":"xán xán","antonym":"どんよりと: u ám / 薄暗く（うすぐらく）: lờ mờ","antonym_hanviet":" / bạc ám","note":"Dạng と. Hay đi với 輝く, 降り注ぐ, 照らす. Ánh nắng rực rỡ. Văn chương.","example":"夏の太陽が、海辺に燦々と降り注いでいた。","example_reading":"なつのたいようが、うみべにさんさんとふりそそいでいた。","example_meaning":"Mặt trời mùa hè chiếu rực rỡ xuống bờ biển.","examples":[{"example":"夏の太陽が、海辺に燦々と降り注いでいた。","example_reading":"なつのたいようが、うみべにさんさんとふりそそいでいた。","example_meaning":"Mặt trời mùa hè chiếu rực rỡ xuống bờ biển."},{"example":"朝の光が窓から燦々と差し込んでいる。","example_reading":"あさのひかりがまどからさんさんとさしこんでいる。","example_meaning":"Ánh sáng ban mai chiếu rực rỡ qua cửa sổ."}],"level":"a1"},
{"word":"勝手に","reading":"かってに","meaning":"tự ý, tùy tiện (không xin phép)","hanviet":"thắng thủ","antonym":"許可を得て（きょかをえて）: có sự cho phép","antonym_hanviet":"hứa khả đắc","note":"Dạng に. Hay đi với 使う, 決める, 入る. Sắc thái chê trách.","example":"私の物を勝手に使わないでください。","example_reading":"わたしのものをかってにつかわないでください。","example_meaning":"Đừng tự ý dùng đồ của tôi.","examples":[{"example":"私の物を勝手に使わないでください。","example_reading":"わたしのものをかってにつかわないでください。","example_meaning":"Đừng tự ý dùng đồ của tôi."},{"example":"猫が勝手に部屋に入ってきた。","example_reading":"ねこがかってにへやにはいってきた。","example_meaning":"Con mèo tự ý chui vào phòng."}],"level":"a1"},
{"word":"凛と","reading":"りんと","meaning":"nghiêm trang, mạnh mẽ và thanh nhã","hanviet":"lẫm","note":"Dạng と. Hay đi với 立つ, 咲く, 響く, 振る舞う. Sắc thái đẹp, văn chương.","example":"彼女は凛とした姿勢で舞台に立った。","example_reading":"かのじょはりんとしたしせいでぶたいにたった。","example_meaning":"Cô ấy bước lên sân khấu với tư thế nghiêm trang thanh nhã.","examples":[{"example":"彼女は凛とした姿勢で舞台に立った。","example_reading":"かのじょはりんとしたしせいでぶたいにたった。","example_meaning":"Cô ấy bước lên sân khấu với tư thế nghiêm trang thanh nhã."},{"example":"冬の朝、凛と冷えた空気が心地よい。","example_reading":"ふゆのあさ、りんとひえたくうきがここちよい。","example_meaning":"Buổi sáng mùa đông, không khí lạnh trong veo thật dễ chịu."}],"level":"a1"},
{"word":"厳かに","reading":"おごそかに","meaning":"trang nghiêm, long trọng","hanviet":"nghiêm","antonym":"軽々しく（かるがるしく）: tùy tiện, nông nổi","antonym_hanviet":"khinh khinh","note":"Dạng に. Hay đi với 行う, 始まる, 告げる. Văn viết, dùng cho nghi lễ.","example":"式は厳かに始まった。","example_reading":"しきはおごそかにはじまった。","example_meaning":"Buổi lễ bắt đầu một cách trang nghiêm.","examples":[{"example":"式は厳かに始まった。","example_reading":"しきはおごそかにはじまった。","example_meaning":"Buổi lễ bắt đầu một cách trang nghiêm."},{"example":"卒業証書が厳かに手渡された。","example_reading":"そつぎょうしょうしょがおごそかにてわたされた。","example_meaning":"Bằng tốt nghiệp được trao một cách trang trọng."}],"level":"a1"},
{"word":"清らかに","reading":"きよらかに","meaning":"trong sạch, tinh khiết","hanviet":"thanh","antonym":"汚く（きたなく）: bẩn / 濁って（にごって）: đục","antonym_hanviet":"ô / trọc","note":"Dạng に. Hay đi với 流れる, 澄む, 保つ. Văn chương, tả nước hoặc tâm hồn.","example":"山の水は清らかに流れている。","example_reading":"やまのみずはきよらかにながれている。","example_meaning":"Nước núi chảy trong veo.","examples":[{"example":"山の水は清らかに流れている。","example_reading":"やまのみずはきよらかにながれている。","example_meaning":"Nước núi chảy trong veo."},{"example":"彼女は清らかに生きることを大切にしている。","example_reading":"かのじょはきよらかにいきることをたいせつにしている。","example_meaning":"Cô ấy coi trọng việc sống trong sạch."}],"level":"a1"},
{"word":"穏便に","reading":"おんびんに","meaning":"một cách êm thấm, ôn hòa","hanviet":"ổn tiện","antonym":"強硬に（きょうこうに）: cứng rắn / 強引に（ごういんに）: cưỡng ép","antonym_hanviet":"cường ngạnh / cường dẫn","note":"Dạng に. Hay đi với 済ませる, 解決する, 取り計らう. Tránh làm ầm ĩ; hơi trang trọng.","example":"この件は、穏便に解決したいと思っています。","example_reading":"このけんは、おんびんにかいけつしたいとおもっています。","example_meaning":"Chuyện này tôi muốn giải quyết cho êm thấm.","examples":[{"example":"この件は、穏便に解決したいと思っています。","example_reading":"このけんは、おんびんにかいけつしたいとおもっています。","example_meaning":"Chuyện này tôi muốn giải quyết cho êm thấm."},{"example":"上司は問題を穏便に済ませるよう指示した。","example_reading":"じょうしはもんだいをおんびんにすませるようしじした。","example_meaning":"Cấp trên chỉ đạo giải quyết vấn đề cho êm."}],"level":"a1"},
{"word":"じとじと","reading":"じとじと","meaning":"ẩm ướt, nhớp nháp, âm ẩm khó chịu","antonym":"からから: khô khốc","note":"Từ tượng hình. Hay đi với する／した hoặc と. Dùng cho mùa mưa, quần áo, da dính mồ hôi.","example":"梅雨は毎日じとじとして、洗濯物がなかなか乾きません。","example_reading":"つゆはまいにちじとじとして、せんたくものがなかなかかわきません。","example_meaning":"Mùa mưa ngày nào cũng ẩm ướt nhớp nháp, quần áo mãi không khô.","examples":[{"example":"梅雨は毎日じとじとして、洗濯物がなかなか乾きません。","example_reading":"つゆはまいにちじとじとして、せんたくものがなかなかかわきません。","example_meaning":"Mùa mưa ngày nào cũng ẩm ướt nhớp nháp, quần áo mãi không khô."},{"example":"傘をさしていたが、靴の中までじとじとしてきた。","example_reading":"かさをさしていたが、くつのなかまでじとじとしてきた。","example_meaning":"Dù đã che ô nhưng bên trong giày cũng ẩm nhớp."}],"level":"b1"},
{"word":"ぐずぐず","reading":"ぐずぐず","meaning":"chần chừ, lề mề, dây dưa","note":"Từ tượng hình chỉ thái độ. Hay dùng với する và ～していないで.","antonym":"さっさと: nhanh nhanh","example":"ぐずぐずしていると、電車に乗り遅れますよ。","example_reading":"ぐずぐずしていると、でんしゃにのりおくれますよ。","example_meaning":"Cứ chần chừ là lỡ tàu đấy.","examples":[{"example":"ぐずぐずしていると、電車に乗り遅れますよ。","example_reading":"ぐずぐずしていると、でんしゃにのりおくれますよ。","example_meaning":"Cứ chần chừ là lỡ tàu đấy."},{"example":"子どもが朝からぐずぐずして、なかなか支度をしない。","example_reading":"こどもがあさからぐずぐずして、なかなかしたくをしない。","example_meaning":"Đứa trẻ từ sáng cứ lề mề mãi không chịu chuẩn bị."}],"level":"b1"},
{"word":"バラバラ","reading":"ばらばら","meaning":"rời rạc, lộn xộn, mỗi nơi một kiểu","antonym":"揃って（そろって）: cùng nhau, đồng loạt","antonym_hanviet":"tề","note":"Từ tượng hình. Có thể dùng với な／に／する. Chỉ sự không thống nhất hoặc bị tách rời.","example":"みんなの意見がバラバラで、まとまりません。","example_reading":"みんなのいけんがばらばらで、まとまりません。","example_meaning":"Ý kiến mỗi người một khác nên không thống nhất được.","examples":[{"example":"みんなの意見がバラバラで、まとまりません。","example_reading":"みんなのいけんがばらばらで、まとまりません。","example_meaning":"Ý kiến mỗi người một khác nên không thống nhất được."},{"example":"時計が壊れて、部品がバラバラになった。","example_reading":"とけいがこわれて、ぶひんがバラバラになった。","example_meaning":"Đồng hồ hỏng, các bộ phận rời tung ra."}],"level":"b1"},
{"word":"ペラペラ","reading":"ぺらぺら","meaning":"lưu loát, trôi chảy (nói ngoại ngữ)","antonym":"たどたどしく: ấp úng","note":"Từ tượng hình. Chủ yếu nói về khả năng nói, hay đi với 話す, だ.","example":"彼女は英語がペラペラです。","example_reading":"かのじょはえいごがぺらぺらです。","example_meaning":"Cô ấy nói tiếng Anh trôi chảy.","examples":[{"example":"彼女は英語がペラペラです。","example_reading":"かのじょはえいごがぺらぺらです。","example_meaning":"Cô ấy nói tiếng Anh trôi chảy."},{"example":"彼は日本語がペラペラで、通訳も務める。","example_reading":"かれはにほんごがペラペラで、つうやくもつとめる。","example_meaning":"Anh ấy nói tiếng Nhật lưu loát, còn làm thông dịch."}],"level":"b1"},
{"word":"ゆっくり","reading":"ゆっくり","meaning":"chậm rãi, thong thả","antonym":"さっさと: nhanh nhanh / 速やかに（すみやかに）: nhanh chóng / 早急に（さっきゅうに）: gấp","antonym_hanviet":" / tốc / tảo cấp","note":"Làm gì đó không vội. Hay đi với 話す, 休む, 歩く, 過ごす.","example":"もう少しゆっくり話してください。","example_reading":"もうすこしゆっくりはなしてください。","example_meaning":"Xin hãy nói chậm hơn một chút.","examples":[{"example":"もう少しゆっくり話してください。","example_reading":"もうすこしゆっくりはなしてください。","example_meaning":"Xin hãy nói chậm hơn một chút."},{"example":"週末は家でゆっくり過ごしたい。","example_reading":"しゅうまつはいえでゆっくりすごしたい。","example_meaning":"Cuối tuần tôi muốn thong thả ở nhà."}],"level":"b1"},
{"word":"はっきり","reading":"はっきり","meaning":"rõ ràng, minh bạch","antonym":"ぼんやり: mờ mờ, lơ mơ / 漠然と（ばくぜんと）: mơ hồ / 微かに（かすかに）: mờ nhạt","antonym_hanviet":" / mạc nhiên / vi","note":"Hay đi với 言う, 見える, わかる, 覚えている.","example":"自分の意見をはっきり言ったほうがいい。","example_reading":"じぶんのいけんをはっきりいったほうがいい。","example_meaning":"Bạn nên nói rõ ý kiến của mình.","examples":[{"example":"自分の意見をはっきり言ったほうがいい。","example_reading":"じぶんのいけんをはっきりいったほうがいい。","example_meaning":"Bạn nên nói rõ ý kiến của mình."},{"example":"今日は空気がきれいで、遠くの山がはっきり見える。","example_reading":"きょうはくうきがきれいで、とおくのやまがはっきりみえる。","example_meaning":"Hôm nay không khí trong lành nên nhìn rõ núi ở xa."}],"level":"b1"},
{"word":"ちゃんと","reading":"ちゃんと","meaning":"đàng hoàng, tử tế, cẩn thận","antonym":"いい加減に（いいかげんに）: qua loa","antonym_hanviet":"gia giảm","note":"Làm đúng quy cách, không qua loa. Hay đi với 食べる, 勉強する, 挨拶する, 確認する.","example":"朝ごはんはちゃんと食べないとだめだよ。","example_reading":"あさごはんはちゃんとたべないとだめだよ。","example_meaning":"Bữa sáng thì phải ăn đàng hoàng đấy.","examples":[{"example":"朝ごはんはちゃんと食べないとだめだよ。","example_reading":"あさごはんはちゃんとたべないとだめだよ。","example_meaning":"Bữa sáng thì phải ăn đàng hoàng đấy."},{"example":"部屋を出るときは、ちゃんと鍵をかけたか確認してください。","example_reading":"へやをでるときは、ちゃんとかぎをかけたかかくにんしてください。","example_meaning":"Khi ra khỏi phòng, hãy kiểm tra cẩn thận xem đã khóa cửa chưa."}],"level":"b1"},
{"word":"うっかり","reading":"うっかり","meaning":"vô ý, lơ đễnh","antonym":"しっかり: chắc chắn, cẩn thận / わざと: cố ý / 故意に（こいに）: cố ý","antonym_hanviet":" /  / cố ý","note":"Hay đi với 忘れる, 言う, する. Sơ suất, không để ý.","example":"うっかり鍵を家に忘れてしまった。","example_reading":"うっかりかぎをいえにわすれてしまった。","example_meaning":"Tôi lơ đãng để quên chìa khóa ở nhà.","examples":[{"example":"うっかり鍵を家に忘れてしまった。","example_reading":"うっかりかぎをいえにわすれてしまった。","example_meaning":"Tôi lơ đãng để quên chìa khóa ở nhà."},{"example":"うっかり秘密をしゃべってしまった。","example_reading":"うっかりひみつをしゃべってしまった。","example_meaning":"Tôi lỡ miệng nói ra bí mật."}],"level":"b1"},
{"word":"どんどん","reading":"どんどん","meaning":"liên tục, nhanh chóng","antonym":"ゆっくり: chậm rãi / のろのろ: chậm chạp","note":"Diễn biến tăng hoặc tiến triển nhanh, liên tiếp. Hay đi với 増える, 進む, 食べる.","example":"友達が増えて、仕事がどんどん楽しくなった。","example_reading":"ともだちがふえて、しごとがどんどんたのしくなった。","example_meaning":"Có thêm bạn nên công việc ngày càng vui hơn.","examples":[{"example":"友達が増えて、仕事がどんどん楽しくなった。","example_reading":"ともだちがふえて、しごとがどんどんたのしくなった。","example_meaning":"Có thêm bạn nên công việc ngày càng vui hơn."},{"example":"遠慮しないで、どんどん食べてください。","example_reading":"えんりょしないで、どんどんたべてください。","example_meaning":"Đừng ngại, cứ ăn thoải mái đi."}],"level":"b1"},
{"word":"すらすら","reading":"すらすら","meaning":"trôi chảy, suôn sẻ, không vấp","antonym":"たどたどしく: ấp úng","note":"Hay đi với 読む, 話す, 解ける, 進む. Diễn tả việc làm không bị vướng mắc.","example":"彼は難しい漢字もすらすら読める。","example_reading":"かれはむずかしいかんじもすらすらよめる。","example_meaning":"Anh ấy đọc trôi chảy cả những chữ Hán khó.","examples":[{"example":"彼は難しい漢字もすらすら読める。","example_reading":"かれはむずかしいかんじもすらすらよめる。","example_meaning":"Anh ấy đọc trôi chảy cả những chữ Hán khó."},{"example":"準備をしておいたので、面接ですらすら答えられた。","example_reading":"じゅんびをしておいたので、めんせつですらすらこたえられた。","example_meaning":"Vì đã chuẩn bị nên tôi trả lời phỏng vấn trôi chảy."}],"level":"b1"},
{"word":"さっさと","reading":"さっさと","meaning":"nhanh nhanh lên, làm gọn lẹ không chần chừ","note":"Hay đi với 行く, 食べる, 片付ける. Dùng khi thúc giục hoặc làm xong nhanh gọn.","antonym":"ゆっくり: chậm rãi / ぐずぐず: chần chừ / もたもた: chậm chạp","example":"さっさと宿題を済ませて、遊びに行こう。","example_reading":"さっさとしゅくだいをすませて、あそびにいこう。","example_meaning":"Làm nhanh bài tập rồi đi chơi thôi.","examples":[{"example":"さっさと宿題を済ませて、遊びに行こう。","example_reading":"さっさとしゅくだいをすませて、あそびにいこう。","example_meaning":"Làm nhanh bài tập rồi đi chơi thôi."},{"example":"彼は用事が終わると、さっさと帰ってしまった。","example_reading":"かれはようじがおわると、さっさとかえってしまった。","example_meaning":"Xong việc là anh ấy về luôn cho nhanh."}],"level":"b1"},
{"word":"ふわふわ","reading":"ふわふわ","meaning":"mềm xốp, nhẹ bẫng","antonym":"ずっしり: nặng trịch / ごわごわ: cứng","note":"Từ tượng hình. Dùng cho bánh, chăn, tóc, mây. Có thể đi với と／する.","example":"このパンはふわふわで、とてもおいしいです。","example_reading":"このパンはふわふわで、とてもおいしいです。","example_meaning":"Chiếc bánh mì này mềm xốp, rất ngon.","examples":[{"example":"このパンはふわふわで、とてもおいしいです。","example_reading":"このパンはふわふわで、とてもおいしいです。","example_meaning":"Chiếc bánh mì này mềm xốp, rất ngon."},{"example":"雪がふわふわと降ってきた。","example_reading":"ゆきがふわふわとふってきた。","example_meaning":"Tuyết rơi nhẹ bẫng xuống."}],"level":"b1"},
{"word":"ドキドキ","reading":"どきどき","meaning":"hồi hộp, tim đập thình thịch","antonym":"落ち着いて（おちついて）: bình tĩnh","antonym_hanviet":"lạc trước","note":"Từ tượng thanh/hình. Hay đi với する, chỉ cảm giác lo lắng hoặc rung động.","example":"面接の前は、心臓がドキドキしました。","example_reading":"めんせつのまえは、しんぞうがどきどきしました。","example_meaning":"Trước buổi phỏng vấn tim tôi đập thình thịch.","examples":[{"example":"面接の前は、心臓がドキドキしました。","example_reading":"めんせつのまえは、しんぞうがどきどきしました。","example_meaning":"Trước buổi phỏng vấn tim tôi đập thình thịch."},{"example":"好きな人に会えると思うと、胸がドキドキした。","example_reading":"すきなひとにあえるとおもうと、むねがドキドキした。","example_meaning":"Nghĩ đến việc được gặp người mình thích, tim tôi đập thình thịch."}],"level":"b1"},
{"word":"ワクワク","reading":"わくわく","meaning":"háo hức, nôn nao mong đợi","antonym":"うんざり: chán ngán / がっかり: thất vọng","note":"Từ tượng hình. Cảm xúc tích cực, hay đi với する.","example":"明日の旅行が楽しみで、ワクワクしています。","example_reading":"あしたのりょこうがたのしみで、わくわくしています。","example_meaning":"Tôi háo hức chờ chuyến đi ngày mai.","examples":[{"example":"明日の旅行が楽しみで、ワクワクしています。","example_reading":"あしたのりょこうがたのしみで、わくわくしています。","example_meaning":"Tôi háo hức chờ chuyến đi ngày mai."},{"example":"新しいゲームを買って、ワクワクしながら帰った。","example_reading":"あたらしいゲームをかって、ワクワクしながらかえった。","example_meaning":"Mua được trò chơi mới, tôi háo hức trên đường về."}],"level":"b1"},
{"word":"イライラ","reading":"いらいら","meaning":"bực bội, nóng ruột, sốt ruột","antonym":"のんびり: thong thả","note":"Từ tượng hình. Hay đi với する, chỉ tâm trạng khó chịu vì phải chờ hoặc không như ý.","example":"電車が遅れて、イライラしました。","example_reading":"でんしゃがおくれて、いらいらしました。","example_meaning":"Tàu bị trễ làm tôi bực bội.","examples":[{"example":"電車が遅れて、イライラしました。","example_reading":"でんしゃがおくれて、いらいらしました。","example_meaning":"Tàu bị trễ làm tôi bực bội."},{"example":"待たされて、だんだんイライラしてきた。","example_reading":"またされて、だんだんイライラしてきた。","example_meaning":"Bị bắt chờ, tôi dần dần bực bội."}],"level":"b1"},
{"word":"もやもや","reading":"もやもや","meaning":"lòng nặng trĩu, khó chịu, chưa thông","antonym":"すっきり: sảng khoái","note":"Tâm trạng không rõ ràng, khó chịu mà không giải tỏa được. Hay đi với 気持ち, する.","example":"彼の言葉が気になって、一日中もやもやしていた。","example_reading":"かれのことばがきになって、いちにちじゅうもやもやしていた。","example_meaning":"Tôi cứ bận tâm lời anh ấy nên cả ngày thấy khó chịu trong lòng.","examples":[{"example":"彼の言葉が気になって、一日中もやもやしていた。","example_reading":"かれのことばがきになって、いちにちじゅうもやもやしていた。","example_meaning":"Tôi cứ bận tâm lời anh ấy nên cả ngày thấy khó chịu trong lòng."},{"example":"結局答えが出ず、もやもやした気持ちが残った。","example_reading":"けっきょくこたえがでず、もやもやしたきもちがのこった。","example_meaning":"Rốt cuộc không có lời đáp, trong lòng vẫn còn cảm giác lấn cấn."}],"level":"b1"},
{"word":"うきうき","reading":"うきうき","meaning":"hớn hở, phấn khởi","note":"Tâm trạng vui vẻ, háo hức vì sắp có chuyện vui. Hay đi với する, 気分.","antonym":"がっくり: thất vọng / しょんぼり: buồn thiu","example":"明日から旅行なので、朝からうきうきしている。","example_reading":"あしたからりょこうなので、あさからうきうきしている。","example_meaning":"Ngày mai bắt đầu đi du lịch nên từ sáng tôi đã háo hức.","examples":[{"example":"明日から旅行なので、朝からうきうきしている。","example_reading":"あしたからりょこうなので、あさからうきうきしている。","example_meaning":"Ngày mai bắt đầu đi du lịch nên từ sáng tôi đã háo hức."},{"example":"彼女は新しい服を着て、うきうきと出かけて行った。","example_reading":"かのじょはあたらしいふくをきて、うきうきとでかけていった。","example_meaning":"Cô ấy mặc bộ đồ mới, hớn hở ra ngoài."}],"level":"b1"},
{"word":"ほっと","reading":"ほっと","meaning":"nhẹ nhõm, thở phào","antonym":"ひやひや: thót tim lo lắng / はらはら: hồi hộp lo lắng / むかっと: tức giận bốc lên","note":"Hết lo lắng. Hay đi với する, ほっとした.","example":"試験が終わって、やっとほっとした。","example_reading":"しけんがおわって、やっとほっとした。","example_meaning":"Thi xong rồi, cuối cùng tôi cũng thở phào.","examples":[{"example":"試験が終わって、やっとほっとした。","example_reading":"しけんがおわって、やっとほっとした。","example_meaning":"Thi xong rồi, cuối cùng tôi cũng thở phào."},{"example":"子どもの無事な顔を見て、ほっとした。","example_reading":"こどものぶじなかおをみて、ほっとした。","example_meaning":"Nhìn thấy gương mặt bình an của con, tôi nhẹ cả người."}],"level":"b1"},
{"word":"むっと","reading":"むっと","meaning":"cáu, nổi giận (thoáng qua)","antonym":"にっこり: mỉm cười / にこっと: mỉm cười","note":"Bực bội trong chốc lát, thường lộ ra mặt. Hay đi với する, むっとした顔.","example":"失礼なことを言われて、むっとした。","example_reading":"しつれいなことをいわれて、むっとした。","example_meaning":"Bị nói những lời thất lễ, tôi thấy bực mình.","examples":[{"example":"失礼なことを言われて、むっとした。","example_reading":"しつれいなことをいわれて、むっとした。","example_meaning":"Bị nói những lời thất lễ, tôi thấy bực mình."},{"example":"彼は少しむっとした顔で席を立った。","example_reading":"かれはすこしむっとしたかおでせきをたった。","example_meaning":"Anh ấy đứng dậy khỏi chỗ với vẻ mặt hơi cáu."}],"level":"b1"},
{"word":"ぴかぴか","reading":"ぴかぴか","meaning":"sáng bóng, sáng loáng","antonym":"ぼろぼろ: rách nát","note":"Từ tượng hình. Dùng cho đồ vật được lau chùi sạch.","example":"掃除をして、床をぴかぴかにしました。","example_reading":"そうじをして、ゆかをぴかぴかにしました。","example_meaning":"Tôi lau dọn làm cho sàn nhà sáng bóng.","examples":[{"example":"掃除をして、床をぴかぴかにしました。","example_reading":"そうじをして、ゆかをぴかぴかにしました。","example_meaning":"Tôi lau dọn làm cho sàn nhà sáng bóng."},{"example":"磨いた靴がぴかぴかに光っている。","example_reading":"みがいたくつがぴかぴかにひかっている。","example_meaning":"Đôi giày đã đánh bóng sáng loáng."}],"level":"b1"},
{"word":"きらきら","reading":"きらきら","meaning":"lấp lánh, long lanh","antonym":"どんより: u ám","note":"Từ tượng hình. Hay đi với と／する, dùng cho sao, mặt nước, ánh mắt.","example":"星がきらきらと光っています。","example_reading":"ほしがきらきらとひかっています。","example_meaning":"Những vì sao đang lấp lánh.","examples":[{"example":"星がきらきらと光っています。","example_reading":"ほしがきらきらとひかっています。","example_meaning":"Những vì sao đang lấp lánh."},{"example":"子どもたちの目がきらきらと輝いていた。","example_reading":"こどもたちのめがきらきらとかがやいていた。","example_meaning":"Đôi mắt bọn trẻ long lanh sáng rực."}],"level":"b1"},
{"word":"ぱっと","reading":"ぱっと","meaning":"bỗng chốc, vụt một cái","antonym":"じわじわ: từ từ / じんわり: từ từ thấm","note":"Hay đi với 明るくなる, 広がる, 思いつく, 消える. Sự việc xảy ra đột ngột và nhanh.","example":"部屋の電気がぱっとついた。","example_reading":"へやのでんきがぱっとついた。","example_meaning":"Đèn trong phòng bật sáng bừng.","examples":[{"example":"部屋の電気がぱっとついた。","example_reading":"へやのでんきがぱっとついた。","example_meaning":"Đèn trong phòng bật sáng bừng."},{"example":"いいアイデアがぱっと頭に浮かんだ。","example_reading":"いいアイデアがぱっとあたまにうかんだ。","example_meaning":"Một ý tưởng hay chợt lóe lên trong đầu."}],"level":"b1"},
{"word":"さっと","reading":"さっと","meaning":"nhanh gọn, thoáng qua","antonym":"じっくり: kỹ lưỡng, từ tốn","note":"Hay đi với 洗う, 見る, 立ち上がる, 茹でる. Làm trong chốc lát.","example":"野菜をさっと茹でてから炒めます。","example_reading":"やさいをさっとゆでてからいためます。","example_meaning":"Luộc rau qua nhanh rồi mới xào.","examples":[{"example":"野菜をさっと茹でてから炒めます。","example_reading":"やさいをさっとゆでてからいためます。","example_meaning":"Luộc rau qua nhanh rồi mới xào."},{"example":"彼女はさっと立ち上がって、窓を開けた。","example_reading":"かのじょはさっとたちあがって、まどをあけた。","example_meaning":"Cô ấy đứng phắt dậy rồi mở cửa sổ."}],"level":"b1"},
{"word":"すっと","reading":"すっと","meaning":"nhẹ nhàng, vụt một cái; nhẹ nhõm","note":"Hay đi với 立つ, 入る, 消える, 気持ちが～. Động tác trơn tru, hoặc cảm giác nhẹ đi.","example":"背の高い男の人がすっと立ち上がった。","example_reading":"せのたかいおとこのひとがすっとたちあがった。","example_meaning":"Người đàn ông cao lớn đứng dậy nhẹ nhàng.","examples":[{"example":"背の高い男の人がすっと立ち上がった。","example_reading":"せのたかいおとこのひとがすっとたちあがった。","example_meaning":"Người đàn ông cao lớn đứng dậy nhẹ nhàng."},{"example":"全部話したら、気持ちがすっと楽になった。","example_reading":"ぜんぶはなしたら、きもちがすっとらくになった。","example_meaning":"Nói hết ra rồi, lòng tôi nhẹ nhõm hẳn."}],"level":"b1"},
{"word":"ぐっと","reading":"ぐっと","meaning":"hẳn lên, mạnh mẽ; dồn sức kìm nén","note":"Hay đi với 上がる, 近づく, 我慢する, 飲む. Thay đổi rõ rệt hoặc dồn sức.","example":"来週からぐっと寒くなるそうだ。","example_reading":"らいしゅうからぐっとさむくなるそうだ。","example_meaning":"Nghe nói từ tuần sau trời lạnh hẳn đi.","examples":[{"example":"来週からぐっと寒くなるそうだ。","example_reading":"らいしゅうからぐっとさむくなるそうだ。","example_meaning":"Nghe nói từ tuần sau trời lạnh hẳn đi."},{"example":"悔しかったが、涙をぐっとこらえた。","example_reading":"くやしかったが、なみだをぐっとこらえた。","example_meaning":"Tuy tiếc nuối nhưng tôi đã cố nén nước mắt."}],"level":"b1"},
{"word":"ぐっすり","reading":"ぐっすり","meaning":"(Ngủ) say, ngon giấc","antonym":"うとうと: ngủ gà ngủ gật / うつらうつら: gà gật","note":"Từ tượng hình. Gần như chỉ đi với 眠る／寝る.","example":"昨日はぐっすり眠れました。","example_reading":"きのうはぐっすりねむれました。","example_meaning":"Hôm qua tôi ngủ rất say.","examples":[{"example":"昨日はぐっすり眠れました。","example_reading":"きのうはぐっすりねむれました。","example_meaning":"Hôm qua tôi ngủ rất say."},{"example":"疲れていたので、ぐっすり眠ってしまった。","example_reading":"つかれていたので、ぐっすりねむってしまった。","example_meaning":"Vì mệt nên tôi ngủ say luôn."}],"level":"b1"},
{"word":"のんびり","reading":"のんびり","meaning":"thong thả, thư thả, thoải mái","antonym":"せかせか: hấp tấp / イライラ: bực bội / ばたばた: cuống quýt bận rộn","note":"Từ tượng hình. Hay đi với する／過ごす, chỉ trạng thái không vội vã.","example":"休みの日は家でのんびり過ごします。","example_reading":"やすみのひはいえでのんびりすごします。","example_meaning":"Ngày nghỉ tôi thong thả ở nhà.","examples":[{"example":"休みの日は家でのんびり過ごします。","example_reading":"やすみのひはいえでのんびりすごします。","example_meaning":"Ngày nghỉ tôi thong thả ở nhà."},{"example":"田舎でのんびり暮らすのが夢だ。","example_reading":"いなかでのんびりくらすのがゆめだ。","example_meaning":"Ước mơ của tôi là sống thong thả ở quê."}],"level":"b1"},
{"word":"じっと","reading":"じっと","meaning":"yên lặng, chăm chú, nhẫn nại","antonym":"うろうろ: đi lòng vòng / きょろきょろ: Đảo mắt nhìn quanh / ちらっと: liếc qua","note":"Giữ yên không động đậy hoặc nhìn chằm chằm. Hay đi với 見る, 待つ, 動かない, 我慢する.","example":"彼は窓の外をじっと見つめていた。","example_reading":"かれはまどのそとをじっとみつめていた。","example_meaning":"Anh ấy chăm chú nhìn ra ngoài cửa sổ.","examples":[{"example":"彼は窓の外をじっと見つめていた。","example_reading":"かれはまどのそとをじっとみつめていた。","example_meaning":"Anh ấy chăm chú nhìn ra ngoài cửa sổ."},{"example":"寒くても、じっと我慢するしかない。","example_reading":"さむくても、じっとがまんするしかない。","example_meaning":"Dù lạnh cũng chỉ có thể kiên nhẫn chịu đựng."}],"level":"b1"},
{"word":"ぎゅっと","reading":"ぎゅっと","meaning":"siết chặt, ôm chặt","antonym":"緩く（ゆるく）: lỏng lẻo","antonym_hanviet":"hoãn","note":"Dùng lực nén chặt. Hay đi với 握る, 抱きしめる, 結ぶ.","example":"子どもは母親の手をぎゅっと握った。","example_reading":"こどもはははおやのてをぎゅっとにぎった。","example_meaning":"Đứa bé nắm chặt tay mẹ.","examples":[{"example":"子どもは母親の手をぎゅっと握った。","example_reading":"こどもはははおやのてをぎゅっとにぎった。","example_meaning":"Đứa bé nắm chặt tay mẹ."},{"example":"靴ひもをぎゅっと結んで、走り出した。","example_reading":"くつひもをぎゅっとむすんで、はしりだした。","example_meaning":"Tôi buộc chặt dây giày rồi chạy đi."}],"level":"b1"},
{"word":"ぐいぐい","reading":"ぐいぐい","meaning":"mạnh mẽ, ráo riết","note":"Hay đi với 引っ張る, 飲む, 進む. Dồn sức tiến lên liên tục.","example":"犬が散歩中、飼い主をぐいぐい引っ張った。","example_reading":"いぬがさんぽちゅう、かいぬしをぐいぐいひっぱった。","example_meaning":"Con chó kéo chủ rất mạnh khi đi dạo.","examples":[{"example":"犬が散歩中、飼い主をぐいぐい引っ張った。","example_reading":"いぬがさんぽちゅう、かいぬしをぐいぐいひっぱった。","example_meaning":"Con chó kéo chủ rất mạnh khi đi dạo."},{"example":"彼はぐいぐいと周りを引っ張るリーダーだ。","example_reading":"かれはぐいぐいとまわりをひっぱるリーダーだ。","example_meaning":"Anh ấy là người lãnh đạo kéo mọi người đi mạnh mẽ."}],"level":"b1"},
{"word":"ずんずん","reading":"ずんずん","meaning":"thẳng tiến, rất nhanh","antonym":"のろのろ: chậm chạp","note":"Hay đi với 進む, 歩く, 伸びる. Tiến lên liên tục, không do dự.","example":"彼は道を知っているのか、ずんずん歩いていった。","example_reading":"かれはみちをしっているのか、ずんずんあるいていった。","example_meaning":"Chắc anh ấy biết đường nên cứ thẳng bước.","examples":[{"example":"彼は道を知っているのか、ずんずん歩いていった。","example_reading":"かれはみちをしっているのか、ずんずんあるいていった。","example_meaning":"Chắc anh ấy biết đường nên cứ thẳng bước."},{"example":"新しい店の売り上げがずんずん伸びている。","example_reading":"あたらしいみせのうりあげがずんずんのびている。","example_meaning":"Doanh thu của cửa hàng mới tăng vùn vụt."}],"level":"b1"},
{"word":"すいすい","reading":"すいすい","meaning":"thoăn thoắt, suôn sẻ","antonym":"もたもた: lóng ngóng / のろのろ: chậm chạp","note":"Hay đi với 泳ぐ, 進む, 運ぶ. Di chuyển nhẹ nhàng, trơn tru.","example":"魚がすいすいと水の中を泳いでいる。","example_reading":"さかながすいすいとみずのなかをおよいでいる。","example_meaning":"Cá bơi thoăn thoắt trong nước.","examples":[{"example":"魚がすいすいと水の中を泳いでいる。","example_reading":"さかながすいすいとみずのなかをおよいでいる。","example_meaning":"Cá bơi thoăn thoắt trong nước."},{"example":"平日の夜は道が空いていて、車がすいすい進んだ。","example_reading":"へいじつのよるはみちがあいていて、くるまがすいすいすすんだ。","example_meaning":"Tối ngày thường đường vắng nên xe chạy thông thoáng."}],"level":"b1"},
{"word":"ぐんぐん","reading":"ぐんぐん","meaning":"vùn vụt, tăng nhanh","antonym":"少しずつ（すこしずつ）: từng chút một","antonym_hanviet":"thiểu","note":"Tăng trưởng hoặc tiến triển mạnh mẽ. Hay đi với 伸びる, 上がる, 成長する.","example":"この木は、毎年ぐんぐん伸びている。","example_reading":"このきは、まいとしぐんぐんのびている。","example_meaning":"Cái cây này năm nào cũng lớn vùn vụt.","examples":[{"example":"この木は、毎年ぐんぐん伸びている。","example_reading":"このきは、まいとしぐんぐんのびている。","example_meaning":"Cái cây này năm nào cũng lớn vùn vụt."},{"example":"彼女の成績は、夏からぐんぐん上がった。","example_reading":"かのじょのせいせきは、なつからぐんぐんあがった。","example_meaning":"Thành tích của cô ấy tăng vùn vụt từ mùa hè."}],"level":"b1"},
{"word":"はきはき","reading":"はきはき","meaning":"rành rọt, dứt khoát, lanh lợi","antonym":"もじもじ: ngượng ngùng, ngập ngừng / もぐもぐ: nhai nhóp nhép / うじうじ: ấp úng","note":"Hay đi với 話す, 答える, 返事する. Nói năng rõ ràng, dễ nghe.","example":"面接では、はきはき答えることが大切だ。","example_reading":"めんせつでは、はきはきこたえることがたいせつだ。","example_meaning":"Khi phỏng vấn, trả lời rành rọt là điều quan trọng.","examples":[{"example":"面接では、はきはき答えることが大切だ。","example_reading":"めんせつでは、はきはきこたえることがたいせつだ。","example_meaning":"Khi phỏng vấn, trả lời rành rọt là điều quan trọng."},{"example":"あの子は誰にでもはきはき挨拶する。","example_reading":"あのこはだれにでもはきはきあいさつする。","example_meaning":"Đứa bé đó chào ai cũng rành rọt."}],"level":"b1"},
{"word":"きびきび","reading":"きびきび","meaning":"nhanh nhẹn, gọn gàng dứt khoát","antonym":"だらだら: uể oải, lề mề / ごろごろ: nằm lăn lười biếng / ぼやっと: lơ đãng","note":"Hay đi với 動く, 働く, 行進する. Động tác gọn, không chần chừ.","example":"新しい店員はきびきび働いている。","example_reading":"あたらしいてんいんはきびきびはたらいている。","example_meaning":"Nhân viên mới làm việc rất nhanh nhẹn.","examples":[{"example":"新しい店員はきびきび働いている。","example_reading":"あたらしいてんいんはきびきびはたらいている。","example_meaning":"Nhân viên mới làm việc rất nhanh nhẹn."},{"example":"隊員たちはきびきびと行進した。","example_reading":"たいいんたちはきびきびとこうしんした。","example_meaning":"Các đội viên diễu hành rất gọn gàng dứt khoát."}],"level":"b1"},
{"word":"いきいき","reading":"いきいき","meaning":"sinh động, đầy sức sống","antonym":"ぐったり: mệt rũ","note":"Hay đi với 働く, 輝く, 話す, 表情. Vẻ tràn đầy năng lượng.","example":"子どもたちは公園でいきいきと遊んでいる。","example_reading":"こどもたちはこうえんでいきいきとあそんでいる。","example_meaning":"Bọn trẻ chơi đầy sức sống ở công viên.","examples":[{"example":"子どもたちは公園でいきいきと遊んでいる。","example_reading":"こどもたちはこうえんでいきいきとあそんでいる。","example_meaning":"Bọn trẻ chơi đầy sức sống ở công viên."},{"example":"好きな仕事をしている彼女は、いきいきして見える。","example_reading":"すきなしごとをしているかのじょは、いきいきしてみえる。","example_meaning":"Cô ấy được làm công việc mình thích nên trông tràn đầy sức sống."}],"level":"b1"},
{"word":"のびのび","reading":"のびのび","meaning":"thoải mái, tự do tự tại","antonym":"窮屈に（きゅうくつに）: gò bó","antonym_hanviet":"cùng khuất","note":"Hay đi với 育つ, 暮らす, 過ごす. Không bị bó buộc, thoải mái phát triển.","example":"田舎で、子どもをのびのび育てたい。","example_reading":"いなかで、こどもをのびのびそだてたい。","example_meaning":"Tôi muốn nuôi con thoải mái tự do ở quê.","examples":[{"example":"田舎で、子どもをのびのび育てたい。","example_reading":"いなかで、こどもをのびのびそだてたい。","example_meaning":"Tôi muốn nuôi con thoải mái tự do ở quê."},{"example":"休日は、のびのびと好きなことをして過ごす。","example_reading":"きゅうじつは、のびのびとすきなことをしてすごす。","example_meaning":"Ngày nghỉ tôi thong thả làm điều mình thích."}],"level":"b1"},
{"word":"ぎりぎり","reading":"ぎりぎり","meaning":"sát nút, vừa đủ, suýt soát","antonym":"余裕で（よゆうで）: thong thả, dư dả","antonym_hanviet":"dư dụ","note":"Từ tượng hình. Chỉ giới hạn cuối cùng về thời gian hoặc số lượng.","example":"ぎりぎり電車に間に合いました。","example_reading":"ぎりぎりでんしゃにまにあいました。","example_meaning":"Tôi kịp tàu sát nút.","examples":[{"example":"ぎりぎり電車に間に合いました。","example_reading":"ぎりぎりでんしゃにまにあいました。","example_meaning":"Tôi kịp tàu sát nút."},{"example":"締め切りぎりぎりに、レポートを出した。","example_reading":"しめきりぎりぎりに、レポートをだした。","example_meaning":"Tôi nộp báo cáo sát hạn chót."}],"level":"b1"},
{"word":"ほんのり","reading":"ほんのり","meaning":"hơi hơi, thoang thoảng, phảng phất","antonym":"はっきり: rõ ràng","note":"Hay đi với 赤い, 甘い, 香る, 温かい. Mức độ nhẹ, dịu.","example":"彼女の頬がほんのり赤く染まった。","example_reading":"かのじょのほおがほんのりあかくそまった。","example_meaning":"Má cô ấy ửng hồng nhè nhẹ.","examples":[{"example":"彼女の頬がほんのり赤く染まった。","example_reading":"かのじょのほおがほんのりあかくそまった。","example_meaning":"Má cô ấy ửng hồng nhè nhẹ."},{"example":"部屋にほんのり花の香りが漂っている。","example_reading":"へやにほんのりはなのかおりがただよっている。","example_meaning":"Trong phòng thoang thoảng hương hoa."}],"level":"b1"},
{"word":"そわそわ","reading":"そわそわ","meaning":"bồn chồn, thấp thỏm, không yên","antonym":"落ち着いて（おちついて）: bình tĩnh","antonym_hanviet":"lạc trước","note":"Từ tượng hình. Hay đi với する, khi đang chờ đợi hoặc lo lắng.","example":"結果が気になって、そわそわしています。","example_reading":"けっかがきになって、そわそわしています。","example_meaning":"Tôi bồn chồn vì lo cho kết quả.","examples":[{"example":"結果が気になって、そわそわしています。","example_reading":"けっかがきになって、そわそわしています。","example_meaning":"Tôi bồn chồn vì lo cho kết quả."},{"example":"彼は試験の発表を前に、そわそわと落ち着かない。","example_reading":"かれはしけんのはっぴょうをまえに、そわそわとおちつかない。","example_meaning":"Trước giờ công bố kết quả thi, anh ấy bồn chồn không yên."}],"level":"b1"},
{"word":"にこにこ","reading":"にこにこ","meaning":"tươi cười, cười hiền","note":"Từ tượng hình. Nụ cười dễ mến, hay đi với する／と.","antonym":"めそめそ: sụt sùi / むすっと: sưng sỉa","example":"彼女はいつもにこにこしています。","example_reading":"かのじょはいつもにこにこしています。","example_meaning":"Cô ấy lúc nào cũng tươi cười.","examples":[{"example":"彼女はいつもにこにこしています。","example_reading":"かのじょはいつもにこにこしています。","example_meaning":"Cô ấy lúc nào cũng tươi cười."},{"example":"赤ちゃんは、にこにこ笑って、手を振った。","example_reading":"あかちゃんは、にこにこわらって、てをふった。","example_meaning":"Em bé cười tươi rồi vẫy tay."}],"level":"b1"},
{"word":"にっこり","reading":"にっこり","meaning":"mỉm cười","antonym":"むっと: cáu, nổi giận thoáng qua / むすっと: sưng sỉa","note":"Cười một lần, thoáng qua (khác にこにこ là cười liên tục). Hay đi với 笑う, 微笑む.","example":"先生はにっこり笑って、私の質問に答えてくれた。","example_reading":"せんせいはにっこりわらって、わたしのしつもんにこたえてくれた。","example_meaning":"Thầy mỉm cười và trả lời câu hỏi của tôi.","examples":[{"example":"先生はにっこり笑って、私の質問に答えてくれた。","example_reading":"せんせいはにっこりわらって、わたしのしつもんにこたえてくれた。","example_meaning":"Thầy mỉm cười và trả lời câu hỏi của tôi."},{"example":"写真を撮るから、にっこりしてね。","example_reading":"しゃしんをとるから、にっこりしてね。","example_meaning":"Sắp chụp ảnh nên cười tươi lên nhé."}],"level":"b1"},
{"word":"ざわざわ","reading":"ざわざわ","meaning":"xôn xao; xào xạc","antonym":"しーん: im phăng phắc","note":"Hay đi với 騒ぐ, 木の葉, 会場. Nhiều người nói nhỏ hoặc lá cây xào xạc.","example":"発表が始まる前、会場がざわざわしていた。","example_reading":"はっぴょうがはじまるまえ、かいじょうがざわざわしていた。","example_meaning":"Trước khi buổi thuyết trình bắt đầu, hội trường xôn xao.","examples":[{"example":"発表が始まる前、会場がざわざわしていた。","example_reading":"はっぴょうがはじまるまえ、かいじょうがざわざわしていた。","example_meaning":"Trước khi buổi thuyết trình bắt đầu, hội trường xôn xao."},{"example":"風で木の葉がざわざわと音を立てた。","example_reading":"かぜでこのはがざわざわとおとをたてた。","example_meaning":"Lá cây xào xạc trong gió."}],"level":"b1"},
{"word":"わいわい","reading":"わいわい","meaning":"ồn ào náo nhiệt vui vẻ","antonym":"しんみり: trầm lắng, bùi ngùi","note":"Nhiều người nói cười rôm rả. Hay đi với 騒ぐ, 言う.","example":"友達とわいわい言いながら、鍋を囲んだ。","example_reading":"ともだちとわいわいいいながら、なべをかこんだ。","example_meaning":"Tôi vừa nói cười rôm rả với bạn bè vừa quây quần quanh nồi lẩu.","examples":[{"example":"友達とわいわい言いながら、鍋を囲んだ。","example_reading":"ともだちとわいわいいいながら、なべをかこんだ。","example_meaning":"Tôi vừa nói cười rôm rả với bạn bè vừa quây quần quanh nồi lẩu."},{"example":"教室の外で、子どもたちがわいわい騒いでいる。","example_reading":"きょうしつのそとで、こどもたちがわいわいさわいでいる。","example_meaning":"Ngoài lớp học, bọn trẻ đang ồn ào vui đùa."}],"level":"b1"},
{"word":"うろうろ","reading":"うろうろ","meaning":"đi lòng vòng, quanh quẩn không mục đích","antonym":"じっと: yên lặng, chăm chú","note":"Từ tượng hình. Hay đi với する, hơi mang sắc thái tiêu cực.","example":"道に迷って、駅の前をうろうろしました。","example_reading":"みちにまよって、えきのまえをうろうろしました。","example_meaning":"Tôi lạc đường nên đi quanh quẩn trước nhà ga.","examples":[{"example":"道に迷って、駅の前をうろうろしました。","example_reading":"みちにまよって、えきのまえをうろうろしました。","example_meaning":"Tôi lạc đường nên đi quanh quẩn trước nhà ga."},{"example":"犬が部屋の中をうろうろしている。","example_reading":"いぬがへやのなかをうろうろしている。","example_meaning":"Con chó đi quanh quẩn trong phòng."}],"level":"b1"},
{"word":"ふらっと","reading":"ふらっと","meaning":"tình cờ, ghé qua bất chợt","antonym":"前もって（まえもって）: định trước / 計画的に（けいかくてきに）: có kế hoạch","antonym_hanviet":"tiền / kế họa đích","note":"Hay đi với 立ち寄る, 現れる, 出かける. Làm gì đó nhẹ nhàng, không có dự định.","example":"散歩のついでに、ふらっと本屋に立ち寄った。","example_reading":"さんぽのついでに、ふらっとほんやにたちよった。","example_meaning":"Nhân tiện đi dạo, tôi tạt vào hiệu sách.","examples":[{"example":"散歩のついでに、ふらっと本屋に立ち寄った。","example_reading":"さんぽのついでに、ふらっとほんやにたちよった。","example_meaning":"Nhân tiện đi dạo, tôi tạt vào hiệu sách."},{"example":"友達がふらっと遊びに来た。","example_reading":"ともだちがふらっとあそびにきた。","example_meaning":"Bạn tôi bất chợt ghé chơi."}],"level":"b1"},
{"word":"ぶらぶら","reading":"ぶらぶら","meaning":"đi dạo vẩn vơ; nhàn rỗi","antonym":"せかせか: vội vã, hấp tấp","note":"Đi lang thang không mục đích, hoặc ăn không ngồi rồi. Hay đi với 歩く, する.","example":"休みの日は、街をぶらぶら歩くのが好きだ。","example_reading":"やすみのひは、まちをぶらぶらあるくのがすきだ。","example_meaning":"Ngày nghỉ tôi thích đi dạo vẩn vơ quanh phố.","examples":[{"example":"休みの日は、街をぶらぶら歩くのが好きだ。","example_reading":"やすみのひは、まちをぶらぶらあるくのがすきだ。","example_meaning":"Ngày nghỉ tôi thích đi dạo vẩn vơ quanh phố."},{"example":"彼は仕事もせず、毎日家でぶらぶらしている。","example_reading":"かれはしごともせず、まいにちいえでぶらぶらしている。","example_meaning":"Anh ta không đi làm, ngày nào cũng ở nhà ăn không ngồi rồi."}],"level":"b1"},
{"word":"じっくり","reading":"じっくり","meaning":"kỹ lưỡng, thong thả","antonym":"さっと: nhanh gọn / ざっと: đại khái / ちらっと: liếc qua","note":"Hay đi với 考える, 読む, 煮込む, 話し合う. Dành thời gian, không vội.","example":"大事なことなので、じっくり考えてから決めたい。","example_reading":"だいじなことなので、じっくりかんがえてからきめたい。","example_meaning":"Vì là việc quan trọng nên tôi muốn suy nghĩ kỹ rồi mới quyết định.","examples":[{"example":"大事なことなので、じっくり考えてから決めたい。","example_reading":"だいじなことなので、じっくりかんがえてからきめたい。","example_meaning":"Vì là việc quan trọng nên tôi muốn suy nghĩ kỹ rồi mới quyết định."},{"example":"野菜をじっくり煮込むと、甘みが増す。","example_reading":"やさいをじっくりにこむと、あまみがます。","example_meaning":"Hầm rau thật kỹ thì vị ngọt sẽ tăng lên."}],"level":"b1"},
{"word":"すたすた","reading":"すたすた","meaning":"bước nhanh đều đều","antonym":"とぼとぼ: lững thững, rũ rượi","note":"Đi nhanh, không do dự. Hay đi với 歩く, 行く.","example":"彼女は私に気づかず、すたすた歩いて行った。","example_reading":"かのじょはわたしにきづかず、すたすたあるいていった。","example_meaning":"Cô ấy không nhận ra tôi, cứ bước nhanh đi mất.","examples":[{"example":"彼女は私に気づかず、すたすた歩いて行った。","example_reading":"かのじょはわたしにきづかず、すたすたあるいていった。","example_meaning":"Cô ấy không nhận ra tôi, cứ bước nhanh đi mất."},{"example":"年を取っても、祖父は坂道をすたすた上る。","example_reading":"としをとっても、そふはさかみちをすたすたのぼる。","example_meaning":"Dù đã lớn tuổi, ông tôi vẫn bước thoăn thoắt lên dốc."}],"level":"b1"},
{"word":"ころころ","reading":"ころころ","meaning":"lăn tròn; (thay đổi) xoành xoạch","note":"Hay đi với 転がる, 変わる, 笑う. Vật tròn lăn, hoặc ý kiến thay đổi liên tục.","example":"ボールがころころと坂を転がっていった。","example_reading":"ボールがころころとさかをころがっていった。","example_meaning":"Quả bóng lăn tròn xuống dốc.","examples":[{"example":"ボールがころころと坂を転がっていった。","example_reading":"ボールがころころとさかをころがっていった。","example_meaning":"Quả bóng lăn tròn xuống dốc."},{"example":"彼は言うことがころころ変わるので、信用できない。","example_reading":"かれはいうことがころころかわるので、しんようできない。","example_meaning":"Anh ta nói thay đổi xoành xoạch nên không thể tin."}],"level":"b1"},
{"word":"じめじめ","reading":"じめじめ","meaning":"ẩm ướt, ẩm thấp; (tính cách) ủ dột","antonym":"からっと: khô thoáng / さらさら: khô ráo","note":"Hay đi với 梅雨, 天気, 部屋. Cũng dùng chỉ người hay u ám, bi quan.","example":"梅雨の時期は毎日じめじめして、洗濯物が乾かない。","example_reading":"つゆのじきはまいにちじめじめして、せんたくものがかわかない。","example_meaning":"Mùa mưa ngày nào cũng ẩm ướt, quần áo phơi không khô.","examples":[{"example":"梅雨の時期は毎日じめじめして、洗濯物が乾かない。","example_reading":"つゆのじきはまいにちじめじめして、せんたくものがかわかない。","example_meaning":"Mùa mưa ngày nào cũng ẩm ướt, quần áo phơi không khô."},{"example":"この部屋は日当たりが悪くて、じめじめしている。","example_reading":"このへやはひあたりがわるくて、じめじめしている。","example_meaning":"Căn phòng này ít nắng nên ẩm thấp."}],"level":"b1"},
{"word":"ごろごろ","reading":"ごろごろ","meaning":"nằm lăn lười biếng; (sấm) rền","antonym":"きびきび: nhanh nhẹn","note":"Từ tượng thanh/hình. Nghĩa 1: nằm dài ở nhà. Nghĩa 2: tiếng sấm hoặc vật nặng lăn.","example":"日曜日は一日中、家でごろごろしていました。","example_reading":"にちようびはいちにちじゅう、いえでごろごろしていました。","example_meaning":"Chủ nhật tôi nằm dài ở nhà cả ngày.","examples":[{"example":"日曜日は一日中、家でごろごろしていました。","example_reading":"にちようびはいちにちじゅう、いえでごろごろしていました。","example_meaning":"Chủ nhật tôi nằm dài ở nhà cả ngày."},{"example":"遠くで雷がごろごろと鳴っている。","example_reading":"とおくでかみなりがごろごろとなっている。","example_meaning":"Ở xa có tiếng sấm rền."}],"level":"b1"},
{"word":"ごちゃごちゃ","reading":"ごちゃごちゃ","meaning":"lộn xộn, bừa bộn; lải nhải","antonym":"きちんと: ngăn nắp / すっきり: gọn gàng","note":"Đồ vật chất lộn xộn, hoặc nói nhiều khó chịu. Hay đi với 部屋, 言う.","example":"机の上がごちゃごちゃで、書類が見つからない。","example_reading":"つくえのうえがごちゃごちゃで、しょるいがみつからない。","example_meaning":"Bàn làm việc bừa bộn nên tôi không tìm thấy tài liệu.","examples":[{"example":"机の上がごちゃごちゃで、書類が見つからない。","example_reading":"つくえのうえがごちゃごちゃで、しょるいがみつからない。","example_meaning":"Bàn làm việc bừa bộn nên tôi không tìm thấy tài liệu."},{"example":"ごちゃごちゃ言わないで、早くやりなさい。","example_reading":"ごちゃごちゃいわないで、はやくやりなさい。","example_meaning":"Đừng lải nhải nữa, làm nhanh đi."}],"level":"b1"},
{"word":"ぐちゃぐちゃ","reading":"ぐちゃぐちゃ","meaning":"nát bét, nhão nhoét; rối tung","antonym":"きちんと: ngăn nắp","note":"Hay đi với 髪, 部屋, 料理, 頭の中.","example":"雨の中を歩いて、靴がぐちゃぐちゃになった。","example_reading":"あめのなかをあるいて、くつがぐちゃぐちゃになった。","example_meaning":"Đi bộ trong mưa nên giày sũng nước nhão nhoét.","examples":[{"example":"雨の中を歩いて、靴がぐちゃぐちゃになった。","example_reading":"あめのなかをあるいて、くつがぐちゃぐちゃになった。","example_meaning":"Đi bộ trong mưa nên giày sũng nước nhão nhoét."},{"example":"頭の中がぐちゃぐちゃで、うまく考えられない。","example_reading":"あたまのなかがぐちゃぐちゃで、うまくかんがえられない。","example_meaning":"Đầu óc rối tung nên tôi không suy nghĩ nổi."}],"level":"b1"},
{"word":"めちゃくちゃ","reading":"めちゃくちゃ","meaning":"lung tung, tệ hại; cực kỳ","antonym":"きちんと: ngăn nắp","note":"Tình trạng hỏng bét, hoặc khẩu ngữ \"cực kỳ\". Hay đi với なる, ～だ.","example":"台風で、庭がめちゃくちゃになった。","example_reading":"たいふうで、にわがめちゃくちゃになった。","example_meaning":"Cơn bão làm khu vườn tan hoang.","examples":[{"example":"台風で、庭がめちゃくちゃになった。","example_reading":"たいふうで、にわがめちゃくちゃになった。","example_meaning":"Cơn bão làm khu vườn tan hoang."},{"example":"昨日のテストは、めちゃくちゃ難しかった。","example_reading":"きのうのテストは、めちゃくちゃむずかしかった。","example_meaning":"Bài kiểm tra hôm qua khó kinh khủng."}],"level":"b1"},
{"word":"ふらふら","reading":"ふらふら","meaning":"loạng choạng, chếnh choáng","antonym":"しっかり: vững vàng","note":"Từ tượng hình. Do ốm, mệt, say hoặc thiếu ngủ.","example":"熱があって、頭がふらふらします。","example_reading":"ねつがあって、あたまがふらふらします。","example_meaning":"Tôi bị sốt nên đầu choáng váng.","examples":[{"example":"熱があって、頭がふらふらします。","example_reading":"ねつがあって、あたまがふらふらします。","example_meaning":"Tôi bị sốt nên đầu choáng váng."},{"example":"徹夜で、足がふらふらだ。","example_reading":"てつやで、あしがふらふらだ。","example_meaning":"Thức trắng đêm nên chân tôi loạng choạng."}],"level":"b1"},
{"word":"くたくた","reading":"くたくた","meaning":"mệt rã rời; nhừ","antonym":"ぴんぴん: khỏe re","note":"Rất mệt. Hay đi với 疲れる, になる. Cũng nghĩa \"nấu nhừ\".","example":"一日中歩き回って、くたくたに疲れた。","example_reading":"いちにちじゅうあるきまわって、くたくたにつかれた。","example_meaning":"Đi bộ cả ngày nên tôi mệt rã rời.","examples":[{"example":"一日中歩き回って、くたくたに疲れた。","example_reading":"いちにちじゅうあるきまわって、くたくたにつかれた。","example_meaning":"Đi bộ cả ngày nên tôi mệt rã rời."},{"example":"くたくたに煮た野菜は、味がしみておいしい。","example_reading":"くたくたににたやさいは、あじがしみておいしい。","example_meaning":"Rau nấu nhừ thấm vị nên rất ngon."}],"level":"b1"},
{"word":"だらだら","reading":"だらだら","meaning":"lề mề, uể oải; kéo dài lê thê","antonym":"きびきび: nhanh nhẹn / てきぱき: nhanh gọn","note":"Hay đi với する, 過ごす, 長引く. Làm việc thiếu dứt khoát, kéo dài vô ích. だらだら汗 = mồ hôi chảy ròng ròng.","example":"休日は家でだらだら過ごすことが多い。","example_reading":"きゅうじつはいえでだらだらすごすことがおおい。","example_meaning":"Ngày nghỉ tôi thường ở nhà lười biếng cho qua ngày.","examples":[{"example":"休日は家でだらだら過ごすことが多い。","example_reading":"きゅうじつはいえでだらだらすごすことがおおい。","example_meaning":"Ngày nghỉ tôi thường ở nhà lười biếng cho qua ngày."},{"example":"会議がだらだらと長引いて、結論が出なかった。","example_reading":"かいぎがだらだらとながびいて、けつろんがでなかった。","example_meaning":"Cuộc họp kéo dài lê thê mà không đưa ra được kết luận."}],"level":"b1"},
{"word":"へとへと","reading":"へとへと","meaning":"mệt lả, kiệt sức","antonym":"ぴんぴん: khỏe re","note":"Mạnh hơn くたくた. Hay đi với 疲れる, になる.","example":"徹夜で仕事をして、へとへとだ。","example_reading":"てつやでしごとをして、へとへとだ。","example_meaning":"Thức trắng đêm làm việc nên tôi kiệt sức.","examples":[{"example":"徹夜で仕事をして、へとへとだ。","example_reading":"てつやでしごとをして、へとへとだ。","example_meaning":"Thức trắng đêm làm việc nên tôi kiệt sức."},{"example":"マラソンを走り終えて、足がへとへとになった。","example_reading":"マラソンをはしりおえて、あしがへとへとになった。","example_meaning":"Chạy xong marathon, chân tôi rã rời."}],"level":"b1"},
{"word":"うとうと","reading":"うとうと","meaning":"ngủ gà ngủ gật","antonym":"ぐっすり: ngủ say","note":"Ngủ chập chờn nhẹ. Hay đi với する, 眠る.","example":"電車の中で、うとうとしてしまった。","example_reading":"でんしゃのなかで、うとうとしてしまった。","example_meaning":"Tôi lỡ ngủ gà ngủ gật trên tàu.","examples":[{"example":"電車の中で、うとうとしてしまった。","example_reading":"でんしゃのなかで、うとうとしてしまった。","example_meaning":"Tôi lỡ ngủ gà ngủ gật trên tàu."},{"example":"暖かい日差しの中で、猫がうとうとしている。","example_reading":"あたたかいひざしのなかで、ねこがうとうとしている。","example_meaning":"Con mèo đang ngủ lim dim dưới nắng ấm."}],"level":"b1"},
{"word":"ずるずる","reading":"ずるずる","meaning":"lê lết; kéo dài mãi","antonym":"きっぱり: dứt khoát","note":"Kéo lê vật nặng, hoặc việc cứ kéo dài không dứt. Cũng chỉ tiếng húp mì. Hay đi với 引きずる, 続く.","example":"重い荷物を、ずるずる引きずって運んだ。","example_reading":"おもいにもつを、ずるずるひきずってはこんだ。","example_meaning":"Tôi kéo lê hành lý nặng để chuyển đi.","examples":[{"example":"重い荷物を、ずるずる引きずって運んだ。","example_reading":"おもいにもつを、ずるずるひきずってはこんだ。","example_meaning":"Tôi kéo lê hành lý nặng để chuyển đi."},{"example":"話し合いがずるずる長引いて、結論が出ない。","example_reading":"はなしあいがずるずるながびいて、けつろんがでない。","example_meaning":"Cuộc bàn bạc cứ kéo dài mãi nên không ra kết luận."}],"level":"b1"},
{"word":"ざあざあ","reading":"ざあざあ","meaning":"(Mưa) xối xả, ào ào","antonym":"しとしと: lất phất / ぽつぽつ: lác đác / ぽたぽた: tí tách","note":"Từ tượng thanh. Hay đi với 降る. Mưa nhẹ hơn: しとしと, mưa lất phất: ぱらぱら.","example":"朝から雨がざあざあ降っています。","example_reading":"あさからあめがざあざあふっています。","example_meaning":"Từ sáng mưa đã rơi xối xả.","examples":[{"example":"朝から雨がざあざあ降っています。","example_reading":"あさからあめがざあざあふっています。","example_meaning":"Từ sáng mưa đã rơi xối xả."},{"example":"急に、ざあざあと雨が降り出した。","example_reading":"きゅうに、ざあざあとあめがふりだした。","example_meaning":"Đột nhiên mưa xối xả đổ xuống."}],"level":"b1"},
{"word":"ちらっと","reading":"ちらっと","meaning":"liếc qua, thoáng thấy","antonym":"じっと: chăm chú / じっくり: kỹ lưỡng / まじまじ: chằm chằm","note":"Hay đi với 見る, 見える. Rất ngắn, dùng nhiều trong khẩu ngữ. Cũng nói ちらりと.","example":"彼女は時計をちらっと見て、席を立った。","example_reading":"かのじょはとけいをちらっとみて、せきをたった。","example_meaning":"Cô ấy liếc nhìn đồng hồ rồi đứng dậy.","examples":[{"example":"彼女は時計をちらっと見て、席を立った。","example_reading":"かのじょはとけいをちらっとみて、せきをたった。","example_meaning":"Cô ấy liếc nhìn đồng hồ rồi đứng dậy."},{"example":"窓の外にちらっと人影が見えた気がした。","example_reading":"まどのそとにちらっとひとかげがみえたきがした。","example_meaning":"Tôi có cảm giác thoáng thấy bóng người ngoài cửa sổ."}],"level":"b1"},
{"word":"ぽろぽろ","reading":"ぽろぽろ","meaning":"rơi lã chã; vụn ra","note":"Nước mắt rơi từng giọt, hoặc vật vụn rơi. Hay đi với 涙, こぼす, 崩れる.","example":"悲しい映画で、涙がぽろぽろこぼれた。","example_reading":"かなしいえいがで、なみだがぽろぽろこぼれた。","example_meaning":"Xem phim buồn, nước mắt tôi rơi lã chã.","examples":[{"example":"悲しい映画で、涙がぽろぽろこぼれた。","example_reading":"かなしいえいがで、なみだがぽろぽろこぼれた。","example_meaning":"Xem phim buồn, nước mắt tôi rơi lã chã."},{"example":"このクッキーは、食べるとぽろぽろ崩れる。","example_reading":"このクッキーは、たべるとぽろぽろくずれる。","example_meaning":"Cái bánh quy này ăn vào là vụn rơi tứ tung."}],"level":"b1"},
{"word":"ゆったり","reading":"ゆったり","meaning":"thong thả, rộng rãi thoải mái","antonym":"ぎゅうぎゅう: chật ních / せかせか: vội vã / どたばた: ầm ĩ","note":"Hay đi với 過ごす, 座る, した服. Không gấp gáp, không chật chội.","example":"休日は、温泉でゆったりと過ごしたい。","example_reading":"きゅうじつは、おんせんでゆったりとすごしたい。","example_meaning":"Ngày nghỉ tôi muốn thong thả ngâm suối nước nóng.","examples":[{"example":"休日は、温泉でゆったりと過ごしたい。","example_reading":"きゅうじつは、おんせんでゆったりとすごしたい。","example_meaning":"Ngày nghỉ tôi muốn thong thả ngâm suối nước nóng."},{"example":"このシャツはゆったりしていて、着心地がいい。","example_reading":"このシャツはゆったりしていて、きごこちがいい。","example_meaning":"Chiếc áo này rộng rãi nên mặc rất dễ chịu."}],"level":"b1"},
{"word":"どろどろ","reading":"どろどろ","meaning":"sền sệt; lầy lội, đầy bùn","antonym":"さらさら: khô ráo, mượt","note":"Hay đi với 汚れる, 溶ける. Chất lỏng đặc hoặc bẩn bùn.","example":"雨の中を走って、靴がどろどろになった。","example_reading":"あめのなかをはしって、くつがどろどろになった。","example_meaning":"Chạy dưới mưa nên giày dính đầy bùn.","examples":[{"example":"雨の中を走って、靴がどろどろになった。","example_reading":"あめのなかをはしって、くつがどろどろになった。","example_meaning":"Chạy dưới mưa nên giày dính đầy bùn."},{"example":"チョコレートを溶かして、どろどろにする。","example_reading":"チョコレートをとかして、どろどろにする。","example_meaning":"Làm tan sô cô la cho sền sệt."}],"level":"b1"},
{"word":"びしょびしょ","reading":"びしょびしょ","meaning":"ướt sũng","antonym":"からから: khô khốc","note":"Ướt đẫm nước. Hay đi với 濡れる, になる.","example":"傘を忘れて、びしょびしょに濡れてしまった。","example_reading":"かさをわすれて、びしょびしょにぬれてしまった。","example_meaning":"Quên ô nên tôi bị ướt sũng.","examples":[{"example":"傘を忘れて、びしょびしょに濡れてしまった。","example_reading":"かさをわすれて、びしょびしょにぬれてしまった。","example_meaning":"Quên ô nên tôi bị ướt sũng."},{"example":"洗濯物が、急な雨でびしょびしょだ。","example_reading":"せんたくぶつが、きゅうなあめでびしょびしょだ。","example_meaning":"Đồ phơi bị cơn mưa bất chợt làm ướt sũng."}],"level":"b1"},
{"word":"きっちり","reading":"きっちり","meaning":"chính xác, đúng khít; gọn gàng","antonym":"だらしなく: luộm thuộm","note":"Hay đi với 守る, 払う, 並べる, 時間. Không sai lệch, đâu ra đấy.","example":"彼は約束の時間にきっちり来る人だ。","example_reading":"かれはやくそくのじかんにきっちりくるひとだ。","example_meaning":"Anh ấy là người luôn đến đúng giờ hẹn.","examples":[{"example":"彼は約束の時間にきっちり来る人だ。","example_reading":"かれはやくそくのじかんにきっちりくるひとだ。","example_meaning":"Anh ấy là người luôn đến đúng giờ hẹn."},{"example":"家賃は毎月きっちり十日までに払っている。","example_reading":"やちんはまいつききっちりとおかまでにはらっている。","example_meaning":"Tôi trả tiền nhà đúng hạn trước ngày mùng 10 hàng tháng."}],"level":"b1"},
{"word":"ぺたぺた","reading":"ぺたぺた","meaning":"dính nhớp; lẹp xẹp","antonym":"さらさら: khô ráo, mượt","note":"Hay đi với 貼る, 触る, 歩く. Dính nhiều chỗ hoặc tiếng chân trần.","example":"壁にポスターをぺたぺた貼った。","example_reading":"かべにポスターをぺたぺたはった。","example_meaning":"Tôi dán áp phích lên tường khắp chỗ.","examples":[{"example":"壁にポスターをぺたぺた貼った。","example_reading":"かべにポスターをぺたぺたはった。","example_meaning":"Tôi dán áp phích lên tường khắp chỗ."},{"example":"裸足でぺたぺたと廊下を歩く音がした。","example_reading":"はだしでぺたぺたとろうかをあるくおとがした。","example_meaning":"Có tiếng chân trần lẹp xẹp đi trên hành lang."}],"level":"b1"},
{"word":"べたべた","reading":"べたべた","meaning":"dính nhớp, nhem nhép","note":"Từ tượng hình. Dùng cho mồ hôi, tay dính đường, đồ ăn dính. Đối lập: さらさら.","antonym":"さらさら: mượt khô ráo","example":"暑くて、汗で体がべたべたします。","example_reading":"あつくて、あせでからだがべたべたします。","example_meaning":"Trời nóng, mồ hôi làm người dính nhớp.","examples":[{"example":"暑くて、汗で体がべたべたします。","example_reading":"あつくて、あせでからだがべたべたします。","example_meaning":"Trời nóng, mồ hôi làm người dính nhớp."},{"example":"おやつを食べた子どもの手が、べたべたになっている。","example_reading":"おやつをたべたこどものてが、べたべたになっている。","example_meaning":"Tay đứa trẻ sau khi ăn bánh kẹo dính nhớp."}],"level":"b1"},
{"word":"ぬるぬる","reading":"ぬるぬる","meaning":"nhớt, trơn nhầy","antonym":"さらさら: khô ráo, mượt","note":"Bề mặt trơn có chất nhớt. Hay đi với 手, 魚, 床.","example":"魚を触ったら、手がぬるぬるした。","example_reading":"さかなをさわったら、てがぬるぬるした。","example_meaning":"Sờ vào con cá, tay tôi bị nhớt.","examples":[{"example":"魚を触ったら、手がぬるぬるした。","example_reading":"さかなをさわったら、てがぬるぬるした。","example_meaning":"Sờ vào con cá, tay tôi bị nhớt."},{"example":"風呂場の床がぬるぬるして、滑りやすい。","example_reading":"ふろばのゆかがぬるぬるして、すべりやすい。","example_meaning":"Sàn phòng tắm trơn nhớt nên dễ trượt."}],"level":"b1"},
{"word":"ごつごつ","reading":"ごつごつ","meaning":"gồ ghề, thô ráp","note":"Hay đi với 手, 岩, 道. Bề mặt cứng, lồi lõm.","antonym":"すべすべ: mịn màng / つるっと: trơn tuột","example":"山道はごつごつした岩だらけだった。","example_reading":"やまみちはごつごつしたいわだらけだった。","example_meaning":"Đường núi toàn đá gồ ghề.","examples":[{"example":"山道はごつごつした岩だらけだった。","example_reading":"やまみちはごつごつしたいわだらけだった。","example_meaning":"Đường núi toàn đá gồ ghề."},{"example":"父の手はごつごつしていて、大きかった。","example_reading":"ちちのてはごつごつしていて、おおきかった。","example_meaning":"Tay bố thô ráp và to."}],"level":"b1"},
{"word":"くしゃくしゃ","reading":"くしゃくしゃ","meaning":"nhàu nát; rối bù","antonym":"ぴんと: căng thẳng / きちんと: gọn gàng","note":"Hay đi với 紙, 髪, 顔. 顔をくしゃくしゃにする = mặt nhăn nhó (khóc/cười).","example":"かばんの中で、レシートがくしゃくしゃになっていた。","example_reading":"かばんのなかで、レシートがくしゃくしゃになっていた。","example_meaning":"Tờ hóa đơn trong cặp đã bị nhàu nát.","examples":[{"example":"かばんの中で、レシートがくしゃくしゃになっていた。","example_reading":"かばんのなかで、レシートがくしゃくしゃになっていた。","example_meaning":"Tờ hóa đơn trong cặp đã bị nhàu nát."},{"example":"彼女は顔をくしゃくしゃにして笑った。","example_reading":"かのじょはかおをくしゃくしゃにしてわらった。","example_meaning":"Cô ấy cười nhăn cả mặt."}],"level":"b1"},
{"word":"でこぼこ","reading":"でこぼこ","meaning":"gập ghềnh, lồi lõm","antonym":"つるつる: nhẵn, trơn","note":"Hay đi với 道, 地面. Mặt không phẳng. Cũng viết 凸凹.","example":"でこぼこの道を車がゆっくり走る。","example_reading":"でこぼこのみちをくるまがゆっくりはしる。","example_meaning":"Chiếc xe chạy chậm trên con đường gập ghềnh.","examples":[{"example":"でこぼこの道を車がゆっくり走る。","example_reading":"でこぼこのみちをくるまがゆっくりはしる。","example_meaning":"Chiếc xe chạy chậm trên con đường gập ghềnh."},{"example":"このテーブルは表面がでこぼこしている。","example_reading":"このテーブルはひょうめんがでこぼこしている。","example_meaning":"Bề mặt chiếc bàn này lồi lõm."}],"level":"b1"},
{"word":"ざらざら","reading":"ざらざら","meaning":"sần sùi, nhám","note":"Bề mặt không mịn. Hay đi với 手, 肌, 砂.","antonym":"つるつる: trơn láng / すべすべ: mịn màng / つるっと: trơn tuột","example":"乾燥して、手がざらざらになった。","example_reading":"かんそうして、てがざらざらになった。","example_meaning":"Da khô nên tay tôi trở nên sần sùi.","examples":[{"example":"乾燥して、手がざらざらになった。","example_reading":"かんそうして、てがざらざらになった。","example_meaning":"Da khô nên tay tôi trở nên sần sùi."},{"example":"窓を開けていたので、床が砂でざらざらしている。","example_reading":"まどをあけていたので、ゆかがすなでざらざらしている。","example_meaning":"Vì mở cửa sổ nên sàn nhà lổn nhổn cát."}],"level":"b1"},
{"word":"ぴたっと","reading":"ぴたっと","meaning":"dừng hẳn; khít","note":"Hay đi với 止まる, 合う, 貼る. Gần ぴたり, khẩu ngữ hơn.","example":"音楽がぴたっと止んで、部屋が静かになった。","example_reading":"おんがくがぴたっとやんで、へやがしずかになった。","example_meaning":"Âm nhạc chợt tắt hẳn, căn phòng trở nên yên tĩnh.","examples":[{"example":"音楽がぴたっと止んで、部屋が静かになった。","example_reading":"おんがくがぴたっとやんで、へやがしずかになった。","example_meaning":"Âm nhạc chợt tắt hẳn, căn phòng trở nên yên tĩnh."},{"example":"このシャツは、体にぴたっと合って着心地がいい。","example_reading":"このシャツは、からだにぴたっとあってきごこちがいい。","example_meaning":"Chiếc áo này ôm vừa khít người nên mặc rất dễ chịu."}],"level":"b1"},
{"word":"くるっと","reading":"くるっと","meaning":"xoay tròn một vòng","note":"Hay đi với 回る, 振り向く, 丸まる. Chuyển động xoay gọn một lần.","example":"彼女は、くるっと振り向いて笑った。","example_reading":"かのじょは、くるっとふりむいてわらった。","example_meaning":"Cô ấy xoay người lại và mỉm cười.","examples":[{"example":"彼女は、くるっと振り向いて笑った。","example_reading":"かのじょは、くるっとふりむいてわらった。","example_meaning":"Cô ấy xoay người lại và mỉm cười."},{"example":"猫が、くるっと体を丸めて眠った。","example_reading":"ねこが、くるっとからだをまるめてねむった。","example_meaning":"Con mèo cuộn tròn mình lại rồi ngủ."}],"level":"b1"},
{"word":"すべすべ","reading":"すべすべ","meaning":"mịn màng, trơn nhẵn","note":"Hay đi với 肌, 手触り. Bề mặt nhẵn, dễ chịu khi sờ.","antonym":"ざらざら: sần sùi / ごつごつ: gồ ghề / ごわごわ: cứng","example":"このクリームを塗ると、肌がすべすべになる。","example_reading":"このクリームをぬると、はだがすべすべになる。","example_meaning":"Bôi kem này da sẽ mịn màng.","examples":[{"example":"このクリームを塗ると、肌がすべすべになる。","example_reading":"このクリームをぬると、はだがすべすべになる。","example_meaning":"Bôi kem này da sẽ mịn màng."},{"example":"川の石は水で削られて、すべすべしている。","example_reading":"かわのいしはみずでけずられて、すべすべしている。","example_meaning":"Đá sông bị nước mài nên rất nhẵn."}],"level":"b1"},
{"word":"つるつる","reading":"つるつる","meaning":"trơn láng","antonym":"ざらざら: sần sùi / でこぼこ: gập ghềnh","note":"Bề mặt nhẵn bóng, dễ trượt. Hay đi với 肌, 滑る. Cũng chỉ tiếng húp mì trơn.","example":"赤ちゃんの肌は、つるつるしている。","example_reading":"あかちゃんのはだは、つるつるしている。","example_meaning":"Da em bé mịn màng láng mượt.","examples":[{"example":"赤ちゃんの肌は、つるつるしている。","example_reading":"あかちゃんのはだは、つるつるしている。","example_meaning":"Da em bé mịn màng láng mượt."},{"example":"道が凍って、つるつる滑った。","example_reading":"みちがこおって、つるつるすべった。","example_meaning":"Đường đóng băng nên trơn tuột."}],"level":"b1"},
{"word":"びっしょり","reading":"びっしょり","meaning":"ướt sũng (mồ hôi, mưa)","antonym":"からから: khô khốc / さらさら: khô ráo","note":"Hay đi với 汗, 濡れる. Dạng ぐっしょり thì nặng nước, nhão nhoẹt hơn.","example":"走ったので、シャツが汗でびっしょりだ。","example_reading":"はしったので、シャツがあせでびっしょりだ。","example_meaning":"Vì chạy nên áo sơ mi ướt đẫm mồ hôi.","examples":[{"example":"走ったので、シャツが汗でびっしょりだ。","example_reading":"はしったので、シャツがあせでびっしょりだ。","example_meaning":"Vì chạy nên áo sơ mi ướt đẫm mồ hôi."},{"example":"傘がなくて、雨でびっしょり濡れてしまった。","example_reading":"かさがなくて、あめでびっしょりぬれてしまった。","example_meaning":"Không có ô nên tôi bị mưa ướt sũng."}],"level":"b1"},
{"word":"ねばねば","reading":"ねばねば","meaning":"dính nhớt","antonym":"さらさら: khô ráo, mượt","note":"Chất dính, kéo sợi. Hay đi với 納豆, オクラ, 汗.","example":"納豆はねばねばしているので、苦手な人もいる。","example_reading":"なっとうはねばねばしているので、にがてなひともいる。","example_meaning":"Natto dính nhớt nên có người không ăn được.","examples":[{"example":"納豆はねばねばしているので、苦手な人もいる。","example_reading":"なっとうはねばねばしているので、にがてなひともいる。","example_meaning":"Natto dính nhớt nên có người không ăn được."},{"example":"汗をかいて、体中がねばねばして気持ち悪い。","example_reading":"あせをかいて、からだじゅうがねばねばしてきもちわるい。","example_meaning":"Đổ mồ hôi nên khắp người dính nhớp khó chịu."}],"level":"b1"},
{"word":"めっきり","reading":"めっきり","meaning":"rõ rệt, hẳn (thay đổi)","note":"Hay đi với 減る, 寒くなる, 老ける. Thay đổi rõ rệt, thường là chiều hướng giảm.","example":"十月に入って、朝晩がめっきり寒くなった。","example_reading":"じゅうがつにはいって、あさばんがめっきりさむくなった。","example_meaning":"Bước sang tháng Mười, sáng và tối lạnh hẳn đi.","examples":[{"example":"十月に入って、朝晩がめっきり寒くなった。","example_reading":"じゅうがつにはいって、あさばんがめっきりさむくなった。","example_meaning":"Bước sang tháng Mười, sáng và tối lạnh hẳn đi."},{"example":"祖父は去年からめっきり体力が落ちてしまった。","example_reading":"そふはきょねんからめっきりたいりょくがおちてしまった。","example_meaning":"Từ năm ngoái, thể lực ông tôi suy giảm rõ rệt."}],"level":"b1"},
{"word":"ふわっと","reading":"ふわっと","meaning":"nhẹ bẫng, phồng nhẹ","antonym":"ずっしり: nặng trĩu","note":"Hay đi với 浮かぶ, 香る, 膨らむ. Cũng nói ふわりと.","example":"風にカーテンがふわっと揺れた。","example_reading":"かぜにカーテンがふわっとゆれた。","example_meaning":"Tấm rèm khẽ lay trong gió.","examples":[{"example":"風にカーテンがふわっと揺れた。","example_reading":"かぜにカーテンがふわっとゆれた。","example_meaning":"Tấm rèm khẽ lay trong gió."},{"example":"焼きたてのケーキは、ふわっと柔らかかった。","example_reading":"やきたてのケーキは、ふわっとやわらかかった。","example_meaning":"Chiếc bánh mới nướng mềm xốp."}],"level":"b1"},
{"word":"しっとり","reading":"しっとり","meaning":"ẩm mượt; trầm lắng, thanh nhã","antonym":"かさかさ: khô ráp / さくさく: giòn tan / ぱりぱり: giòn rụm","note":"Hay đi với 肌, 髪, 雰囲気. Ẩm vừa phải hoặc không khí nhã nhặn.","example":"このクリームは肌がしっとりする。","example_reading":"このクリームははだがしっとりする。","example_meaning":"Kem này làm da ẩm mượt.","examples":[{"example":"このクリームは肌がしっとりする。","example_reading":"このクリームははだがしっとりする。","example_meaning":"Kem này làm da ẩm mượt."},{"example":"雨のあとの京都は、しっとりと落ち着いている。","example_reading":"あめのあとのきょうとは、しっとりとおちついている。","example_meaning":"Kyoto sau cơn mưa thật trầm lắng."}],"level":"b1"},
{"word":"さらさら","reading":"さらさら","meaning":"mượt, khô ráo, không dính","antonym":"べたべた: dính nhớp / どろどろ: sền sệt / ぺたぺた: dính nhớp","note":"Từ tượng hình. Dùng cho tóc, cát, chất lỏng loãng, vải.","example":"このシャンプーを使うと、髪がさらさらになります。","example_reading":"このシャンプーをつかうと、かみがさらさらになります。","example_meaning":"Dùng loại dầu gội này thì tóc sẽ mượt.","examples":[{"example":"このシャンプーを使うと、髪がさらさらになります。","example_reading":"このシャンプーをつかうと、かみがさらさらになります。","example_meaning":"Dùng loại dầu gội này thì tóc sẽ mượt."},{"example":"川の水がさらさらと流れている。","example_reading":"かわのみずがさらさらとながれている。","example_meaning":"Nước sông chảy róc rách."}],"level":"b1"},
{"word":"がらがら","reading":"がらがら","meaning":"vắng tanh; (giọng) khàn","note":"Hay đi với 空いている, 声. Rất vắng; giọng khàn đặc.","antonym":"ぱんぱん: căng phồng / ぎゅうぎゅう: chen chúc / ぎっしり: chật cứng","example":"平日の昼間なので、電車はがらがらだった。","example_reading":"へいじつのひるまなので、でんしゃはがらがらだった。","example_meaning":"Vì là ban ngày ngày thường nên tàu vắng tanh.","examples":[{"example":"平日の昼間なので、電車はがらがらだった。","example_reading":"へいじつのひるまなので、でんしゃはがらがらだった。","example_meaning":"Vì là ban ngày ngày thường nên tàu vắng tanh."},{"example":"風邪で声ががらがらになってしまった。","example_reading":"かぜでこえががらがらになってしまった。","example_meaning":"Bị cảm nên giọng tôi khàn đặc."}],"level":"b1"},
{"word":"ぽたぽた","reading":"ぽたぽた","meaning":"tí tách, nhỏ giọt","antonym":"ざあざあ: xối xả","note":"Hay đi với 落ちる, 垂れる. Giọt nước rơi từng giọt.","example":"蛇口からぽたぽた水が落ちているので、閉め直した。","example_reading":"じゃぐちからぽたぽたみずがおちているので、しめなおした。","example_meaning":"Vòi nước nhỏ giọt tí tách nên tôi vặn lại cho chặt.","examples":[{"example":"蛇口からぽたぽた水が落ちているので、閉め直した。","example_reading":"じゃぐちからぽたぽたみずがおちているので、しめなおした。","example_meaning":"Vòi nước nhỏ giọt tí tách nên tôi vặn lại cho chặt."},{"example":"傘をさし忘れて、髪からぽたぽた雫が垂れた。","example_reading":"かさをさしわすれて、かみからぽたぽたしずくがたれた。","example_meaning":"Quên che ô nên nước nhỏ giọt từ tóc xuống."}],"level":"b1"},
{"word":"かさかさ","reading":"かさかさ","meaning":"khô ráp; sột soạt","note":"Hay đi với 肌, 唇, 音. Khô thiếu nước, hoặc tiếng sột soạt.","antonym":"しっとり: ẩm mượt","example":"冬は空気が乾燥して、肌がかさかさになる。","example_reading":"ふゆはくうきがかんそうして、はだがかさかさになる。","example_meaning":"Mùa đông không khí khô nên da khô ráp.","examples":[{"example":"冬は空気が乾燥して、肌がかさかさになる。","example_reading":"ふゆはくうきがかんそうして、はだがかさかさになる。","example_meaning":"Mùa đông không khí khô nên da khô ráp."},{"example":"枯れ葉がかさかさと音を立てた。","example_reading":"かれはがかさかさとおとをたてた。","example_meaning":"Lá khô kêu sột soạt."}],"level":"b1"},
{"word":"からから","reading":"からから","meaning":"khô khốc, khô cạn","antonym":"びしょびしょ: ướt sũng / じとじと: Ẩm ướt / びっしょり: ướt sũng","note":"Khô hoàn toàn. Hay đi với 喉, 乾く, 空気.","example":"暑い中を歩いて、喉がからからだ。","example_reading":"あついなかをあるいて、のどがからからだ。","example_meaning":"Đi bộ trong nắng nóng nên cổ họng tôi khô khốc.","examples":[{"example":"暑い中を歩いて、喉がからからだ。","example_reading":"あついなかをあるいて、のどがからからだ。","example_meaning":"Đi bộ trong nắng nóng nên cổ họng tôi khô khốc."},{"example":"雨が降らず、田んぼの土がからからに乾いた。","example_reading":"あめがふらず、たんぼのつちがからからにかわいた。","example_meaning":"Không mưa nên đất ruộng khô nứt."}],"level":"b1"},
{"word":"ひんやり","reading":"ひんやり","meaning":"mát lạnh","note":"Cảm giác lạnh nhẹ dễ chịu. Hay đi với 空気, 風, 感触.","antonym":"ぽかぽか: ấm áp / ほかほか: nóng hổi / ぬくぬく: ấm áp thoải mái","example":"朝の山は、空気がひんやりして気持ちいい。","example_reading":"あさのやまは、くうきがひんやりしてきもちいい。","example_meaning":"Núi buổi sáng không khí mát lạnh rất dễ chịu.","examples":[{"example":"朝の山は、空気がひんやりして気持ちいい。","example_reading":"あさのやまは、くうきがひんやりしてきもちいい。","example_meaning":"Núi buổi sáng không khí mát lạnh rất dễ chịu."},{"example":"夏の夜、ひんやりした風が吹いてきた。","example_reading":"なつのよる、ひんやりしたかぜがふいてきた。","example_meaning":"Đêm hè, một làn gió mát lạnh thổi đến."}],"level":"b1"},
{"word":"もぐもぐ","reading":"もぐもぐ","meaning":"nhai nhóp nhép; lầm bầm","antonym":"はきはき: rành rọt","note":"Hay đi với 食べる, 言う. Nhai chậm trong miệng hoặc nói không rõ.","example":"赤ちゃんがパンをもぐもぐ食べている。","example_reading":"あかちゃんがパンをもぐもぐたべている。","example_meaning":"Em bé đang nhai bánh mì nhóp nhép.","examples":[{"example":"赤ちゃんがパンをもぐもぐ食べている。","example_reading":"あかちゃんがパンをもぐもぐたべている。","example_meaning":"Em bé đang nhai bánh mì nhóp nhép."},{"example":"彼は口の中でもぐもぐと何か言った。","example_reading":"かれはくちのなかでもぐもぐとなにかいった。","example_meaning":"Anh ấy lầm bầm điều gì đó trong miệng."}],"level":"b1"},
{"word":"もたもた","reading":"もたもた","meaning":"chậm chạp, lóng ngóng","antonym":"てきぱき: nhanh gọn / さっさと: nhanh nhanh / 素早く（すばやく）: nhanh nhẹn","antonym_hanviet":" /  / tố tảo","note":"Hay đi với する. Làm việc chậm, thiếu nhanh nhẹn, hàm ý chê trách.","example":"もたもたしていると、電車に乗り遅れるよ。","example_reading":"もたもたしていると、でんしゃにのりおくれるよ。","example_meaning":"Cứ chậm chạp thế này là lỡ tàu đấy.","examples":[{"example":"もたもたしていると、電車に乗り遅れるよ。","example_reading":"もたもたしていると、でんしゃにのりおくれるよ。","example_meaning":"Cứ chậm chạp thế này là lỡ tàu đấy."},{"example":"新入社員は操作に慣れず、もたもたしていた。","example_reading":"しんにゅうしゃいんはそうさになれず、もたもたしていた。","example_meaning":"Nhân viên mới chưa quen thao tác nên cứ lóng ngóng."}],"level":"b1"},
{"word":"ごくごく","reading":"ごくごく","meaning":"ừng ực (uống)","antonym":"ちびちび: từng chút một","note":"Hay đi với 飲む. Uống nhiều, liền một hơi.","example":"のどが渇いていたので、水をごくごく飲んだ。","example_reading":"のどがかわいていたので、みずをごくごくのんだ。","example_meaning":"Khát quá nên tôi uống nước ừng ực.","examples":[{"example":"のどが渇いていたので、水をごくごく飲んだ。","example_reading":"のどがかわいていたので、みずをごくごくのんだ。","example_meaning":"Khát quá nên tôi uống nước ừng ực."},{"example":"運動のあと、冷たいお茶をごくごくと飲み干した。","example_reading":"うんどうのあと、つめたいおちゃをごくごくとのみほした。","example_meaning":"Sau khi tập, tôi uống cạn ly trà lạnh ừng ực."}],"level":"b1"},
{"word":"がつがつ","reading":"がつがつ","meaning":"ngấu nghiến, tham ăn","antonym":"ちびちび: từng chút một","note":"Hay đi với 食べる. Ăn vội vàng vì rất đói; cũng chỉ sự tham lam.","example":"お腹がすいていたのか、彼はがつがつ食べた。","example_reading":"おなかがすいていたのか、かれはがつがつたべた。","example_meaning":"Chắc đói bụng nên anh ấy ăn ngấu nghiến.","examples":[{"example":"お腹がすいていたのか、彼はがつがつ食べた。","example_reading":"おなかがすいていたのか、かれはがつがつたべた。","example_meaning":"Chắc đói bụng nên anh ấy ăn ngấu nghiến."},{"example":"そんなにがつがつ食べると、体に悪いよ。","example_reading":"そんなにがつがつたべると、からだにわるいよ。","example_meaning":"Ăn ngấu nghiến như vậy là hại cho cơ thể đấy."}],"level":"b1"},
{"word":"ぱくぱく","reading":"ぱくぱく","meaning":"ăn lia lịa; (miệng) đớp đớp","antonym":"ちびちび: từng chút","note":"Hay đi với 食べる, 口を動かす. Ăn ngon miệng liên tục.","example":"息子はケーキをぱくぱく食べている。","example_reading":"むすこはケーキをぱくぱくたべている。","example_meaning":"Con trai tôi đang ăn bánh lia lịa.","examples":[{"example":"息子はケーキをぱくぱく食べている。","example_reading":"むすこはケーキをぱくぱくたべている。","example_meaning":"Con trai tôi đang ăn bánh lia lịa."},{"example":"魚が口をぱくぱくさせている。","example_reading":"さかながくちをぱくぱくさせている。","example_meaning":"Con cá đang đớp đớp miệng."}],"level":"b1"},
{"word":"ずるっと","reading":"ずるっと","meaning":"trượt, tuột một cái","note":"Hay đi với 滑る, 落ちる, 脱げる. Mất chỗ bám nên tụt đi.","example":"雨の日に、階段でずるっと滑って転んだ。","example_reading":"あめのひに、かいだんでずるっとすべってころんだ。","example_meaning":"Ngày mưa, tôi trượt chân ở cầu thang và ngã.","examples":[{"example":"雨の日に、階段でずるっと滑って転んだ。","example_reading":"あめのひに、かいだんでずるっとすべってころんだ。","example_meaning":"Ngày mưa, tôi trượt chân ở cầu thang và ngã."},{"example":"ズボンがずるっと下がって、慌てて引き上げた。","example_reading":"ズボンがずるっとさがって、あわててひきあげた。","example_meaning":"Quần tụt xuống một cái, tôi vội kéo lên."}],"level":"b1"},
{"word":"ぐいっと","reading":"ぐいっと","meaning":"mạnh tay (kéo, uống)","antonym":"そっと: nhẹ nhàng","note":"Hay đi với 引っ張る, 飲む, 押す. Làm dứt khoát bằng một động tác mạnh.","example":"彼は袖をぐいっと引っ張って、私を止めた。","example_reading":"かれはそでをぐいっとひっぱって、わたしをとめた。","example_meaning":"Anh ấy giật mạnh tay áo để giữ tôi lại.","examples":[{"example":"彼は袖をぐいっと引っ張って、私を止めた。","example_reading":"かれはそでをぐいっとひっぱって、わたしをとめた。","example_meaning":"Anh ấy giật mạnh tay áo để giữ tôi lại."},{"example":"コーヒーをぐいっと飲んで、仕事に戻った。","example_reading":"コーヒーをぐいっとのんで、しごとにもどった。","example_meaning":"Tôi nốc một ngụm cà phê rồi quay lại làm việc."}],"level":"b1"},
{"word":"ぐるっと","reading":"ぐるっと","meaning":"vòng quanh, xoay một vòng","note":"Hay đi với 回る, 見回す, 囲む. Cũng nói ぐるりと.","example":"部屋の中をぐるっと見回したが、誰もいなかった。","example_reading":"へやのなかをぐるっとみまわしたが、だれもいなかった。","example_meaning":"Tôi nhìn quanh phòng nhưng không có ai.","examples":[{"example":"部屋の中をぐるっと見回したが、誰もいなかった。","example_reading":"へやのなかをぐるっとみまわしたが、だれもいなかった。","example_meaning":"Tôi nhìn quanh phòng nhưng không có ai."},{"example":"家の周りをぐるっと塀が囲んでいる。","example_reading":"いえのまわりをぐるっとへいがかこんでいる。","example_meaning":"Một bức tường bao quanh nhà."}],"level":"b1"},
{"word":"ぞくぞく","reading":"ぞくぞく","meaning":"rùng mình (vì lạnh, sợ hay phấn khích)","note":"Hay đi với 寒気, 背中, する. Dùng cho cả sợ hãi lẫn hồi hộp phấn khích.","example":"風邪を引いたのか、朝から背中がぞくぞくする。","example_reading":"かぜをひいたのか、あさからせなかがぞくぞくする。","example_meaning":"Chắc bị cảm, từ sáng tôi đã thấy lạnh gai sống lưng.","examples":[{"example":"風邪を引いたのか、朝から背中がぞくぞくする。","example_reading":"かぜをひいたのか、あさからせなかがぞくぞくする。","example_meaning":"Chắc bị cảm, từ sáng tôi đã thấy lạnh gai sống lưng."},{"example":"優勝が決まる瞬間を見て、ぞくぞくした。","example_reading":"ゆうしょうがきまるしゅんかんをみて、ぞくぞくした。","example_meaning":"Nhìn khoảnh khắc chức vô địch được định đoạt, tôi rùng mình phấn khích."}],"level":"b1"},
{"word":"ちびちび","reading":"ちびちび","meaning":"từng chút một, nhấp từng ngụm","antonym":"ごくごく: ừng ực / がつがつ: ngấu nghiến / ぱくぱく: ăn lia lịa","note":"Hay đi với 飲む, 食べる, 使う. Làm từ từ, tiết kiệm.","example":"彼は熱いお茶をちびちび飲んでいる。","example_reading":"かれはあついおちゃをちびちびのんでいる。","example_meaning":"Anh ấy nhấp từng ngụm trà nóng.","examples":[{"example":"彼は熱いお茶をちびちび飲んでいる。","example_reading":"かれはあついおちゃをちびちびのんでいる。","example_meaning":"Anh ấy nhấp từng ngụm trà nóng."},{"example":"お小遣いをちびちび使って、月末まで持たせた。","example_reading":"おこづかいをちびちびつかって、げつまつまでもたせた。","example_meaning":"Tôi tiêu tiền tiêu vặt từng chút để cầm cự đến cuối tháng."}],"level":"b1"},
{"word":"ふわり","reading":"ふわり","meaning":"nhẹ nhàng (bay, phủ)","antonym":"どしん: rầm / ずしん: rầm","note":"Hay đi với 浮かぶ, 舞う, 香る. Cũng nói ふわりと.","example":"白いハンカチが、風にふわりと舞い上がった。","example_reading":"しろいハンカチが、かぜにふわりとまいあがった。","example_meaning":"Chiếc khăn tay trắng nhẹ nhàng bay lên trong gió.","examples":[{"example":"白いハンカチが、風にふわりと舞い上がった。","example_reading":"しろいハンカチが、かぜにふわりとまいあがった。","example_meaning":"Chiếc khăn tay trắng nhẹ nhàng bay lên trong gió."},{"example":"窓を開けると、花の香りがふわりと入ってきた。","example_reading":"まどをあけると、はなのかおりがふわりとはいってきた。","example_meaning":"Mở cửa sổ, hương hoa nhẹ nhàng ùa vào."}],"level":"b1"},
{"word":"じんわり","reading":"じんわり","meaning":"từ từ thấm, dần dần","antonym":"ぱっと: bỗng chốc / 一気に（いっきに）: một mạch","antonym_hanviet":" / nhất khí","note":"Hay đi với 温まる, 涙が出る, 広がる. Cảm giác hoặc cảm xúc thấm dần.","example":"温かいスープを飲むと、体がじんわり温まった。","example_reading":"あたたかいスープをのむと、からだがじんわりあたたまった。","example_meaning":"Uống bát súp nóng, cơ thể ấm dần lên.","examples":[{"example":"温かいスープを飲むと、体がじんわり温まった。","example_reading":"あたたかいスープをのむと、からだがじんわりあたたまった。","example_meaning":"Uống bát súp nóng, cơ thể ấm dần lên."},{"example":"友達の優しい言葉に、胸がじんわり熱くなった。","example_reading":"ともだちのやさしいことばに、むねがじんわりあつくなった。","example_meaning":"Nghe lời dịu dàng của bạn, lòng tôi ấm lên từ từ."}],"level":"b1"},
{"word":"ぴたり","reading":"ぴたり","meaning":"khít, đúng phóc; dừng hẳn","note":"Hay đi với 合う, 止まる, 当たる. Cũng nói ぴたりと.","example":"彼の予想はぴたりと当たった。","example_reading":"かれのよそうはぴたりとあたった。","example_meaning":"Dự đoán của anh ấy trúng phóc.","examples":[{"example":"彼の予想はぴたりと当たった。","example_reading":"かれのよそうはぴたりとあたった。","example_meaning":"Dự đoán của anh ấy trúng phóc."},{"example":"雨がぴたりと止んで、空が明るくなった。","example_reading":"あめがぴたりとやんで、そらがあかるくなった。","example_meaning":"Mưa tạnh hẳn, bầu trời sáng lên."}],"level":"b1"},
{"word":"むしゃむしゃ","reading":"むしゃむしゃ","meaning":"ăn ngồm ngoàm","antonym":"ちびちび: từng chút / 少しずつ（すこしずつ）: từng chút một","antonym_hanviet":" / thiểu","note":"Hay đi với 食べる. Ăn ngon lành, nhai mạnh.","example":"お腹がすいていた弟は、ご飯をむしゃむしゃ食べた。","example_reading":"おなかがすいていたおとうとは、ごはんをむしゃむしゃたべた。","example_meaning":"Em trai đói bụng nên ăn cơm ngồm ngoàm.","examples":[{"example":"お腹がすいていた弟は、ご飯をむしゃむしゃ食べた。","example_reading":"おなかがすいていたおとうとは、ごはんをむしゃむしゃたべた。","example_meaning":"Em trai đói bụng nên ăn cơm ngồm ngoàm."},{"example":"ヤギが草をむしゃむしゃ食べている。","example_reading":"ヤギがくさをむしゃむしゃたべている。","example_meaning":"Con dê đang nhai cỏ ngồm ngoàm."}],"level":"b1"},
{"word":"ぺこぺこ","reading":"ぺこぺこ","meaning":"đói meo, bụng đói cồn cào","antonym":"満腹で（まんぷくで）: no bụng","antonym_hanviet":"mãn phúc","note":"Từ tượng hình. Thường dùng trong cụm お腹がぺこぺこ.","example":"朝ご飯を食べなかったので、お腹がぺこぺこです。","example_reading":"あさごはんをたべなかったので、おなかがぺこぺこです。","example_meaning":"Vì không ăn sáng nên bụng đói meo.","examples":[{"example":"朝ご飯を食べなかったので、お腹がぺこぺこです。","example_reading":"あさごはんをたべなかったので、おなかがぺこぺこです。","example_meaning":"Vì không ăn sáng nên bụng đói meo."},{"example":"運動したら、お腹がぺこぺこになった。","example_reading":"うんどうしたら、おなかがぺこぺこになった。","example_meaning":"Vận động xong, bụng tôi đói meo."}],"level":"b1"},
{"word":"くるくる","reading":"くるくる","meaning":"xoay tròn; cuộn tròn","note":"Hay đi với 回る, 巻く, 変わる. Quay nhẹ liên tục.","example":"子どもがくるくる回って遊んでいる。","example_reading":"こどもがくるくるまわってあそんでいる。","example_meaning":"Đứa bé đang xoay tròn chơi.","examples":[{"example":"子どもがくるくる回って遊んでいる。","example_reading":"こどもがくるくるまわってあそんでいる。","example_meaning":"Đứa bé đang xoay tròn chơi."},{"example":"髪をくるくると丸めて、ピンで留めた。","example_reading":"かみをくるくるとまるめて、ピンでとめた。","example_meaning":"Tôi cuộn tóc lại rồi cài kẹp."}],"level":"b1"},
{"word":"ふっくら","reading":"ふっくら","meaning":"phồng mềm, đầy đặn","antonym":"げっそり: hốc hác / がりがり: gầy trơ xương","note":"Hay đi với 焼き上がる, 炊ける, 頬. Mềm xốp, tròn đầy.","example":"ふっくらと焼き上がったパンの香りが部屋に広がった。","example_reading":"ふっくらとやきあがったパンのかおりがへやにひろがった。","example_meaning":"Mùi bánh mì nướng phồng xốp lan khắp phòng.","examples":[{"example":"ふっくらと焼き上がったパンの香りが部屋に広がった。","example_reading":"ふっくらとやきあがったパンのかおりがへやにひろがった。","example_meaning":"Mùi bánh mì nướng phồng xốp lan khắp phòng."},{"example":"赤ちゃんはふっくらした頬が愛らしい。","example_reading":"あかちゃんはふっくらしたほおがあいらしい。","example_meaning":"Em bé có đôi má phúng phính thật đáng yêu."}],"level":"b1"},
{"word":"ぴょんぴょん","reading":"ぴょんぴょん","meaning":"nhảy tưng tưng","note":"Hay đi với 跳ねる. Nhảy liên tiếp nhẹ nhàng.","example":"うさぎが草原をぴょんぴょん跳ねている。","example_reading":"うさぎがそうげんをぴょんぴょんはねている。","example_meaning":"Con thỏ nhảy tưng tưng trên đồng cỏ.","examples":[{"example":"うさぎが草原をぴょんぴょん跳ねている。","example_reading":"うさぎがそうげんをぴょんぴょんはねている。","example_meaning":"Con thỏ nhảy tưng tưng trên đồng cỏ."},{"example":"子どもたちは嬉しくて、ぴょんぴょん飛び跳ねた。","example_reading":"こどもたちはうれしくて、ぴょんぴょんとびはねた。","example_meaning":"Bọn trẻ vui quá nên nhảy tưng tưng."}],"level":"b1"},
{"word":"ぐるぐる","reading":"ぐるぐる","meaning":"xoay vòng vòng, quay tròn","note":"Từ tượng hình. Hay đi với 回る, 巻く. Còn dùng khi chóng mặt: 目がぐるぐる回る.","example":"ぐるぐる回る遊園地の乗り物に乗りました。","example_reading":"ぐるぐるまわるゆうえんちののりものにのりました。","example_meaning":"Tôi đã đi trò chơi xoay vòng ở công viên giải trí.","examples":[{"example":"ぐるぐる回る遊園地の乗り物に乗りました。","example_reading":"ぐるぐるまわるゆうえんちののりものにのりました。","example_meaning":"Tôi đã đi trò chơi xoay vòng ở công viên giải trí."},{"example":"首にマフラーをぐるぐる巻いた。","example_reading":"くびにマフラーをぐるぐるまいた。","example_meaning":"Tôi quấn chiếc khăn quàng vòng vòng quanh cổ."}],"level":"b1"},
{"word":"うじうじ","reading":"うじうじ","meaning":"ấp úng, do dự, bứt rứt không dứt khoát","antonym":"はきはき: rành rọt / きっぱり: dứt khoát","note":"Hay đi với する, 悩む. Hàm ý chê người thiếu quyết đoán.","example":"うじうじしていないで、はっきり気持ちを伝えたら？","example_reading":"うじうじしていないで、はっきりきもちをつたえたら？","example_meaning":"Đừng ấp úng nữa, thử nói rõ cảm xúc của mình đi?","examples":[{"example":"うじうじしていないで、はっきり気持ちを伝えたら？","example_reading":"うじうじしていないで、はっきりきもちをつたえたら？","example_meaning":"Đừng ấp úng nữa, thử nói rõ cảm xúc của mình đi?"},{"example":"彼は失敗をいつまでもうじうじと気にしている。","example_reading":"かれはしっぱいをいつまでもうじうじときにしている。","example_meaning":"Anh ấy cứ day dứt mãi về thất bại."}],"level":"b1"},
{"word":"ぽかぽか","reading":"ぽかぽか","meaning":"ấm áp, ấm dễ chịu","note":"Từ tượng hình. Dùng cho thời tiết xuân, nắng, cơ thể sau khi tắm.","antonym":"ひんやり: mát lạnh","example":"春になって、ぽかぽかした日が続いています。","example_reading":"はるになって、ぽかぽかしたひがつづいています。","example_meaning":"Sang xuân, những ngày ấm áp cứ nối tiếp.","examples":[{"example":"春になって、ぽかぽかした日が続いています。","example_reading":"はるになって、ぽかぽかしたひがつづいています。","example_meaning":"Sang xuân, những ngày ấm áp cứ nối tiếp."},{"example":"お風呂に入って、体がぽかぽかに温まった。","example_reading":"おふろにはいって、からだがぽかぽかにあたたまった。","example_meaning":"Tắm xong, người tôi ấm áp dễ chịu."}],"level":"b1"},
{"word":"ほかほか","reading":"ほかほか","meaning":"nóng hổi, ấm áp","note":"Thức ăn còn nóng hoặc cơ thể ấm lên. Hay đi với ご飯, 焼き芋, 体.","antonym":"ひんやり: mát lạnh","example":"ほかほかのご飯に、味噌汁があれば十分だ。","example_reading":"ほかほかのごはんに、みそしるがあればじゅうぶんだ。","example_meaning":"Chỉ cần cơm nóng hổi và canh miso là đủ.","examples":[{"example":"ほかほかのご飯に、味噌汁があれば十分だ。","example_reading":"ほかほかのごはんに、みそしるがあればじゅうぶんだ。","example_meaning":"Chỉ cần cơm nóng hổi và canh miso là đủ."},{"example":"風呂上がりで、体がほかほかしている。","example_reading":"ふろあがりで、からだがほかほかしている。","example_meaning":"Vừa tắm xong nên người ấm áp."}],"level":"b1"},
{"word":"ぐしゃぐしゃ","reading":"ぐしゃぐしゃ","meaning":"nát bét, bị bóp méo; rối tung","antonym":"きちんと: gọn gàng / ぴしっと: phẳng phiu","note":"Hay đi với 潰れる, 髪, 紙. Mạnh hơn くしゃくしゃ, bị phá hỏng hẳn hình dạng.","example":"箱が踏まれて、ぐしゃぐしゃに潰れてしまった。","example_reading":"はこがふまれて、ぐしゃぐしゃにつぶれてしまった。","example_meaning":"Chiếc hộp bị giẫm nát bét.","examples":[{"example":"箱が踏まれて、ぐしゃぐしゃに潰れてしまった。","example_reading":"はこがふまれて、ぐしゃぐしゃにつぶれてしまった。","example_meaning":"Chiếc hộp bị giẫm nát bét."},{"example":"風で髪がぐしゃぐしゃになった。","example_reading":"かぜでかみがぐしゃぐしゃになった。","example_meaning":"Tóc tôi bị gió thổi rối tung."}],"level":"b1"},
{"word":"ふんわり","reading":"ふんわり","meaning":"mềm xốp, nhẹ nhàng","antonym":"ずっしり: nặng trĩu / かちかち: cứng ngắc","note":"Nhẹ và mềm. Hay đi với パン, 笑う, 香る.","example":"このパンは、ふんわりしていてとても柔らかい。","example_reading":"このパンは、ふんわりしていてとてもやわらかい。","example_meaning":"Bánh mì này mềm xốp và rất mềm.","examples":[{"example":"このパンは、ふんわりしていてとても柔らかい。","example_reading":"このパンは、ふんわりしていてとてもやわらかい。","example_meaning":"Bánh mì này mềm xốp và rất mềm."},{"example":"春の風に乗って、ふんわりと花の香りが漂ってきた。","example_reading":"はるのかぜにのって、ふんわりとはなのかおりがただよってきた。","example_meaning":"Theo làn gió xuân, hương hoa thoang thoảng bay tới."}],"level":"b1"},
{"word":"めきめき","reading":"めきめき","meaning":"tiến bộ nhanh rõ rệt","antonym":"停滞して（ていたいして）: trì trệ / 伸び悩んで（のびなやんで）: chững lại","antonym_hanviet":"đình trệ / thân não","note":"Hay đi với 上達する, 腕を上げる, 頭角を現す.","example":"毎日練習したおかげで、ピアノがめきめき上達した。","example_reading":"まいにちれんしゅうしたおかげで、ピアノがめきめきじょうたつした。","example_meaning":"Nhờ luyện tập mỗi ngày, tôi chơi piano tiến bộ nhanh thấy rõ.","examples":[{"example":"毎日練習したおかげで、ピアノがめきめき上達した。","example_reading":"まいにちれんしゅうしたおかげで、ピアノがめきめきじょうたつした。","example_meaning":"Nhờ luyện tập mỗi ngày, tôi chơi piano tiến bộ nhanh thấy rõ."},{"example":"彼は入社して二年で、めきめき頭角を現した。","example_reading":"かれはにゅうしゃしてにねんで、めきめきとうかくをあらわした。","example_meaning":"Vào công ty hai năm, anh ấy đã nổi bật lên nhanh chóng."}],"level":"b1"},
{"word":"かっと","reading":"かっと","meaning":"nóng bừng, bùng nổ (giận)","antonym":"冷静に（れいせいに）: bình tĩnh","antonym_hanviet":"lãnh tĩnh","note":"Hay đi với 怒る, なる, 顔が熱くなる.","example":"馬鹿にされて、かっとなって大声を出してしまった。","example_reading":"ばかにされて、かっとなっておおごえをだしてしまった。","example_meaning":"Bị coi thường, tôi nổi nóng và quát to.","examples":[{"example":"馬鹿にされて、かっとなって大声を出してしまった。","example_reading":"ばかにされて、かっとなっておおごえをだしてしまった。","example_meaning":"Bị coi thường, tôi nổi nóng và quát to."},{"example":"恥ずかしくて、顔がかっと熱くなった。","example_reading":"はずかしくて、かおがかっとあつくなった。","example_meaning":"Xấu hổ đến mức mặt nóng bừng."}],"level":"b1"},
{"word":"がたん","reading":"がたん","meaning":"rầm, cạch (vật rơi, rung)","note":"Hay đi với と, 倒れる, 揺れる. Tiếng vật đổ hoặc rung lên.","example":"椅子ががたんと倒れて、みんなが振り返った。","example_reading":"いすががたんとたおれて、みんながふりかえった。","example_meaning":"Chiếc ghế đổ đánh rầm, mọi người đều ngoái lại.","examples":[{"example":"椅子ががたんと倒れて、みんなが振り返った。","example_reading":"いすががたんとたおれて、みんながふりかえった。","example_meaning":"Chiếc ghế đổ đánh rầm, mọi người đều ngoái lại."},{"example":"トラックが、がたんと大きく揺れて止まった。","example_reading":"トラックが、がたんとおおきくゆれてとまった。","example_meaning":"Chiếc xe tải lắc mạnh cái rầm rồi dừng lại."}],"level":"b1"},
{"word":"どしん","reading":"どしん","meaning":"rầm, ịch (ngã, va nặng)","antonym":"ふわり: nhẹ nhàng","note":"Hay đi với と, 落ちる, 尻もちをつく.","example":"子どもが、どしんと尻もちをついた。","example_reading":"こどもが、どしんとしりもちをついた。","example_meaning":"Đứa bé ngã ngồi đánh ịch.","examples":[{"example":"子どもが、どしんと尻もちをついた。","example_reading":"こどもが、どしんとしりもちをついた。","example_meaning":"Đứa bé ngã ngồi đánh ịch."},{"example":"上の階から、どしんと大きな音がした。","example_reading":"うえのかいから、どしんとおおきなおとがした。","example_meaning":"Từ tầng trên vọng xuống tiếng rầm rất lớn."}],"level":"b1"},
{"word":"ばたっと","reading":"ばたっと","meaning":"phịch (ngã, đóng sập)","note":"Hay đi với 倒れる, 閉まる. Hơi nhẹ hơn どさっと.","example":"疲れ切って、ばたっとベッドに倒れ込んだ。","example_reading":"つかれきって、ばたっとベッドにたおれこんだ。","example_meaning":"Kiệt sức, tôi đổ phịch xuống giường.","examples":[{"example":"疲れ切って、ばたっとベッドに倒れ込んだ。","example_reading":"つかれきって、ばたっとベッドにたおれこんだ。","example_meaning":"Kiệt sức, tôi đổ phịch xuống giường."},{"example":"風でドアがばたっと閉まった。","example_reading":"かぜでドアがばたっとしまった。","example_meaning":"Cánh cửa sập đánh phịch vì gió."}],"level":"b1"},
{"word":"ぎゅーっと","reading":"ぎゅーっと","meaning":"siết chặt, ép sát","antonym":"ゆるゆる: lỏng lẻo","note":"Hay đi với 引っ張る, つぶる, 抱きしめる. Dùng lực kéo dài.","example":"ひもをぎゅーっと引っ張って、結び目を固くした。","example_reading":"ひもをぎゅーっとひっぱって、むすびめをかたくした。","example_meaning":"Tôi siết chặt sợi dây để nút buộc thật chắc.","examples":[{"example":"ひもをぎゅーっと引っ張って、結び目を固くした。","example_reading":"ひもをぎゅーっとひっぱって、むすびめをかたくした。","example_meaning":"Tôi siết chặt sợi dây để nút buộc thật chắc."},{"example":"目をぎゅーっとつぶって、願い事をした。","example_reading":"めをぎゅーっとつぶって、ねがいごとをした。","example_meaning":"Tôi nhắm chặt mắt rồi ước một điều."}],"level":"b1"},
{"word":"ぎょっと","reading":"ぎょっと","meaning":"giật mình, sững sờ","note":"Hay đi với する. Giật mình vì điều bất ngờ gây sợ hoặc sốc.","example":"暗い道で急に人が現れて、ぎょっとした。","example_reading":"くらいみちできゅうにひとがあらわれて、ぎょっとした。","example_meaning":"Trên con đường tối bỗng có người xuất hiện, tôi giật bắn mình.","examples":[{"example":"暗い道で急に人が現れて、ぎょっとした。","example_reading":"くらいみちできゅうにひとがあらわれて、ぎょっとした。","example_meaning":"Trên con đường tối bỗng có người xuất hiện, tôi giật bắn mình."},{"example":"請求書の金額を見て、思わずぎょっとした。","example_reading":"せいきゅうしょのきんがくをみて、おもわずぎょっとした。","example_meaning":"Nhìn số tiền trên hóa đơn, tôi bất giác sững người."}],"level":"b1"},
{"word":"ぞろぞろ","reading":"ぞろぞろ","meaning":"nối đuôi nhau, từng đoàn kéo đi","note":"Từ tượng hình. Nhiều người hoặc vật đi liền nhau, hay đi với と.","example":"映画が終わって、客がぞろぞろと出てきた。","example_reading":"えいががおわって、きゃくがぞろぞろとでてきた。","example_meaning":"Phim hết, khách nối đuôi nhau đi ra.","examples":[{"example":"映画が終わって、客がぞろぞろと出てきた。","example_reading":"えいががおわって、きゃくがぞろぞろとでてきた。","example_meaning":"Phim hết, khách nối đuôi nhau đi ra."},{"example":"授業が終わり、生徒がぞろぞろ教室から出てきた。","example_reading":"じゅぎょうがおわり、せいとがぞろぞろきょうしつからでてきた。","example_meaning":"Tan học, học sinh nối đuôi nhau ra khỏi lớp."}],"level":"b1"},
{"word":"ぽんと","reading":"ぽんと","meaning":"nhẹ tay, bụp một cái; (chi) thoải mái","note":"Hay đi với 叩く, 渡す, 出す. Làm nhẹ nhàng hoặc chi tiền hào phóng.","example":"先生は私の肩をぽんと叩いて、励ましてくれた。","example_reading":"せんせいはわたしのかたをぽんとたたいて、はげましてくれた。","example_meaning":"Thầy vỗ nhẹ vai tôi để động viên.","examples":[{"example":"先生は私の肩をぽんと叩いて、励ましてくれた。","example_reading":"せんせいはわたしのかたをぽんとたたいて、はげましてくれた。","example_meaning":"Thầy vỗ nhẹ vai tôi để động viên."},{"example":"彼は十万円をぽんと出して、新しいパソコンを買った。","example_reading":"かれはじゅうまんえんをぽんとだして、あたらしいパソコンをかった。","example_meaning":"Anh ấy chi phăng mười vạn yên mua máy tính mới."}],"level":"b1"},
{"word":"ばったり","reading":"ばったり","meaning":"tình cờ gặp; đổ phịch","note":"Hay đi với 会う, 倒れる. Gặp bất ngờ, ngã nhanh.","example":"街で、昔の同級生にばったり会った。","example_reading":"まちで、むかしのどうきゅうせいにばったりあった。","example_meaning":"Ngoài phố, tôi tình cờ gặp lại bạn học cũ.","examples":[{"example":"街で、昔の同級生にばったり会った。","example_reading":"まちで、むかしのどうきゅうせいにばったりあった。","example_meaning":"Ngoài phố, tôi tình cờ gặp lại bạn học cũ."},{"example":"彼は疲れ果てて、ばったりと倒れ込んだ。","example_reading":"かれはつかれはてて、ばったりとたおれこんだ。","example_meaning":"Anh ấy kiệt sức, đổ phịch xuống."}],"level":"b1"},
{"word":"もりもり","reading":"もりもり","meaning":"hăng hái ăn, tràn đầy sức","note":"Hay đi với 食べる, 力が湧く, 働く.","example":"食欲が戻って、ご飯をもりもり食べている。","example_reading":"しょくよくがもどって、ごはんをもりもりたべている。","example_meaning":"Ăn uống trở lại, tôi ăn cơm ngon lành.","examples":[{"example":"食欲が戻って、ご飯をもりもり食べている。","example_reading":"しょくよくがもどって、ごはんをもりもりたべている。","example_meaning":"Ăn uống trở lại, tôi ăn cơm ngon lành."},{"example":"新しい仕事を始めて、やる気がもりもり湧いてきた。","example_reading":"あたらしいしごとをはじめて、やるきがもりもりわいてきた。","example_meaning":"Bắt đầu công việc mới, tôi tràn đầy động lực."}],"level":"b1"},
{"word":"がっかり","reading":"がっかり","meaning":"thất vọng, chán nản","note":"Từ tượng hình. Hay đi với する, khi kỳ vọng không thành.","antonym":"ワクワク: háo hức","example":"試験に落ちて、がっかりしました。","example_reading":"しけんにおちて、がっかりしました。","example_meaning":"Tôi thất vọng vì thi trượt.","examples":[{"example":"試験に落ちて、がっかりしました。","example_reading":"しけんにおちて、がっかりしました。","example_meaning":"Tôi thất vọng vì thi trượt."},{"example":"楽しみにしていた旅行が中止になって、がっかりした。","example_reading":"たのしみにしていたりょこうがちゅうしになって、がっかりした。","example_meaning":"Chuyến du lịch mong chờ bị hủy, tôi thất vọng."}],"level":"b1"},
{"word":"うんざり","reading":"うんざり","meaning":"chán ngấy","note":"Chán đến mức không muốn nữa. Hay đi với する, ～にはうんざりだ.","antonym":"ワクワク: háo hức","example":"毎日同じ話を聞かされて、うんざりしている。","example_reading":"まいにちおなじはなしをきかされて、うんざりしている。","example_meaning":"Ngày nào cũng bị bắt nghe một chuyện nên tôi chán ngấy.","examples":[{"example":"毎日同じ話を聞かされて、うんざりしている。","example_reading":"まいにちおなじはなしをきかされて、うんざりしている。","example_meaning":"Ngày nào cũng bị bắt nghe một chuyện nên tôi chán ngấy."},{"example":"雨ばかりの天気には、もううんざりだ。","example_reading":"あめばかりのてんきには、もううんざりだ。","example_meaning":"Thời tiết toàn mưa, tôi chán ngấy rồi."}],"level":"b1"},
{"word":"ぴかっと","reading":"ぴかっと","meaning":"lóe sáng, chớp sáng","note":"Hay đi với 光る, 稲妻. Sáng lên một lần rồi tắt.","example":"空がぴかっと光って、すぐに雷の音がした。","example_reading":"そらがぴかっとひかって、すぐにかみなりのおとがした。","example_meaning":"Bầu trời chớp sáng rồi ngay sau đó có tiếng sấm.","examples":[{"example":"空がぴかっと光って、すぐに雷の音がした。","example_reading":"そらがぴかっとひかって、すぐにかみなりのおとがした。","example_meaning":"Bầu trời chớp sáng rồi ngay sau đó có tiếng sấm."},{"example":"暗い道で、懐中電灯がぴかっと光った。","example_reading":"くらいみちで、かいちゅうでんとうがぴかっとひかった。","example_meaning":"Trên con đường tối, chiếc đèn pin chợt lóe sáng."}],"level":"b1"},
{"word":"がっくり","reading":"がっくり","meaning":"thất vọng, ủ rũ","note":"Mất hết sức lực vì thất vọng. Hay đi với 肩を落とす, うなだれる.","antonym":"うきうき: hớn hở","example":"試合に負けて、彼はがっくりと肩を落とした。","example_reading":"しあいにまけて、かれはがっくりとかたをおとした。","example_meaning":"Thua trận, anh ấy rũ vai thất vọng.","examples":[{"example":"試合に負けて、彼はがっくりと肩を落とした。","example_reading":"しあいにまけて、かれはがっくりとかたをおとした。","example_meaning":"Thua trận, anh ấy rũ vai thất vọng."},{"example":"不合格の通知を見て、がっくりきた。","example_reading":"ふごうかくのつうちをみて、がっくりきた。","example_meaning":"Nhìn thông báo trượt, tôi thấy rã rời thất vọng."}],"level":"b1"},
{"word":"しょんぼり","reading":"しょんぼり","meaning":"buồn thiu, ủ rũ","note":"Dáng vẻ buồn bã, cô đơn. Hay đi với する, 立つ.","antonym":"うきうき: hớn hở","example":"叱られた子どもが、しょんぼりと立っている。","example_reading":"しかられたこどもが、しょんぼりとたっている。","example_meaning":"Đứa trẻ bị mắng đang đứng buồn thiu.","examples":[{"example":"叱られた子どもが、しょんぼりと立っている。","example_reading":"しかられたこどもが、しょんぼりとたっている。","example_meaning":"Đứa trẻ bị mắng đang đứng buồn thiu."},{"example":"犬は飼い主が出かけると、しょんぼりしている。","example_reading":"いぬはかいぬしがでかけると、しょんぼりしている。","example_meaning":"Khi chủ ra ngoài, con chó buồn thiu hẳn."}],"level":"b1"},
{"word":"すっきり","reading":"すっきり","meaning":"sảng khoái, thông thoáng, gọn gàng","antonym":"もやもや: nặng trĩu, khó chịu / ごちゃごちゃ: lộn xộn / むかむか: buồn nôn","note":"Từ tượng hình. Dùng cho tâm trạng, căn phòng, vị đồ uống, thiết kế.","example":"部屋を片付けたら、気持ちもすっきりしました。","example_reading":"へやをかたづけたら、きもちもすっきりしました。","example_meaning":"Dọn phòng xong tâm trạng cũng nhẹ nhõm.","examples":[{"example":"部屋を片付けたら、気持ちもすっきりしました。","example_reading":"へやをかたづけたら、きもちもすっきりしました。","example_meaning":"Dọn phòng xong tâm trạng cũng nhẹ nhõm."},{"example":"この飲み物は、後味がすっきりしている。","example_reading":"こののみものは、あとあじがすっきりしている。","example_meaning":"Đồ uống này có hậu vị thanh mát."}],"level":"b1"},
{"word":"びっくり","reading":"びっくり","meaning":"giật mình, ngạc nhiên","antonym":"平然と（へいぜんと）: bình thản / けろっと: thản nhiên","antonym_hanviet":"bình nhiên / ","note":"Từ tượng hình. Hay đi với する. Mức mạnh hơn: びっくり仰天.","example":"突然名前を呼ばれて、びっくりしました。","example_reading":"とつぜんなまえをよばれて、びっくりしました。","example_meaning":"Bất ngờ bị gọi tên nên tôi giật mình.","examples":[{"example":"突然名前を呼ばれて、びっくりしました。","example_reading":"とつぜんなまえをよばれて、びっくりしました。","example_meaning":"Bất ngờ bị gọi tên nên tôi giật mình."},{"example":"彼の年を聞いて、びっくりした。","example_reading":"かれのとしをきいて、びっくりした。","example_meaning":"Nghe tuổi của anh ấy, tôi giật mình."}],"level":"b1"},
{"word":"ぱちぱち","reading":"ぱちぱち","meaning":"lách tách; vỗ tay giòn giã","note":"Hay đi với 燃える, 拍手, まばたき. Tiếng nổ nhỏ liên tiếp.","example":"暖炉の薪がぱちぱちと音を立てて燃えている。","example_reading":"だんろのまきがぱちぱちとおとをたててもえている。","example_meaning":"Củi trong lò sưởi cháy lách tách.","examples":[{"example":"暖炉の薪がぱちぱちと音を立てて燃えている。","example_reading":"だんろのまきがぱちぱちとおとをたててもえている。","example_meaning":"Củi trong lò sưởi cháy lách tách."},{"example":"演奏が終わると、観客はぱちぱちと拍手を送った。","example_reading":"えんそうがおわると、かんきゃくはぱちぱちとはくしゅをおくった。","example_meaning":"Biểu diễn kết thúc, khán giả vỗ tay giòn giã."}],"level":"b1"},
{"word":"しーん","reading":"しーん","meaning":"im phăng phắc","antonym":"がやがや: ồn ào / ざわざわ: xôn xao","note":"Hay đi với と, する, 静まり返る. Không một tiếng động.","example":"先生が入ってくると、教室はしーんと静まり返った。","example_reading":"せんせいがはいってくると、きょうしつはしーんとしずまりかえった。","example_meaning":"Khi thầy bước vào, lớp học im phăng phắc.","examples":[{"example":"先生が入ってくると、教室はしーんと静まり返った。","example_reading":"せんせいがはいってくると、きょうしつはしーんとしずまりかえった。","example_meaning":"Khi thầy bước vào, lớp học im phăng phắc."},{"example":"夜の図書館はしーんとしていて、足音まで響く。","example_reading":"よるのとしょかんはしーんとしていて、あしおとまでひびく。","example_meaning":"Thư viện ban đêm im ắng đến mức cả tiếng bước chân cũng vang."}],"level":"b1"},
{"word":"どきっと","reading":"どきっと","meaning":"giật thót tim","note":"Bất ngờ làm tim đập mạnh một cái. Hay đi với する.","example":"突然名前を呼ばれて、どきっとした。","example_reading":"とつぜんなまえをよばれて、どきっとした。","example_meaning":"Đột ngột bị gọi tên, tôi giật thót tim.","examples":[{"example":"突然名前を呼ばれて、どきっとした。","example_reading":"とつぜんなまえをよばれて、どきっとした。","example_meaning":"Đột ngột bị gọi tên, tôi giật thót tim."},{"example":"夜道で後ろから足音が聞こえて、どきっとした。","example_reading":"よみちでうしろからあしおとがきこえて、どきっとした。","example_meaning":"Trên đường đêm nghe tiếng bước chân phía sau, tôi giật mình thót tim."}],"level":"b1"},
{"word":"ぎくっと","reading":"ぎくっと","meaning":"giật mình (bị nói trúng tâm tư)","note":"Giật mình vì bị chạm vào điều muốn giấu. Hay đi với する.","example":"隠していたことを聞かれて、ぎくっとした。","example_reading":"かくしていたことをきかれて、ぎくっとした。","example_meaning":"Bị hỏi đúng chuyện đang giấu, tôi giật thót mình.","examples":[{"example":"隠していたことを聞かれて、ぎくっとした。","example_reading":"かくしていたことをきかれて、ぎくっとした。","example_meaning":"Bị hỏi đúng chuyện đang giấu, tôi giật thót mình."},{"example":"先生と目が合って、思わずぎくっとした。","example_reading":"せんせいとめがあって、おもわずぎくっとした。","example_meaning":"Chạm mắt với thầy giáo, tôi bất giác giật mình."}],"level":"b1"},
{"word":"にこっと","reading":"にこっと","meaning":"mỉm cười (một cái)","antonym":"むっと: cáu / むすっと: sưng sỉa","note":"Hay đi với 笑う, する. Cười nhẹ một lần, thân thiện.","example":"彼女は私を見て、にこっと笑った。","example_reading":"かのじょはわたしをみて、にこっとわらった。","example_meaning":"Cô ấy nhìn tôi rồi mỉm cười.","examples":[{"example":"彼女は私を見て、にこっと笑った。","example_reading":"かのじょはわたしをみて、にこっとわらった。","example_meaning":"Cô ấy nhìn tôi rồi mỉm cười."},{"example":"店員さんがにこっとして、「いらっしゃいませ」と言った。","example_reading":"てんいんさんがにこっとして、「いらっしゃいませ」といった。","example_meaning":"Nhân viên mỉm cười và nói \"Xin chào quý khách\"."}],"level":"b1"},
{"word":"むかっと","reading":"むかっと","meaning":"tức giận bốc lên","antonym":"ほっと: nhẹ nhõm","note":"Hay đi với する, 腹が立つ. Nổi giận đột ngột.","example":"失礼な言い方をされて、思わずむかっとした。","example_reading":"しつれいないいかたをされて、おもわずむかっとした。","example_meaning":"Bị nói năng thiếu lịch sự, tôi bất giác nổi giận.","examples":[{"example":"失礼な言い方をされて、思わずむかっとした。","example_reading":"しつれいないいかたをされて、おもわずむかっとした。","example_meaning":"Bị nói năng thiếu lịch sự, tôi bất giác nổi giận."},{"example":"彼の態度を見て、むかっと腹が立った。","example_reading":"かれのたいどをみて、むかっとはらがたった。","example_meaning":"Thấy thái độ của anh ta, tôi nổi giận đùng đùng."}],"level":"b1"},
{"word":"ぽたり","reading":"ぽたり","meaning":"nhỏ một giọt","note":"Hay đi với と, 落ちる, 垂れる. Một giọt lớn rơi xuống.","example":"蛇口から、水滴がぽたりと落ちた。","example_reading":"じゃぐちから、すいてきがぽたりとおちた。","example_meaning":"Một giọt nước nhỏ xuống từ vòi.","examples":[{"example":"蛇口から、水滴がぽたりと落ちた。","example_reading":"じゃぐちから、すいてきがぽたりとおちた。","example_meaning":"Một giọt nước nhỏ xuống từ vòi."},{"example":"彼女の目から、大粒の涙がぽたりと机に落ちた。","example_reading":"かのじょのめから、おおつぶのなみだがぽたりとつくえにおちた。","example_meaning":"Giọt nước mắt to rơi xuống mặt bàn."}],"level":"b1"},
{"word":"ごっくん","reading":"ごっくん","meaning":"ực (nuốt một ngụm)","note":"Hay đi với と, 飲み込む. Nuốt trọn một lần, thường dùng với trẻ con.","example":"赤ちゃんは、ミルクをごっくんと飲み込んだ。","example_reading":"あかちゃんは、ミルクをごっくんとのみこんだ。","example_meaning":"Em bé nuốt ực ngụm sữa.","examples":[{"example":"赤ちゃんは、ミルクをごっくんと飲み込んだ。","example_reading":"あかちゃんは、ミルクをごっくんとのみこんだ。","example_meaning":"Em bé nuốt ực ngụm sữa."},{"example":"苦い薬を、水でごっくんと流し込んだ。","example_reading":"にがいくすりを、みずでごっくんとながしこんだ。","example_meaning":"Tôi nuốt ực viên thuốc đắng với nước."}],"level":"b1"},
{"word":"ぺろぺろ","reading":"ぺろぺろ","meaning":"liếm láp","note":"Hay đi với なめる, 食べる. Liếm liên tục.","example":"犬が、私の手をぺろぺろとなめた。","example_reading":"いぬが、わたしのてをぺろぺろとなめた。","example_meaning":"Con chó liếm láp tay tôi.","examples":[{"example":"犬が、私の手をぺろぺろとなめた。","example_reading":"いぬが、わたしのてをぺろぺろとなめた。","example_meaning":"Con chó liếm láp tay tôi."},{"example":"子どもが、アイスクリームをぺろぺろ食べている。","example_reading":"こどもが、アイスクリームをぺろぺろたべている。","example_meaning":"Đứa trẻ đang liếm kem."}],"level":"b1"},
{"word":"ぴょんと","reading":"ぴょんと","meaning":"nhảy bật lên","note":"Hay đi với 跳ねる, 飛び越える. Nhảy gọn một cái.","example":"カエルが、ぴょんと池に跳ねた。","example_reading":"カエルが、ぴょんといけにはねた。","example_meaning":"Con ếch nhảy phốc xuống ao.","examples":[{"example":"カエルが、ぴょんと池に跳ねた。","example_reading":"カエルが、ぴょんといけにはねた。","example_meaning":"Con ếch nhảy phốc xuống ao."},{"example":"彼は、ぴょんとベンチを飛び越えた。","example_reading":"かれは、ぴょんとベンチをとびこえた。","example_meaning":"Anh ấy nhảy phốc qua chiếc ghế dài."}],"level":"b1"},
{"word":"ひやっと","reading":"ひやっと","meaning":"lạnh người, giật thót","note":"Hay đi với する. Cảm giác lạnh hoặc thót tim vì suýt gặp nguy.","example":"階段を踏み外しそうになって、ひやっとした。","example_reading":"かいだんをふみはずしそうになって、ひやっとした。","example_meaning":"Suýt trượt chân ở cầu thang, tôi thót cả tim.","examples":[{"example":"階段を踏み外しそうになって、ひやっとした。","example_reading":"かいだんをふみはずしそうになって、ひやっとした。","example_meaning":"Suýt trượt chân ở cầu thang, tôi thót cả tim."},{"example":"首筋に冷たい水が落ちてきて、ひやっとした。","example_reading":"くびすじにつめたいみずがおちてきて、ひやっとした。","example_meaning":"Giọt nước lạnh rơi xuống gáy khiến tôi rùng mình."}],"level":"b1"},
{"word":"ぐらっと","reading":"ぐらっと","meaning":"rung lắc, chao đảo","note":"Hay đi với 揺れる, 傾く. Rung hoặc nghiêng mạnh một lần.","example":"地震で、建物がぐらっと大きく揺れた。","example_reading":"じしんで、たてものがぐらっとおおきくゆれた。","example_meaning":"Do động đất, tòa nhà rung lắc mạnh.","examples":[{"example":"地震で、建物がぐらっと大きく揺れた。","example_reading":"じしんで、たてものがぐらっとおおきくゆれた。","example_meaning":"Do động đất, tòa nhà rung lắc mạnh."},{"example":"バスが急に曲がって、体がぐらっと傾いた。","example_reading":"バスがきゅうにまがって、からだがぐらっとかたむいた。","example_meaning":"Xe buýt rẽ gấp khiến người tôi chao nghiêng."}],"level":"b1"},
{"word":"ぷるぷる","reading":"ぷるぷる","meaning":"rung rinh, run run","note":"Hay đi với ゼリー, 震える. Vật mềm rung nhẹ.","example":"このプリンはぷるぷるしていて、おいしい。","example_reading":"このプリンはぷるぷるしていて、おいしい。","example_meaning":"Bánh pudding này rung rinh và ngon.","examples":[{"example":"このプリンはぷるぷるしていて、おいしい。","example_reading":"このプリンはぷるぷるしていて、おいしい。","example_meaning":"Bánh pudding này rung rinh và ngon."},{"example":"寒くて、手がぷるぷる震えた。","example_reading":"さむくて、てがぷるぷるふるえた。","example_meaning":"Lạnh quá nên tay run run."}],"level":"b1"},
{"word":"ゆらゆら","reading":"ゆらゆら","meaning":"đung đưa, chập chờn","note":"Hay đi với 揺れる, 浮かぶ. Chuyển động nhẹ nhàng lặp lại.","example":"湖の上に、小さな船がゆらゆら浮かんでいる。","example_reading":"みずうみのうえに、ちいさなふねがゆらゆらうかんでいる。","example_meaning":"Trên hồ, chiếc thuyền nhỏ đung đưa trôi nổi.","examples":[{"example":"湖の上に、小さな船がゆらゆら浮かんでいる。","example_reading":"みずうみのうえに、ちいさなふねがゆらゆらうかんでいる。","example_meaning":"Trên hồ, chiếc thuyền nhỏ đung đưa trôi nổi."},{"example":"ろうそくの炎が、ゆらゆらと揺れていた。","example_reading":"ろうそくのほのおが、ゆらゆらとゆれていた。","example_meaning":"Ngọn nến chập chờn lay động."}],"level":"b1"},
{"word":"まごまご","reading":"まごまご","meaning":"lúng túng, bối rối không biết làm gì","antonym":"てきぱき: nhanh gọn","note":"Hay đi với する. Không biết đường hoặc cách làm nên đứng đơ.","example":"初めて来た駅で、出口が分からずまごまごしてしまった。","example_reading":"はじめてきたえきで、でぐちがわからずまごまごしてしまった。","example_meaning":"Ở nhà ga lần đầu đến, tôi không biết lối ra nên lúng túng.","examples":[{"example":"初めて来た駅で、出口が分からずまごまごしてしまった。","example_reading":"はじめてきたえきで、でぐちがわからずまごまごしてしまった。","example_meaning":"Ở nhà ga lần đầu đến, tôi không biết lối ra nên lúng túng."},{"example":"突然質問されて、まごまごして答えられなかった。","example_reading":"とつぜんしつもんされて、まごまごしてこたえられなかった。","example_meaning":"Bị hỏi đột ngột, tôi bối rối không trả lời được."}],"level":"b1"},
{"word":"ぐつぐつ","reading":"ぐつぐつ","meaning":"sôi sùng sục","antonym":"ことこと: sôi liu riu","note":"Hay đi với 煮える, 煮る. Sôi mạnh hơn ことこと.","example":"鍋がぐつぐつ煮えてきたら、火を弱めてください。","example_reading":"なべがぐつぐつにえてきたら、ひをよわめてください。","example_meaning":"Khi nồi sôi sùng sục thì hãy giảm lửa.","examples":[{"example":"鍋がぐつぐつ煮えてきたら、火を弱めてください。","example_reading":"なべがぐつぐつにえてきたら、ひをよわめてください。","example_meaning":"Khi nồi sôi sùng sục thì hãy giảm lửa."},{"example":"寒い日は、ぐつぐつ煮えた鍋料理が食べたくなる。","example_reading":"さむいひは、ぐつぐつにえたなべりょうりがたべたくなる。","example_meaning":"Ngày lạnh tôi muốn ăn món lẩu sôi sùng sục."}],"level":"b1"},
{"word":"ぶるぶる","reading":"ぶるぶる","meaning":"run lẩy bẩy","note":"Hay đi với 震える. Run vì lạnh hoặc sợ hãi.","example":"雪の中で、寒さにぶるぶる震えた。","example_reading":"ゆきのなかで、さむさにぶるぶるふるえた。","example_meaning":"Giữa tuyết, tôi run lẩy bẩy vì lạnh.","examples":[{"example":"雪の中で、寒さにぶるぶる震えた。","example_reading":"ゆきのなかで、さむさにぶるぶるふるえた。","example_meaning":"Giữa tuyết, tôi run lẩy bẩy vì lạnh."},{"example":"犬は雷の音に驚いて、ぶるぶるしていた。","example_reading":"いぬはかみなりのおとにおどろいて、ぶるぶるしていた。","example_meaning":"Con chó giật mình vì tiếng sấm nên run lẩy bẩy."}],"level":"b1"},
{"word":"ぞっと","reading":"ぞっと","meaning":"rùng mình (vì sợ, ghê)","note":"Cảm giác lạnh người vì sợ hãi hoặc ghê tởm. Hay đi với する.","example":"あの事故を思い出すと、今でもぞっとする。","example_reading":"あのじこをおもいだすと、いまでもぞっとする。","example_meaning":"Nhớ lại vụ tai nạn đó, đến giờ tôi vẫn rùng mình.","examples":[{"example":"あの事故を思い出すと、今でもぞっとする。","example_reading":"あのじこをおもいだすと、いまでもぞっとする。","example_meaning":"Nhớ lại vụ tai nạn đó, đến giờ tôi vẫn rùng mình."},{"example":"部屋でゴキブリを見つけて、ぞっとした。","example_reading":"へやでごきぶりをみつけて、ぞっとした。","example_meaning":"Thấy con gián trong phòng, tôi rùng mình ghê sợ."}],"level":"b1"},
{"word":"かたかた","reading":"かたかた","meaning":"lạch cạch, lọc cọc","note":"Hay đi với 鳴る, 揺れる. Tiếng vật cứng chạm nhẹ vào nhau; cũng chỉ run lập cập.","example":"風で窓ガラスがかたかたと鳴っている。","example_reading":"かぜでまどガラスがかたかたとなっている。","example_meaning":"Gió làm kính cửa sổ kêu lạch cạch.","examples":[{"example":"風で窓ガラスがかたかたと鳴っている。","example_reading":"かぜでまどガラスがかたかたとなっている。","example_meaning":"Gió làm kính cửa sổ kêu lạch cạch."},{"example":"地震で、棚の上の食器がかたかた揺れた。","example_reading":"じしんで、たなのうえのしょっきがかたかたゆれた。","example_meaning":"Do động đất, chén đĩa trên kệ rung lạch cạch."}],"level":"b1"},
{"word":"はっと","reading":"はっと","meaning":"chợt, giật mình nhận ra","note":"Nhận ra hoặc bị bất ngờ trong chớp mắt. Hay đi với 気づく, 思い出す, 息をのむ.","example":"電車を降りたとき、傘を忘れたことにはっと気づいた。","example_reading":"でんしゃをおりたとき、かさをわすれたことにはっときづいた。","example_meaning":"Khi xuống tàu, tôi chợt nhận ra mình để quên ô.","examples":[{"example":"電車を降りたとき、傘を忘れたことにはっと気づいた。","example_reading":"でんしゃをおりたとき、かさをわすれたことにはっときづいた。","example_meaning":"Khi xuống tàu, tôi chợt nhận ra mình để quên ô."},{"example":"彼女の美しさに、はっと息をのんだ。","example_reading":"かのじょのうつくしさに、はっといきをのんだ。","example_meaning":"Tôi bất giác nín thở trước vẻ đẹp của cô ấy."}],"level":"b1"},
{"word":"しとしと","reading":"しとしと","meaning":"(Mưa) lất phất, rả rích","antonym":"ざあざあ: xối xả","note":"Từ tượng thanh/hình. Mưa nhẹ, êm, kéo dài. Mạnh hơn: ざあざあ.","example":"春の雨がしとしと降っている。","example_reading":"はるのあめがしとしとふっている。","example_meaning":"Mưa xuân rơi rả rích.","examples":[{"example":"春の雨がしとしと降っている。","example_reading":"はるのあめがしとしとふっている。","example_meaning":"Mưa xuân rơi rả rích."},{"example":"雨がしとしと降る静かな夜だった。","example_reading":"あめがしとしとふるしずかなよるだった。","example_meaning":"Đó là một đêm yên tĩnh có mưa rả rích."}],"level":"b1"},
{"word":"ぐうぐう","reading":"ぐうぐう","meaning":"ngáy khò khò; bụng sôi ục ục","note":"Hay đi với 寝る, お腹が鳴る. Ngủ say hoặc đói bụng.","example":"父はソファでぐうぐう寝てしまった。","example_reading":"ちちはソファでぐうぐうねてしまった。","example_meaning":"Bố ngủ say khò khò trên sofa.","examples":[{"example":"父はソファでぐうぐう寝てしまった。","example_reading":"ちちはソファでぐうぐうねてしまった。","example_meaning":"Bố ngủ say khò khò trên sofa."},{"example":"朝ご飯を抜いたので、お昼前にお腹がぐうぐう鳴った。","example_reading":"あさごはんをぬいたので、おひるまえにおなかがぐうぐうなった。","example_meaning":"Vì bỏ bữa sáng nên trước trưa bụng tôi sôi ục ục."}],"level":"b1"},
{"word":"ひらひら","reading":"ひらひら","meaning":"phấp phới, bay bay","note":"Hay đi với 舞う, 揺れる, 散る. Vật mỏng nhẹ bay lượn.","example":"桜の花びらがひらひらと舞い落ちた。","example_reading":"さくらのはなびらがひらひらとまいおちた。","example_meaning":"Cánh hoa anh đào rơi bay lả tả.","examples":[{"example":"桜の花びらがひらひらと舞い落ちた。","example_reading":"さくらのはなびらがひらひらとまいおちた。","example_meaning":"Cánh hoa anh đào rơi bay lả tả."},{"example":"窓のカーテンが風でひらひら揺れている。","example_reading":"まどのカーテンがかぜでひらひらゆれている。","example_meaning":"Rèm cửa sổ phấp phới trong gió."}],"level":"b1"},
{"word":"ぱらぱら","reading":"ぱらぱら","meaning":"(Mưa) lác đác; rải rời, lật nhanh","antonym":"ざあざあ: xối xả","note":"Từ tượng thanh. Hạt mưa thưa; cũng dùng khi lật trang sách.","example":"雨がぱらぱらと降ってきた。","example_reading":"あめがぱらぱらとふってきた。","example_meaning":"Mưa bắt đầu rơi lác đác.","examples":[{"example":"雨がぱらぱらと降ってきた。","example_reading":"あめがぱらぱらとふってきた。","example_meaning":"Mưa bắt đầu rơi lác đác."},{"example":"本をぱらぱらとめくって、内容を確かめた。","example_reading":"ほんをぱらぱらとめくって、ないようをたしかめた。","example_meaning":"Tôi lật nhanh cuốn sách để kiểm tra nội dung."}],"level":"b1"},
{"word":"ことこと","reading":"ことこと","meaning":"sôi liu riu","antonym":"ぐつぐつ: sôi sùng sục","note":"Hay đi với 煮る, 煮込む. Nồi hầm nhỏ lửa, tiếng sôi nhẹ.","example":"鍋で野菜をことこと煮込むと、甘みが出る。","example_reading":"なべでやさいをことことにこむと、あまみがでる。","example_meaning":"Hầm rau liu riu trong nồi thì ra vị ngọt.","examples":[{"example":"鍋で野菜をことこと煮込むと、甘みが出る。","example_reading":"なべでやさいをことことにこむと、あまみがでる。","example_meaning":"Hầm rau liu riu trong nồi thì ra vị ngọt."},{"example":"台所でスープがことこと煮える音がする。","example_reading":"だいどころでスープがことことにえるおとがする。","example_meaning":"Trong bếp có tiếng súp sôi liu riu."}],"level":"b1"},
{"word":"びっしり","reading":"びっしり","meaning":"dày đặc, kín mít","antonym":"ちらほら: lác đác / がらがら: vắng tanh","note":"Hay đi với 書く, 詰まる, 並ぶ, 予定. Gần ぎっしり nhưng nhấn mạnh độ chi chít.","example":"ノートにはびっしり文字が書き込まれていた。","example_reading":"ノートにはびっしりもじがかきこまれていた。","example_meaning":"Cuốn vở được viết chi chít chữ.","examples":[{"example":"ノートにはびっしり文字が書き込まれていた。","example_reading":"ノートにはびっしりもじがかきこまれていた。","example_meaning":"Cuốn vở được viết chi chít chữ."},{"example":"来週はスケジュールがびっしり詰まっている。","example_reading":"らいしゅうはスケジュールがびっしりつまっている。","example_meaning":"Tuần sau lịch trình kín mít."}],"level":"b1"},
{"word":"ほのぼの","reading":"ほのぼの","meaning":"ấm áp, dịu dàng (cảm xúc)","note":"Hay đi với する, とした. Cảm giác ấm lòng, bình yên.","example":"子どもと犬が遊ぶ姿を見て、ほのぼのとした気持ちになった。","example_reading":"こどもといぬがあそぶすがたをみて、ほのぼのとしたきもちになった。","example_meaning":"Nhìn cảnh trẻ con chơi với chó, lòng tôi thấy ấm áp.","examples":[{"example":"子どもと犬が遊ぶ姿を見て、ほのぼのとした気持ちになった。","example_reading":"こどもといぬがあそぶすがたをみて、ほのぼのとしたきもちになった。","example_meaning":"Nhìn cảnh trẻ con chơi với chó, lòng tôi thấy ấm áp."},{"example":"この漫画は、家族の日常を描いたほのぼのした話だ。","example_reading":"このまんがは、かぞくのにちじょうをえがいたほのぼのしたはなしだ。","example_meaning":"Bộ truyện này là câu chuyện ấm áp về đời thường của một gia đình."}],"level":"b1"},
{"word":"ぱりっと","reading":"ぱりっと","meaning":"giòn rụm; (đồ) phẳng phiu","antonym":"しなしな: héo rũ / よれよれ: nhàu nhĩ","note":"Hay đi với 焼ける, 揚がる, した服. Cũng chỉ quần áo hồ phẳng.","example":"皮がぱりっと焼けた鶏肉は、とてもおいしい。","example_reading":"かわがぱりっとやけたとりにくは、とてもおいしい。","example_meaning":"Thịt gà nướng da giòn rụm rất ngon.","examples":[{"example":"皮がぱりっと焼けた鶏肉は、とてもおいしい。","example_reading":"かわがぱりっとやけたとりにくは、とてもおいしい。","example_meaning":"Thịt gà nướng da giòn rụm rất ngon."},{"example":"彼はぱりっとしたスーツで面接に来た。","example_reading":"かれはぱりっとしたスーツでめんせつにきた。","example_meaning":"Anh ấy đến phỏng vấn trong bộ vest phẳng phiu."}],"level":"b1"},
{"word":"さくっと","reading":"さくっと","meaning":"giòn xốp; làm gọn nhanh","note":"Hay đi với 食べる, 切る, 終わる. Cũng là khẩu ngữ \"làm gọn lẹ\".","example":"このクッキーは、さくっとした食感がたまらない。","example_reading":"このクッキーは、さくっとしたしょっかんがたまらない。","example_meaning":"Chiếc bánh quy này có độ giòn xốp rất tuyệt.","examples":[{"example":"このクッキーは、さくっとした食感がたまらない。","example_reading":"このクッキーは、さくっとしたしょっかんがたまらない。","example_meaning":"Chiếc bánh quy này có độ giòn xốp rất tuyệt."},{"example":"宿題はさくっと終わらせて、遊びに行こう。","example_reading":"しゅくだいはさくっとおわらせて、あそびにいこう。","example_meaning":"Làm gọn bài tập rồi đi chơi nào."}],"level":"b1"},
{"word":"つるっと","reading":"つるっと","meaning":"trơn tuột; nhẵn bóng","antonym":"ざらざら: sần sùi / ごつごつ: gồ ghề","note":"Hay đi với 滑る, むける, 入る. Bề mặt trơn.","example":"床が濡れていて、足がつるっと滑った。","example_reading":"ゆかがぬれていて、あしがつるっとすべった。","example_meaning":"Sàn ướt nên chân tôi trượt cái trơn.","examples":[{"example":"床が濡れていて、足がつるっと滑った。","example_reading":"ゆかがぬれていて、あしがつるっとすべった。","example_meaning":"Sàn ướt nên chân tôi trượt cái trơn."},{"example":"ゆで卵の殻が、つるっときれいにむけた。","example_reading":"ゆでたまごのからが、つるっときれいにむけた。","example_meaning":"Vỏ trứng luộc bóc tuột sạch trơn."}],"level":"b1"},
{"word":"ぬるっと","reading":"ぬるっと","meaning":"trơn nhớt","antonym":"さらさら: khô ráo","note":"Hay đi với する, 滑る. Cảm giác nhầy trơn khi chạm.","example":"魚の表面は、ぬるっとしていて触りにくい。","example_reading":"さかなのひょうめんは、ぬるっとしていてさわりにくい。","example_meaning":"Bề mặt con cá nhớt trơn nên khó cầm.","examples":[{"example":"魚の表面は、ぬるっとしていて触りにくい。","example_reading":"さかなのひょうめんは、ぬるっとしていてさわりにくい。","example_meaning":"Bề mặt con cá nhớt trơn nên khó cầm."},{"example":"水に浸けたせっけんが、ぬるっと手から滑り落ちた。","example_reading":"みずにつけたせっけんが、ぬるっとてからすべりおちた。","example_meaning":"Cục xà phòng ngâm nước trượt nhớt khỏi tay."}],"level":"b1"},
{"word":"ぱたっと","reading":"ぱたっと","meaning":"đổ phịch; ngừng đột ngột","note":"Hay đi với 倒れる, 止む, 途絶える.","example":"彼はぱたっと倒れて、そのまま動かなくなった。","example_reading":"かれはぱたっとたおれて、そのままうごかなくなった。","example_meaning":"Anh ấy ngã phịch xuống rồi nằm bất động.","examples":[{"example":"彼はぱたっと倒れて、そのまま動かなくなった。","example_reading":"かれはぱたっとたおれて、そのままうごかなくなった。","example_meaning":"Anh ấy ngã phịch xuống rồi nằm bất động."},{"example":"風がぱたっと止んで、海が静まり返った。","example_reading":"かぜがぱたっとやんで、うみがしずまりかえった。","example_meaning":"Gió tắt hẳn, mặt biển lặng đi."}],"level":"b1"},
{"word":"ごとん","reading":"ごとん","meaning":"cộp, cạch (vật nặng đổ, tàu rung)","note":"Hay đi với と, 落ちる, 動く. Tiếng nặng và trầm.","example":"棚から、重い箱がごとんと落ちた。","example_reading":"たなから、おもいはこがごとんとおちた。","example_meaning":"Một chiếc hộp nặng rơi từ giá xuống kêu cộp.","examples":[{"example":"棚から、重い箱がごとんと落ちた。","example_reading":"たなから、おもいはこがごとんとおちた。","example_meaning":"Một chiếc hộp nặng rơi từ giá xuống kêu cộp."},{"example":"電車がごとんと揺れて、動き出した。","example_reading":"でんしゃがごとんとゆれて、うごきだした。","example_meaning":"Tàu rung lên một cái rồi chạy."}],"level":"b1"},
{"word":"ぐびっと","reading":"ぐびっと","meaning":"tu một ngụm","note":"Hay đi với 飲む, 飲み干す. Một ngụm mạnh.","example":"彼はコップの水を、ぐびっと一気に飲み干した。","example_reading":"かれはコップのみずを、ぐびっといっきにのみほした。","example_meaning":"Anh ấy tu một hơi hết cốc nước.","examples":[{"example":"彼はコップの水を、ぐびっと一気に飲み干した。","example_reading":"かれはコップのみずを、ぐびっといっきにのみほした。","example_meaning":"Anh ấy tu một hơi hết cốc nước."},{"example":"のどが渇いて、お茶をぐびっと飲んだ。","example_reading":"のどがかわいて、おちゃをぐびっとのんだ。","example_meaning":"Khát nên tôi tu một ngụm trà."}],"level":"b1"},
{"word":"もぞもぞ","reading":"もぞもぞ","meaning":"cựa quậy, lúng búng","note":"Hay đi với 動く, 言う. Cử động nhẹ khó chịu hoặc nói ấp úng.","example":"赤ちゃんが、布団の中でもぞもぞ動いている。","example_reading":"あかちゃんが、ふとんのなかでもぞもぞうごいている。","example_meaning":"Em bé đang cựa quậy trong chăn.","examples":[{"example":"赤ちゃんが、布団の中でもぞもぞ動いている。","example_reading":"あかちゃんが、ふとんのなかでもぞもぞうごいている。","example_meaning":"Em bé đang cựa quậy trong chăn."},{"example":"彼はもぞもぞと、何か言いかけてやめた。","example_reading":"かれはもぞもぞと、なにかいいかけてやめた。","example_meaning":"Anh ấy lúng búng định nói gì đó rồi thôi."}],"level":"b1"},
{"word":"べとべと","reading":"べとべと","meaning":"dính nhớp","antonym":"さらさら: khô ráo","note":"Hay đi với 手, 肌, 汗. Cảm giác dính khó chịu.","example":"ジュースをこぼして、手がべとべとになった。","example_reading":"ジュースをこぼして、てがべとべとになった。","example_meaning":"Làm đổ nước ép nên tay tôi dính nhớp.","examples":[{"example":"ジュースをこぼして、手がべとべとになった。","example_reading":"ジュースをこぼして、てがべとべとになった。","example_meaning":"Làm đổ nước ép nên tay tôi dính nhớp."},{"example":"夏は汗で、肌がべとべとして気持ち悪い。","example_reading":"なつはあせで、はだがべとべとしてきもちわるい。","example_meaning":"Mùa hè mồ hôi làm da dính nhớp rất khó chịu."}],"level":"b1"},
{"word":"がっしり","reading":"がっしり","meaning":"vạm vỡ, chắc chắn","antonym":"ひょろひょろ: lêu nghêu / ほっそり: mảnh mai / ひょろっと: gầy cao","note":"Hay đi với した体格, 作る. Cơ thể hoặc vật rắn chắc.","example":"彼はがっしりした体格で、力が強い。","example_reading":"かれはがっしりしたたいかくで、ちからがつよい。","example_meaning":"Anh ấy vạm vỡ nên rất khỏe.","examples":[{"example":"彼はがっしりした体格で、力が強い。","example_reading":"かれはがっしりしたたいかくで、ちからがつよい。","example_meaning":"Anh ấy vạm vỡ nên rất khỏe."},{"example":"この机は、がっしりと作られていて、壊れにくい。","example_reading":"このつくえは、がっしりとつくられていて、こわれにくい。","example_meaning":"Chiếc bàn này làm chắc chắn nên khó hỏng."}],"level":"b1"},
{"word":"すらっと","reading":"すらっと","meaning":"thon thả, cao ráo","antonym":"ずんぐり: lùn mập / でっぷり: bụng phệ / ぽっちゃり: mũm mĩm","note":"Hay đi với した, 伸びる. Dáng người cao, gọn, đẹp.","example":"彼女はすらっとした長い足をしている。","example_reading":"かのじょはすらっとしたながいあしをしている。","example_meaning":"Cô ấy có đôi chân dài thon thả.","examples":[{"example":"彼女はすらっとした長い足をしている。","example_reading":"かのじょはすらっとしたながいあしをしている。","example_meaning":"Cô ấy có đôi chân dài thon thả."},{"example":"すらっと背の高いモデルが、ステージに現れた。","example_reading":"すらっとせのたかいモデルが、ステージにあらわれた。","example_meaning":"Người mẫu cao ráo thon thả xuất hiện trên sân khấu."}],"level":"b1"},
{"word":"ちょこちょこ","reading":"ちょこちょこ","meaning":"lăng xăng; thỉnh thoảng","note":"Hay đi với 歩く, 動く, 顔を出す. Bước nhỏ nhanh; hoặc làm việc lặt vặt thường xuyên.","example":"赤ちゃんがちょこちょこ歩く姿は、本当にかわいい。","example_reading":"あかちゃんがちょこちょこあるくすがたは、ほんとうにかわいい。","example_meaning":"Dáng em bé chập chững bước thật đáng yêu.","examples":[{"example":"赤ちゃんがちょこちょこ歩く姿は、本当にかわいい。","example_reading":"あかちゃんがちょこちょこあるくすがたは、ほんとうにかわいい。","example_meaning":"Dáng em bé chập chững bước thật đáng yêu."},{"example":"彼は暇なときに、ちょこちょこ店に顔を出す。","example_reading":"かれはひまなときに、ちょこちょこみせにかおをだす。","example_meaning":"Lúc rảnh anh ấy thỉnh thoảng lại ghé cửa hàng."}],"level":"b1"},
{"word":"ぶんぶん","reading":"ぶんぶん","meaning":"vo ve; vung vút","note":"Hay đi với 飛ぶ, 振り回す. Tiếng ong ruồi bay; vung mạnh.","example":"部屋の中をハエがぶんぶん飛び回っている。","example_reading":"へやのなかをハエがぶんぶんとびまわっている。","example_meaning":"Con ruồi bay vo ve trong phòng.","examples":[{"example":"部屋の中をハエがぶんぶん飛び回っている。","example_reading":"へやのなかをハエがぶんぶんとびまわっている。","example_meaning":"Con ruồi bay vo ve trong phòng."},{"example":"子どもが棒をぶんぶん振り回して遊んでいる。","example_reading":"こどもがぼうをぶんぶんふりまわしてあそんでいる。","example_meaning":"Đứa bé vung vút cây gậy để chơi."}],"level":"b1"},
{"word":"もくもく","reading":"もくもく","meaning":"cuồn cuộn (khói, mây)","note":"Hay đi với 煙, 雲, 立ち上る. Chú ý: 黙々と ở nhóm a1 cũng đọc もくもくと nhưng nghĩa khác.","example":"工場の煙突から、白い煙がもくもくと上がっている。","example_reading":"こうじょうのえんとつから、しろいけむりがもくもくとあがっている。","example_meaning":"Khói trắng cuồn cuộn bốc lên từ ống khói nhà máy.","examples":[{"example":"工場の煙突から、白い煙がもくもくと上がっている。","example_reading":"こうじょうのえんとつから、しろいけむりがもくもくとあがっている。","example_meaning":"Khói trắng cuồn cuộn bốc lên từ ống khói nhà máy."},{"example":"山の向こうに、大きな雲がもくもく広がっていた。","example_reading":"やまのむこうに、おおきなくもがもくもくひろがっていた。","example_meaning":"Phía sau núi, những đám mây lớn cuồn cuộn lan rộng."}],"level":"b1"},
{"word":"ひょいと","reading":"ひょいと","meaning":"nhẹ nhàng, tiện tay","note":"Hay đi với 持ち上げる, 顔を出す, 飛び越える. Làm nhẹ nhàng, nhanh gọn.","example":"彼は重い荷物をひょいと持ち上げた。","example_reading":"かれはおもいにもつをひょいともちあげた。","example_meaning":"Anh ấy nhấc bổng hành lý nặng một cách nhẹ nhàng.","examples":[{"example":"彼は重い荷物をひょいと持ち上げた。","example_reading":"かれはおもいにもつをひょいともちあげた。","example_meaning":"Anh ấy nhấc bổng hành lý nặng một cách nhẹ nhàng."},{"example":"窓からひょいと顔を出して、手を振った。","example_reading":"まどからひょいとかおをだして、てをふった。","example_meaning":"Anh ta thò đầu ra cửa sổ rồi vẫy tay."}],"level":"b1"},
{"word":"ぷりぷり","reading":"ぷりぷり","meaning":"giòn dai, tươi (tôm); hầm hầm tức giận","note":"Tả độ đàn hồi của thực phẩm (えび, 肉). ぷりぷり怒る = giận đùng đùng.","example":"このえびはぷりぷりしていて、とてもおいしい。","example_reading":"このえびはぷりぷりしていて、とてもおいしい。","example_meaning":"Con tôm này giòn dai, rất ngon.","examples":[{"example":"このえびはぷりぷりしていて、とてもおいしい。","example_reading":"このえびはぷりぷりしていて、とてもおいしい。","example_meaning":"Con tôm này giòn dai, rất ngon."},{"example":"妹は約束を忘れられて、朝からぷりぷり怒っている。","example_reading":"いもうとはやくそくをわすれられて、あさからぷりぷりおこっている。","example_meaning":"Em gái bị quên hẹn nên từ sáng đã giận đùng đùng."}],"level":"b1"},
{"word":"ぽつぽつ","reading":"ぽつぽつ","meaning":"lác đác, lẻ tẻ (hạt mưa, chấm nhỏ)","antonym":"ざあざあ: xối xả","note":"Từ tượng hình. Mưa mới bắt đầu, hoặc các chấm rải rác.","example":"雨がぽつぽつ降り出した。","example_reading":"あめがぽつぽつふりだした。","example_meaning":"Mưa bắt đầu rơi lộp độp.","examples":[{"example":"雨がぽつぽつ降り出した。","example_reading":"あめがぽつぽつふりだした。","example_meaning":"Mưa bắt đầu rơi lộp độp."},{"example":"窓ガラスに、ぽつぽつと雨粒が当たり始めた。","example_reading":"まどガラスに、ぽつぽつとあまつぶがあたりはじめた。","example_meaning":"Những hạt mưa bắt đầu lộp độp rơi trên kính cửa sổ."}],"level":"b1"},
{"word":"じりじり","reading":"じりじり","meaning":"nóng rát; sốt ruột dần","note":"Hay đi với 照りつける, 待つ, 近づく. Nhiệt hoặc cảm giác tăng dần từ từ.","example":"真夏の太陽がじりじり照りつけている。","example_reading":"まなつのたいようがじりじりてりつけている。","example_meaning":"Mặt trời giữa hè chiếu rát.","examples":[{"example":"真夏の太陽がじりじり照りつけている。","example_reading":"まなつのたいようがじりじりてりつけている。","example_meaning":"Mặt trời giữa hè chiếu rát."},{"example":"彼の返事を、じりじりしながら待った。","example_reading":"かれのへんじを、じりじりしながらまった。","example_meaning":"Tôi sốt ruột chờ câu trả lời của anh ấy."}],"level":"b1"},
{"word":"しゃきしゃき","reading":"しゃきしゃき","meaning":"giòn tươi (rau)","antonym":"しなしな: héo rũ","note":"Hay đi với レタス, キャベツ, 歯ごたえ. Dùng khen rau tươi giòn.","example":"このサラダのレタスはしゃきしゃきしていておいしい。","example_reading":"このサラダのレタスはしゃきしゃきしていておいしい。","example_meaning":"Xà lách trong món salad này giòn tươi nên rất ngon.","examples":[{"example":"このサラダのレタスはしゃきしゃきしていておいしい。","example_reading":"このサラダのレタスはしゃきしゃきしていておいしい。","example_meaning":"Xà lách trong món salad này giòn tươi nên rất ngon."},{"example":"切ったばかりのキャベツは、しゃきしゃきした食感が楽しめる。","example_reading":"きったばかりのキャベツは、しゃきしゃきしたしょっかんがたのしめる。","example_meaning":"Bắp cải mới cắt cho cảm giác giòn tươi rất thích."}],"level":"b1"},
{"word":"こんがり","reading":"こんがり","meaning":"vàng ruộm (nướng)","note":"Hay đi với 焼ける, 焼く, 揚げる. Cũng dùng chỉ rám nắng (こんがり日焼けする).","example":"パンをこんがり焼いて、バターを塗って食べた。","example_reading":"パンをこんがりやいて、バターをぬってたべた。","example_meaning":"Tôi nướng bánh mì vàng ruộm rồi phết bơ ăn.","examples":[{"example":"パンをこんがり焼いて、バターを塗って食べた。","example_reading":"パンをこんがりやいて、バターをぬってたべた。","example_meaning":"Tôi nướng bánh mì vàng ruộm rồi phết bơ ăn."},{"example":"夏休みに海へ行って、こんがり日焼けした。","example_reading":"なつやすみにうみへいって、こんがりひやけした。","example_meaning":"Kỳ nghỉ hè đi biển nên tôi rám nắng đen sạm."}],"level":"b1"},
{"word":"ぎらぎら","reading":"ぎらぎら","meaning":"chói chang, lóa mắt","note":"Hay đi với 光る, 輝く, 太陽. Ánh sáng gắt; cũng chỉ ánh mắt rực lên.","example":"夏の太陽が海をぎらぎら照らしていた。","example_reading":"なつのたいようがうみをぎらぎらてらしていた。","example_meaning":"Mặt trời mùa hè chiếu chói chang xuống biển.","examples":[{"example":"夏の太陽が海をぎらぎら照らしていた。","example_reading":"なつのたいようがうみをぎらぎらてらしていた。","example_meaning":"Mặt trời mùa hè chiếu chói chang xuống biển."},{"example":"ぎらぎらした目で、彼はこちらを見ていた。","example_reading":"ぎらぎらしためで、かれはこちらをみていた。","example_meaning":"Anh ấy nhìn về phía này với ánh mắt rực lên."}],"level":"b1"},
{"word":"かんかん","reading":"かんかん","meaning":"(Nắng) chói chang; nổi giận đùng đùng","note":"Từ tượng hình. Nghĩa 1: 太陽がかんかん照る. Nghĩa 2: かんかんに怒る.","example":"夏の太陽がかんかん照っている。","example_reading":"なつのたいようがかんかんてっている。","example_meaning":"Nắng mùa hè đang chiếu chói chang.","examples":[{"example":"夏の太陽がかんかん照っている。","example_reading":"なつのたいようがかんかんてっている。","example_meaning":"Nắng mùa hè đang chiếu chói chang."},{"example":"嘘がばれて、父はかんかんに怒った。","example_reading":"うそがばれて、ちちはかんかんにおこった。","example_meaning":"Bị lộ lời nói dối, bố giận đùng đùng."}],"level":"b1"},
{"word":"ひゅうひゅう","reading":"ひゅうひゅう","meaning":"vi vu, rít (gió)","note":"Hay đi với 風, 吹く. Gió lạnh thổi mạnh.","example":"冬の海辺は、冷たい風がひゅうひゅうと吹いていた。","example_reading":"ふゆのうみべは、つめたいかぜがひゅうひゅうとふいていた。","example_meaning":"Bờ biển mùa đông gió lạnh rít vi vu.","examples":[{"example":"冬の海辺は、冷たい風がひゅうひゅうと吹いていた。","example_reading":"ふゆのうみべは、つめたいかぜがひゅうひゅうとふいていた。","example_meaning":"Bờ biển mùa đông gió lạnh rít vi vu."},{"example":"窓の隙間から、風がひゅうひゅう入ってくる。","example_reading":"まどのすきまから、かぜがひゅうひゅうはいってくる。","example_meaning":"Gió lùa vi vu qua khe cửa sổ."}],"level":"b1"},
{"word":"ぴりぴり","reading":"ぴりぴり","meaning":"cay tê, nhức nhối; căng thẳng","antonym":"のんびり: thong thả","note":"Từ tượng hình. Dùng cho vị cay, cảm giác tê rát, hoặc bầu không khí căng.","example":"辛いものを食べて、舌がぴりぴりする。","example_reading":"からいものをたべて、したがぴりぴりする。","example_meaning":"Ăn đồ cay nên lưỡi tê rát.","examples":[{"example":"辛いものを食べて、舌がぴりぴりする。","example_reading":"からいものをたべて、したがぴりぴりする。","example_meaning":"Ăn đồ cay nên lưỡi tê rát."},{"example":"試験前の教室は、ぴりぴりした空気だった。","example_reading":"しけんまえのきょうしつは、ぴりぴりしたくうきだった。","example_meaning":"Lớp học trước giờ thi có không khí căng thẳng."}],"level":"b1"},
{"word":"ずきずき","reading":"ずきずき","meaning":"đau nhói từng nhịp","note":"Từ tượng hình. Đau theo nhịp mạch, hay dùng với đầu, răng, vết thương.","example":"虫歯で歯がずきずき痛みます。","example_reading":"むしばではがずきずきいたみます。","example_meaning":"Tôi bị sâu răng nên răng đau nhói.","examples":[{"example":"虫歯で歯がずきずき痛みます。","example_reading":"むしばではがずきずきいたみます。","example_meaning":"Tôi bị sâu răng nên răng đau nhói."},{"example":"転んで打った膝が、ずきずきと痛む。","example_reading":"ころんでうったひざが、ずきずきといたむ。","example_meaning":"Đầu gối bị đập khi ngã đau nhói từng nhịp."}],"level":"b1"},
{"word":"だぶだぶ","reading":"だぶだぶ","meaning":"rộng thùng thình","antonym":"ぴちぴち: chật cứng / ぴったり: vừa khít","note":"Hay đi với 服, ズボン. Quần áo quá rộng. Trái nghĩa: ぴちぴち.","example":"兄のお古のシャツは、私にはだぶだぶだった。","example_reading":"あにのおふるのシャツは、わたしにはだぶだぶだった。","example_meaning":"Chiếc áo cũ của anh trai rộng thùng thình với tôi.","examples":[{"example":"兄のお古のシャツは、私にはだぶだぶだった。","example_reading":"あにのおふるのシャツは、わたしにはだぶだぶだった。","example_meaning":"Chiếc áo cũ của anh trai rộng thùng thình với tôi."},{"example":"痩せたので、前に買ったズボンがだぶだぶになった。","example_reading":"やせたので、まえにかったズボンがだぶだぶになった。","example_meaning":"Vì gầy đi nên chiếc quần mua trước đây giờ rộng thùng thình."}],"level":"b1"},
{"word":"ぴくりと","reading":"ぴくりと","meaning":"giật nhẹ một cái","note":"Hay đi với 動く, 眉, 耳. Cử động nhỏ thoáng qua.","example":"彼は、その言葉に眉をぴくりと動かした。","example_reading":"かれは、そのことばにまゆをぴくりとうごかした。","example_meaning":"Nghe câu đó, anh ấy khẽ nhướn mày.","examples":[{"example":"彼は、その言葉に眉をぴくりと動かした。","example_reading":"かれは、そのことばにまゆをぴくりとうごかした。","example_meaning":"Nghe câu đó, anh ấy khẽ nhướn mày."},{"example":"寝ていた犬が、物音にぴくりと耳を動かした。","example_reading":"ねていたいぬが、ものおとにぴくりとみみをうごかした。","example_meaning":"Con chó đang ngủ khẽ giật tai khi nghe tiếng động."}],"level":"b1"},
{"word":"ぎくり","reading":"ぎくり","meaning":"giật thột, chột dạ","note":"Hay đi với と, する. Giật mình vì bị nói trúng hoặc nhận ra điều không hay.","example":"嘘を指摘されて、ぎくりとした。","example_reading":"うそをしてきされて、ぎくりとした。","example_meaning":"Bị chỉ ra lời nói dối, tôi giật thột.","examples":[{"example":"嘘を指摘されて、ぎくりとした。","example_reading":"うそをしてきされて、ぎくりとした。","example_meaning":"Bị chỉ ra lời nói dối, tôi giật thột."},{"example":"体重計の数字を見て、ぎくりとした。","example_reading":"たいじゅうけいのすうじをみて、ぎくりとした。","example_meaning":"Nhìn con số trên cân, tôi giật mình."}],"level":"b1"},
{"word":"くすっと","reading":"くすっと","meaning":"phì cười","note":"Hay đi với 笑う, させられる. Cười khẽ một tiếng.","example":"彼の冗談に、思わずくすっと笑ってしまった。","example_reading":"かれのじょうだんに、おもわずくすっとわらってしまった。","example_meaning":"Nghe câu đùa của anh ấy, tôi bất giác phì cười.","examples":[{"example":"彼の冗談に、思わずくすっと笑ってしまった。","example_reading":"かれのじょうだんに、おもわずくすっとわらってしまった。","example_meaning":"Nghe câu đùa của anh ấy, tôi bất giác phì cười."},{"example":"手紙の中の一言に、くすっとさせられた。","example_reading":"てがみのなかのひとことに、くすっとさせられた。","example_meaning":"Một câu trong bức thư khiến tôi phì cười."}],"level":"b1"},
{"word":"むくっと","reading":"むくっと","meaning":"bật dậy, nhổm dậy","note":"Hay đi với 起き上がる, 体を起こす. Cử động đột ngột từ tư thế nằm.","example":"寝ていた犬が、むくっと起き上がった。","example_reading":"ねていたいぬが、むくっとおきあがった。","example_meaning":"Con chó đang ngủ bỗng nhổm dậy.","examples":[{"example":"寝ていた犬が、むくっと起き上がった。","example_reading":"ねていたいぬが、むくっとおきあがった。","example_meaning":"Con chó đang ngủ bỗng nhổm dậy."},{"example":"彼はむくっと体を起こして、あたりを見回した。","example_reading":"かれはむくっとからだをおこして、あたりをみまわした。","example_meaning":"Anh ấy bật người dậy rồi nhìn quanh."}],"level":"b1"},
{"word":"ぷるっと","reading":"ぷるっと","meaning":"rung rinh; run nhẹ","note":"Hay đi với 揺れる, 震える. Vật mềm rung hoặc cơ thể run khẽ.","example":"プリンをスプーンですくうと、ぷるっと揺れた。","example_reading":"プリンをスプーンですくうと、ぷるっとゆれた。","example_meaning":"Múc miếng pudding bằng thìa, nó rung rinh.","examples":[{"example":"プリンをスプーンですくうと、ぷるっと揺れた。","example_reading":"プリンをスプーンですくうと、ぷるっとゆれた。","example_meaning":"Múc miếng pudding bằng thìa, nó rung rinh."},{"example":"寒さで、体がぷるっと震えた。","example_reading":"さむさで、からだがぷるっとふるえた。","example_meaning":"Vì lạnh, người tôi run bần bật."}],"level":"b1"},
{"word":"ぶかぶか","reading":"ぶかぶか","meaning":"rộng lùng thùng (giày, mũ)","antonym":"ぴったり: vừa khít / きつきつ: chật cứng / ぴちぴち: chật cứng","note":"Hay đi với 靴, 帽子, 服. Không vừa vì quá to.","example":"大きめの靴を買ったら、ぶかぶかだった。","example_reading":"おおきめのくつをかったら、ぶかぶかだった。","example_meaning":"Mua đôi giày hơi to nên bị rộng lùng thùng.","examples":[{"example":"大きめの靴を買ったら、ぶかぶかだった。","example_reading":"おおきめのくつをかったら、ぶかぶかだった。","example_meaning":"Mua đôi giày hơi to nên bị rộng lùng thùng."},{"example":"弟は父のぶかぶかの帽子をかぶって遊んでいる。","example_reading":"おとうとはちちのぶかぶかのぼうしをかぶってあそんでいる。","example_meaning":"Em trai đội chiếc mũ rộng thùng thình của bố mà chơi."}],"level":"b1"},
{"word":"ほっそり","reading":"ほっそり","meaning":"mảnh mai, thanh mảnh","antonym":"ぽっちゃり: mũm mĩm / でっぷり: bụng phệ / がっしり: vạm vỡ","note":"Hay đi với した指, 体つき.","example":"彼女はほっそりした指で、ピアノを弾いている。","example_reading":"かのじょはほっそりしたゆびで、ピアノをひいている。","example_meaning":"Cô ấy chơi piano bằng những ngón tay mảnh mai.","examples":[{"example":"彼女はほっそりした指で、ピアノを弾いている。","example_reading":"かのじょはほっそりしたゆびで、ピアノをひいている。","example_meaning":"Cô ấy chơi piano bằng những ngón tay mảnh mai."},{"example":"ほっそりした体つきだが、意外に力がある。","example_reading":"ほっそりしたからだつきだが、いがいにちからがある。","example_meaning":"Dáng người mảnh mai nhưng lại khỏe bất ngờ."}],"level":"b1"},
{"word":"ぽっちゃり","reading":"ぽっちゃり","meaning":"mũm mĩm, tròn trịa dễ thương","antonym":"ほっそり: mảnh mai / すらっと: thon thả / がりがり: gầy trơ xương","note":"Hay đi với した, 体型. Hơi đầy đặn, mang sắc thái dễ thương.","example":"ぽっちゃりした赤ちゃんが、にこにこ笑っている。","example_reading":"ぽっちゃりしたあかちゃんが、にこにこわらっている。","example_meaning":"Em bé mũm mĩm đang cười tươi.","examples":[{"example":"ぽっちゃりした赤ちゃんが、にこにこ笑っている。","example_reading":"ぽっちゃりしたあかちゃんが、にこにこわらっている。","example_meaning":"Em bé mũm mĩm đang cười tươi."},{"example":"彼女は少しぽっちゃりしているが、とても魅力的だ。","example_reading":"かのじょはすこしぽっちゃりしているが、とてもみりょくてきだ。","example_meaning":"Cô ấy hơi mũm mĩm nhưng rất cuốn hút."}],"level":"b1"},
{"word":"ぞくっと","reading":"ぞくっと","meaning":"lạnh gáy, rợn người","note":"Hay đi với する. Cảm giác lạnh chạy dọc sống lưng vì sợ hoặc lạnh.","example":"背後で物音がして、ぞくっとした。","example_reading":"はいごでものおとがして、ぞくっとした。","example_meaning":"Có tiếng động phía sau, tôi lạnh cả gáy.","examples":[{"example":"背後で物音がして、ぞくっとした。","example_reading":"はいごでものおとがして、ぞくっとした。","example_meaning":"Có tiếng động phía sau, tôi lạnh cả gáy."},{"example":"熱が出るのか、朝から背筋がぞくっとする。","example_reading":"ねつがでるのか、あさからせすじがぞくっとする。","example_meaning":"Chắc sắp sốt, từ sáng sống lưng tôi cứ ớn lạnh."}],"level":"b1"},
{"word":"ぎくしゃく","reading":"ぎくしゃく","meaning":"gượng gạo, trục trặc","antonym":"すんなり: suôn sẻ / スムーズに: trôi chảy","note":"Hay đi với する. Quan hệ không êm hoặc động tác không trôi chảy.","example":"喧嘩して以来、二人の関係がぎくしゃくしている。","example_reading":"けんかしていらい、ふたりのかんけいがぎくしゃくしている。","example_meaning":"Từ sau lần cãi nhau, quan hệ hai người trở nên gượng gạo.","examples":[{"example":"喧嘩して以来、二人の関係がぎくしゃくしている。","example_reading":"けんかしていらい、ふたりのかんけいがぎくしゃくしている。","example_meaning":"Từ sau lần cãi nhau, quan hệ hai người trở nên gượng gạo."},{"example":"緊張して、動きがぎくしゃくしてしまった。","example_reading":"きんちょうして、うごきがぎくしゃくしてしまった。","example_meaning":"Căng thẳng nên động tác của tôi cứng đơ."}],"level":"b1"},
{"word":"びくっと","reading":"びくっと","meaning":"giật bắn người","note":"Hay đi với する. Giật mình đột ngột vì bất ngờ.","example":"突然名前を呼ばれて、びくっとした。","example_reading":"とつぜんなまえをよばれて、びくっとした。","example_meaning":"Bị gọi tên đột ngột, tôi giật bắn mình.","examples":[{"example":"突然名前を呼ばれて、びくっとした。","example_reading":"とつぜんなまえをよばれて、びくっとした。","example_meaning":"Bị gọi tên đột ngột, tôi giật bắn mình."},{"example":"大きな音に、犬がびくっと体を震わせた。","example_reading":"おおきなおとに、いぬがびくっとからだをふるわせた。","example_meaning":"Nghe tiếng động lớn, con chó giật mình run lên."}],"level":"b1"},
{"word":"ぺろり","reading":"ぺろり","meaning":"liếm một cái; ăn sạch gọn","note":"Hay đi với 舐める, 食べる. Cũng nói ぺろっと.","example":"弟は大きなピザを一人でぺろりと食べてしまった。","example_reading":"おとうとはおおきなピザをひとりでぺろりとたべてしまった。","example_meaning":"Em trai tôi một mình ăn sạch chiếc pizza lớn.","examples":[{"example":"弟は大きなピザを一人でぺろりと食べてしまった。","example_reading":"おとうとはおおきなピザをひとりでぺろりとたべてしまった。","example_meaning":"Em trai tôi một mình ăn sạch chiếc pizza lớn."},{"example":"猫がぺろりと口の周りを舐めた。","example_reading":"ねこがぺろりとくちのまわりをなめた。","example_meaning":"Con mèo liếm quanh miệng một cái."}],"level":"b1"},
{"word":"ぐにゃぐにゃ","reading":"ぐにゃぐにゃ","meaning":"mềm oặt, cong vẹo","antonym":"かちかち: cứng ngắc / ぴんと: căng thẳng / かちこち: cứng đơ","note":"Hay đi với 曲がる, 柔らかい. Dễ uốn cong, không giữ được hình.","example":"熱でプラスチックのスプーンがぐにゃぐにゃに曲がった。","example_reading":"ねつでプラスチックのスプーンがぐにゃぐにゃにまがった。","example_meaning":"Chiếc thìa nhựa bị nhiệt làm cong vẹo.","examples":[{"example":"熱でプラスチックのスプーンがぐにゃぐにゃに曲がった。","example_reading":"ねつでプラスチックのスプーンがぐにゃぐにゃにまがった。","example_meaning":"Chiếc thìa nhựa bị nhiệt làm cong vẹo."},{"example":"疲れすぎて、足がぐにゃぐにゃになって歩けない。","example_reading":"つかれすぎて、あしがぐにゃぐにゃになってあるけない。","example_meaning":"Mệt quá, chân mềm nhũn không đi nổi."}],"level":"b1"},
{"word":"ちょろちょろ","reading":"ちょろちょろ","meaning":"rỉ rách (nước); chạy tới chạy lui","note":"Hay đi với 流れる, 走り回る. Nước chảy nhỏ yếu; trẻ con chạy loanh quanh.","example":"蛇口からちょろちょろと水が出ているだけだ。","example_reading":"じゃぐちからちょろちょろとみずがでているだけだ。","example_meaning":"Từ vòi chỉ có nước rỉ ra chút ít.","examples":[{"example":"蛇口からちょろちょろと水が出ているだけだ。","example_reading":"じゃぐちからちょろちょろとみずがでているだけだ。","example_meaning":"Từ vòi chỉ có nước rỉ ra chút ít."},{"example":"子どもがちょろちょろ動き回って、目が離せない。","example_reading":"こどもがちょろちょろうごきまわって、めがはなせない。","example_meaning":"Đứa bé chạy loanh quanh nên không thể rời mắt."}],"level":"b1"},
{"word":"ぶらりと","reading":"ぶらりと","meaning":"dạo lang thang; lủng lẳng","note":"Hay đi với 出かける, 訪ねる, 下がる. Đi chơi không mục đích.","example":"休日は、ぶらりと近所を散歩するのが好きだ。","example_reading":"きゅうじつは、ぶらりときんじょをさんぽするのがすきだ。","example_meaning":"Ngày nghỉ tôi thích đi dạo vu vơ quanh khu phố.","examples":[{"example":"休日は、ぶらりと近所を散歩するのが好きだ。","example_reading":"きゅうじつは、ぶらりときんじょをさんぽするのがすきだ。","example_meaning":"Ngày nghỉ tôi thích đi dạo vu vơ quanh khu phố."},{"example":"天井から、電球が一つぶらりと下がっている。","example_reading":"てんじょうから、でんきゅうがひとつぶらりとさがっている。","example_meaning":"Một bóng đèn treo lủng lẳng từ trần nhà."}],"level":"b1"},
{"word":"ごくり","reading":"ごくり","meaning":"ực (nuốt nước bọt)","note":"Hay đi với と, 飲む, 唾を飲み込む. Nuốt một ngụm lớn.","example":"緊張して、思わずごくりと唾を飲み込んだ。","example_reading":"きんちょうして、おもわずごくりとつばをのみこんだ。","example_meaning":"Căng thẳng, tôi bất giác nuốt nước bọt đánh ực.","examples":[{"example":"緊張して、思わずごくりと唾を飲み込んだ。","example_reading":"きんちょうして、おもわずごくりとつばをのみこんだ。","example_meaning":"Căng thẳng, tôi bất giác nuốt nước bọt đánh ực."},{"example":"彼は冷たい水をごくりと一口飲んだ。","example_reading":"かれはつめたいみずをごくりとひとくちのんだ。","example_meaning":"Anh ấy uống ực một ngụm nước lạnh."}],"level":"b1"},
{"word":"ぽろっと","reading":"ぽろっと","meaning":"rơi ra, buột miệng","note":"Hay đi với 落ちる, 言う, こぼれる. Rơi nhẹ hoặc lỡ lời.","example":"彼女の目から、涙がぽろっとこぼれた。","example_reading":"かのじょのめから、なみだがぽろっとこぼれた。","example_meaning":"Nước mắt khẽ rơi từ mắt cô ấy.","examples":[{"example":"彼女の目から、涙がぽろっとこぼれた。","example_reading":"かのじょのめから、なみだがぽろっとこぼれた。","example_meaning":"Nước mắt khẽ rơi từ mắt cô ấy."},{"example":"酔って、秘密をぽろっと話してしまった。","example_reading":"よって、ひみつをぽろっとはなしてしまった。","example_meaning":"Say rượu nên tôi lỡ buột miệng nói ra bí mật."}],"level":"b1"},
{"word":"ぼやっと","reading":"ぼやっと","meaning":"lơ đãng; mờ nhòe","antonym":"はっきり: rõ ràng / きびきび: nhanh nhẹn","note":"Hay đi với する. Giống ぼうっと nhưng khẩu ngữ hơn.","example":"ぼやっとしていて、電車を乗り過ごしてしまった。","example_reading":"ぼやっとしていて、でんしゃをのりすごしてしまった。","example_meaning":"Lơ đãng nên tôi ngồi quá ga.","examples":[{"example":"ぼやっとしていて、電車を乗り過ごしてしまった。","example_reading":"ぼやっとしていて、でんしゃをのりすごしてしまった。","example_meaning":"Lơ đãng nên tôi ngồi quá ga."},{"example":"眼鏡を忘れて、遠くの景色がぼやっと見える。","example_reading":"めがねをわすれて、とおくのけしきがぼやっとみえる。","example_meaning":"Quên kính nên cảnh xa nhìn mờ nhòe."}],"level":"b1"},
{"word":"もっちり","reading":"もっちり","meaning":"dẻo mềm, dai","antonym":"ぱさぱさ: khô xơ / かちかち: cứng ngắc","note":"Hay đi với パン, 餅, 麺. Độ dai mềm dễ chịu.","example":"この店のパンは、もっちりとした食感が人気だ。","example_reading":"このみせのパンは、もっちりとしたしょっかんがにんきだ。","example_meaning":"Bánh mì quán này nổi tiếng nhờ độ dẻo mềm.","examples":[{"example":"この店のパンは、もっちりとした食感が人気だ。","example_reading":"このみせのパンは、もっちりとしたしょっかんがにんきだ。","example_meaning":"Bánh mì quán này nổi tiếng nhờ độ dẻo mềm."},{"example":"打ちたてのうどんは、もっちりしていて、とてもおいしい。","example_reading":"うちたてのうどんは、もっちりしていて、とてもおいしい。","example_meaning":"Mì udon mới cán dẻo dai, rất ngon."}],"level":"b1"},
{"word":"かりかり","reading":"かりかり","meaning":"giòn rụm; bực bội","antonym":"ふにゃふにゃ: mềm nhũn","note":"Hay đi với 焼ける, 怒る. Giòn của thức ăn; かりかりする = cáu kỉnh.","example":"ベーコンをかりかりになるまで焼いた。","example_reading":"ベーコンをかりかりになるまでやいた。","example_meaning":"Tôi nướng thịt xông khói đến khi giòn rụm.","examples":[{"example":"ベーコンをかりかりになるまで焼いた。","example_reading":"ベーコンをかりかりになるまでやいた。","example_meaning":"Tôi nướng thịt xông khói đến khi giòn rụm."},{"example":"締め切り前で、みんなかりかりしている。","example_reading":"しめきりまえで、みんなかりかりしている。","example_meaning":"Sắp đến hạn chót nên ai cũng cáu kỉnh."}],"level":"b1"},
{"word":"むすっと","reading":"むすっと","meaning":"sưng sỉa, cau có im lặng","antonym":"にこにこ: tươi cười / にっこり: mỉm cười / にこっと: mỉm cười","note":"Hay đi với する. Mặt hằm hằm, không nói chuyện.","example":"彼は怒られて、むすっとして口をきかなかった。","example_reading":"かれはおこられて、むすっとしてくちをきかなかった。","example_meaning":"Bị mắng, anh ấy sưng mặt không nói lời nào.","examples":[{"example":"彼は怒られて、むすっとして口をきかなかった。","example_reading":"かれはおこられて、むすっとしてくちをきかなかった。","example_meaning":"Bị mắng, anh ấy sưng mặt không nói lời nào."},{"example":"妹は朝からむすっとした顔で座っている。","example_reading":"いもうとはあさからむすっとしたかおですわっている。","example_meaning":"Em gái tôi từ sáng đã ngồi với vẻ mặt cau có."}],"level":"b1"},
{"word":"わんわん","reading":"わんわん","meaning":"tiếng chó sủa; khóc oà","note":"Hay đi với 吠える, 泣く. Tiếng chó sủa; cũng là tiếng khóc to.","example":"隣の犬が夜中にわんわん吠えて眠れなかった。","example_reading":"となりのいぬがよなかにわんわんほえてねむれなかった。","example_meaning":"Con chó nhà bên sủa inh ỏi giữa đêm khiến tôi không ngủ được.","examples":[{"example":"隣の犬が夜中にわんわん吠えて眠れなかった。","example_reading":"となりのいぬがよなかにわんわんほえてねむれなかった。","example_meaning":"Con chó nhà bên sủa inh ỏi giữa đêm khiến tôi không ngủ được."},{"example":"迷子の男の子は母親を見つけて、わんわん泣き出した。","example_reading":"まいごのおとこのこはははおやをみつけて、わんわんなきだした。","example_meaning":"Cậu bé lạc thấy mẹ liền khóc oà lên."}],"level":"b1"},
{"word":"ちくちく","reading":"ちくちく","meaning":"châm chích, ngứa ngáy","note":"Từ tượng hình. Cảm giác bị kim hoặc len thô châm vào da.","example":"このセーターは首がちくちくします。","example_reading":"このセーターはくびがちくちくします。","example_meaning":"Chiếc áo len này làm cổ tôi ngứa ngáy.","examples":[{"example":"このセーターは首がちくちくします。","example_reading":"このセーターはくびがちくちくします。","example_meaning":"Chiếc áo len này làm cổ tôi ngứa ngáy."},{"example":"髭が伸びて、頬がちくちくする。","example_reading":"ひげがのびて、ほおがちくちくする。","example_meaning":"Râu mọc dài nên má tôi châm chích."}],"level":"b1"},
{"word":"むずむず","reading":"むずむず","meaning":"ngứa ngáy; nôn nóng muốn làm","note":"Ngứa nhẹ khó chịu, hoặc rất muốn làm điều gì. Hay đi với 鼻, する.","example":"花粉のせいで、鼻がむずむずする。","example_reading":"かふんのせいで、はながむずむずする。","example_meaning":"Vì phấn hoa nên mũi tôi ngứa ngáy.","examples":[{"example":"花粉のせいで、鼻がむずむずする。","example_reading":"かふんのせいで、はながむずむずする。","example_meaning":"Vì phấn hoa nên mũi tôi ngứa ngáy."},{"example":"話したくて、口がむずむずしている。","example_reading":"はなしたくて、くちがむずむずしている。","example_meaning":"Tôi nôn nóng muốn nói quá nên miệng ngứa ngáy."}],"level":"b1"},
{"word":"ぐにゃり","reading":"ぐにゃり","meaning":"cong oặt, mềm nhũn","antonym":"ぴんと: căng thẳng","note":"Hay đi với と, 曲がる, 座り込む.","example":"熱い鉄の棒が、ぐにゃりと曲がった。","example_reading":"あついてつのぼうが、ぐにゃりとまがった。","example_meaning":"Thanh sắt nóng uốn cong oặt đi.","examples":[{"example":"熱い鉄の棒が、ぐにゃりと曲がった。","example_reading":"あついてつのぼうが、ぐにゃりとまがった。","example_meaning":"Thanh sắt nóng uốn cong oặt đi."},{"example":"彼は力が抜けて、ぐにゃりと床に座り込んだ。","example_reading":"かれはちからがぬけて、ぐにゃりとゆかにすわりこんだ。","example_meaning":"Anh ấy mất sức, ngồi sụp mềm nhũn xuống sàn."}],"level":"b1"},
{"word":"ごわごわ","reading":"ごわごわ","meaning":"cứng, sượng (vải, tóc)","antonym":"ふかふか: mềm xốp / ふわふわ: nhẹ xốp / すべすべ: mịn màng","note":"Hay đi với 乾く, した髪. Mất độ mềm.","example":"洗濯したタオルが、乾いてごわごわになった。","example_reading":"せんたくしたタオルが、かわいてごわごわになった。","example_meaning":"Khăn giặt xong phơi khô lại cứng sượng.","examples":[{"example":"洗濯したタオルが、乾いてごわごわになった。","example_reading":"せんたくしたタオルが、かわいてごわごわになった。","example_meaning":"Khăn giặt xong phơi khô lại cứng sượng."},{"example":"ごわごわした髪をまとめるのに苦労する。","example_reading":"ごわごわしたかみをまとめるのにくろうする。","example_meaning":"Tóc cứng khó vuốt nên tôi vất vả khi buộc."}],"level":"b1"},
{"word":"ざくざく","reading":"ざくざく","meaning":"lạo xạo; (cắt) phăng phăng","note":"Hay đi với 歩く, 切る. Tiếng giẫm lên tuyết, sỏi hoặc cắt nhanh.","example":"雪道を、ざくざくと音を立てて歩いた。","example_reading":"ゆきみちを、ざくざくとおとをたててあるいた。","example_meaning":"Tôi bước đi lạo xạo trên đường tuyết.","examples":[{"example":"雪道を、ざくざくと音を立てて歩いた。","example_reading":"ゆきみちを、ざくざくとおとをたててあるいた。","example_meaning":"Tôi bước đi lạo xạo trên đường tuyết."},{"example":"キャベツを、ざくざく切って鍋に入れた。","example_reading":"キャベツを、ざくざくきってなべにいれた。","example_meaning":"Tôi cắt phăng phăng bắp cải rồi cho vào nồi."}],"level":"b1"},
{"word":"がくがく","reading":"がくがく","meaning":"run, lảo đảo (chân)","note":"Hay đi với 震える, なる. Chân yếu hoặc run vì mệt, sợ.","example":"山を下りて、足ががくがくになった。","example_reading":"やまをおりて、あしががくがくになった。","example_meaning":"Xuống núi xong, chân tôi run lẩy bẩy.","examples":[{"example":"山を下りて、足ががくがくになった。","example_reading":"やまをおりて、あしががくがくになった。","example_meaning":"Xuống núi xong, chân tôi run lẩy bẩy."},{"example":"緊張して、膝ががくがく震えた。","example_reading":"きんちょうして、ひざががくがくふるえた。","example_meaning":"Căng thẳng nên đầu gối tôi run bần bật."}],"level":"b1"},
{"word":"うるうる","reading":"うるうる","meaning":"rưng rưng","note":"Hay đi với する, 目. Mắt ngấn nước.","example":"感動して、彼女の目がうるうるしていた。","example_reading":"かんどうして、かのじょのめがうるうるしていた。","example_meaning":"Xúc động đến mức mắt cô ấy rưng rưng.","examples":[{"example":"感動して、彼女の目がうるうるしていた。","example_reading":"かんどうして、かのじょのめがうるうるしていた。","example_meaning":"Xúc động đến mức mắt cô ấy rưng rưng."},{"example":"子犬が、うるうるした目でこちらを見ている。","example_reading":"こいぬが、うるうるしためでこちらをみている。","example_meaning":"Chú chó con nhìn tôi bằng đôi mắt ướt long lanh."}],"level":"b1"},
{"word":"ひりひり","reading":"ひりひり","meaning":"rát, xót","note":"Cảm giác đau rát trên da hoặc niêm mạc. Hay đi với 日焼け, 傷, 喉.","example":"海で日焼けして、背中がひりひりする。","example_reading":"うみでひやけして、せなかがひりひりする。","example_meaning":"Đi biển bị cháy nắng nên lưng tôi rát.","examples":[{"example":"海で日焼けして、背中がひりひりする。","example_reading":"うみでひやけして、せなかがひりひりする。","example_meaning":"Đi biển bị cháy nắng nên lưng tôi rát."},{"example":"カレーが辛すぎて、舌がひりひりした。","example_reading":"カレーがからすぎて、したがひりひりした。","example_meaning":"Món cà ri cay quá nên lưỡi tôi bị xót."}],"level":"b1"},
{"word":"がんがん","reading":"がんがん","meaning":"nhức ầm ầm; mạnh hết cỡ","note":"Đau đầu dữ dội, hoặc làm gì đó cường độ mạnh. Hay đi với 頭が痛い, 鳴る, 効く.","example":"風邪で頭ががんがん痛む。","example_reading":"かぜであたまががんがんいたむ。","example_meaning":"Bị cảm nên đầu tôi nhức ầm ầm.","examples":[{"example":"風邪で頭ががんがん痛む。","example_reading":"かぜであたまががんがんいたむ。","example_meaning":"Bị cảm nên đầu tôi nhức ầm ầm."},{"example":"クーラーをがんがんかけて、部屋を冷やした。","example_reading":"クーラーをがんがんかけて、へやをひやした。","example_meaning":"Tôi bật điều hòa hết công suất để làm lạnh phòng."}],"level":"b1"},
{"word":"ぱさぱさ","reading":"ぱさぱさ","meaning":"khô khốc, khô xơ","antonym":"しっとり: ẩm mượt / もっちり: dẻo mềm / もちもち: dẻo dai","note":"Hay đi với パン, 髪, 肌, 肉. Mất độ ẩm.","example":"昨日のパンは固くて、ぱさぱさしていた。","example_reading":"きのうのパンはかたくて、ぱさぱさしていた。","example_meaning":"Bánh mì hôm qua cứng và khô khốc.","examples":[{"example":"昨日のパンは固くて、ぱさぱさしていた。","example_reading":"きのうのパンはかたくて、ぱさぱさしていた。","example_meaning":"Bánh mì hôm qua cứng và khô khốc."},{"example":"冬は肌がぱさぱさになるので、クリームが欠かせない。","example_reading":"ふゆははだがぱさぱさになるので、クリームがかかせない。","example_meaning":"Mùa đông da khô ráp nên không thể thiếu kem dưỡng."}],"level":"b1"},
{"word":"ほっこり","reading":"ほっこり","meaning":"ấm lòng, dễ chịu","note":"Hay đi với する. Cảm giác ấm áp, thư thái trong lòng.","example":"温かいお茶を飲んで、ほっこりした気分になった。","example_reading":"あたたかいおちゃをのんで、ほっこりしたきぶんになった。","example_meaning":"Uống trà nóng, lòng tôi thấy ấm áp dễ chịu.","examples":[{"example":"温かいお茶を飲んで、ほっこりした気分になった。","example_reading":"あたたかいおちゃをのんで、ほっこりしたきぶんになった。","example_meaning":"Uống trà nóng, lòng tôi thấy ấm áp dễ chịu."},{"example":"子どもの寝顔を見ると、ほっこりする。","example_reading":"こどものねがおをみると、ほっこりする。","example_meaning":"Nhìn gương mặt con ngủ, lòng tôi thấy ấm áp."}],"level":"b1"},
{"word":"ひょっこり","reading":"ひょっこり","meaning":"bất chợt xuất hiện","note":"Hay đi với 現れる, 顔を出す, 帰る. Xuất hiện bất ngờ, không báo trước.","example":"三年ぶりに、彼がひょっこり帰ってきた。","example_reading":"さんねんぶりに、かれがひょっこりかえってきた。","example_meaning":"Sau ba năm, anh ấy bất ngờ trở về.","examples":[{"example":"三年ぶりに、彼がひょっこり帰ってきた。","example_reading":"さんねんぶりに、かれがひょっこりかえってきた。","example_meaning":"Sau ba năm, anh ấy bất ngờ trở về."},{"example":"夕方、隣の犬が庭にひょっこり顔を出した。","example_reading":"ゆうがた、となりのいぬがにわにひょっこりかおをだした。","example_meaning":"Chiều tối, con chó nhà bên bất chợt thò mặt vào vườn."}],"level":"b1"},
{"word":"ぱったり","reading":"ぱったり","meaning":"đột ngột ngừng hẳn","note":"Hay đi với 止む, 途絶える, 来なくなる. Đang thường xuyên bỗng dừng hẳn.","example":"毎日来ていた客が、ぱったり来なくなった。","example_reading":"まいにちきていたきゃくが、ぱったりこなくなった。","example_meaning":"Vị khách ngày nào cũng đến bỗng không đến nữa.","examples":[{"example":"毎日来ていた客が、ぱったり来なくなった。","example_reading":"まいにちきていたきゃくが、ぱったりこなくなった。","example_meaning":"Vị khách ngày nào cũng đến bỗng không đến nữa."},{"example":"彼からの連絡が、ぱったりと途絶えてしまった。","example_reading":"かれからのれんらくが、ぱったりととだえてしまった。","example_meaning":"Liên lạc từ anh ấy đột ngột ngừng hẳn."}],"level":"b1"},
{"word":"ぶるっと","reading":"ぶるっと","meaning":"rùng mình","note":"Hay đi với 震える, 身震いする. Run nhẹ vì lạnh hoặc sợ.","example":"冷たい風が吹いて、思わずぶるっと震えた。","example_reading":"つめたいかぜがふいて、おもわずぶるっとふるえた。","example_meaning":"Gió lạnh thổi, tôi bất giác rùng mình.","examples":[{"example":"冷たい風が吹いて、思わずぶるっと震えた。","example_reading":"つめたいかぜがふいて、おもわずぶるっとふるえた。","example_meaning":"Gió lạnh thổi, tôi bất giác rùng mình."},{"example":"怖い話を聞いて、ぶるっと身震いした。","example_reading":"こわいはなしをきいて、ぶるっとみぶるいした。","example_meaning":"Nghe chuyện đáng sợ, tôi rùng mình."}],"level":"b1"},
{"word":"ちかちか","reading":"ちかちか","meaning":"chói mắt, nhấp nháy","note":"Hay đi với 目, 光, する. Ánh sáng nháy làm mỏi mắt.","example":"長時間パソコンを見ていたら、目がちかちかしてきた。","example_reading":"ちょうじかんパソコンをみていたら、めがちかちかしてきた。","example_meaning":"Nhìn máy tính lâu nên mắt tôi bắt đầu nhấp nháy, mỏi.","examples":[{"example":"長時間パソコンを見ていたら、目がちかちかしてきた。","example_reading":"ちょうじかんパソコンをみていたら、めがちかちかしてきた。","example_meaning":"Nhìn máy tính lâu nên mắt tôi bắt đầu nhấp nháy, mỏi."},{"example":"蛍光灯がちかちかして、落ち着かない。","example_reading":"けいこうとうがちかちかして、おちつかない。","example_meaning":"Bóng đèn huỳnh quang nhấp nháy làm tôi khó chịu."}],"level":"b1"},
{"word":"すっぽり","reading":"すっぽり","meaning":"vừa khít, trùm kín","note":"Hay đi với 入る, 隠れる, 覆う, はまる.","example":"赤ちゃんは母親の腕の中にすっぽり収まった。","example_reading":"あかちゃんはははおやのうでのなかにすっぽりおさまった。","example_meaning":"Em bé nằm gọn lỏn trong vòng tay mẹ.","examples":[{"example":"赤ちゃんは母親の腕の中にすっぽり収まった。","example_reading":"あかちゃんはははおやのうでのなかにすっぽりおさまった。","example_meaning":"Em bé nằm gọn lỏn trong vòng tay mẹ."},{"example":"雪で町がすっぽり覆われた。","example_reading":"ゆきでまちがすっぽりおおわれた。","example_meaning":"Tuyết phủ kín cả thị trấn."}],"level":"b1"},
{"word":"がっちり","reading":"がっちり","meaning":"chắc nịch, vững chắc; (người) keo kiệt","note":"Hay đi với 組む, 握る, した体. がっちりした体 = thân hình vạm vỡ.","example":"二人はがっちりと握手を交わした。","example_reading":"ふたりはがっちりとあくしゅをかわした。","example_meaning":"Hai người bắt tay thật chặt.","examples":[{"example":"二人はがっちりと握手を交わした。","example_reading":"ふたりはがっちりとあくしゅをかわした。","example_meaning":"Hai người bắt tay thật chặt."},{"example":"彼はスポーツをしていて、がっちりした体つきだ。","example_reading":"かれはスポーツをしていて、がっちりしたからだつきだ。","example_meaning":"Anh ấy chơi thể thao nên thân hình vạm vỡ."}],"level":"b1"},
{"word":"むかむか","reading":"むかむか","meaning":"buồn nôn, cồn cào; tức tối","antonym":"すっきり: sảng khoái","note":"Từ tượng hình. Dạ dày khó chịu hoặc cơn bực dâng lên.","example":"食べ過ぎて、胃がむかむかします。","example_reading":"たべすぎて、いがむかむかします。","example_meaning":"Ăn quá nhiều nên dạ dày cồn cào.","examples":[{"example":"食べ過ぎて、胃がむかむかします。","example_reading":"たべすぎて、いがむかむかします。","example_meaning":"Ăn quá nhiều nên dạ dày cồn cào."},{"example":"彼の失礼な態度に、むかむかした。","example_reading":"かれのしつれいなたいどに、むかむかした。","example_meaning":"Trước thái độ thất lễ của anh ta, tôi nổi cơn bực."}],"level":"b1"},
{"word":"くらくら","reading":"くらくら","meaning":"chóng mặt, choáng váng","antonym":"しゃきっと: tỉnh táo","note":"Từ tượng hình. Do nóng, thiếu máu, mùi mạnh.","example":"暑さで頭がくらくらした。","example_reading":"あつさであたまがくらくらした。","example_meaning":"Vì nóng nên tôi bị choáng.","examples":[{"example":"暑さで頭がくらくらした。","example_reading":"あつさであたまがくらくらした。","example_meaning":"Vì nóng nên tôi bị choáng."},{"example":"急に立ち上がったら、頭がくらくらした。","example_reading":"きゅうにたちあがったら、あたまがくらくらした。","example_meaning":"Đứng bật dậy đột ngột, tôi thấy choáng váng."}],"level":"b1"},
{"word":"ぼんやり","reading":"ぼんやり","meaning":"đờ đẫn, lơ đãng; mờ mờ","antonym":"はっきり: rõ ràng / くっきり: rõ nét / 鮮明に（せんめいに）: rõ nét","antonym_hanviet":" /  / tiên minh","note":"Từ tượng hình. Hay đi với する, 見える.","example":"疲れて、ぼんやりしていました。","example_reading":"つかれて、ぼんやりしていました。","example_meaning":"Tôi mệt nên cứ đờ đẫn.","examples":[{"example":"疲れて、ぼんやりしていました。","example_reading":"つかれて、ぼんやりしていました。","example_meaning":"Tôi mệt nên cứ đờ đẫn."},{"example":"遠くの山がぼんやりと見えた。","example_reading":"とおくのやまがぼんやりとみえた。","example_meaning":"Ngọn núi xa mờ mờ hiện ra."}],"level":"b1"},
{"word":"ぴちぴち","reading":"ぴちぴち","meaning":"chật cứng; tươi rói, tràn sức sống","antonym":"ぶかぶか: rộng thùng thình / だぶだぶ: rộng thùng thình","note":"Hay đi với 服, 魚, 若い. Quần áo chật ôm sát, hoặc cá tươi giãy tanh tách.","example":"太ってしまって、去年のズボンがぴちぴちになった。","example_reading":"ふとってしまって、きょねんのズボンがぴちぴちになった。","example_meaning":"Tôi béo lên nên chiếc quần năm ngoái đã chật cứng.","examples":[{"example":"太ってしまって、去年のズボンがぴちぴちになった。","example_reading":"ふとってしまって、きょねんのズボンがぴちぴちになった。","example_meaning":"Tôi béo lên nên chiếc quần năm ngoái đã chật cứng."},{"example":"市場で、ぴちぴちした新鮮な魚が売られていた。","example_reading":"いちばで、ぴちぴちしたしんせんなさかながうられていた。","example_meaning":"Ở chợ có bán những con cá tươi rói đang giãy."}],"level":"b1"},
{"word":"くねくね","reading":"くねくね","meaning":"ngoằn ngoèo, uốn éo","antonym":"まっすぐ: thẳng tắp / ぴんと: căng thẳng","note":"Hay đi với 曲がる, 道, 動く.","example":"山道がくねくねと曲がっていて、運転が大変だった。","example_reading":"やまみちがくねくねとまがっていて、うんてんがたいへんだった。","example_meaning":"Đường núi ngoằn ngoèo nên lái xe rất vất vả.","examples":[{"example":"山道がくねくねと曲がっていて、運転が大変だった。","example_reading":"やまみちがくねくねとまがっていて、うんてんがたいへんだった。","example_meaning":"Đường núi ngoằn ngoèo nên lái xe rất vất vả."},{"example":"蛇が草の中をくねくねと進んでいった。","example_reading":"へびがくさのなかをくねくねとすすんでいった。","example_meaning":"Con rắn ngoằn ngoèo bò qua đám cỏ."}],"level":"b1"},
{"word":"じゅわっと","reading":"じゅわっと","meaning":"rịn ra, tứa nước","note":"Hay đi với 広がる, 染み出る. Nước hoặc dầu thấm ra, tứa ra.","example":"肉を噛むと、じゅわっと肉汁があふれ出した。","example_reading":"にくをかむと、じゅわっとにくじるがあふれだした。","example_meaning":"Cắn miếng thịt, nước thịt tứa ra.","examples":[{"example":"肉を噛むと、じゅわっと肉汁があふれ出した。","example_reading":"にくをかむと、じゅわっとにくじるがあふれだした。","example_meaning":"Cắn miếng thịt, nước thịt tứa ra."},{"example":"焼きたてのパンにバターを乗せると、じゅわっと溶けた。","example_reading":"やきたてのパンにバターをのせると、じゅわっととけた。","example_meaning":"Đặt bơ lên bánh mì mới nướng, bơ tan chảy ngay."}],"level":"b1"},
{"word":"ひらり","reading":"ひらり","meaning":"nhẹ nhàng (nhảy, bay)","note":"Hay đi với と, 飛ぶ, 舞う. Nhẹ và nhanh gọn.","example":"桜の花びらが、ひらりと肩に落ちてきた。","example_reading":"さくらのはなびらが、ひらりとかたにおちてきた。","example_meaning":"Cánh hoa anh đào nhẹ nhàng rơi xuống vai.","examples":[{"example":"桜の花びらが、ひらりと肩に落ちてきた。","example_reading":"さくらのはなびらが、ひらりとかたにおちてきた。","example_meaning":"Cánh hoa anh đào nhẹ nhàng rơi xuống vai."},{"example":"猫はひらりと塀の上に飛び乗った。","example_reading":"ねこはひらりとへいのうえにとびのった。","example_meaning":"Con mèo nhẹ nhàng nhảy lên bờ tường."}],"level":"b1"},
{"word":"ちょこんと","reading":"ちょこんと","meaning":"nhỏ nhắn, gọn gàng","note":"Hay đi với 座る, 乗る, 置く. Vật nhỏ ở vị trí gọn, dễ thương.","example":"小さな猫が、箱の中にちょこんと座っていた。","example_reading":"ちいさなねこが、はこのなかにちょこんとすわっていた。","example_meaning":"Chú mèo nhỏ ngồi gọn trong chiếc hộp.","examples":[{"example":"小さな猫が、箱の中にちょこんと座っていた。","example_reading":"ちいさなねこが、はこのなかにちょこんとすわっていた。","example_meaning":"Chú mèo nhỏ ngồi gọn trong chiếc hộp."},{"example":"机の上に、小さな人形がちょこんと置いてある。","example_reading":"つくえのうえに、ちいさなにんぎょうがちょこんとおいてある。","example_meaning":"Trên bàn có một con búp bê nhỏ đặt gọn gàng."}],"level":"b1"},
{"word":"ぷらぷら","reading":"ぷらぷら","meaning":"đu đưa; đi lang thang","note":"Hay đi với 揺れる, 歩く. Lắc lư nhẹ hoặc đi dạo không mục đích.","example":"子どもが、ベンチで足をぷらぷらさせている。","example_reading":"こどもが、ベンチであしをぷらぷらさせている。","example_meaning":"Đứa bé ngồi ghế đu đưa đôi chân.","examples":[{"example":"子どもが、ベンチで足をぷらぷらさせている。","example_reading":"こどもが、ベンチであしをぷらぷらさせている。","example_meaning":"Đứa bé ngồi ghế đu đưa đôi chân."},{"example":"休みの日は、街をぷらぷら歩くのが好きだ。","example_reading":"やすみのひは、まちをぷらぷらあるくのがすきだ。","example_meaning":"Ngày nghỉ tôi thích đi dạo lang thang trong phố."}],"level":"b1"},
{"word":"むっつり","reading":"むっつり","meaning":"im lìm, ủ ê","note":"Hay đi với と, する, 黙り込む. Ít nói, mặt không vui.","example":"彼は朝から、むっつりと黙り込んでいる。","example_reading":"かれはあさから、むっつりとだまりこんでいる。","example_meaning":"Từ sáng anh ấy cứ ủ rũ im lặng.","examples":[{"example":"彼は朝から、むっつりと黙り込んでいる。","example_reading":"かれはあさから、むっつりとだまりこんでいる。","example_meaning":"Từ sáng anh ấy cứ ủ rũ im lặng."},{"example":"父はむっつりした顔で、新聞を読んでいた。","example_reading":"ちちはむっつりしたかおで、しんぶんをよんでいた。","example_meaning":"Bố tôi đọc báo với vẻ mặt trầm lặng."}],"level":"b1"},
{"word":"がくん","reading":"がくん","meaning":"chùng xuống, gục xuống","note":"Hay đi với と, 落ちる, 傾く. Giảm hoặc nghiêng đột ngột.","example":"電車が急に止まって、体ががくんと前に傾いた。","example_reading":"でんしゃがきゅうにとまって、からだががくんとまえにかたむいた。","example_meaning":"Tàu phanh gấp nên người tôi chúi hẳn về phía trước.","examples":[{"example":"電車が急に止まって、体ががくんと前に傾いた。","example_reading":"でんしゃがきゅうにとまって、からだががくんとまえにかたむいた。","example_meaning":"Tàu phanh gấp nên người tôi chúi hẳn về phía trước."},{"example":"疲れがたまって、体力ががくんと落ちた。","example_reading":"つかれがたまって、たいりょくががくんとおちた。","example_meaning":"Mệt mỏi tích tụ khiến thể lực tụt hẳn."}],"level":"b1"},
{"word":"ぷつん","reading":"ぷつん","meaning":"phựt (đứt)","note":"Hay đi với と, 切れる. Dây hay mối liên kết đứt đột ngột.","example":"糸が、ぷつんと切れてしまった。","example_reading":"いとが、ぷつんときれてしまった。","example_meaning":"Sợi chỉ đứt đánh phựt.","examples":[{"example":"糸が、ぷつんと切れてしまった。","example_reading":"いとが、ぷつんときれてしまった。","example_meaning":"Sợi chỉ đứt đánh phựt."},{"example":"緊張の糸が、ぷつんと切れて、涙が出た。","example_reading":"きんちょうのいとが、ぷつんときれて、なみだがでた。","example_meaning":"Sợi dây căng thẳng đứt phựt, nước mắt tôi trào ra."}],"level":"b1"},
{"word":"へらへら","reading":"へらへら","meaning":"cười nhơn nhơn","antonym":"むすっと: sưng sỉa / きりっと: nghiêm nghị","note":"Hay đi với 笑う. Sắc thái chê: cười không nghiêm túc.","example":"注意されているのに、へらへら笑っている。","example_reading":"ちゅういされているのに、へらへらわらっている。","example_meaning":"Đang bị nhắc nhở mà vẫn cười nhơn nhơn.","examples":[{"example":"注意されているのに、へらへら笑っている。","example_reading":"ちゅういされているのに、へらへらわらっている。","example_meaning":"Đang bị nhắc nhở mà vẫn cười nhơn nhơn."},{"example":"彼はいつもへらへらして、真剣さが感じられない。","example_reading":"かれはいつもへらへらして、しんけんさがかんじられない。","example_meaning":"Anh ta lúc nào cũng cười cợt, chẳng thấy nghiêm túc."}],"level":"b1"},
{"word":"ぼそっと","reading":"ぼそっと","meaning":"lẩm bẩm, nói nhỏ","antonym":"はきはき: rành rọt / 大声で（おおごえで）: nói to","antonym_hanviet":" / đại thanh","note":"Hay đi với 言う, つぶやく. Nói nhỏ như tự nói với mình.","example":"彼は「疲れた」とぼそっとつぶやいた。","example_reading":"かれは「つかれた」とぼそっとつぶやいた。","example_meaning":"Anh ấy lẩm bẩm \"mệt quá\".","examples":[{"example":"彼は「疲れた」とぼそっとつぶやいた。","example_reading":"かれは「つかれた」とぼそっとつぶやいた。","example_meaning":"Anh ấy lẩm bẩm \"mệt quá\"."},{"example":"後ろの席から、誰かがぼそっと文句を言った。","example_reading":"うしろのせきから、だれかがぼそっともんくをいった。","example_meaning":"Từ hàng ghế sau, ai đó lầm bầm phàn nàn."}],"level":"b1"},
{"word":"ぼそぼそ","reading":"ぼそぼそ","meaning":"nói lí nhí; (đồ ăn) khô rời","antonym":"はきはき: rành rọt","note":"Hay đi với 話す. Nói nhỏ khó nghe; cũng chỉ thức ăn khô, rời rạc.","example":"彼はぼそぼそ話すので、何を言っているのか聞き取れない。","example_reading":"かれはぼそぼそはなすので、なにをいっているのかききとれない。","example_meaning":"Anh ấy nói lí nhí nên không nghe rõ nói gì.","examples":[{"example":"彼はぼそぼそ話すので、何を言っているのか聞き取れない。","example_reading":"かれはぼそぼそはなすので、なにをいっているのかききとれない。","example_meaning":"Anh ấy nói lí nhí nên không nghe rõ nói gì."},{"example":"古いご飯は、ぼそぼそして味がしなかった。","example_reading":"ふるいごはんは、ぼそぼそしてあじがしなかった。","example_meaning":"Cơm cũ khô rời, chẳng có vị gì."}],"level":"b1"},
{"word":"ぽきっと","reading":"ぽきっと","meaning":"rắc (gãy giòn)","note":"Hay đi với 折れる, 折る. Tiếng gãy giòn của vật cứng mảnh.","example":"力を入れすぎて、鉛筆がぽきっと折れた。","example_reading":"ちからをいれすぎて、えんぴつがぽきっとおれた。","example_meaning":"Dùng sức quá mạnh nên cây bút chì gãy đánh rắc.","examples":[{"example":"力を入れすぎて、鉛筆がぽきっと折れた。","example_reading":"ちからをいれすぎて、えんぴつがぽきっとおれた。","example_meaning":"Dùng sức quá mạnh nên cây bút chì gãy đánh rắc."},{"example":"枯れた枝を踏むと、ぽきっと音がした。","example_reading":"かれたえだをふむと、ぽきっとおとがした。","example_meaning":"Giẫm lên cành khô, nghe tiếng rắc."}],"level":"b1"},
{"word":"ぽーっと","reading":"ぽーっと","meaning":"thẫn thờ, đỏ bừng","antonym":"しゃきっと: tỉnh táo","note":"Hay đi với する, なる. Đầu nóng, ngẩn ra vì sốt hoặc say mê.","example":"熱があって、頭がぽーっとしている。","example_reading":"ねつがあって、あたまがぽーっとしている。","example_meaning":"Bị sốt nên đầu óc lâng lâng.","examples":[{"example":"熱があって、頭がぽーっとしている。","example_reading":"ねつがあって、あたまがぽーっとしている。","example_meaning":"Bị sốt nên đầu óc lâng lâng."},{"example":"彼女は憧れの先輩を見て、ぽーっと顔を赤らめた。","example_reading":"かのじょはあこがれのせんぱいをみて、ぽーっとかおをあからめた。","example_meaning":"Thấy anh khóa trên mình ngưỡng mộ, cô ấy ngẩn ra, mặt đỏ bừng."}],"level":"b1"},
{"word":"ぱくり","reading":"ぱくり","meaning":"ngoạm một miếng","note":"Hay đi với 食べる, 食いつく. Cắn gọn một miếng, nhanh hơn ぱくっと.","example":"子どもは大きな口を開けて、ケーキをぱくりと食べた。","example_reading":"こどもはおおきなくちをあけて、ケーキをぱくりとたべた。","example_meaning":"Đứa bé mở miệng to và ngoạm một miếng bánh.","examples":[{"example":"子どもは大きな口を開けて、ケーキをぱくりと食べた。","example_reading":"こどもはおおきなくちをあけて、ケーキをぱくりとたべた。","example_meaning":"Đứa bé mở miệng to và ngoạm một miếng bánh."},{"example":"魚が餌にぱくりと食いついた。","example_reading":"さかながえさにぱくりとくいついた。","example_meaning":"Con cá ngoạm gọn mồi câu."}],"level":"b1"},
{"word":"もこもこ","reading":"もこもこ","meaning":"bông xù, phồng xốp","note":"Hay đi với した服, 手袋. Mềm, dày, xù lông.","example":"冬は、もこもこしたセーターが手放せない。","example_reading":"ふゆは、もこもこしたセーターがてばなせない。","example_meaning":"Mùa đông tôi không thể thiếu chiếc áo len xù bông.","examples":[{"example":"冬は、もこもこしたセーターが手放せない。","example_reading":"ふゆは、もこもこしたセーターがてばなせない。","example_meaning":"Mùa đông tôi không thể thiếu chiếc áo len xù bông."},{"example":"もこもこの手袋をして、雪遊びに出かけた。","example_reading":"もこもこのてぶくろをして、ゆきあそびにでかけた。","example_meaning":"Đeo đôi găng tay bông xù, tôi ra ngoài chơi tuyết."}],"level":"b1"},
{"word":"がりがり","reading":"がりがり","meaning":"gầy trơ xương; nghiến lạo xạo","antonym":"ふっくら: phồng mềm / ぽっちゃり: mũm mĩm / むちむち: mũm mĩm","note":"Hay đi với 痩せる, 噛む, 削る. Người gầy, hoặc tiếng nghiến cứng.","example":"彼は食べても太らず、がりがりに痩せている。","example_reading":"かれはたべてもふとらず、がりがりにやせている。","example_meaning":"Anh ấy ăn mãi không béo, gầy trơ xương.","examples":[{"example":"彼は食べても太らず、がりがりに痩せている。","example_reading":"かれはたべてもふとらず、がりがりにやせている。","example_meaning":"Anh ấy ăn mãi không béo, gầy trơ xương."},{"example":"氷をがりがり噛む癖がある。","example_reading":"こおりをがりがりかむくせがある。","example_meaning":"Tôi có thói quen nhai đá lạo xạo."}],"level":"b1"},
{"word":"げっそり","reading":"げっそり","meaning":"hốc hác, tiều tụy","antonym":"ふっくら: đầy đặn / ぽっちゃり: mũm mĩm / でっぷり: bụng phệ","note":"Hay đi với 痩せる, する. Gầy sút đột ngột vì mệt hoặc bệnh.","example":"看病で疲れて、母はげっそりと痩せてしまった。","example_reading":"かんびょうでつかれて、ははがげっそりとやせてしまった。","example_meaning":"Mệt vì chăm bệnh, mẹ tôi gầy hốc hác.","examples":[{"example":"看病で疲れて、母はげっそりと痩せてしまった。","example_reading":"かんびょうでつかれて、ははがげっそりとやせてしまった。","example_meaning":"Mệt vì chăm bệnh, mẹ tôi gầy hốc hác."},{"example":"連日の残業で、彼の顔はげっそりしていた。","example_reading":"れんじつのざんぎょうで、かれのかおはげっそりしていた。","example_meaning":"Làm thêm giờ liên tục khiến mặt anh ấy hốc hác."}],"level":"b1"},
{"word":"ゆるゆる","reading":"ゆるゆる","meaning":"lỏng lẻo; thong thả","antonym":"ぴったり: vừa khít / きつきつ: chật cứng / ぎゅうぎゅう: chật ních","note":"Hay đi với 緩い, 過ごす. Quần áo lỏng, hoặc nhịp sống chậm rãi.","example":"靴ひもがゆるゆるで、歩きにくい。","example_reading":"くつひもがゆるゆるで、あるきにくい。","example_meaning":"Dây giày lỏng nên khó đi.","examples":[{"example":"靴ひもがゆるゆるで、歩きにくい。","example_reading":"くつひもがゆるゆるで、あるきにくい。","example_meaning":"Dây giày lỏng nên khó đi."},{"example":"休日は、ゆるゆるとした気分で過ごしている。","example_reading":"きゅうじつは、ゆるゆるとしたきぶんですごしている。","example_meaning":"Ngày nghỉ tôi sống với tâm trạng thong thả."}],"level":"b1"},
{"word":"むしゃくしゃ","reading":"むしゃくしゃ","meaning":"bực bội, bức bối","antonym":"すっきり: sảng khoái / さっぱり: sảng khoái","note":"Hay đi với する. Tâm trạng khó chịu, muốn xả ra.","example":"嫌なことが続いて、むしゃくしゃして仕方がない。","example_reading":"いやなことがつづいて、むしゃくしゃしてしかたがない。","example_meaning":"Chuyện không vui cứ liên tiếp nên tôi bực bội vô cùng.","examples":[{"example":"嫌なことが続いて、むしゃくしゃして仕方がない。","example_reading":"いやなことがつづいて、むしゃくしゃしてしかたがない。","example_meaning":"Chuyện không vui cứ liên tiếp nên tôi bực bội vô cùng."},{"example":"むしゃくしゃしたときは、思い切り走ることにしている。","example_reading":"むしゃくしゃしたときは、おもいきりはしることにしている。","example_meaning":"Khi bức bối, tôi thường chạy hết sức."}],"level":"b1"},
{"word":"ぷかぷか","reading":"ぷかぷか","meaning":"lềnh bềnh; phì phèo","note":"Hay đi với 浮かぶ, 煙. Trôi nổi trên nước; hút thuốc phì phèo.","example":"池に、アヒルがぷかぷか浮かんでいる。","example_reading":"いけに、アヒルがぷかぷかうかんでいる。","example_meaning":"Trên ao, con vịt trôi lềnh bềnh.","examples":[{"example":"池に、アヒルがぷかぷか浮かんでいる。","example_reading":"いけに、アヒルがぷかぷかうかんでいる。","example_meaning":"Trên ao, con vịt trôi lềnh bềnh."},{"example":"祖父は縁側でたばこをぷかぷか吸っていた。","example_reading":"そふはえんがわでたばこをぷかぷかすっていた。","example_meaning":"Ông tôi ngồi hiên hút thuốc phì phèo."}],"level":"b1"},
{"word":"くたっと","reading":"くたっと","meaning":"rũ xuống, héo (vải, rau)","antonym":"しゃきっと: tỉnh táo / ぴんと: căng thẳng","note":"Hay đi với 柔らかい, 萎れる. Mất độ cứng.","example":"冷蔵庫に入れ忘れて、野菜がくたっとしてしまった。","example_reading":"れいぞうこにいれわすれて、やさいがくたっとしてしまった。","example_meaning":"Quên bỏ vào tủ lạnh nên rau bị héo rũ.","examples":[{"example":"冷蔵庫に入れ忘れて、野菜がくたっとしてしまった。","example_reading":"れいぞうこにいれわすれて、やさいがくたっとしてしまった。","example_meaning":"Quên bỏ vào tủ lạnh nên rau bị héo rũ."},{"example":"何度も洗って、シャツがくたっとした着心地になった。","example_reading":"なんどもあらって、シャツがくたっとしたきごこちになった。","example_meaning":"Giặt nhiều lần nên chiếc áo mềm rũ, mặc rất dễ chịu."}],"level":"b1"},
{"word":"ぱたん","reading":"ぱたん","meaning":"cạch, bịch (đóng/gập/ngã nhẹ)","note":"Hay đi với 閉める, 閉じる, 倒れる. Tiếng đóng hoặc gập lại.","example":"彼女は本をぱたんと閉じて、立ち上がった。","example_reading":"かのじょはほんをぱたんととじて、たちあがった。","example_meaning":"Cô ấy gấp cuốn sách đánh cạch rồi đứng dậy.","examples":[{"example":"彼女は本をぱたんと閉じて、立ち上がった。","example_reading":"かのじょはほんをぱたんととじて、たちあがった。","example_meaning":"Cô ấy gấp cuốn sách đánh cạch rồi đứng dậy."},{"example":"ドアがぱたんと閉まる音で、目が覚めた。","example_reading":"ドアがぱたんとしまるおとで、めがさめた。","example_meaning":"Tôi tỉnh giấc vì tiếng cửa đóng cạch."}],"level":"b1"},
{"word":"ぼうっと","reading":"ぼうっと","meaning":"thẫn thờ, đờ đẫn","antonym":"はっきり: rõ ràng","note":"Đầu óc không tập trung. Hay đi với する, 眺める. Cũng viết ぼーっと.","example":"寝不足で、授業中ずっとぼうっとしていた。","example_reading":"ねふそくで、じゅぎょうちゅうずっとぼうっとしていた。","example_meaning":"Thiếu ngủ nên suốt giờ học tôi cứ đờ đẫn.","examples":[{"example":"寝不足で、授業中ずっとぼうっとしていた。","example_reading":"ねふそくで、じゅぎょうちゅうずっとぼうっとしていた。","example_meaning":"Thiếu ngủ nên suốt giờ học tôi cứ đờ đẫn."},{"example":"窓の外を、ぼうっと眺めていた。","example_reading":"まどのそとを、ぼうっとながめていた。","example_meaning":"Tôi thẫn thờ ngắm nhìn ra ngoài cửa sổ."}],"level":"b1"},
{"word":"うっとり","reading":"うっとり","meaning":"say sưa, mê mẩn","note":"Bị cuốn hút bởi cái đẹp. Hay đi với 見とれる, 聞き入る.","example":"彼女の歌声に、観客はうっとりと聞き入った。","example_reading":"かのじょのうたごえに、かんきゃくはうっとりとききいった。","example_meaning":"Khán giả say sưa lắng nghe giọng hát của cô ấy.","examples":[{"example":"彼女の歌声に、観客はうっとりと聞き入った。","example_reading":"かのじょのうたごえに、かんきゃくはうっとりとききいった。","example_meaning":"Khán giả say sưa lắng nghe giọng hát của cô ấy."},{"example":"夕日が沈む景色に、うっとりした。","example_reading":"ゆうひがしずむけしきに、うっとりした。","example_meaning":"Tôi mê mẩn trước cảnh mặt trời lặn."}],"level":"b1"},
{"word":"とんとん","reading":"とんとん","meaning":"cốc cốc; suôn sẻ","note":"Hay đi với 叩く, 進む. Gõ nhẹ liên tiếp; とんとん拍子 = thuận buồm xuôi gió.","example":"誰かがドアをとんとんと叩いた。","example_reading":"だれかがドアをとんとんとたたいた。","example_meaning":"Ai đó gõ cốc cốc vào cửa.","examples":[{"example":"誰かがドアをとんとんと叩いた。","example_reading":"だれかがドアをとんとんとたたいた。","example_meaning":"Ai đó gõ cốc cốc vào cửa."},{"example":"交渉はとんとん拍子に進み、その日のうちに決まった。","example_reading":"こうしょうはとんとんびょうしにすすみ、そのひのうちにきまった。","example_meaning":"Đàm phán diễn ra thuận lợi, quyết định xong ngay trong ngày."}],"level":"b1"},
{"word":"ぽかん","reading":"ぽかん","meaning":"ngơ ngác, há hốc","note":"Hay đi với 口を開ける, 見る. Sững sờ, không hiểu chuyện gì.","example":"彼は突然の話に、ぽかんとしていた。","example_reading":"かれはとつぜんのはなしに、ぽかんとしていた。","example_meaning":"Anh ấy ngơ ngác trước câu chuyện bất ngờ.","examples":[{"example":"彼は突然の話に、ぽかんとしていた。","example_reading":"かれはとつぜんのはなしに、ぽかんとしていた。","example_meaning":"Anh ấy ngơ ngác trước câu chuyện bất ngờ."},{"example":"子どもたちは口をぽかんと開けて空を見上げた。","example_reading":"こどもたちはくちをぽかんとあけてそらをみあげた。","example_meaning":"Bọn trẻ há hốc miệng ngước nhìn bầu trời."}],"level":"b1"},
{"word":"ぽっかり","reading":"ぽっかり","meaning":"trống hoác; lơ lửng","note":"Lỗ hổng lớn đột ngột hiện ra, hoặc vật nhẹ nổi lơ lửng. Hay đi với 穴が開く, 浮かぶ, 心.","example":"道路にぽっかり大きな穴が開いていた。","example_reading":"どうろにぽっかりおおきなあながひらいていた。","example_meaning":"Trên mặt đường xuất hiện một cái hố lớn trống hoác.","examples":[{"example":"道路にぽっかり大きな穴が開いていた。","example_reading":"どうろにぽっかりおおきなあながひらいていた。","example_meaning":"Trên mặt đường xuất hiện một cái hố lớn trống hoác."},{"example":"青い空に、白い雲がぽっかり浮かんでいる。","example_reading":"あおいそらに、しろいくもがぽっかりうかんでいる。","example_meaning":"Trên bầu trời xanh, một đám mây trắng lững lờ trôi."}],"level":"b1"},
{"word":"ざぶん","reading":"ざぶん","meaning":"ùm (nhảy xuống nước)","note":"Hay đi với と, 飛び込む, 打ち寄せる.","example":"少年は、ざぶんと川に飛び込んだ。","example_reading":"しょうねんは、ざぶんとかわにとびこんだ。","example_meaning":"Cậu bé nhảy ùm xuống sông.","examples":[{"example":"少年は、ざぶんと川に飛び込んだ。","example_reading":"しょうねんは、ざぶんとかわにとびこんだ。","example_meaning":"Cậu bé nhảy ùm xuống sông."},{"example":"波がざぶんと岩に打ち寄せた。","example_reading":"なみがざぶんといわにうちよせた。","example_meaning":"Sóng đánh ào vào ghềnh đá."}],"level":"b1"},
{"word":"ぼちゃん","reading":"ぼちゃん","meaning":"tõm (rơi xuống nước)","note":"Hay đi với と, 落ちる, 投げ込む. Nặng hơn ぽちゃん.","example":"誰かが、池にぼちゃんと何かを投げ込んだ。","example_reading":"だれかが、いけにぼちゃんとなにかをなげこんだ。","example_meaning":"Ai đó ném thứ gì đó xuống ao đánh tõm.","examples":[{"example":"誰かが、池にぼちゃんと何かを投げ込んだ。","example_reading":"だれかが、いけにぼちゃんとなにかをなげこんだ。","example_meaning":"Ai đó ném thứ gì đó xuống ao đánh tõm."},{"example":"手が滑って、スマホをぼちゃんと水に落としてしまった。","example_reading":"てがすべって、スマホをぼちゃんとみずにおとしてしまった。","example_meaning":"Tay trượt nên tôi làm rơi điện thoại tõm xuống nước."}],"level":"b1"},
{"word":"ぽとん","reading":"ぽとん","meaning":"tõm nhẹ; rơi bộp","note":"Hay đi với と, 落ちる, 入る. Vật nhỏ rơi nhẹ.","example":"スープに、ぽとんとバターを落とした。","example_reading":"スープに、ぽとんとバターをおとした。","example_meaning":"Tôi thả một miếng bơ xuống súp.","examples":[{"example":"スープに、ぽとんとバターを落とした。","example_reading":"スープに、ぽとんとバターをおとした。","example_meaning":"Tôi thả một miếng bơ xuống súp."},{"example":"手紙が、ぽとんと郵便受けに入る音がした。","example_reading":"てがみが、ぽとんとゆうびんうけにはいるおとがした。","example_meaning":"Nghe tiếng lá thư rơi bộp vào hộp thư."}],"level":"b1"},
{"word":"だくだく","reading":"だくだく","meaning":"chảy ròng ròng","note":"Hay đi với 流れる, 汗, 血.","example":"暑い中を歩いて、汗がだくだく流れた。","example_reading":"あついなかをあるいて、あせがだくだくながれた。","example_meaning":"Đi bộ giữa trời nóng, mồ hôi chảy ròng ròng.","examples":[{"example":"暑い中を歩いて、汗がだくだく流れた。","example_reading":"あついなかをあるいて、あせがだくだくながれた。","example_meaning":"Đi bộ giữa trời nóng, mồ hôi chảy ròng ròng."},{"example":"傷口から、血がだくだくと出てきた。","example_reading":"きずぐちから、ちがだくだくとでてきた。","example_meaning":"Máu chảy ròng ròng từ vết thương."}],"level":"b1"},
{"word":"たらり","reading":"たらり","meaning":"nhỏ giọt, chảy chậm","note":"Hay đi với と, 流れる, 垂れる. Chất lỏng đặc chảy chậm.","example":"額から、汗がたらりと流れた。","example_reading":"ひたいから、あせがたらりとながれた。","example_meaning":"Mồ hôi chảy ròng từ trán.","examples":[{"example":"額から、汗がたらりと流れた。","example_reading":"ひたいから、あせがたらりとながれた。","example_meaning":"Mồ hôi chảy ròng từ trán."},{"example":"蜂蜜をたらりとパンにかけて食べた。","example_reading":"はちみつをたらりとパンにかけてたべた。","example_meaning":"Tôi rưới mật ong lên bánh mì rồi ăn."}],"level":"b1"},
{"word":"がぶり","reading":"がぶり","meaning":"ngoạm mạnh","note":"Hay đi với とかむ, かじる. Ngoạm một miếng lớn.","example":"犬が、骨にがぶりとかみついた。","example_reading":"いぬが、ほねにがぶりとかみついた。","example_meaning":"Con chó ngoạm mạnh khúc xương.","examples":[{"example":"犬が、骨にがぶりとかみついた。","example_reading":"いぬが、ほねにがぶりとかみついた。","example_meaning":"Con chó ngoạm mạnh khúc xương."},{"example":"彼はりんごをがぶりとかじった。","example_reading":"かれはりんごをがぶりとかじった。","example_meaning":"Anh ấy cắn phập quả táo."}],"level":"b1"},
{"word":"ぱくっと","reading":"ぱくっと","meaning":"ngoạm một cái, ăn gọn một miếng","note":"Hay đi với 食べる, くわえる. Cắn hoặc ăn gọn trong một miếng.","example":"子どもはお菓子をぱくっと口に入れた。","example_reading":"こどもはおかしをぱくっとくちにいれた。","example_meaning":"Đứa bé ngoạm gọn chiếc bánh kẹo vào miệng.","examples":[{"example":"子どもはお菓子をぱくっと口に入れた。","example_reading":"こどもはおかしをぱくっとくちにいれた。","example_meaning":"Đứa bé ngoạm gọn chiếc bánh kẹo vào miệng."},{"example":"犬は投げたボールをぱくっとくわえた。","example_reading":"いぬはなげたボールをぱくっとくわえた。","example_meaning":"Con chó ngoạm gọn quả bóng được ném."}],"level":"b1"},
{"word":"はらはら","reading":"はらはら","meaning":"hồi hộp lo lắng, thót tim","antonym":"ほっと: nhẹ nhõm","note":"Từ tượng hình. Lo cho điều có thể xảy ra, hay đi với する.","example":"綱渡りを見ていて、はらはらしました。","example_reading":"つなわたりをみていて、はらはらしました。","example_meaning":"Xem người đi trên dây mà tôi thót tim.","examples":[{"example":"綱渡りを見ていて、はらはらしました。","example_reading":"つなわたりをみていて、はらはらしました。","example_meaning":"Xem người đi trên dây mà tôi thót tim."},{"example":"子どもが高い木に登って、はらはらした。","example_reading":"こどもがたかいきにのぼって、はらはらした。","example_meaning":"Thấy đứa bé leo lên cây cao, tôi thót tim."}],"level":"b1"},
{"word":"くよくよ","reading":"くよくよ","meaning":"buồn phiền, nghĩ ngợi mãi","antonym":"さっぱり: dứt khoát, thoáng / さばさば: sảng khoái","note":"Hay đi với 悩む, する. Lo lắng, tiếc nuối chuyện đã qua.","example":"終わったことをくよくよ考えても仕方がない。","example_reading":"おわったことをくよくよかんがえてもしかたがない。","example_meaning":"Có nghĩ ngợi mãi chuyện đã qua thì cũng chẳng ích gì.","examples":[{"example":"終わったことをくよくよ考えても仕方がない。","example_reading":"おわったことをくよくよかんがえてもしかたがない。","example_meaning":"Có nghĩ ngợi mãi chuyện đã qua thì cũng chẳng ích gì."},{"example":"失敗してもくよくよしないで、次に頑張ろう。","example_reading":"しっぱいしてもくよくよしないで、つぎにがんばろう。","example_meaning":"Dù thất bại cũng đừng buồn phiền, lần sau cố gắng nhé."}],"level":"b1"},
{"word":"ふにゃふにゃ","reading":"ふにゃふにゃ","meaning":"mềm oặt, nhũn","antonym":"かちかち: cứng ngắc / ぴんと: căng thẳng / かりかり: giòn rụm","note":"Hay đi với する, なる. Vật hoặc người mềm yếu, không có sức.","example":"湿気で、せっかくのクッキーがふにゃふにゃになってしまった。","example_reading":"しっけで、せっかくのクッキーがふにゃふにゃになってしまった。","example_meaning":"Vì ẩm nên bánh quy khó khăn lắm mới làm xong đã nhũn mềm.","examples":[{"example":"湿気で、せっかくのクッキーがふにゃふにゃになってしまった。","example_reading":"しっけで、せっかくのクッキーがふにゃふにゃになってしまった。","example_meaning":"Vì ẩm nên bánh quy khó khăn lắm mới làm xong đã nhũn mềm."},{"example":"熱が高くて、体がふにゃふにゃで立てない。","example_reading":"ねつがたかくて、からだがふにゃふにゃでたてない。","example_meaning":"Sốt cao nên người mềm nhũn, không đứng nổi."}],"level":"b1"},
{"word":"ちらほら","reading":"ちらほら","meaning":"lác đác, thưa thớt","antonym":"びっしり: dày đặc / ぎっしり: chật cứng / ずらり: hàng dài","note":"Hay đi với 見える, 咲く, 降る. Chỉ có vài cái rải rác.","example":"公園の桜がちらほら咲き始めた。","example_reading":"こうえんのさくらがちらほらさきはじめた。","example_meaning":"Hoa anh đào trong công viên bắt đầu nở lác đác.","examples":[{"example":"公園の桜がちらほら咲き始めた。","example_reading":"こうえんのさくらがちらほらさきはじめた。","example_meaning":"Hoa anh đào trong công viên bắt đầu nở lác đác."},{"example":"平日の昼間は、店内にお客さんがちらほらいるだけだった。","example_reading":"へいじつのひるまは、てんないにおきゃくさんがちらほらいるだけだった。","example_meaning":"Ban ngày ngày thường, trong tiệm chỉ lác đác vài khách."}],"level":"b1"},
{"word":"どたばた","reading":"どたばた","meaning":"ầm ĩ, rần rần (chạy nhảy); cuống cuồng","antonym":"そっと: nhẹ nhàng / ゆったり: thong thả","note":"Hay đi với する, 走り回る. Tiếng chân chạy loạn xạ; cũng chỉ sự náo loạn, bận rộn.","example":"上の階で子どもたちがどたばた走り回っている。","example_reading":"うえのかいでこどもたちがどたばたはしりまわっている。","example_meaning":"Ở tầng trên bọn trẻ đang chạy ầm ầm.","examples":[{"example":"上の階で子どもたちがどたばた走り回っている。","example_reading":"うえのかいでこどもたちがどたばたはしりまわっている。","example_meaning":"Ở tầng trên bọn trẻ đang chạy ầm ầm."},{"example":"出発の朝はどたばたして、忘れ物をしてしまった。","example_reading":"しゅっぱつのあさはどたばたして、わすれものをしてしまった。","example_meaning":"Sáng khởi hành rối rít cuống cuồng nên tôi để quên đồ."}],"level":"b1"},
{"word":"ぱっちり","reading":"ぱっちり","meaning":"(Mắt) to tròn; tỉnh hẳn","antonym":"うつらうつら: gà gật","note":"Hay đi với 目, 開く, 覚める.","example":"彼女は目がぱっちりしていて、人形のようだ。","example_reading":"かのじょはめがぱっちりしていて、にんぎょうのようだ。","example_meaning":"Cô ấy mắt to tròn như búp bê.","examples":[{"example":"彼女は目がぱっちりしていて、人形のようだ。","example_reading":"かのじょはめがぱっちりしていて、にんぎょうのようだ。","example_meaning":"Cô ấy mắt to tròn như búp bê."},{"example":"コーヒーを飲んだら、目がぱっちり覚めた。","example_reading":"コーヒーをのんだら、めがぱっちりさめた。","example_meaning":"Uống cà phê xong, mắt tôi tỉnh hẳn."}],"level":"b1"},
{"word":"ぐるり","reading":"ぐるり","meaning":"một vòng, xoay trọn","note":"Hay đi với と, 見渡す, 一周する. Cũng nói ぐるりと.","example":"彼は部屋の中をぐるりと見渡した。","example_reading":"かれはへやのなかをぐるりとみわたした。","example_meaning":"Anh ấy đảo mắt nhìn quanh căn phòng.","examples":[{"example":"彼は部屋の中をぐるりと見渡した。","example_reading":"かれはへやのなかをぐるりとみわたした。","example_meaning":"Anh ấy đảo mắt nhìn quanh căn phòng."},{"example":"池のまわりを、ぐるりと一周した。","example_reading":"いけのまわりを、ぐるりといっしゅうした。","example_meaning":"Tôi đi một vòng quanh cái hồ."}],"level":"b1"},
{"word":"よれよれ","reading":"よれよれ","meaning":"nhàu nhĩ, xộc xệch","antonym":"ぴしっと: phẳng phiu / ぱりっと: phẳng phiu","note":"Hay đi với 服, シャツ, スーツ. Quần áo mòn nhăn, mất dáng.","example":"彼はよれよれのシャツを着て、会社に来た。","example_reading":"かれはよれよれのシャツをきて、かいしゃにきた。","example_meaning":"Anh ấy mặc chiếc áo sơ mi nhàu nhĩ đến công ty.","examples":[{"example":"彼はよれよれのシャツを着て、会社に来た。","example_reading":"かれはよれよれのシャツをきて、かいしゃにきた。","example_meaning":"Anh ấy mặc chiếc áo sơ mi nhàu nhĩ đến công ty."},{"example":"洗濯を繰り返したせいで、タオルがよれよれになった。","example_reading":"せんたくをくりかえしたせいで、タオルがよれよれになった。","example_meaning":"Do giặt nhiều lần nên chiếc khăn đã xơ xác."}],"level":"b1"},
{"word":"ちゃっかり","reading":"ちゃっかり","meaning":"khôn khéo, láu cá (có lợi cho mình)","note":"Hay đi với する. Biết tranh thủ lợi cho bản thân.","example":"彼はちゃっかり一番いい席を確保していた。","example_reading":"かれはちゃっかりいちばんいいせきをかくほしていた。","example_meaning":"Anh ta đã khôn khéo giữ cho mình chỗ ngồi tốt nhất.","examples":[{"example":"彼はちゃっかり一番いい席を確保していた。","example_reading":"かれはちゃっかりいちばんいいせきをかくほしていた。","example_meaning":"Anh ta đã khôn khéo giữ cho mình chỗ ngồi tốt nhất."},{"example":"妹はちゃっかりしていて、いつも得をしている。","example_reading":"いもうとはちゃっかりしていて、いつもとくをしている。","example_meaning":"Em gái tôi láu lỉnh nên lúc nào cũng được lợi."}],"level":"b1"},
{"word":"べちゃべちゃ","reading":"べちゃべちゃ","meaning":"nhão nhoẹt, ướt nhèm","antonym":"さらさら: khô ráo","note":"Hay đi với 濡れる, 話す, 食べる. Ướt nhão; cũng nghĩa nói lèm bèm.","example":"雨で、道がべちゃべちゃにぬかるんでいる。","example_reading":"あめで、みちがべちゃべちゃにぬかるんでいる。","example_meaning":"Mưa khiến đường lầy lội nhão nhoẹt.","examples":[{"example":"雨で、道がべちゃべちゃにぬかるんでいる。","example_reading":"あめで、みちがべちゃべちゃにぬかるんでいる。","example_meaning":"Mưa khiến đường lầy lội nhão nhoẹt."},{"example":"炊きすぎて、ご飯がべちゃべちゃになってしまった。","example_reading":"たきすぎて、ごはんがべちゃべちゃになってしまった。","example_meaning":"Nấu quá tay nên cơm bị nhão nhoẹt."}],"level":"b1"},
{"word":"こりこり","reading":"こりこり","meaning":"giòn sần sật; cứng (vai)","note":"Hay đi với 食感, 肩. Độ giòn dai của sụn, hoặc cơ cứng.","example":"このイカは、こりこりとした歯ごたえがいい。","example_reading":"このイカは、こりこりとしたはごたえがいい。","example_meaning":"Mực này giòn sần sật rất ngon.","examples":[{"example":"このイカは、こりこりとした歯ごたえがいい。","example_reading":"このイカは、こりこりとしたはごたえがいい。","example_meaning":"Mực này giòn sần sật rất ngon."},{"example":"一日中パソコンを使って、肩がこりこりに固まった。","example_reading":"いちにちじゅうパソコンをつかって、かたがこりこりにかたまった。","example_meaning":"Dùng máy tính cả ngày nên vai cứng đờ."}],"level":"b1"},
{"word":"じんじん","reading":"じんじん","meaning":"tê rần, nhức nhối","note":"Hay đi với する, 痛む, 手足. Cảm giác tê buốt kéo dài.","example":"寒い外にいたせいで、指先がじんじんする。","example_reading":"さむいそとにいたせいで、ゆびさきがじんじんする。","example_meaning":"Vì ở ngoài trời lạnh nên đầu ngón tay tôi tê rần.","examples":[{"example":"寒い外にいたせいで、指先がじんじんする。","example_reading":"さむいそとにいたせいで、ゆびさきがじんじんする。","example_meaning":"Vì ở ngoài trời lạnh nên đầu ngón tay tôi tê rần."},{"example":"転んでぶつけた膝がじんじん痛んだ。","example_reading":"ころんでぶつけたひざがじんじんいたんだ。","example_meaning":"Đầu gối bị va khi ngã đau nhức nhối."}],"level":"b1"},
{"word":"びくびく","reading":"びくびく","meaning":"rón rén, hoảng sợ","note":"Sợ hãi lo lắng không yên. Hay đi với する.","antonym":"堂々と（どうどうと）: đường hoàng","antonym_hanviet":"đường đường","example":"叱られるのではないかと、びくびくしていた。","example_reading":"しかられるのではないかと、びくびくしていた。","example_meaning":"Tôi cứ thấp thỏm sợ bị mắng.","examples":[{"example":"叱られるのではないかと、びくびくしていた。","example_reading":"しかられるのではないかと、びくびくしていた。","example_meaning":"Tôi cứ thấp thỏm sợ bị mắng."},{"example":"彼は上司の顔色を見ながら、びくびく働いている。","example_reading":"かれはじょうしのかおいろをみながら、びくびくはたらいている。","example_meaning":"Anh ấy vừa nhìn sắc mặt sếp vừa làm việc thấp thỏm."}],"level":"b1"},
{"word":"もじもじ","reading":"もじもじ","meaning":"ngượng ngùng, ngập ngừng","antonym":"はきはき: rành rọt","note":"Hay đi với する. Rụt rè, bối rối, không dám nói hoặc làm.","example":"彼は好きな人の前でもじもじしていた。","example_reading":"かれはすきなひとのまえでもじもじしていた。","example_meaning":"Anh ấy ngượng ngùng trước người mình thích.","examples":[{"example":"彼は好きな人の前でもじもじしていた。","example_reading":"かれはすきなひとのまえでもじもじしていた。","example_meaning":"Anh ấy ngượng ngùng trước người mình thích."},{"example":"トイレに行きたいのか、子どもがもじもじしている。","example_reading":"トイレにいきたいのか、こどもがもじもじしている。","example_meaning":"Có lẽ muốn đi vệ sinh nên đứa bé cứ ngọ nguậy."}],"level":"b1"},
{"word":"ばさばさ","reading":"ばさばさ","meaning":"khô xơ (tóc); vỗ phành phạch","antonym":"しっとり: ẩm mượt / つやつや: bóng mượt","note":"Hay đi với 髪, 羽. Tóc hư tổn khô xơ; cũng là tiếng vỗ cánh.","example":"髪が傷んで、ばさばさになってしまった。","example_reading":"かみがいたんで、ばさばさになってしまった。","example_meaning":"Tóc bị hư tổn nên khô xơ.","examples":[{"example":"髪が傷んで、ばさばさになってしまった。","example_reading":"かみがいたんで、ばさばさになってしまった。","example_meaning":"Tóc bị hư tổn nên khô xơ."},{"example":"鳥がばさばさと羽を鳴らして飛び立った。","example_reading":"とりがばさばさとはねをならしてとびたった。","example_meaning":"Con chim vỗ cánh phành phạch rồi bay vút lên."}],"level":"b1"},
{"word":"からっと","reading":"からっと","meaning":"khô ráo, giòn tan; thẳng tính","antonym":"じめじめ: ẩm ướt / じっとり: ẩm nhớp","note":"Hay đi với 揚がる, 晴れる, した性格. Chỉ trạng thái khô, ráo, giòn.","example":"天ぷらがからっと揚がって、とてもおいしそうだ。","example_reading":"てんぷらがからっとあがって、とてもおいしそうだ。","example_meaning":"Tempura chiên giòn tan trông rất ngon.","examples":[{"example":"天ぷらがからっと揚がって、とてもおいしそうだ。","example_reading":"てんぷらがからっとあがって、とてもおいしそうだ。","example_meaning":"Tempura chiên giòn tan trông rất ngon."},{"example":"今日は朝からからっと晴れて、洗濯日和だ。","example_reading":"きょうはあさからからっとはれて、せんたくびよりだ。","example_meaning":"Hôm nay trời nắng ráo từ sáng, đúng ngày giặt đồ."}],"level":"b1"},
{"word":"おろおろ","reading":"おろおろ","meaning":"luống cuống, bối rối","antonym":"堂々と（どうどうと）: đường hoàng","antonym_hanviet":"đường đường","note":"Hay đi với する. Mất bình tĩnh khi gặp việc bất ngờ.","example":"突然の事故に、彼女はおろおろするばかりだった。","example_reading":"とつぜんのじこに、かのじょはおろおろするばかりだった。","example_meaning":"Trước tai nạn bất ngờ, cô ấy chỉ biết luống cuống.","examples":[{"example":"突然の事故に、彼女はおろおろするばかりだった。","example_reading":"とつぜんのじこに、かのじょはおろおろするばかりだった。","example_meaning":"Trước tai nạn bất ngờ, cô ấy chỉ biết luống cuống."},{"example":"財布をなくして、おろおろと探し回った。","example_reading":"さいふをなくして、おろおろとさがしまわった。","example_meaning":"Mất ví, tôi cuống cuồng tìm khắp nơi."}],"level":"b1"},
{"word":"ひょろっと","reading":"ひょろっと","meaning":"gầy cao, mảnh khảnh","antonym":"がっしり: vạm vỡ","note":"Hay đi với した, 背が高い. Giống ひょろひょろ, nhẹ hơn.","example":"ひょろっと背の高い青年が、入口に立っていた。","example_reading":"ひょろっとせのたかいせいねんが、いりぐちにたっていた。","example_meaning":"Một chàng trai cao gầy đứng ở lối vào.","examples":[{"example":"ひょろっと背の高い青年が、入口に立っていた。","example_reading":"ひょろっとせのたかいせいねんが、いりぐちにたっていた。","example_meaning":"Một chàng trai cao gầy đứng ở lối vào."},{"example":"彼はひょろっとしているが、意外に力持ちだ。","example_reading":"かれはひょろっとしているが、いがいにちからもちだ。","example_meaning":"Anh ấy tuy gầy cao nhưng lại khỏe bất ngờ."}],"level":"b1"},
{"word":"ぽいと","reading":"ぽいと","meaning":"ném nhẹ, vứt tùy tiện","note":"Hay đi với 捨てる, 投げる. Làm tùy tiện, không để ý.","example":"彼はごみを、ぽいとかごに投げ入れた。","example_reading":"かれはごみを、ぽいとかごになげいれた。","example_meaning":"Anh ấy tiện tay ném rác vào giỏ.","examples":[{"example":"彼はごみを、ぽいとかごに投げ入れた。","example_reading":"かれはごみを、ぽいとかごになげいれた。","example_meaning":"Anh ấy tiện tay ném rác vào giỏ."},{"example":"そんな大事な物を、ぽいと捨てないでください。","example_reading":"そんなだいじなものを、ぽいとすてないでください。","example_meaning":"Đừng vứt bừa món đồ quan trọng như thế."}],"level":"b1"},
{"word":"ふんわか","reading":"ふんわか","meaning":"phồng nhẹ, ấm áp","note":"Hay đi với した, 温かい. Mềm nhẹ gây cảm giác dễ chịu.","example":"ふんわかした毛布にくるまって、眠った。","example_reading":"ふんわかしたもうふにくるまって、ねむった。","example_meaning":"Tôi quấn chăn mềm xốp rồi ngủ.","examples":[{"example":"ふんわかした毛布にくるまって、眠った。","example_reading":"ふんわかしたもうふにくるまって、ねむった。","example_meaning":"Tôi quấn chăn mềm xốp rồi ngủ."},{"example":"彼女の笑顔を見ていると、ふんわか温かい気持ちになる。","example_reading":"かのじょのえがおをみていると、ふんわかあたたかいきもちになる。","example_meaning":"Nhìn nụ cười của cô ấy, lòng tôi ấm áp nhẹ nhàng."}],"level":"b1"},
{"word":"ぞわぞわ","reading":"ぞわぞわ","meaning":"nổi da gà, rờn rợn","note":"Hay đi với する. Cảm giác rùng mình lan khắp da.","example":"怖い話を聞いて、背中がぞわぞわした。","example_reading":"こわいはなしをきいて、せなかがぞわぞわした。","example_meaning":"Nghe chuyện đáng sợ, lưng tôi nổi da gà.","examples":[{"example":"怖い話を聞いて、背中がぞわぞわした。","example_reading":"こわいはなしをきいて、せなかがぞわぞわした。","example_meaning":"Nghe chuyện đáng sợ, lưng tôi nổi da gà."},{"example":"虫が腕を這う感覚に、全身がぞわぞわする。","example_reading":"むしがうでをはうかんかくに、ぜんしんがぞわぞわする。","example_meaning":"Cảm giác con sâu bò trên tay làm toàn thân tôi rờn rợn."}],"level":"b1"},
{"word":"おどおど","reading":"おどおど","meaning":"lúng túng, e dè","antonym":"堂々と（どうどうと）: đường hoàng","antonym_hanviet":"đường đường","note":"Rụt rè, bất an. Hay đi với する, 話す, 答える.","example":"彼は初対面の人の前で、おどおどして何も言えなかった。","example_reading":"かれははつたいめんのひとのまえで、おどおどしてなにもいえなかった。","example_meaning":"Trước người mới gặp, anh ấy lúng túng không nói được gì.","examples":[{"example":"彼は初対面の人の前で、おどおどして何も言えなかった。","example_reading":"かれははつたいめんのひとのまえで、おどおどしてなにもいえなかった。","example_meaning":"Trước người mới gặp, anh ấy lúng túng không nói được gì."},{"example":"面接官に聞かれて、おどおどと答えた。","example_reading":"めんせつかんにきかれて、おどおどとこたえた。","example_meaning":"Bị người phỏng vấn hỏi, tôi trả lời một cách e dè."}],"level":"b1"},
{"word":"ひやひや","reading":"ひやひや","meaning":"thót tim lo lắng","antonym":"ほっと: nhẹ nhõm","note":"Lo lắng khi sắp có chuyện xấu. Hay đi với する.","example":"子どもが階段で遊んでいて、ひやひやした。","example_reading":"こどもがかいだんであそんでいて、ひやひやした。","example_meaning":"Con chơi trên cầu thang làm tôi thót tim.","examples":[{"example":"子どもが階段で遊んでいて、ひやひやした。","example_reading":"こどもがかいだんであそんでいて、ひやひやした。","example_meaning":"Con chơi trên cầu thang làm tôi thót tim."},{"example":"試験の時間が迫り、ひやひやしながら問題を解いた。","example_reading":"しけんのじかんがせまり、ひやひやしながらもんだいをといた。","example_meaning":"Sắp hết giờ thi, tôi vừa lo thót tim vừa làm bài."}],"level":"b1"},
{"word":"じろじろ","reading":"じろじろ","meaning":"nhìn chằm chằm, nhìn soi mói","antonym":"ちらちら: liếc nhìn","note":"Từ tượng hình. Nhìn lộ liễu, thiếu lịch sự.","example":"人にじろじろ見られて、恥ずかしかった。","example_reading":"ひとにじろじろみられて、はずかしかった。","example_meaning":"Bị người ta nhìn chằm chằm nên tôi ngại.","examples":[{"example":"人にじろじろ見られて、恥ずかしかった。","example_reading":"ひとにじろじろみられて、はずかしかった。","example_meaning":"Bị người ta nhìn chằm chằm nên tôi ngại."},{"example":"彼は私の服をじろじろ見ていた。","example_reading":"かれはわたしのふくをじろじろみていた。","example_meaning":"Anh ấy nhìn chằm chằm vào quần áo của tôi."}],"level":"b1"},
{"word":"ほくほく","reading":"ほくほく","meaning":"bở nóng, thơm bùi (khoai); hớn hở","note":"Hay đi với さつまいも, じゃがいも, 栗. ほくほく顔 = vẻ mặt hài lòng.","example":"焼きたてのさつまいもはほくほくしていて甘い。","example_reading":"やきたてのさつまいもはほくほくしていてあまい。","example_meaning":"Khoai lang mới nướng bở bùi và ngọt.","examples":[{"example":"焼きたてのさつまいもはほくほくしていて甘い。","example_reading":"やきたてのさつまいもはほくほくしていてあまい。","example_meaning":"Khoai lang mới nướng bở bùi và ngọt."},{"example":"ボーナスが出て、父はほくほく顔で帰ってきた。","example_reading":"ボーナスがでて、ちちはほくほくがおでかえってきた。","example_meaning":"Có thưởng nên bố tôi về nhà với vẻ mặt hớn hở."}],"level":"b1"},
{"word":"ごろり","reading":"ごろり","meaning":"nằm vật ra, lăn ra","note":"Hay đi với 横になる, 寝転ぶ. Cũng nói ごろっと. Nằm xuống một cách thoải mái.","example":"昼ご飯を食べたあと、ソファにごろりと横になった。","example_reading":"ひるごはんをたべたあと、ソファにごろりとよこになった。","example_meaning":"Ăn trưa xong, tôi nằm vật ra sofa.","examples":[{"example":"昼ご飯を食べたあと、ソファにごろりと横になった。","example_reading":"ひるごはんをたべたあと、ソファにごろりとよこになった。","example_meaning":"Ăn trưa xong, tôi nằm vật ra sofa."},{"example":"疲れた父は帰ってくるなり、畳にごろりと寝転んだ。","example_reading":"つかれたちちはかえってくるなり、たたみにごろりとねころんだ。","example_meaning":"Bố mệt, vừa về đến nhà đã lăn ra chiếu tatami nằm."}],"level":"b1"},
{"word":"ぺこり","reading":"ぺこり","meaning":"cúi đầu một cái","note":"Hay đi với と, 頭を下げる, お辞儀. Cúi chào nhẹ, thường mang vẻ dễ thương.","example":"男の子はぺこりと頭を下げて、教室を出ていった。","example_reading":"おとこのこはぺこりとあたまをさげて、きょうしつをでていった。","example_meaning":"Cậu bé cúi đầu chào một cái rồi ra khỏi lớp.","examples":[{"example":"男の子はぺこりと頭を下げて、教室を出ていった。","example_reading":"おとこのこはぺこりとあたまをさげて、きょうしつをでていった。","example_meaning":"Cậu bé cúi đầu chào một cái rồi ra khỏi lớp."},{"example":"店員さんはぺこりとお辞儀をして、お釣りを渡した。","example_reading":"てんいんさんはぺこりとおじぎをして、おつりをわたした。","example_meaning":"Nhân viên cúi chào một cái rồi đưa tiền thối."}],"level":"b1"},
{"word":"ぴくぴく","reading":"ぴくぴく","meaning":"giật giật nhẹ","note":"Hay đi với 動く, まぶた, 耳. Cử động nhỏ lặp lại.","example":"眠っている猫の耳が、ぴくぴくと動いた。","example_reading":"ねむっているねこのみみが、ぴくぴくとうごいた。","example_meaning":"Tai con mèo đang ngủ giật giật.","examples":[{"example":"眠っている猫の耳が、ぴくぴくと動いた。","example_reading":"ねむっているねこのみみが、ぴくぴくとうごいた。","example_meaning":"Tai con mèo đang ngủ giật giật."},{"example":"釣り竿の先がぴくぴく動いて、魚がかかったと分かった。","example_reading":"つりざおのさきがぴくぴくうごいて、さかながかかったとわかった。","example_meaning":"Đầu cần câu giật giật, tôi biết cá đã cắn câu."}],"level":"b1"},
{"word":"ぷっくり","reading":"ぷっくり","meaning":"phồng lên, phúng phính","antonym":"ぺしゃんこ: dẹp lép","note":"Hay đi với 膨らむ, 唇, 腫れる.","example":"唇がぷっくりしているので、リップがよく似合う。","example_reading":"くちびるがぷっくりしているので、リップがよくにあう。","example_meaning":"Môi đầy đặn nên son rất hợp.","examples":[{"example":"唇がぷっくりしているので、リップがよく似合う。","example_reading":"くちびるがぷっくりしているので、リップがよくにあう。","example_meaning":"Môi đầy đặn nên son rất hợp."},{"example":"虫に刺されて、腕がぷっくり腫れてしまった。","example_reading":"むしにさされて、うでがぷっくりはれてしまった。","example_meaning":"Bị côn trùng đốt, tay tôi sưng phồng lên."}],"level":"b1"},
{"word":"ほんわか","reading":"ほんわか","meaning":"ấm áp, nhẹ nhàng (không khí)","note":"Hay đi với した雰囲気, 気持ち. Cảm giác ấm áp dễ chịu.","example":"彼女のそばにいると、ほんわかした気持ちになる。","example_reading":"かのじょのそばにいると、ほんわかしたきもちになる。","example_meaning":"Ở cạnh cô ấy, tôi thấy lòng ấm áp nhẹ nhàng.","examples":[{"example":"彼女のそばにいると、ほんわかした気持ちになる。","example_reading":"かのじょのそばにいると、ほんわかしたきもちになる。","example_meaning":"Ở cạnh cô ấy, tôi thấy lòng ấm áp nhẹ nhàng."},{"example":"あのお店は、ほんわかした雰囲気で居心地がいい。","example_reading":"あのおみせは、ほんわかしたふんいきでいごこちがいい。","example_meaning":"Quán đó có không khí ấm áp nên ngồi rất dễ chịu."}],"level":"b1"},
{"word":"じっとり","reading":"じっとり","meaning":"ẩm ướt, nhớp nháp","antonym":"からっと: khô ráo / さらさら: khô ráo","note":"Hay đi với 汗ばむ, 湿気, 重い. Ẩm đến mức khó chịu.","example":"蒸し暑くて、背中がじっとり汗ばんできた。","example_reading":"むしあつくて、せなかがじっとりあせばんできた。","example_meaning":"Oi bức, lưng tôi bắt đầu ướt đẫm mồ hôi.","examples":[{"example":"蒸し暑くて、背中がじっとり汗ばんできた。","example_reading":"むしあつくて、せなかがじっとりあせばんできた。","example_meaning":"Oi bức, lưng tôi bắt đầu ướt đẫm mồ hôi."},{"example":"梅雨の部屋は、空気がじっとりと重い。","example_reading":"つゆのへやは、くうきがじっとりとおもい。","example_meaning":"Căn phòng mùa mưa có không khí ẩm nặng."}],"level":"b1"},
{"word":"ごつん","reading":"ごつん","meaning":"cộp (va đập)","note":"Hay đi với とぶつける, 当たる. Tiếng va mạnh vào vật cứng.","example":"低い天井に、頭をごつんとぶつけた。","example_reading":"ひくいてんじょうに、あたまをごつんとぶつけた。","example_meaning":"Tôi va đầu vào trần thấp đánh cộp.","examples":[{"example":"低い天井に、頭をごつんとぶつけた。","example_reading":"ひくいてんじょうに、あたまをごつんとぶつけた。","example_meaning":"Tôi va đầu vào trần thấp đánh cộp."},{"example":"二人の頭が、ごつんと音を立ててぶつかった。","example_reading":"ふたりのあたまが、ごつんとおとをたててぶつかった。","example_meaning":"Đầu hai người va vào nhau kêu cộp."}],"level":"b1"},
{"word":"ちらちら","reading":"ちらちら","meaning":"liếc nhìn; lất phất","antonym":"じろじろ: nhìn chằm chằm / まじまじ: chằm chằm","note":"Liếc nhìn liên tục, hoặc tuyết/ánh sáng lất phất. Hay đi với 見る, 雪が降る.","example":"彼は授業中、ちらちら時計を見ていた。","example_reading":"かれはじゅぎょうちゅう、ちらちらとけいをみていた。","example_meaning":"Trong giờ học, cậu ấy cứ liếc nhìn đồng hồ.","examples":[{"example":"彼は授業中、ちらちら時計を見ていた。","example_reading":"かれはじゅぎょうちゅう、ちらちらとけいをみていた。","example_meaning":"Trong giờ học, cậu ấy cứ liếc nhìn đồng hồ."},{"example":"窓の外では、雪がちらちらと降り始めた。","example_reading":"まどのそとでは、ゆきがちらちらとふりはじめた。","example_meaning":"Ngoài cửa sổ, tuyết bắt đầu rơi lất phất."}],"level":"b1"},
{"word":"うねうね","reading":"うねうね","meaning":"uốn lượn, gập ghềnh dài","note":"Hay đi với 続く, 曲がる. Đường, sóng, rắn kéo dài uốn lượn, lớn hơn くねくね.","example":"田んぼの間を、細い道がうねうねと続いている。","example_reading":"たんぼのあいだを、ほそいみちがうねうねとつづいている。","example_meaning":"Giữa các thửa ruộng, con đường nhỏ uốn lượn kéo dài.","examples":[{"example":"田んぼの間を、細い道がうねうねと続いている。","example_reading":"たんぼのあいだを、ほそいみちがうねうねとつづいている。","example_meaning":"Giữa các thửa ruộng, con đường nhỏ uốn lượn kéo dài."},{"example":"海は風で、うねうねと大きく波打っていた。","example_reading":"うみはかぜで、うねうねとおおきくなみうっていた。","example_meaning":"Biển bị gió thổi, sóng nhấp nhô lớn."}],"level":"b1"},
{"word":"へなへな","reading":"へなへな","meaning":"rũ xuống, nhũn người","antonym":"しゃきっと: tỉnh táo / ぴんと: căng thẳng","note":"Hay đi với 座り込む, 力が抜ける. Mất sức đột ngột.","example":"合格を知って、安心のあまりへなへなと座り込んだ。","example_reading":"ごうかくをしって、あんしんのあまりへなへなとすわりこんだ。","example_meaning":"Biết tin đỗ, tôi nhẹ nhõm đến mức khuỵu xuống ngồi.","examples":[{"example":"合格を知って、安心のあまりへなへなと座り込んだ。","example_reading":"ごうかくをしって、あんしんのあまりへなへなとすわりこんだ。","example_meaning":"Biết tin đỗ, tôi nhẹ nhõm đến mức khuỵu xuống ngồi."},{"example":"暑さで、花がへなへなとしおれてしまった。","example_reading":"あつさで、はながへなへなとしおれてしまった。","example_meaning":"Vì nóng nên hoa héo rũ."}],"level":"b1"},
{"word":"ぬくぬく","reading":"ぬくぬく","meaning":"ấm áp thoải mái","antonym":"ひんやり: mát lạnh","note":"Hay đi với 暮らす, 育つ, 布団. Cũng chỉ sống sung sướng không lo (ぬくぬくと育つ).","example":"寒い朝は、布団の中でぬくぬくしていたい。","example_reading":"さむいあさは、ふとんのなかでぬくぬくしていたい。","example_meaning":"Sáng lạnh, tôi chỉ muốn nằm ấm trong chăn.","examples":[{"example":"寒い朝は、布団の中でぬくぬくしていたい。","example_reading":"さむいあさは、ふとんのなかでぬくぬくしていたい。","example_meaning":"Sáng lạnh, tôi chỉ muốn nằm ấm trong chăn."},{"example":"彼は親の庇護の下で、ぬくぬくと育った。","example_reading":"かれはおやのひごのもとで、ぬくぬくとそだった。","example_meaning":"Anh ấy lớn lên êm ấm dưới sự che chở của cha mẹ."}],"level":"b1"},
{"word":"にやり","reading":"にやり","meaning":"cười nhếch, cười đầy ẩn ý","note":"Hay đi với と, 笑う. Cười mỉm có ý thầm, tự mãn.","example":"彼はにやりと笑って、「うまくいったぞ」と言った。","example_reading":"かれはにやりとわらって、「うまくいったぞ」といった。","example_meaning":"Anh ta cười nhếch mép và nói \"Thành công rồi\".","examples":[{"example":"彼はにやりと笑って、「うまくいったぞ」と言った。","example_reading":"かれはにやりとわらって、「うまくいったぞ」といった。","example_meaning":"Anh ta cười nhếch mép và nói \"Thành công rồi\"."},{"example":"作戦が成功し、隊長はにやりとした。","example_reading":"さくせんがせいこうし、たいちょうはにやりとした。","example_meaning":"Kế hoạch thành công, đội trưởng khẽ nhếch cười."}],"level":"b1"},
{"word":"むくむく","reading":"むくむく","meaning":"phồng lên, trào dâng","note":"Hay đi với 膨らむ, 起き上がる, 湧く. Cũng nói về mây cuồn cuộn.","example":"夏の空に、入道雲がむくむくと湧き上がった。","example_reading":"なつのそらに、にゅうどうぐもがむくむくとわきあがった。","example_meaning":"Trên bầu trời mùa hè, mây vũ tích cuồn cuộn nổi lên.","examples":[{"example":"夏の空に、入道雲がむくむくと湧き上がった。","example_reading":"なつのそらに、にゅうどうぐもがむくむくとわきあがった。","example_meaning":"Trên bầu trời mùa hè, mây vũ tích cuồn cuộn nổi lên."},{"example":"彼の話を聞いて、挑戦したい気持ちがむくむくと湧いてきた。","example_reading":"かれのはなしをきいて、ちょうせんしたいきもちがむくむくとわいてきた。","example_meaning":"Nghe anh ấy kể, ý muốn thử thách trào dâng trong tôi."}],"level":"b1"},
{"word":"ぼりぼり","reading":"ぼりぼり","meaning":"gãi sồn sột; nhai rau ráu","note":"Hay đi với 掻く, 食べる. Gãi mạnh hoặc nhai vật cứng.","example":"蚊に刺された腕を、ぼりぼり掻いてしまった。","example_reading":"かにさされたうでを、ぼりぼりかいてしまった。","example_meaning":"Tôi gãi sồn sột chỗ tay bị muỗi đốt.","examples":[{"example":"蚊に刺された腕を、ぼりぼり掻いてしまった。","example_reading":"かにさされたうでを、ぼりぼりかいてしまった。","example_meaning":"Tôi gãi sồn sột chỗ tay bị muỗi đốt."},{"example":"弟はせんべいをぼりぼり食べながら、テレビを見ている。","example_reading":"おとうとはせんべいをぼりぼりたべながら、テレビをみている。","example_meaning":"Em trai vừa nhai bánh gạo rau ráu vừa xem tivi."}],"level":"b1"},
{"word":"ごりごり","reading":"ごりごり","meaning":"sồn sột (mài, xay)","note":"Hay đi với 削る, 挽く, おろす. Tiếng mài, xay mạnh vật cứng.","example":"コーヒー豆をごりごり挽いて、淹れた。","example_reading":"コーヒーまめをごりごりひいて、いれた。","example_meaning":"Tôi xay hạt cà phê sồn sột rồi pha.","examples":[{"example":"コーヒー豆をごりごり挽いて、淹れた。","example_reading":"コーヒーまめをごりごりひいて、いれた。","example_meaning":"Tôi xay hạt cà phê sồn sột rồi pha."},{"example":"大根をごりごりおろして、そばに入れた。","example_reading":"だいこんをごりごりおろして、そばにいれた。","example_meaning":"Tôi mài củ cải sồn sột rồi cho vào soba."}],"level":"b1"},
{"word":"しなしな","reading":"しなしな","meaning":"héo rũ, mềm nhũn","antonym":"ぱりぱり: giòn rụm / しゃきしゃき: giòn tươi / ぱりっと: giòn rụm","note":"Hay đi với なる, しおれる. Mất độ giòn hoặc tươi.","example":"湿気で、せんべいがしなしなになってしまった。","example_reading":"しっけで、せんべいがしなしなになってしまった。","example_meaning":"Do ẩm, bánh gạo đã trở nên mềm nhũn.","examples":[{"example":"湿気で、せんべいがしなしなになってしまった。","example_reading":"しっけで、せんべいがしなしなになってしまった。","example_meaning":"Do ẩm, bánh gạo đã trở nên mềm nhũn."},{"example":"水をやり忘れて、花がしなしなにしおれていた。","example_reading":"みずをやりわすれて、はながしなしなにしおれていた。","example_meaning":"Quên tưới nước nên hoa héo rũ."}],"level":"b1"},
{"word":"ばくっと","reading":"ばくっと","meaning":"ngoạm to","note":"Hay đi với 食べる, くわえる. Há miệng lớn cắn một miếng.","example":"大きな口を開けて、ハンバーガーをばくっと食べた。","example_reading":"おおきなくちをあけて、ハンバーガーをばくっとたべた。","example_meaning":"Há miệng to, anh ấy ngoạm chiếc hamburger.","examples":[{"example":"大きな口を開けて、ハンバーガーをばくっと食べた。","example_reading":"おおきなくちをあけて、ハンバーガーをばくっとたべた。","example_meaning":"Há miệng to, anh ấy ngoạm chiếc hamburger."},{"example":"ワニが、獲物をばくっとくわえた。","example_reading":"ワニが、えものをばくっとくわえた。","example_meaning":"Con cá sấu ngoạm gọn con mồi."}],"level":"b1"},
{"word":"ぴょこん","reading":"ぴょこん","meaning":"nhô lên; cúi chào nhanh","note":"Hay đi với 飛び出す, お辞儀する. Động tác nhỏ, đáng yêu.","example":"ウサギの耳が、草の間からぴょこんと飛び出した。","example_reading":"ウサギのみみが、くさのあいだからぴょこんととびだした。","example_meaning":"Tai thỏ nhô lên giữa đám cỏ.","examples":[{"example":"ウサギの耳が、草の間からぴょこんと飛び出した。","example_reading":"ウサギのみみが、くさのあいだからぴょこんととびだした。","example_meaning":"Tai thỏ nhô lên giữa đám cỏ."},{"example":"子どもは、ぴょこんとお辞儀をして、走っていった。","example_reading":"こどもは、ぴょこんとおじぎをして、はしっていった。","example_meaning":"Đứa bé cúi chào nhanh một cái rồi chạy đi."}],"level":"b1"},
{"word":"ぽわぽわ","reading":"ぽわぽわ","meaning":"mềm xốp, lâng lâng","note":"Hay đi với 漂う, する. Nhẹ như bông hoặc đầu óc lơ mơ.","example":"たんぽぽの綿毛が、ぽわぽわと風に漂っている。","example_reading":"たんぽぽのわたげが、ぽわぽわとかぜにただよっている。","example_meaning":"Những sợi bông bồ công anh bồng bềnh trong gió.","examples":[{"example":"たんぽぽの綿毛が、ぽわぽわと風に漂っている。","example_reading":"たんぽぽのわたげが、ぽわぽわとかぜにただよっている。","example_meaning":"Những sợi bông bồ công anh bồng bềnh trong gió."},{"example":"お酒を飲んで、頭がぽわぽわしてきた。","example_reading":"おさけをのんで、あたまがぽわぽわしてきた。","example_meaning":"Uống rượu xong, đầu tôi lâng lâng."}],"level":"b1"},
{"word":"ほわっと","reading":"ほわっと","meaning":"nhẹ nhàng, thoang thoảng","note":"Hay đi với 香る, 立ちのぼる. Hơi ấm hoặc hương nhẹ lan ra.","example":"カフェに入ると、ほわっと甘い香りがした。","example_reading":"カフェにはいると、ほわっとあまいかおりがした。","example_meaning":"Bước vào quán cà phê, một mùi ngọt thoang thoảng lan ra.","examples":[{"example":"カフェに入ると、ほわっと甘い香りがした。","example_reading":"カフェにはいると、ほわっとあまいかおりがした。","example_meaning":"Bước vào quán cà phê, một mùi ngọt thoang thoảng lan ra."},{"example":"湯気がほわっと立ちのぼる、温かいスープだ。","example_reading":"ゆげがほわっとたちのぼる、あたたかいスープだ。","example_meaning":"Đó là món súp nóng với hơi nước nhẹ bốc lên."}],"level":"b1"},
{"word":"ゆるっと","reading":"ゆるっと","meaning":"thoải mái, lỏng lẻo","antonym":"ぴったり: vừa khít","note":"Hay đi với した. Không gò bó, thường nói về quần áo hoặc tâm trạng.","example":"ゆるっとしたワンピースは、楽で着やすい。","example_reading":"ゆるっとしたワンピースは、らくできやすい。","example_meaning":"Chiếc váy suông rộng mặc thoải mái dễ dàng.","examples":[{"example":"ゆるっとしたワンピースは、楽で着やすい。","example_reading":"ゆるっとしたワンピースは、らくできやすい。","example_meaning":"Chiếc váy suông rộng mặc thoải mái dễ dàng."},{"example":"今日は、ゆるっとした気分で過ごしたい。","example_reading":"きょうは、ゆるっとしたきぶんですごしたい。","example_meaning":"Hôm nay tôi muốn sống với tâm trạng thong thả."}],"level":"b1"},
{"word":"ぎとぎと","reading":"ぎとぎと","meaning":"nhờn dầu mỡ","antonym":"さっぱり: thanh đạm / さらさら: khô ráo","note":"Hay đi với する, 油. Có nhiều dầu mỡ gây khó chịu.","example":"揚げ物ばかり食べて、顔がぎとぎとしてきた。","example_reading":"あげものばかりたべて、かおがぎとぎとしてきた。","example_meaning":"Ăn toàn đồ chiên nên mặt tôi nhờn bóng.","examples":[{"example":"揚げ物ばかり食べて、顔がぎとぎとしてきた。","example_reading":"あげものばかりたべて、かおがぎとぎとしてきた。","example_meaning":"Ăn toàn đồ chiên nên mặt tôi nhờn bóng."},{"example":"この料理は、油が多くてぎとぎとしている。","example_reading":"このりょうりは、あぶらがおおくてぎとぎとしている。","example_meaning":"Món này nhiều dầu nên rất ngấy."}],"level":"b1"},
{"word":"ぐりぐり","reading":"ぐりぐり","meaning":"day mạnh, xoáy","note":"Hay đi với 押す, 回す, 撫でる. Ấn hoặc xoay mạnh.","example":"肩のこりをほぐそうと、ぐりぐり押してもらった。","example_reading":"かたのこりをほぐそうと、ぐりぐりおしてもらった。","example_meaning":"Tôi nhờ người ấn mạnh để làm dịu vai cứng.","examples":[{"example":"肩のこりをほぐそうと、ぐりぐり押してもらった。","example_reading":"かたのこりをほぐそうと、ぐりぐりおしてもらった。","example_meaning":"Tôi nhờ người ấn mạnh để làm dịu vai cứng."},{"example":"犬の頭を、ぐりぐり撫でてやった。","example_reading":"いぬのあたまを、ぐりぐりなでてやった。","example_meaning":"Tôi xoa đầu con chó thật mạnh."}],"level":"b1"},
{"word":"ぴちゃぴちゃ","reading":"ぴちゃぴちゃ","meaning":"tõm tõm, chóp chép (nước)","note":"Hay đi với 水, 舐める. Tiếng nước bắn nhẹ, tiếng liếm.","example":"子どもたちは水たまりでぴちゃぴちゃ遊んでいる。","example_reading":"こどもたちはみずたまりでぴちゃぴちゃあそんでいる。","example_meaning":"Bọn trẻ nghịch tõm tõm trong vũng nước.","examples":[{"example":"子どもたちは水たまりでぴちゃぴちゃ遊んでいる。","example_reading":"こどもたちはみずたまりでぴちゃぴちゃあそんでいる。","example_meaning":"Bọn trẻ nghịch tõm tõm trong vũng nước."},{"example":"猫がミルクをぴちゃぴちゃと舐めている。","example_reading":"ねこがミルクをぴちゃぴちゃとなめている。","example_meaning":"Con mèo liếm sữa chóp chép."}],"level":"b1"},
{"word":"じゃぶじゃぶ","reading":"じゃぶじゃぶ","meaning":"ào ào, lõm bõm (nước)","note":"Hay đi với 洗う, 歩く. Tiếng nước bắn nhiều khi giặt hoặc lội.","example":"川に入って、じゃぶじゃぶと洗濯をした。","example_reading":"かわにはいって、じゃぶじゃぶとせんたくをした。","example_meaning":"Tôi lội xuống sông giặt đồ ào ào.","examples":[{"example":"川に入って、じゃぶじゃぶと洗濯をした。","example_reading":"かわにはいって、じゃぶじゃぶとせんたくをした。","example_meaning":"Tôi lội xuống sông giặt đồ ào ào."},{"example":"子どもは長靴で、浅い川をじゃぶじゃぶ歩いた。","example_reading":"こどもはながぐつで、あさいかわをじゃぶじゃぶあるいた。","example_meaning":"Đứa bé đi ủng lội lõm bõm qua con sông cạn."}],"level":"b1"},
{"word":"ぽっこり","reading":"ぽっこり","meaning":"phình ra, nhô lên","antonym":"へこんで: lõm xuống / ぺしゃんこ: dẹp lép","note":"Hay đi với お腹, 膨らむ. Phình tròn nhẹ.","example":"運動不足で、お腹がぽっこり出てきた。","example_reading":"うんどうぶそくで、おなかがぽっこりでてきた。","example_meaning":"Vì thiếu vận động nên bụng tôi phình ra.","examples":[{"example":"運動不足で、お腹がぽっこり出てきた。","example_reading":"うんどうぶそくで、おなかがぽっこりでてきた。","example_meaning":"Vì thiếu vận động nên bụng tôi phình ra."},{"example":"海の上に、小さな島がぽっこり浮かんでいる。","example_reading":"うみのうえに、ちいさなしまがぽっこりうかんでいる。","example_meaning":"Trên mặt biển, một hòn đảo nhỏ nhô lên."}],"level":"b1"},
{"word":"ぴしゃり","reading":"ぴしゃり","meaning":"đóng sập; vỗ chan chát","note":"Hay đi với と, 閉める, 叩く. Cũng nghĩa dứt khoát bác bỏ.","example":"彼は怒って、戸をぴしゃりと閉めて出ていった。","example_reading":"かれはおこって、とをぴしゃりとしめてでていった。","example_meaning":"Anh ta giận dữ đóng sập cửa rồi bỏ đi.","examples":[{"example":"彼は怒って、戸をぴしゃりと閉めて出ていった。","example_reading":"かれはおこって、とをぴしゃりとしめてでていった。","example_meaning":"Anh ta giận dữ đóng sập cửa rồi bỏ đi."},{"example":"部長は私の提案をぴしゃりと断った。","example_reading":"ぶちょうはわたしのていあんをぴしゃりとことわった。","example_meaning":"Trưởng phòng gạt phăng đề xuất của tôi."}],"level":"b1"},
{"word":"もやっと","reading":"もやっと","meaning":"mờ mịt; lòng bứt rứt","antonym":"すっきり: sảng khoái","note":"Hay đi với する, 霧. Có sương mù mờ, hoặc cảm giác khó chịu không rõ. Gần もやもや.","example":"朝の駅前は、霧でもやっとしていた。","example_reading":"あさのえきまえは、きりでもやっとしていた。","example_meaning":"Sáng sớm trước ga mờ mịt vì sương.","examples":[{"example":"朝の駅前は、霧でもやっとしていた。","example_reading":"あさのえきまえは、きりでもやっとしていた。","example_meaning":"Sáng sớm trước ga mờ mịt vì sương."},{"example":"彼の返事を聞いて、胸の中がもやっとした。","example_reading":"かれのへんじをきいて、むねのなかがもやっとした。","example_meaning":"Nghe câu trả lời của anh ấy, lòng tôi thấy lấn cấn."}],"level":"b1"},
{"word":"きょろきょろ","reading":"きょろきょろ","meaning":"đảo mắt nhìn quanh","antonym":"じっと: yên lặng, chăm chú","note":"Nhìn quanh liên tục vì tò mò hoặc tìm kiếm. Hay đi với 見回す, する.","example":"道に迷って、きょろきょろと周りを見回した。","example_reading":"みちにまよって、きょろきょろとまわりをみまわした。","example_meaning":"Bị lạc đường, tôi đảo mắt nhìn quanh.","examples":[{"example":"道に迷って、きょろきょろと周りを見回した。","example_reading":"みちにまよって、きょろきょろとまわりをみまわした。","example_meaning":"Bị lạc đường, tôi đảo mắt nhìn quanh."},{"example":"きょろきょろしていないで、前を向いて歩きなさい。","example_reading":"きょろきょろしていないで、まえをむいてあるきなさい。","example_meaning":"Đừng nhìn ngó lung tung, hãy nhìn phía trước mà đi."}],"level":"b1"},
{"word":"ひょろひょろ","reading":"ひょろひょろ","meaning":"gầy cao lêu nghêu","antonym":"がっしり: vạm vỡ / どっしり: vững chãi","note":"Hay đi với 伸びる, した体型. Mảnh yếu, thiếu vững chắc.","example":"背ばかり伸びて、ひょろひょろした体型だ。","example_reading":"せばかりのびて、ひょろひょろしたたいけいだ。","example_meaning":"Cao lên chỉ biết cao, dáng người lêu nghêu.","examples":[{"example":"背ばかり伸びて、ひょろひょろした体型だ。","example_reading":"せばかりのびて、ひょろひょろしたたいけいだ。","example_meaning":"Cao lên chỉ biết cao, dáng người lêu nghêu."},{"example":"日当たりが悪くて、苗がひょろひょろと伸びてしまった。","example_reading":"ひあたりがわるくて、なえがひょろひょろとのびてしまった。","example_meaning":"Thiếu nắng nên cây con mọc vống lên mảnh yếu."}],"level":"b1"},
{"word":"ごとごと","reading":"ごとごと","meaning":"lộc cộc (xe, nồi)","note":"Hay đi với 揺れる, 音を立てる. Tiếng vật nặng chuyển động đều.","example":"電車が、ごとごと揺れながら進んでいく。","example_reading":"でんしゃが、ごとごとゆれながらすすんでいく。","example_meaning":"Đoàn tàu lắc lư lộc cộc tiến về phía trước.","examples":[{"example":"電車が、ごとごと揺れながら進んでいく。","example_reading":"でんしゃが、ごとごとゆれながらすすんでいく。","example_meaning":"Đoàn tàu lắc lư lộc cộc tiến về phía trước."},{"example":"台所の鍋が、ごとごと音を立てている。","example_reading":"だいどころのなべが、ごとごとおとをたてている。","example_meaning":"Chiếc nồi trong bếp kêu lộc cộc."}],"level":"b1"},
{"word":"こそこそ","reading":"こそこそ","meaning":"lén lút, rón rén","antonym":"堂々と（どうどうと）: đường hoàng","antonym_hanviet":"đường đường","note":"Từ tượng hình. Làm gì đó trốn tránh người khác, sắc thái tiêu cực.","example":"彼は何かこそこそ話している。","example_reading":"かれはなにかこそこそはなしている。","example_meaning":"Anh ta đang thì thầm lén lút chuyện gì đó.","examples":[{"example":"彼は何かこそこそ話している。","example_reading":"かれはなにかこそこそはなしている。","example_meaning":"Anh ta đang thì thầm lén lút chuyện gì đó."},{"example":"彼らは会議の後、こそこそと何か相談していた。","example_reading":"かれらはかいぎのあと、こそこそとなにかそうだんしていた。","example_meaning":"Sau cuộc họp, họ rỉ tai bàn bạc điều gì đó."}],"level":"b1"},
{"word":"ひそひそ","reading":"ひそひそ","meaning":"thì thầm, xì xào","antonym":"大声で（おおごえで）: nói to","antonym_hanviet":"đại thanh","note":"Từ tượng thanh. Nói rất nhỏ để người khác không nghe.","example":"図書館では、ひそひそ声で話します。","example_reading":"としょかんでは、ひそひそごえではなします。","example_meaning":"Trong thư viện tôi nói thì thầm.","examples":[{"example":"図書館では、ひそひそ声で話します。","example_reading":"としょかんでは、ひそひそごえではなします。","example_meaning":"Trong thư viện tôi nói thì thầm."},{"example":"後ろの席の人が、ひそひそ話をしている。","example_reading":"うしろのせきのひとが、ひそひそばなしをしている。","example_meaning":"Người ngồi ghế sau đang thì thầm nói chuyện."}],"level":"b1"},
{"word":"ぽつん","reading":"ぽつん","meaning":"lẻ loi, cô độc; một chấm nhỏ","antonym":"ずらり: hàng dài","note":"Hay đi với と, 立つ, 座る, 残る. Một mình giữa không gian rộng.","example":"野原にぽつんと一本の木が立っていた。","example_reading":"のはらにぽつんといっぽんのきがたっていた。","example_meaning":"Giữa cánh đồng có một cái cây đứng lẻ loi.","examples":[{"example":"野原にぽつんと一本の木が立っていた。","example_reading":"のはらにぽつんといっぽんのきがたっていた。","example_meaning":"Giữa cánh đồng có một cái cây đứng lẻ loi."},{"example":"パーティーで知り合いがおらず、ぽつんと座っていた。","example_reading":"パーティーでしりあいがおらず、ぽつんとすわっていた。","example_meaning":"Ở bữa tiệc không có người quen, tôi ngồi lẻ loi một mình."}],"level":"b1"},
{"word":"ごっそり","reading":"ごっそり","meaning":"sạch trơn, một lượng lớn cùng lúc","note":"Hay đi với 盗む, 減る, 抜ける, 取る. Lấy đi hoặc mất đi một lượng lớn.","example":"空き巣に入られて、現金がごっそり盗まれた。","example_reading":"あきすにはいられて、げんきんがごっそりぬすまれた。","example_meaning":"Bị trộm đột nhập, tiền mặt bị lấy sạch.","examples":[{"example":"空き巣に入られて、現金がごっそり盗まれた。","example_reading":"あきすにはいられて、げんきんがごっそりぬすまれた。","example_meaning":"Bị trộm đột nhập, tiền mặt bị lấy sạch."},{"example":"最近は抜け毛がひどくて、髪がごっそり抜ける。","example_reading":"さいきんはぬけげがひどくて、かみがごっそりぬける。","example_meaning":"Dạo này rụng tóc nhiều, tóc rụng từng nắm."}],"level":"b1"},
{"word":"ぐっしょり","reading":"ぐっしょり","meaning":"ướt đẫm, ướt nhẹp","antonym":"からから: khô khốc","note":"Hay đi với 濡れる, 汗. Nặng nước hơn びっしょり, cảm giác nhão nhoẹt.","example":"悪い夢を見て、起きたら寝間着が汗でぐっしょりだった。","example_reading":"わるいゆめをみて、おきたらねまきがあせでぐっしょりだった。","example_meaning":"Gặp ác mộng, tỉnh dậy thấy đồ ngủ ướt đẫm mồ hôi.","examples":[{"example":"悪い夢を見て、起きたら寝間着が汗でぐっしょりだった。","example_reading":"わるいゆめをみて、おきたらねまきがあせでぐっしょりだった。","example_meaning":"Gặp ác mộng, tỉnh dậy thấy đồ ngủ ướt đẫm mồ hôi."},{"example":"川に落ちて、靴の中までぐっしょり濡れた。","example_reading":"かわにおちて、くつのなかまでぐっしょりぬれた。","example_meaning":"Rơi xuống sông, ướt nhẹp cả bên trong giày."}],"level":"b1"},
{"word":"ぐすぐす","reading":"ぐすぐす","meaning":"sụt sịt (khóc, mũi)","note":"Hay đi với 泣く, 鼻をすする. Tiếng khóc nhỏ hoặc mũi nghẹt.","example":"子どもは転んで、ぐすぐす泣いている。","example_reading":"こどもはころんで、ぐすぐすないている。","example_meaning":"Đứa bé ngã rồi, đang sụt sịt khóc.","examples":[{"example":"子どもは転んで、ぐすぐす泣いている。","example_reading":"こどもはころんで、ぐすぐすないている。","example_meaning":"Đứa bé ngã rồi, đang sụt sịt khóc."},{"example":"花粉症で、春になると鼻がぐすぐすする。","example_reading":"かふんしょうで、はるになるとはながぐすぐすする。","example_meaning":"Vì dị ứng phấn hoa nên mùa xuân mũi tôi cứ sụt sịt."}],"level":"b1"},
{"word":"がやがや","reading":"がやがや","meaning":"ồn ào, nhao nhao","antonym":"しーん: im phăng phắc","note":"Từ tượng thanh. Nhiều người nói chuyện cùng lúc.","example":"休み時間の教室はがやがやしている。","example_reading":"やすみじかんのきょうしつはがやがやしている。","example_meaning":"Lớp học giờ ra chơi ồn ào.","examples":[{"example":"休み時間の教室はがやがやしている。","example_reading":"やすみじかんのきょうしつはがやがやしている。","example_meaning":"Lớp học giờ ra chơi ồn ào."},{"example":"駅前は、人々でがやがやしていた。","example_reading":"えきまえは、ひとびとでがやがやしていた。","example_meaning":"Trước nhà ga ồn ào người qua lại."}],"level":"b1"},
{"word":"ぶつぶつ","reading":"ぶつぶつ","meaning":"lầm bầm, cằn nhằn","antonym":"はっきり: rõ ràng","note":"Từ tượng thanh. Nói nhỏ trong miệng, thường là phàn nàn.","example":"彼はいつもぶつぶつ文句を言っている。","example_reading":"かれはいつもぶつぶつもんくをいっている。","example_meaning":"Anh ta lúc nào cũng lầm bầm phàn nàn.","examples":[{"example":"彼はいつもぶつぶつ文句を言っている。","example_reading":"かれはいつもぶつぶつもんくをいっている。","example_meaning":"Anh ta lúc nào cũng lầm bầm phàn nàn."},{"example":"彼女は一人でぶつぶつ言いながら歩いていた。","example_reading":"かのじょはひとりでぶつぶついいながらあるいていた。","example_meaning":"Cô ấy vừa đi vừa lẩm bẩm một mình."}],"level":"b1"},
{"word":"ぺちゃくちゃ","reading":"ぺちゃくちゃ","meaning":"líu lo, nói huyên thuyên","antonym":"黙々と（もくもくと）: lặng lẽ","antonym_hanviet":"mặc mặc","note":"Nói chuyện không ngớt, ồn ào. Hay đi với 喋る, おしゃべり.","example":"図書館で、ぺちゃくちゃ喋ってはいけません。","example_reading":"としょかんで、ぺちゃくちゃしゃべってはいけません。","example_meaning":"Không được nói chuyện huyên thuyên trong thư viện.","examples":[{"example":"図書館で、ぺちゃくちゃ喋ってはいけません。","example_reading":"としょかんで、ぺちゃくちゃしゃべってはいけません。","example_meaning":"Không được nói chuyện huyên thuyên trong thư viện."},{"example":"後ろの席の女の子たちが、ぺちゃくちゃとおしゃべりしている。","example_reading":"うしろのせきのおんなのこたちが、ぺちゃくちゃとおしゃべりしている。","example_meaning":"Mấy cô bé ở hàng ghế sau đang nói chuyện líu lo."}],"level":"b1"},
{"word":"でっぷり","reading":"でっぷり","meaning":"phị, bụng phệ","antonym":"すらっと: thon thả / ほっそり: mảnh mai / げっそり: hốc hác","note":"Hay đi với した, 太る. Béo phị, bụng to.","example":"でっぷりした体格の男が、店の奥から出てきた。","example_reading":"でっぷりしたたいかくのおとこが、みせのおくからでてきた。","example_meaning":"Người đàn ông thân hình to béo bước ra từ trong cửa hàng.","examples":[{"example":"でっぷりした体格の男が、店の奥から出てきた。","example_reading":"でっぷりしたたいかくのおとこが、みせのおくからでてきた。","example_meaning":"Người đàn ông thân hình to béo bước ra từ trong cửa hàng."},{"example":"年を取って、お腹がでっぷりと出てきた。","example_reading":"としをとって、おなかがでっぷりとでてきた。","example_meaning":"Có tuổi nên bụng tôi phệ ra."}],"level":"b1"},
{"word":"ちろちろ","reading":"ちろちろ","meaning":"le lói; thè lè","note":"Hay đi với 燃える, 舌を出す. Lửa nhỏ nhấp nháy hoặc lưỡi thè nhanh.","example":"暖炉の中で、小さな炎がちろちろと燃えている。","example_reading":"だんろのなかで、ちいさなほのおがちろちろともえている。","example_meaning":"Ngọn lửa nhỏ nhấp nhoáng trong lò sưởi.","examples":[{"example":"暖炉の中で、小さな炎がちろちろと燃えている。","example_reading":"だんろのなかで、ちいさなほのおがちろちろともえている。","example_meaning":"Ngọn lửa nhỏ nhấp nhoáng trong lò sưởi."},{"example":"蛇が舌をちろちろと出している。","example_reading":"へびがしたをちろちろとだしている。","example_meaning":"Con rắn thè lưỡi liên tục."}],"level":"b1"},
{"word":"かちこち","reading":"かちこち","meaning":"cứng đơ","antonym":"ふにゃふにゃ: mềm nhũn / ぐにゃぐにゃ: mềm oặt","note":"Hay đi với 固まる, なる. Cứng vì đông lạnh hoặc căng thẳng.","example":"冷凍庫から出したパンは、かちこちに固まっていた。","example_reading":"れいとうこからだしたパンは、かちこちにかたまっていた。","example_meaning":"Bánh mì lấy từ ngăn đá ra cứng đơ.","examples":[{"example":"冷凍庫から出したパンは、かちこちに固まっていた。","example_reading":"れいとうこからだしたパンは、かちこちにかたまっていた。","example_meaning":"Bánh mì lấy từ ngăn đá ra cứng đơ."},{"example":"緊張で、体がかちこちになってしまった。","example_reading":"きんちょうで、からだがかちこちになってしまった。","example_meaning":"Vì căng thẳng, người tôi cứng đờ."}],"level":"b1"},
{"word":"ひくっと","reading":"ひくっと","meaning":"giật nhẹ, nấc","note":"Hay đi với 動く, しゃっくり. Cử động giật thoáng qua.","example":"名前を呼ばれて、肩がひくっと動いた。","example_reading":"なまえをよばれて、かたがひくっとうごいた。","example_meaning":"Bị gọi tên, vai tôi giật nhẹ.","examples":[{"example":"名前を呼ばれて、肩がひくっと動いた。","example_reading":"なまえをよばれて、かたがひくっとうごいた。","example_meaning":"Bị gọi tên, vai tôi giật nhẹ."},{"example":"しゃっくりがひくっと出て、止まらない。","example_reading":"しゃっくりがひくっとでて、とまらない。","example_meaning":"Tôi nấc cụt từng tiếng không dừng được."}],"level":"b1"},
{"word":"わなわな","reading":"わなわな","meaning":"run lẩy bẩy","note":"Hay đi với 震える. Run vì giận, sợ, xúc động.","example":"怒りで、彼の手がわなわなと震えていた。","example_reading":"いかりで、かれのてがわなわなとふるえていた。","example_meaning":"Tay anh ấy run lên vì tức giận.","examples":[{"example":"怒りで、彼の手がわなわなと震えていた。","example_reading":"いかりで、かれのてがわなわなとふるえていた。","example_meaning":"Tay anh ấy run lên vì tức giận."},{"example":"緊張のあまり、唇がわなわな震えた。","example_reading":"きんちょうのあまり、くちびるがわなわなふるえた。","example_meaning":"Căng thẳng quá nên môi tôi run lẩy bẩy."}],"level":"b1"},
{"word":"ばくばく","reading":"ばくばく","meaning":"thình thịch (tim); ăn ngấu nghiến","note":"Hay đi với 心臓, 食べる. Tim đập rất mạnh vì căng thẳng; cũng ăn lấy ăn để.","example":"発表の前、緊張で心臓がばくばくしていた。","example_reading":"はっぴょうのまえ、きんちょうでしんぞうがばくばくしていた。","example_meaning":"Trước buổi thuyết trình, tim tôi đập thình thịch vì căng thẳng.","examples":[{"example":"発表の前、緊張で心臓がばくばくしていた。","example_reading":"はっぴょうのまえ、きんちょうでしんぞうがばくばくしていた。","example_meaning":"Trước buổi thuyết trình, tim tôi đập thình thịch vì căng thẳng."},{"example":"弟はお腹がすいていたのか、ご飯をばくばく食べている。","example_reading":"おとうとはおなかがすいていたのか、ごはんをばくばくたべている。","example_meaning":"Em trai chắc đói nên ăn ngấu nghiến."}],"level":"b1"},
{"word":"ぶくぶく","reading":"ぶくぶく","meaning":"sủi bọt; béo phị","note":"Hay đi với 泡, 太る. Bọt nổi lên; cũng chỉ người mập ú.","example":"水の中から、ぶくぶくと泡が出てきた。","example_reading":"みずのなかから、ぶくぶくとあわがでてきた。","example_meaning":"Từ dưới nước, bọt sủi lên ùng ục.","examples":[{"example":"水の中から、ぶくぶくと泡が出てきた。","example_reading":"みずのなかから、ぶくぶくとあわがでてきた。","example_meaning":"Từ dưới nước, bọt sủi lên ùng ục."},{"example":"運動をやめたら、体がぶくぶくに太ってしまった。","example_reading":"うんどうをやめたら、からだがぶくぶくにふとってしまった。","example_meaning":"Bỏ tập thể dục nên người tôi béo phị ra."}],"level":"b1"},
{"word":"ぎしぎし","reading":"ぎしぎし","meaning":"cót két, kẽo kẹt","note":"Hay đi với 鳴る, 軋む. Tiếng gỗ, ván kêu khi chịu sức nặng.","example":"古い階段を上るたびに、ぎしぎしと音がする。","example_reading":"ふるいかいだんをのぼるたびに、ぎしぎしとおとがする。","example_meaning":"Mỗi lần bước lên cầu thang cũ lại kêu cót két.","examples":[{"example":"古い階段を上るたびに、ぎしぎしと音がする。","example_reading":"ふるいかいだんをのぼるたびに、ぎしぎしとおとがする。","example_meaning":"Mỗi lần bước lên cầu thang cũ lại kêu cót két."},{"example":"ベッドが古くて、寝返りを打つとぎしぎしいう。","example_reading":"ベッドがふるくて、ねがえりをうつとぎしぎしいう。","example_meaning":"Giường cũ nên trở mình là kêu kẽo kẹt."}],"level":"b1"},
{"word":"べらべら","reading":"べらべら","meaning":"nói liến thoắng, ba hoa","antonym":"黙々と（もくもくと）: lặng lẽ","antonym_hanviet":"mặc mặc","note":"Nói nhiều và trôi chảy, thường mang nghĩa tiêu cực (khác ペラペラ là lưu loát). Hay đi với 喋る.","example":"彼は秘密を、べらべらと喋ってしまった。","example_reading":"かれはひみつを、べらべらとしゃべってしまった。","example_meaning":"Anh ta liến thoắng nói hết bí mật ra.","examples":[{"example":"彼は秘密を、べらべらと喋ってしまった。","example_reading":"かれはひみつを、べらべらとしゃべってしまった。","example_meaning":"Anh ta liến thoắng nói hết bí mật ra."},{"example":"酔った彼は、自慢話をべらべらと続けた。","example_reading":"よったかれは、じまんはなしをべらべらとつづけた。","example_meaning":"Anh ta say rồi cứ ba hoa khoe khoang mãi."}],"level":"b1"},
{"word":"くすくす","reading":"くすくす","meaning":"cười khúc khích","antonym":"げらげら: cười ha hả","note":"Từ tượng thanh. Cười nhỏ, cố nén tiếng.","example":"後ろの席でくすくす笑う声が聞こえた。","example_reading":"うしろのせきでくすくすわらうこえがきこえた。","example_meaning":"Tôi nghe tiếng cười khúc khích ở hàng ghế sau.","examples":[{"example":"後ろの席でくすくす笑う声が聞こえた。","example_reading":"うしろのせきでくすくすわらうこえがきこえた。","example_meaning":"Tôi nghe tiếng cười khúc khích ở hàng ghế sau."},{"example":"彼女は、手で口を押さえてくすくす笑った。","example_reading":"かのじょは、てでくちをおさえてくすくすわらった。","example_meaning":"Cô ấy lấy tay che miệng cười khúc khích."}],"level":"b1"},
{"word":"げらげら","reading":"げらげら","meaning":"cười ha hả","antonym":"くすくす: cười khúc khích / しくしく: sụt sùi","note":"Từ tượng thanh. Cười to, thoải mái.","example":"友達の話が面白くて、げらげら笑った。","example_reading":"ともだちのはなしがおもしろくて、げらげらわらった。","example_meaning":"Chuyện của bạn buồn cười nên tôi cười ha hả.","examples":[{"example":"友達の話が面白くて、げらげら笑った。","example_reading":"ともだちのはなしがおもしろくて、げらげらわらった。","example_meaning":"Chuyện của bạn buồn cười nên tôi cười ha hả."},{"example":"テレビを見ながら、みんなでげらげら笑った。","example_reading":"テレビをみながら、みんなでげらげらわらった。","example_meaning":"Vừa xem tivi, mọi người vừa cười ha hả."}],"level":"b1"},
{"word":"にやにや","reading":"にやにや","meaning":"cười tủm tỉm, cười thầm","note":"Từ tượng hình. Cười mỉm, có thể ngụ ý đắc ý hoặc ẩn ý.","example":"彼は何かにやにやしている。","example_reading":"かれはなにかにやにやしている。","example_meaning":"Anh ta cứ cười tủm tỉm chuyện gì đó.","examples":[{"example":"彼は何かにやにやしている。","example_reading":"かれはなにかにやにやしている。","example_meaning":"Anh ta cứ cười tủm tỉm chuyện gì đó."},{"example":"彼はいたずらが成功して、にやにやしていた。","example_reading":"かれはいたずらがせいこうして、にやにやしていた。","example_meaning":"Trò đùa thành công nên anh ta cười tủm tỉm."}],"level":"b1"},
{"word":"ほわほわ","reading":"ほわほわ","meaning":"mềm xốp, nhẹ bẫng","note":"Hay đi với 雪, 毛, ひよこ. Mềm và nhẹ như bông.","example":"生まれたばかりのひよこは、ほわほわしていてかわいい。","example_reading":"うまれたばかりのひよこは、ほわほわしていてかわいい。","example_meaning":"Gà con mới nở mềm xốp trông thật đáng yêu.","examples":[{"example":"生まれたばかりのひよこは、ほわほわしていてかわいい。","example_reading":"うまれたばかりのひよこは、ほわほわしていてかわいい。","example_meaning":"Gà con mới nở mềm xốp trông thật đáng yêu."},{"example":"ほわほわの雪が、静かに降り積もっていく。","example_reading":"ほわほわのゆきが、しずかにふりつもっていく。","example_meaning":"Tuyết mềm xốp lặng lẽ phủ dày dần."}],"level":"b1"},
{"word":"ゆらり","reading":"ゆらり","meaning":"lắc lư nhẹ","note":"Hay đi với と, 揺れる, 立ち上がる. Chuyển động chậm một lần.","example":"カーテンがゆらりと揺れて、風が入ってきた。","example_reading":"カーテンがゆらりとゆれて、かぜがはいってきた。","example_meaning":"Tấm rèm lay nhẹ và gió ùa vào.","examples":[{"example":"カーテンがゆらりと揺れて、風が入ってきた。","example_reading":"カーテンがゆらりとゆれて、かぜがはいってきた。","example_meaning":"Tấm rèm lay nhẹ và gió ùa vào."},{"example":"酔った男は、ゆらりと立ち上がって歩き出した。","example_reading":"よったおとこは、ゆらりとたちあがってあるきだした。","example_meaning":"Người đàn ông say loạng choạng đứng dậy rồi bước đi."}],"level":"b1"},
{"word":"ぶらん","reading":"ぶらん","meaning":"lủng lẳng","note":"Hay đi với と, 垂れ下がる, 投げ出す.","example":"枝から、ブランコがぶらんと垂れ下がっている。","example_reading":"えだから、ブランコがぶらんとたれさがっている。","example_meaning":"Chiếc xích đu treo lủng lẳng từ cành cây.","examples":[{"example":"枝から、ブランコがぶらんと垂れ下がっている。","example_reading":"えだから、ブランコがぶらんとたれさがっている。","example_meaning":"Chiếc xích đu treo lủng lẳng từ cành cây."},{"example":"彼は足をぶらんと投げ出して、ベンチに座った。","example_reading":"かれはあしをぶらんとなげだして、ベンチにすわった。","example_meaning":"Anh ấy thả chân lủng lẳng và ngồi xuống ghế."}],"level":"b1"},
{"word":"どすん","reading":"どすん","meaning":"bịch (vật nặng)","note":"Hay đi với と, 落ちる, 腰を下ろす. Tiếng vật nặng rơi hoặc ngồi mạnh.","example":"重い荷物が、床にどすんと落ちた。","example_reading":"おもいにもつが、ゆかにどすんとおちた。","example_meaning":"Hành lý nặng rơi bịch xuống sàn.","examples":[{"example":"重い荷物が、床にどすんと落ちた。","example_reading":"おもいにもつが、ゆかにどすんとおちた。","example_meaning":"Hành lý nặng rơi bịch xuống sàn."},{"example":"彼は疲れて、ソファにどすんと腰を下ろした。","example_reading":"かれはつかれて、ソファにどすんとこしをおろした。","example_meaning":"Anh ấy mệt nên thả người đánh phịch xuống sofa."}],"level":"b1"},
{"word":"どかっと","reading":"どかっと","meaning":"phịch (ngồi, đặt xuống)","antonym":"そっと: nhẹ nhàng","note":"Hay đi với 座る, 置く. Hành động mạnh, thô.","example":"彼はどかっと椅子に座って、腕を組んだ。","example_reading":"かれはどかっといすにすわって、うでをくんだ。","example_meaning":"Anh ta ngồi phịch xuống ghế và khoanh tay.","examples":[{"example":"彼はどかっと椅子に座って、腕を組んだ。","example_reading":"かれはどかっといすにすわって、うでをくんだ。","example_meaning":"Anh ta ngồi phịch xuống ghế và khoanh tay."},{"example":"テーブルの上に、料理がどかっと置かれた。","example_reading":"テーブルのうえに、りょうりがどかっとおかれた。","example_meaning":"Món ăn được đặt phịch lên bàn."}],"level":"b1"},
{"word":"ばしゃっと","reading":"ばしゃっと","meaning":"tạt, bắn (nước)","note":"Hay đi với 水, 跳ねる, かける.","example":"車が水たまりを走り、水がばしゃっと跳ねた。","example_reading":"くるまがみずたまりをはしり、みずがばしゃっとはねた。","example_meaning":"Xe chạy qua vũng nước, nước bắn tung tóe.","examples":[{"example":"車が水たまりを走り、水がばしゃっと跳ねた。","example_reading":"くるまがみずたまりをはしり、みずがばしゃっとはねた。","example_meaning":"Xe chạy qua vũng nước, nước bắn tung tóe."},{"example":"暑くて、顔にばしゃっと冷たい水をかけた。","example_reading":"あつくて、かおにばしゃっとつめたいみずをかけた。","example_meaning":"Nóng quá nên tôi tạt nước lạnh lên mặt."}],"level":"b1"},
{"word":"ぽとり","reading":"ぽとり","meaning":"rơi tõm một giọt/vật nhỏ","note":"Hay đi với と, 落ちる. Vật nhẹ nhỏ rơi nhẹ.","example":"熟した柿が、ぽとりと地面に落ちた。","example_reading":"じゅくしたかきが、ぽとりとじめんにおちた。","example_meaning":"Quả hồng chín rơi bộp xuống đất.","examples":[{"example":"熟した柿が、ぽとりと地面に落ちた。","example_reading":"じゅくしたかきが、ぽとりとじめんにおちた。","example_meaning":"Quả hồng chín rơi bộp xuống đất."},{"example":"彼のポケットから、鍵がぽとりと落ちた。","example_reading":"かれのポケットから、かぎがぽとりとおちた。","example_meaning":"Chiếc chìa khóa rơi bộp ra khỏi túi anh ấy."}],"level":"b1"},
{"word":"ひくひく","reading":"ひくひく","meaning":"giật giật, phập phồng","note":"Hay đi với 動く, 鼻, まぶた.","example":"犬の鼻が、においを嗅いでひくひく動いている。","example_reading":"いぬのはなが、においをかいでひくひくうごいている。","example_meaning":"Mũi con chó phập phồng khi đánh hơi.","examples":[{"example":"犬の鼻が、においを嗅いでひくひく動いている。","example_reading":"いぬのはなが、においをかいでひくひくうごいている。","example_meaning":"Mũi con chó phập phồng khi đánh hơi."},{"example":"疲れがたまって、まぶたがひくひくする。","example_reading":"つかれがたまって、まぶたがひくひくする。","example_meaning":"Mệt mỏi tích tụ khiến mí mắt tôi giật giật."}],"level":"b1"},
{"word":"まじまじ","reading":"まじまじ","meaning":"chằm chằm, nhìn kỹ","antonym":"ちらっと: liếc qua / ちらちら: liếc nhìn","note":"Hay đi với と, 見る, 見つめる. Nhìn không rời, thường vì ngạc nhiên.","example":"彼は私の顔を、まじまじと見つめていた。","example_reading":"かれはわたしのかおを、まじまじとみつめていた。","example_meaning":"Anh ấy nhìn chằm chằm vào mặt tôi.","examples":[{"example":"彼は私の顔を、まじまじと見つめていた。","example_reading":"かれはわたしのかおを、まじまじとみつめていた。","example_meaning":"Anh ấy nhìn chằm chằm vào mặt tôi."},{"example":"久しぶりに会った友人を、まじまじと見てしまった。","example_reading":"ひさしぶりにあったゆうじんを、まじまじとみてしまった。","example_meaning":"Tôi bất giác nhìn chăm chăm người bạn lâu ngày mới gặp."}],"level":"b1"},
{"word":"うつらうつら","reading":"うつらうつら","meaning":"gà gật, lơ mơ","antonym":"ぐっすり: ngủ say / ぱっちり: tỉnh hẳn","note":"Hay đi với と, 居眠りする, する. Nửa tỉnh nửa ngủ.","example":"電車の中で、うつらうつらと居眠りをしてしまった。","example_reading":"でんしゃのなかで、うつらうつらといねむりをしてしまった。","example_meaning":"Trên tàu, tôi gà gật ngủ quên.","examples":[{"example":"電車の中で、うつらうつらと居眠りをしてしまった。","example_reading":"でんしゃのなかで、うつらうつらといねむりをしてしまった。","example_meaning":"Trên tàu, tôi gà gật ngủ quên."},{"example":"午後の授業では、つい眠くてうつらうつらしてしまう。","example_reading":"ごごのじゅぎょうでは、ついねむくてうつらうつらしてしまう。","example_meaning":"Giờ học buổi chiều tôi buồn ngủ nên hay gà gật."}],"level":"b1"},
{"word":"けろっと","reading":"けろっと","meaning":"thản nhiên như không","antonym":"びっくり: giật mình","note":"Hay đi với する. Không còn dấu vết của chuyện vừa xảy ra.","example":"あんなに怒っていたのに、彼はけろっとした顔をしている。","example_reading":"あんなにおこっていたのに、かれはけろっとしたかおをしている。","example_meaning":"Giận đến thế mà anh ấy lại tỉnh bơ như không.","examples":[{"example":"あんなに怒っていたのに、彼はけろっとした顔をしている。","example_reading":"あんなにおこっていたのに、かれはけろっとしたかおをしている。","example_meaning":"Giận đến thế mà anh ấy lại tỉnh bơ như không."},{"example":"転んでも、子どもはけろっと立ち上がった。","example_reading":"ころんでも、こどもはけろっとたちあがった。","example_meaning":"Ngã mà đứa bé vẫn đứng dậy như không có gì."}],"level":"b1"},
{"word":"じゅうじゅう","reading":"じゅうじゅう","meaning":"xèo xèo (nướng, rán)","note":"Hay đi với 焼ける, 焼く. Tiếng thịt cá nướng trên chảo, vỉ.","example":"鉄板の上でお肉がじゅうじゅう焼けている。","example_reading":"てっぱんのうえでおにくがじゅうじゅうやけている。","example_meaning":"Thịt đang xèo xèo trên vỉ sắt nướng.","examples":[{"example":"鉄板の上でお肉がじゅうじゅう焼けている。","example_reading":"てっぱんのうえでおにくがじゅうじゅうやけている。","example_meaning":"Thịt đang xèo xèo trên vỉ sắt nướng."},{"example":"ステーキがじゅうじゅう音を立てて運ばれてきた。","example_reading":"ステーキがじゅうじゅうおとをたててはこばれてきた。","example_meaning":"Miếng bít tết được bưng ra, còn kêu xèo xèo."}],"level":"b1"},
{"word":"つるん","reading":"つるん","meaning":"trơn láng, tuột vào miệng","note":"Hay đi với と, 食べる, した肌. Mượt, dễ trôi.","example":"このゼリーは、つるんと喉を通って食べやすい。","example_reading":"このゼリーは、つるんとのどをとおってたべやすい。","example_meaning":"Thạch này trôi tuột qua họng nên dễ ăn.","examples":[{"example":"このゼリーは、つるんと喉を通って食べやすい。","example_reading":"このゼリーは、つるんとのどをとおってたべやすい。","example_meaning":"Thạch này trôi tuột qua họng nên dễ ăn."},{"example":"つるんとした肌を保つために、毎日スキンケアをしている。","example_reading":"つるんとしたはだをたもつために、まいにちスキンケアをしている。","example_meaning":"Để giữ làn da mịn láng, tôi chăm sóc da mỗi ngày."}],"level":"b1"},
{"word":"もちっと","reading":"もちっと","meaning":"dẻo dai (mochi)","note":"Hay đi với した食感. Độ dẻo mềm khi nhai.","example":"この餅は、もちっとした食感がたまらない。","example_reading":"このもちは、もちっとしたしょっかんがたまらない。","example_meaning":"Bánh mochi này có độ dẻo dai không thể cưỡng.","examples":[{"example":"この餅は、もちっとした食感がたまらない。","example_reading":"このもちは、もちっとしたしょっかんがたまらない。","example_meaning":"Bánh mochi này có độ dẻo dai không thể cưỡng."},{"example":"生地をこねて、もちっと弾力のあるパンに仕上げた。","example_reading":"きじをこねて、もちっとだんりょくのあるパンにしあげた。","example_meaning":"Tôi nhào bột để làm ra ổ bánh mì dẻo đàn hồi."}],"level":"b1"},
{"word":"かぷっと","reading":"かぷっと","meaning":"cắn khẽ, ngoạm nhẹ","note":"Hay đi với かむ, くわえる. Cắn nhẹ, đáng yêu.","example":"子犬が、私の指をかぷっとかんだ。","example_reading":"こいぬが、わたしのゆびをかぷっとかんだ。","example_meaning":"Chú chó con cắn nhẹ ngón tay tôi.","examples":[{"example":"子犬が、私の指をかぷっとかんだ。","example_reading":"こいぬが、わたしのゆびをかぷっとかんだ。","example_meaning":"Chú chó con cắn nhẹ ngón tay tôi."},{"example":"赤ちゃんが、おもちゃをかぷっとくわえた。","example_reading":"あかちゃんが、おもちゃをかぷっとくわえた。","example_meaning":"Em bé ngậm gọn món đồ chơi."}],"level":"b1"},
{"word":"めそめそ","reading":"めそめそ","meaning":"sụt sùi, thút thít","note":"Hay đi với 泣く, する. Khóc yếu đuối, nhỏ tiếng.","antonym":"にこにこ: tươi cười","example":"いつまでもめそめそしていないで、前を向こう。","example_reading":"いつまでもめそめそしていないで、まえをむこう。","example_meaning":"Đừng sụt sùi mãi, hãy hướng về phía trước.","examples":[{"example":"いつまでもめそめそしていないで、前を向こう。","example_reading":"いつまでもめそめそしていないで、まえをむこう。","example_meaning":"Đừng sụt sùi mãi, hãy hướng về phía trước."},{"example":"転んだ子どもが、めそめそ泣いている。","example_reading":"ころんだこどもが、めそめそないている。","example_meaning":"Đứa bé bị ngã đang thút thít khóc."}],"level":"b1"},
{"word":"しくしく","reading":"しくしく","meaning":"sụt sùi, thút thít; đau âm ỉ","antonym":"げらげら: cười ha hả","note":"Từ tượng thanh/hình. Khóc nhỏ hoặc đau âm ỉ.","example":"子供がしくしく泣いている。","example_reading":"こどもがしくしくないている。","example_meaning":"Đứa bé đang khóc thút thít.","examples":[{"example":"子供がしくしく泣いている。","example_reading":"こどもがしくしくないている。","example_meaning":"Đứa bé đang khóc thút thít."},{"example":"夜中からお腹がしくしく痛む。","example_reading":"よなかからおなかがしくしくいたむ。","example_meaning":"Từ nửa đêm bụng tôi đau âm ỉ."}],"level":"b1"},
{"word":"どさっと","reading":"どさっと","meaning":"rơi bịch (vật nặng)","antonym":"そっと: nhẹ nhàng","note":"Hay đi với 落ちる, 置く, 倒れる. Vật nặng, mềm rơi xuống thành tiếng nặng.","example":"屋根から雪がどさっと落ちてきた。","example_reading":"やねからゆきがどさっとおちてきた。","example_meaning":"Tuyết từ mái nhà rơi bịch xuống.","examples":[{"example":"屋根から雪がどさっと落ちてきた。","example_reading":"やねからゆきがどさっとおちてきた。","example_meaning":"Tuyết từ mái nhà rơi bịch xuống."},{"example":"帰宅すると、重いかばんをどさっと床に置いた。","example_reading":"きたくすると、おもいかばんをどさっとゆかにおいた。","example_meaning":"Về nhà, tôi quẳng cái cặp nặng xuống sàn đánh bịch."}],"level":"b1"},
{"word":"ぴんと","reading":"ぴんと","meaning":"thẳng căng; chợt hiểu ra","antonym":"だらりと: rũ xuống / くしゃくしゃ: nhàu nát / ぐにゃぐにゃ: mềm oặt","note":"Hay đi với 張る, 伸ばす, 来る. Căng thẳng hoặc linh cảm bật ra.","example":"ロープをぴんと張って、テントを立てた。","example_reading":"ロープをぴんとはって、テントをたてた。","example_meaning":"Căng thẳng sợi dây rồi dựng lều.","examples":[{"example":"ロープをぴんと張って、テントを立てた。","example_reading":"ロープをぴんとはって、テントをたてた。","example_meaning":"Căng thẳng sợi dây rồi dựng lều."},{"example":"彼の話を聞いても、どうもぴんとこなかった。","example_reading":"かれのはなしをきいても、どうもぴんとこなかった。","example_meaning":"Nghe anh ấy kể mà tôi vẫn không thấy thấm."}],"level":"b1"},
{"word":"ばっちり","reading":"ばっちり","meaning":"hoàn hảo, đâu ra đó","note":"Hay đi với 決まる, 準備する, 合う. Khẩu ngữ, kết quả rất tốt.","example":"準備はばっちりだから、安心して。","example_reading":"じゅんびはばっちりだから、あんしんして。","example_meaning":"Chuẩn bị đâu ra đó rồi, yên tâm nhé.","examples":[{"example":"準備はばっちりだから、安心して。","example_reading":"じゅんびはばっちりだから、あんしんして。","example_meaning":"Chuẩn bị đâu ra đó rồi, yên tâm nhé."},{"example":"今日の髪型はばっちり決まった。","example_reading":"きょうのかみがたはばっちりきまった。","example_meaning":"Kiểu tóc hôm nay lên rất chuẩn."}],"level":"b1"},
{"word":"ぴったり","reading":"ぴったり","meaning":"vừa khít, vừa vặn, đúng y","antonym":"ぶかぶか: rộng thùng thình / だぶだぶ: rộng thùng thình / ゆるゆる: lỏng lẻo","note":"Từ tượng hình. Dùng cho kích cỡ, thời gian, sự phù hợp.","example":"この服はサイズがぴったりです。","example_reading":"このふくはサイズがぴったりです。","example_meaning":"Bộ đồ này vừa khít cỡ của tôi.","examples":[{"example":"この服はサイズがぴったりです。","example_reading":"このふくはサイズがぴったりです。","example_meaning":"Bộ đồ này vừa khít cỡ của tôi."},{"example":"ぴったり九時に、電車が到着した。","example_reading":"ぴったりくじに、でんしゃがとうちゃくした。","example_meaning":"Đúng chín giờ, tàu đã đến nơi."}],"level":"b1"},
{"word":"くっきり","reading":"くっきり","meaning":"rõ nét, rõ mồn một","antonym":"ぼんやり: mờ mờ / うっすら: mờ mờ","note":"Từ tượng hình. Hình dáng, đường nét hiện rõ.","example":"今日は富士山がくっきり見えます。","example_reading":"きょうはふじさんがくっきりみえます。","example_meaning":"Hôm nay nhìn thấy núi Phú Sĩ rất rõ.","examples":[{"example":"今日は富士山がくっきり見えます。","example_reading":"きょうはふじさんがくっきりみえます。","example_meaning":"Hôm nay nhìn thấy núi Phú Sĩ rất rõ."},{"example":"雪の上に、足跡がくっきり残っている。","example_reading":"ゆきのうえに、あしあとがくっきりのこっている。","example_meaning":"Dấu chân in rõ nét trên tuyết."}],"level":"b1"},
{"word":"にたにた","reading":"にたにた","meaning":"cười mỉm khó chịu, nhếch mép","note":"Hay đi với 笑う. Sắc thái kỳ quái, khó chịu.","example":"男はにたにた笑いながら、こちらを見ていた。","example_reading":"おとこはにたにたわらいながら、こちらをみていた。","example_meaning":"Người đàn ông vừa cười nhếch mép vừa nhìn về phía này.","examples":[{"example":"男はにたにた笑いながら、こちらを見ていた。","example_reading":"おとこはにたにたわらいながら、こちらをみていた。","example_meaning":"Người đàn ông vừa cười nhếch mép vừa nhìn về phía này."},{"example":"彼は一人でスマホを見て、にたにたしている。","example_reading":"かれはひとりでスマホをみて、にたにたしている。","example_meaning":"Anh ta ngồi một mình xem điện thoại rồi cười tủm tỉm."}],"level":"b1"},
{"word":"にんまり","reading":"にんまり","meaning":"cười tủm tỉm hài lòng","note":"Hay đi với 笑う, する. Cười kín đáo vì vui, hài lòng.","example":"宝くじが当たって、彼はにんまりと笑った。","example_reading":"たからくじがあたって、かれはにんまりとわらった。","example_meaning":"Trúng xổ số, anh ấy cười tủm tỉm.","examples":[{"example":"宝くじが当たって、彼はにんまりと笑った。","example_reading":"たからくじがあたって、かれはにんまりとわらった。","example_meaning":"Trúng xổ số, anh ấy cười tủm tỉm."},{"example":"褒められた弟は、にんまりして部屋に戻った。","example_reading":"ほめられたおとうとは、にんまりしてへやにもどった。","example_meaning":"Được khen, em trai tôi cười tủm tỉm quay về phòng."}],"level":"b1"},
{"word":"ごにょごにょ","reading":"ごにょごにょ","meaning":"lúng búng, ấp úng","antonym":"はっきり: rõ ràng / はきはき: rành rọt","note":"Hay đi với 言う. Nói không rõ ràng vì ngại.","example":"理由を聞かれて、彼はごにょごにょと口ごもった。","example_reading":"りゆうをきかれて、かれはごにょごにょとくちごもった。","example_meaning":"Bị hỏi lý do, anh ấy ấp úng không nói rõ.","examples":[{"example":"理由を聞かれて、彼はごにょごにょと口ごもった。","example_reading":"りゆうをきかれて、かれはごにょごにょとくちごもった。","example_meaning":"Bị hỏi lý do, anh ấy ấp úng không nói rõ."},{"example":"何かごにょごにょ言っていたが、聞こえなかった。","example_reading":"なにかごにょごにょいっていたが、きこえなかった。","example_meaning":"Anh ta lầm bầm điều gì đó nhưng tôi không nghe được."}],"level":"b1"},
{"word":"ぱっくり","reading":"ぱっくり","meaning":"há hốc, toạc rộng","note":"Hay đi với 割れる, 開く. Nứt hoặc mở toạc to.","example":"転んで、膝がぱっくり割れてしまった。","example_reading":"ころんで、ひざがぱっくりわれてしまった。","example_meaning":"Tôi ngã, đầu gối bị rách toạc.","examples":[{"example":"転んで、膝がぱっくり割れてしまった。","example_reading":"ころんで、ひざがぱっくりわれてしまった。","example_meaning":"Tôi ngã, đầu gối bị rách toạc."},{"example":"地震で地面がぱっくりと裂けた。","example_reading":"じしんでじめんがぱっくりとさけた。","example_meaning":"Động đất làm mặt đất nứt toác."}],"level":"b1"},
{"word":"きっぱり","reading":"きっぱり","meaning":"dứt khoát, thẳng thừng","antonym":"ずるずる: kéo dài mãi / うじうじ: ấp úng","note":"Hay đi với 断る, 言う, やめる. Thái độ rõ ràng, không do dự.","example":"彼はその誘いをきっぱり断った。","example_reading":"かれはそのさそいをきっぱりことわった。","example_meaning":"Anh ấy từ chối thẳng thừng lời mời đó.","examples":[{"example":"彼はその誘いをきっぱり断った。","example_reading":"かれはそのさそいをきっぱりことわった。","example_meaning":"Anh ấy từ chối thẳng thừng lời mời đó."},{"example":"タバコはきっぱりやめることにした。","example_reading":"タバコはきっぱりやめることにした。","example_meaning":"Tôi đã quyết dứt khoát bỏ thuốc lá."}],"level":"b1"},
{"word":"あっさり","reading":"あっさり","meaning":"đơn giản, dễ dàng; nhạt thanh","antonym":"こってり: đậm đà béo ngậy / こく: vị đậm đà / なかなか: mãi mà","note":"Làm việc gì nhẹ nhàng không do dự, hoặc vị thanh đạm. Hay đi với 認める, 断る, 味.","example":"彼は自分のミスをあっさり認めた。","example_reading":"かれはじぶんのミスをあっさりみとめた。","example_meaning":"Anh ấy dễ dàng thừa nhận lỗi của mình.","examples":[{"example":"彼は自分のミスをあっさり認めた。","example_reading":"かれはじぶんのミスをあっさりみとめた。","example_meaning":"Anh ấy dễ dàng thừa nhận lỗi của mình."},{"example":"夏は、あっさりした味のものが食べたくなる。","example_reading":"なつは、あっさりしたあじのものがたべたくなる。","example_meaning":"Mùa hè tôi muốn ăn đồ vị thanh đạm."}],"level":"b1"},
{"word":"すうすう","reading":"すうすう","meaning":"thở đều (khi ngủ); gió lùa lạnh","note":"Hay đi với 寝息, 息, 風. Hơi thở nhẹ đều; cũng cảm giác gió lạnh lùa vào.","example":"赤ちゃんはすうすうと寝息を立てて眠っている。","example_reading":"あかちゃんはすうすうとねいきをたててねむっている。","example_meaning":"Em bé ngủ thở đều đều.","examples":[{"example":"赤ちゃんはすうすうと寝息を立てて眠っている。","example_reading":"あかちゃんはすうすうとねいきをたててねむっている。","example_meaning":"Em bé ngủ thở đều đều."},{"example":"首元がすうすうして寒いので、マフラーを巻いた。","example_reading":"くびもとがすうすうしてさむいので、マフラーをまいた。","example_meaning":"Cổ lạnh gió lùa nên tôi quàng khăn."}],"level":"b1"},
{"word":"ちゅうちゅう","reading":"ちゅうちゅう","meaning":"hút chùn chụt; chít chít","note":"Hay đi với 吸う, 鳴く. Hút bằng miệng; tiếng chuột kêu.","example":"赤ちゃんがミルクをちゅうちゅう吸っている。","example_reading":"あかちゃんがミルクをちゅうちゅうすっている。","example_meaning":"Em bé đang bú sữa chùn chụt.","examples":[{"example":"赤ちゃんがミルクをちゅうちゅう吸っている。","example_reading":"あかちゃんがミルクをちゅうちゅうすっている。","example_meaning":"Em bé đang bú sữa chùn chụt."},{"example":"屋根裏で、ネズミがちゅうちゅう鳴いている。","example_reading":"やねうらで、ネズミがちゅうちゅうないている。","example_meaning":"Trên gác mái, chuột kêu chít chít."}],"level":"b1"},
{"word":"ぷにぷに","reading":"ぷにぷに","meaning":"mềm mại, phúng phính","note":"Hay đi với 柔らかい, ほっぺ, 肉球.","example":"赤ちゃんのぷにぷにしたほっぺを、そっと触った。","example_reading":"あかちゃんのぷにぷにしたほっぺを、そっとさわった。","example_meaning":"Tôi khẽ sờ đôi má phúng phính của em bé.","examples":[{"example":"赤ちゃんのぷにぷにしたほっぺを、そっと触った。","example_reading":"あかちゃんのぷにぷにしたほっぺを、そっとさわった。","example_meaning":"Tôi khẽ sờ đôi má phúng phính của em bé."},{"example":"この猫の肉球は、ぷにぷにして気持ちいい。","example_reading":"このねこのにくきゅうは、ぷにぷにしてきもちいい。","example_meaning":"Đệm thịt chân con mèo này mềm mại, sờ rất thích."}],"level":"b1"},
{"word":"ゆさゆさ","reading":"ゆさゆさ","meaning":"lắc lư (vật nặng)","note":"Hay đi với 揺れる. Vật to nặng đung đưa.","example":"重い荷物を背負うと、体がゆさゆさと揺れる。","example_reading":"おもいにもつをせおうと、からだがゆさゆさとゆれる。","example_meaning":"Cõng hành lý nặng thì người cứ lắc lư.","examples":[{"example":"重い荷物を背負うと、体がゆさゆさと揺れる。","example_reading":"おもいにもつをせおうと、からだがゆさゆさとゆれる。","example_meaning":"Cõng hành lý nặng thì người cứ lắc lư."},{"example":"風で、大きな木の枝がゆさゆさと揺れていた。","example_reading":"かぜで、おおきなきのえだがゆさゆさとゆれていた。","example_meaning":"Cành cây to lắc lư trong gió."}],"level":"b1"},
{"word":"ずしん","reading":"ずしん","meaning":"rầm, nặng nề","antonym":"ふわり: nhẹ nhàng","note":"Hay đi với と, 揺れる, 響く. Tiếng vật rất nặng; cũng cảm giác nặng trong lòng.","example":"大きな音がして、家がずしんと揺れた。","example_reading":"おおきなおとがして、いえがずしんとゆれた。","example_meaning":"Có tiếng động lớn, ngôi nhà rung rầm lên.","examples":[{"example":"大きな音がして、家がずしんと揺れた。","example_reading":"おおきなおとがして、いえがずしんとゆれた。","example_meaning":"Có tiếng động lớn, ngôi nhà rung rầm lên."},{"example":"悪い知らせが、胸にずしんと響いた。","example_reading":"わるいしらせが、むねにずしんとひびいた。","example_meaning":"Tin xấu nặng nề đè lên lòng tôi."}],"level":"b1"},
{"word":"むしゃり","reading":"むしゃり","meaning":"nhai ngấu nghiến","note":"Hay đi với かじる, 食べる. Cắn nhai mạnh miệng.","example":"彼はパンをむしゃりとかじって、また歩き出した。","example_reading":"かれはパンをむしゃりとかじって、またあるきだした。","example_meaning":"Anh ấy cắn ngấu miếng bánh mì rồi lại bước đi.","examples":[{"example":"彼はパンをむしゃりとかじって、また歩き出した。","example_reading":"かれはパンをむしゃりとかじって、またあるきだした。","example_meaning":"Anh ấy cắn ngấu miếng bánh mì rồi lại bước đi."},{"example":"サルが、バナナをむしゃりと食べた。","example_reading":"サルが、バナナをむしゃりとたべた。","example_meaning":"Con khỉ ăn ngấu chuối."}],"level":"b1"},
{"word":"むぎゅっと","reading":"むぎゅっと","meaning":"ôm chặt, ép sát","note":"Hay đi với 抱きしめる, 押される. Dùng lực siết mạnh.","example":"お母さんは、子どもをむぎゅっと抱きしめた。","example_reading":"おかあさんは、こどもをむぎゅっとだきしめた。","example_meaning":"Người mẹ ôm chặt đứa con vào lòng.","examples":[{"example":"お母さんは、子どもをむぎゅっと抱きしめた。","example_reading":"おかあさんは、こどもをむぎゅっとだきしめた。","example_meaning":"Người mẹ ôm chặt đứa con vào lòng."},{"example":"満員電車で、人にむぎゅっと押された。","example_reading":"まんいんでんしゃで、ひとにむぎゅっとおされた。","example_meaning":"Trên tàu đông nghẹt, tôi bị người ta ép chặt."}],"level":"b1"},
{"word":"ぶらんぶらん","reading":"ぶらんぶらん","meaning":"đung đưa lủng lẳng","note":"Hay đi với 揺れる, ぶら下がる. Vật treo đung đưa liên tục.","example":"ポケットの鍵が、歩くたびにぶらんぶらんと揺れる。","example_reading":"ポケットのかぎが、あるくたびにぶらんぶらんとゆれる。","example_meaning":"Chìa khóa trong túi đung đưa mỗi khi tôi bước.","examples":[{"example":"ポケットの鍵が、歩くたびにぶらんぶらんと揺れる。","example_reading":"ポケットのかぎが、あるくたびにぶらんぶらんとゆれる。","example_meaning":"Chìa khóa trong túi đung đưa mỗi khi tôi bước."},{"example":"彼は、木の枝にぶらんぶらんとぶら下がって遊んだ。","example_reading":"かれは、きのえだにぶらんぶらんとぶらさがってあそんだ。","example_meaning":"Anh ấy đu lủng lẳng trên cành cây để chơi."}],"level":"b1"},
{"word":"ぽちゃん","reading":"ぽちゃん","meaning":"tõm (rơi xuống nước)","note":"Hay đi với と, 落ちる, 飛び込む.","example":"池に石を投げると、ぽちゃんと音がした。","example_reading":"いけにいしをなげると、ぽちゃんとおとがした。","example_meaning":"Ném hòn đá xuống ao, nghe tiếng tõm.","examples":[{"example":"池に石を投げると、ぽちゃんと音がした。","example_reading":"いけにいしをなげると、ぽちゃんとおとがした。","example_meaning":"Ném hòn đá xuống ao, nghe tiếng tõm."},{"example":"カエルが、ぽちゃんと水に飛び込んだ。","example_reading":"カエルが、ぽちゃんとみずにとびこんだ。","example_meaning":"Con ếch nhảy tõm xuống nước."}],"level":"b1"},
{"word":"ぼたぼた","reading":"ぼたぼた","meaning":"nhỏ giọt to","note":"Hay đi với 垂れる, 落ちる. Giọt lớn rơi liên tiếp.","example":"傷口から、血がぼたぼたと垂れた。","example_reading":"きずぐちから、ちがぼたぼたとたれた。","example_meaning":"Máu nhỏ từng giọt lớn từ vết thương.","examples":[{"example":"傷口から、血がぼたぼたと垂れた。","example_reading":"きずぐちから、ちがぼたぼたとたれた。","example_meaning":"Máu nhỏ từng giọt lớn từ vết thương."},{"example":"雨漏りで、天井から水がぼたぼた落ちてくる。","example_reading":"あまもりで、てんじょうからみずがぼたぼたおちてくる。","example_meaning":"Mái dột nên nước rơi từng giọt lớn từ trần nhà."}],"level":"b1"},
{"word":"ぐびぐび","reading":"ぐびぐび","meaning":"tu ừng ực","note":"Hay đi với 飲む, 飲み干す. Uống nhanh, liên tục thành tiếng.","example":"彼は冷えたビールをぐびぐび飲み干した。","example_reading":"かれはひえたビールをぐびぐびのみほした。","example_meaning":"Anh ta tu ừng ực hết cốc bia lạnh.","examples":[{"example":"彼は冷えたビールをぐびぐび飲み干した。","example_reading":"かれはひえたビールをぐびぐびのみほした。","example_meaning":"Anh ta tu ừng ực hết cốc bia lạnh."},{"example":"のどが渇いていたので、水をぐびぐび飲んだ。","example_reading":"のどがかわいていたので、みずをぐびぐびのんだ。","example_meaning":"Khát nên tôi uống nước ừng ực."}],"level":"b1"},
{"word":"こってり","reading":"こってり","meaning":"đậm đà, béo ngậy","note":"Vị đậm, nhiều dầu mỡ. Cũng dùng trong こってり絞られる (bị mắng kỹ). Hay đi với ラーメン, 味.","antonym":"あっさり: thanh đạm","example":"こってりしたラーメンは、おいしいが食べすぎると胃にもたれる。","example_reading":"こってりしたラーメンは、おいしいがたべすぎるといにもたれる。","example_meaning":"Ramen đậm đà tuy ngon nhưng ăn nhiều thì nặng bụng.","examples":[{"example":"こってりしたラーメンは、おいしいが食べすぎると胃にもたれる。","example_reading":"こってりしたラーメンは、おいしいがたべすぎるといにもたれる。","example_meaning":"Ramen đậm đà tuy ngon nhưng ăn nhiều thì nặng bụng."},{"example":"遅刻して、先生にこってり叱られた。","example_reading":"ちこくして、せんせいにこってりしかられた。","example_meaning":"Tôi đi muộn nên bị thầy mắng một trận ra trò."}],"level":"b1"},
{"word":"すんなり","reading":"すんなり","meaning":"suôn sẻ, thuận lợi","antonym":"なかなか: mãi mà (không) / ぎくしゃく: gượng gạo","note":"Diễn ra trơn tru, không trở ngại. Hay đi với 決まる, 通る, 受け入れる.","example":"会議で、私の案はすんなり通った。","example_reading":"かいぎで、わたしのあんはすんなりとおった。","example_meaning":"Trong cuộc họp, đề xuất của tôi được thông qua suôn sẻ.","examples":[{"example":"会議で、私の案はすんなり通った。","example_reading":"かいぎで、わたしのあんはすんなりとおった。","example_meaning":"Trong cuộc họp, đề xuất của tôi được thông qua suôn sẻ."},{"example":"彼はすんなりと負けを認めなかった。","example_reading":"かれはすんなりとまけをみとめなかった。","example_meaning":"Anh ta không dễ dàng thừa nhận thua."}],"level":"b1"},
{"word":"ふさふさ","reading":"ふさふさ","meaning":"rậm, dày và mượt (lông, tóc)","note":"Hay đi với 髪, 毛, しっぽ.","example":"祖父は年を取っても髪がふさふさだ。","example_reading":"そふはとしをとってもかみがふさふさだ。","example_meaning":"Ông tôi dù lớn tuổi tóc vẫn dày rậm.","examples":[{"example":"祖父は年を取っても髪がふさふさだ。","example_reading":"そふはとしをとってもかみがふさふさだ。","example_meaning":"Ông tôi dù lớn tuổi tóc vẫn dày rậm."},{"example":"その犬はふさふさしたしっぽを振っている。","example_reading":"そのいぬはふさふさしたしっぽをふっている。","example_meaning":"Con chó đó đang vẫy cái đuôi xù."}],"level":"b1"},
{"word":"ふかふか","reading":"ふかふか","meaning":"mềm xốp, êm ái","note":"Từ tượng hình. Dùng cho chăn, nệm, bánh mì.","antonym":"かちかち: cứng ngắc / ごわごわ: cứng","example":"ふかふかの布団で寝たい。","example_reading":"ふかふかのふとんでねたい。","example_meaning":"Tôi muốn ngủ trên chiếc nệm êm ái.","examples":[{"example":"ふかふかの布団で寝たい。","example_reading":"ふかふかのふとんでねたい。","example_meaning":"Tôi muốn ngủ trên chiếc nệm êm ái."},{"example":"新しい靴下は、ふかふかで温かい。","example_reading":"あたらしいくつしたは、ふかふかであたたかい。","example_meaning":"Đôi tất mới mềm xốp và ấm."}],"level":"b1"},
{"word":"ねちねち","reading":"ねちねち","meaning":"dai dẳng, lải nhải, dây dưa","antonym":"さっぱり: dứt khoát / あっさり: nhẹ nhàng, dễ dàng / さばさば: sảng khoái","note":"Hay đi với 言う, 責める, 文句. Sắc thái khó chịu. Cũng nghĩa \"dính nhớp\".","example":"上司は小さなミスをねちねち責め続けた。","example_reading":"じょうしはちいさなミスをねちねちせめつづけた。","example_meaning":"Sếp cứ dai dẳng trách mắng cái lỗi nhỏ.","examples":[{"example":"上司は小さなミスをねちねち責め続けた。","example_reading":"じょうしはちいさなミスをねちねちせめつづけた。","example_meaning":"Sếp cứ dai dẳng trách mắng cái lỗi nhỏ."},{"example":"姑にねちねちと嫌味を言われて、疲れてしまった。","example_reading":"しゅうとめにねちねちといやみをいわれて、つかれてしまった。","example_meaning":"Bị mẹ chồng lải nhải mỉa mai, tôi mệt mỏi quá."}],"level":"b1"},
{"word":"とろとろ","reading":"とろとろ","meaning":"sệt mềm, nhừ","antonym":"かちかち: cứng ngắc / さらさら: khô ráo","note":"Hay đi với 煮る, 溶ける, 卵. Đặc mềm, chảy nhẹ.","example":"とろとろのチーズがパンに乗っている。","example_reading":"とろとろのチーズがパンにのっている。","example_meaning":"Phô mai chảy sệt phủ trên bánh mì.","examples":[{"example":"とろとろのチーズがパンに乗っている。","example_reading":"とろとろのチーズがパンにのっている。","example_meaning":"Phô mai chảy sệt phủ trên bánh mì."},{"example":"肉を弱火でとろとろになるまで煮込んだ。","example_reading":"にくをよわびでとろとろになるまでにこんだ。","example_meaning":"Tôi ninh thịt lửa nhỏ đến khi nhừ."}],"level":"b1"},
{"word":"もちもち","reading":"もちもち","meaning":"dẻo dai, mềm dẻo","antonym":"ぱさぱさ: khô xơ / さくさく: giòn tan","note":"Từ tượng hình. Kết cấu dẻo như bánh gạo, mì udon.","example":"このうどんはもちもちしておいしい。","example_reading":"このうどんはもちもちしておいしい。","example_meaning":"Mì udon này dẻo dai và ngon.","examples":[{"example":"このうどんはもちもちしておいしい。","example_reading":"このうどんはもちもちしておいしい。","example_meaning":"Mì udon này dẻo dai và ngon."},{"example":"焼きたてのパンは、中がもちもちしている。","example_reading":"やきたてのパンは、なかがもちもちしている。","example_meaning":"Bánh mì mới nướng có ruột dẻo dai."}],"level":"b1"},
{"word":"さくさく","reading":"さくさく","meaning":"giòn tan, xốp giòn","antonym":"しっとり: ẩm mềm / もちもち: dẻo dai","note":"Từ tượng thanh/hình. Dùng cho tempura, bánh quy.","example":"揚げたての天ぷらはさくさくです。","example_reading":"あげたてのてんぷらはさくさくです。","example_meaning":"Tempura mới chiên giòn tan.","examples":[{"example":"揚げたての天ぷらはさくさくです。","example_reading":"あげたてのてんぷらはさくさくです。","example_meaning":"Tempura mới chiên giòn tan."},{"example":"このクッキーは、さくさくして食べやすい。","example_reading":"このクッキーは、さくさくしてたべやすい。","example_meaning":"Bánh quy này giòn xốp, dễ ăn."}],"level":"b1"},
{"word":"さばさば","reading":"さばさば","meaning":"sảng khoái, thẳng thắn, dứt khoát","antonym":"ねちねち: dai dẳng / くよくよ: buồn phiền","note":"Hay đi với する, した性格. Tính cách phóng khoáng, không dây dưa; cũng chỉ cảm giác nhẹ nhõm.","example":"彼女はさばさばした性格で、誰とでもすぐ仲良くなる。","example_reading":"かのじょはさばさばしたせいかくで、だれとでもすぐなかよくなる。","example_meaning":"Cô ấy tính thẳng thắn nên ai cũng nhanh chóng thân.","examples":[{"example":"彼女はさばさばした性格で、誰とでもすぐ仲良くなる。","example_reading":"かのじょはさばさばしたせいかくで、だれとでもすぐなかよくなる。","example_meaning":"Cô ấy tính thẳng thắn nên ai cũng nhanh chóng thân."},{"example":"悩んでいたことを全部話したら、さばさばした気分になった。","example_reading":"なやんでいたことをぜんぶはなしたら、さばさばしたきぶんになった。","example_meaning":"Nói hết những điều bận tâm ra, tôi thấy nhẹ nhõm."}],"level":"b1"},
{"word":"ぱりぱり","reading":"ぱりぱり","meaning":"giòn rụm","antonym":"しっとり: ẩm mềm / しなしな: héo rũ","note":"Độ giòn của đồ ăn nướng, chiên. Hay đi với 焼く, 揚げる, 皮.","example":"この鶏肉は、皮がぱりぱりに焼けている。","example_reading":"このけいにくは、かわがぱりぱりにやけている。","example_meaning":"Thịt gà này da nướng giòn rụm.","examples":[{"example":"この鶏肉は、皮がぱりぱりに焼けている。","example_reading":"このけいにくは、かわがぱりぱりにやけている。","example_meaning":"Thịt gà này da nướng giòn rụm."},{"example":"ぱりぱりのせんべいを食べながら、お茶を飲んだ。","example_reading":"ぱりぱりのせんべいをたべながら、おちゃをのんだ。","example_meaning":"Tôi vừa ăn bánh senbei giòn rụm vừa uống trà."}],"level":"b1"},
{"word":"かちかち","reading":"かちかち","meaning":"cứng ngắc","note":"Cứng như đá, hoặc căng thẳng cứng người. Hay đi với 凍る, 緊張, 頭.","antonym":"ふかふか: mềm xốp / ふんわり: mềm xốp / ぐにゃぐにゃ: mềm oặt","example":"冷凍庫に入れておいたパンが、かちかちになった。","example_reading":"れいとうこにいれておいたパンが、かちかちになった。","example_meaning":"Cái bánh mì để trong ngăn đá đã cứng ngắc.","examples":[{"example":"冷凍庫に入れておいたパンが、かちかちになった。","example_reading":"れいとうこにいれておいたパンが、かちかちになった。","example_meaning":"Cái bánh mì để trong ngăn đá đã cứng ngắc."},{"example":"面接の前で、緊張して体がかちかちだ。","example_reading":"めんせつのまえで、きんちょうしてからだがかちかちだ。","example_meaning":"Sắp phỏng vấn nên tôi căng thẳng cứng cả người."}],"level":"b1"},
{"word":"ぱんぱん","reading":"ぱんぱん","meaning":"căng phồng, căng cứng","note":"Hay đi với 膨らむ, 詰まる, お腹, 予定. Chứa đầy đến mức căng.","antonym":"がらがら: vắng tanh","example":"かばんに荷物を詰めすぎて、ぱんぱんになった。","example_reading":"かばんににもつをつめすぎて、ぱんぱんになった。","example_meaning":"Nhét đồ quá nhiều nên cặp căng phồng.","examples":[{"example":"かばんに荷物を詰めすぎて、ぱんぱんになった。","example_reading":"かばんににもつをつめすぎて、ぱんぱんになった。","example_meaning":"Nhét đồ quá nhiều nên cặp căng phồng."},{"example":"今週は予定がぱんぱんで、休む暇がない。","example_reading":"こんしゅうはよていがぱんぱんで、やすむひまがない。","example_meaning":"Tuần này lịch kín mít, không có thời gian nghỉ."}],"level":"b1"},
{"word":"たっぷり","reading":"たっぷり","meaning":"đầy đặn, dồi dào","antonym":"わずかに: một chút ít / ちょっぴり: chút xíu","note":"Hay đi với 入れる, 使う, 寝る, 時間. Nhiều và dư dả.","example":"野菜をたっぷり入れてスープを作った。","example_reading":"やさいをたっぷりいれてスープをつくった。","example_meaning":"Tôi nấu súp với thật nhiều rau.","examples":[{"example":"野菜をたっぷり入れてスープを作った。","example_reading":"やさいをたっぷりいれてスープをつくった。","example_meaning":"Tôi nấu súp với thật nhiều rau."},{"example":"時間はたっぷりあるから、急がなくていい。","example_reading":"じかんはたっぷりあるから、いそがなくていい。","example_meaning":"Thời gian còn dư dả nên không cần vội."}],"level":"b1"},
{"word":"ぎゅうぎゅう","reading":"ぎゅうぎゅう","meaning":"chen chúc, ních chặt","note":"Hay đi với 詰める, 押す, 満員電車. Chật cứng, nén chặt.","antonym":"がらがら: vắng tanh / ゆったり: thong thả / ゆるゆる: lỏng lẻo","example":"朝の電車はぎゅうぎゅうで、動けなかった。","example_reading":"あさのでんしゃはぎゅうぎゅうで、うごけなかった。","example_meaning":"Tàu buổi sáng chen chúc, không nhúc nhích được.","examples":[{"example":"朝の電車はぎゅうぎゅうで、動けなかった。","example_reading":"あさのでんしゃはぎゅうぎゅうで、うごけなかった。","example_meaning":"Tàu buổi sáng chen chúc, không nhúc nhích được."},{"example":"スーツケースに服をぎゅうぎゅう詰め込んだ。","example_reading":"スーツケースにふくをぎゅうぎゅうつめこんだ。","example_meaning":"Tôi nhét quần áo chật cứng vào vali."}],"level":"b1"},
{"word":"ぎっしり","reading":"ぎっしり","meaning":"chật cứng, kín mít","note":"Chứa đầy không còn khe hở. Hay đi với 詰まる, 並ぶ, 予定が入る.","antonym":"がらがら: vắng tanh / ちらほら: lác đác","example":"スーツケースには、お土産がぎっしり詰まっていた。","example_reading":"スーツケースには、おみやげがぎっしりつまっていた。","example_meaning":"Va li chật cứng quà lưu niệm.","examples":[{"example":"スーツケースには、お土産がぎっしり詰まっていた。","example_reading":"スーツケースには、おみやげがぎっしりつまっていた。","example_meaning":"Va li chật cứng quà lưu niệm."},{"example":"来週は、会議の予定がぎっしり入っている。","example_reading":"らいしゅうは、かいぎのよていがぎっしりはいっている。","example_meaning":"Tuần sau lịch họp kín mít."}],"level":"b1"},
{"word":"ごうごう","reading":"ごうごう","meaning":"ầm ầm (gió, lửa, thác)","note":"Hay đi với 風, 燃える, 流れる. Tiếng lớn, dữ dội.","example":"台風の夜、風がごうごうと音を立てていた。","example_reading":"たいふうのよる、かぜがごうごうとおとをたてていた。","example_meaning":"Đêm bão, gió gào ầm ầm.","examples":[{"example":"台風の夜、風がごうごうと音を立てていた。","example_reading":"たいふうのよる、かぜがごうごうとおとをたてていた。","example_meaning":"Đêm bão, gió gào ầm ầm."},{"example":"山の火事は、ごうごうと燃え広がった。","example_reading":"やまのかじは、ごうごうともえひろがった。","example_meaning":"Đám cháy núi bùng lan dữ dội."}],"level":"b1"},
{"word":"むちむち","reading":"むちむち","meaning":"mũm mĩm, căng tròn","antonym":"ほっそり: mảnh mai / がりがり: gầy trơ xương","note":"Hay đi với 腕, 太もも. Cơ thể đầy đặn, săn.","example":"赤ちゃんの腕は、むちむちしてとてもかわいい。","example_reading":"あかちゃんのうでは、むちむちしてとてもかわいい。","example_meaning":"Cánh tay em bé mũm mĩm trông rất đáng yêu.","examples":[{"example":"赤ちゃんの腕は、むちむちしてとてもかわいい。","example_reading":"あかちゃんのうでは、むちむちしてとてもかわいい。","example_meaning":"Cánh tay em bé mũm mĩm trông rất đáng yêu."},{"example":"むちむちした太ももを隠すために、長いスカートをはいた。","example_reading":"むちむちしたふとももをかくすために、ながいスカートをはいた。","example_meaning":"Để che đôi đùi đầy đặn, cô ấy mặc váy dài."}],"level":"b1"},
{"word":"ぽってり","reading":"ぽってり","meaning":"dày, tròn đầy","antonym":"ほっそり: mảnh mai / すらっと: thon thả","note":"Hay đi với した唇, カップ. Dày dặn, đầy đặn.","example":"ぽってりした厚みのあるカップで、お茶を飲んだ。","example_reading":"ぽってりしたあつみのあるカップで、おちゃをのんだ。","example_meaning":"Tôi uống trà bằng chiếc cốc dày dặn tròn trịa.","examples":[{"example":"ぽってりした厚みのあるカップで、お茶を飲んだ。","example_reading":"ぽってりしたあつみのあるカップで、おちゃをのんだ。","example_meaning":"Tôi uống trà bằng chiếc cốc dày dặn tròn trịa."},{"example":"彼女はぽってりした唇に、赤い口紅を塗った。","example_reading":"かのじょはぽってりしたくちびるに、あかいくちべにをぬった。","example_meaning":"Cô ấy tô son đỏ lên đôi môi đầy đặn."}],"level":"b1"},
{"word":"ずんぐり","reading":"ずんぐり","meaning":"lùn mập, đậm người","antonym":"すらっと: thon thả / ほっそり: mảnh mai","note":"Hay đi với した体つき, 形. Thấp và to ngang.","example":"その人形は、ずんぐりした体つきが愛らしい。","example_reading":"そのにんぎょうは、ずんぐりしたからだつきがあいらしい。","example_meaning":"Con búp bê đó có dáng mập mạp thật đáng yêu.","examples":[{"example":"その人形は、ずんぐりした体つきが愛らしい。","example_reading":"そのにんぎょうは、ずんぐりしたからだつきがあいらしい。","example_meaning":"Con búp bê đó có dáng mập mạp thật đáng yêu."},{"example":"港には、ずんぐりした形の船が並んでいた。","example_reading":"みなとには、ずんぐりしたかたちのふねがならんでいた。","example_meaning":"Ở cảng có những chiếc thuyền hình dáng đậm người xếp hàng."}],"level":"b1"},
{"word":"たらたら","reading":"たらたら","meaning":"chảy ròng ròng; lải nhải","note":"Hay đi với 流れる, 言う. Chất lỏng chảy dài; hoặc than phiền kéo dài.","example":"暑くて、額から汗がたらたら流れた。","example_reading":"あつくて、ひたいからあせがたらたらながれた。","example_meaning":"Nóng quá, mồ hôi chảy ròng ròng từ trán.","examples":[{"example":"暑くて、額から汗がたらたら流れた。","example_reading":"あつくて、ひたいからあせがたらたらながれた。","example_meaning":"Nóng quá, mồ hôi chảy ròng ròng từ trán."},{"example":"彼は仕事の不満を、たらたら言い続けている。","example_reading":"かれはしごとのふまんを、たらたらいいつづけている。","example_meaning":"Anh ta cứ lải nhải mãi về nỗi bất mãn trong công việc."}],"level":"b1"},
{"word":"しれっと","reading":"しれっと","meaning":"tỉnh bơ","note":"Hay đi với する, 言う, 座る. Thản nhiên dù đáng ra phải áy náy.","example":"彼は遅刻したのに、しれっと席に座った。","example_reading":"かれはちこくしたのに、しれっとせきにすわった。","example_meaning":"Dù đến muộn, anh ta vẫn tỉnh bơ ngồi vào chỗ.","examples":[{"example":"彼は遅刻したのに、しれっと席に座った。","example_reading":"かれはちこくしたのに、しれっとせきにすわった。","example_meaning":"Dù đến muộn, anh ta vẫn tỉnh bơ ngồi vào chỗ."},{"example":"しれっと嘘をつく彼の態度に、腹が立った。","example_reading":"しれっとうそをつくかれのたいどに、はらがたった。","example_meaning":"Tôi tức vì thái độ nói dối mặt tỉnh bơ của anh ta."}],"level":"b1"},
{"word":"がぶがぶ","reading":"がぶがぶ","meaning":"uống ừng ực, nốc","antonym":"ちびちび: từng chút","note":"Hay đi với 飲む. Uống nhiều và nhanh.","example":"運動のあと、スポーツドリンクをがぶがぶ飲んだ。","example_reading":"うんどうのあと、スポーツドリンクをがぶがぶのんだ。","example_meaning":"Tập xong, tôi nốc ừng ực nước thể thao.","examples":[{"example":"運動のあと、スポーツドリンクをがぶがぶ飲んだ。","example_reading":"うんどうのあと、スポーツドリンクをがぶがぶのんだ。","example_meaning":"Tập xong, tôi nốc ừng ực nước thể thao."},{"example":"そんなに水をがぶがぶ飲むと、お腹を壊すよ。","example_reading":"そんなにみずをがぶがぶのむと、おなかをこわすよ。","example_meaning":"Uống nước ừng ực thế là đau bụng đấy."}],"level":"b1"},
{"word":"がたがた","reading":"がたがた","meaning":"rung lắc ầm ầm; run cầm cập","note":"Hay đi với 揺れる, 震える, 言う. Vật rung lắc, hoặc ca cẩm lằng nhằng.","example":"地震で、棚ががたがた揺れた。","example_reading":"じしんで、たなががたがたゆれた。","example_meaning":"Kệ rung lên ầm ầm vì động đất.","examples":[{"example":"地震で、棚ががたがた揺れた。","example_reading":"じしんで、たなががたがたゆれた。","example_meaning":"Kệ rung lên ầm ầm vì động đất."},{"example":"文句をがたがた言わないで、手伝ってよ。","example_reading":"もんくをがたがたいわないで、てつだってよ。","example_meaning":"Đừng ca cẩm nữa, giúp một tay đi."}],"level":"b1"},
{"word":"ぐらぐら","reading":"ぐらぐら","meaning":"lung lay, chao đảo, rung lắc","antonym":"しっかり: chắc chắn / どっしり: vững chãi","note":"Từ tượng hình. Dùng cho nhà cửa, răng, ghế không vững. Còn nghĩa sôi sùng sục: ぐらぐら煮える.","example":"地震で家がぐらぐら揺れた。","example_reading":"じしんでいえがぐらぐらゆれた。","example_meaning":"Động đất làm ngôi nhà rung lắc.","examples":[{"example":"地震で家がぐらぐら揺れた。","example_reading":"じしんでいえがぐらぐらゆれた。","example_meaning":"Động đất làm ngôi nhà rung lắc."},{"example":"歯がぐらぐらして、噛むと痛い。","example_reading":"はがぐらぐらして、かむといたい。","example_meaning":"Răng lung lay nên cắn là đau."}],"level":"b1"},
{"word":"ぱたぱた","reading":"ぱたぱた","meaning":"lạch bạch, vỗ phành phạch","note":"Hay đi với 走る, 扇ぐ, 音. Tiếng động nhẹ, nhịp liên tiếp.","example":"子どもがぱたぱたと廊下を走っていった。","example_reading":"こどもがぱたぱたとろうかをはしっていった。","example_meaning":"Đứa bé chạy lạch bạch dọc hành lang.","examples":[{"example":"子どもがぱたぱたと廊下を走っていった。","example_reading":"こどもがぱたぱたとろうかをはしっていった。","example_meaning":"Đứa bé chạy lạch bạch dọc hành lang."},{"example":"暑いので、うちわでぱたぱた扇いだ。","example_reading":"あついので、うちわでぱたぱたあおいだ。","example_meaning":"Nóng quá nên tôi phe phẩy quạt liên tục."}],"level":"b1"},
{"word":"あたふた","reading":"あたふた","meaning":"cuống cuồng, hớt hải","antonym":"落ち着いて（おちついて）: bình tĩnh","antonym_hanviet":"lạc trước","note":"Hay đi với する. Vội vàng vì không kịp hoặc bị bất ngờ.","example":"寝坊して、あたふたと家を出た。","example_reading":"ねぼうして、あたふたといえをでた。","example_meaning":"Ngủ quên nên tôi hớt hải ra khỏi nhà.","examples":[{"example":"寝坊して、あたふたと家を出た。","example_reading":"ねぼうして、あたふたといえをでた。","example_meaning":"Ngủ quên nên tôi hớt hải ra khỏi nhà."},{"example":"急な来客で、みんなあたふたした。","example_reading":"きゅうならいきゃくで、みんなあたふたした。","example_meaning":"Khách đến đột xuất, ai cũng cuống lên."}],"level":"b1"},
{"word":"ばたばた","reading":"ばたばた","meaning":"cuống quýt bận rộn; (tiếng) đập cánh, chạy huỳnh huỵch","antonym":"のんびり: thong thả","note":"Từ tượng thanh/hình. Hay đi với する, chỉ trạng thái bận rộn.","example":"朝はいつもばたばたしています。","example_reading":"あさはいつもばたばたしています。","example_meaning":"Buổi sáng tôi lúc nào cũng cuống quýt.","examples":[{"example":"朝はいつもばたばたしています。","example_reading":"あさはいつもばたばたしています。","example_meaning":"Buổi sáng tôi lúc nào cũng cuống quýt."},{"example":"廊下をばたばた走ってはいけません。","example_reading":"ろうかをばたばたはしってはいけません。","example_meaning":"Không được chạy huỳnh huỵch ngoài hành lang."}],"level":"b1"},
{"word":"てきぱき","reading":"てきぱき","meaning":"nhanh nhẹn, gọn gàng","note":"Làm việc nhanh và hiệu quả. Hay đi với 働く, 片づける, こなす.","antonym":"のろのろ: chậm chạp / だらだら: lề mề / もたもた: chậm chạp","example":"新人の彼女は、てきぱきと仕事をこなしている。","example_reading":"しんじんのかのじょは、てきぱきとしごとをこなしている。","example_meaning":"Cô nhân viên mới xử lý công việc nhanh nhẹn gọn gàng.","examples":[{"example":"新人の彼女は、てきぱきと仕事をこなしている。","example_reading":"しんじんのかのじょは、てきぱきとしごとをこなしている。","example_meaning":"Cô nhân viên mới xử lý công việc nhanh nhẹn gọn gàng."},{"example":"母は、てきぱき家事をして、すぐに出かけた。","example_reading":"ははは、てきぱきかじをして、すぐにでかけた。","example_meaning":"Mẹ làm việc nhà thoăn thoắt rồi ra ngoài ngay."}],"level":"b1"},
{"word":"がらり","reading":"がらり","meaning":"thay đổi hẳn; (cửa) mở soạt","antonym":"相変わらず（あいかわらず）: vẫn như cũ / 依然として（いぜんとして）: vẫn như cũ","antonym_hanviet":"tương biến / y nhiên","note":"Hay đi với 変わる, 戸を開ける, と. Thay đổi hoàn toàn; cũng tiếng kéo cửa trượt.","example":"引っ越してから、生活ががらりと変わった。","example_reading":"ひっこしてから、せいかつががらりとかわった。","example_meaning":"Sau khi chuyển nhà, cuộc sống đã thay đổi hoàn toàn.","examples":[{"example":"引っ越してから、生活ががらりと変わった。","example_reading":"ひっこしてから、せいかつががらりとかわった。","example_meaning":"Sau khi chuyển nhà, cuộc sống đã thay đổi hoàn toàn."},{"example":"部屋の戸ががらりと開いて、祖父が入ってきた。","example_reading":"へやのとががらりとあいて、そふがはいってきた。","example_meaning":"Cửa phòng bật mở đánh soạt, ông tôi bước vào."}],"level":"b1"},
{"word":"せかせか","reading":"せかせか","meaning":"hấp tấp, vội vã","antonym":"のんびり: thong thả / ぶらぶら: Đi dạo vẩn vơ / ゆったり: thong thả","note":"Dáng vẻ không bình tĩnh, luôn vội. Hay đi với 歩く, する.","example":"彼はいつもせかせか歩いて、立ち止まらない。","example_reading":"かれはいつもせかせかあるいて、たちどまらない。","example_meaning":"Anh ấy lúc nào cũng đi vội vã, không dừng lại.","examples":[{"example":"彼はいつもせかせか歩いて、立ち止まらない。","example_reading":"かれはいつもせかせかあるいて、たちどまらない。","example_meaning":"Anh ấy lúc nào cũng đi vội vã, không dừng lại."},{"example":"せかせかせずに、もっと落ち着いて話してください。","example_reading":"せかせかせずに、もっとおちついてはなしてください。","example_meaning":"Đừng hấp tấp, hãy nói bình tĩnh hơn."}],"level":"b1"},
{"word":"いそいそ","reading":"いそいそ","meaning":"hớn hở vội vàng","note":"Vội vàng vì vui mừng. Hay đi với 出かける, 支度する.","example":"彼女は、デートの日にいそいそと出かけて行った。","example_reading":"かのじょは、デートのひにいそいそとでかけていった。","example_meaning":"Đến ngày hẹn hò, cô ấy hớn hở đi ra ngoài.","examples":[{"example":"彼女は、デートの日にいそいそと出かけて行った。","example_reading":"かのじょは、デートのひにいそいそとでかけていった。","example_meaning":"Đến ngày hẹn hò, cô ấy hớn hở đi ra ngoài."},{"example":"父は孫が来ると聞いて、いそいそと買い物に出かけた。","example_reading":"ちちはまごがくるときいて、いそいそとかいものにでかけた。","example_meaning":"Nghe cháu sắp đến, ông tôi hớn hở đi mua sắm."}],"level":"b1"},
{"word":"こつこつ","reading":"こつこつ","meaning":"chăm chỉ bền bỉ, đều đặn từng chút","antonym":"いい加減に（いいかげんに）: qua loa","antonym_hanviet":"gia giảm","note":"Từ tượng hình (cũng là tiếng gõ nhẹ). Làm việc kiên trì, hay đi với 努力する, 貯金する.","example":"彼は毎日こつこつ貯金している。","example_reading":"かれはまいにちこつこつちょきんしている。","example_meaning":"Anh ấy ngày nào cũng chăm chỉ tiết kiệm.","examples":[{"example":"彼は毎日こつこつ貯金している。","example_reading":"かれはまいにちこつこつちょきんしている。","example_meaning":"Anh ấy ngày nào cũng chăm chỉ tiết kiệm."},{"example":"彼女はこつこつ勉強して、資格を取った。","example_reading":"かのじょはこつこつべんきょうして、しかくをとった。","example_meaning":"Cô ấy chăm chỉ học tập từng chút rồi lấy được chứng chỉ."}],"level":"b1"},
{"word":"じわじわ","reading":"じわじわ","meaning":"từ từ nhưng chắc chắn","antonym":"一気に（いっきに）: một mạch / ぱっと: bỗng chốc","antonym_hanviet":"nhất khí / ","note":"Lan, ngấm hoặc tăng dần chậm rãi. Hay đi với 広がる, 効く, 増える.","example":"薬の効果が、じわじわと現れてきた。","example_reading":"くすりのこうかが、じわじわとあらわれてきた。","example_meaning":"Hiệu quả của thuốc dần dần xuất hiện.","examples":[{"example":"薬の効果が、じわじわと現れてきた。","example_reading":"くすりのこうかが、じわじわとあらわれてきた。","example_meaning":"Hiệu quả của thuốc dần dần xuất hiện."},{"example":"円安の影響が、じわじわと生活に広がっている。","example_reading":"えんやすのえいきょうが、じわじわとせいかつにひろがっている。","example_meaning":"Ảnh hưởng của đồng yên yếu đang dần lan vào đời sống."}],"level":"b1"},
{"word":"とぼとぼ","reading":"とぼとぼ","meaning":"lững thững, rũ rượi","antonym":"すたすた: bước nhanh đều","note":"Hay đi với 歩く. Bước đi chậm vì buồn hoặc mệt.","example":"試験に落ちて、彼はとぼとぼ家に帰った。","example_reading":"しけんにおちて、かれはとぼとぼいえにかえった。","example_meaning":"Thi trượt, anh ấy lủi thủi đi về nhà.","examples":[{"example":"試験に落ちて、彼はとぼとぼ家に帰った。","example_reading":"しけんにおちて、かれはとぼとぼいえにかえった。","example_meaning":"Thi trượt, anh ấy lủi thủi đi về nhà."},{"example":"雨の中を、とぼとぼと歩く老人を見かけた。","example_reading":"あめのなかを、とぼとぼとあるくろうじんをみかけた。","example_meaning":"Tôi thấy một cụ già lững thững đi dưới mưa."}],"level":"b1"},
{"word":"よろよろ","reading":"よろよろ","meaning":"loạng choạng, chập chững","antonym":"しっかり: vững vàng","note":"Hay đi với 歩く, 立ち上がる. Đi không vững vì yếu hoặc mang nặng.","example":"重い荷物を持って、よろよろ歩いた。","example_reading":"おもいにもつをもって、よろよろあるいた。","example_meaning":"Xách đồ nặng nên tôi đi loạng choạng.","examples":[{"example":"重い荷物を持って、よろよろ歩いた。","example_reading":"おもいにもつをもって、よろよろあるいた。","example_meaning":"Xách đồ nặng nên tôi đi loạng choạng."},{"example":"熱が高くて、よろよろと立ち上がった。","example_reading":"ねつがたかくて、よろよろとたちあがった。","example_meaning":"Sốt cao nên tôi loạng choạng đứng dậy."}],"level":"b1"},
{"word":"のろのろ","reading":"のろのろ","meaning":"chậm chạp, lờ đờ","note":"Di chuyển hoặc làm việc rất chậm. Hay đi với 歩く, 進む, する.","antonym":"てきぱき: nhanh nhẹn / どんどん: liên tục / ずんずん: thẳng tiến","example":"前の車がのろのろ走って、なかなか進まない。","example_reading":"まえのくるまがのろのろはしって、なかなかすすまない。","example_meaning":"Chiếc xe phía trước chạy lờ đờ nên mãi không tiến lên được.","examples":[{"example":"前の車がのろのろ走って、なかなか進まない。","example_reading":"まえのくるまがのろのろはしって、なかなかすすまない。","example_meaning":"Chiếc xe phía trước chạy lờ đờ nên mãi không tiến lên được."},{"example":"のろのろしていると、電車に乗り遅れるよ。","example_reading":"のろのろしていると、でんしゃにのりおくれるよ。","example_meaning":"Cứ chậm chạp thế này sẽ lỡ tàu đấy."}],"level":"b1"},
{"word":"ほろり","reading":"ほろり","meaning":"chạnh lòng, rơm rớm nước mắt","note":"Hay đi với と, する, させる. Cảm động nhẹ nhàng, chực khóc.","example":"昔の友人からの手紙を読んで、思わずほろりとした。","example_reading":"むかしのゆうじんからのてがみをよんで、おもわずほろりとした。","example_meaning":"Đọc thư người bạn cũ, tôi chợt rơm rớm nước mắt.","examples":[{"example":"昔の友人からの手紙を読んで、思わずほろりとした。","example_reading":"むかしのゆうじんからのてがみをよんで、おもわずほろりとした。","example_meaning":"Đọc thư người bạn cũ, tôi chợt rơm rớm nước mắt."},{"example":"ほろりとさせる話に、会場は静まり返った。","example_reading":"ほろりとさせるはなしに、かいじょうはしずまりかえった。","example_meaning":"Câu chuyện làm lòng người chạnh lại khiến cả hội trường im phăng phắc."}],"level":"b1"},
{"word":"すやすや","reading":"すやすや","meaning":"(Ngủ) ngon lành, yên bình","note":"Từ tượng hình. Dùng cho giấc ngủ của trẻ nhỏ, êm đềm.","example":"赤ちゃんがすやすや眠っている。","example_reading":"あかちゃんがすやすやねむっている。","example_meaning":"Em bé đang ngủ ngon lành.","examples":[{"example":"赤ちゃんがすやすや眠っている。","example_reading":"あかちゃんがすやすやねむっている。","example_meaning":"Em bé đang ngủ ngon lành."},{"example":"猫がソファの上で、すやすや眠っている。","example_reading":"ねこがソファのうえで、すやすやねむっている。","example_meaning":"Con mèo ngủ ngon lành trên ghế sofa."}],"level":"b1"},
{"word":"ぷんぷん","reading":"ぷんぷん","meaning":"giận đùng đùng; (mùi) nồng nặc","note":"Từ tượng hình. Nghĩa 1: giận dỗi. Nghĩa 2: mùi bốc lên mạnh.","example":"彼女は遅刻されて、ぷんぷん怒っている。","example_reading":"かのじょはちこくされて、ぷんぷんおこっている。","example_meaning":"Bị cho leo cây nên cô ấy giận đùng đùng.","examples":[{"example":"彼女は遅刻されて、ぷんぷん怒っている。","example_reading":"かのじょはちこくされて、ぷんぷんおこっている。","example_meaning":"Bị cho leo cây nên cô ấy giận đùng đùng."},{"example":"部屋中に、カレーのにおいがぷんぷんする。","example_reading":"へやじゅうに、カレーのにおいがぷんぷんする。","example_meaning":"Mùi cà ri nồng nặc khắp phòng."}],"level":"b1"},
{"word":"ぴんぴん","reading":"ぴんぴん","meaning":"khỏe re, tráng kiện","antonym":"ぐったり: mệt rũ / くたくた: mệt rã rời / へとへと: mệt lả","note":"Hay đi với 元気, している. Dùng cho người lớn tuổi mà vẫn rất khỏe.","example":"祖母は八十歳なのに、ぴんぴんしている。","example_reading":"そぼははちじゅっさいなのに、ぴんぴんしている。","example_meaning":"Bà tôi đã tám mươi tuổi mà vẫn khỏe re.","examples":[{"example":"祖母は八十歳なのに、ぴんぴんしている。","example_reading":"そぼははちじゅっさいなのに、ぴんぴんしている。","example_meaning":"Bà tôi đã tám mươi tuổi mà vẫn khỏe re."},{"example":"手術から一年、父は今もぴんぴんしている。","example_reading":"しゅじゅつからいちねん、ちちはいまもぴんぴんしている。","example_meaning":"Một năm sau ca phẫu thuật, bố tôi giờ vẫn khỏe mạnh."}],"level":"b1"},
{"word":"ぐったり","reading":"ぐったり","meaning":"mệt rũ, kiệt sức, lả người","antonym":"ぴんぴん: khỏe re / いきいき: sinh động","note":"Từ tượng hình. Hay đi với する／と, do mệt mỏi hoặc bệnh.","example":"一日中歩いて、ぐったりしました。","example_reading":"いちにちじゅうあるいて、ぐったりしました。","example_meaning":"Đi bộ cả ngày làm tôi rã rời.","examples":[{"example":"一日中歩いて、ぐったりしました。","example_reading":"いちにちじゅうあるいて、ぐったりしました。","example_meaning":"Đi bộ cả ngày làm tôi rã rời."},{"example":"暑さで、犬がぐったりしている。","example_reading":"あつさで、いぬがぐったりしている。","example_meaning":"Vì nóng, con chó lả người đi."}],"level":"b1"},
{"word":"ふっと","reading":"ふっと","meaning":"chợt, bất chợt","note":"Xảy ra bất ngờ, nhẹ nhàng. Hay đi với 思う, 消える, 笑う.","example":"電車の中で、ふっと昔のことを思い出した。","example_reading":"でんしゃのなかで、ふっとむかしのことをおもいだした。","example_meaning":"Trên tàu, tôi chợt nhớ lại chuyện ngày xưa.","examples":[{"example":"電車の中で、ふっと昔のことを思い出した。","example_reading":"でんしゃのなかで、ふっとむかしのことをおもいだした。","example_meaning":"Trên tàu, tôi chợt nhớ lại chuyện ngày xưa."},{"example":"風で、ろうそくの火がふっと消えた。","example_reading":"かぜで、ろうそくのひがふっときえた。","example_meaning":"Ngọn nến bỗng tắt phụt vì gió."}],"level":"b1"},
{"word":"しみじみ","reading":"しみじみ","meaning":"thấm thía, sâu sắc","note":"Hay đi với 感じる, 思う, 語る. Cảm xúc thấm sâu trong lòng.","example":"親になって、母の苦労をしみじみと感じた。","example_reading":"おやになって、ははのくろうをしみじみとかんじた。","example_meaning":"Khi làm cha mẹ, tôi mới thấm thía nỗi vất vả của mẹ.","examples":[{"example":"親になって、母の苦労をしみじみと感じた。","example_reading":"おやになって、ははのくろうをしみじみとかんじた。","example_meaning":"Khi làm cha mẹ, tôi mới thấm thía nỗi vất vả của mẹ."},{"example":"古い写真を見ながら、しみじみ昔を思い出した。","example_reading":"ふるいしゃしんをみながら、しみじみむかしをおもいだした。","example_meaning":"Ngắm ảnh cũ, tôi lặng lẽ nhớ lại chuyện xưa."}],"level":"b1"},
{"word":"しんみり","reading":"しんみり","meaning":"trầm lắng, bùi ngùi","antonym":"わいわい: ồn ào vui vẻ","note":"Không khí hoặc tâm trạng yên lặng buồn man mác. Hay đi với する, 話す.","example":"別れの話になって、座がしんみりしてしまった。","example_reading":"わかれのはなしになって、ざがしんみりしてしまった。","example_meaning":"Câu chuyện chuyển sang chia tay nên không khí buổi họp trở nên trầm lắng.","examples":[{"example":"別れの話になって、座がしんみりしてしまった。","example_reading":"わかれのはなしになって、ざがしんみりしてしまった。","example_meaning":"Câu chuyện chuyển sang chia tay nên không khí buổi họp trở nên trầm lắng."},{"example":"昔の写真を見ながら、しんみりと話し込んだ。","example_reading":"むかしのしゃしんをみながら、しんみりとはなしこんだ。","example_meaning":"Chúng tôi vừa xem ảnh xưa vừa trò chuyện bùi ngùi."}],"level":"b1"},
{"word":"しっかり","reading":"しっかり","meaning":"chắc chắn, vững vàng, cẩn thận","antonym":"ぐらぐら: lung lay / いい加減に（いいかげんに）: qua loa / うっかり: vô ý","antonym_hanviet":" / gia giảm / ","note":"Từ tượng hình. Dùng cho cầm nắm, ý chí, tính cách, cách làm.","example":"大事な書類をしっかり保管してください。","example_reading":"だいじなしょるいをしっかりほかんしてください。","example_meaning":"Hãy giữ cẩn thận tài liệu quan trọng.","examples":[{"example":"大事な書類をしっかり保管してください。","example_reading":"だいじなしょるいをしっかりほかんしてください。","example_meaning":"Hãy giữ cẩn thận tài liệu quan trọng."},{"example":"靴ひもをしっかり結んでから、走り始めた。","example_reading":"くつひもをしっかりむすんでから、はしりはじめた。","example_meaning":"Tôi buộc chặt dây giày rồi mới bắt đầu chạy."}],"level":"b1"},
{"word":"こっそり","reading":"こっそり","meaning":"lén lút, âm thầm","note":"Từ tượng hình. Làm mà không để ai biết, nhẹ hơn こそこそ.","antonym":"堂々と（どうどうと）: đường hoàng","antonym_hanviet":"đường đường","example":"夜中にこっそり冷蔵庫を開けた。","example_reading":"よなかにこっそりれいぞうこをあけた。","example_meaning":"Nửa đêm tôi lén mở tủ lạnh.","examples":[{"example":"夜中にこっそり冷蔵庫を開けた。","example_reading":"よなかにこっそりれいぞうこをあけた。","example_meaning":"Nửa đêm tôi lén mở tủ lạnh."},{"example":"彼は誕生日のプレゼントをこっそり準備していた。","example_reading":"かれはたんじょうびのプレゼントをこっそりじゅんびしていた。","example_meaning":"Anh ấy lén chuẩn bị quà sinh nhật."}],"level":"b1"},
{"word":"きちんと","reading":"きちんと","meaning":"đàng hoàng, ngăn nắp, đúng chuẩn mực","antonym":"だらしなく: luộm thuộm / ごちゃごちゃ: lộn xộn / ぐちゃぐちゃ: nát bét","note":"Từ tượng hình. Hay đi với 片付ける, 守る, 挨拶する.","example":"部屋をきちんと片付けなさい。","example_reading":"へやをきちんとかたづけなさい。","example_meaning":"Hãy dọn phòng cho ngăn nắp.","examples":[{"example":"部屋をきちんと片付けなさい。","example_reading":"へやをきちんとかたづけなさい。","example_meaning":"Hãy dọn phòng cho ngăn nắp."},{"example":"毎月の家賃をきちんと払っている。","example_reading":"まいつきのやちんをきちんとはらっている。","example_meaning":"Tiền nhà hằng tháng tôi đều trả đúng hạn."}],"level":"b1"},
{"word":"ぼろぼろ","reading":"ぼろぼろ","meaning":"rách nát, tả tơi; (nước mắt) lã chã","antonym":"ぴかぴか: sáng bóng","note":"Từ tượng hình. Nghĩa 1: hỏng nát. Nghĩa 2: 涙がぼろぼろ落ちる.","example":"この靴はもうぼろぼろです。","example_reading":"このくつはもうぼろぼろです。","example_meaning":"Đôi giày này đã rách tả tơi.","examples":[{"example":"この靴はもうぼろぼろです。","example_reading":"このくつはもうぼろぼろです。","example_meaning":"Đôi giày này đã rách tả tơi."},{"example":"感動的な映画で、涙がぼろぼろ出た。","example_reading":"かんどうてきなえいがで、なみだがぼろぼろでた。","example_meaning":"Xem bộ phim cảm động, nước mắt tôi lã chã."}],"level":"b1"},
{"word":"ぼさぼさ","reading":"ぼさぼさ","meaning":"rối bù, xơ xác","antonym":"きちんと: ngăn nắp","note":"Tóc hoặc lông không được chải chuốt. Hay đi với 髪, 毛.","example":"寝起きで髪がぼさぼさのまま、玄関に出た。","example_reading":"ねおきでかみがぼさぼさのまま、げんかんにでた。","example_meaning":"Mới ngủ dậy, tôi để nguyên mái tóc rối bù ra cửa.","examples":[{"example":"寝起きで髪がぼさぼさのまま、玄関に出た。","example_reading":"ねおきでかみがぼさぼさのまま、げんかんにでた。","example_meaning":"Mới ngủ dậy, tôi để nguyên mái tóc rối bù ra cửa."},{"example":"犬の毛がぼさぼさだから、ブラシをかけてあげよう。","example_reading":"いぬのけがぼさぼさだから、ブラシをかけてあげよう。","example_meaning":"Lông chó rối xơ nên chải cho nó nhé."}],"level":"b1"},
{"word":"どっしり","reading":"どっしり","meaning":"vững chãi, bề thế","antonym":"ぐらぐら: lung lay / ひょろひょろ: gầy cao lêu nghêu","note":"Hay đi với 構える, 座る, 重い. Chắc chắn, đĩnh đạc.","example":"山のふもとに、どっしりとした古い家が立っている。","example_reading":"やまのふもとに、どっしりとしたふるいいえがたっている。","example_meaning":"Dưới chân núi có ngôi nhà cổ bề thế.","examples":[{"example":"山のふもとに、どっしりとした古い家が立っている。","example_reading":"やまのふもとに、どっしりとしたふるいいえがたっている。","example_meaning":"Dưới chân núi có ngôi nhà cổ bề thế."},{"example":"彼は何があっても、どっしり構えている。","example_reading":"かれはなにがあっても、どっしりかまえている。","example_meaning":"Dù có chuyện gì anh ấy vẫn điềm tĩnh vững vàng."}],"level":"b1"},
{"word":"ずっしり","reading":"ずっしり","meaning":"nặng trịch","antonym":"ふわふわ: nhẹ bẫng / ふわっと: nhẹ bẫng / ふんわり: mềm xốp","note":"Hay đi với 重い, 手応え. Cảm giác nặng và chắc.","example":"買い物袋がずっしりと重い。","example_reading":"かいものぶくろがずっしりとおもい。","example_meaning":"Túi mua sắm nặng trịch.","examples":[{"example":"買い物袋がずっしりと重い。","example_reading":"かいものぶくろがずっしりとおもい。","example_meaning":"Túi mua sắm nặng trịch."},{"example":"初めて抱いた赤ちゃんは、ずっしりと重かった。","example_reading":"はじめてだいたあかちゃんは、ずっしりとおもかった。","example_meaning":"Em bé lần đầu tôi bế nặng trĩu trong tay."}],"level":"b1"},
{"word":"ずらり","reading":"ずらり","meaning":"một hàng dài","antonym":"ぽつん: lẻ loi / ちらほら: lác đác","note":"Nhiều vật xếp thành hàng. Hay đi với 並ぶ, 揃う.","example":"市場には、新鮮な魚がずらりと並んでいた。","example_reading":"いちばには、しんせんなさかながずらりとならんでいた。","example_meaning":"Ở chợ, cá tươi bày thành hàng dài.","examples":[{"example":"市場には、新鮮な魚がずらりと並んでいた。","example_reading":"いちばには、しんせんなさかながずらりとならんでいた。","example_meaning":"Ở chợ, cá tươi bày thành hàng dài."},{"example":"会場の前に、車がずらりと止まっている。","example_reading":"かいじょうのまえに、くるまがずらりととまっている。","example_meaning":"Trước hội trường, xe đỗ thành hàng dài."}],"level":"b1"},
{"word":"なかなか","reading":"なかなか","meaning":"mãi mà (không), không dễ","antonym":"すぐに: ngay lập tức / あっさり: dễ dàng / すんなり: suôn sẻ","note":"Đi với phủ định ～ない: \"mãi mà chưa／không dễ ～\". Không đi với ～ない thì nghĩa là \"khá, tương đối\".","example":"薬を飲んだのに、熱がなかなか下がらない。","example_reading":"くすりをのんだのに、ねつがなかなかさがらない。","example_meaning":"Tôi đã uống thuốc rồi mà sốt mãi không hạ.","examples":[{"example":"薬を飲んだのに、熱がなかなか下がらない。","example_reading":"くすりをのんだのに、ねつがなかなかさがらない。","example_meaning":"Tôi đã uống thuốc rồi mà sốt mãi không hạ."},{"example":"彼女は新人なのに、なかなか度胸がある。","example_reading":"かのじょはしんじんなのに、なかなかどきょうがある。","example_meaning":"Cô ấy mới vào mà khá là gan dạ."}],"level":"c1"},
{"word":"あまり","reading":"あまり","meaning":"không ... lắm","antonym":"とても: rất","note":"Đi với phủ định ～ない／～ません: \"không ～ lắm\". Dạng nhấn mạnh あまりにも (quá mức).","example":"最近は忙しくて、あまり寝ていない。","example_reading":"さいきんはいそがしくて、あまりねていない。","example_meaning":"Dạo này bận nên tôi không ngủ được mấy.","examples":[{"example":"最近は忙しくて、あまり寝ていない。","example_reading":"さいきんはいそがしくて、あまりねていない。","example_meaning":"Dạo này bận nên tôi không ngủ được mấy."},{"example":"甘い物はあまり食べないようにしている。","example_reading":"あまいものはあまりたべないようにしている。","example_meaning":"Tôi cố gắng không ăn nhiều đồ ngọt."}],"level":"c1"},
{"word":"ほとんど","reading":"ほとんど","meaning":"hầu như (không)","note":"Đi với phủ định ～ない: \"hầu như không ～\". Với khẳng định (～た／～ている) nghĩa là \"gần như, hầu hết\".","example":"昨日の夜は緊張して、ほとんど眠れなかった。","example_reading":"きのうのよるはきんちょうして、ほとんどねむれなかった。","example_meaning":"Tối qua tôi căng thẳng nên gần như không ngủ được.","examples":[{"example":"昨日の夜は緊張して、ほとんど眠れなかった。","example_reading":"きのうのよるはきんちょうして、ほとんどねむれなかった。","example_meaning":"Tối qua tôi căng thẳng nên gần như không ngủ được."},{"example":"仕事はほとんど終わったので、先に帰ります。","example_reading":"しごとはほとんどおわったので、さきにかえります。","example_meaning":"Công việc gần xong rồi nên tôi về trước."}],"level":"c1"},
{"word":"全然","reading":"ぜんぜん","meaning":"hoàn toàn không","hanviet":"toàn nhiên","note":"Đi với phủ định ～ない: \"hoàn toàn không ～\". Khẩu ngữ giới trẻ đôi khi dùng với khẳng định (全然いい).","example":"説明を聞いても、全然わからなかった。","example_reading":"せつめいをきいても、ぜんぜんわからなかった。","example_meaning":"Nghe giải thích rồi mà tôi vẫn hoàn toàn không hiểu.","examples":[{"example":"説明を聞いても、全然わからなかった。","example_reading":"せつめいをきいても、ぜんぜんわからなかった。","example_meaning":"Nghe giải thích rồi mà tôi vẫn hoàn toàn không hiểu."},{"example":"雨が降っても、私は全然平気です。","example_reading":"あめがふっても、わたしはぜんぜんへいきです。","example_meaning":"Dù trời mưa, tôi cũng hoàn toàn không sao."}],"level":"c1"},
{"word":"もし","reading":"もし","meaning":"nếu như","note":"Đi với ～たら／～ば／～なら. Giả định có thể xảy ra.","example":"もし明日雨が降ったら、試合は中止になります。","example_reading":"もしあしたあめがふったら、しあいはちゅうしになります。","example_meaning":"Nếu ngày mai trời mưa thì trận đấu sẽ bị hủy.","examples":[{"example":"もし明日雨が降ったら、試合は中止になります。","example_reading":"もしあしたあめがふったら、しあいはちゅうしになります。","example_meaning":"Nếu ngày mai trời mưa thì trận đấu sẽ bị hủy."},{"example":"もし私が社長なら、休みをもっと増やします。","example_reading":"もしわたしがしゃちょうなら、やすみをもっとふやします。","example_meaning":"Nếu tôi là giám đốc, tôi sẽ tăng thêm ngày nghỉ."}],"level":"c1"},
{"word":"まさか","reading":"まさか","meaning":"lẽ nào, không ngờ","note":"Đi với ～ないだろう／～ないよね, hoặc ～とは／～なんて (không ngờ tới). Diễn tả khó tin, bất ngờ.","example":"まさか彼が約束を忘れるなんて、思わなかった。","example_reading":"まさかかれがやくそくをわすれるなんて、おもわなかった。","example_meaning":"Tôi không ngờ anh ấy lại quên cuộc hẹn.","examples":[{"example":"まさか彼が約束を忘れるなんて、思わなかった。","example_reading":"まさかかれがやくそくをわすれるなんて、おもわなかった。","example_meaning":"Tôi không ngờ anh ấy lại quên cuộc hẹn."},{"example":"まさか、そんな高い物を買ったんじゃないでしょうね。","example_reading":"まさか、そんなたかいものをかったんじゃないでしょうね。","example_meaning":"Lẽ nào bạn lại mua món đắt thế đó chứ?"}],"level":"c1"},
{"word":"とても","reading":"とても","meaning":"không thể nào (với ～ない); rất","antonym":"あまり: không ... lắm / ちっとも: chẳng một chút nào / それほど: không đến mức đó","note":"Đi với phủ định ～ない／～られない: \"không tài nào ～\". Với khẳng định nghĩa là \"rất\".","example":"彼の絵はとても素人が描いたとは思えない。","example_reading":"かれのえはとてもしろうとがえがいたとはおもえない。","example_meaning":"Bức tranh của anh ấy không thể nào tin là do người nghiệp dư vẽ.","examples":[{"example":"彼の絵はとても素人が描いたとは思えない。","example_reading":"かれのえはとてもしろうとがえがいたとはおもえない。","example_meaning":"Bức tranh của anh ấy không thể nào tin là do người nghiệp dư vẽ."},{"example":"こんなに多くの仕事は、一人ではとても終わらない。","example_reading":"こんなにおおくのしごとは、ひとりではとてもおわらない。","example_meaning":"Từng này việc thì một mình tôi không thể nào xong được."}],"level":"c1"},
{"word":"決して","reading":"けっして","meaning":"tuyệt đối không","hanviet":"quyết","note":"Đi với phủ định ～ない／～ません. Phủ định rất mạnh, thể hiện quyết tâm hoặc khẳng định chắc chắn.","antonym":"必ず（かならず）: nhất định","antonym_hanviet":"tất","example":"このご恩は決して忘れません。","example_reading":"このごおんはけっしてわすれません。","example_meaning":"Tôi sẽ không bao giờ quên ơn này.","examples":[{"example":"このご恩は決して忘れません。","example_reading":"このごおんはけっしてわすれません。","example_meaning":"Tôi sẽ không bao giờ quên ơn này."},{"example":"彼は決して約束を破るような人ではない。","example_reading":"かれはけっしてやくそくをやぶるようなひとではない。","example_meaning":"Anh ấy tuyệt đối không phải người sẽ thất hứa."}],"level":"c1"},
{"word":"必ず","reading":"かならず","meaning":"nhất định, chắc chắn","hanviet":"tất","antonym":"決して（けっして）: tuyệt đối không / 必ずしも（かならずしも）: không hẳn là","antonym_hanviet":"quyết / tất","note":"Đi với ～する／～てください／～だろう. Ý chí hoặc khẳng định mạnh; khác 必ずしも (không hẳn).","example":"明日は必ず時間どおりに来てください。","example_reading":"あしたはかならずじかんどおりにきてください。","example_meaning":"Ngày mai nhất định hãy đến đúng giờ.","examples":[{"example":"明日は必ず時間どおりに来てください。","example_reading":"あしたはかならずじかんどおりにきてください。","example_meaning":"Ngày mai nhất định hãy đến đúng giờ."},{"example":"努力すれば、必ず夢は叶う。","example_reading":"どりょくすれば、かならずゆめはかなう。","example_meaning":"Nếu nỗ lực thì nhất định ước mơ sẽ thành."}],"level":"c1"},
{"word":"必ずしも","reading":"かならずしも","meaning":"không hẳn là, chưa chắc","hanviet":"tất","antonym":"必ず（かならず）: nhất định","antonym_hanviet":"tất","note":"Đi với phủ định ～ない／～とは限らない／～わけではない. Phủ định một phần.","example":"値段が高いからといって、必ずしも品質がいいとは限らない。","example_reading":"ねだんがたかいからといって、かならずしもひんしつがいいとはかぎらない。","example_meaning":"Giá cao không có nghĩa là chất lượng nhất định tốt.","examples":[{"example":"値段が高いからといって、必ずしも品質がいいとは限らない。","example_reading":"ねだんがたかいからといって、かならずしもひんしつがいいとはかぎらない。","example_meaning":"Giá cao không có nghĩa là chất lượng nhất định tốt."},{"example":"必ずしも全員が賛成しているわけではない。","example_reading":"かならずしもぜんいんがさんせいしているわけではない。","example_meaning":"Không hẳn là mọi người đều tán thành."}],"level":"c1"},
{"word":"まるで","reading":"まるで","meaning":"cứ như là","note":"Đi với ～ようだ／～みたいだ／～かのようだ. Dùng để so sánh ví von.","example":"今日はまるで夏のような暑さだ。","example_reading":"きょうはまるでなつのようなあつさだ。","example_meaning":"Hôm nay nóng cứ như mùa hè.","examples":[{"example":"今日はまるで夏のような暑さだ。","example_reading":"きょうはまるでなつのようなあつさだ。","example_meaning":"Hôm nay nóng cứ như mùa hè."},{"example":"彼女はまるで何も知らないかのように振る舞っていた。","example_reading":"かのじょはまるでなにもしらないかのようにふるまっていた。","example_meaning":"Cô ấy cư xử cứ như thể chẳng biết gì cả."}],"level":"c1"},
{"word":"たとえ","reading":"たとえ","meaning":"dù cho, cho dù","note":"Đi với ～ても／～でも. Nhượng bộ mang tính giả định.","example":"たとえ失敗しても、最後までやってみます。","example_reading":"たとえしっぱいしても、さいごまでやってみます。","example_meaning":"Dù có thất bại, tôi cũng sẽ thử đến cùng.","examples":[{"example":"たとえ失敗しても、最後までやってみます。","example_reading":"たとえしっぱいしても、さいごまでやってみます。","example_meaning":"Dù có thất bại, tôi cũng sẽ thử đến cùng."},{"example":"たとえ親に反対されても、この仕事を続けたい。","example_reading":"たとえおやにはんたいされても、このしごとをつづけたい。","example_meaning":"Dù bị bố mẹ phản đối, tôi vẫn muốn tiếp tục công việc này."}],"level":"c1"},
{"word":"いくら","reading":"いくら","meaning":"dù ... đến đâu","note":"Đi với ～ても／～でも: \"dù có ～ bao nhiêu cũng ～\". Còn có nghĩa \"bao nhiêu (tiền)\".","example":"いくら頑張っても、この問題は解けなかった。","example_reading":"いくらがんばっても、このもんだいはとけなかった。","example_meaning":"Dù cố gắng thế nào tôi cũng không giải được bài này.","examples":[{"example":"いくら頑張っても、この問題は解けなかった。","example_reading":"いくらがんばっても、このもんだいはとけなかった。","example_meaning":"Dù cố gắng thế nào tôi cũng không giải được bài này."},{"example":"いくら安くても、使わない物は買わないほうがいい。","example_reading":"いくらやすくても、つかわないものはかわないほうがいい。","example_meaning":"Dù rẻ đến đâu thì đồ không dùng cũng đừng mua."}],"level":"c1"},
{"word":"どんなに","reading":"どんなに","meaning":"dù ... đến mức nào","note":"Đi với ～ても／～でも. Cũng đi với ～ことか／～たか để cảm thán: \"biết bao ～\".","example":"どんなに忙しくても、毎朝ジョギングをしている。","example_reading":"どんなにいそがしくても、まいあさジョギングをしている。","example_meaning":"Dù bận đến đâu, tôi vẫn chạy bộ mỗi sáng.","examples":[{"example":"どんなに忙しくても、毎朝ジョギングをしている。","example_reading":"どんなにいそがしくても、まいあさジョギングをしている。","example_meaning":"Dù bận đến đâu, tôi vẫn chạy bộ mỗi sáng."},{"example":"合格の知らせを聞いて、どんなに嬉しかったことか。","example_reading":"ごうかくのしらせをきいて、どんなにうれしかったことか。","example_meaning":"Nghe tin đỗ, tôi vui biết bao."}],"level":"c1"},
{"word":"どれほど","reading":"どれほど","meaning":"dù bao nhiêu, đến mức nào","note":"Đi với ～ても／～ことか. Mức độ lớn, thường dùng trong văn viết.","example":"どれほど努力しても、彼には勝てなかった。","example_reading":"どれほどどりょくしても、かれにはかてなかった。","example_meaning":"Dù nỗ lực đến đâu tôi cũng không thắng được anh ấy.","examples":[{"example":"どれほど努力しても、彼には勝てなかった。","example_reading":"どれほどどりょくしても、かれにはかてなかった。","example_meaning":"Dù nỗ lực đến đâu tôi cũng không thắng được anh ấy."},{"example":"あなたがどれほど心配したことか。","example_reading":"あなたがどれほどしんぱいしたことか。","example_meaning":"Bạn đã lo lắng biết nhường nào."}],"level":"c1"},
{"word":"ぜひ","reading":"ぜひ","meaning":"nhất định, rất mong","note":"Đi với ～たい／～てください／～てほしい. Diễn tả nguyện vọng mạnh hoặc lời mời.","example":"京都に来たら、ぜひ私の家に寄ってください。","example_reading":"きょうとにきたら、ぜひわたしのいえによってください。","example_meaning":"Nếu đến Kyoto thì nhất định ghé nhà tôi nhé.","examples":[{"example":"京都に来たら、ぜひ私の家に寄ってください。","example_reading":"きょうとにきたら、ぜひわたしのいえによってください。","example_meaning":"Nếu đến Kyoto thì nhất định ghé nhà tôi nhé."},{"example":"来年はぜひ日本語能力試験のN1に合格したい。","example_reading":"らいねんはぜひにほんごのうりょくしけんのエヌいちにごうかくしたい。","example_meaning":"Năm sau tôi nhất định muốn đỗ N1 kỳ thi năng lực tiếng Nhật."}],"level":"c1"},
{"word":"別に","reading":"べつに","meaning":"không có gì đặc biệt","hanviet":"biệt","note":"Đi với phủ định ～ない. Khẩu ngữ, hay dùng để trả lời qua loa \"chẳng có gì\".","example":"「どうかしたの？」「別に。何でもないよ。」","example_reading":"「どうかしたの？」「べつに。なんでもないよ。」","example_meaning":"\"Có chuyện gì à?\" \"Không có gì. Chẳng sao đâu.\"","examples":[{"example":"「どうかしたの？」「別に。何でもないよ。」","example_reading":"「どうかしたの？」「べつに。なんでもないよ。」","example_meaning":"\"Có chuyện gì à?\" \"Không có gì. Chẳng sao đâu.\""},{"example":"別に怒っているわけではなく、ただ心配しているだけだ。","example_reading":"べつにおこっているわけではなく、ただしんぱいしているだけだ。","example_meaning":"Tôi không hẳn là giận, chỉ là lo thôi."}],"level":"c1"},
{"word":"めったに","reading":"めったに","meaning":"hiếm khi","note":"Đi với phủ định ～ない／～ません: \"hiếm khi ～\". Tần suất rất thấp.","antonym":"よく: hay, thường / いつも: luôn luôn / しょっちゅう: luôn luôn","example":"私はお酒をめったに飲みません。","example_reading":"わたしはおさけをめったにのみません。","example_meaning":"Tôi hiếm khi uống rượu.","examples":[{"example":"私はお酒をめったに飲みません。","example_reading":"わたしはおさけをめったにのみません。","example_meaning":"Tôi hiếm khi uống rượu."},{"example":"彼は人前でめったに怒らないが、怒ると怖い。","example_reading":"かれはひとまえでめったにおこらないが、おこるとこわい。","example_meaning":"Anh ấy hiếm khi nổi giận trước mặt người khác, nhưng khi giận thì rất đáng sợ."}],"level":"c1"},
{"word":"何も","reading":"なにも","meaning":"chẳng (gì) cả","hanviet":"hà","antonym":"何でも（なんでも）: cái gì cũng / 全て（すべて）: tất cả","antonym_hanviet":"hà / toàn","note":"Đi với phủ định ～ない. Đọc なにも. Nhấn mạnh hoàn toàn không có gì.","example":"朝から何も食べていない。","example_reading":"あさからなにもたべていない。","example_meaning":"Từ sáng tôi chưa ăn gì cả.","examples":[{"example":"朝から何も食べていない。","example_reading":"あさからなにもたべていない。","example_meaning":"Từ sáng tôi chưa ăn gì cả."},{"example":"何も心配することはありません。","example_reading":"なにもしんぱいすることはありません。","example_meaning":"Không có gì phải lo cả."}],"level":"c1"},
{"word":"少しも","reading":"すこしも","meaning":"một chút cũng không","hanviet":"thiểu","antonym":"大いに（おおいに）: rất nhiều","antonym_hanviet":"đại","note":"Đi với phủ định ～ない. Mạnh hơn あまり.","example":"彼女は少しも疲れた様子を見せなかった。","example_reading":"かのじょはすこしもつかれたようすをみせなかった。","example_meaning":"Cô ấy không hề tỏ vẻ mệt mỏi chút nào.","examples":[{"example":"彼女は少しも疲れた様子を見せなかった。","example_reading":"かのじょはすこしもつかれたようすをみせなかった。","example_meaning":"Cô ấy không hề tỏ vẻ mệt mỏi chút nào."},{"example":"私は少しも気にしていませんから、どうぞ遠慮なく。","example_reading":"わたしはすこしもきにしていませんから、どうぞえんりょなく。","example_meaning":"Tôi không bận tâm chút nào, xin cứ tự nhiên."}],"level":"c1"},
{"word":"ちっとも","reading":"ちっとも","meaning":"chẳng một chút nào","antonym":"とても: rất","note":"Đi với phủ định ～ない. Khẩu ngữ, thường kèm ý bực bội, phàn nàn.","example":"何度も言ったのに、息子はちっとも宿題をしない。","example_reading":"なんどもいったのに、むすこはちっともしゅくだいをしない。","example_meaning":"Tôi nhắc bao nhiêu lần mà thằng bé chẳng làm bài tập chút nào.","examples":[{"example":"何度も言ったのに、息子はちっとも宿題をしない。","example_reading":"なんどもいったのに、むすこはちっともしゅくだいをしない。","example_meaning":"Tôi nhắc bao nhiêu lần mà thằng bé chẳng làm bài tập chút nào."},{"example":"この映画はちっとも面白くなかった。","example_reading":"このえいがはちっともおもしろくなかった。","example_meaning":"Bộ phim này chẳng thú vị chút nào."}],"level":"c1"},
{"word":"何とか","reading":"なんとか","meaning":"bằng cách nào đó, cố xoay xở","hanviet":"hà","note":"Đi với ～する／～なる／～てください. Cố gắng làm cho được. Đọc なんとか.","example":"何とか終電に間に合った。","example_reading":"なんとかしゅうでんにまにあった。","example_meaning":"Cuối cùng tôi cũng kịp chuyến tàu cuối.","examples":[{"example":"何とか終電に間に合った。","example_reading":"なんとかしゅうでんにまにあった。","example_meaning":"Cuối cùng tôi cũng kịp chuyến tàu cuối."},{"example":"お金がなくても、何とかなるだろう。","example_reading":"おかねがなくても、なんとかなるだろう。","example_meaning":"Dù không có tiền chắc rồi cũng xoay xở được."}],"level":"c1"},
{"word":"どうしても","reading":"どうしても","meaning":"nhất định, dù thế nào cũng (không)","note":"Đi với ～たい／～ない／～なければならない. Ý chí mạnh, hoặc \"làm cách nào cũng không được\".","example":"この仕事は、どうしても今日中に終わらせたい。","example_reading":"このしごとは、どうしてもきょうじゅうにおわらせたい。","example_meaning":"Công việc này tôi nhất định muốn xong trong hôm nay.","examples":[{"example":"この仕事は、どうしても今日中に終わらせたい。","example_reading":"このしごとは、どうしてもきょうじゅうにおわらせたい。","example_meaning":"Công việc này tôi nhất định muốn xong trong hôm nay."},{"example":"何度やっても、どうしてもドアが開かない。","example_reading":"なんどやっても、どうしてもドアがひらかない。","example_meaning":"Thử bao nhiêu lần mà cửa vẫn không mở được."}],"level":"c1"},
{"word":"つい","reading":"つい","meaning":"lỡ, vô tình","antonym":"意識して（いしきして）: có ý thức / わざと: cố ý","antonym_hanviet":"ý thức / ","note":"Đi với ～てしまう／～ちゃう. Hành động ngoài ý muốn, hay lặp lại thói quen.","example":"ダイエット中なのに、ついケーキを食べてしまった。","example_reading":"ダイエットちゅうなのに、ついケーキをたべてしまった。","example_meaning":"Đang ăn kiêng mà lỡ ăn bánh mất rồi.","examples":[{"example":"ダイエット中なのに、ついケーキを食べてしまった。","example_reading":"ダイエットちゅうなのに、ついケーキをたべてしまった。","example_meaning":"Đang ăn kiêng mà lỡ ăn bánh mất rồi."},{"example":"面白くて、ついスマホを見続けてしまう。","example_reading":"おもしろくて、ついスマホをみつづけてしまう。","example_meaning":"Vì thú vị nên tôi cứ lỡ xem điện thoại mãi."}],"level":"c1"},
{"word":"思わず","reading":"おもわず","meaning":"bất giác, không kìm được","hanviet":"tư","antonym":"意識して（いしきして）: có ý thức / わざと: cố ý","antonym_hanviet":"ý thức / ","note":"Đi với ～てしまう／～た. Hành động phản xạ, không chủ ý.","example":"あまりにおかしくて、思わず笑ってしまった。","example_reading":"あまりにおかしくて、おもわずわらってしまった。","example_meaning":"Buồn cười quá nên tôi bất giác bật cười.","examples":[{"example":"あまりにおかしくて、思わず笑ってしまった。","example_reading":"あまりにおかしくて、おもわずわらってしまった。","example_meaning":"Buồn cười quá nên tôi bất giác bật cười."},{"example":"財布を落としたことに気づいて、思わず声を上げた。","example_reading":"さいふをおとしたことにきづいて、おもわずこえをあげた。","example_meaning":"Nhận ra mình làm rơi ví, tôi bất giác thốt lên."}],"level":"c1"},
{"word":"全く","reading":"まったく","meaning":"hoàn toàn (không)","hanviet":"toàn","note":"Đi với phủ định ～ない. Có thể đứng riêng để than phiền (\"まったく！\" = thật tình).","example":"彼の言っていることは全く理解できない。","example_reading":"かれのいっていることはまったくりかいできない。","example_meaning":"Tôi hoàn toàn không hiểu anh ấy nói gì.","examples":[{"example":"彼の言っていることは全く理解できない。","example_reading":"かれのいっていることはまったくりかいできない。","example_meaning":"Tôi hoàn toàn không hiểu anh ấy nói gì."},{"example":"全く、いつまでゲームをしているの。早く寝なさい。","example_reading":"まったく、いつまでゲームをしているの。はやくねなさい。","example_meaning":"Thật tình, chơi game đến bao giờ nữa. Ngủ đi."}],"level":"c1"},
{"word":"何としても","reading":"なんとしても","meaning":"bằng mọi giá","hanviet":"hà","note":"Đi với ～たい／～なければならない／～てみせる. Ý chí mạnh. Đọc なんとしても.","example":"何としても試合に勝ちたい。","example_reading":"なんとしてもしあいにかちたい。","example_meaning":"Bằng mọi giá tôi muốn thắng trận.","examples":[{"example":"何としても試合に勝ちたい。","example_reading":"なんとしてもしあいにかちたい。","example_meaning":"Bằng mọi giá tôi muốn thắng trận."},{"example":"何としても期限までに完成させなければならない。","example_reading":"なんとしてもきげんまでにかんせいさせなければならない。","example_meaning":"Bằng mọi giá phải hoàn thành trước hạn."}],"level":"c1"},
{"word":"いつまでも","reading":"いつまでも","meaning":"mãi mãi, mãi không","antonym":"一時的に（いちじてきに）: tạm thời","antonym_hanviet":"nhất thời đích","note":"Đi với ～ない (không thể mãi…) hoặc ～ている／～てください (mãi mãi…).","example":"いつまでも若いままではいられない。","example_reading":"いつまでもわかいままではいられない。","example_meaning":"Không thể trẻ mãi được.","examples":[{"example":"いつまでも若いままではいられない。","example_reading":"いつまでもわかいままではいられない。","example_meaning":"Không thể trẻ mãi được."},{"example":"この思い出は、いつまでも忘れないでしょう。","example_reading":"このおもいでは、いつまでもわすれないでしょう。","example_meaning":"Kỷ niệm này có lẽ tôi sẽ mãi không quên."}],"level":"c1"},
{"word":"絶対に","reading":"ぜったいに","meaning":"tuyệt đối","hanviet":"tuyệt đối","antonym":"多分（たぶん）: có lẽ / たぶん: có lẽ / おそらく: có lẽ","antonym_hanviet":"đa phân /  / ","note":"Đi với ～ない／～てはいけない (cấm tuyệt đối) hoặc ～てください／～する (quyết tâm nhất định).","example":"この秘密は絶対に誰にも言わないでください。","example_reading":"このひみつはぜったいにだれにもいわないでください。","example_meaning":"Bí mật này tuyệt đối đừng nói với ai.","examples":[{"example":"この秘密は絶対に誰にも言わないでください。","example_reading":"このひみつはぜったいにだれにもいわないでください。","example_meaning":"Bí mật này tuyệt đối đừng nói với ai."},{"example":"今度の試合は絶対に勝つぞ。","example_reading":"こんどのしあいはぜったいにかつぞ。","example_meaning":"Trận lần này nhất định phải thắng."}],"level":"c1"},
{"word":"もしも","reading":"もしも","meaning":"nếu chẳng may","note":"Đi với ～たら／～ば. Mạnh hơn もし, thường là tình huống xấu hoặc ít khả năng xảy ra.","example":"もしも地震が起きたら、まずテーブルの下に隠れてください。","example_reading":"もしもじしんがおきたら、まずテーブルのしたにかくれてください。","example_meaning":"Nếu chẳng may có động đất, trước hết hãy trốn xuống gầm bàn.","examples":[{"example":"もしも地震が起きたら、まずテーブルの下に隠れてください。","example_reading":"もしもじしんがおきたら、まずテーブルのしたにかくれてください。","example_meaning":"Nếu chẳng may có động đất, trước hết hãy trốn xuống gầm bàn."},{"example":"もしも宝くじが当たったら、世界一周旅行がしたい。","example_reading":"もしもたからくじがあたったら、せかいいちしゅうりょこうがしたい。","example_meaning":"Giả sử trúng xổ số, tôi muốn đi du lịch vòng quanh thế giới."}],"level":"c1"},
{"word":"せめて","reading":"せめて","meaning":"ít nhất thì, chí ít","note":"Đi với ～たい／～てほしい／～てもいい. Diễn tả mức tối thiểu mong muốn.","example":"せめて週末ぐらいはゆっくり休みたい。","example_reading":"せめてしゅうまつぐらいはゆっくりやすみたい。","example_meaning":"Ít nhất thì cuối tuần tôi muốn được nghỉ ngơi thong thả.","examples":[{"example":"せめて週末ぐらいはゆっくり休みたい。","example_reading":"せめてしゅうまつぐらいはゆっくりやすみたい。","example_meaning":"Ít nhất thì cuối tuần tôi muốn được nghỉ ngơi thong thả."},{"example":"忙しくても、せめて連絡ぐらいはしてほしかった。","example_reading":"いそがしくても、せめてれんらくぐらいはしてほしかった。","example_meaning":"Dù bận, chí ít tôi cũng mong bạn liên lạc."}],"level":"c1"},
{"word":"さっぱり","reading":"さっぱり","meaning":"hoàn toàn không (hiểu/được)","antonym":"くよくよ: buồn phiền / むしゃくしゃ: bực bội / ぎとぎと: nhờn dầu mỡ","note":"Đi với phủ định ～ない／～わからない: cảm giác bó tay. Còn nghĩa \"sảng khoái; nhạt thanh\".","example":"先生の説明は難しくて、さっぱりわからなかった。","example_reading":"せんせいのせつめいはむずかしくて、さっぱりわからなかった。","example_meaning":"Thầy giải thích khó quá, tôi chẳng hiểu gì cả.","examples":[{"example":"先生の説明は難しくて、さっぱりわからなかった。","example_reading":"せんせいのせつめいはむずかしくて、さっぱりわからなかった。","example_meaning":"Thầy giải thích khó quá, tôi chẳng hiểu gì cả."},{"example":"営業を始めて半年だが、売り上げはさっぱり伸びない。","example_reading":"えいぎょうをはじめてはんとしだが、うりあげはさっぱりのびない。","example_meaning":"Bắt đầu kinh doanh được nửa năm mà doanh thu chẳng tăng chút nào."}],"level":"c1"},
{"word":"さして","reading":"さして","meaning":"không… lắm, chẳng mấy","note":"Đi với phủ định ～ない. Gần そんなに／大して nhưng thiên về văn viết.","example":"その問題はさして重要ではない。","example_reading":"そのもんだいはさしてじゅうようではない。","example_meaning":"Vấn đề đó không quan trọng lắm.","examples":[{"example":"その問題はさして重要ではない。","example_reading":"そのもんだいはさしてじゅうようではない。","example_meaning":"Vấn đề đó không quan trọng lắm."},{"example":"彼はさして気にする様子もなく、仕事を続けた。","example_reading":"かれはさしてきにするようすもなく、しごとをつづけた。","example_meaning":"Anh ấy chẳng tỏ vẻ bận tâm mấy, tiếp tục làm việc."}],"level":"c1"},
{"word":"かろうじて","reading":"かろうじて","meaning":"vừa vặn, suýt soát, mãi mới","note":"Hay đi với ～た. Chỉ đạt được ở mức tối thiểu, suýt nữa thất bại.","example":"終電に、かろうじて間に合った。","example_reading":"しゅうでんに、かろうじてまにあった。","example_meaning":"Tôi vừa kịp chuyến tàu cuối.","examples":[{"example":"終電に、かろうじて間に合った。","example_reading":"しゅうでんに、かろうじてまにあった。","example_meaning":"Tôi vừa kịp chuyến tàu cuối."},{"example":"彼は、かろうじて合格ラインを超えた。","example_reading":"かれは、かろうじてごうかくラインをこえた。","example_meaning":"Anh ấy vừa đủ vượt qua điểm chuẩn đỗ."}],"level":"c1"},
{"word":"それほど","reading":"それほど","meaning":"không đến mức đó","antonym":"とても: rất","note":"Đi với phủ định ～ない: \"không ～ đến thế\". So với mức vừa được nhắc đến.","example":"台風はそれほど強くなかったので、被害は少なかった。","example_reading":"たいふうはそれほどつよくなかったので、ひがいはすくなかった。","example_meaning":"Bão không mạnh đến thế nên thiệt hại ít.","examples":[{"example":"台風はそれほど強くなかったので、被害は少なかった。","example_reading":"たいふうはそれほどつよくなかったので、ひがいはすくなかった。","example_meaning":"Bão không mạnh đến thế nên thiệt hại ít."},{"example":"彼とはそれほど親しくないので、お願いしにくい。","example_reading":"かれとはそれほどしたしくないので、おねがいしにくい。","example_meaning":"Tôi không thân với anh ấy đến mức đó nên khó nhờ."}],"level":"c1"},
{"word":"大して","reading":"たいして","meaning":"không ... lắm","hanviet":"đại","antonym":"とても: rất","note":"Đi với phủ định ～ない. Mức độ không đáng kể.","example":"この問題は大して難しくないので、すぐ解けるでしょう。","example_reading":"このもんだいはたいしてむずかしくないので、すぐとけるでしょう。","example_meaning":"Bài này không khó lắm nên sẽ giải nhanh thôi.","examples":[{"example":"この問題は大して難しくないので、すぐ解けるでしょう。","example_reading":"このもんだいはたいしてむずかしくないので、すぐとけるでしょう。","example_meaning":"Bài này không khó lắm nên sẽ giải nhanh thôi."},{"example":"私の給料は大して高くないが、生活には困っていない。","example_reading":"わたしのきゅうりょうはたいしてたかくないが、せいかつにはこまっていない。","example_meaning":"Lương tôi không cao lắm nhưng cuộc sống không túng thiếu."}],"level":"c1"},
{"word":"一向に","reading":"いっこうに","meaning":"mãi vẫn không, hoàn toàn không","hanviet":"nhất hướng","note":"Đi với phủ định ～ない. Chờ đợi mà tình hình không cải thiện. Hơi văn viết.","example":"薬を飲み続けているのに、症状は一向によくならない。","example_reading":"くすりをのみつづけているのに、しょうじょうはいっこうによくならない。","example_meaning":"Tôi uống thuốc liên tục mà triệu chứng mãi không khá hơn.","examples":[{"example":"薬を飲み続けているのに、症状は一向によくならない。","example_reading":"くすりをのみつづけているのに、しょうじょうはいっこうによくならない。","example_meaning":"Tôi uống thuốc liên tục mà triệu chứng mãi không khá hơn."},{"example":"彼は私の注意を聞いても、一向に気にする様子がない。","example_reading":"かれはわたしのちゅういをきいても、いっこうにきにするようすがない。","example_meaning":"Dù tôi nhắc, anh ấy hoàn toàn chẳng có vẻ gì bận tâm."}],"level":"c1"},
{"word":"到底","reading":"とうてい","meaning":"không thể nào","hanviet":"đáo để","note":"Đi với phủ định ～ない／～られない／～できない. Nhấn mạnh sự bất khả thi.","example":"今から勉強しても、到底試験には間に合わない。","example_reading":"いまからべんきょうしても、とうていしけんにはまにあわない。","example_meaning":"Bây giờ có học thì cũng không thể nào kịp kỳ thi.","examples":[{"example":"今から勉強しても、到底試験には間に合わない。","example_reading":"いまからべんきょうしても、とうていしけんにはまにあわない。","example_meaning":"Bây giờ có học thì cũng không thể nào kịp kỳ thi."},{"example":"彼の苦しみは、私には到底理解できない。","example_reading":"かれのくるしみは、わたしにはとうていりかいできない。","example_meaning":"Nỗi đau của anh ấy, tôi không thể nào hiểu nổi."}],"level":"c1"},
{"word":"何とも","reading":"なんとも","meaning":"thật là; (không) biết nói sao","hanviet":"hà","note":"Đi với phủ định ～ない: 何とも言えない, 何ともない (chẳng hề hấn gì). Cũng dùng khẳng định nghĩa \"thật là\".","example":"その映画の結末は、何とも言えない気持ちになった。","example_reading":"そのえいがのけつまつは、なんともいえないきもちになった。","example_meaning":"Cái kết bộ phim khiến tôi có cảm giác khó tả.","examples":[{"example":"その映画の結末は、何とも言えない気持ちになった。","example_reading":"そのえいがのけつまつは、なんともいえないきもちになった。","example_meaning":"Cái kết bộ phim khiến tôi có cảm giác khó tả."},{"example":"転んだけれど、怪我は何ともなかった。","example_reading":"ころんだけれど、けがはなんともなかった。","example_meaning":"Tôi ngã nhưng chẳng hề hấn gì."}],"level":"c1"},
{"word":"一度も","reading":"いちども","meaning":"chưa một lần","hanviet":"nhất độ","antonym":"何度も（なんども）: nhiều lần","antonym_hanviet":"hà độ","note":"Đi với phủ định ～ない／～ことがない. Nhấn mạnh chưa từng có.","example":"私は一度も海外に行ったことがない。","example_reading":"わたしはいちどもかいがいにいったことがない。","example_meaning":"Tôi chưa một lần đi nước ngoài.","examples":[{"example":"私は一度も海外に行ったことがない。","example_reading":"わたしはいちどもかいがいにいったことがない。","example_meaning":"Tôi chưa một lần đi nước ngoài."},{"example":"彼は一度も遅刻したことがありません。","example_reading":"かれはいちどもちこくしたことがありません。","example_meaning":"Anh ấy chưa từng đi trễ lần nào."}],"level":"c1"},
{"word":"一つも","reading":"ひとつも","meaning":"không một cái nào","hanviet":"nhất","antonym":"全部（ぜんぶ）: tất cả","antonym_hanviet":"toàn bộ","note":"Đi với phủ định ～ない. Nhấn mạnh hoàn toàn không có.","example":"このテストは、一つも間違えなかった。","example_reading":"このテストは、ひとつもまちがえなかった。","example_meaning":"Bài kiểm tra này tôi không sai câu nào.","examples":[{"example":"このテストは、一つも間違えなかった。","example_reading":"このテストは、ひとつもまちがえなかった。","example_meaning":"Bài kiểm tra này tôi không sai câu nào."},{"example":"冷蔵庫には、食べ物が一つもない。","example_reading":"れいぞうこには、たべものがひとつもない。","example_meaning":"Trong tủ lạnh chẳng có món ăn nào."}],"level":"c1"},
{"word":"何一つ","reading":"なにひとつ","meaning":"không một thứ gì","hanviet":"hà nhất","antonym":"すべて: tất cả","note":"Đi với phủ định ～ない. Đọc なにひとつ. Nhấn mạnh hoàn toàn không có gì; mạnh hơn 何も.","example":"あの人は何一つ文句を言わずに働いた。","example_reading":"あのひとはなにひとつもんくをいわずにはたらいた。","example_meaning":"Người đó làm việc mà không hề than phiền điều gì.","examples":[{"example":"あの人は何一つ文句を言わずに働いた。","example_reading":"あのひとはなにひとつもんくをいわずにはたらいた。","example_meaning":"Người đó làm việc mà không hề than phiền điều gì."},{"example":"彼について、何一つ知らない。","example_reading":"かれについて、なにひとつしらない。","example_meaning":"Về anh ấy tôi chẳng biết gì cả."}],"level":"c1"},
{"word":"二度と","reading":"にどと","meaning":"không bao giờ nữa","hanviet":"nhị độ","antonym":"また: lại","note":"Đi với phủ định ～ない／～まい. Ý quyết tâm không lặp lại.","example":"あんな失敗は二度としないと決めた。","example_reading":"あんなしっぱいはにどとしないときめた。","example_meaning":"Tôi đã quyết sẽ không bao giờ mắc lỗi như vậy nữa.","examples":[{"example":"あんな失敗は二度としないと決めた。","example_reading":"あんなしっぱいはにどとしないときめた。","example_meaning":"Tôi đã quyết sẽ không bao giờ mắc lỗi như vậy nữa."},{"example":"彼とは二度と会うことはないだろう。","example_reading":"かれとはにどとあうことはないだろう。","example_meaning":"Có lẽ tôi sẽ không bao giờ gặp lại anh ấy nữa."}],"level":"c1"},
{"word":"まともに","reading":"まともに","meaning":"đàng hoàng, tử tế; trực diện","antonym":"いい加減に（いいかげんに）: qua loa / でたらめに: bậy bạ","antonym_hanviet":"gia giảm / ","note":"Hay đi với phủ định ～ない: まともに話せない, まともに見られない. Cũng dùng khẳng định nghĩa \"trực diện\" (まともに受ける).","example":"忙しすぎて、最近まともに食事をしていない。","example_reading":"いそがしすぎて、さいきんまともにしょくじをしていない。","example_meaning":"Bận quá nên dạo này tôi không ăn uống tử tế.","examples":[{"example":"忙しすぎて、最近まともに食事をしていない。","example_reading":"いそがしすぎて、さいきんまともにしょくじをしていない。","example_meaning":"Bận quá nên dạo này tôi không ăn uống tử tế."},{"example":"台風が街をまともに直撃した。","example_reading":"たいふうがまちをまともにちょくげきした。","example_meaning":"Bão đánh trực diện vào thành phố."}],"level":"c1"},
{"word":"ことのほか","reading":"ことのほか","meaning":"đặc biệt, hơn dự kiến","note":"Hay đi với 嬉しい, 喜ぶ, 厳しい. Mức độ vượt hơn thông thường.","example":"今年の冬は、ことのほか寒さが厳しい。","example_reading":"ことしのふゆは、ことのほかさむさがきびしい。","example_meaning":"Mùa đông năm nay cái lạnh đặc biệt khắc nghiệt.","examples":[{"example":"今年の冬は、ことのほか寒さが厳しい。","example_reading":"ことしのふゆは、ことのほかさむさがきびしい。","example_meaning":"Mùa đông năm nay cái lạnh đặc biệt khắc nghiệt."},{"example":"孫からの手紙を、祖母はことのほか喜んだ。","example_reading":"まごからのてがみを、そぼはことのほかよろこんだ。","example_meaning":"Bà vô cùng vui mừng với bức thư của cháu."}],"level":"c1"},
{"word":"どうぞ","reading":"どうぞ","meaning":"xin mời, xin hãy","note":"Đi với ～てください／～ください (mời mọc, nhờ vả lịch sự). Dùng khi mời hoặc đề nghị.","example":"どうぞお入りください。","example_reading":"どうぞおはいりください。","example_meaning":"Xin mời vào.","examples":[{"example":"どうぞお入りください。","example_reading":"どうぞおはいりください。","example_meaning":"Xin mời vào."},{"example":"どうぞご自由にお取りください。","example_reading":"どうぞごじゆうにおとりください。","example_meaning":"Xin cứ tự nhiên lấy."}],"level":"c1"},
{"word":"どうにも","reading":"どうにも","meaning":"thật sự (không… được), chẳng thể nào","note":"Đi với phủ định ～ない／～ようがない／～ならない. Diễn tả bất lực.","example":"頭が痛くて、どうにも我慢できない。","example_reading":"あたまがいたくて、どうにもがまんできない。","example_meaning":"Đau đầu đến mức không sao chịu nổi.","examples":[{"example":"頭が痛くて、どうにも我慢できない。","example_reading":"あたまがいたくて、どうにもがまんできない。","example_meaning":"Đau đầu đến mức không sao chịu nổi."},{"example":"事情が複雑で、どうにも説明のしようがない。","example_reading":"じじょうがふくざつで、どうにもせつめいのしようがない。","example_meaning":"Tình hình phức tạp nên thật sự không biết giải thích sao."}],"level":"c1"},
{"word":"別段","reading":"べつだん","meaning":"đặc biệt (không), chẳng gì đặc biệt","hanviet":"biệt đoạn","note":"Đi với phủ định ～ない. Gần 別に nhưng văn viết, trang trọng hơn.","example":"別段変わったことはなかったので、報告しなかった。","example_reading":"べつだんかわったことはなかったので、ほうこくしなかった。","example_meaning":"Không có gì đặc biệt nên tôi đã không báo cáo.","examples":[{"example":"別段変わったことはなかったので、報告しなかった。","example_reading":"べつだんかわったことはなかったので、ほうこくしなかった。","example_meaning":"Không có gì đặc biệt nên tôi đã không báo cáo."},{"example":"そのニュースを聞いても、彼は別段驚いた様子はなかった。","example_reading":"そのニュースをきいても、かれはべつだんおどろいたようすはなかった。","example_meaning":"Nghe tin đó, anh ấy cũng chẳng tỏ vẻ ngạc nhiên gì đặc biệt."}],"level":"c1"},
{"word":"どうか","reading":"どうか","meaning":"xin hãy, làm ơn","note":"Đi với ～てください／～ますように. Lời cầu xin, nhờ vả khẩn thiết.","example":"どうか私の話を最後まで聞いてください。","example_reading":"どうかわたしのはなしをさいごまできいてください。","example_meaning":"Xin hãy nghe tôi nói đến cùng.","examples":[{"example":"どうか私の話を最後まで聞いてください。","example_reading":"どうかわたしのはなしをさいごまできいてください。","example_meaning":"Xin hãy nghe tôi nói đến cùng."},{"example":"どうか明日は晴れますように。","example_reading":"どうかあしたははれますように。","example_meaning":"Mong sao ngày mai trời nắng."}],"level":"c1"},
{"word":"せっかく","reading":"せっかく","meaning":"công sức/dịp hiếm hoi","note":"Đi với ～のに (uổng công, tiếc) hoặc ～から／～のだから (đã có dịp thì nên tận dụng).","example":"せっかく作った料理なのに、誰も食べてくれなかった。","example_reading":"せっかくつくったりょうりなのに、だれもたべてくれなかった。","example_meaning":"Công sức nấu món ăn mà chẳng ai chịu ăn.","examples":[{"example":"せっかく作った料理なのに、誰も食べてくれなかった。","example_reading":"せっかくつくったりょうりなのに、だれもたべてくれなかった。","example_meaning":"Công sức nấu món ăn mà chẳng ai chịu ăn."},{"example":"せっかく京都に来たのだから、お寺を見て帰ろう。","example_reading":"せっかくきょうとにきたのだから、おてらをみてかえろう。","example_meaning":"Đã có dịp đến Kyoto thì xem chùa rồi hãy về."}],"level":"c1"},
{"word":"なぜ","reading":"なぜ","meaning":"tại sao","note":"Đi với câu hỏi ～のか／～だろう. Trả lời bằng ～からだ／なぜなら～からだ. Hay dùng trong văn viết.","example":"なぜ彼は何も言わなかったのだろう。","example_reading":"なぜかれはなにもいわなかったのだろう。","example_meaning":"Tại sao anh ấy lại không nói gì nhỉ.","examples":[{"example":"なぜ彼は何も言わなかったのだろう。","example_reading":"なぜかれはなにもいわなかったのだろう。","example_meaning":"Tại sao anh ấy lại không nói gì nhỉ."},{"example":"なぜ日本語を勉強しようと思ったのですか。","example_reading":"なぜにほんごをべんきょうしようとおもったのですか。","example_meaning":"Vì sao bạn nghĩ đến việc học tiếng Nhật?"}],"level":"c1"},
{"word":"所詮","reading":"しょせん","meaning":"rốt cuộc cũng chỉ là","hanviet":"sở thuyên","note":"Đi với ～に過ぎない／～だ／～ない. Hàm ý rốt cuộc không thể làm gì hơn.","example":"所詮、私一人の力ではどうにもならない。","example_reading":"しょせん、わたしひとりのちからではどうにもならない。","example_meaning":"Rốt cuộc, chỉ với sức một mình tôi thì chẳng làm được gì.","examples":[{"example":"所詮、私一人の力ではどうにもならない。","example_reading":"しょせん、わたしひとりのちからではどうにもならない。","example_meaning":"Rốt cuộc, chỉ với sức một mình tôi thì chẳng làm được gì."},{"example":"彼の言葉は、所詮その場しのぎの言い訳に過ぎない。","example_reading":"かれのことばは、しょせんそのばしのぎのいいわけにすぎない。","example_meaning":"Lời anh ta nói rốt cuộc chỉ là lời bao biện tạm thời."}],"level":"c1"},
{"word":"皆目","reading":"かいもく","meaning":"hoàn toàn (không)","hanviet":"giai mục","note":"Đi với phủ định ～ない: 皆目見当がつかない, 皆目分からない. Nhấn mạnh hoàn toàn không biết.","example":"彼がどこへ行ったのか、皆目見当がつかない。","example_reading":"かれがどこへいったのか、かいもくけんとうがつかない。","example_meaning":"Anh ấy đi đâu thì tôi hoàn toàn không đoán ra.","examples":[{"example":"彼がどこへ行ったのか、皆目見当がつかない。","example_reading":"かれがどこへいったのか、かいもくけんとうがつかない。","example_meaning":"Anh ấy đi đâu thì tôi hoàn toàn không đoán ra."},{"example":"専門用語ばかりで、話の内容が皆目分からなかった。","example_reading":"せんもんようごばかりで、はなしのないようがかいもくわからなかった。","example_meaning":"Toàn thuật ngữ chuyên ngành nên tôi hoàn toàn không hiểu nội dung."}],"level":"c1"},
{"word":"どうも","reading":"どうも","meaning":"cứ cảm thấy, hình như (không chắc)","note":"Đi với ～ようだ／～らしい／～そうだ／～ない. Phán đoán mơ hồ; cũng dùng như lời cảm ơn (どうもありがとう).","example":"どうも風邪をひいたようだ。","example_reading":"どうもかぜをひいたようだ。","example_meaning":"Hình như tôi bị cảm rồi.","examples":[{"example":"どうも風邪をひいたようだ。","example_reading":"どうもかぜをひいたようだ。","example_meaning":"Hình như tôi bị cảm rồi."},{"example":"この問題はどうも納得できない。","example_reading":"このもんだいはどうもなっとくできない。","example_meaning":"Vấn đề này thế nào tôi cũng không thấy thuyết phục."}],"level":"c1"},
{"word":"どうして","reading":"どうして","meaning":"tại sao, sao lại","note":"Đi với câu hỏi ～のか／～んですか. Khẩu ngữ hơn なぜ.","example":"どうして昨日来なかったのですか。","example_reading":"どうしてきのうこなかったのですか。","example_meaning":"Tại sao hôm qua bạn không đến?","examples":[{"example":"どうして昨日来なかったのですか。","example_reading":"どうしてきのうこなかったのですか。","example_meaning":"Tại sao hôm qua bạn không đến?"},{"example":"どうして彼があんなことを言ったのか分からない。","example_reading":"どうしてかれがあんなことをいったのかわからない。","example_meaning":"Tôi không hiểu vì sao anh ấy lại nói như thế."}],"level":"c1"},
{"word":"一体","reading":"いったい","meaning":"rốt cuộc là, cái quái gì","hanviet":"nhất thể","note":"Đi với câu nghi vấn (～か／từ để hỏi). Thể hiện thắc mắc, ngạc nhiên hoặc bực bội mạnh.","example":"一体どこで何をしていたのか、説明しなさい。","example_reading":"いったいどこでなにをしていたのか、せつめいしなさい。","example_meaning":"Rốt cuộc đã ở đâu làm gì, hãy giải thích.","examples":[{"example":"一体どこで何をしていたのか、説明しなさい。","example_reading":"いったいどこでなにをしていたのか、せつめいしなさい。","example_meaning":"Rốt cuộc đã ở đâu làm gì, hãy giải thích."},{"example":"この騒ぎは一体何事ですか。","example_reading":"このさわぎはいったいなにごとですか。","example_meaning":"Ồn ào thế này rốt cuộc là có chuyện gì?"}],"level":"c1"},
{"word":"たかだか","reading":"たかだか","meaning":"cùng lắm, nhiều lắm là","antonym":"少なくとも（すくなくとも）: ít nhất là","antonym_hanviet":"thiểu","note":"Đi với ～だ／～にすぎない／～程度. Giới hạn trên thấp, hàm ý xem nhẹ.","example":"たかだか千円の損で、そんなに怒ることはない。","example_reading":"たかだかせんえんのそんで、そんなにおこることはない。","example_meaning":"Chỉ lỗ cùng lắm nghìn yên thôi, đâu cần giận thế.","examples":[{"example":"たかだか千円の損で、そんなに怒ることはない。","example_reading":"たかだかせんえんのそんで、そんなにおこることはない。","example_meaning":"Chỉ lỗ cùng lắm nghìn yên thôi, đâu cần giận thế."},{"example":"参加者は、多くてもたかだか十人程度だろう。","example_reading":"さんかしゃは、おおくてもたかだかじゅうにんていどだろう。","example_meaning":"Số người tham gia nhiều lắm cũng chỉ khoảng mười người."}],"level":"c1"},
{"word":"よほど","reading":"よほど","meaning":"hẳn là rất, khá là","note":"Đi với ～だろう／～に違いない／～ないと. Phỏng đoán mức độ lớn.","example":"よほど疲れていたのか、彼は帰るとすぐ寝てしまった。","example_reading":"よほどつかれていたのか、かれはかえるとすぐねてしまった。","example_meaning":"Chắc hẳn rất mệt, anh ấy về là ngủ ngay.","examples":[{"example":"よほど疲れていたのか、彼は帰るとすぐ寝てしまった。","example_reading":"よほどつかれていたのか、かれはかえるとすぐねてしまった。","example_meaning":"Chắc hẳn rất mệt, anh ấy về là ngủ ngay."},{"example":"あの店に行くなら、よほど早く行かないと座れない。","example_reading":"あのみせにいくなら、よほどはやくいかないとすわれない。","example_meaning":"Nếu đến quán đó thì phải đi thật sớm mới có chỗ ngồi."}],"level":"c1"},
{"word":"まんざら","reading":"まんざら","meaning":"không hẳn là, cũng chẳng đến nỗi","note":"Đi với phủ định ～ない／～でもない. まんざらでもない = cũng chẳng tệ, khá thích.","example":"彼女は褒められて、まんざらでもない顔をしていた。","example_reading":"かのじょはほめられて、まんざらでもないかおをしていた。","example_meaning":"Được khen, cô ấy có vẻ cũng không phải là không vui.","examples":[{"example":"彼女は褒められて、まんざらでもない顔をしていた。","example_reading":"かのじょはほめられて、まんざらでもないかおをしていた。","example_meaning":"Được khen, cô ấy có vẻ cũng không phải là không vui."},{"example":"この料理の味は、まんざら悪くもない。","example_reading":"このりょうりのあじは、まんざらわるくもない。","example_meaning":"Vị món này cũng không đến nỗi tệ."}],"level":"c1"},
{"word":"もしや","reading":"もしや","meaning":"phải chăng, biết đâu","note":"Đi với ～か／～ではないか／～かもしれない. Mang sắc thái nghi ngờ, lo lắng.","example":"もしや、あの人が犯人ではないかと疑った。","example_reading":"もしや、あのひとがはんにんではないかとうたがった。","example_meaning":"Tôi nghi ngờ phải chăng người đó là thủ phạm.","examples":[{"example":"もしや、あの人が犯人ではないかと疑った。","example_reading":"もしや、あのひとがはんにんではないかとうたがった。","example_meaning":"Tôi nghi ngờ phải chăng người đó là thủ phạm."},{"example":"もしや、私の話を信じていないのですか。","example_reading":"もしや、わたしのはなしをしんじていないのですか。","example_meaning":"Phải chăng bạn không tin lời tôi nói?"}],"level":"c1"},
{"word":"仮に","reading":"かりに","meaning":"giả sử","hanviet":"giả","antonym":"正式に（せいしきに）: chính thức","antonym_hanviet":"chính thức","note":"Đi với ～たら／～としても／～ば. Giả định tạm thời để bàn luận.","example":"仮に今日中に終わらなかったとしても、明日までに仕上げれば問題ない。","example_reading":"かりにきょうじゅうにおわらなかったとしても、あしたまでにしあげればもんだいない。","example_meaning":"Giả sử hôm nay chưa xong thì chỉ cần hoàn thành trước ngày mai là được.","examples":[{"example":"仮に今日中に終わらなかったとしても、明日までに仕上げれば問題ない。","example_reading":"かりにきょうじゅうにおわらなかったとしても、あしたまでにしあげればもんだいない。","example_meaning":"Giả sử hôm nay chưa xong thì chỉ cần hoàn thành trước ngày mai là được."},{"example":"仮にあなたが私の立場だったら、どうしますか。","example_reading":"かりにあなたがわたしのたちばだったら、どうしますか。","example_meaning":"Giả sử bạn ở vị trí của tôi thì bạn sẽ làm gì?"}],"level":"c1"},
{"word":"一切","reading":"いっさい","meaning":"hoàn toàn không, tuyệt nhiên không","hanviet":"nhất thiết","antonym":"全て（すべて）: tất cả","antonym_hanviet":"toàn","note":"Đi với phủ định ～ない. Cũng đi với từ cấm 禁止 (cấm hoàn toàn). Văn viết, biển báo.","example":"当社は、お客様の個人情報を一切外部に出しません。","example_reading":"とうしゃは、おきゃくさまのこじんじょうほうをいっさいがいぶにだしません。","example_meaning":"Công ty chúng tôi tuyệt đối không tiết lộ thông tin cá nhân của khách hàng ra ngoài.","examples":[{"example":"当社は、お客様の個人情報を一切外部に出しません。","example_reading":"とうしゃは、おきゃくさまのこじんじょうほうをいっさいがいぶにだしません。","example_meaning":"Công ty chúng tôi tuyệt đối không tiết lộ thông tin cá nhân của khách hàng ra ngoài."},{"example":"館内では、飲食は一切禁止されています。","example_reading":"かんないでは、いんしょくはいっさいきんしされています。","example_meaning":"Trong tòa nhà nghiêm cấm hoàn toàn việc ăn uống."}],"level":"c1"},
{"word":"今さら","reading":"いまさら","meaning":"đến giờ này mới, bây giờ mới","hanviet":"kim","note":"Đi với ～ても／～ない. Quá muộn, vô ích.","example":"今さら謝っても、もう遅い。","example_reading":"いまさらあやまっても、もうおそい。","example_meaning":"Giờ mới xin lỗi thì đã muộn.","examples":[{"example":"今さら謝っても、もう遅い。","example_reading":"いまさらあやまっても、もうおそい。","example_meaning":"Giờ mới xin lỗi thì đã muộn."},{"example":"今さら後悔しても仕方がない。","example_reading":"いまさらこうかいしてもしかたがない。","example_meaning":"Giờ có hối hận cũng chẳng ích gì."}],"level":"c1"},
{"word":"かつて","reading":"かつて","meaning":"từng, ngày trước","antonym":"今後（こんご）: sau này / 今や（いまや）: giờ đây","antonym_hanviet":"kim hậu / kim","note":"Đi với ～た／～ていた (từng ～) hoặc ～たことがない (chưa từng). Văn viết.","example":"この町はかつて炭鉱で栄えていた。","example_reading":"このまちはかつてたんこうでさかえていた。","example_meaning":"Thị trấn này ngày trước từng thịnh vượng nhờ mỏ than.","examples":[{"example":"この町はかつて炭鉱で栄えていた。","example_reading":"このまちはかつてたんこうでさかえていた。","example_meaning":"Thị trấn này ngày trước từng thịnh vượng nhờ mỏ than."},{"example":"彼ほど優れた選手は、かつて見たことがない。","example_reading":"かれほどすぐれたせんしゅは、かつてみたことがない。","example_meaning":"Tôi chưa từng thấy cầu thủ nào xuất sắc như anh ấy."}],"level":"c1"},
{"word":"さぞかし","reading":"さぞかし","meaning":"hẳn là, chắc hẳn","note":"Đi với ～だろう／～でしょう. Suy đoán thể hiện sự cảm thông. Mạnh hơn さぞ.","example":"長旅で、さぞかしお疲れでしょう。","example_reading":"ながたびで、さぞかしおつかれでしょう。","example_meaning":"Đi đường dài, chắc hẳn anh/chị mệt lắm.","examples":[{"example":"長旅で、さぞかしお疲れでしょう。","example_reading":"ながたびで、さぞかしおつかれでしょう。","example_meaning":"Đi đường dài, chắc hẳn anh/chị mệt lắm."},{"example":"合格の知らせに、ご両親もさぞかしお喜びだろう。","example_reading":"ごうかくのしらせに、ごりょうしんもさぞかしおよろこびだろう。","example_meaning":"Nghe tin đỗ, bố mẹ chắc hẳn rất vui."}],"level":"c1"},
{"word":"みすみす","reading":"みすみす","meaning":"trơ mắt nhìn, đành để mất","note":"Đi với 逃す, 失う, ～わけにはいかない. Thấy rõ mà không ngăn được hoặc không làm gì.","example":"目の前のチャンスを、みすみす逃すわけにはいかない。","example_reading":"めのまえのチャンスを、みすみすのがすわけにはいかない。","example_meaning":"Không thể trơ mắt để vuột mất cơ hội ngay trước mắt.","examples":[{"example":"目の前のチャンスを、みすみす逃すわけにはいかない。","example_reading":"めのまえのチャンスを、みすみすのがすわけにはいかない。","example_meaning":"Không thể trơ mắt để vuột mất cơ hội ngay trước mắt."},{"example":"危険だと分かっていながら、みすみす部下を行かせてしまった。","example_reading":"きけんだとわかっていながら、みすみすぶかをいかせてしまった。","example_meaning":"Biết rõ là nguy hiểm mà tôi vẫn đành để cấp dưới đi."}],"level":"c1"},
{"word":"もはや","reading":"もはや","meaning":"giờ đây đã (không còn)","antonym":"いまだに: vẫn còn","note":"Đi với ～ない／～だ. Tình hình đã đến mức không thể quay lại. Văn viết.","example":"もはや、私たちにできることは何もない。","example_reading":"もはや、わたしたちにできることはなにもない。","example_meaning":"Giờ đây chúng ta không còn làm được gì nữa.","examples":[{"example":"もはや、私たちにできることは何もない。","example_reading":"もはや、わたしたちにできることはなにもない。","example_meaning":"Giờ đây chúng ta không còn làm được gì nữa."},{"example":"彼の実力は、もはや日本一と言っても過言ではない。","example_reading":"かれのじつりょくは、もはやにほんいちといってもかごんではない。","example_meaning":"Thực lực của anh ấy giờ nói là số một Nhật Bản cũng không ngoa."}],"level":"c1"},
{"word":"万一","reading":"まんいち","meaning":"nếu chẳng may","hanviet":"vạn nhất","note":"Đi với ～たら／～の場合は／～ときのために. Khả năng cực thấp, dùng để dự phòng.","example":"万一、道に迷った場合は、この番号に電話してください。","example_reading":"まんいち、みちにまよったばあいは、このばんごうにでんわしてください。","example_meaning":"Nếu chẳng may bị lạc đường, hãy gọi số này.","examples":[{"example":"万一、道に迷った場合は、この番号に電話してください。","example_reading":"まんいち、みちにまよったばあいは、このばんごうにでんわしてください。","example_meaning":"Nếu chẳng may bị lạc đường, hãy gọi số này."},{"example":"万一事故が起きたときのために、保険に入っておく。","example_reading":"まんいちじこがおきたときのために、ほけんにはいっておく。","example_meaning":"Tôi mua bảo hiểm để phòng khi chẳng may có tai nạn."}],"level":"c1"},
{"word":"ひとたび","reading":"ひとたび","meaning":"một khi đã","note":"Đi với ～と／～ば／～たら. Nêu điều kiện dẫn đến hệ quả lớn.","example":"ひとたび火が付けば、乾燥した森は一気に燃え広がる。","example_reading":"ひとたびひがつけば、かんそうしたもりはいっきにもえひろがる。","example_meaning":"Một khi lửa bén, khu rừng khô sẽ cháy lan ngay.","examples":[{"example":"ひとたび火が付けば、乾燥した森は一気に燃え広がる。","example_reading":"ひとたびひがつけば、かんそうしたもりはいっきにもえひろがる。","example_meaning":"Một khi lửa bén, khu rừng khô sẽ cháy lan ngay."},{"example":"彼はひとたび怒り出すと、誰にも止められない。","example_reading":"かれはひとたびおこりだすと、だれにもとめられない。","example_meaning":"Một khi anh ấy đã nổi giận thì không ai cản được."}],"level":"c1"},
{"word":"何だか","reading":"なんだか","meaning":"không hiểu sao, cứ thấy","hanviet":"hà","note":"Đi với ～気がする／～ようだ／～そうだ. Cảm giác mơ hồ không rõ lý do. Đọc なんだか.","example":"今日は何だか体がだるい。","example_reading":"きょうはなんだかからだがだるい。","example_meaning":"Hôm nay không hiểu sao người cứ uể oải.","examples":[{"example":"今日は何だか体がだるい。","example_reading":"きょうはなんだかからだがだるい。","example_meaning":"Hôm nay không hiểu sao người cứ uể oải."},{"example":"何だか彼に嫌われているような気がする。","example_reading":"なんだかかれにきらわれているようなきがする。","example_meaning":"Không hiểu sao tôi cứ có cảm giác bị anh ấy ghét."}],"level":"c1"},
{"word":"何分","reading":"なにぶん","meaning":"dù sao thì, xin thông cảm là","hanviet":"hà phân","note":"Hay đi với ～ので／～ですから hoặc よろしくお願いします. Lời xin thông cảm hoặc nhờ cậy, trang trọng.","example":"何分初めてのことなので、不慣れな点はお許しください。","example_reading":"なにぶんはじめてのことなので、ふなれなてんはおゆるしください。","example_meaning":"Vì dù sao cũng là lần đầu, mong thông cảm những điểm chưa quen.","examples":[{"example":"何分初めてのことなので、不慣れな点はお許しください。","example_reading":"なにぶんはじめてのことなので、ふなれなてんはおゆるしください。","example_meaning":"Vì dù sao cũng là lần đầu, mong thông cảm những điểm chưa quen."},{"example":"何分よろしくお願いいたします。","example_reading":"なにぶんよろしくおねがいいたします。","example_meaning":"Xin nhờ cậy mong anh/chị giúp đỡ cho."}],"level":"c1"},
{"word":"たかが","reading":"たかが","meaning":"chỉ là, chẳng qua","note":"Đi với ～に過ぎない／～くらいで／～ごとき. Xem nhẹ sự việc.","example":"たかがゲームに負けたくらいで、泣くことはない。","example_reading":"たかがゲームにまけたくらいで、なくことはない。","example_meaning":"Chỉ thua một ván game thôi mà, đâu cần khóc.","examples":[{"example":"たかがゲームに負けたくらいで、泣くことはない。","example_reading":"たかがゲームにまけたくらいで、なくことはない。","example_meaning":"Chỉ thua một ván game thôi mà, đâu cần khóc."},{"example":"たかが一度の失敗で、全てが終わるわけではない。","example_reading":"たかがいちどのしっぱいで、すべてがおわるわけではない。","example_meaning":"Chỉ một lần thất bại thì đâu phải là hết tất cả."}],"level":"c1"},
{"word":"万が一","reading":"まんがいち","meaning":"nhỡ mà, lỡ như","hanviet":"vạn nhất","note":"Đi với ～た場合／～ても／～ときのために. Giả định xác suất cực nhỏ; gần nghĩa 万一.","example":"万が一、火事になったら、すぐに逃げてください。","example_reading":"まんがいち、かじになったら、すぐににげてください。","example_meaning":"Nhỡ có hỏa hoạn thì hãy chạy ngay.","examples":[{"example":"万が一、火事になったら、すぐに逃げてください。","example_reading":"まんがいち、かじになったら、すぐににげてください。","example_meaning":"Nhỡ có hỏa hoạn thì hãy chạy ngay."},{"example":"万が一に備えて、保険に入っておいた。","example_reading":"まんがいちにそなえて、ほけんにはいっておいた。","example_meaning":"Tôi đã mua bảo hiểm để phòng khi bất trắc."}],"level":"c1"},
{"word":"あえて","reading":"あえて","meaning":"cố tình, dám","note":"Đi với ～する (cố làm dù biết khó/trái thông thường) hoặc ～ない (không nhất thiết phải). Văn viết, trang trọng.","example":"友人のためを思って、あえて厳しいことを言った。","example_reading":"ゆうじんのためをおもって、あえてきびしいことをいった。","example_meaning":"Vì nghĩ cho bạn, tôi đã cố tình nói những điều nghiêm khắc.","examples":[{"example":"友人のためを思って、あえて厳しいことを言った。","example_reading":"ゆうじんのためをおもって、あえてきびしいことをいった。","example_meaning":"Vì nghĩ cho bạn, tôi đã cố tình nói những điều nghiêm khắc."},{"example":"今さらあえて反論するつもりはありません。","example_reading":"いまさらあえてはんろんするつもりはありません。","example_meaning":"Đến giờ tôi không định cố phản bác nữa."}],"level":"c1"},
{"word":"一概に","reading":"いちがいに","meaning":"nói chung chung, đánh đồng","hanviet":"nhất khái","note":"Đi với phủ định ～ない／～とは言えない／～てはいけない: \"không thể đánh đồng ～\".","example":"若者が全員そうだとは、一概には言えない。","example_reading":"わかものがぜんいんそうだとは、いちがいにはいえない。","example_meaning":"Không thể đánh đồng rằng tất cả giới trẻ đều như vậy.","examples":[{"example":"若者が全員そうだとは、一概には言えない。","example_reading":"わかものがぜんいんそうだとは、いちがいにはいえない。","example_meaning":"Không thể đánh đồng rằng tất cả giới trẻ đều như vậy."},{"example":"大企業のほうが安定していると一概に決めつけてはいけない。","example_reading":"だいきぎょうのほうがあんていしているといちがいにきめつけてはいけない。","example_meaning":"Không nên đánh đồng rằng công ty lớn thì ổn định hơn."}],"level":"c1"},
{"word":"ひとえに","reading":"ひとえに","meaning":"hoàn toàn là nhờ, chỉ vì","note":"Đi với ～のおかげだ／～による／～責任だ. Nêu nguyên nhân duy nhất.","example":"今回の成功は、ひとえに皆様のご協力のおかげです。","example_reading":"こんかいのせいこうは、ひとえにみなさまのごきょうりょくのおかげです。","example_meaning":"Thành công lần này hoàn toàn là nhờ sự hợp tác của mọi người.","examples":[{"example":"今回の成功は、ひとえに皆様のご協力のおかげです。","example_reading":"こんかいのせいこうは、ひとえにみなさまのごきょうりょくのおかげです。","example_meaning":"Thành công lần này hoàn toàn là nhờ sự hợp tác của mọi người."},{"example":"この失敗は、ひとえに私の責任です。","example_reading":"このしっぱいは、ひとえにわたしのせきにんです。","example_meaning":"Thất bại này hoàn toàn là trách nhiệm của tôi."}],"level":"c1"},
{"word":"微塵も","reading":"みじんも","meaning":"dù một chút cũng (không)","hanviet":"vi trần","note":"Đi với phủ định ～ない. Nhấn mạnh hoàn toàn không, mạnh hơn 少しも.","example":"彼は反省する様子を微塵も見せなかった。","example_reading":"かれははんせいするようすをみじんもみせなかった。","example_meaning":"Anh ta không hề tỏ ra chút hối lỗi nào.","examples":[{"example":"彼は反省する様子を微塵も見せなかった。","example_reading":"かれははんせいするようすをみじんもみせなかった。","example_meaning":"Anh ta không hề tỏ ra chút hối lỗi nào."},{"example":"負けるなんて、微塵も考えていなかった。","example_reading":"まけるなんて、みじんもかんがえていなかった。","example_meaning":"Tôi chưa từng nghĩ đến chuyện thua, dù chỉ một chút."}],"level":"c1"},
{"word":"さほど","reading":"さほど","meaning":"không ... lắm","antonym":"とても: rất","note":"Đi với phủ định ～ない. Văn viết hơn それほど.","example":"今年の冬は、さほど寒くならなかった。","example_reading":"ことしのふゆは、さほどさむくならなかった。","example_meaning":"Mùa đông năm nay không lạnh lắm.","examples":[{"example":"今年の冬は、さほど寒くならなかった。","example_reading":"ことしのふゆは、さほどさむくならなかった。","example_meaning":"Mùa đông năm nay không lạnh lắm."},{"example":"この件は、さほど急ぐ必要はありません。","example_reading":"このけんは、さほどいそぐひつようはありません。","example_meaning":"Việc này không cần gấp lắm."}],"level":"c1"},
{"word":"ろくに","reading":"ろくに","meaning":"không ra hồn, chẳng ... nổi","note":"Đi với phủ định ～ない. Làm không đầy đủ, sơ sài; thường mang ý chê trách.","example":"昨日は忙しくて、ろくに食事もできなかった。","example_reading":"きのうはいそがしくて、ろくにしょくじもできなかった。","example_meaning":"Hôm qua bận quá, tôi chẳng ăn uống tử tế được.","examples":[{"example":"昨日は忙しくて、ろくに食事もできなかった。","example_reading":"きのうはいそがしくて、ろくにしょくじもできなかった。","example_meaning":"Hôm qua bận quá, tôi chẳng ăn uống tử tế được."},{"example":"彼は挨拶もろくにしないで、帰ってしまった。","example_reading":"かれはあいさつもろくにしないで、かえってしまった。","example_meaning":"Anh ta chào hỏi cũng không ra hồn rồi về mất."}],"level":"c1"},
{"word":"一度たりとも","reading":"いちどたりとも","meaning":"dù một lần cũng (không)","hanviet":"nhất độ","note":"Đi với phủ định ～ない. Nhấn mạnh hoàn toàn chưa từng.","example":"彼は、一度たりとも約束を破ったことがない。","example_reading":"かれは、いちどたりともやくそくをやぶったことがない。","example_meaning":"Anh ấy chưa từng thất hứa dù chỉ một lần.","examples":[{"example":"彼は、一度たりとも約束を破ったことがない。","example_reading":"かれは、いちどたりともやくそくをやぶったことがない。","example_meaning":"Anh ấy chưa từng thất hứa dù chỉ một lần."},{"example":"この十年、一度たりとも学校を休まなかった。","example_reading":"このじゅうねん、いちどたりともがっこうをやすまなかった。","example_meaning":"Mười năm qua, tôi chưa nghỉ học lần nào."}],"level":"c1"},
{"word":"殊更","reading":"ことさら","meaning":"cố tình; đặc biệt","hanviet":"thù cánh","note":"Đi với ～する／～に: 殊更強調する, 殊更に～ない. Cố ý làm nổi bật, hoặc \"đặc biệt hơn thường lệ\".","example":"彼は自分の功績を殊更に強調しようとはしなかった。","example_reading":"かれはじぶんのこうせきをことさらにきょうちょうしようとはしなかった。","example_meaning":"Anh ấy không cố tình nhấn mạnh thành tích của mình.","examples":[{"example":"彼は自分の功績を殊更に強調しようとはしなかった。","example_reading":"かれはじぶんのこうせきをことさらにきょうちょうしようとはしなかった。","example_meaning":"Anh ấy không cố tình nhấn mạnh thành tích của mình."},{"example":"今年の冬は、殊更寒さが身にしみる。","example_reading":"ことしのふゆは、ことさらさむさがみにしみる。","example_meaning":"Mùa đông năm nay cái lạnh càng thấm vào người đặc biệt."}],"level":"c1"},
{"word":"まして","reading":"まして","meaning":"huống hồ, huống chi","note":"Đi với ～は／～なら／～ない. Vế sau mạnh hơn vế trước.","example":"大人でも難しいのに、まして子どもにできるはずがない。","example_reading":"おとなでもむずかしいのに、ましてこどもにできるはずがない。","example_meaning":"Người lớn còn thấy khó, huống hồ trẻ con thì không thể làm được.","examples":[{"example":"大人でも難しいのに、まして子どもにできるはずがない。","example_reading":"おとなでもむずかしいのに、ましてこどもにできるはずがない。","example_meaning":"Người lớn còn thấy khó, huống hồ trẻ con thì không thể làm được."},{"example":"漢字は日本人でも間違えるのだから、まして外国人なら当然だ。","example_reading":"かんじはにほんにんでもまちがえるのだから、ましてがいこくにんならとうぜんだ。","example_meaning":"Người Nhật còn viết sai chữ Hán, huống chi người nước ngoài thì đương nhiên."}],"level":"c1"},
{"word":"いっそ","reading":"いっそ","meaning":"thà (là)","note":"Đi với ～ほうがいい／～ようか／～(よ)う. Chọn phương án cực đoan khi tiến thoái lưỡng nan.","example":"こんなに待たされるなら、いっそ帰ってしまおうか。","example_reading":"こんなにまたされるなら、いっそかえってしまおうか。","example_meaning":"Bị bắt chờ lâu thế này, thà về luôn cho rồi.","examples":[{"example":"こんなに待たされるなら、いっそ帰ってしまおうか。","example_reading":"こんなにまたされるなら、いっそかえってしまおうか。","example_meaning":"Bị bắt chờ lâu thế này, thà về luôn cho rồi."},{"example":"中途半端にやるくらいなら、いっそやめたほうがいい。","example_reading":"ちゅうとはんぱにやるくらいなら、いっそやめたほうがいい。","example_meaning":"Thà bỏ hẳn còn hơn làm dở dang."}],"level":"c1"},
{"word":"いささかも","reading":"いささかも","meaning":"chút nào cũng (không)","note":"Đi với phủ định ～ない. Văn viết, trang trọng.","example":"彼の決意は、いささかも揺らぐことがなかった。","example_reading":"かれのけついは、いささかもゆらぐことがなかった。","example_meaning":"Quyết tâm của anh ấy không hề lung lay chút nào.","examples":[{"example":"彼の決意は、いささかも揺らぐことがなかった。","example_reading":"かれのけついは、いささかもゆらぐことがなかった。","example_meaning":"Quyết tâm của anh ấy không hề lung lay chút nào."},{"example":"私は、彼の言葉をいささかも疑っていない。","example_reading":"わたしは、かれのことばをいささかもうたがっていない。","example_meaning":"Tôi không nghi ngờ lời anh ấy chút nào."}],"level":"c1"},
{"word":"危うく","reading":"あやうく","meaning":"suýt nữa","hanviet":"nguy","note":"Đi với ～ところだった／～そうになった. Suýt xảy ra chuyện không hay.","example":"寝坊して、危うく飛行機に乗り遅れるところだった。","example_reading":"ねぼうして、あやうくひこうきにのりおくれるところだった。","example_meaning":"Tôi ngủ quên, suýt nữa thì lỡ chuyến bay.","examples":[{"example":"寝坊して、危うく飛行機に乗り遅れるところだった。","example_reading":"ねぼうして、あやうくひこうきにのりおくれるところだった。","example_meaning":"Tôi ngủ quên, suýt nữa thì lỡ chuyến bay."},{"example":"子どもが道に飛び出して、危うく車にひかれそうになった。","example_reading":"こどもがみちにとびだして、あやうくくるまにひかれそうになった。","example_meaning":"Đứa trẻ lao ra đường, suýt bị xe đâm."}],"level":"c1"},
{"word":"さながら","reading":"さながら","meaning":"hệt như, y như","note":"Đi với ～のようだ／～のごとく／～かのようだ. Văn chương, dùng so sánh.","example":"夜の海は、さながら黒い鏡のようだった。","example_reading":"よるのうみは、さながらくろいかがみのようだった。","example_meaning":"Biển đêm hệt như một tấm gương đen.","examples":[{"example":"夜の海は、さながら黒い鏡のようだった。","example_reading":"よるのうみは、さながらくろいかがみのようだった。","example_meaning":"Biển đêm hệt như một tấm gương đen."},{"example":"彼の演説は、さながら詩を朗読するかのようだった。","example_reading":"かれのえんぜつは、さながらしをろうどくするかのようだった。","example_meaning":"Bài diễn thuyết của anh ấy hệt như đang ngâm một bài thơ."}],"level":"c1"},
{"word":"むざむざ","reading":"むざむざ","meaning":"uổng phí, đành bó tay để mất","note":"Đi với ～と／～逃す／～失う／～やられる. Để mất một cách đáng tiếc hoặc không kháng cự.","example":"目の前で、むざむざと財産を奪われてしまった。","example_reading":"めのまえで、むざむざとざいさんをうばわれてしまった。","example_meaning":"Ngay trước mắt, tài sản bị cướp mất mà không làm gì được.","examples":[{"example":"目の前で、むざむざと財産を奪われてしまった。","example_reading":"めのまえで、むざむざとざいさんをうばわれてしまった。","example_meaning":"Ngay trước mắt, tài sản bị cướp mất mà không làm gì được."},{"example":"勝てる試合を、むざむざと落としてしまった。","example_reading":"かてるしあいを、むざむざとおとしてしまった。","example_meaning":"Tôi đã đánh mất một cách đáng tiếc trận đấu lẽ ra thắng được."}],"level":"c1"},
{"word":"仮にも","reading":"かりにも","meaning":"dù sao cũng là, đã là","hanviet":"giả","note":"Đi với ～なのだから／～たる者／～べきではない. Nhấn mạnh phải giữ phẩm cách đúng với vị trí đang có.","example":"仮にも教師なのだから、生徒の前でそんな言葉を使うべきではない。","example_reading":"かりにもきょうしなのだから、せいとのまえでそんなことばをつかうべきではない。","example_meaning":"Dù sao cũng là giáo viên, không nên dùng lời lẽ như vậy trước học sinh.","examples":[{"example":"仮にも教師なのだから、生徒の前でそんな言葉を使うべきではない。","example_reading":"かりにもきょうしなのだから、せいとのまえでそんなことばをつかうべきではない。","example_meaning":"Dù sao cũng là giáo viên, không nên dùng lời lẽ như vậy trước học sinh."},{"example":"仮にも社長が約束を破るなど、あってはならない。","example_reading":"かりにもしゃちょうがやくそくをやぶるなど、あってはならない。","example_meaning":"Đã là giám đốc thì không được phép thất hứa."}],"level":"c1"},
{"word":"いかんせん","reading":"いかんせん","meaning":"khổ nỗi, đáng tiếc là","note":"Hay đi với ～ない／～が足りない. Nêu lý do khiến điều mong muốn không thể thực hiện. Trang trọng, hơi cứng.","example":"やりたい気持ちはあるが、いかんせん時間が足りない。","example_reading":"やりたいきもちはあるが、いかんせんじかんがたりない。","example_meaning":"Tôi muốn làm lắm nhưng khổ nỗi không đủ thời gian.","examples":[{"example":"やりたい気持ちはあるが、いかんせん時間が足りない。","example_reading":"やりたいきもちはあるが、いかんせんじかんがたりない。","example_meaning":"Tôi muốn làm lắm nhưng khổ nỗi không đủ thời gian."},{"example":"いい案だと思うが、いかんせん予算がない。","example_reading":"いいあんだとおもうが、いかんせんよさんがない。","example_meaning":"Tôi nghĩ là phương án hay, nhưng tiếc là không có ngân sách."}],"level":"c1"},
{"word":"一見","reading":"いっけん","meaning":"thoạt nhìn","hanviet":"nhất kiến","antonym":"実は（じつは）: thật ra","antonym_hanviet":"thực","note":"Đi với ～ようだ／～が、実は～. Ấn tượng ban đầu, thường đối lập với thực tế.","example":"この店は一見高そうだが、実は安い。","example_reading":"このみせはいっけんたかそうだが、じつはやすい。","example_meaning":"Quán này thoạt nhìn có vẻ đắt nhưng thực ra rẻ.","examples":[{"example":"この店は一見高そうだが、実は安い。","example_reading":"このみせはいっけんたかそうだが、じつはやすい。","example_meaning":"Quán này thoạt nhìn có vẻ đắt nhưng thực ra rẻ."},{"example":"彼は一見冷たいようで、本当は優しい人だ。","example_reading":"かれはいっけんつめたいようで、ほんとうはやさしいひとだ。","example_meaning":"Anh ấy thoạt nhìn có vẻ lạnh lùng nhưng thật ra là người tốt."}],"level":"c1"},
{"word":"夢にも","reading":"ゆめにも","meaning":"dù trong mơ cũng không (nghĩ tới)","hanviet":"mộng","note":"Đi với 思わない／考えない／思っていなかった. Hoàn toàn không ngờ tới.","example":"こんな結果になるとは、夢にも思わなかった。","example_reading":"こんなけっかになるとは、ゆめにもおもわなかった。","example_meaning":"Tôi không bao giờ ngờ lại ra kết quả thế này.","examples":[{"example":"こんな結果になるとは、夢にも思わなかった。","example_reading":"こんなけっかになるとは、ゆめにもおもわなかった。","example_meaning":"Tôi không bao giờ ngờ lại ra kết quả thế này."},{"example":"彼が嘘をついているなんて、夢にも考えなかった。","example_reading":"かれがうそをついているなんて、ゆめにもかんがえなかった。","example_meaning":"Tôi chưa từng nghĩ anh ta lại nói dối."}],"level":"c1"},
{"word":"果たして","reading":"はたして","meaning":"rốt cuộc liệu có, quả nhiên","hanviet":"quả","note":"Đi với ～か／～だろうか (nghi vấn về kết quả thực tế). Đi với ～た thì nghĩa \"quả nhiên\". Văn viết.","example":"彼の計画は、果たして成功するだろうか。","example_reading":"かれのけいかくは、はたしてせいこうするだろうか。","example_meaning":"Kế hoạch của anh ấy rốt cuộc liệu có thành công không?","examples":[{"example":"彼の計画は、果たして成功するだろうか。","example_reading":"かれのけいかくは、はたしてせいこうするだろうか。","example_meaning":"Kế hoạch của anh ấy rốt cuộc liệu có thành công không?"},{"example":"噂の新製品は、果たして期待どおりの性能だった。","example_reading":"うわさのしんせいひんは、はたしてきたいどおりのせいのうだった。","example_meaning":"Sản phẩm mới được đồn đại quả nhiên có tính năng như mong đợi."}],"level":"c1"},
{"word":"寸分","reading":"すんぶん","meaning":"dù một chút (không sai lệch)","hanviet":"thốn phân","note":"Hay đi với 寸分違わず, 寸分の狂いもなく. Rất chính xác, không sai lệch.","example":"彼の予想は、結果と寸分違わず一致した。","example_reading":"かれのよそうは、けっかとすんぶんたがわずいっちした。","example_meaning":"Dự đoán của anh ấy khớp với kết quả không sai chút nào.","examples":[{"example":"彼の予想は、結果と寸分違わず一致した。","example_reading":"かれのよそうは、けっかとすんぶんたがわずいっちした。","example_meaning":"Dự đoán của anh ấy khớp với kết quả không sai chút nào."},{"example":"この機械は、寸分の狂いもなく部品を組み立てる。","example_reading":"このきかいは、すんぶんのくるいもなくぶひんをくみたてる。","example_meaning":"Chiếc máy này lắp ráp linh kiện chính xác tuyệt đối."}],"level":"c1"},
{"word":"まるっきり","reading":"まるっきり","meaning":"hoàn toàn không","note":"Đi với phủ định ～ない. Khẩu ngữ, dạng nhấn mạnh của まるで／全然.","example":"英語はまるっきり話せません。","example_reading":"えいごはまるっきりはなせません。","example_meaning":"Tiếng Anh thì tôi hoàn toàn không nói được.","examples":[{"example":"英語はまるっきり話せません。","example_reading":"えいごはまるっきりはなせません。","example_meaning":"Tiếng Anh thì tôi hoàn toàn không nói được."},{"example":"初めて聞く話で、まるっきり見当がつかない。","example_reading":"はじめてきくはなしで、まるっきりけんとうがつかない。","example_meaning":"Chuyện lần đầu nghe nên tôi hoàn toàn không đoán ra được."}],"level":"c1"},
{"word":"てんで","reading":"てんで","meaning":"hoàn toàn không, chẳng hề","note":"Đi với phủ định ～ない (hoặc てんでだめ). Khẩu ngữ, hơi thiếu tôn trọng.","example":"弟は私の忠告など、てんで聞こうとしない。","example_reading":"おとうとはわたしのちゅうこくなど、てんできこうとしない。","example_meaning":"Em trai tôi chẳng buồn nghe lời khuyên của tôi.","examples":[{"example":"弟は私の忠告など、てんで聞こうとしない。","example_reading":"おとうとはわたしのちゅうこくなど、てんできこうとしない。","example_meaning":"Em trai tôi chẳng buồn nghe lời khuyên của tôi."},{"example":"数学はてんでだめで、毎回赤点だ。","example_reading":"すうがくはてんでだめで、まいかいせきてんだ。","example_meaning":"Môn toán tôi dở tệ, lần nào cũng bị điểm liệt."}],"level":"c1"},
{"word":"あわよくば","reading":"あわよくば","meaning":"nếu may mắn, biết đâu được","note":"Đi với ～たい／～ようとする／～と思う. Mong nhân cơ hội thuận lợi để đạt thêm điều gì.","example":"あわよくば、優勝を狙いたいと思っている。","example_reading":"あわよくば、ゆうしょうをねらいたいとおもっている。","example_meaning":"Nếu may mắn, tôi muốn nhắm tới chức vô địch.","examples":[{"example":"あわよくば、優勝を狙いたいと思っている。","example_reading":"あわよくば、ゆうしょうをねらいたいとおもっている。","example_meaning":"Nếu may mắn, tôi muốn nhắm tới chức vô địch."},{"example":"彼はあわよくば社長の座を手に入れようとしていた。","example_reading":"かれはあわよくばしゃちょうのざをてにいれようとしていた。","example_meaning":"Anh ta mưu tính nếu có cơ hội sẽ giành lấy ghế giám đốc."}],"level":"c1"},
{"word":"ついぞ","reading":"ついぞ","meaning":"chưa từng, suốt từ trước đến nay không","note":"Đi với phủ định ～ない／～たことがない. Văn viết, hơi cổ.","example":"彼が怒った顔など、ついぞ見たことがない。","example_reading":"かれがおこったかおなど、ついぞみたことがない。","example_meaning":"Tôi chưa từng thấy bộ mặt giận dữ của anh ấy.","examples":[{"example":"彼が怒った顔など、ついぞ見たことがない。","example_reading":"かれがおこったかおなど、ついぞみたことがない。","example_meaning":"Tôi chưa từng thấy bộ mặt giận dữ của anh ấy."},{"example":"長年住んでいるが、そんなうわさはついぞ聞かなかった。","example_reading":"ながねんすんでいるが、そんなうわさはついぞきかなかった。","example_meaning":"Sống nhiều năm rồi nhưng tôi chưa từng nghe tin đồn như vậy."}],"level":"c1"},
{"word":"おいそれと","reading":"おいそれと","meaning":"dễ dàng (không thể), không dễ gì","note":"Đi với phủ định ～ない. Không thể làm ngay vì phải cân nhắc kỹ.","example":"こんな高い買い物は、おいそれと決められない。","example_reading":"こんなたかいかいものは、おいそれときめられない。","example_meaning":"Một món mua đắt thế này, không thể dễ dàng quyết định.","examples":[{"example":"こんな高い買い物は、おいそれと決められない。","example_reading":"こんなたかいかいものは、おいそれときめられない。","example_meaning":"Một món mua đắt thế này, không thể dễ dàng quyết định."},{"example":"重要な情報は、おいそれと他人には教えられない。","example_reading":"じゅうようなじょうほうは、おいそれとたにんにはおしえられない。","example_meaning":"Thông tin quan trọng thì không thể tùy tiện nói cho người khác."}],"level":"c1"},
{"word":"微動だに","reading":"びどうだに","meaning":"không nhúc nhích dù chút","hanviet":"vi động","note":"Đi với しない／せず／しなかった. Hoàn toàn bất động.","example":"兵士は、微動だにせず立ち続けていた。","example_reading":"へいしは、びどうだにせずたちつづけていた。","example_meaning":"Người lính đứng bất động không hề nhúc nhích.","examples":[{"example":"兵士は、微動だにせず立ち続けていた。","example_reading":"へいしは、びどうだにせずたちつづけていた。","example_meaning":"Người lính đứng bất động không hề nhúc nhích."},{"example":"その大木は、強風にも微動だにしなかった。","example_reading":"そのたいぼくは、きょうふうにもびどうだにしなかった。","example_meaning":"Cây cổ thụ ấy đứng vững không hề lay chuyển trước gió mạnh."}],"level":"c1"},
{"word":"何ら","reading":"なんら","meaning":"hoàn toàn không, tuyệt không","hanviet":"hà","note":"Đi với phủ định ～ない. Văn viết; hay đi với 問題, 関係, 変わり.","example":"私は、この事故とは何ら関係がありません。","example_reading":"わたしは、このじことはなんらかんけいがありません。","example_meaning":"Tôi hoàn toàn không liên quan đến vụ tai nạn này.","examples":[{"example":"私は、この事故とは何ら関係がありません。","example_reading":"わたしは、このじことはなんらかんけいがありません。","example_meaning":"Tôi hoàn toàn không liên quan đến vụ tai nạn này."},{"example":"新しい制度になっても、何ら変わりはない。","example_reading":"あたらしいせいどになっても、なんらかわりはない。","example_meaning":"Dù chuyển sang chế độ mới cũng chẳng có gì thay đổi."}],"level":"c1"},
{"word":"ぜひとも","reading":"ぜひとも","meaning":"nhất định, rất mong","note":"Đi với ～たい／～ください／～ていただきたい. Mạnh và trang trọng hơn ぜひ.","example":"ぜひとも一度、工場を見学させていただきたいです。","example_reading":"ぜひともいちど、こうじょうをけんがくさせていただきたいです。","example_meaning":"Tôi rất mong được tham quan nhà máy một lần.","examples":[{"example":"ぜひとも一度、工場を見学させていただきたいです。","example_reading":"ぜひともいちど、こうじょうをけんがくさせていただきたいです。","example_meaning":"Tôi rất mong được tham quan nhà máy một lần."},{"example":"この件は、ぜひとも前向きにご検討ください。","example_reading":"このけんは、ぜひともまえむきにごけんとうください。","example_meaning":"Về việc này, kính mong quý vị xem xét tích cực."}],"level":"c1"},
{"word":"断じて","reading":"だんじて","meaning":"nhất quyết không","hanviet":"đoạn","note":"Đi với phủ định ～ない／～ません. Văn viết, trang trọng, ý chí cứng rắn.","example":"暴力は断じて許されるものではない。","example_reading":"ぼうりょくはだんじてゆるされるものではない。","example_meaning":"Bạo lực tuyệt đối không thể được tha thứ.","examples":[{"example":"暴力は断じて許されるものではない。","example_reading":"ぼうりょくはだんじてゆるされるものではない。","example_meaning":"Bạo lực tuyệt đối không thể được tha thứ."},{"example":"私は断じてそのような不正はしておりません。","example_reading":"わたしはだんじてそのようなふせいはしておりません。","example_meaning":"Tôi nhất quyết không hề làm điều gian lận như vậy."}],"level":"c1"},
{"word":"いかに","reading":"いかに","meaning":"dù ... thế nào; ... biết bao","note":"Đi với ～ても／～とも (nhượng bộ) hoặc ～か (cảm thán, nghi vấn gián tiếp). Văn viết.","example":"いかに才能があっても、努力しなければ成功しない。","example_reading":"いかにさいのうがあっても、どりょくしなければせいこうしない。","example_meaning":"Dù có tài năng đến mấy, không nỗ lực thì cũng không thành công.","examples":[{"example":"いかに才能があっても、努力しなければ成功しない。","example_reading":"いかにさいのうがあっても、どりょくしなければせいこうしない。","example_meaning":"Dù có tài năng đến mấy, không nỗ lực thì cũng không thành công."},{"example":"家族の支えが、いかに大切かを痛感した。","example_reading":"かぞくのささえが、いかにたいせつかをつうかんした。","example_meaning":"Tôi thấm thía sự hỗ trợ của gia đình quan trọng biết bao."}],"level":"c1"},
{"word":"ゆめゆめ","reading":"ゆめゆめ","meaning":"tuyệt đối (không được)","note":"Đi với phủ định ～ない／～てはならない／～な. Cảnh báo mạnh, văn viết, hơi cổ.","example":"このことは、ゆめゆめ他人に話してはならない。","example_reading":"このことは、ゆめゆめたにんにはなしてはならない。","example_meaning":"Chuyện này tuyệt đối không được nói với người ngoài.","examples":[{"example":"このことは、ゆめゆめ他人に話してはならない。","example_reading":"このことは、ゆめゆめたにんにはなしてはならない。","example_meaning":"Chuyện này tuyệt đối không được nói với người ngoài."},{"example":"油断はゆめゆめするな。","example_reading":"ゆだんはゆめゆめするな。","example_meaning":"Tuyệt đối đừng chủ quan."}],"level":"c1"},
{"word":"いまだかつて","reading":"いまだかつて","meaning":"từ trước đến nay chưa từng","note":"Đi với phủ định ～ない／～たことがない. Nhấn mạnh chưa bao giờ.","example":"いまだかつて、こんなに美しい夕日を見たことがない。","example_reading":"いまだかつて、こんなにうつくしいゆうひをみたことがない。","example_meaning":"Từ trước đến nay tôi chưa từng thấy hoàng hôn đẹp thế này.","examples":[{"example":"いまだかつて、こんなに美しい夕日を見たことがない。","example_reading":"いまだかつて、こんなにうつくしいゆうひをみたことがない。","example_meaning":"Từ trước đến nay tôi chưa từng thấy hoàng hôn đẹp thế này."},{"example":"いまだかつて、彼が約束を破ったことはない。","example_reading":"いまだかつて、かれがやくそくをやぶったことはない。","example_meaning":"Chưa bao giờ anh ấy thất hứa."}],"level":"c1"},
{"word":"まんじりとも","reading":"まんじりとも","meaning":"chợp mắt (không)","note":"Đi với しない／せず／できなかった. Không chợp mắt được dù chỉ một chút.","example":"心配で、一晩中まんじりともせずに過ごした。","example_reading":"しんぱいで、ひとばんじゅうまんじりともせずにすごした。","example_meaning":"Lo lắng nên tôi thức trắng đêm không chợp mắt.","examples":[{"example":"心配で、一晩中まんじりともせずに過ごした。","example_reading":"しんぱいで、ひとばんじゅうまんじりともせずにすごした。","example_meaning":"Lo lắng nên tôi thức trắng đêm không chợp mắt."},{"example":"試験の前の夜は、緊張してまんじりともできなかった。","example_reading":"しけんのまえのよるは、きんちょうしてまんじりともできなかった。","example_meaning":"Đêm trước kỳ thi, tôi căng thẳng nên không ngủ được chút nào."}],"level":"c1"},
{"word":"いわんや","reading":"いわんや","meaning":"huống chi","note":"Hay đi với ～においてをや／～はなおさら. Văn viết cổ, nghĩa mạnh hơn ましてや.","example":"大人でさえ難しいのだ。いわんや子どもにおいてをや。","example_reading":"おとなでさえむずかしいのだ。いわんやこどもにおいてをや。","example_meaning":"Người lớn còn thấy khó, huống chi trẻ con.","examples":[{"example":"大人でさえ難しいのだ。いわんや子どもにおいてをや。","example_reading":"おとなでさえむずかしいのだ。いわんやこどもにおいてをや。","example_meaning":"Người lớn còn thấy khó, huống chi trẻ con."},{"example":"達人でも失敗するのだから、いわんや初心者は言うまでもない。","example_reading":"たつじんでもしっぱいするのだから、いわんやしょしんしゃはいうまでもない。","example_meaning":"Cao thủ còn thất bại, huống chi người mới thì khỏi nói."}],"level":"c1"},
{"word":"なまじ","reading":"なまじ","meaning":"nửa vời, biết chút ít mà hóa dở","note":"Hay đi với ～ば／～ために／かえって. Làm hoặc biết nửa vời nên sinh ra kết quả xấu.","example":"なまじ知識があるばかりに、かえって失敗してしまった。","example_reading":"なまじちしきがあるばかりに、かえってしっぱいしてしまった。","example_meaning":"Chỉ vì biết chút ít mà tôi lại thất bại.","examples":[{"example":"なまじ知識があるばかりに、かえって失敗してしまった。","example_reading":"なまじちしきがあるばかりに、かえってしっぱいしてしまった。","example_meaning":"Chỉ vì biết chút ít mà tôi lại thất bại."},{"example":"なまじ手を出さないほうが、よかったかもしれない。","example_reading":"なまじてをださないほうが、よかったかもしれない。","example_meaning":"Có lẽ đừng nhúng tay nửa vời thì tốt hơn."}],"level":"c1"},
{"word":"必ずや","reading":"かならずや","meaning":"nhất định sẽ","hanviet":"tất","note":"Đi với ～だろう／～に違いない／～てみせる. Văn viết, trang trọng, thể hiện niềm tin mạnh.","example":"努力を続ければ、必ずや夢は叶うだろう。","example_reading":"どりょくをつづければ、かならずやゆめはかなうだろう。","example_meaning":"Nếu tiếp tục nỗ lực, ước mơ nhất định sẽ thành.","examples":[{"example":"努力を続ければ、必ずや夢は叶うだろう。","example_reading":"どりょくをつづければ、かならずやゆめはかなうだろう。","example_meaning":"Nếu tiếp tục nỗ lực, ước mơ nhất định sẽ thành."},{"example":"彼ならば、必ずやこの難局を乗り越えてくれるに違いない。","example_reading":"かれならば、かならずやこのなんきょくをのりこえてくれるにちがいない。","example_meaning":"Nếu là anh ấy thì nhất định sẽ vượt qua khó khăn này."}],"level":"c1"},
{"word":"いかにも","reading":"いかにも","meaning":"quả đúng là, trông đúng là","note":"Đi với ～そうだ／～ようだ／～らしい. Nhấn mạnh trông đúng là như vậy.","example":"彼はいかにも頭がよさそうに見える。","example_reading":"かれはいかにもあたまがよさそうにみえる。","example_meaning":"Anh ấy trông đúng là người thông minh.","examples":[{"example":"彼はいかにも頭がよさそうに見える。","example_reading":"かれはいかにもあたまがよさそうにみえる。","example_meaning":"Anh ấy trông đúng là người thông minh."},{"example":"いかにも彼らしい答えだった。","example_reading":"いかにもかれらしいこたえだった。","example_meaning":"Quả đúng là câu trả lời giống anh ấy."}],"level":"c1"},
{"word":"さも","reading":"さも","meaning":"cứ như là, làm ra vẻ","note":"Đi với ～ように／～そうに／～かのように. Làm ra vẻ như thật; sắc thái hơi mỉa.","example":"彼はさも自分で作ったかのように話した。","example_reading":"かれはさもじぶんでつくったかのようにはなした。","example_meaning":"Anh ta kể cứ như thể chính mình làm ra vậy.","examples":[{"example":"彼はさも自分で作ったかのように話した。","example_reading":"かれはさもじぶんでつくったかのようにはなした。","example_meaning":"Anh ta kể cứ như thể chính mình làm ra vậy."},{"example":"彼女はさも楽しそうに笑ってみせた。","example_reading":"かのじょはさもたのしそうにわらってみせた。","example_meaning":"Cô ấy cười ra vẻ rất vui."}],"level":"c1"},
{"word":"あたかも","reading":"あたかも","meaning":"cứ như thể","note":"Đi với ～ようだ／～かのようだ. Văn viết, tương tự まるで.","example":"彼はあたかも自分が見てきたかのように話した。","example_reading":"かれはあたかもじぶんがみてきたかのようにはなした。","example_meaning":"Anh ấy kể cứ như thể chính mình đã chứng kiến.","examples":[{"example":"彼はあたかも自分が見てきたかのように話した。","example_reading":"かれはあたかもじぶんがみてきたかのようにはなした。","example_meaning":"Anh ấy kể cứ như thể chính mình đã chứng kiến."},{"example":"湖面に映る紅葉は、あたかも一枚の絵のようだった。","example_reading":"こめんにうつるこうようは、あたかもいちまいのえのようだった。","example_meaning":"Lá đỏ phản chiếu trên mặt hồ cứ như một bức tranh."}],"level":"c1"},
{"word":"よしんば","reading":"よしんば","meaning":"dù cho, giả sử","note":"Đi với ～ても／～としても. Văn viết, hơi cổ.","example":"よしんば失敗したとしても、挑戦する価値はある。","example_reading":"よしんばしっぱいしたとしても、ちょうせんするかちはある。","example_meaning":"Dù có thất bại thì thử thách vẫn đáng giá.","examples":[{"example":"よしんば失敗したとしても、挑戦する価値はある。","example_reading":"よしんばしっぱいしたとしても、ちょうせんするかちはある。","example_meaning":"Dù có thất bại thì thử thách vẫn đáng giá."},{"example":"よしんば彼の言うことが正しくても、やり方に問題がある。","example_reading":"よしんばかれのいうことがただしくても、やりかたにもんだいがある。","example_meaning":"Dù lời anh ấy có đúng thì cách làm vẫn có vấn đề."}],"level":"c1"},
{"word":"何卒","reading":"なにとぞ","meaning":"xin hãy, kính mong","hanviet":"hà tốt","note":"Đi với ～ください／～お願い申し上げます. Rất trang trọng, dùng trong thư từ, kinh doanh.","example":"ご迷惑をおかけしますが、何卒ご理解ください。","example_reading":"ごめいわくをおかけしますが、なにとぞごりかいください。","example_meaning":"Xin lỗi vì đã gây phiền hà, kính mong quý vị thông cảm.","examples":[{"example":"ご迷惑をおかけしますが、何卒ご理解ください。","example_reading":"ごめいわくをおかけしますが、なにとぞごりかいください。","example_meaning":"Xin lỗi vì đã gây phiền hà, kính mong quý vị thông cảm."},{"example":"今後とも何卒よろしくお願い申し上げます。","example_reading":"こんごともなにとぞよろしくおねがいもうしあげます。","example_meaning":"Kính mong tiếp tục nhận được sự giúp đỡ của quý vị."}],"level":"c1"},
{"word":"よもや","reading":"よもや","meaning":"lẽ nào, không thể ngờ","note":"Đi với ～まい／～ないだろう／～とは. Văn viết, hơi cổ.","example":"よもや彼が裏切るとは、誰も思わなかった。","example_reading":"よもやかれがうらぎるとは、だれもおもわなかった。","example_meaning":"Không ai ngờ lẽ nào anh ta lại phản bội.","examples":[{"example":"よもや彼が裏切るとは、誰も思わなかった。","example_reading":"よもやかれがうらぎるとは、だれもおもわなかった。","example_meaning":"Không ai ngờ lẽ nào anh ta lại phản bội."},{"example":"よもや、この雨の中を出かけるつもりではないだろうね。","example_reading":"よもや、このあめのなかをでかけるつもりではないだろうね。","example_meaning":"Lẽ nào bạn định ra ngoài trong trời mưa thế này đấy chứ?"}],"level":"c1"},
{"word":"毛頭","reading":"もうとう","meaning":"chút nào cũng không","hanviet":"mao đầu","note":"Đi với phủ định ～ない. Hay đi với ～つもりは毛頭ない. Văn viết, nhấn mạnh phủ định ý định.","example":"あなたを責めるつもりは毛頭ありません。","example_reading":"あなたをせめるつもりはもうとうありません。","example_meaning":"Tôi hoàn toàn không có ý trách bạn.","examples":[{"example":"あなたを責めるつもりは毛頭ありません。","example_reading":"あなたをせめるつもりはもうとうありません。","example_meaning":"Tôi hoàn toàn không có ý trách bạn."},{"example":"会社を辞める気など毛頭ない。","example_reading":"かいしゃをやめるきなどもうとうない。","example_meaning":"Tôi chẳng hề có ý định nghỉ việc ở công ty."}],"level":"c1"},
{"word":"今に","reading":"いまに","meaning":"rồi sẽ, chẳng bao lâu nữa","hanviet":"kim","note":"Đi với ～だろう／～に違いない／～ことになる. Dự đoán điều sắp xảy ra.","example":"そんな無理をしていると、今に病気になるよ。","example_reading":"そんなむりをしていると、いまにびょうきになるよ。","example_meaning":"Cứ gắng sức như thế rồi sẽ bệnh đấy.","examples":[{"example":"そんな無理をしていると、今に病気になるよ。","example_reading":"そんなむりをしていると、いまにびょうきになるよ。","example_meaning":"Cứ gắng sức như thế rồi sẽ bệnh đấy."},{"example":"今に彼の実力が認められるはずだ。","example_reading":"いまにかれのじつりょくがみとめられるはずだ。","example_meaning":"Chẳng bao lâu nữa thực lực của anh ấy sẽ được công nhận."}],"level":"c1"},
{"word":"すぐに","reading":"すぐに","meaning":"ngay lập tức","antonym":"後で（あとで）: lát nữa / あとで: lát nữa / なかなか: mãi mà","antonym_hanviet":"hậu /  / ","note":"Hay đi với 行く, 返事する, 効く. Dạng ngắn すぐ. Khoảng thời gian rất ngắn từ lúc bắt đầu.","example":"メールを見たら、すぐに返事をしてください。","example_reading":"メールをみたら、すぐにへんじをしてください。","example_meaning":"Xem email xong hãy trả lời ngay.","examples":[{"example":"メールを見たら、すぐに返事をしてください。","example_reading":"メールをみたら、すぐにへんじをしてください。","example_meaning":"Xem email xong hãy trả lời ngay."},{"example":"この薬はすぐに効くわけではない。","example_reading":"このくすりはすぐにきくわけではない。","example_meaning":"Thuốc này không phải có tác dụng ngay."}],"level":"d1"},
{"word":"もう","reading":"もう","meaning":"đã rồi; sắp; thêm nữa","antonym":"まだ: vẫn còn, vẫn chưa","note":"Đi với ～た (đã xong) hoặc ～ない (không còn nữa). Cũng nghĩa 'thêm nữa' như もう一度.","example":"宿題はもう終わりましたか。","example_reading":"しゅくだいはもうおわりましたか。","example_meaning":"Bạn làm xong bài tập chưa?","examples":[{"example":"宿題はもう終わりましたか。","example_reading":"しゅくだいはもうおわりましたか。","example_meaning":"Bạn làm xong bài tập chưa?"},{"example":"もう少し待ってください。","example_reading":"もうすこしまってください。","example_meaning":"Xin hãy đợi thêm một chút."}],"level":"d1"},
{"word":"まだ","reading":"まだ","meaning":"vẫn còn, vẫn chưa","antonym":"もう: đã rồi / すでに: Đã / とっくに: từ lâu rồi","note":"Đi với ～ている (vẫn) hoặc ～ない (chưa). Trạng thái chưa kết thúc hoặc chưa xảy ra.","example":"まだ昼ご飯を食べていません。","example_reading":"まだひるごはんをたべていません。","example_meaning":"Tôi vẫn chưa ăn trưa.","examples":[{"example":"まだ昼ご飯を食べていません。","example_reading":"まだひるごはんをたべていません。","example_meaning":"Tôi vẫn chưa ăn trưa."},{"example":"彼はまだ学生で、収入が少ない。","example_reading":"かれはまだがくせいで、しゅうにゅうがすくない。","example_meaning":"Anh ấy vẫn còn là sinh viên nên thu nhập ít."}],"level":"d1"},
{"word":"まず","reading":"まず","meaning":"trước tiên, đầu tiên","antonym":"最後に（さいごに）: cuối cùng / 次に（つぎに）: tiếp theo","antonym_hanviet":"tối hậu / thứ","note":"Đứng đầu câu liệt kê: まず～、次に～. Rất thường dùng.","example":"まず手を洗ってから、ご飯を食べましょう。","example_reading":"まずてをあらってから、ごはんをたべましょう。","example_meaning":"Trước tiên hãy rửa tay rồi ăn cơm.","examples":[{"example":"まず手を洗ってから、ご飯を食べましょう。","example_reading":"まずてをあらってから、ごはんをたべましょう。","example_meaning":"Trước tiên hãy rửa tay rồi ăn cơm."},{"example":"新しい街では、まず住む場所を探さなければならない。","example_reading":"あたらしいまちでは、まずすむばしょをさがさなければならない。","example_meaning":"Ở thành phố mới, trước hết phải tìm chỗ ở."}],"level":"d1"},
{"word":"いつも","reading":"いつも","meaning":"luôn luôn, lúc nào cũng","antonym":"めったに: hiếm khi / 時々（ときどき）: thỉnh thoảng / 久々に（ひさびさに）: lâu rồi mới","antonym_hanviet":" / thời thời / cửu cửu","note":"Hay đi với ～ている, ～する. Tần suất cao nhất; trái nghĩa: 一度も～ない.","example":"彼はいつも笑顔で挨拶してくれる。","example_reading":"かれはいつもえがおであいさつしてくれる。","example_meaning":"Anh ấy lúc nào cũng chào tôi bằng nụ cười.","examples":[{"example":"彼はいつも笑顔で挨拶してくれる。","example_reading":"かれはいつもえがおであいさつしてくれる。","example_meaning":"Anh ấy lúc nào cũng chào tôi bằng nụ cười."},{"example":"朝はいつもコーヒーを飲んでから出かける。","example_reading":"あさはいつもコーヒーをのんでからでかける。","example_meaning":"Buổi sáng tôi luôn uống cà phê rồi mới ra khỏi nhà."}],"level":"d1"},
{"word":"よく","reading":"よく","meaning":"hay, thường; (làm) kỹ","note":"Chỉ tần suất cao (よく行く) hoặc mức độ kỹ (よく考える). Phân biệt với いつも (luôn luôn).","antonym":"めったに: hiếm khi","example":"週末はよく友達と映画を見に行く。","example_reading":"しゅうまつはよくともだちとえいがをみにいく。","example_meaning":"Cuối tuần tôi hay đi xem phim với bạn.","examples":[{"example":"週末はよく友達と映画を見に行く。","example_reading":"しゅうまつはよくともだちとえいがをみにいく。","example_meaning":"Cuối tuần tôi hay đi xem phim với bạn."},{"example":"契約書をよく読んでからサインしてください。","example_reading":"けいやくしょをよくよんでからサインしてください。","example_meaning":"Hãy đọc kỹ hợp đồng rồi mới ký."}],"level":"d1"},
{"word":"また","reading":"また","meaning":"lại, lần nữa","antonym":"二度と（にどと）: không bao giờ nữa","antonym_hanviet":"nhị độ","note":"Lặp lại cùng sự việc. Hay đi với ～た／～よう. Cũng là liên từ 'hơn nữa'.","example":"また来週の月曜日にお会いしましょう。","example_reading":"またらいしゅうのげつようびにおあいしましょう。","example_meaning":"Hẹn gặp lại bạn vào thứ Hai tuần sau.","examples":[{"example":"また来週の月曜日にお会いしましょう。","example_reading":"またらいしゅうのげつようびにおあいしましょう。","example_meaning":"Hẹn gặp lại bạn vào thứ Hai tuần sau."},{"example":"昨日と同じ失敗を、また繰り返してしまった。","example_reading":"きのうとおなじしっぱいを、またくりかえしてしまった。","example_meaning":"Tôi lại lặp lại thất bại giống hôm qua mất rồi."}],"level":"d1"},
{"word":"毎日","reading":"まいにち","meaning":"mỗi ngày","hanviet":"mỗi nhật","note":"Chỉ tần suất hằng ngày. Dùng như phó từ, không cần に.","example":"私は毎日、六時に起きてジョギングをしている。","example_reading":"わたしはまいにち、ろくじにおきてジョギングをしている。","example_meaning":"Ngày nào tôi cũng dậy lúc sáu giờ để chạy bộ.","examples":[{"example":"私は毎日、六時に起きてジョギングをしている。","example_reading":"わたしはまいにち、ろくじにおきてジョギングをしている。","example_meaning":"Ngày nào tôi cũng dậy lúc sáu giờ để chạy bộ."},{"example":"毎日少しずつ漢字を覚えれば、必ず上達する。","example_reading":"まいにちすこしずつかんじをおぼえれば、かならずじょうたつする。","example_meaning":"Nếu mỗi ngày nhớ một ít chữ Hán thì chắc chắn sẽ tiến bộ."}],"level":"d1"},
{"word":"もっと","reading":"もっと","meaning":"hơn nữa, thêm nữa","note":"Hay đi với ～たい／～てください／tính từ. So sánh mức độ cao hơn hiện tại.","example":"もっと大きい声で話してください。","example_reading":"もっとおおきいこえではなしてください。","example_meaning":"Xin hãy nói to hơn nữa.","examples":[{"example":"もっと大きい声で話してください。","example_reading":"もっとおおきいこえではなしてください。","example_meaning":"Xin hãy nói to hơn nữa."},{"example":"この仕事を、もっと効率よく進める方法はないだろうか。","example_reading":"このしごとを、もっとこうりつよくすすめるほうほうはないだろうか。","example_meaning":"Không có cách nào làm công việc này hiệu quả hơn nữa sao?"}],"level":"d1"},
{"word":"今度","reading":"こんど","meaning":"lần này; lần sau","hanviet":"kim độ","antonym":"この間（このあいだ）: hôm nọ","antonym_hanviet":"gian","note":"Tùy ngữ cảnh chỉ lần sắp tới hoặc lần hiện tại. 今度また = lần sau nhé.","example":"今度また遊びに来てください。","example_reading":"こんどまたあそびにきてください。","example_meaning":"Lần sau lại đến chơi nhé.","examples":[{"example":"今度また遊びに来てください。","example_reading":"こんどまたあそびにきてください。","example_meaning":"Lần sau lại đến chơi nhé."},{"example":"今度は私が払います。","example_reading":"こんどはわたしがはらいます。","example_meaning":"Lần này tôi trả."}],"level":"d1"},
{"word":"ずっと","reading":"ずっと","meaning":"suốt, liên tục; hơn hẳn","note":"Chỉ thời gian kéo dài (ずっと待つ) hoặc hơn hẳn (ずっと大きい).","example":"彼女のことを、ずっと待っていた。","example_reading":"かのじょのことを、ずっとまっていた。","example_meaning":"Tôi đã đợi cô ấy suốt.","examples":[{"example":"彼女のことを、ずっと待っていた。","example_reading":"かのじょのことを、ずっとまっていた。","example_meaning":"Tôi đã đợi cô ấy suốt."},{"example":"この道のほうが、あの道よりずっと近い。","example_reading":"このみちのほうが、あのみちよりずっとちかい。","example_meaning":"Con đường này gần hơn con đường kia nhiều."}],"level":"d1"},
{"word":"ちょっと","reading":"ちょっと","meaning":"một chút; hơi","antonym":"たくさん: nhiều / とても: rất / めっちゃ: cực kỳ","note":"Mức độ hoặc thời gian ít; cũng dùng nhẹ nhàng khi nhờ vả hay từ chối. Khẩu ngữ.","example":"ちょっと待ってください。すぐ戻ります。","example_reading":"ちょっとまってください。すぐもどります。","example_meaning":"Xin đợi một chút. Tôi quay lại ngay.","examples":[{"example":"ちょっと待ってください。すぐ戻ります。","example_reading":"ちょっとまってください。すぐもどります。","example_meaning":"Xin đợi một chút. Tôi quay lại ngay."},{"example":"この靴は私にはちょっと小さい。","example_reading":"このくつはわたしにはちょっとちいさい。","example_meaning":"Đôi giày này hơi nhỏ với tôi."}],"level":"d1"},
{"word":"さっき","reading":"さっき","meaning":"lúc nãy, vừa nãy","antonym":"あとで: sau đó / 後ほど（のちほど）: lát nữa","antonym_hanviet":" / hậu","note":"Khẩu ngữ. Trang trọng hơn: 先ほど.","example":"さっき駅で田中さんに会ったよ。","example_reading":"さっきえきでたなかさんにあったよ。","example_meaning":"Lúc nãy mình gặp anh Tanaka ở ga.","examples":[{"example":"さっき駅で田中さんに会ったよ。","example_reading":"さっきえきでたなかさんにあったよ。","example_meaning":"Lúc nãy mình gặp anh Tanaka ở ga."},{"example":"さっき言ったことを、もう一度説明します。","example_reading":"さっきいったことを、もういちどせつめいします。","example_meaning":"Tôi sẽ giải thích lại điều vừa nói."}],"level":"d1"},
{"word":"後で","reading":"あとで","meaning":"sau đó, lát nữa","hanviet":"hậu","antonym":"先に（さきに）: trước / 今すぐ（いますぐ）: ngay bây giờ / 先ほど（さきほど）: lúc nãy","antonym_hanviet":"tiên / kim / tiên","note":"Hay đi với ～ます, ～てください. Thân mật hơn 後ほど.","example":"今は忙しいので、後で電話します。","example_reading":"いまはいそがしいので、あとででんわします。","example_meaning":"Giờ tôi bận nên lát nữa sẽ gọi điện.","examples":[{"example":"今は忙しいので、後で電話します。","example_reading":"いまはいそがしいので、あとででんわします。","example_meaning":"Giờ tôi bận nên lát nữa sẽ gọi điện."},{"example":"説明は後でゆっくり聞かせてください。","example_reading":"せつめいはあとでゆっくりきかせてください。","example_meaning":"Lát nữa hãy từ từ giải thích cho tôi nghe."}],"level":"d1"},
{"word":"少し","reading":"すこし","meaning":"một chút, ít","hanviet":"thiểu","antonym":"たくさん: nhiều / すごく: rất / かなり: khá","note":"Đọc すこし. Hay đi với 待つ, 休む, 足りない. Trang trọng hơn ちょっと.","example":"少し休んでから、もう一度やってみよう。","example_reading":"すこしやすんでから、もういちどやってみよう。","example_meaning":"Nghỉ một chút rồi thử lại lần nữa.","examples":[{"example":"少し休んでから、もう一度やってみよう。","example_reading":"すこしやすんでから、もういちどやってみよう。","example_meaning":"Nghỉ một chút rồi thử lại lần nữa."},{"example":"彼は少し疲れているようだ。","example_reading":"かれはすこしつかれているようだ。","example_meaning":"Anh ấy có vẻ hơi mệt."}],"level":"d1"},
{"word":"先に","reading":"さきに","meaning":"trước, đi trước","hanviet":"tiên","antonym":"後で（あとで）: sau / 後から（あとから）: sau đó","antonym_hanviet":"hậu / hậu","note":"Hay đi với 行く, 帰る, 食べる. Làm việc gì trước người khác hoặc trước việc khác.","example":"私は用事があるので、先に帰らせてもらいます。","example_reading":"わたしはようじがあるので、さきにかえらせてもらいます。","example_meaning":"Tôi có việc nên xin phép về trước.","examples":[{"example":"私は用事があるので、先に帰らせてもらいます。","example_reading":"わたしはようじがあるので、さきにかえらせてもらいます。","example_meaning":"Tôi có việc nên xin phép về trước."},{"example":"先にお金を払ってから、商品を受け取った。","example_reading":"さきにおかねをはらってから、しょうひんをうけとった。","example_meaning":"Tôi trả tiền trước rồi mới nhận hàng."}],"level":"d1"},
{"word":"すごく","reading":"すごく","meaning":"rất, cực kỳ","antonym":"ちょっと: một chút / 少し（すこし）: một ít","antonym_hanviet":" / thiểu","note":"Khẩu ngữ, dùng trước tính từ hoặc động từ. Gốc từ すごい.","example":"昨日の映画は、すごく面白かった。","example_reading":"きのうのえいがは、すごくおもしろかった。","example_meaning":"Bộ phim hôm qua cực kỳ hay.","examples":[{"example":"昨日の映画は、すごく面白かった。","example_reading":"きのうのえいがは、すごくおもしろかった。","example_meaning":"Bộ phim hôm qua cực kỳ hay."},{"example":"今日はすごく疲れているので、早く寝ます。","example_reading":"きょうはすごくつかれているので、はやくねます。","example_meaning":"Hôm nay tôi rất mệt nên đi ngủ sớm."}],"level":"d1"},
{"word":"みんな","reading":"みんな","meaning":"mọi người, tất cả","antonym":"誰も（だれも）: không ai / 一部（いちぶ）: một phần","antonym_hanviet":"thùy / nhất bộ","note":"Khẩu ngữ. Trang trọng hơn: 皆さん／全員.","example":"みんなで協力すれば、すぐに終わるよ。","example_reading":"みんなできょうりょくすれば、すぐにおわるよ。","example_meaning":"Nếu mọi người cùng hợp sức thì sẽ xong ngay thôi.","examples":[{"example":"みんなで協力すれば、すぐに終わるよ。","example_reading":"みんなできょうりょくすれば、すぐにおわるよ。","example_meaning":"Nếu mọi người cùng hợp sức thì sẽ xong ngay thôi."},{"example":"クラスのみんなが、彼の誕生日を祝った。","example_reading":"クラスのみんなが、かれのたんじょうびをいわった。","example_meaning":"Cả lớp đã chúc mừng sinh nhật cậu ấy."}],"level":"d1"},
{"word":"かなり","reading":"かなり","meaning":"khá, tương đối (mức khá cao)","antonym":"少し（すこし）: một ít","antonym_hanviet":"thiểu","note":"Chỉ mức độ cao hơn \"khá\" thông thường. Dùng được với tính từ, động từ, số lượng. Trung tính.","example":"今日はかなり寒いので、コートを着て行きましょう。","example_reading":"きょうはかなりさむいので、コートをきていきましょう。","example_meaning":"Hôm nay khá lạnh nên hãy mặc áo khoác đi nhé.","examples":[{"example":"今日はかなり寒いので、コートを着て行きましょう。","example_reading":"きょうはかなりさむいので、コートをきていきましょう。","example_meaning":"Hôm nay khá lạnh nên hãy mặc áo khoác đi nhé."},{"example":"駅から家までは、かなり歩かなければならない。","example_reading":"えきからいえまでは、かなりあるかなければならない。","example_meaning":"Từ ga về nhà phải đi bộ khá xa."}],"level":"d1"},
{"word":"もうすぐ","reading":"もうすぐ","meaning":"sắp, chẳng mấy chốc","note":"Gần まもなく nhưng khẩu ngữ hơn. Hay đi với ～です, ～する.","example":"もうすぐ春が来て、桜が咲く季節になる。","example_reading":"もうすぐはるがきて、さくらがさくきせつになる。","example_meaning":"Sắp sang xuân, đến mùa hoa anh đào nở.","examples":[{"example":"もうすぐ春が来て、桜が咲く季節になる。","example_reading":"もうすぐはるがきて、さくらがさくきせつになる。","example_meaning":"Sắp sang xuân, đến mùa hoa anh đào nở."},{"example":"電車はもうすぐ到着します。","example_reading":"でんしゃはもうすぐとうちゃくします。","example_meaning":"Tàu sắp đến nơi."}],"level":"d1"},
{"word":"一番","reading":"いちばん","meaning":"nhất, hơn cả","hanviet":"nhất phiên","note":"Chỉ mức độ cao nhất trong số được so sánh. Khẩu ngữ, thân mật hơn 最も.","example":"家族の中で、父が一番早く起きる。","example_reading":"かぞくのなかで、ちちがいちばんはやくおきる。","example_meaning":"Trong gia đình, bố dậy sớm nhất.","examples":[{"example":"家族の中で、父が一番早く起きる。","example_reading":"かぞくのなかで、ちちがいちばんはやくおきる。","example_meaning":"Trong gia đình, bố dậy sớm nhất."},{"example":"この中で、どれが一番好きですか。","example_reading":"このなかで、どれがいちばんすきですか。","example_meaning":"Trong số này, bạn thích cái nào nhất?"}],"level":"d1"},
{"word":"一緒に","reading":"いっしょに","meaning":"cùng nhau","hanviet":"nhất tự","antonym":"別々に（べつべつに）: riêng rẽ / 一人で（ひとりで）: một mình / 独自に（どくじに）: riêng","antonym_hanviet":"biệt biệt / nhất nhân / độc tự","note":"Hay đi với 行く, 食べる, 送る. Làm cùng người khác hoặc cùng lúc.","example":"明日、一緒に昼ご飯を食べませんか。","example_reading":"あした、いっしょにひるごはんをたべませんか。","example_meaning":"Ngày mai cùng ăn trưa không?","examples":[{"example":"明日、一緒に昼ご飯を食べませんか。","example_reading":"あした、いっしょにひるごはんをたべませんか。","example_meaning":"Ngày mai cùng ăn trưa không?"},{"example":"この荷物も一緒に送ってください。","example_reading":"このにもつもいっしょにおくってください。","example_meaning":"Xin gửi luôn cả kiện hàng này cùng."}],"level":"d1"},
{"word":"すでに","reading":"すでに","meaning":"đã, đã từ trước","antonym":"まだ: vẫn chưa","note":"Việc đã hoàn thành hoặc đã xảy ra trước thời điểm nói. Hay đi với ～ている／～た. Trang trọng hơn もう.","example":"私が着いたとき、会議はすでに始まっていた。","example_reading":"わたしがついたとき、かいぎはすでにはじまっていた。","example_meaning":"Khi tôi đến, cuộc họp đã bắt đầu rồi.","examples":[{"example":"私が着いたとき、会議はすでに始まっていた。","example_reading":"わたしがついたとき、かいぎはすでにはじまっていた。","example_meaning":"Khi tôi đến, cuộc họp đã bắt đầu rồi."},{"example":"その問題については、すでに解決済みです。","example_reading":"そのもんだいについては、すでにかいけつずみです。","example_meaning":"Vấn đề đó đã được giải quyết xong."}],"level":"d1"},
{"word":"たくさん","reading":"たくさん","meaning":"nhiều","antonym":"少し（すこし）: ít / わずか: ít ỏi / ちょっぴり: chút xíu","antonym_hanviet":"thiểu /  / ","note":"Dùng như phó từ hoặc danh từ. Khẩu ngữ, dùng rất thường xuyên.","example":"昨日は、たくさん歩いて足が痛い。","example_reading":"きのうは、たくさんあるいてあしがいたい。","example_meaning":"Hôm qua đi bộ nhiều nên chân tôi đau.","examples":[{"example":"昨日は、たくさん歩いて足が痛い。","example_reading":"きのうは、たくさんあるいてあしがいたい。","example_meaning":"Hôm qua đi bộ nhiều nên chân tôi đau."},{"example":"お土産を、たくさん買ってきた。","example_reading":"おみやげを、たくさんかってきた。","example_meaning":"Tôi đã mua rất nhiều quà lưu niệm."}],"level":"d1"},
{"word":"いっぱい","reading":"いっぱい","meaning":"đầy, nhiều","antonym":"少し（すこし）: ít / わずか: ít ỏi","antonym_hanviet":"thiểu / ","note":"Dùng nói về mức đầy hoặc số lượng nhiều. Khẩu ngữ.","example":"お腹がいっぱいで、もう食べられない。","example_reading":"おなかがいっぱいで、もうたべられない。","example_meaning":"No căng bụng rồi, không ăn thêm được nữa.","examples":[{"example":"お腹がいっぱいで、もう食べられない。","example_reading":"おなかがいっぱいで、もうたべられない。","example_meaning":"No căng bụng rồi, không ăn thêm được nữa."},{"example":"公園には、子どもたちがいっぱい遊んでいた。","example_reading":"こうえんには、こどもたちがいっぱいあそんでいた。","example_meaning":"Trong công viên có rất nhiều trẻ đang chơi."}],"level":"d1"},
{"word":"大変","reading":"たいへん","meaning":"rất, vô cùng; vất vả","hanviet":"đại biến","note":"Trước tính từ／động từ nghĩa \"rất\" (hơi trang trọng). Hay đi với お世話になる, 失礼しました, 申し訳ない.","antonym":"楽（らく）: nhàn","antonym_hanviet":"lạc","example":"先日は大変お世話になりました。","example_reading":"せんじつはたいへんおせわになりました。","example_meaning":"Hôm trước tôi đã nhận được rất nhiều sự giúp đỡ của anh.","examples":[{"example":"先日は大変お世話になりました。","example_reading":"せんじつはたいへんおせわになりました。","example_meaning":"Hôm trước tôi đã nhận được rất nhiều sự giúp đỡ của anh."},{"example":"今日は大変暑いので、水分をこまめにとってください。","example_reading":"きょうはたいへんあついので、すいぶんをこまめにとってください。","example_meaning":"Hôm nay rất nóng nên hãy uống nước thường xuyên."}],"level":"d1"},
{"word":"そろそろ","reading":"そろそろ","meaning":"sắp, đã đến lúc","note":"Hay đi với ～時間だ, ～ましょう, ～ようか.","example":"そろそろ時間なので、会議を始めましょう。","example_reading":"そろそろじかんなので、かいぎをはじめましょう。","example_meaning":"Sắp đến giờ rồi, ta bắt đầu cuộc họp nhé.","examples":[{"example":"そろそろ時間なので、会議を始めましょう。","example_reading":"そろそろじかんなので、かいぎをはじめましょう。","example_meaning":"Sắp đến giờ rồi, ta bắt đầu cuộc họp nhé."},{"example":"もう遅いし、そろそろ帰ろうか。","example_reading":"もうおそいし、そろそろかえろうか。","example_meaning":"Muộn rồi, mình về thôi nhỉ."}],"level":"d1"},
{"word":"非常に","reading":"ひじょうに","meaning":"cực kỳ, rất","hanviet":"phi thường","antonym":"わずかに: một chút ít / 幾分（いくぶん）: phần nào / いささか: hơi","antonym_hanviet":" / kỷ phân / ","note":"Mức độ rất cao. Dùng trong văn viết, báo cáo, nói trang trọng.","example":"この製品は非常に使いやすいと評判です。","example_reading":"このせいひんはひじょうにつかいやすいとひょうばんです。","example_meaning":"Sản phẩm này nổi tiếng là cực kỳ dễ dùng.","examples":[{"example":"この製品は非常に使いやすいと評判です。","example_reading":"このせいひんはひじょうにつかいやすいとひょうばんです。","example_meaning":"Sản phẩm này nổi tiếng là cực kỳ dễ dùng."},{"example":"この地域では、水不足が非常に深刻になっている。","example_reading":"このちいきでは、みずふそくがひじょうにしんこくになっている。","example_meaning":"Ở khu vực này, tình trạng thiếu nước đang trở nên cực kỳ nghiêm trọng."}],"level":"d1"},
{"word":"最初に","reading":"さいしょに","meaning":"đầu tiên","hanviet":"tối sơ","antonym":"最後に（さいごに）: cuối cùng / 次に（つぎに）: tiếp theo","antonym_hanviet":"tối hậu / thứ","note":"Chỉ việc làm trước hết, mở đầu.","example":"最初に自己紹介をお願いします。","example_reading":"さいしょにじこしょうかいをおねがいします。","example_meaning":"Trước tiên xin mời tự giới thiệu.","examples":[{"example":"最初に自己紹介をお願いします。","example_reading":"さいしょにじこしょうかいをおねがいします。","example_meaning":"Trước tiên xin mời tự giới thiệu."},{"example":"店に入ったら、最初に注文を済ませてください。","example_reading":"みせにはいったら、さいしょにちゅうもんをすませてください。","example_meaning":"Khi vào quán, hãy gọi món trước đã."}],"level":"d1"},
{"word":"最後に","reading":"さいごに","meaning":"cuối cùng","hanviet":"tối hậu","antonym":"最初に（さいしょに）: đầu tiên / まず: trước tiên","antonym_hanviet":"tối sơ / ","note":"Hay dùng khi kết thúc lời phát biểu hoặc liệt kê các bước.","example":"最後に、皆様にお礼を申し上げます。","example_reading":"さいごに、みなさまにおれいをもうしあげます。","example_meaning":"Cuối cùng, tôi xin gửi lời cảm ơn đến mọi người.","examples":[{"example":"最後に、皆様にお礼を申し上げます。","example_reading":"さいごに、みなさまにおれいをもうしあげます。","example_meaning":"Cuối cùng, tôi xin gửi lời cảm ơn đến mọi người."},{"example":"最後に塩を少し加えると、味が引き締まる。","example_reading":"さいごにしおをすこしくわえると、あじがひきしまる。","example_meaning":"Cuối cùng cho thêm chút muối thì vị sẽ đậm đà hơn."}],"level":"d1"},
{"word":"すっかり","reading":"すっかり","meaning":"hoàn toàn, hẳn","antonym":"少しだけ（すこしだけ）: chỉ một chút","antonym_hanviet":"thiểu","note":"Hay đi với ～た／～なる／忘れる. Mức độ trọn vẹn, thay đổi hẳn.","example":"すっかり暗くなったので、帰ることにした。","example_reading":"すっかりくらくなったので、かえることにした。","example_meaning":"Trời tối hẳn nên tôi quyết định về.","examples":[{"example":"すっかり暗くなったので、帰ることにした。","example_reading":"すっかりくらくなったので、かえることにした。","example_meaning":"Trời tối hẳn nên tôi quyết định về."},{"example":"約束のことを、すっかり忘れていた。","example_reading":"やくそくのことを、すっかりわすれていた。","example_meaning":"Tôi quên bẵng lời hẹn."}],"level":"d1"},
{"word":"結構","reading":"けっこう","meaning":"khá, tương đối","hanviet":"kết cấu","note":"Khẩu ngữ, sắc thái tích cực nhẹ: \"khá là ～\". Còn nghĩa \"đủ rồi／được rồi\".","example":"このお店のパスタは結構おいしいですよ。","example_reading":"このおみせのパスタはけっこうおいしいですよ。","example_meaning":"Mì Ý ở quán này khá ngon đấy.","examples":[{"example":"このお店のパスタは結構おいしいですよ。","example_reading":"このおみせのパスタはけっこうおいしいですよ。","example_meaning":"Mì Ý ở quán này khá ngon đấy."},{"example":"遅刻しそうだったが、結構早く着いた。","example_reading":"ちこくしそうだったが、けっこうはやくついた。","example_meaning":"Tưởng sẽ đến muộn nhưng lại đến khá sớm."}],"level":"d1"},
{"word":"全部","reading":"ぜんぶ","meaning":"toàn bộ","hanviet":"toàn bộ","antonym":"一部（いちぶ）: một phần / 半分（はんぶん）: một nửa","antonym_hanviet":"nhất bộ / bán phân","note":"Khẩu ngữ hơn 全て.","example":"宿題は全部終わりましたか。","example_reading":"しゅくだいはぜんぶおわりましたか。","example_meaning":"Bài tập đã làm xong hết chưa?","examples":[{"example":"宿題は全部終わりましたか。","example_reading":"しゅくだいはぜんぶおわりましたか。","example_meaning":"Bài tập đã làm xong hết chưa?"},{"example":"お弁当を全部食べたら、お腹がいっぱいになった。","example_reading":"おべんとうをぜんぶたべたら、おなかがいっぱいになった。","example_meaning":"Ăn hết hộp cơm thì no căng bụng."}],"level":"d1"},
{"word":"だいぶ","reading":"だいぶ","meaning":"khá nhiều, khá hơn","antonym":"少し（すこし）: một ít","antonym_hanviet":"thiểu","note":"Thay đổi đáng kể so với trước. Hay đi với ～なる／～てきた／減った. Khẩu ngữ.","example":"薬を飲んだら、だいぶ楽になりました。","example_reading":"くすりをのんだら、だいぶらくになりました。","example_meaning":"Uống thuốc xong tôi đã đỡ hơn nhiều.","examples":[{"example":"薬を飲んだら、だいぶ楽になりました。","example_reading":"くすりをのんだら、だいぶらくになりました。","example_meaning":"Uống thuốc xong tôi đã đỡ hơn nhiều."},{"example":"引っ越してきて、この町にもだいぶ慣れた。","example_reading":"ひっこしてきて、このまちにもだいぶなれた。","example_meaning":"Chuyển đến đây, tôi đã khá quen với thị trấn này."}],"level":"d1"},
{"word":"ずいぶん","reading":"ずいぶん","meaning":"khá nhiều, quá (kèm ngạc nhiên)","antonym":"少し（すこし）: một ít","antonym_hanviet":"thiểu","note":"Mức độ cao hơn dự đoán; có thể kèm ngạc nhiên hoặc chê. Khẩu ngữ.","example":"しばらく会わないうちに、ずいぶん背が伸びたね。","example_reading":"しばらくあわないうちに、ずいぶんせがのびたね。","example_meaning":"Lâu không gặp mà con cao lên nhiều quá nhỉ.","examples":[{"example":"しばらく会わないうちに、ずいぶん背が伸びたね。","example_reading":"しばらくあわないうちに、ずいぶんせがのびたね。","example_meaning":"Lâu không gặp mà con cao lên nhiều quá nhỉ."},{"example":"ずいぶん遅かったですね。何かあったんですか。","example_reading":"ずいぶんおそかったですね。なにかあったんですか。","example_meaning":"Bạn đến muộn quá nhỉ. Có chuyện gì à?"}],"level":"d1"},
{"word":"だんだん","reading":"だんだん","meaning":"dần dần","antonym":"急に（きゅうに）: đột ngột","antonym_hanviet":"cấp","note":"Hay đi với ～なる／～てくる. Thay đổi từ từ theo thời gian; khẩu ngữ hơn 次第に.","example":"春になって、だんだん暖かくなってきた。","example_reading":"はるになって、だんだんあたたかくなってきた。","example_meaning":"Sang xuân, trời dần ấm lên.","examples":[{"example":"春になって、だんだん暖かくなってきた。","example_reading":"はるになって、だんだんあたたかくなってきた。","example_meaning":"Sang xuân, trời dần ấm lên."},{"example":"新しい仕事に、だんだん慣れてきた。","example_reading":"あたらしいしごとに、だんだんなれてきた。","example_meaning":"Tôi dần quen với công việc mới."}],"level":"d1"},
{"word":"相当","reading":"そうとう","meaning":"khá nhiều, đáng kể","hanviet":"tương đương","antonym":"少し（すこし）: một ít","antonym_hanviet":"thiểu","note":"Mức độ khá cao. Hay đi với 疲れる, 時間がかかる, 努力. Còn nghĩa \"tương đương\".","example":"この仕事を終わらせるには、相当な時間がかかりそうだ。","example_reading":"このしごとをおわらせるには、そうとうなじかんがかかりそうだ。","example_meaning":"Để xong việc này có vẻ sẽ mất khá nhiều thời gian.","examples":[{"example":"この仕事を終わらせるには、相当な時間がかかりそうだ。","example_reading":"このしごとをおわらせるには、そうとうなじかんがかかりそうだ。","example_meaning":"Để xong việc này có vẻ sẽ mất khá nhiều thời gian."},{"example":"昨日のマラソンで、相当疲れているようだ。","example_reading":"きのうのマラソンで、そうとうつかれているようだ。","example_meaning":"Có vẻ vì cuộc chạy marathon hôm qua mà anh ấy mệt khá nhiều."}],"level":"d1"},
{"word":"比較的","reading":"ひかくてき","meaning":"tương đối (so với mức chung)","hanviet":"tỷ giảo đích","note":"So với mức chung hoặc so với cái khác. Hay đi với 少ない, 安い, 簡単.","example":"この地域は、比較的家賃が安いことで知られている。","example_reading":"このちいきは、ひかくてきやちんがやすいことでしられている。","example_meaning":"Khu vực này nổi tiếng là tiền thuê nhà tương đối rẻ.","examples":[{"example":"この地域は、比較的家賃が安いことで知られている。","example_reading":"このちいきは、ひかくてきやちんがやすいことでしられている。","example_meaning":"Khu vực này nổi tiếng là tiền thuê nhà tương đối rẻ."},{"example":"今年の夏は、比較的過ごしやすかった。","example_reading":"ことしのなつは、ひかくてきすごしやすかった。","example_meaning":"Mùa hè năm nay tương đối dễ chịu."}],"level":"d1"},
{"word":"割と","reading":"わりと","meaning":"khá là (hơn dự tính)","hanviet":"cát","note":"Khẩu ngữ, ý \"ngoài dự tính, khá hơn tưởng\". Dạng viết: 割に／割合に.","example":"初めて作ったにしては、割とうまくできた。","example_reading":"はじめてつくったにしては、わりとうまくできた。","example_meaning":"So với lần đầu làm thì khá là thành công.","examples":[{"example":"初めて作ったにしては、割とうまくできた。","example_reading":"はじめてつくったにしては、わりとうまくできた。","example_meaning":"So với lần đầu làm thì khá là thành công."},{"example":"この辺りは、駅前なのに割と静かだ。","example_reading":"このあたりは、えきまえなのにわりとしずかだ。","example_meaning":"Khu này tuy ngay trước ga mà khá yên tĩnh."}],"level":"d1"},
{"word":"毎週","reading":"まいしゅう","meaning":"mỗi tuần","hanviet":"mỗi chu","note":"Chỉ tần suất hằng tuần. Dùng như phó từ, không cần に.","example":"私は毎週日曜日に、テニスをしている。","example_reading":"わたしはまいしゅうにちようびに、テニスをしている。","example_meaning":"Tuần nào vào Chủ nhật tôi cũng chơi tennis.","examples":[{"example":"私は毎週日曜日に、テニスをしている。","example_reading":"わたしはまいしゅうにちようびに、テニスをしている。","example_meaning":"Tuần nào vào Chủ nhật tôi cũng chơi tennis."},{"example":"このドラマは毎週楽しみに見ている。","example_reading":"このドラマはまいしゅうたのしみにみている。","example_meaning":"Tuần nào tôi cũng mong chờ xem bộ phim này."}],"level":"d1"},
{"word":"毎月","reading":"まいつき","meaning":"mỗi tháng","hanviet":"mỗi nguyệt","note":"Chỉ tần suất hằng tháng. Cũng đọc まいげつ trong văn viết.","example":"毎月、給料の一部を貯金している。","example_reading":"まいつき、きゅうりょうのいちぶをちょきんしている。","example_meaning":"Tháng nào tôi cũng gửi tiết kiệm một phần lương.","examples":[{"example":"毎月、給料の一部を貯金している。","example_reading":"まいつき、きゅうりょうのいちぶをちょきんしている。","example_meaning":"Tháng nào tôi cũng gửi tiết kiệm một phần lương."},{"example":"雑誌は毎月十日に発売される。","example_reading":"ざっしはまいつきとおかにはつばいされる。","example_meaning":"Tạp chí phát hành vào ngày mùng 10 mỗi tháng."}],"level":"d1"},
{"word":"毎朝","reading":"まいあさ","meaning":"mỗi sáng","hanviet":"mỗi triêu","note":"Chỉ việc lặp lại vào mỗi buổi sáng.","antonym":"毎晩（まいばん）: mỗi tối","antonym_hanviet":"mỗi vãn","example":"毎朝、コーヒーを飲んでから出かける。","example_reading":"まいあさ、コーヒーをのんでからでかける。","example_meaning":"Sáng nào tôi cũng uống cà phê rồi mới ra khỏi nhà.","examples":[{"example":"毎朝、コーヒーを飲んでから出かける。","example_reading":"まいあさ、コーヒーをのんでからでかける。","example_meaning":"Sáng nào tôi cũng uống cà phê rồi mới ra khỏi nhà."},{"example":"祖母は毎朝、庭の花に水をやっている。","example_reading":"そぼはまいあさ、にわのはなにみずをやっている。","example_meaning":"Sáng nào bà tôi cũng tưới hoa trong vườn."}],"level":"d1"},
{"word":"先月","reading":"せんげつ","meaning":"tháng trước","hanviet":"tiên nguyệt","antonym":"来月（らいげつ）: tháng sau","antonym_hanviet":"lai nguyệt","note":"Dùng như phó từ chỉ thời gian.","example":"先月、引っ越したばかりなので、まだ荷物が片付いていない。","example_reading":"せんげつ、ひっこしたばかりなので、まだにもつがかたづいていない。","example_meaning":"Tháng trước mới chuyển nhà nên đồ đạc vẫn chưa dọn xong.","examples":[{"example":"先月、引っ越したばかりなので、まだ荷物が片付いていない。","example_reading":"せんげつ、ひっこしたばかりなので、まだにもつがかたづいていない。","example_meaning":"Tháng trước mới chuyển nhà nên đồ đạc vẫn chưa dọn xong."},{"example":"先月に比べて、今月は売り上げが伸びた。","example_reading":"せんげつにくらべて、こんげつはうりあげがのびた。","example_meaning":"So với tháng trước, tháng này doanh thu tăng."}],"level":"d1"},
{"word":"来月","reading":"らいげつ","meaning":"tháng sau","hanviet":"lai nguyệt","antonym":"先月（せんげつ）: tháng trước","antonym_hanviet":"tiên nguyệt","note":"Dùng như phó từ chỉ thời gian.","example":"来月から、新しい部署に異動することになった。","example_reading":"らいげつから、あたらしいぶしょにいどうすることになった。","example_meaning":"Từ tháng sau, tôi sẽ chuyển sang phòng ban mới.","examples":[{"example":"来月から、新しい部署に異動することになった。","example_reading":"らいげつから、あたらしいぶしょにいどうすることになった。","example_meaning":"Từ tháng sau, tôi sẽ chuyển sang phòng ban mới."},{"example":"家賃は、来月分を月末までに払ってください。","example_reading":"やちんは、らいげつぶんをげつまつまでにはらってください。","example_meaning":"Xin hãy trả tiền nhà của tháng sau trước cuối tháng."}],"level":"d1"},
{"word":"先週","reading":"せんしゅう","meaning":"tuần trước","hanviet":"tiên chu","antonym":"来週（らいしゅう）: tuần sau","antonym_hanviet":"lai chu","note":"Dùng như phó từ chỉ thời gian.","example":"先週の日曜日、友達と一緒に山登りに行った。","example_reading":"せんしゅうのにちようび、ともだちといっしょにやまのぼりにいった。","example_meaning":"Chủ nhật tuần trước, tôi đi leo núi với bạn.","examples":[{"example":"先週の日曜日、友達と一緒に山登りに行った。","example_reading":"せんしゅうのにちようび、ともだちといっしょにやまのぼりにいった。","example_meaning":"Chủ nhật tuần trước, tôi đi leo núi với bạn."},{"example":"先週は出張で、ほとんど家にいなかった。","example_reading":"せんしゅうはしゅっちょうで、ほとんどいえにいなかった。","example_meaning":"Tuần trước tôi đi công tác nên gần như không ở nhà."}],"level":"d1"},
{"word":"来週","reading":"らいしゅう","meaning":"tuần sau","hanviet":"lai chu","antonym":"先週（せんしゅう）: tuần trước","antonym_hanviet":"tiên chu","note":"Dùng như phó từ chỉ thời gian.","example":"来週の水曜日に、大事な試験がある。","example_reading":"らいしゅうのすいようびに、だいじなしけんがある。","example_meaning":"Thứ Tư tuần sau có kỳ thi quan trọng.","examples":[{"example":"来週の水曜日に、大事な試験がある。","example_reading":"らいしゅうのすいようびに、だいじなしけんがある。","example_meaning":"Thứ Tư tuần sau có kỳ thi quan trọng."},{"example":"来週までに、報告書を仕上げておきます。","example_reading":"らいしゅうまでに、ほうこくしょをしあげておきます。","example_meaning":"Tôi sẽ hoàn thành báo cáo trước tuần sau."}],"level":"d1"},
{"word":"これまで","reading":"これまで","meaning":"từ trước đến nay","antonym":"これから: từ nay trở đi / 今後（こんご）: từ nay về sau","antonym_hanviet":" / kim hậu","note":"Hay đi với ～てきた, ～たことがない. Hơi trang trọng hơn 今まで.","example":"これまで、一度も病気で休んだことがない。","example_reading":"これまで、いちどもびょうきでやすんだことがない。","example_meaning":"Từ trước đến nay tôi chưa từng nghỉ vì bệnh.","examples":[{"example":"これまで、一度も病気で休んだことがない。","example_reading":"これまで、いちどもびょうきでやすんだことがない。","example_meaning":"Từ trước đến nay tôi chưa từng nghỉ vì bệnh."},{"example":"これまで支えてくれた皆さんに、感謝しています。","example_reading":"これまでささえてくれたみなさんに、かんしゃしています。","example_meaning":"Tôi biết ơn mọi người đã luôn ủng hộ tôi đến nay."}],"level":"d1"},
{"word":"今まで","reading":"いままで","meaning":"cho đến nay","hanviet":"kim","antonym":"これから: từ nay trở đi / 今後（こんご）: từ nay về sau","antonym_hanviet":" / kim hậu","note":"Khẩu ngữ hơn これまで. Hay đi với ～たことがない.","example":"今まで、こんなに美しい景色を見たことがない。","example_reading":"いままで、こんなにうつくしいけしきをみたことがない。","example_meaning":"Từ trước đến giờ tôi chưa từng thấy cảnh đẹp thế này.","examples":[{"example":"今まで、こんなに美しい景色を見たことがない。","example_reading":"いままで、こんなにうつくしいけしきをみたことがない。","example_meaning":"Từ trước đến giờ tôi chưa từng thấy cảnh đẹp thế này."},{"example":"今まで黙っていたけれど、実は転職を考えている。","example_reading":"いままでだまっていたけれど、じつはてんしょくをかんがえている。","example_meaning":"Từ nãy tôi vẫn im lặng, nhưng thật ra tôi đang nghĩ đến chuyện đổi việc."}],"level":"d1"},
{"word":"一度","reading":"いちど","meaning":"một lần","hanviet":"nhất độ","antonym":"何度も（なんども）: nhiều lần","antonym_hanviet":"hà độ","note":"Hay đi với ～てみる, ～たことがある.","example":"一度、あの店に行ってみたいと思っている。","example_reading":"いちど、あのみせにいってみたいとおもっている。","example_meaning":"Tôi muốn thử đến quán đó một lần.","examples":[{"example":"一度、あの店に行ってみたいと思っている。","example_reading":"いちど、あのみせにいってみたいとおもっている。","example_meaning":"Tôi muốn thử đến quán đó một lần."},{"example":"京都には一度行ったことがある。","example_reading":"きょうとにはいちどいったことがある。","example_meaning":"Tôi đã từng đến Kyoto một lần."}],"level":"d1"},
{"word":"いきなり","reading":"いきなり","meaning":"đột ngột, bất thình lình","antonym":"徐々に（じょじょに）: dần dần / 少しずつ（すこしずつ）: từng chút một","antonym_hanviet":"từ từ / thiểu","note":"Dùng khi sự việc xảy ra bất ngờ, không báo trước. Gần 突然, khẩu ngữ hơn.","example":"知らない人がいきなり話しかけてきて、驚いた。","example_reading":"しらないひとがいきなりはなしかけてきて、おどろいた。","example_meaning":"Một người lạ bất ngờ bắt chuyện, tôi giật mình.","examples":[{"example":"知らない人がいきなり話しかけてきて、驚いた。","example_reading":"しらないひとがいきなりはなしかけてきて、おどろいた。","example_meaning":"Một người lạ bất ngờ bắt chuyện, tôi giật mình."},{"example":"彼はいきなり大声で笑い出した。","example_reading":"かれはいきなりおおごえでわらいだした。","example_meaning":"Anh ấy đột nhiên cười toáng lên."}],"level":"d1"},
{"word":"少しずつ","reading":"すこしずつ","meaning":"từng chút một","hanviet":"thiểu","antonym":"一気に（いっきに）: một mạch / いきなり: đột ngột / 一度に（いちどに）: một lần","antonym_hanviet":"nhất khí /  / nhất độ","note":"Hay đi với 慣れる, 進む, 上達する, 飲む. Làm dần dần, mỗi lần một ít.","example":"少しずつ、新しい仕事に慣れてきた。","example_reading":"すこしずつ、あたらしいしごとになれてきた。","example_meaning":"Tôi đang dần quen với công việc mới.","examples":[{"example":"少しずつ、新しい仕事に慣れてきた。","example_reading":"すこしずつ、あたらしいしごとになれてきた。","example_meaning":"Tôi đang dần quen với công việc mới."},{"example":"薬を少しずつ飲んで、様子を見てください。","example_reading":"くすりをすこしずつのんで、ようすをみてください。","example_meaning":"Hãy uống thuốc từng chút một và theo dõi tình trạng."}],"level":"d1"},
{"word":"一日中","reading":"いちにちじゅう","meaning":"cả ngày","hanviet":"nhất nhật trung","note":"Hay đi với 家にいる, 歩き回る, 働く. Chỉ trạng thái kéo dài suốt cả ngày.","example":"昨日は一日中、家で映画を見ていた。","example_reading":"きのうはいちにちじゅう、いえでえいがをみていた。","example_meaning":"Hôm qua tôi xem phim ở nhà cả ngày.","examples":[{"example":"昨日は一日中、家で映画を見ていた。","example_reading":"きのうはいちにちじゅう、いえでえいがをみていた。","example_meaning":"Hôm qua tôi xem phim ở nhà cả ngày."},{"example":"一日中歩き回って、足がくたくただ。","example_reading":"いちにちじゅうあるきまわって、あしがくたくただ。","example_meaning":"Đi loanh quanh cả ngày nên chân rã rời."}],"level":"d1"},
{"word":"大体","reading":"だいたい","meaning":"đại khái, hầu hết","hanviet":"đại thể","antonym":"正確に（せいかくに）: chính xác","antonym_hanviet":"chính xác","note":"Đọc だいたい. Hay đi với 終わる, 分かる, ～ぐらい. Không chính xác tuyệt đối.","example":"仕事は大体終わりました。","example_reading":"しごとはだいたいおわりました。","example_meaning":"Công việc đã xong gần hết.","examples":[{"example":"仕事は大体終わりました。","example_reading":"しごとはだいたいおわりました。","example_meaning":"Công việc đã xong gần hết."},{"example":"駅まで大体十分ぐらいかかります。","example_reading":"えきまでだいたいじっぷんぐらいかかります。","example_meaning":"Đến ga mất khoảng chừng mười phút."}],"level":"d1"},
{"word":"大概","reading":"たいがい","meaning":"phần lớn, thường thì","hanviet":"đại khái","note":"Đọc たいがい. Hay đi với ～ことが多い. Nói về điều thường xảy ra.","example":"休みの日は、大概家で本を読んでいる。","example_reading":"やすみのひは、たいがいいえでほんをよんでいる。","example_meaning":"Ngày nghỉ tôi thường ở nhà đọc sách.","examples":[{"example":"休みの日は、大概家で本を読んでいる。","example_reading":"やすみのひは、たいがいいえでほんをよんでいる。","example_meaning":"Ngày nghỉ tôi thường ở nhà đọc sách."},{"example":"彼が怒るのは、大概つまらないことが原因だ。","example_reading":"かれがおこるのは、たいがいつまらないことがげんいんだ。","example_meaning":"Anh ta nổi giận thường là vì chuyện vặt vãnh."}],"level":"d1"},
{"word":"ほぼ","reading":"ほぼ","meaning":"gần như, hầu như","note":"Gần đạt đến mức hoàn toàn. Hay đi với 全員, 完成, 同じ. Trung tính, hơi trang trọng.","example":"工事はほぼ予定どおりに終わった。","example_reading":"こうじはほぼよていどおりにおわった。","example_meaning":"Công trình đã xong gần như đúng kế hoạch.","examples":[{"example":"工事はほぼ予定どおりに終わった。","example_reading":"こうじはほぼよていどおりにおわった。","example_meaning":"Công trình đã xong gần như đúng kế hoạch."},{"example":"二つの商品は、性能がほぼ同じです。","example_reading":"ふたつのしょうひんは、せいのうがほぼおなじです。","example_meaning":"Hai sản phẩm có tính năng gần như giống nhau."}],"level":"d1"},
{"word":"やや","reading":"やや","meaning":"hơi, một chút","antonym":"大いに（おおいに）: rất nhiều","antonym_hanviet":"đại","note":"Mức độ nhẹ. Văn viết (báo cáo, dự báo thời tiết).","example":"明日は、午後からやや雲が増えるでしょう。","example_reading":"あしたは、ごごからややくもがふえるでしょう。","example_meaning":"Ngày mai từ chiều mây sẽ hơi nhiều lên.","examples":[{"example":"明日は、午後からやや雲が増えるでしょう。","example_reading":"あしたは、ごごからややくもがふえるでしょう。","example_meaning":"Ngày mai từ chiều mây sẽ hơi nhiều lên."},{"example":"先月に比べて、売り上げはやや減少した。","example_reading":"せんげつにくらべて、うりあげはややげんしょうした。","example_meaning":"So với tháng trước, doanh thu giảm nhẹ."}],"level":"d1"},
{"word":"ちょうど","reading":"ちょうど","meaning":"vừa đúng, đúng lúc","note":"Hay đi với ～ところ／thời điểm／số lượng. Khớp chính xác.","example":"ちょうど今、家を出るところです。","example_reading":"ちょうどいま、いえをでるところです。","example_meaning":"Đúng lúc này tôi đang ra khỏi nhà.","examples":[{"example":"ちょうど今、家を出るところです。","example_reading":"ちょうどいま、いえをでるところです。","example_meaning":"Đúng lúc này tôi đang ra khỏi nhà."},{"example":"駅に着いたら、ちょうど電車が来た。","example_reading":"えきについたら、ちょうどでんしゃがきた。","example_meaning":"Vừa đến ga thì tàu đến đúng lúc."}],"level":"d1"},
{"word":"毎年","reading":"まいとし","meaning":"hằng năm","hanviet":"mỗi niên","note":"Đọc まいとし hoặc まいねん. Hay đi với ～になると, ～開かれる.","example":"毎年夏になると、家族で海へ行く。","example_reading":"まいとしなつになると、かぞくでうみへいく。","example_meaning":"Năm nào cứ đến mùa hè, cả nhà tôi lại ra biển.","examples":[{"example":"毎年夏になると、家族で海へ行く。","example_reading":"まいとしなつになると、かぞくでうみへいく。","example_meaning":"Năm nào cứ đến mùa hè, cả nhà tôi lại ra biển."},{"example":"この祭りは毎年多くの観光客でにぎわう。","example_reading":"このまつりはまいとしおおくのかんこうきゃくでにぎわう。","example_meaning":"Lễ hội này năm nào cũng đông khách du lịch."}],"level":"d1"},
{"word":"毎晩","reading":"まいばん","meaning":"mỗi tối","hanviet":"mỗi vãn","note":"Chỉ việc lặp lại vào mỗi buổi tối.","antonym":"毎朝（まいあさ）: mỗi sáng","antonym_hanviet":"mỗi triêu","example":"子どもたちは毎晩、九時に寝ている。","example_reading":"こどもたちはまいばん、くじにねている。","example_meaning":"Tối nào bọn trẻ cũng đi ngủ lúc chín giờ.","examples":[{"example":"子どもたちは毎晩、九時に寝ている。","example_reading":"こどもたちはまいばん、くじにねている。","example_meaning":"Tối nào bọn trẻ cũng đi ngủ lúc chín giờ."},{"example":"毎晩のように、隣の部屋から音楽が聞こえる。","example_reading":"まいばんのように、となりのへやからおんがくがきこえる。","example_meaning":"Gần như tối nào cũng nghe thấy nhạc từ phòng bên cạnh."}],"level":"d1"},
{"word":"とっても","reading":"とっても","meaning":"rất, cực kỳ (khẩu ngữ)","note":"Dạng nhấn mạnh của とても, thân mật.","example":"昨日のコンサートは、とっても素晴らしかった。","example_reading":"きのうのコンサートは、とってもすばらしかった。","example_meaning":"Buổi hòa nhạc hôm qua tuyệt vời vô cùng.","examples":[{"example":"昨日のコンサートは、とっても素晴らしかった。","example_reading":"きのうのコンサートは、とってもすばらしかった。","example_meaning":"Buổi hòa nhạc hôm qua tuyệt vời vô cùng."},{"example":"この猫、とっても人懐っこいんですよ。","example_reading":"このねこ、とってもひとなつっこいんですよ。","example_meaning":"Con mèo này rất quấn người đấy."}],"level":"d1"},
{"word":"昼間","reading":"ひるま","meaning":"ban ngày, giữa trưa","hanviet":"trú gian","antonym":"夜（よる）: ban đêm / 夜中に（よなかに）: giữa đêm / 真夜中に（まよなかに）: vào giữa đêm khuya","antonym_hanviet":"dạ / dạ trung / chân dạ trung","note":"Đối lập với 夜. Nói về khoảng thời gian có nắng trong ngày.","example":"昼間は忙しいので、夜に電話します。","example_reading":"ひるまはいそがしいので、よるにでんわします。","example_meaning":"Ban ngày tôi bận nên tối sẽ gọi điện.","examples":[{"example":"昼間は忙しいので、夜に電話します。","example_reading":"ひるまはいそがしいので、よるにでんわします。","example_meaning":"Ban ngày tôi bận nên tối sẽ gọi điện."},{"example":"夜勤明けは、昼間に眠ることが多い。","example_reading":"やきんあけは、ひるまにねむることがおおい。","example_meaning":"Sau ca đêm, tôi thường ngủ vào ban ngày."}],"level":"d1"},
{"word":"夕方","reading":"ゆうがた","meaning":"chiều tối","hanviet":"tịch phương","antonym":"朝（あさ）: buổi sáng / 明け方に（あけがたに）: lúc rạng đông / 早朝（そうちょう）: sáng sớm","antonym_hanviet":"triêu / minh phương / tảo triêu","note":"Khoảng thời gian trước khi trời tối.","example":"夕方になると、街に明かりがともり始める。","example_reading":"ゆうがたになると、まちにあかりがともりはじめる。","example_meaning":"Đến chiều tối, đèn bắt đầu sáng khắp phố.","examples":[{"example":"夕方になると、街に明かりがともり始める。","example_reading":"ゆうがたになると、まちにあかりがともりはじめる。","example_meaning":"Đến chiều tối, đèn bắt đầu sáng khắp phố."},{"example":"約束は、明日の夕方五時でお願いします。","example_reading":"やくそくは、あしたのゆうがたごじでおねがいします。","example_meaning":"Xin hẹn vào năm giờ chiều ngày mai."}],"level":"d1"},
{"word":"二人で","reading":"ふたりで","meaning":"hai người cùng nhau","hanviet":"nhị nhân","antonym":"一人で（ひとりで）: một mình / 大勢で（おおぜいで）: đông người","antonym_hanviet":"nhất nhân / đại thế","note":"Hay đi với 行く, 食べる, 運ぶ.","example":"週末は、二人で映画を見に行く予定だ。","example_reading":"しゅうまつは、ふたりでえいがをみにいくよていだ。","example_meaning":"Cuối tuần hai chúng tôi định đi xem phim.","examples":[{"example":"週末は、二人で映画を見に行く予定だ。","example_reading":"しゅうまつは、ふたりでえいがをみにいくよていだ。","example_meaning":"Cuối tuần hai chúng tôi định đi xem phim."},{"example":"この荷物は重いから、二人で運ぼう。","example_reading":"このにもつはおもいから、ふたりではこぼう。","example_meaning":"Hành lý này nặng nên hai người cùng khiêng nhé."}],"level":"d1"},
{"word":"まとめて","reading":"まとめて","meaning":"gộp lại một lượt","antonym":"別々に（べつべつに）: riêng rẽ / 一つ一つ（ひとつひとつ）: từng cái / 個別に（こべつに）: riêng từng cái","antonym_hanviet":"biệt biệt / nhất nhất / cá biệt","note":"Hay đi với 送る, 払う, 買う. Làm một lần cho nhiều thứ.","example":"荷物は、まとめて一度に送ってください。","example_reading":"にもつは、まとめていちどにおくってください。","example_meaning":"Xin hãy gửi hành lý gộp một lần.","examples":[{"example":"荷物は、まとめて一度に送ってください。","example_reading":"にもつは、まとめていちどにおくってください。","example_meaning":"Xin hãy gửi hành lý gộp một lần."},{"example":"支払いは、月末にまとめてお願いします。","example_reading":"しはらいは、げつまつにまとめておねがいします。","example_meaning":"Việc thanh toán xin gộp vào cuối tháng."}],"level":"d1"},
{"word":"できるだけ","reading":"できるだけ","meaning":"cố hết mức có thể","note":"Hay đi với 早く, ～ように. Gần なるべく.","example":"できるだけ早く、返事をください。","example_reading":"できるだけはやく、へんじをください。","example_meaning":"Xin hãy trả lời sớm hết mức có thể.","examples":[{"example":"できるだけ早く、返事をください。","example_reading":"できるだけはやく、へんじをください。","example_meaning":"Xin hãy trả lời sớm hết mức có thể."},{"example":"できるだけ人に迷惑をかけないように暮らしたい。","example_reading":"できるだけひとにめいわくをかけないようにくらしたい。","example_meaning":"Tôi muốn sống sao cho ít làm phiền người khác nhất có thể."}],"level":"d1"},
{"word":"なるべく","reading":"なるべく","meaning":"càng… càng tốt","note":"Hay đi với 早く, ～ようにする, 避ける. Khẩu ngữ hơn できるだけ.","example":"なるべく早く来てください。","example_reading":"なるべくはやくきてください。","example_meaning":"Xin hãy đến càng sớm càng tốt.","examples":[{"example":"なるべく早く来てください。","example_reading":"なるべくはやくきてください。","example_meaning":"Xin hãy đến càng sớm càng tốt."},{"example":"風邪を引いたので、なるべく外出を避けている。","example_reading":"かぜをひいたので、なるべくがいしゅつをさけている。","example_meaning":"Bị cảm nên tôi cố tránh ra ngoài."}],"level":"d1"},
{"word":"もう少し","reading":"もうすこし","meaning":"thêm một chút","hanviet":"thiểu","note":"Hay đi với ～てください, ～ほうがいい. Muốn tăng thêm một ít.","example":"もう少し待ってくれれば、すぐに終わります。","example_reading":"もうすこしまってくれれば、すぐにおわります。","example_meaning":"Nếu bạn đợi thêm chút nữa thì sẽ xong ngay.","examples":[{"example":"もう少し待ってくれれば、すぐに終わります。","example_reading":"もうすこしまってくれれば、すぐにおわります。","example_meaning":"Nếu bạn đợi thêm chút nữa thì sẽ xong ngay."},{"example":"味が薄いので、もう少し塩を足したほうがいい。","example_reading":"あじがうすいので、もうすこししおをたしたほうがいい。","example_meaning":"Vị nhạt nên cho thêm chút muối thì hơn."}],"level":"d1"},
{"word":"もうちょっと","reading":"もうちょっと","meaning":"thêm chút nữa","note":"Khẩu ngữ của もう少し.","example":"もうちょっとだけ、ここにいてもいい？","example_reading":"もうちょっとだけ、ここにいてもいい？","example_meaning":"Cho mình ở đây thêm chút nữa được không?","examples":[{"example":"もうちょっとだけ、ここにいてもいい？","example_reading":"もうちょっとだけ、ここにいてもいい？","example_meaning":"Cho mình ở đây thêm chút nữa được không?"},{"example":"結果が出るまで、もうちょっと待ってください。","example_reading":"けっかがでるまで、もうちょっとまってください。","example_meaning":"Xin hãy đợi thêm chút nữa cho đến khi có kết quả."}],"level":"d1"},
{"word":"それぞれ","reading":"それぞれ","meaning":"mỗi người, từng cái","antonym":"まとめて: gộp lại / 一緒に（いっしょに）: cùng nhau","antonym_hanviet":" / nhất tự","note":"Nhấn mạnh sự khác nhau của từng người hoặc từng vật.","example":"人にはそれぞれ、得意なことと苦手なことがある。","example_reading":"ひとにはそれぞれ、とくいなこととにがてなことがある。","example_meaning":"Mỗi người đều có điều sở trường và điều kém.","examples":[{"example":"人にはそれぞれ、得意なことと苦手なことがある。","example_reading":"ひとにはそれぞれ、とくいなこととにがてなことがある。","example_meaning":"Mỗi người đều có điều sở trường và điều kém."},{"example":"三人はそれぞれの道を歩み始めた。","example_reading":"さんにんはそれぞれのみちをあゆみはじめた。","example_meaning":"Ba người bắt đầu bước đi trên con đường riêng của mình."}],"level":"d1"},
{"word":"全て","reading":"すべて","meaning":"tất cả","hanviet":"toàn","antonym":"一部（いちぶ）: một phần / 何も（なにも）: chẳng gì","antonym_hanviet":"nhất bộ / hà","note":"Dùng như danh từ hoặc phó từ: 全てを～, 全て～.","example":"質問には全て正直に答えました。","example_reading":"しつもんにはすべてしょうじきにこたえました。","example_meaning":"Tôi đã trả lời trung thực mọi câu hỏi.","examples":[{"example":"質問には全て正直に答えました。","example_reading":"しつもんにはすべてしょうじきにこたえました。","example_meaning":"Tôi đã trả lời trung thực mọi câu hỏi."},{"example":"彼は全てを失っても、あきらめなかった。","example_reading":"かれはすべてをうしなっても、あきらめなかった。","example_meaning":"Dù mất tất cả, anh ấy vẫn không bỏ cuộc."}],"level":"d1"},
{"word":"特に","reading":"とくに","meaning":"đặc biệt là","hanviet":"đặc","antonym":"一般に（いっぱんに）: nói chung","antonym_hanviet":"nhất ban","note":"Nhấn mạnh một đối tượng nổi bật trong số nhiều cái. Hay đi với ～が／～は／～ない.","example":"私は果物の中で、特にりんごが好きです。","example_reading":"わたしはくだもののなかで、とくにりんごがすきです。","example_meaning":"Trong các loại trái cây, tôi đặc biệt thích táo.","examples":[{"example":"私は果物の中で、特にりんごが好きです。","example_reading":"わたしはくだもののなかで、とくにりんごがすきです。","example_meaning":"Trong các loại trái cây, tôi đặc biệt thích táo."},{"example":"今日は特に予定がないので、家でゆっくりします。","example_reading":"きょうはとくによていがないので、いえでゆっくりします。","example_meaning":"Hôm nay không có kế hoạch gì đặc biệt nên tôi ở nhà thư giãn."}],"level":"d1"},
{"word":"さらに","reading":"さらに","meaning":"hơn nữa, thêm nữa","note":"Thêm vào, mức độ tăng thêm. Cũng dùng ở đầu câu như từ nối. Văn viết.","example":"風が強まり、さらに雨も降り出した。","example_reading":"かぜがつよまり、さらにあめもふりだした。","example_meaning":"Gió mạnh lên, rồi mưa cũng bắt đầu rơi.","examples":[{"example":"風が強まり、さらに雨も降り出した。","example_reading":"かぜがつよまり、さらにあめもふりだした。","example_meaning":"Gió mạnh lên, rồi mưa cũng bắt đầu rơi."},{"example":"来週には、さらに詳しい調査結果が発表される予定だ。","example_reading":"らいしゅうには、さらにくわしいちょうさけっかがはっぴょうされるよていだ。","example_meaning":"Tuần sau dự kiến sẽ công bố kết quả điều tra chi tiết hơn nữa."}],"level":"d1"},
{"word":"ますます","reading":"ますます","meaning":"ngày càng, càng thêm","note":"Mức độ tăng dần theo thời gian. Hay đi với ～なる／増える／高まる.","example":"来月から、仕事はますます忙しくなりそうだ。","example_reading":"らいげつから、しごとはますますいそがしくなりそうだ。","example_meaning":"Từ tháng sau, công việc có vẻ sẽ ngày càng bận hơn.","examples":[{"example":"来月から、仕事はますます忙しくなりそうだ。","example_reading":"らいげつから、しごとはますますいそがしくなりそうだ。","example_meaning":"Từ tháng sau, công việc có vẻ sẽ ngày càng bận hơn."},{"example":"彼の人気は、ますます高まっている。","example_reading":"かれのにんきは、ますますたかまっている。","example_meaning":"Sự nổi tiếng của anh ấy ngày càng tăng."}],"level":"d1"},
{"word":"初めて","reading":"はじめて","meaning":"lần đầu tiên","hanviet":"sơ","antonym":"最後に（さいごに）: lần cuối / 再び（ふたたび）: lại một lần nữa / 再度（さいど）: lần nữa","antonym_hanviet":"tối hậu / tái / tái độ","note":"Đọc はじめて. Hay đi với ～た／～てから. Trải nghiệm đầu tiên.","example":"初めて日本に来たとき、雪を見て感動した。","example_reading":"はじめてにほんにきたとき、ゆきをみてかんどうした。","example_meaning":"Lần đầu đến Nhật, nhìn thấy tuyết tôi rất xúc động.","examples":[{"example":"初めて日本に来たとき、雪を見て感動した。","example_reading":"はじめてにほんにきたとき、ゆきをみてかんどうした。","example_meaning":"Lần đầu đến Nhật, nhìn thấy tuyết tôi rất xúc động."},{"example":"この料理は、初めて食べたけれど、おいしかった。","example_reading":"このりょうりは、はじめてたべたけれど、おいしかった。","example_meaning":"Món này lần đầu ăn nhưng ngon."}],"level":"d1"},
{"word":"突然","reading":"とつぜん","meaning":"đột nhiên, bất ngờ","hanviet":"đột nhiên","note":"Đọc とつぜん. Hay đi với 現れる, 起こる, 変わる. Việc xảy ra bất ngờ.","antonym":"徐々に（じょじょに）: dần dần","antonym_hanviet":"từ từ","example":"夜中に、突然電話が鳴った。","example_reading":"よなかに、とつぜんでんわがなった。","example_meaning":"Giữa đêm, điện thoại bỗng reo.","examples":[{"example":"夜中に、突然電話が鳴った。","example_reading":"よなかに、とつぜんでんわがなった。","example_meaning":"Giữa đêm, điện thoại bỗng reo."},{"example":"彼は突然会社を辞めると言い出した。","example_reading":"かれはとつぜんかいしゃをやめるといいだした。","example_meaning":"Anh ấy bỗng nói là sẽ nghỉ công ty."}],"level":"d1"},
{"word":"急に","reading":"きゅうに","meaning":"đột ngột","hanviet":"cấp","antonym":"徐々に（じょじょに）: dần dần / 次第に（しだいに）: dần dần / だんだん: dần dần","antonym_hanviet":"từ từ / thứ đệ / ","note":"Đọc きゅうに. Hay đi với 止まる, 寒くなる, 変わる. Diễn biến thay đổi nhanh.","example":"急に雨が降ってきて、傘がなくて困った。","example_reading":"きゅうにあめがふってきて、かさがなくてこまった。","example_meaning":"Trời đột ngột đổ mưa, không có ô nên khổ.","examples":[{"example":"急に雨が降ってきて、傘がなくて困った。","example_reading":"きゅうにあめがふってきて、かさがなくてこまった。","example_meaning":"Trời đột ngột đổ mưa, không có ô nên khổ."},{"example":"前の車が急に止まったので、驚いた。","example_reading":"まえのくるまがきゅうにとまったので、おどろいた。","example_meaning":"Xe phía trước đột ngột dừng nên tôi giật mình."}],"level":"d1"},
{"word":"毎回","reading":"まいかい","meaning":"mỗi lần","hanviet":"mỗi hồi","note":"Chỉ việc lặp lại mỗi lần.","example":"彼は毎回、会議に遅れてくる。","example_reading":"かれはまいかい、かいぎにおくれてくる。","example_meaning":"Lần nào anh ấy cũng đến họp muộn.","examples":[{"example":"彼は毎回、会議に遅れてくる。","example_reading":"かれはまいかい、かいぎにおくれてくる。","example_meaning":"Lần nào anh ấy cũng đến họp muộn."},{"example":"毎回同じ失敗をしてしまうので、対策を考えた。","example_reading":"まいかいおなじしっぱいをしてしまうので、たいさくをかんがえた。","example_meaning":"Lần nào cũng mắc cùng một lỗi nên tôi đã nghĩ biện pháp."}],"level":"d1"},
{"word":"近頃","reading":"ちかごろ","meaning":"dạo này, gần đây","hanviet":"cận khoảnh","antonym":"昔（むかし）: ngày xưa / 以前（いぜん）: trước đây","antonym_hanviet":"tích / dĩ tiền","note":"Nói về khoảng thời gian gần đây, thường kèm nhận xét.","example":"近頃の若者は、あまり新聞を読まないそうだ。","example_reading":"ちかごろのわかものは、あまりしんぶんをよまないそうだ。","example_meaning":"Nghe nói giới trẻ dạo này ít đọc báo.","examples":[{"example":"近頃の若者は、あまり新聞を読まないそうだ。","example_reading":"ちかごろのわかものは、あまりしんぶんをよまないそうだ。","example_meaning":"Nghe nói giới trẻ dạo này ít đọc báo."},{"example":"近頃、夜になるとよく眠れない。","example_reading":"ちかごろ、よるになるとよくねむれない。","example_meaning":"Dạo này cứ đến tối là tôi khó ngủ."}],"level":"d1"},
{"word":"途中で","reading":"とちゅうで","meaning":"giữa chừng, dọc đường","hanviet":"đồ trung","antonym":"最初から（さいしょから）: từ đầu / 最後まで（さいごまで）: đến cuối / 終始（しゅうし）: từ đầu đến cuối","antonym_hanviet":"tối sơ / tối hậu / chung thủy","note":"Hay đi với やめる, 寝る, 会う.","example":"映画の途中で、眠くなってしまった。","example_reading":"えいがのとちゅうで、ねむくなってしまった。","example_meaning":"Xem phim được nửa chừng thì tôi buồn ngủ.","examples":[{"example":"映画の途中で、眠くなってしまった。","example_reading":"えいがのとちゅうで、ねむくなってしまった。","example_meaning":"Xem phim được nửa chừng thì tôi buồn ngủ."},{"example":"途中で気が変わって、行くのをやめた。","example_reading":"とちゅうできがかわって、いくのをやめた。","example_meaning":"Giữa chừng tôi đổi ý nên không đi nữa."}],"level":"d1"},
{"word":"皆","reading":"みな","meaning":"mọi người, tất cả","hanviet":"giai","note":"Đọc みな hoặc みんな. 皆さん = quý vị, mọi người.","example":"皆、彼の意見に賛成した。","example_reading":"みな、かれのいけんにさんせいした。","example_meaning":"Mọi người đều đồng ý với ý kiến của anh ấy.","examples":[{"example":"皆、彼の意見に賛成した。","example_reading":"みな、かれのいけんにさんせいした。","example_meaning":"Mọi người đều đồng ý với ý kiến của anh ấy."},{"example":"家族は皆、元気に暮らしています。","example_reading":"かぞくはみな、げんきにくらしています。","example_meaning":"Cả nhà tôi đều sống khỏe mạnh."}],"level":"d1"},
{"word":"ついさっき","reading":"ついさっき","meaning":"mới lúc nãy","note":"Khẩu ngữ. Nhấn mạnh việc xảy ra rất gần.","example":"彼なら、ついさっきまでここにいたよ。","example_reading":"かれなら、ついさっきまでここにいたよ。","example_meaning":"Anh ấy thì mới lúc nãy còn ở đây mà.","examples":[{"example":"彼なら、ついさっきまでここにいたよ。","example_reading":"かれなら、ついさっきまでここにいたよ。","example_meaning":"Anh ấy thì mới lúc nãy còn ở đây mà."},{"example":"ついさっき、母から電話があった。","example_reading":"ついさっき、ははからでんわがあった。","example_meaning":"Mới lúc nãy mẹ tôi có gọi điện."}],"level":"d1"},
{"word":"午前中","reading":"ごぜんちゅう","meaning":"trong buổi sáng","hanviet":"ngọ tiền trung","antonym":"午後（ごご）: buổi chiều","antonym_hanviet":"ngọ hậu","note":"Chỉ khoảng thời gian trước buổi trưa.","example":"荷物は、午前中に届く予定だ。","example_reading":"にもつは、ごぜんちゅうにとどくよていだ。","example_meaning":"Hành lý dự kiến sẽ đến trong buổi sáng.","examples":[{"example":"荷物は、午前中に届く予定だ。","example_reading":"にもつは、ごぜんちゅうにとどくよていだ。","example_meaning":"Hành lý dự kiến sẽ đến trong buổi sáng."},{"example":"午前中は、会議で忙しかった。","example_reading":"ごぜんちゅうは、かいぎでいそがしかった。","example_meaning":"Cả buổi sáng tôi bận họp."}],"level":"d1"},
{"word":"大勢","reading":"おおぜい","meaning":"đông người","hanviet":"đại thế","antonym":"少人数（しょうにんずう）: ít người / 一人（ひとり）: một người","antonym_hanviet":"thiểu nhân số / nhất nhân","note":"Hay đi với の人, 集まる. Số người nhiều.","example":"駅には、大勢の人が集まっていた。","example_reading":"えきには、おおぜいのひとがあつまっていた。","example_meaning":"Ở nhà ga có rất đông người tụ tập.","examples":[{"example":"駅には、大勢の人が集まっていた。","example_reading":"えきには、おおぜいのひとがあつまっていた。","example_meaning":"Ở nhà ga có rất đông người tụ tập."},{"example":"コンサートには、大勢のファンが詰めかけた。","example_reading":"コンサートには、おおぜいのファンがつめかけた。","example_meaning":"Đông đảo người hâm mộ đổ về buổi hòa nhạc."}],"level":"d1"},
{"word":"まだまだ","reading":"まだまだ","meaning":"còn lâu mới, vẫn còn","note":"Thể hiện khiêm tốn hoặc việc còn tiếp diễn.","example":"私の日本語は、まだまだ未熟です。","example_reading":"わたしのにほんごは、まだまだみじゅくです。","example_meaning":"Tiếng Nhật của tôi còn lâu mới thành thạo.","examples":[{"example":"私の日本語は、まだまだ未熟です。","example_reading":"わたしのにほんごは、まだまだみじゅくです。","example_meaning":"Tiếng Nhật của tôi còn lâu mới thành thạo."},{"example":"まだまだ頑張らなければならない。","example_reading":"まだまだがんばらなければならない。","example_meaning":"Tôi vẫn còn phải cố gắng nhiều."}],"level":"d1"},
{"word":"この間","reading":"このあいだ","meaning":"hôm nọ, mới đây","hanviet":"gian","antonym":"今度（こんど）: lần sau","antonym_hanviet":"kim độ","note":"Hay dùng khi nhắc việc vừa xảy ra cách đây ít ngày.","example":"この間は、ご馳走になりました。","example_reading":"このあいだは、ごちそうになりました。","example_meaning":"Hôm nọ cảm ơn anh đã đãi tôi.","examples":[{"example":"この間は、ご馳走になりました。","example_reading":"このあいだは、ごちそうになりました。","example_meaning":"Hôm nọ cảm ơn anh đã đãi tôi."},{"example":"この間買った本は、とても面白かった。","example_reading":"このあいだかったほんは、とてもおもしろかった。","example_meaning":"Quyển sách mua hôm nọ rất hay."}],"level":"d1"},
{"word":"今月","reading":"こんげつ","meaning":"tháng này","hanviet":"kim nguyệt","note":"Dùng như phó từ chỉ thời gian.","antonym":"来月（らいげつ）: tháng sau","antonym_hanviet":"lai nguyệt","example":"今月は、仕事が忙しくて休みが取れない。","example_reading":"こんげつは、しごとがいそがしくてやすみがとれない。","example_meaning":"Tháng này công việc bận nên tôi không nghỉ được.","examples":[{"example":"今月は、仕事が忙しくて休みが取れない。","example_reading":"こんげつは、しごとがいそがしくてやすみがとれない。","example_meaning":"Tháng này công việc bận nên tôi không nghỉ được."},{"example":"今月末までに、レポートを提出してください。","example_reading":"こんげつまつまでに、レポートをていしゅつしてください。","example_meaning":"Xin hãy nộp báo cáo trước cuối tháng này."}],"level":"d1"},
{"word":"今週","reading":"こんしゅう","meaning":"tuần này","hanviet":"kim chu","note":"Dùng như phó từ chỉ thời gian.","example":"今週は、毎日雨が降っている。","example_reading":"こんしゅうは、まいにちあめがふっている。","example_meaning":"Tuần này ngày nào cũng mưa.","examples":[{"example":"今週は、毎日雨が降っている。","example_reading":"こんしゅうは、まいにちあめがふっている。","example_meaning":"Tuần này ngày nào cũng mưa."},{"example":"今週中に、返事をください。","example_reading":"こんしゅうちゅうに、へんじをください。","example_meaning":"Xin hãy trả lời trong tuần này."}],"level":"d1"},
{"word":"今のところ","reading":"いまのところ","meaning":"hiện tại thì, cho đến lúc này","hanviet":"kim","note":"Hay đi với 問題ない, ～ない. Chỉ tình trạng ở thời điểm hiện nay.","example":"今のところ、計画は順調に進んでいる。","example_reading":"いまのところ、けいかくはじゅんちょうにすすんでいる。","example_meaning":"Hiện tại kế hoạch đang tiến triển suôn sẻ.","examples":[{"example":"今のところ、計画は順調に進んでいる。","example_reading":"いまのところ、けいかくはじゅんちょうにすすんでいる。","example_meaning":"Hiện tại kế hoạch đang tiến triển suôn sẻ."},{"example":"今のところ、大きな問題は起きていません。","example_reading":"いまのところ、おおきなもんだいはおきていません。","example_meaning":"Cho đến lúc này chưa có vấn đề lớn nào xảy ra."}],"level":"d1"},
{"word":"ふと","reading":"ふと","meaning":"chợt, bất chợt","note":"Hay đi với 思い出す, 気づく, 目が覚める. Làm hoặc nhận ra điều gì đó không chủ ý.","example":"電車の中で、ふと昔のことを思い出した。","example_reading":"でんしゃのなかで、ふとむかしのことをおもいだした。","example_meaning":"Trên tàu, tôi chợt nhớ lại chuyện ngày xưa.","examples":[{"example":"電車の中で、ふと昔のことを思い出した。","example_reading":"でんしゃのなかで、ふとむかしのことをおもいだした。","example_meaning":"Trên tàu, tôi chợt nhớ lại chuyện ngày xưa."},{"example":"夜中にふと目が覚めて、眠れなくなった。","example_reading":"よなかにふとめがさめて、ねむれなくなった。","example_meaning":"Giữa đêm bỗng tỉnh giấc rồi không ngủ lại được."}],"level":"d1"},
{"word":"あちこち","reading":"あちこち","meaning":"đây đó, khắp nơi","note":"Hay đi với 探す, 見て回る, 傷む.","example":"財布をなくして、あちこち探し回った。","example_reading":"さいふをなくして、あちこちさがしまわった。","example_meaning":"Mất ví nên tôi tìm khắp nơi.","examples":[{"example":"財布をなくして、あちこち探し回った。","example_reading":"さいふをなくして、あちこちさがしまわった。","example_meaning":"Mất ví nên tôi tìm khắp nơi."},{"example":"古い家なので、あちこち傷んでいる。","example_reading":"ふるいいえなので、あちこちいたんでいる。","example_meaning":"Vì là nhà cũ nên chỗ nào cũng hư hỏng."}],"level":"d1"},
{"word":"直接","reading":"ちょくせつ","meaning":"trực tiếp","hanviet":"trực tiếp","antonym":"間接的に（かんせつてきに）: gián tiếp","antonym_hanviet":"gian tiếp đích","note":"Trái nghĩa: 間接. Hay đi với 会う, 聞く, 連絡する.","example":"詳しいことは、本人に直接聞いてください。","example_reading":"くわしいことは、ほんにんにちょくせつきいてください。","example_meaning":"Chi tiết xin hãy hỏi trực tiếp người đó.","examples":[{"example":"詳しいことは、本人に直接聞いてください。","example_reading":"くわしいことは、ほんにんにちょくせつきいてください。","example_meaning":"Chi tiết xin hãy hỏi trực tiếp người đó."},{"example":"太陽の光を直接見ると、目に悪い。","example_reading":"たいようのひかりをちょくせつみると、めにわるい。","example_meaning":"Nhìn trực tiếp vào ánh nắng sẽ hại mắt."}],"level":"d1"},
{"word":"一旦","reading":"いったん","meaning":"một khi, tạm thời một lần","hanviet":"nhất đán","note":"Đọc いったん. Hay đi với ～たら／～てから. Một khi đã làm thì...; hoặc tạm dừng rồi tiếp tục.","example":"一旦決めたことは、最後までやり抜く。","example_reading":"いったんきめたことは、さいごまでやりぬく。","example_meaning":"Một khi đã quyết thì tôi làm đến cùng.","examples":[{"example":"一旦決めたことは、最後までやり抜く。","example_reading":"いったんきめたことは、さいごまでやりぬく。","example_meaning":"Một khi đã quyết thì tôi làm đến cùng."},{"example":"会議を一旦休憩にして、午後に再開します。","example_reading":"かいぎをいったんきゅうけいにして、ごごにさいかいします。","example_meaning":"Cuộc họp tạm nghỉ, sẽ tiếp tục vào buổi chiều."}],"level":"d1"},
{"word":"しばらく","reading":"しばらく","meaning":"một lúc, một thời gian","antonym":"すぐ: ngay","note":"Khoảng thời gian không quá ngắn. Hay đi với ～ていない／お待ちください.","example":"疲れたので、ベンチでしばらく休んだ。","example_reading":"つかれたので、ベンチでしばらくやすんだ。","example_meaning":"Vì mệt nên tôi nghỉ một lúc trên ghế đá.","examples":[{"example":"疲れたので、ベンチでしばらく休んだ。","example_reading":"つかれたので、ベンチでしばらくやすんだ。","example_meaning":"Vì mệt nên tôi nghỉ một lúc trên ghế đá."},{"example":"祖母とはしばらく会っていないので、会いたい。","example_reading":"そぼとはしばらくあっていないので、あいたい。","example_meaning":"Lâu rồi tôi chưa gặp bà nên muốn gặp."}],"level":"d1"},
{"word":"日中","reading":"にっちゅう","meaning":"ban ngày","hanviet":"nhật trung","antonym":"夜間（やかん）: ban đêm / 夜（よる）: ban đêm / 夜中に（よなかに）: giữa đêm","antonym_hanviet":"dạ gian / dạ / dạ trung","note":"Đọc にっちゅう. Trái nghĩa: 夜間.","example":"夏の日中は、とても暑くて外に出られない。","example_reading":"なつのにっちゅうは、とてもあつくてそとにでられない。","example_meaning":"Ban ngày mùa hè nóng quá không ra ngoài được.","examples":[{"example":"夏の日中は、とても暑くて外に出られない。","example_reading":"なつのにっちゅうは、とてもあつくてそとにでられない。","example_meaning":"Ban ngày mùa hè nóng quá không ra ngoài được."},{"example":"日中は仕事で、夜だけ学校に通っている。","example_reading":"にっちゅうはしごとで、よるだけがっこうにかよっている。","example_meaning":"Ban ngày tôi đi làm, chỉ học ở trường vào buổi tối."}],"level":"d1"},
{"word":"世界中","reading":"せかいじゅう","meaning":"khắp thế giới","hanviet":"thế giới trung","note":"Hay đi với の人, に広まる.","example":"このアニメは、世界中の子どもたちに愛されている。","example_reading":"このアニメは、せかいじゅうのこどもたちにあいされている。","example_meaning":"Bộ anime này được trẻ em khắp thế giới yêu thích.","examples":[{"example":"このアニメは、世界中の子どもたちに愛されている。","example_reading":"このアニメは、せかいじゅうのこどもたちにあいされている。","example_meaning":"Bộ anime này được trẻ em khắp thế giới yêu thích."},{"example":"そのニュースは、あっという間に世界中に広まった。","example_reading":"そのニュースは、あっというまにせかいじゅうにひろまった。","example_meaning":"Tin đó lan khắp thế giới trong chớp mắt."}],"level":"d1"},
{"word":"普段","reading":"ふだん","meaning":"thường ngày, bình thường","hanviet":"phổ đoạn","antonym":"特別に（とくべつに）: đặc biệt","antonym_hanviet":"đặc biệt","note":"Đọc ふだん. Hay đi với ～は, ～から, 着る, 食べる. Trái với dịp đặc biệt.","example":"普段は電車で通勤していますが、今日は車で来ました。","example_reading":"ふだんはでんしゃでつうきんしていますが、きょうはくるまできました。","example_meaning":"Bình thường tôi đi làm bằng tàu nhưng hôm nay đi ô tô.","examples":[{"example":"普段は電車で通勤していますが、今日は車で来ました。","example_reading":"ふだんはでんしゃでつうきんしていますが、きょうはくるまできました。","example_meaning":"Bình thường tôi đi làm bằng tàu nhưng hôm nay đi ô tô."},{"example":"普段から運動しておくと、病気になりにくい。","example_reading":"ふだんからうんどうしておくと、びょうきになりにくい。","example_meaning":"Nếu thường ngày có tập thể dục thì khó bị bệnh."}],"level":"d1"},
{"word":"最近","reading":"さいきん","meaning":"dạo gần đây","hanviet":"tối cận","note":"Đọc さいきん. Hay đi với ～ている／～た. Khoảng thời gian vừa qua; cũng là danh từ.","antonym":"昔（むかし）: ngày xưa / 長年（ながねん）: nhiều năm / 昔から（むかしから）: từ xưa","antonym_hanviet":"tích / trưởng niên / tích","example":"最近、仕事が忙しくて、あまり寝ていない。","example_reading":"さいきん、しごとがいそがしくて、あまりねていない。","example_meaning":"Dạo này công việc bận nên tôi ít ngủ.","examples":[{"example":"最近、仕事が忙しくて、あまり寝ていない。","example_reading":"さいきん、しごとがいそがしくて、あまりねていない。","example_meaning":"Dạo này công việc bận nên tôi ít ngủ."},{"example":"最近になって、やっと日本の生活に慣れた。","example_reading":"さいきんになって、やっとにほんのせいかつになれた。","example_meaning":"Mãi gần đây tôi mới quen cuộc sống ở Nhật."}],"level":"d1"},
{"word":"常に","reading":"つねに","meaning":"luôn luôn","hanviet":"thường","antonym":"たまに: thỉnh thoảng / 時折（ときおり）: Đôi khi / 時には（ときには）: thỉnh thoảng","antonym_hanviet":" / thời chiết / thời","note":"Mọi lúc, không ngoại lệ. Văn viết, đánh giá. Hay đi với 心がける, ～ている.","example":"安全には常に注意してください。","example_reading":"あんぜんにはつねにちゅういしてください。","example_meaning":"Hãy luôn chú ý an toàn.","examples":[{"example":"安全には常に注意してください。","example_reading":"あんぜんにはつねにちゅういしてください。","example_meaning":"Hãy luôn chú ý an toàn."},{"example":"彼は常に冷静で、誰にも感情を見せない。","example_reading":"かれはつねにれいせいで、だれにもかんじょうをみせない。","example_meaning":"Anh ấy lúc nào cũng điềm tĩnh, không để lộ cảm xúc với ai."}],"level":"d1"},
{"word":"じきに","reading":"じきに","meaning":"chẳng bao lâu nữa","note":"Hay đi với なる, ～だろう. Gần すぐに nhưng hơi lâu hơn một chút.","example":"心配しなくても、じきに雨はやむでしょう。","example_reading":"しんぱいしなくても、じきにあめはやむでしょう。","example_meaning":"Đừng lo, chẳng bao lâu nữa mưa sẽ tạnh.","examples":[{"example":"心配しなくても、じきに雨はやむでしょう。","example_reading":"しんぱいしなくても、じきにあめはやむでしょう。","example_meaning":"Đừng lo, chẳng bao lâu nữa mưa sẽ tạnh."},{"example":"新しい生活にも、じきに慣れるよ。","example_reading":"あたらしいせいかつにも、じきになれるよ。","example_meaning":"Chẳng bao lâu nữa bạn cũng sẽ quen với cuộc sống mới."}],"level":"d1"},
{"word":"ひとまず","reading":"ひとまず","meaning":"tạm thời, trước mắt","note":"Hay đi với ～ておく, ～よう. Làm trước, chưa phải kết thúc.","example":"ひとまずここで休憩にしましょう。","example_reading":"ひとまずここできゅうけいにしましょう。","example_meaning":"Tạm thời nghỉ giải lao ở đây nhé.","examples":[{"example":"ひとまずここで休憩にしましょう。","example_reading":"ひとまずここできゅうけいにしましょう。","example_meaning":"Tạm thời nghỉ giải lao ở đây nhé."},{"example":"詳しいことは後で考えるとして、ひとまず安心した。","example_reading":"くわしいことはあとでかんがえるとして、ひとまずあんしんした。","example_meaning":"Chuyện chi tiết để sau, trước mắt tôi đã yên tâm."}],"level":"d1"},
{"word":"今朝","reading":"けさ","meaning":"sáng nay","hanviet":"kim triêu","antonym":"今晩（こんばん）: tối nay / 今夜（こんや）: đêm nay","antonym_hanviet":"kim vãn / kim dạ","note":"Đọc けさ, không đọc こんちょう trong khẩu ngữ.","example":"今朝は、いつもより早く目が覚めた。","example_reading":"けさは、いつもよりはやくめがさめた。","example_meaning":"Sáng nay tôi tỉnh dậy sớm hơn thường lệ.","examples":[{"example":"今朝は、いつもより早く目が覚めた。","example_reading":"けさは、いつもよりはやくめがさめた。","example_meaning":"Sáng nay tôi tỉnh dậy sớm hơn thường lệ."},{"example":"今朝のニュースで、台風が近づいていると知った。","example_reading":"けさのニュースで、たいふうがちかづいているとしった。","example_meaning":"Qua bản tin sáng nay, tôi biết bão đang đến gần."}],"level":"d1"},
{"word":"今晩","reading":"こんばん","meaning":"tối nay","hanviet":"kim vãn","antonym":"今朝（けさ）: sáng nay / 昨夜（さくや）: đêm qua","antonym_hanviet":"kim triêu / tạc dạ","note":"Cũng nói 今夜 (こんや).","example":"今晩、友達と食事に行く約束をしている。","example_reading":"こんばん、ともだちとしょくじにいくやくそくをしている。","example_meaning":"Tối nay tôi có hẹn đi ăn với bạn.","examples":[{"example":"今晩、友達と食事に行く約束をしている。","example_reading":"こんばん、ともだちとしょくじにいくやくそくをしている。","example_meaning":"Tối nay tôi có hẹn đi ăn với bạn."},{"example":"今晩は雨になるそうだから、傘を持っていこう。","example_reading":"こんばんはあめになるそうだから、かさをもっていこう。","example_meaning":"Nghe nói tối nay sẽ mưa nên mang ô theo thôi."}],"level":"d1"},
{"word":"今夜","reading":"こんや","meaning":"đêm nay","hanviet":"kim dạ","antonym":"今朝（けさ）: sáng nay / 昨夜（さくや）: đêm qua","antonym_hanviet":"kim triêu / tạc dạ","note":"Hơi văn chương hơn 今晩.","example":"今夜は、満月がきれいに見えるでしょう。","example_reading":"こんやは、まんげつがきれいにみえるでしょう。","example_meaning":"Đêm nay có lẽ sẽ nhìn thấy trăng tròn rất đẹp.","examples":[{"example":"今夜は、満月がきれいに見えるでしょう。","example_reading":"こんやは、まんげつがきれいにみえるでしょう。","example_meaning":"Đêm nay có lẽ sẽ nhìn thấy trăng tròn rất đẹp."},{"example":"今夜、遅くなるので、先に寝ていてください。","example_reading":"こんや、おそくなるので、さきにねていてください。","example_meaning":"Đêm nay tôi về muộn nên bạn cứ đi ngủ trước nhé."}],"level":"d1"},
{"word":"あっという間に","reading":"あっというまに","meaning":"trong chớp mắt","hanviet":"gian","antonym":"長い間（ながいあいだ）: lâu / ゆっくり: chậm rãi","antonym_hanviet":"trưởng gian / ","note":"Khẩu ngữ. Thời gian trôi hoặc việc xảy ra quá nhanh.","example":"楽しい夏休みは、あっという間に終わってしまった。","example_reading":"たのしいなつやすみは、あっというまにおわってしまった。","example_meaning":"Kỳ nghỉ hè vui vẻ đã trôi qua trong chớp mắt.","examples":[{"example":"楽しい夏休みは、あっという間に終わってしまった。","example_reading":"たのしいなつやすみは、あっというまにおわってしまった。","example_meaning":"Kỳ nghỉ hè vui vẻ đã trôi qua trong chớp mắt."},{"example":"彼はあっという間にケーキを食べ終えた。","example_reading":"かれはあっというまにケーキをたべおえた。","example_meaning":"Anh ấy ăn xong cái bánh trong nháy mắt."}],"level":"d1"},
{"word":"元々","reading":"もともと","meaning":"vốn dĩ, từ đầu","hanviet":"nguyên","note":"Chỉ trạng thái từ ban đầu, trước khi thay đổi.","example":"私は元々、人前で話すのが苦手だった。","example_reading":"わたしはもともと、ひとまえではなすのがにがてだった。","example_meaning":"Vốn dĩ tôi không giỏi nói trước đám đông.","examples":[{"example":"私は元々、人前で話すのが苦手だった。","example_reading":"わたしはもともと、ひとまえではなすのがにがてだった。","example_meaning":"Vốn dĩ tôi không giỏi nói trước đám đông."},{"example":"この店は元々、小さな本屋だった。","example_reading":"このみせはもともと、ちいさなほんやだった。","example_meaning":"Cửa hàng này ban đầu chỉ là một tiệm sách nhỏ."}],"level":"d1"},
{"word":"ほんの","reading":"ほんの","meaning":"chỉ một chút, vỏn vẹn","note":"Đứng trước danh từ: ほんの少し, ほんの一瞬. Nhấn mạnh rất ít.","example":"ほんの少し、塩を加えてください。","example_reading":"ほんのすこし、しおをくわえてください。","example_meaning":"Xin cho thêm một chút xíu muối.","examples":[{"example":"ほんの少し、塩を加えてください。","example_reading":"ほんのすこし、しおをくわえてください。","example_meaning":"Xin cho thêm một chút xíu muối."},{"example":"ほんの一瞬のうちに、財布を盗まれた。","example_reading":"ほんのいっしゅんのうちに、さいふをぬすまれた。","example_meaning":"Chỉ trong một thoáng, ví tôi đã bị lấy cắp."}],"level":"d1"},
{"word":"大きく","reading":"おおきく","meaning":"một cách lớn, mạnh","hanviet":"đại","antonym":"小さく（ちいさく）: nhỏ","antonym_hanviet":"tiểu","note":"Hay đi với 変わる, 影響する, 息を吸う. Mức độ lớn hoặc động tác rộng.","example":"この十年で、町は大きく変わった。","example_reading":"このじゅうねんで、まちはおおきくかわった。","example_meaning":"Trong mười năm qua, thị trấn đã thay đổi rất nhiều.","examples":[{"example":"この十年で、町は大きく変わった。","example_reading":"このじゅうねんで、まちはおおきくかわった。","example_meaning":"Trong mười năm qua, thị trấn đã thay đổi rất nhiều."},{"example":"緊張したら、大きく深呼吸してみてください。","example_reading":"きんちょうしたら、おおきくしんこきゅうしてみてください。","example_meaning":"Nếu căng thẳng, hãy thử hít thở thật sâu."}],"level":"d1"},
{"word":"再び","reading":"ふたたび","meaning":"lại một lần nữa","hanviet":"tái","antonym":"初めて（はじめて）: lần đầu","antonym_hanviet":"sơ","note":"Việc xảy ra lần nữa. Văn viết.","example":"彼は故郷を離れ、再び戻ることはなかった。","example_reading":"かれはこきょうをはなれ、ふたたびもどることはなかった。","example_meaning":"Anh ấy rời quê hương và không bao giờ quay lại nữa.","examples":[{"example":"彼は故郷を離れ、再び戻ることはなかった。","example_reading":"かれはこきょうをはなれ、ふたたびもどることはなかった。","example_meaning":"Anh ấy rời quê hương và không bao giờ quay lại nữa."},{"example":"台風は日本に近づき、再び勢力を強めている。","example_reading":"たいふうはにほんにちかづき、ふたたびせいりょくをつよめている。","example_meaning":"Bão tiến gần Nhật Bản và lại mạnh lên."}],"level":"d1"},
{"word":"改めて","reading":"あらためて","meaning":"một lần nữa, làm lại cho chính thức","hanviet":"cải","note":"Làm lại vào lúc khác một cách nghiêm túc, hoặc nhận ra lại. Hay đi với 伺う, 連絡する, 感じる, 考える.","example":"資料を準備して、改めてご連絡いたします。","example_reading":"しりょうをじゅんびして、あらためてごれんらくいたします。","example_meaning":"Tôi sẽ chuẩn bị tài liệu rồi liên lạc lại với anh sau.","examples":[{"example":"資料を準備して、改めてご連絡いたします。","example_reading":"しりょうをじゅんびして、あらためてごれんらくいたします。","example_meaning":"Tôi sẽ chuẩn bị tài liệu rồi liên lạc lại với anh sau."},{"example":"母の料理を食べて、家族のありがたさを改めて感じた。","example_reading":"ははのりょうりをたべて、かぞくのありがたさをあらためてかんじた。","example_meaning":"Ăn món mẹ nấu, tôi lại cảm nhận được sự quý giá của gia đình."}],"level":"d1"},
{"word":"夜中に","reading":"よなかに","meaning":"giữa đêm","hanviet":"dạ trung","antonym":"昼間（ひるま）: ban ngày / 日中（にっちゅう）: ban ngày","antonym_hanviet":"trú gian / nhật trung","note":"Hay đi với 目が覚める, 食べる, 起きる.","example":"夜中に、お腹がすいてラーメンを食べてしまった。","example_reading":"よなかに、おなかがすいてラーメンをたべてしまった。","example_meaning":"Giữa đêm đói bụng nên tôi lỡ ăn mì ramen.","examples":[{"example":"夜中に、お腹がすいてラーメンを食べてしまった。","example_reading":"よなかに、おなかがすいてラーメンをたべてしまった。","example_meaning":"Giữa đêm đói bụng nên tôi lỡ ăn mì ramen."},{"example":"隣の部屋から、夜中に大きな音が聞こえた。","example_reading":"となりのへやから、よなかにおおきなおとがきこえた。","example_meaning":"Giữa đêm có tiếng động lớn vang lên từ phòng bên cạnh."}],"level":"d1"},
{"word":"早速","reading":"さっそく","meaning":"ngay lập tức, liền","hanviet":"tảo tốc","antonym":"後で（あとで）: để sau","antonym_hanviet":"hậu","note":"Đọc さっそく. Hay đi với ～ます／～た. Bắt tay làm ngay sau khi nhận được.","example":"新しいカメラを買って、早速使ってみた。","example_reading":"あたらしいカメラをかって、さっそくつかってみた。","example_meaning":"Mua máy ảnh mới xong tôi dùng thử ngay.","examples":[{"example":"新しいカメラを買って、早速使ってみた。","example_reading":"あたらしいカメラをかって、さっそくつかってみた。","example_meaning":"Mua máy ảnh mới xong tôi dùng thử ngay."},{"example":"ご連絡ありがとうございます。早速確認いたします。","example_reading":"ごれんらくありがとうございます。さっそくかくにんいたします。","example_meaning":"Cảm ơn bạn đã liên lạc. Tôi sẽ xác nhận ngay."}],"level":"d1"},
{"word":"とりあえず","reading":"とりあえず","meaning":"trước mắt, tạm thời","note":"Làm trước đã, chưa quyết định cuối cùng. Rất hay gặp trong khẩu ngữ.","example":"注文は、とりあえずビールを二つお願いします。","example_reading":"ちゅうもんは、とりあえずビールをふたつおねがいします。","example_meaning":"Trước mắt cho tôi hai cốc bia.","examples":[{"example":"注文は、とりあえずビールを二つお願いします。","example_reading":"ちゅうもんは、とりあえずビールをふたつおねがいします。","example_meaning":"Trước mắt cho tôi hai cốc bia."},{"example":"詳しいことはあとで考えるとして、とりあえず今日は休もう。","example_reading":"くわしいことはあとでかんがえるとして、とりあえずきょうはやすもう。","example_meaning":"Chuyện chi tiết tính sau, trước mắt hôm nay cứ nghỉ đã."}],"level":"d1"},
{"word":"直ちに","reading":"ただちに","meaning":"ngay tức khắc","hanviet":"trực","note":"Đọc ただちに. Hay đi với 行う, 避難する, 対応する. Trang trọng, hay dùng trong thông báo.","antonym":"後ほど（のちほど）: lát nữa","antonym_hanviet":"hậu","example":"火災が起きたら、直ちに避難してください。","example_reading":"かさいがおきたら、ただちにひなんしてください。","example_meaning":"Khi có hỏa hoạn xin hãy sơ tán ngay lập tức.","examples":[{"example":"火災が起きたら、直ちに避難してください。","example_reading":"かさいがおきたら、ただちにひなんしてください。","example_meaning":"Khi có hỏa hoạn xin hãy sơ tán ngay lập tức."},{"example":"問題が見つかり次第、直ちに報告すること。","example_reading":"もんだいがみつかりしだい、ただちにほうこくすること。","example_meaning":"Hễ phát hiện vấn đề thì phải báo cáo ngay."}],"level":"d1"},
{"word":"長年","reading":"ながねん","meaning":"nhiều năm, lâu năm","hanviet":"trường niên","antonym":"短期間（たんきかん）: thời gian ngắn / 最近（さいきん）: dạo gần đây","antonym_hanviet":"đoản kỳ gian / tối cận","note":"Hay đi với 勤める, 続ける, の夢.","example":"彼は長年、同じ会社で働いてきた。","example_reading":"かれはながねん、おなじかいしゃではたらいてきた。","example_meaning":"Anh ấy đã làm việc ở cùng một công ty suốt nhiều năm.","examples":[{"example":"彼は長年、同じ会社で働いてきた。","example_reading":"かれはながねん、おなじかいしゃではたらいてきた。","example_meaning":"Anh ấy đã làm việc ở cùng một công ty suốt nhiều năm."},{"example":"長年の夢がついに叶った。","example_reading":"ながねんのゆめがついにかなった。","example_meaning":"Ước mơ bao năm cuối cùng đã thành hiện thực."}],"level":"d1"},
{"word":"一つ一つ","reading":"ひとつひとつ","meaning":"từng cái một","hanviet":"nhất nhất","antonym":"まとめて: gộp lại / 一度に（いちどに）: một lần","antonym_hanviet":" / nhất độ","note":"Làm cẩn thận lần lượt từng thứ.","example":"質問には一つ一つ丁寧に答えるつもりだ。","example_reading":"しつもんにはひとつひとつていねいにこたえるつもりだ。","example_meaning":"Tôi định trả lời cẩn thận từng câu hỏi một.","examples":[{"example":"質問には一つ一つ丁寧に答えるつもりだ。","example_reading":"しつもんにはひとつひとつていねいにこたえるつもりだ。","example_meaning":"Tôi định trả lời cẩn thận từng câu hỏi một."},{"example":"問題を一つ一つ解決していけば、必ず終わる。","example_reading":"もんだいをひとつひとつかいけつしていけば、かならずおわる。","example_meaning":"Nếu giải quyết từng vấn đề một thì chắc chắn sẽ xong."}],"level":"d1"},
{"word":"昨夜","reading":"さくや","meaning":"đêm qua","hanviet":"tạc dạ","antonym":"今夜（こんや）: đêm nay / 今晩（こんばん）: tối nay","antonym_hanviet":"kim dạ / kim vãn","note":"Cũng nói ゆうべ trong khẩu ngữ.","example":"昨夜は暑くて、あまりよく眠れなかった。","example_reading":"さくやはあつくて、あまりよくねむれなかった。","example_meaning":"Đêm qua nóng nên tôi ngủ không ngon.","examples":[{"example":"昨夜は暑くて、あまりよく眠れなかった。","example_reading":"さくやはあつくて、あまりよくねむれなかった。","example_meaning":"Đêm qua nóng nên tôi ngủ không ngon."},{"example":"昨夜遅く、地震があったそうだ。","example_reading":"さくやおそく、じしんがあったそうだ。","example_meaning":"Nghe nói đêm qua muộn có động đất."}],"level":"d1"},
{"word":"朝晩","reading":"あさばん","meaning":"sáng và tối","hanviet":"triêu vãn","note":"Hay đi với 冷える, 涼しい, 散歩する.","example":"朝晩は、まだ少し肌寒い。","example_reading":"あさばんは、まだすこしはだざむい。","example_meaning":"Sáng và tối vẫn còn hơi se lạnh.","examples":[{"example":"朝晩は、まだ少し肌寒い。","example_reading":"あさばんは、まだすこしはだざむい。","example_meaning":"Sáng và tối vẫn còn hơi se lạnh."},{"example":"朝晩、犬の散歩をするのが日課だ。","example_reading":"あさばん、いぬのさんぽをするのがにっかだ。","example_meaning":"Sáng tối dắt chó đi dạo là việc thường ngày của tôi."}],"level":"d1"},
{"word":"当日","reading":"とうじつ","meaning":"đúng ngày hôm đó","hanviet":"đương nhật","antonym":"前日（ぜんじつ）: ngày hôm trước / 翌日（よくじつ）: hôm sau / 後日（ごじつ）: sau này","antonym_hanviet":"tiền nhật / dực nhật / hậu nhật","note":"Chỉ ngày diễn ra sự kiện.","example":"当日は、雨でも予定どおり行います。","example_reading":"とうじつは、あめでもよていどおりおこないます。","example_meaning":"Vào ngày hôm đó, dù mưa chúng tôi vẫn tiến hành như dự kiến.","examples":[{"example":"当日は、雨でも予定どおり行います。","example_reading":"とうじつは、あめでもよていどおりおこないます。","example_meaning":"Vào ngày hôm đó, dù mưa chúng tôi vẫn tiến hành như dự kiến."},{"example":"試験当日は、早めに会場へ来てください。","example_reading":"しけんとうじつは、はやめにかいじょうへきてください。","example_meaning":"Vào ngày thi, xin hãy đến địa điểm sớm một chút."}],"level":"d1"},
{"word":"いつの間にか","reading":"いつのまにか","meaning":"từ lúc nào không hay","hanviet":"gian","note":"Hay đi với ～ていた. Thay đổi xảy ra mà không nhận ra.","example":"いつの間にか、外は暗くなっていた。","example_reading":"いつのまにか、そとはくらくなっていた。","example_meaning":"Từ lúc nào không hay, bên ngoài đã tối.","examples":[{"example":"いつの間にか、外は暗くなっていた。","example_reading":"いつのまにか、そとはくらくなっていた。","example_meaning":"Từ lúc nào không hay, bên ngoài đã tối."},{"example":"読書に夢中で、いつの間にか朝になっていた。","example_reading":"どくしょにむちゅうで、いつのまにかあさになっていた。","example_meaning":"Mải đọc sách, trời đã sáng lúc nào chẳng hay."}],"level":"d1"},
{"word":"とっくに","reading":"とっくに","meaning":"từ lâu rồi","antonym":"まだ: vẫn chưa / これから: từ nay","note":"Khẩu ngữ. Việc đã xảy ra từ lâu, hơn dự tưởng.","example":"宿題なら、とっくに終わらせたよ。","example_reading":"しゅくだいなら、とっくにおわらせたよ。","example_meaning":"Bài tập thì mình làm xong từ lâu rồi.","examples":[{"example":"宿題なら、とっくに終わらせたよ。","example_reading":"しゅくだいなら、とっくにおわらせたよ。","example_meaning":"Bài tập thì mình làm xong từ lâu rồi."},{"example":"彼はとっくに家を出たはずだ。","example_reading":"かれはとっくにいえをでたはずだ。","example_meaning":"Chắc anh ấy đã rời nhà từ lâu rồi."}],"level":"d1"},
{"word":"少し前に","reading":"すこしまえに","meaning":"cách đây một lúc","hanviet":"thiểu tiền","antonym":"少し後に（すこしあとに）: lát sau / あとで: sau đó","antonym_hanviet":"thiểu hậu / ","note":"Chỉ khoảng thời gian ngắn trước đây.","example":"少し前に、彼から電話があったよ。","example_reading":"すこしまえに、かれからでんわがあったよ。","example_meaning":"Cách đây một lúc, anh ấy có gọi điện.","examples":[{"example":"少し前に、彼から電話があったよ。","example_reading":"すこしまえに、かれからでんわがあったよ。","example_meaning":"Cách đây một lúc, anh ấy có gọi điện."},{"example":"少し前に、この道を通ったばかりだ。","example_reading":"すこしまえに、このみちをとおったばかりだ。","example_meaning":"Tôi vừa mới đi qua con đường này lúc nãy."}],"level":"d1"},
{"word":"昨年","reading":"さくねん","meaning":"năm ngoái","hanviet":"tạc niên","antonym":"来年（らいねん）: năm sau","antonym_hanviet":"lai niên","note":"Trang trọng hơn 去年.","example":"昨年に比べて、売り上げが二割増えた。","example_reading":"さくねんにくらべて、うりあげがにわりふえた。","example_meaning":"So với năm ngoái, doanh thu tăng hai thành.","examples":[{"example":"昨年に比べて、売り上げが二割増えた。","example_reading":"さくねんにくらべて、うりあげがにわりふえた。","example_meaning":"So với năm ngoái, doanh thu tăng hai thành."},{"example":"彼は昨年、大学を卒業した。","example_reading":"かれはさくねん、だいがくをそつぎょうした。","example_meaning":"Anh ấy tốt nghiệp đại học vào năm ngoái."}],"level":"d1"},
{"word":"たった今","reading":"たったいま","meaning":"ngay vừa rồi","hanviet":"kim","note":"Hay đi với ～たところだ. Nhấn mạnh việc vừa xảy ra.","example":"たった今、電車が出てしまった。","example_reading":"たったいま、でんしゃがでてしまった。","example_meaning":"Tàu vừa mới chạy mất rồi.","examples":[{"example":"たった今、電車が出てしまった。","example_reading":"たったいま、でんしゃがでてしまった。","example_meaning":"Tàu vừa mới chạy mất rồi."},{"example":"たった今、ニュースで知ったばかりだ。","example_reading":"たったいま、ニュースでしったばかりだ。","example_meaning":"Tôi vừa mới biết qua bản tin xong."}],"level":"d1"},
{"word":"わずか","reading":"わずか","meaning":"chỉ, ít ỏi","antonym":"たくさん: nhiều / 大量に（たいりょうに）: số lượng lớn / いっぱい: đầy","antonym_hanviet":" / đại lượng / ","note":"Hay đi với わずか三日, わずか一点. Số lượng hoặc mức độ rất nhỏ.","example":"残された時間は、わずか三日しかない。","example_reading":"のこされたじかんは、わずかみっかしかない。","example_meaning":"Thời gian còn lại chỉ có ba ngày.","examples":[{"example":"残された時間は、わずか三日しかない。","example_reading":"のこされたじかんは、わずかみっかしかない。","example_meaning":"Thời gian còn lại chỉ có ba ngày."},{"example":"彼との差は、わずか一点だった。","example_reading":"かれとのさは、わずかいってんだった。","example_meaning":"Cách biệt với anh ấy chỉ một điểm."}],"level":"d1"},
{"word":"当時","reading":"とうじ","meaning":"thời đó","hanviet":"đương thời","antonym":"現在（げんざい）: hiện tại / 今（いま）: bây giờ","antonym_hanviet":"hiện tại / kim","note":"Hay đi với の, は. Chỉ thời điểm đã trôi qua.","example":"当時の私は、まだ何も知らない子どもだった。","example_reading":"とうじのわたしは、まだなにもしらないこどもだった。","example_meaning":"Tôi thời ấy chỉ là đứa trẻ chưa biết gì.","examples":[{"example":"当時の私は、まだ何も知らない子どもだった。","example_reading":"とうじのわたしは、まだなにもしらないこどもだった。","example_meaning":"Tôi thời ấy chỉ là đứa trẻ chưa biết gì."},{"example":"この写真は、当時の様子をよく伝えている。","example_reading":"このしゃしんは、とうじのようすをよくつたえている。","example_meaning":"Bức ảnh này truyền tải rõ khung cảnh thời đó."}],"level":"d1"},
{"word":"明け方に","reading":"あけがたに","meaning":"lúc rạng đông","hanviet":"minh phương","antonym":"夕方（ゆうがた）: chiều tối","antonym_hanviet":"tịch phương","note":"Hay đi với 目が覚める, 眠る, 降る.","example":"昨夜は遅く寝て、明け方にやっと眠った。","example_reading":"ゆうべはおそくねて、あけがたにやっとねむった。","example_meaning":"Đêm qua tôi ngủ muộn, đến rạng sáng mới ngủ được.","examples":[{"example":"昨夜は遅く寝て、明け方にやっと眠った。","example_reading":"ゆうべはおそくねて、あけがたにやっとねむった。","example_meaning":"Đêm qua tôi ngủ muộn, đến rạng sáng mới ngủ được."},{"example":"明け方に、遠くで雷が鳴っていた。","example_reading":"あけがたに、とおくでかみなりがなっていた。","example_meaning":"Lúc rạng đông, có tiếng sấm xa xa."}],"level":"d1"},
{"word":"真夜中に","reading":"まよなかに","meaning":"vào giữa đêm khuya","hanviet":"chân dạ trung","antonym":"真昼に（まひるに）: giữa trưa / 昼間（ひるま）: ban ngày","antonym_hanviet":"chân trú / trú gian","note":"Khoảng thời gian khuya nhất trong đêm.","example":"真夜中に、突然電話が鳴って目が覚めた。","example_reading":"まよなかに、とつぜんでんわがなってめがさめた。","example_meaning":"Giữa đêm khuya, điện thoại reo bất ngờ khiến tôi tỉnh giấc.","examples":[{"example":"真夜中に、突然電話が鳴って目が覚めた。","example_reading":"まよなかに、とつぜんでんわがなってめがさめた。","example_meaning":"Giữa đêm khuya, điện thoại reo bất ngờ khiến tôi tỉnh giấc."},{"example":"彼は真夜中に、一人で海へ出かけていった。","example_reading":"かれはまよなかに、ひとりでうみへでかけていった。","example_meaning":"Anh ấy một mình ra biển lúc nửa đêm."}],"level":"d1"},
{"word":"明後日","reading":"あさって","meaning":"ngày kia","hanviet":"minh hậu nhật","antonym":"一昨日（おととい）: hôm kia","antonym_hanviet":"nhất tạc nhật","note":"Đọc あさって.","example":"明後日から、三日間出張に行く。","example_reading":"あさってから、みっかかんしゅっちょうにいく。","example_meaning":"Từ ngày kia, tôi đi công tác ba ngày.","examples":[{"example":"明後日から、三日間出張に行く。","example_reading":"あさってから、みっかかんしゅっちょうにいく。","example_meaning":"Từ ngày kia, tôi đi công tác ba ngày."},{"example":"明後日の午後、時間はありますか。","example_reading":"あさってのごご、じかんはありますか。","example_meaning":"Chiều ngày kia bạn có rảnh không?"}],"level":"d1"},
{"word":"一昨日","reading":"おととい","meaning":"hôm kia","hanviet":"nhất tạc nhật","antonym":"明後日（あさって）: ngày kia","antonym_hanviet":"minh hậu nhật","note":"Đọc おととい (ít khi いっさくじつ).","example":"一昨日、友達と映画を見に行った。","example_reading":"おととい、ともだちとえいがをみにいった。","example_meaning":"Hôm kia tôi đi xem phim với bạn.","examples":[{"example":"一昨日、友達と映画を見に行った。","example_reading":"おととい、ともだちとえいがをみにいった。","example_meaning":"Hôm kia tôi đi xem phim với bạn."},{"example":"一昨日の夜から、ずっと雨が降っている。","example_reading":"おとといのよるから、ずっとあめがふっている。","example_meaning":"Từ tối hôm kia trời mưa suốt."}],"level":"d1"},
{"word":"目下","reading":"もっか","meaning":"hiện nay, trước mắt","hanviet":"mục hạ","note":"Văn viết, trang trọng. Hay đi với 調査中, 検討中.","example":"事故の原因は、目下調査中です。","example_reading":"じこのげんいんは、もっかちょうさちゅうです。","example_meaning":"Nguyên nhân tai nạn hiện đang được điều tra.","examples":[{"example":"事故の原因は、目下調査中です。","example_reading":"じこのげんいんは、もっかちょうさちゅうです。","example_meaning":"Nguyên nhân tai nạn hiện đang được điều tra."},{"example":"目下のところ、新しい情報は入っていない。","example_reading":"もっかのところ、あたらしいじょうほうははいっていない。","example_meaning":"Hiện tại vẫn chưa có thông tin mới."}],"level":"d1"},
{"word":"先ほど","reading":"さきほど","meaning":"lúc nãy, vừa nãy","hanviet":"tiên","antonym":"のちほど: lát nữa / 後で（あとで）: sau đó","antonym_hanviet":" / hậu","note":"Đọc さきほど. Lịch sự hơn さっき. Dùng trong công việc, thông báo.","example":"先ほどはお電話をありがとうございました。","example_reading":"さきほどはおでんわをありがとうございました。","example_meaning":"Cảm ơn bạn vì cuộc gọi lúc nãy.","examples":[{"example":"先ほどはお電話をありがとうございました。","example_reading":"さきほどはおでんわをありがとうございました。","example_meaning":"Cảm ơn bạn vì cuộc gọi lúc nãy."},{"example":"先ほどお渡しした資料をご覧ください。","example_reading":"さきほどおわたししたしりょうをごらんください。","example_meaning":"Xin hãy xem tài liệu tôi vừa đưa."}],"level":"d1"},
{"word":"久々に","reading":"ひさびさに","meaning":"lâu rồi mới","hanviet":"cửu","antonym":"頻繁に（ひんぱんに）: thường xuyên / いつも: luôn luôn","antonym_hanviet":"tần phồn / ","note":"Khẩu ngữ hơn 久しぶりに.","example":"久々に実家に帰って、母の料理を食べた。","example_reading":"ひさびさにじっかにかえって、ははのりょうりをたべた。","example_meaning":"Lâu lắm mới về nhà bố mẹ, tôi được ăn cơm mẹ nấu.","examples":[{"example":"久々に実家に帰って、母の料理を食べた。","example_reading":"ひさびさにじっかにかえって、ははのりょうりをたべた。","example_meaning":"Lâu lắm mới về nhà bố mẹ, tôi được ăn cơm mẹ nấu."},{"example":"久々に高校の友達と会って、昔話で盛り上がった。","example_reading":"ひさびさにこうこうのともだちとあって、むかしばなしでもりあがった。","example_meaning":"Lâu rồi mới gặp bạn cấp ba, chúng tôi nói chuyện ngày xưa rất rôm rả."}],"level":"d1"},
{"word":"ごく","reading":"ごく","meaning":"rất, cực kỳ (ít, bình thường)","note":"Hay đi với ごく普通, ごく簡単, ごく一部. Chỉ mức độ nhỏ hoặc bình thường.","example":"これはごく普通の家庭料理です。","example_reading":"これはごくふつうのかていりょうりです。","example_meaning":"Đây chỉ là món ăn gia đình rất bình thường.","examples":[{"example":"これはごく普通の家庭料理です。","example_reading":"これはごくふつうのかていりょうりです。","example_meaning":"Đây chỉ là món ăn gia đình rất bình thường."},{"example":"そのうわさを信じている人は、ごく一部にすぎない。","example_reading":"そのうわさをしんじているひとは、ごくいちぶにすぎない。","example_meaning":"Người tin lời đồn đó chỉ là một số rất ít."}],"level":"d1"},
{"word":"一部","reading":"いちぶ","meaning":"một phần","hanviet":"nhất bộ","antonym":"全部（ぜんぶ）: toàn bộ / 全て（すべて）: tất cả / 大部分（だいぶぶん）: phần lớn","antonym_hanviet":"toàn bộ / toàn / đại bộ phân","note":"Hay đi với 一部の人, 一部修正.","example":"一部の地域では、今夜から雪が降るでしょう。","example_reading":"いちぶのちいきでは、こんやからゆきがふるでしょう。","example_meaning":"Ở một số khu vực, từ tối nay sẽ có tuyết rơi.","examples":[{"example":"一部の地域では、今夜から雪が降るでしょう。","example_reading":"いちぶのちいきでは、こんやからゆきがふるでしょう。","example_meaning":"Ở một số khu vực, từ tối nay sẽ có tuyết rơi."},{"example":"契約書の一部を書き直す必要がある。","example_reading":"けいやくしょのいちぶをかきなおすひつようがある。","example_meaning":"Cần viết lại một phần của hợp đồng."}],"level":"d1"},
{"word":"順番に","reading":"じゅんばんに","meaning":"lần lượt, theo thứ tự","hanviet":"thuận phiên","antonym":"同時に（どうじに）: đồng thời / 一斉に（いっせいに）: đồng loạt / ばらばらに: rời rạc","antonym_hanviet":"đồng thời / nhất tề / ","note":"Hay đi với 並ぶ, 呼ぶ, 進む. Làm lần lượt từng người, từng việc.","example":"名前を呼ばれたら、順番に中へ入ってください。","example_reading":"なまえをよばれたら、じゅんばんになかへはいってください。","example_meaning":"Khi được gọi tên, xin lần lượt vào bên trong.","examples":[{"example":"名前を呼ばれたら、順番に中へ入ってください。","example_reading":"なまえをよばれたら、じゅんばんになかへはいってください。","example_meaning":"Khi được gọi tên, xin lần lượt vào bên trong."},{"example":"一人ずつ順番に自己紹介をしていった。","example_reading":"ひとりずつじゅんばんにじこしょうかいをしていった。","example_meaning":"Từng người lần lượt tự giới thiệu."}],"level":"d1"},
{"word":"互いに","reading":"たがいに","meaning":"lẫn nhau","hanviet":"hỗ","antonym":"一方的に（いっぽうてきに）: đơn phương","antonym_hanviet":"nhất phương đích","note":"Hay đi với 助け合う, 尊重する, 理解する.","example":"二人は互いに助け合いながら、困難を乗り越えた。","example_reading":"ふたりはたがいにたすけあいながら、こんなんをのりこえた。","example_meaning":"Hai người giúp đỡ lẫn nhau và vượt qua khó khăn.","examples":[{"example":"二人は互いに助け合いながら、困難を乗り越えた。","example_reading":"ふたりはたがいにたすけあいながら、こんなんをのりこえた。","example_meaning":"Hai người giúp đỡ lẫn nhau và vượt qua khó khăn."},{"example":"互いに意見を尊重することが大切だ。","example_reading":"たがいにいけんをそんちょうすることがたいせつだ。","example_meaning":"Điều quan trọng là tôn trọng ý kiến lẫn nhau."}],"level":"d1"},
{"word":"即座に","reading":"そくざに","meaning":"ngay lập tức, tại chỗ","hanviet":"tức tọa","antonym":"徐々に（じょじょに）: dần dần","antonym_hanviet":"từ từ","note":"Đọc そくざに. Hay đi với 答える, 断る, 判断する. Không chút chần chừ.","example":"彼は私の質問に即座に答えた。","example_reading":"かれはわたしのしつもんにそくざにこたえた。","example_meaning":"Anh ấy trả lời câu hỏi của tôi ngay tức thì.","examples":[{"example":"彼は私の質問に即座に答えた。","example_reading":"かれはわたしのしつもんにそくざにこたえた。","example_meaning":"Anh ấy trả lời câu hỏi của tôi ngay tức thì."},{"example":"危険を感じて、即座に逃げ出した。","example_reading":"きけんをかんじて、そくざににげだした。","example_meaning":"Cảm thấy nguy hiểm, tôi bỏ chạy ngay."}],"level":"d1"},
{"word":"早急に","reading":"さっきゅうに","meaning":"gấp, khẩn trương","hanviet":"tảo cấp","antonym":"ゆっくり: chậm rãi","note":"Đọc さっきゅうに (cũng そうきゅうに). Hay đi với 対応する, 解決する, 連絡する. Trang trọng, dùng trong công việc.","example":"この問題は早急に対応する必要がある。","example_reading":"このもんだいはさっきゅうにたいおうするひつようがある。","example_meaning":"Vấn đề này cần xử lý khẩn trương.","examples":[{"example":"この問題は早急に対応する必要がある。","example_reading":"このもんだいはさっきゅうにたいおうするひつようがある。","example_meaning":"Vấn đề này cần xử lý khẩn trương."},{"example":"早急にご連絡いただけますと助かります。","example_reading":"さっきゅうにごれんらくいただけますとたすかります。","example_meaning":"Nếu quý vị liên lạc sớm cho chúng tôi thì thật cảm kích."}],"level":"d1"},
{"word":"近々","reading":"ちかぢか","meaning":"sắp tới, ít hôm nữa","hanviet":"cận cận","antonym":"遠い将来に（とおいしょうらいに）: tương lai xa","antonym_hanviet":"viễn tương lai","note":"Hay đi với 発表する, 開店する, お会いする.","example":"新しい店が近々オープンする予定だ。","example_reading":"あたらしいみせがちかぢかオープンするよていだ。","example_meaning":"Dự định cửa hàng mới sẽ khai trương trong ít ngày tới.","examples":[{"example":"新しい店が近々オープンする予定だ。","example_reading":"あたらしいみせがちかぢかオープンするよていだ。","example_meaning":"Dự định cửa hàng mới sẽ khai trương trong ít ngày tới."},{"example":"近々、皆さんにお会いできるのを楽しみにしています。","example_reading":"ちかぢか、みなさんにおあいできるのをたのしみにしています。","example_meaning":"Tôi mong sớm được gặp mọi người trong những ngày tới."}],"level":"d1"},
{"word":"事前に","reading":"じぜんに","meaning":"trước, từ trước","hanviet":"sự tiền","antonym":"事後に（じごに）: sau sự việc / 後から（あとから）: sau đó","antonym_hanviet":"sự hậu / hậu","note":"Hay đi với 連絡する, 準備する, 確認する.","example":"訪問する前に、事前に連絡を入れてください。","example_reading":"ほうもんするまえに、じぜんにれんらくをいれてください。","example_meaning":"Trước khi đến thăm, xin hãy liên lạc trước.","examples":[{"example":"訪問する前に、事前に連絡を入れてください。","example_reading":"ほうもんするまえに、じぜんにれんらくをいれてください。","example_meaning":"Trước khi đến thăm, xin hãy liên lạc trước."},{"example":"事前に資料を読んでおくと、会議がスムーズに進む。","example_reading":"じぜんにしりょうをよんでおくと、かいぎがスムーズにすすむ。","example_meaning":"Đọc tài liệu trước thì cuộc họp sẽ suôn sẻ."}],"level":"d1"},
{"word":"当初","reading":"とうしょ","meaning":"ban đầu, lúc đầu","hanviet":"đương sơ","antonym":"最終的に（さいしゅうてきに）: cuối cùng / 現在（げんざい）: hiện tại","antonym_hanviet":"tối chung đích / hiện tại","note":"Hay đi với 当初は, 当初の計画. Chỉ lúc mới bắt đầu.","example":"当初の予定では、今月中に完成するはずだった。","example_reading":"とうしょのよていでは、こんげつちゅうにかんせいするはずだった。","example_meaning":"Theo dự kiến ban đầu, tháng này lẽ ra đã hoàn thành.","examples":[{"example":"当初の予定では、今月中に完成するはずだった。","example_reading":"とうしょのよていでは、こんげつちゅうにかんせいするはずだった。","example_meaning":"Theo dự kiến ban đầu, tháng này lẽ ra đã hoàn thành."},{"example":"当初は反対していた父も、最後には賛成してくれた。","example_reading":"とうしょははんたいしていたちちも、さいごにはさんせいしてくれた。","example_meaning":"Bố tôi lúc đầu phản đối nhưng cuối cùng cũng đồng ý."}],"level":"d1"},
{"word":"近年","reading":"きんねん","meaning":"những năm gần đây","hanviet":"cận niên","antonym":"昔（むかし）: ngày xưa / 古来（こらい）: từ xa xưa","antonym_hanviet":"tích / cổ lai","note":"Văn viết. Hay đi với 増える, 注目される.","example":"近年、この地域では外国人観光客が急増している。","example_reading":"きんねん、このちいきではがいこくじんかんこうきゃくがきゅうぞうしている。","example_meaning":"Những năm gần đây, khách du lịch nước ngoài tăng vọt ở khu vực này.","examples":[{"example":"近年、この地域では外国人観光客が急増している。","example_reading":"きんねん、このちいきではがいこくじんかんこうきゃくがきゅうぞうしている。","example_meaning":"Những năm gần đây, khách du lịch nước ngoài tăng vọt ở khu vực này."},{"example":"近年の気候変動は、農業に大きな影響を与えている。","example_reading":"きんねんのきこうへんどうは、のうぎょうにおおきなえいきょうをあたえている。","example_meaning":"Biến đổi khí hậu những năm gần đây ảnh hưởng lớn đến nông nghiệp."}],"level":"d1"},
{"word":"立て続けに","reading":"たてつづけに","meaning":"liên tiếp, dồn dập","hanviet":"lập tục","antonym":"間を置いて（あいだをおいて）: cách quãng / たまに: thỉnh thoảng","antonym_hanviet":"gian trí / ","note":"Hay đi với 起こる, 鳴る, 受賞する.","example":"立て続けに三回も電話が鳴って、驚いた。","example_reading":"たてつづけにさんかいもでんわがなって、おどろいた。","example_meaning":"Điện thoại reo liên tiếp ba lần khiến tôi giật mình.","examples":[{"example":"立て続けに三回も電話が鳴って、驚いた。","example_reading":"たてつづけにさんかいもでんわがなって、おどろいた。","example_meaning":"Điện thoại reo liên tiếp ba lần khiến tôi giật mình."},{"example":"彼は立て続けに二つの賞を受賞した。","example_reading":"かれはたてつづけにふたつのしょうをじゅしょうした。","example_meaning":"Anh ấy nhận liên tiếp hai giải thưởng."}],"level":"d1"},
{"word":"次から次へと","reading":"つぎからつぎへと","meaning":"hết cái này đến cái khác","hanviet":"thứ","note":"Hay đi với 起こる, 現れる, 入ってくる.","example":"次から次へと問題が起こって、休む暇がない。","example_reading":"つぎからつぎへともんだいがおこって、やすむひまがない。","example_meaning":"Vấn đề cứ nảy sinh liên tục nên tôi không có thời gian nghỉ.","examples":[{"example":"次から次へと問題が起こって、休む暇がない。","example_reading":"つぎからつぎへともんだいがおこって、やすむひまがない。","example_meaning":"Vấn đề cứ nảy sinh liên tục nên tôi không có thời gian nghỉ."},{"example":"店には、次から次へと客が入ってきた。","example_reading":"みせには、つぎからつぎへときゃくがはいってきた。","example_meaning":"Khách lần lượt kéo vào cửa hàng."}],"level":"d1"},
{"word":"思い切り","reading":"おもいきり","meaning":"hết sức, thỏa thích","hanviet":"tư thiết","antonym":"遠慮がちに（えんりょがちに）: dè dặt / 控えめに（ひかえめに）: vừa phải","antonym_hanviet":"viễn lự / khống","note":"Hay đi với 走る, 蹴る, 泣く. Làm không giữ lại.","example":"久しぶりに、思い切り走った。","example_reading":"ひさしぶりに、おもいきりはしった。","example_meaning":"Lâu rồi tôi mới chạy hết sức.","examples":[{"example":"久しぶりに、思い切り走った。","example_reading":"ひさしぶりに、おもいきりはしった。","example_meaning":"Lâu rồi tôi mới chạy hết sức."},{"example":"彼はボールを思い切り蹴り上げた。","example_reading":"かれはボールをおもいきりけりあげた。","example_meaning":"Anh ấy đá bóng lên thật mạnh."}],"level":"d1"},
{"word":"翌日","reading":"よくじつ","meaning":"hôm sau","hanviet":"dực nhật","antonym":"前日（ぜんじつ）: ngày hôm trước / 当日（とうじつ）: đúng ngày hôm đó","antonym_hanviet":"tiền nhật / đương nhật","note":"Ngày liền sau ngày vừa nhắc.","example":"遅くまで飲んだ翌日は、体がだるい。","example_reading":"おそくまでのんだよくじつは、からだがだるい。","example_meaning":"Hôm sau khi uống đến khuya, người tôi uể oải.","examples":[{"example":"遅くまで飲んだ翌日は、体がだるい。","example_reading":"おそくまでのんだよくじつは、からだがだるい。","example_meaning":"Hôm sau khi uống đến khuya, người tôi uể oải."},{"example":"試験の翌日、結果が発表された。","example_reading":"しけんのよくじつ、けっかがはっぴょうされた。","example_meaning":"Hôm sau kỳ thi, kết quả được công bố."}],"level":"d1"},
{"word":"前日","reading":"ぜんじつ","meaning":"ngày hôm trước","hanviet":"tiền nhật","antonym":"翌日（よくじつ）: hôm sau / 当日（とうじつ）: đúng ngày","antonym_hanviet":"dực nhật / đương nhật","note":"Ngày liền trước sự kiện.","example":"試験の前日は、早めに寝るようにしている。","example_reading":"しけんのぜんじつは、はやめにねるようにしている。","example_meaning":"Trước ngày thi, tôi cố gắng đi ngủ sớm.","examples":[{"example":"試験の前日は、早めに寝るようにしている。","example_reading":"しけんのぜんじつは、はやめにねるようにしている。","example_meaning":"Trước ngày thi, tôi cố gắng đi ngủ sớm."},{"example":"出発の前日に、荷物の最終確認をした。","example_reading":"しゅっぱつのぜんじつに、にもつのさいしゅうかくにんをした。","example_meaning":"Ngày trước khi khởi hành, tôi kiểm tra lại hành lý lần cuối."}],"level":"d1"},
{"word":"連日","reading":"れんじつ","meaning":"ngày nào cũng, nhiều ngày liên tiếp","hanviet":"liên nhật","antonym":"たまに: thỉnh thoảng / 時たま（ときたま）: thỉnh thoảng","antonym_hanviet":" / thời","note":"Hay đi với 猛暑, 報道, 続く.","example":"連日の猛暑で、体調を崩す人が増えている。","example_reading":"れんじつのもうしょで、たいちょうをくずすひとがふえている。","example_meaning":"Do nắng nóng liên tiếp nhiều ngày, số người ốm tăng lên.","examples":[{"example":"連日の猛暑で、体調を崩す人が増えている。","example_reading":"れんじつのもうしょで、たいちょうをくずすひとがふえている。","example_meaning":"Do nắng nóng liên tiếp nhiều ngày, số người ốm tăng lên."},{"example":"連日、遅くまで残業が続いている。","example_reading":"れんじつ、おそくまでざんぎょうがつづいている。","example_meaning":"Nhiều ngày liền tôi phải làm thêm đến khuya."}],"level":"d1"},
{"word":"今のうちに","reading":"いまのうちに","meaning":"nhân lúc này, trong lúc còn","hanviet":"kim","note":"Hay đi với ～ておく. Làm trước khi tình trạng thay đổi.","example":"雨が降る前に、今のうちに洗濯物を取り込もう。","example_reading":"あめがふるまえに、いまのうちにせんたくものをとりこもう。","example_meaning":"Nhân lúc này mau thu quần áo vào trước khi mưa.","examples":[{"example":"雨が降る前に、今のうちに洗濯物を取り込もう。","example_reading":"あめがふるまえに、いまのうちにせんたくものをとりこもう。","example_meaning":"Nhân lúc này mau thu quần áo vào trước khi mưa."},{"example":"若い今のうちに、いろいろな経験をしておきたい。","example_reading":"わかいいまのうちに、いろいろなけいけんをしておきたい。","example_meaning":"Nhân lúc còn trẻ, tôi muốn trải nghiệm nhiều điều."}],"level":"d1"},
{"word":"まもなく","reading":"まもなく","meaning":"sắp, chẳng bao lâu nữa","note":"Thời gian ngắn sắp tới. Dùng trong thông báo. Dạng V＋まもなく: \"ngay sau khi ～\".","example":"まもなく一番線に、電車が参ります。","example_reading":"まもなくいちばんせんに、でんしゃがまいります。","example_meaning":"Chẳng bao lâu nữa tàu sẽ vào sân ga số 1.","examples":[{"example":"まもなく一番線に、電車が参ります。","example_reading":"まもなくいちばんせんに、でんしゃがまいります。","example_meaning":"Chẳng bao lâu nữa tàu sẽ vào sân ga số 1."},{"example":"家に着いてまもなく、友達から電話がかかってきた。","example_reading":"いえについてまもなく、ともだちからでんわがかかってきた。","example_meaning":"Tôi vừa về đến nhà thì bạn gọi điện đến."}],"level":"d1"},
{"word":"やがて","reading":"やがて","meaning":"rồi thì, chẳng bao lâu sau","note":"Thời gian trôi qua rồi sự việc xảy ra. Văn viết, hay dùng khi kể chuyện.","example":"空が暗くなり、やがて雨が降り出した。","example_reading":"そらがくらくなり、やがてあめがふりだした。","example_meaning":"Bầu trời tối sầm, rồi chẳng bao lâu mưa bắt đầu rơi.","examples":[{"example":"空が暗くなり、やがて雨が降り出した。","example_reading":"そらがくらくなり、やがてあめがふりだした。","example_meaning":"Bầu trời tối sầm, rồi chẳng bao lâu mưa bắt đầu rơi."},{"example":"若者はやがて立派な医者になった。","example_reading":"わかものはやがてりっぱないしゃになった。","example_meaning":"Chàng trai rồi cũng trở thành một bác sĩ tài giỏi."}],"level":"d1"},
{"word":"ついに","reading":"ついに","meaning":"cuối cùng thì, rốt cuộc","note":"Hay đi với ～た (đạt được hoặc xảy ra sau thời gian dài). Cũng dùng với ～なかった.","example":"十年の努力が実り、ついに夢が叶った。","example_reading":"じゅうねんのどりょくがみのり、ついにゆめがかなった。","example_meaning":"Nỗ lực mười năm đơm hoa, cuối cùng ước mơ đã thành.","examples":[{"example":"十年の努力が実り、ついに夢が叶った。","example_reading":"じゅうねんのどりょくがみのり、ついにゆめがかなった。","example_meaning":"Nỗ lực mười năm đơm hoa, cuối cùng ước mơ đã thành."},{"example":"彼はついに会社を辞める決心をした。","example_reading":"かれはついにかいしゃをやめるけっしんをした。","example_meaning":"Rốt cuộc anh ấy đã quyết định nghỉ việc."}],"level":"d1"},
{"word":"最も","reading":"もっとも","meaning":"nhất, cực kỳ","hanviet":"tối","note":"Trang trọng hơn 一番. Chú ý: khác với もっとも (tuy nhiên) ở nhóm e1.","example":"これは日本で最も古い神社の一つだ。","example_reading":"これはにほんでもっともふるいじんじゃのひとつだ。","example_meaning":"Đây là một trong những ngôi đền cổ nhất Nhật Bản.","examples":[{"example":"これは日本で最も古い神社の一つだ。","example_reading":"これはにほんでもっともふるいじんじゃのひとつだ。","example_meaning":"Đây là một trong những ngôi đền cổ nhất Nhật Bản."},{"example":"今回の調査で、最も多かった意見は「時間が足りない」だった。","example_reading":"こんかいのちょうさで、もっともおおかったいけんは「じかんがたりない」だった。","example_meaning":"Trong cuộc khảo sát lần này, ý kiến nhiều nhất là \"không đủ thời gian\"."}],"level":"d1"},
{"word":"当分","reading":"とうぶん","meaning":"trong thời gian tới, tạm thời","hanviet":"đương phân","note":"Hay đi với ～ない, ～つもりだ, ～続きそうだ.","example":"怪我をしたので、当分運動はできない。","example_reading":"けがをしたので、とうぶんうんどうはできない。","example_meaning":"Vì bị thương nên tạm thời tôi không thể tập thể dục.","examples":[{"example":"怪我をしたので、当分運動はできない。","example_reading":"けがをしたので、とうぶんうんどうはできない。","example_meaning":"Vì bị thương nên tạm thời tôi không thể tập thể dục."},{"example":"この商品は人気で、当分品切れが続きそうだ。","example_reading":"このしょうひんはにんきで、とうぶんしなぎれがつづきそうだ。","example_meaning":"Sản phẩm này đang hot nên có vẻ sẽ hết hàng một thời gian."}],"level":"d1"},
{"word":"割に","reading":"わりに","meaning":"khá là, so với","hanviet":"cát","note":"Hay đi với ～わりに: 値段の割に, 年の割に. So với mức thông thường thì khác.","example":"この店は値段が安い割においしい。","example_reading":"このみせはねだんがやすいわりにおいしい。","example_meaning":"Quán này so với giá rẻ thì ngon.","examples":[{"example":"この店は値段が安い割においしい。","example_reading":"このみせはねだんがやすいわりにおいしい。","example_meaning":"Quán này so với giá rẻ thì ngon."},{"example":"彼は年の割に若く見える。","example_reading":"かれはとしのわりにわかくみえる。","example_meaning":"Anh ấy trông trẻ so với tuổi."}],"level":"d1"},
{"word":"まあまあ","reading":"まあまあ","meaning":"tàm tạm, cũng được","note":"Hay dùng khi trả lời: まあまあです. Đánh giá trung bình.","example":"昨日見た映画は、まあまあ面白かった。","example_reading":"きのうみたえいがは、まあまあおもしろかった。","example_meaning":"Bộ phim hôm qua xem cũng tàm tạm, khá hay.","examples":[{"example":"昨日見た映画は、まあまあ面白かった。","example_reading":"きのうみたえいがは、まあまあおもしろかった。","example_meaning":"Bộ phim hôm qua xem cũng tàm tạm, khá hay."},{"example":"「テストはどうだった？」「まあまあかな。」","example_reading":"「テストはどうだった？」「まあまあかな。」","example_meaning":"\"Bài kiểm tra thế nào?\" \"Tàm tạm thôi.\""}],"level":"d1"},
{"word":"急激に","reading":"きゅうげきに","meaning":"đột ngột, mạnh mẽ (thay đổi)","hanviet":"cấp kích","antonym":"緩やかに（ゆるやかに）: chậm rãi / 徐々に（じょじょに）: dần dần","antonym_hanviet":"hoãn / từ từ","note":"Hay đi với 増える, 変わる, 下がる. Văn viết, dùng nhiều trong bản tin.","example":"気温が急激に下がり、雪が降り出した。","example_reading":"きおんがきゅうげきにさがり、ゆきがふりだした。","example_meaning":"Nhiệt độ giảm đột ngột và tuyết bắt đầu rơi.","examples":[{"example":"気温が急激に下がり、雪が降り出した。","example_reading":"きおんがきゅうげきにさがり、ゆきがふりだした。","example_meaning":"Nhiệt độ giảm đột ngột và tuyết bắt đầu rơi."},{"example":"人口が急激に増加している地域もある。","example_reading":"じんこうがきゅうげきにぞうかしているちいきもある。","example_meaning":"Có những khu vực dân số đang tăng đột biến."}],"level":"d1"},
{"word":"とうとう","reading":"とうとう","meaning":"rốt cuộc, cuối cùng","note":"Hay đi với ～た. Gần ついに, thường kèm cảm xúc sau thời gian dài chờ đợi hoặc kết quả không mong muốn.","example":"待っていた新製品が、とうとう発売された。","example_reading":"まっていたしんせいひんが、とうとうはつばいされた。","example_meaning":"Sản phẩm mới tôi chờ đợi cuối cùng đã được bán ra.","examples":[{"example":"待っていた新製品が、とうとう発売された。","example_reading":"まっていたしんせいひんが、とうとうはつばいされた。","example_meaning":"Sản phẩm mới tôi chờ đợi cuối cùng đã được bán ra."},{"example":"我慢できなくなって、とうとう怒り出した。","example_reading":"がまんできなくなって、とうとうおこりだした。","example_meaning":"Không chịu nổi nữa, cuối cùng anh ấy nổi giận."}],"level":"d1"},
{"word":"繰り返し","reading":"くりかえし","meaning":"lặp đi lặp lại","hanviet":"tảo phản","antonym":"一度きり（いちどきり）: chỉ một lần / 一度だけ（いちどだけ）: chỉ một lần","antonym_hanviet":"nhất độ / nhất độ","note":"Hay đi với 読む, 練習する, 言う.","example":"発音は、繰り返し練習すれば上手になる。","example_reading":"はつおんは、くりかえしれんしゅうすればじょうずになる。","example_meaning":"Phát âm chỉ cần luyện đi luyện lại là sẽ giỏi.","examples":[{"example":"発音は、繰り返し練習すれば上手になる。","example_reading":"はつおんは、くりかえしれんしゅうすればじょうずになる。","example_meaning":"Phát âm chỉ cần luyện đi luyện lại là sẽ giỏi."},{"example":"先生は同じ注意を、繰り返し伝えていた。","example_reading":"せんせいはおなじちゅういを、くりかえしつたえていた。","example_meaning":"Thầy đã nhắc đi nhắc lại cùng một điều lưu ý."}],"level":"d1"},
{"word":"個別に","reading":"こべつに","meaning":"riêng từng cái, riêng từng người","hanviet":"cá biệt","antonym":"まとめて: gộp lại / 一括して（いっかつして）: gộp một lượt / 総合的に（そうごうてきに）: tổng hợp","antonym_hanviet":" / nhất quát / tổng hợp đích","note":"Hay đi với 対応する, 連絡する, 包装する.","example":"質問がある方には、個別にお答えします。","example_reading":"しつもんがあるかたには、こべつにおこたえします。","example_meaning":"Chúng tôi sẽ trả lời riêng cho người có thắc mắc.","examples":[{"example":"質問がある方には、個別にお答えします。","example_reading":"しつもんがあるかたには、こべつにおこたえします。","example_meaning":"Chúng tôi sẽ trả lời riêng cho người có thắc mắc."},{"example":"商品は、一つずつ個別に包装されている。","example_reading":"しょうひんは、ひとつずつこべつにほうそうされている。","example_meaning":"Sản phẩm được gói riêng từng cái một."}],"level":"d1"},
{"word":"いくらか","reading":"いくらか","meaning":"một ít, phần nào","note":"Hay đi với 余る, 足りない, 良くなる.","example":"お金がいくらか余っているので、貯金するつもりだ。","example_reading":"おかねがいくらかあまっているので、ちょきんするつもりだ。","example_meaning":"Còn dư ít tiền nên tôi định đem gửi tiết kiệm.","examples":[{"example":"お金がいくらか余っているので、貯金するつもりだ。","example_reading":"おかねがいくらかあまっているので、ちょきんするつもりだ。","example_meaning":"Còn dư ít tiền nên tôi định đem gửi tiết kiệm."},{"example":"このスープは、いくらか塩気が足りない気がする。","example_reading":"このスープは、いくらかしおけがたりないきがする。","example_meaning":"Tôi thấy món súp này hơi thiếu vị mặn."}],"level":"d1"},
{"word":"うっすら","reading":"うっすら","meaning":"mờ mờ, nhàn nhạt","antonym":"はっきり: rõ ràng / くっきり: rõ nét","note":"Hay đi với と, 見える, 積もる, 浮かぶ.","example":"朝、庭にうっすらと霜が降りていた。","example_reading":"あさ、にわにうっすらとしもがおりていた。","example_meaning":"Sáng ra, sương giá phủ mỏng trong vườn.","examples":[{"example":"朝、庭にうっすらと霜が降りていた。","example_reading":"あさ、にわにうっすらとしもがおりていた。","example_meaning":"Sáng ra, sương giá phủ mỏng trong vườn."},{"example":"彼女の目には、うっすら涙が浮かんでいた。","example_reading":"かのじょのめには、うっすらなみだがうかんでいた。","example_meaning":"Đôi mắt cô ấy ngấn lệ mờ mờ."}],"level":"d1"},
{"word":"おおかた","reading":"おおかた","meaning":"phần lớn, hầu hết","antonym":"一部（いちぶ）: một phần","antonym_hanviet":"nhất bộ","note":"Hay đi với 終わる, 予想どおり. Gần だいたい.","example":"仕事は、おおかた終わったので、先に帰ります。","example_reading":"しごとは、おおかたおわったので、さきにかえります。","example_meaning":"Công việc xong hầu hết rồi nên tôi xin về trước.","examples":[{"example":"仕事は、おおかた終わったので、先に帰ります。","example_reading":"しごとは、おおかたおわったので、さきにかえります。","example_meaning":"Công việc xong hầu hết rồi nên tôi xin về trước."},{"example":"おおかた予想どおりの結果になった。","example_reading":"おおかたよそうどおりのけっかになった。","example_meaning":"Kết quả phần lớn đúng như dự đoán."}],"level":"d1"},
{"word":"おおよそ","reading":"おおよそ","meaning":"đại khái, khoảng","antonym":"正確に（せいかくに）: chính xác / 厳密に（げんみつに）: chính xác ngặt","antonym_hanviet":"chính xác / nghiêm mật","note":"Hay đi với の, 理解する, ～分. Gần およそ nhưng khẩu ngữ hơn.","example":"おおよそ三十分で着くと思います。","example_reading":"おおよそさんじゅっぷんでつくとおもいます。","example_meaning":"Tôi nghĩ khoảng ba mươi phút nữa sẽ đến.","examples":[{"example":"おおよそ三十分で着くと思います。","example_reading":"おおよそさんじゅっぷんでつくとおもいます。","example_meaning":"Tôi nghĩ khoảng ba mươi phút nữa sẽ đến."},{"example":"話の内容は、おおよそ理解できた。","example_reading":"はなしのないようは、おおよそりかいできた。","example_meaning":"Tôi đã hiểu đại khái nội dung câu chuyện."}],"level":"d1"},
{"word":"力いっぱい","reading":"ちからいっぱい","meaning":"hết sức lực","hanviet":"lực","antonym":"軽く（かるく）: nhẹ nhàng / そっと: nhẹ nhàng","antonym_hanviet":"khinh / ","note":"Hay đi với 押す, 投げる, 応援する.","example":"彼は力いっぱいドアを押したが、開かなかった。","example_reading":"かれはちからいっぱいドアをおしたが、あかなかった。","example_meaning":"Anh ấy dùng hết sức đẩy cửa nhưng không mở.","examples":[{"example":"彼は力いっぱいドアを押したが、開かなかった。","example_reading":"かれはちからいっぱいドアをおしたが、あかなかった。","example_meaning":"Anh ấy dùng hết sức đẩy cửa nhưng không mở."},{"example":"子どもたちは、力いっぱい声援を送った。","example_reading":"こどもたちは、ちからいっぱいせいえんをおくった。","example_meaning":"Bọn trẻ hết sức cổ vũ."}],"level":"d1"},
{"word":"年々","reading":"ねんねん","meaning":"năm này qua năm khác","hanviet":"niên niên","note":"Hay đi với 増える, 減る, 厳しくなる.","example":"この町の人口は、年々減っている。","example_reading":"このまちのじんこうは、ねんねんへっている。","example_meaning":"Dân số thị trấn này giảm dần theo từng năm.","examples":[{"example":"この町の人口は、年々減っている。","example_reading":"このまちのじんこうは、ねんねんへっている。","example_meaning":"Dân số thị trấn này giảm dần theo từng năm."},{"example":"年々、夏の暑さが厳しくなっているように感じる。","example_reading":"ねんねん、なつのあつさがきびしくなっているようにかんじる。","example_meaning":"Tôi cảm thấy cái nóng mùa hè năm nào cũng khắc nghiệt hơn."}],"level":"d1"},
{"word":"ちょくちょく","reading":"ちょくちょく","meaning":"thường xuyên, năng","antonym":"めったに: hiếm khi","note":"Khẩu ngữ. Làm lặp lại với khoảng cách ngắn.","example":"彼はちょくちょくこの店に来る。","example_reading":"かれはちょくちょくこのみせにくる。","example_meaning":"Anh ấy thường xuyên đến quán này.","examples":[{"example":"彼はちょくちょくこの店に来る。","example_reading":"かれはちょくちょくこのみせにくる。","example_meaning":"Anh ấy thường xuyên đến quán này."},{"example":"実家には、ちょくちょく帰るようにしている。","example_reading":"じっかには、ちょくちょくかえるようにしている。","example_meaning":"Tôi cố gắng thường xuyên về nhà bố mẹ."}],"level":"d1"},
{"word":"日ごとに","reading":"ひごとに","meaning":"mỗi ngày một, ngày càng","hanviet":"nhật","note":"Hay đi với 増える, 変わる. Gần 日増しに.","example":"日ごとに、日が短くなってきた。","example_reading":"ひごとに、ひがみじかくなってきた。","example_meaning":"Ngày càng ngắn dần theo từng ngày.","examples":[{"example":"日ごとに、日が短くなってきた。","example_reading":"ひごとに、ひがみじかくなってきた。","example_meaning":"Ngày càng ngắn dần theo từng ngày."},{"example":"彼の日本語は、日ごとに上手になっている。","example_reading":"かれのにほんごは、ひごとにじょうずになっている。","example_meaning":"Tiếng Nhật của anh ấy giỏi lên từng ngày."}],"level":"d1"},
{"word":"しばらくの間","reading":"しばらくのあいだ","meaning":"trong một thời gian","hanviet":"gian","note":"Chỉ khoảng thời gian không rõ dài ngắn, thường khá ngắn.","example":"しばらくの間、ここでお待ちください。","example_reading":"しばらくのあいだ、ここでおまちください。","example_meaning":"Xin hãy đợi ở đây một lát.","examples":[{"example":"しばらくの間、ここでお待ちください。","example_reading":"しばらくのあいだ、ここでおまちください。","example_meaning":"Xin hãy đợi ở đây một lát."},{"example":"しばらくの間、会社を休むことにした。","example_reading":"しばらくのあいだ、かいしゃをやすむことにした。","example_meaning":"Tôi quyết định nghỉ làm một thời gian."}],"level":"d1"},
{"word":"山ほど","reading":"やまほど","meaning":"chất đống, rất nhiều","hanviet":"sơn","antonym":"わずか: ít ỏi / 少し（すこし）: ít","antonym_hanviet":" / thiểu","note":"Hay đi với ある, 残っている.","example":"やるべき仕事が、山ほど残っている。","example_reading":"やるべきしごとが、やまほどのこっている。","example_meaning":"Công việc phải làm còn chất đống.","examples":[{"example":"やるべき仕事が、山ほど残っている。","example_reading":"やるべきしごとが、やまほどのこっている。","example_meaning":"Công việc phải làm còn chất đống."},{"example":"彼には、聞きたいことが山ほどある。","example_reading":"かれには、ききたいことがやまほどある。","example_meaning":"Tôi có cả núi điều muốn hỏi anh ấy."}],"level":"d1"},
{"word":"一晩中","reading":"ひとばんじゅう","meaning":"suốt đêm","hanviet":"nhất vãn trung","note":"Hay đi với 起きている, 看病する. Cả đêm không ngủ hoặc không nghỉ.","example":"子どもが熱を出して、一晩中看病した。","example_reading":"こどもがねつをだして、ひとばんじゅうかんびょうした。","example_meaning":"Con bị sốt nên tôi chăm sóc suốt đêm.","examples":[{"example":"子どもが熱を出して、一晩中看病した。","example_reading":"こどもがねつをだして、ひとばんじゅうかんびょうした。","example_meaning":"Con bị sốt nên tôi chăm sóc suốt đêm."},{"example":"一晩中雨が降り続いて、川の水かさが増した。","example_reading":"ひとばんじゅうあめがふりつづいて、かわのみずかさがました。","example_meaning":"Mưa suốt đêm làm mực nước sông dâng cao."}],"level":"d1"},
{"word":"数日前","reading":"すうじつまえ","meaning":"vài ngày trước","hanviet":"số nhật tiền","antonym":"数日後（すうじつご）: vài ngày sau","antonym_hanviet":"số nhật hậu","note":"Hay đi với から, に.","example":"数日前から、喉が痛くて咳が出る。","example_reading":"すうじつまえから、のどがいたくてせきがでる。","example_meaning":"Từ vài ngày trước, tôi bị đau họng và ho.","examples":[{"example":"数日前から、喉が痛くて咳が出る。","example_reading":"すうじつまえから、のどがいたくてせきがでる。","example_meaning":"Từ vài ngày trước, tôi bị đau họng và ho."},{"example":"数日前に、新しい店がオープンした。","example_reading":"すうじつまえに、あたらしいみせがオープンした。","example_meaning":"Vài ngày trước, một cửa hàng mới đã khai trương."}],"level":"d1"},
{"word":"数年前","reading":"すうねんまえ","meaning":"vài năm trước","hanviet":"số niên tiền","antonym":"数年後（すうねんご）: vài năm sau","antonym_hanviet":"số niên hậu","note":"Hay đi với に, と比べて.","example":"数年前に、この町に引っ越してきた。","example_reading":"すうねんまえに、このまちにひっこしてきた。","example_meaning":"Vài năm trước tôi đã chuyển đến thị trấn này.","examples":[{"example":"数年前に、この町に引っ越してきた。","example_reading":"すうねんまえに、このまちにひっこしてきた。","example_meaning":"Vài năm trước tôi đã chuyển đến thị trấn này."},{"example":"数年前と比べて、物価がかなり上がった。","example_reading":"すうねんまえとくらべて、ぶっかがかなりあがった。","example_meaning":"So với vài năm trước, giá cả đã tăng khá nhiều."}],"level":"d1"},
{"word":"直後に","reading":"ちょくごに","meaning":"ngay sau đó","hanviet":"trực hậu","antonym":"直前に（ちょくぜんに）: ngay trước đó / 寸前に（すんぜんに）: ngay trước khi","antonym_hanviet":"trực tiền / thốn tiền","note":"Hay đi với ～た直後に. Nối hai sự việc xảy ra liền nhau.","example":"地震が起きた直後に、津波警報が出された。","example_reading":"じしんがおきたちょくごに、つなみけいほうがだされた。","example_meaning":"Ngay sau khi động đất xảy ra, cảnh báo sóng thần được ban bố.","examples":[{"example":"地震が起きた直後に、津波警報が出された。","example_reading":"じしんがおきたちょくごに、つなみけいほうがだされた。","example_meaning":"Ngay sau khi động đất xảy ra, cảnh báo sóng thần được ban bố."},{"example":"彼は電話を切った直後に、部屋を出ていった。","example_reading":"かれはでんわをきったちょくごに、へやをでていった。","example_meaning":"Ngay sau khi cúp máy, anh ấy rời khỏi phòng."}],"level":"d1"},
{"word":"前から","reading":"まえから","meaning":"từ trước","hanviet":"tiền","antonym":"これから: từ nay / 今後（こんご）: từ nay về sau","antonym_hanviet":" / kim hậu","note":"Hay đi với 気になる, 知っている, ～たかった.","example":"この店は、前から一度行ってみたかった。","example_reading":"このみせは、まえからいちどいってみたかった。","example_meaning":"Quán này từ trước tôi đã muốn đến thử một lần.","examples":[{"example":"この店は、前から一度行ってみたかった。","example_reading":"このみせは、まえからいちどいってみたかった。","example_meaning":"Quán này từ trước tôi đã muốn đến thử một lần."},{"example":"彼のことは、前から知っていた。","example_reading":"かれのことは、まえからしっていた。","example_meaning":"Tôi biết anh ấy từ trước rồi."}],"level":"d1"},
{"word":"ようやく","reading":"ようやく","meaning":"cuối cùng cũng, mãi mới","antonym":"すぐに: ngay lập tức / あっさり: dễ dàng","note":"Sau thời gian dài hoặc khó khăn, việc mới thành. Mang cảm giác nhẹ nhõm.","example":"長い交渉の末、ようやく合意に達した。","example_reading":"ながいこうしょうのすえ、ようやくごういにたっした。","example_meaning":"Sau cuộc đàm phán dài, cuối cùng cũng đạt được thỏa thuận.","examples":[{"example":"長い交渉の末、ようやく合意に達した。","example_reading":"ながいこうしょうのすえ、ようやくごういにたっした。","example_meaning":"Sau cuộc đàm phán dài, cuối cùng cũng đạt được thỏa thuận."},{"example":"春になって、ようやく桜が咲き始めた。","example_reading":"はるになって、ようやくさくらがさきはじめた。","example_meaning":"Sang xuân, hoa anh đào mãi mới bắt đầu nở."}],"level":"d1"},
{"word":"久しぶりに","reading":"ひさしぶりに","meaning":"sau một thời gian dài","hanviet":"cửu","antonym":"頻繁に（ひんぱんに）: thường xuyên","antonym_hanviet":"tần phồn","note":"Đọc ひさしぶりに. Hay đi với 会う, 帰る, 食べる. Cũng dùng 久しぶり một mình khi chào hỏi.","example":"久しぶりに高校の友達と会った。","example_reading":"ひさしぶりにこうこうのともだちとあった。","example_meaning":"Lâu rồi tôi mới gặp bạn cấp ba.","examples":[{"example":"久しぶりに高校の友達と会った。","example_reading":"ひさしぶりにこうこうのともだちとあった。","example_meaning":"Lâu rồi tôi mới gặp bạn cấp ba."},{"example":"久しぶりに実家に帰って、母の料理を食べた。","example_reading":"ひさしぶりにじっかにかえって、ははのりょうりをたべた。","example_meaning":"Lâu lắm mới về quê, tôi được ăn món mẹ nấu."}],"level":"d1"},
{"word":"相変わらず","reading":"あいかわらず","meaning":"vẫn như mọi khi","hanviet":"tương biến","antonym":"すっかり変わって（すっかりかわって）: thay đổi hẳn / がらりと: thay đổi hẳn / がらり: thay đổi hẳn","antonym_hanviet":"biến /  / ","note":"Không thay đổi so với trước. Trung tính, hay dùng trong hội thoại.","example":"久しぶりに会った友人は、相変わらず元気そうだった。","example_reading":"ひさしぶりにあったゆうじんは、あいかわらずげんきそうだった。","example_meaning":"Người bạn lâu ngày gặp vẫn khỏe mạnh như mọi khi.","examples":[{"example":"久しぶりに会った友人は、相変わらず元気そうだった。","example_reading":"ひさしぶりにあったゆうじんは、あいかわらずげんきそうだった。","example_meaning":"Người bạn lâu ngày gặp vẫn khỏe mạnh như mọi khi."},{"example":"相変わらず、電車は朝から満員だ。","example_reading":"あいかわらず、でんしゃはあさからまんいんだ。","example_meaning":"Như mọi khi, tàu điện đông nghẹt từ sáng."}],"level":"d1"},
{"word":"各自","reading":"かくじ","meaning":"mỗi người, từng người","hanviet":"các tự","note":"Hay đi với で, の. Mỗi người tự lo phần của mình.","example":"昼食は、各自で用意してください。","example_reading":"ちゅうしょくは、かくじでよういしてください。","example_meaning":"Bữa trưa xin mỗi người tự chuẩn bị.","examples":[{"example":"昼食は、各自で用意してください。","example_reading":"ちゅうしょくは、かくじでよういしてください。","example_meaning":"Bữa trưa xin mỗi người tự chuẩn bị."},{"example":"各自の責任で、行動してください。","example_reading":"かくじのせきにんで、こうどうしてください。","example_meaning":"Mỗi người hãy tự chịu trách nhiệm khi hành động."}],"level":"d1"},
{"word":"単独で","reading":"たんどくで","meaning":"một mình, đơn độc","hanviet":"đơn độc","antonym":"共同で（きょうどうで）: cùng nhau / 一緒に（いっしょに）: cùng nhau / 共に（ともに）: cùng nhau","antonym_hanviet":"cộng đồng / nhất tự / cộng","note":"Hay đi với 行動する, 行う, 登る. Không có người đi cùng.","example":"彼は、単独で山に登ることにした。","example_reading":"かれは、たんどくでやまにのぼることにした。","example_meaning":"Anh ấy quyết định leo núi một mình.","examples":[{"example":"彼は、単独で山に登ることにした。","example_reading":"かれは、たんどくでやまにのぼることにした。","example_meaning":"Anh ấy quyết định leo núi một mình."},{"example":"犯人は単独で犯行に及んだとみられる。","example_reading":"はんにんはたんどくではんこうにおよんだとみられる。","example_meaning":"Thủ phạm được cho là đã gây án một mình."}],"level":"d1"},
{"word":"折々","reading":"おりおり","meaning":"thỉnh thoảng; tùy từng thời điểm","hanviet":"chiết chiết","note":"Hay đi với の, に. 季節折々 = tùy theo từng mùa.","example":"この庭では、季節折々の花が楽しめる。","example_reading":"このにわでは、きせつおりおりのはながたのしめる。","example_meaning":"Trong vườn này có thể ngắm hoa theo từng mùa.","examples":[{"example":"この庭では、季節折々の花が楽しめる。","example_reading":"このにわでは、きせつおりおりのはながたのしめる。","example_meaning":"Trong vườn này có thể ngắm hoa theo từng mùa."},{"example":"彼は折々に、故郷の母に手紙を書いている。","example_reading":"かれはおりおりに、こきょうのははにてがみをかいている。","example_meaning":"Thỉnh thoảng anh ấy lại viết thư cho mẹ ở quê."}],"level":"d1"},
{"word":"多少","reading":"たしょう","meaning":"ít nhiều, phần nào","hanviet":"đa thiểu","antonym":"大幅に（おおはばに）: đáng kể, nhiều","antonym_hanviet":"đại bức","note":"Mức độ ít hoặc \"nhiều ít gì đó\". Hay đi với ～は／～でも.","example":"日本語は多少わかりますが、上手には話せません。","example_reading":"にほんごはたしょうわかりますが、じょうずにははなせません。","example_meaning":"Tiếng Nhật tôi hiểu ít nhiều nhưng nói không giỏi.","examples":[{"example":"日本語は多少わかりますが、上手には話せません。","example_reading":"にほんごはたしょうわかりますが、じょうずにははなせません。","example_meaning":"Tiếng Nhật tôi hiểu ít nhiều nhưng nói không giỏi."},{"example":"多少高くても、品質のよいものを選びたい。","example_reading":"たしょうたかくても、ひんしつのよいものをえらびたい。","example_meaning":"Dù đắt hơn một chút, tôi vẫn muốn chọn đồ chất lượng tốt."}],"level":"d1"},
{"word":"少々","reading":"しょうしょう","meaning":"một chút, chút ít","hanviet":"thiểu thiểu","antonym":"たくさん: nhiều","note":"Trang trọng hơn ちょっと. Hay dùng khi phục vụ khách: 少々お待ちください.","example":"少々お待ちください。ただいまお調べします。","example_reading":"しょうしょうおまちください。ただいまおしらべします。","example_meaning":"Xin đợi một chút. Tôi sẽ kiểm tra ngay.","examples":[{"example":"少々お待ちください。ただいまお調べします。","example_reading":"しょうしょうおまちください。ただいまおしらべします。","example_meaning":"Xin đợi một chút. Tôi sẽ kiểm tra ngay."},{"example":"今日は少々風が強いので、お気をつけて。","example_reading":"きょうはしょうしょうかぜがつよいので、おきをつけて。","example_meaning":"Hôm nay gió hơi mạnh, xin hãy cẩn thận."}],"level":"d1"},
{"word":"急速に","reading":"きゅうそくに","meaning":"nhanh chóng (tốc độ)","hanviet":"cấp tốc","antonym":"緩やかに（ゆるやかに）: chậm rãi / 徐々に（じょじょに）: dần dần","antonym_hanviet":"hoãn / từ từ","note":"Hay đi với 進歩する, 発達する, 広まる. Nhấn mạnh tốc độ nhanh.","example":"技術は急速に進歩している。","example_reading":"ぎじゅつはきゅうそくにしんぽしている。","example_meaning":"Kỹ thuật đang tiến bộ nhanh chóng.","examples":[{"example":"技術は急速に進歩している。","example_reading":"ぎじゅつはきゅうそくにしんぽしている。","example_meaning":"Kỹ thuật đang tiến bộ nhanh chóng."},{"example":"台風は急速に発達しながら、日本に近づいている。","example_reading":"たいふうはきゅうそくにはったつしながら、にほんにちかづいている。","example_meaning":"Bão đang mạnh lên nhanh chóng và tiến gần Nhật Bản."}],"level":"d1"},
{"word":"続けて","reading":"つづけて","meaning":"liên tục, liền nhau","hanviet":"tục","antonym":"途切れ途切れに（とぎれとぎれに）: đứt quãng / 断続的に（だんぞくてきに）: gián đoạn / 交互に（こうごに）: luân phiên","antonym_hanviet":"đồ thiết đồ thiết / đoạn tục đích / giao hỗ","note":"Hay đi với 三回, 二日. Làm lặp lại ngay sau nhau.","example":"彼は三年続けて、同じ大会で優勝した。","example_reading":"かれはさんねんつづけて、おなじたいかいでゆうしょうした。","example_meaning":"Anh ấy vô địch cùng một giải ba năm liên tiếp.","examples":[{"example":"彼は三年続けて、同じ大会で優勝した。","example_reading":"かれはさんねんつづけて、おなじたいかいでゆうしょうした。","example_meaning":"Anh ấy vô địch cùng một giải ba năm liên tiếp."},{"example":"続けて二本映画を見たので、目が疲れた。","example_reading":"つづけてにほんえいがをみたので、めがつかれた。","example_meaning":"Xem liền hai bộ phim nên mắt tôi mỏi."}],"level":"d1"},
{"word":"余計に","reading":"よけいに","meaning":"thừa, càng thêm","hanviet":"dư kế","note":"Hay đi với かかる, 心配する, 言う. Nhiều hơn mức cần thiết hoặc dự kiến.","example":"急ぎの配送は、余計に料金がかかる。","example_reading":"いそぎのはいそうは、よけいにりょうきんがかかる。","example_meaning":"Giao hàng gấp thì phải trả thêm phí.","examples":[{"example":"急ぎの配送は、余計に料金がかかる。","example_reading":"いそぎのはいそうは、よけいにりょうきんがかかる。","example_meaning":"Giao hàng gấp thì phải trả thêm phí."},{"example":"母に黙っていたので、余計に心配をかけてしまった。","example_reading":"ははにだまっていたので、よけいにしんぱいをかけてしまった。","example_meaning":"Vì giấu mẹ nên tôi càng làm mẹ lo thêm."}],"level":"d1"},
{"word":"日増しに","reading":"ひましに","meaning":"ngày càng, mỗi ngày một","hanviet":"nhật tăng","note":"Hay đi với 増える, 寒くなる, 強まる.","example":"日増しに寒さが厳しくなってきた。","example_reading":"ひましにさむさがきびしくなってきた。","example_meaning":"Cái lạnh ngày càng khắc nghiệt.","examples":[{"example":"日増しに寒さが厳しくなってきた。","example_reading":"ひましにさむさがきびしくなってきた。","example_meaning":"Cái lạnh ngày càng khắc nghiệt."},{"example":"子どもは日増しに大きくなっていく。","example_reading":"こどもはひましにおおきくなっていく。","example_meaning":"Đứa trẻ lớn lên từng ngày."}],"level":"d1"},
{"word":"以来","reading":"いらい","meaning":"kể từ khi","hanviet":"dĩ lai","note":"Hay đi với ～て以来. Cũng dùng それ以来 = từ đó đến nay.","example":"去年、彼と会って以来、一度も連絡を取っていない。","example_reading":"きょねん、かれとあっていらい、いちどもれんらくをとっていない。","example_meaning":"Từ lần gặp anh ấy năm ngoái, tôi chưa liên lạc lần nào.","examples":[{"example":"去年、彼と会って以来、一度も連絡を取っていない。","example_reading":"きょねん、かれとあっていらい、いちどもれんらくをとっていない。","example_meaning":"Từ lần gặp anh ấy năm ngoái, tôi chưa liên lạc lần nào."},{"example":"日本に来て以来、毎朝納豆を食べている。","example_reading":"にほんにきていらい、まいあさなっとうをたべている。","example_meaning":"Từ khi đến Nhật, sáng nào tôi cũng ăn natto."}],"level":"d1"},
{"word":"近日中に","reading":"きんじつちゅうに","meaning":"trong vài ngày tới","hanviet":"cận nhật trung","note":"Trang trọng. Gần 近いうちに nhưng gần hơn.","example":"新しい商品は、近日中に発売される予定です。","example_reading":"あたらしいしょうひんは、きんじつちゅうにはつばいされるよていです。","example_meaning":"Sản phẩm mới dự kiến sẽ ra mắt trong vài ngày tới.","examples":[{"example":"新しい商品は、近日中に発売される予定です。","example_reading":"あたらしいしょうひんは、きんじつちゅうにはつばいされるよていです。","example_meaning":"Sản phẩm mới dự kiến sẽ ra mắt trong vài ngày tới."},{"example":"詳細は、近日中にご連絡いたします。","example_reading":"しょうさいは、きんじつちゅうにごれんらくいたします。","example_meaning":"Chi tiết chúng tôi sẽ liên lạc trong vài ngày tới."}],"level":"d1"},
{"word":"近いうちに","reading":"ちかいうちに","meaning":"trong nay mai, sớm thôi","hanviet":"cận","note":"Hay đi với 会う, 連絡する. Thời điểm gần nhưng chưa xác định.","example":"近いうちに、ぜひ食事に行きましょう。","example_reading":"ちかいうちに、ぜひしょくじにいきましょう。","example_meaning":"Nay mai nhất định mình đi ăn nhé.","examples":[{"example":"近いうちに、ぜひ食事に行きましょう。","example_reading":"ちかいうちに、ぜひしょくじにいきましょう。","example_meaning":"Nay mai nhất định mình đi ăn nhé."},{"example":"近いうちに結果をお知らせします。","example_reading":"ちかいうちにけっかをおしらせします。","example_meaning":"Chúng tôi sẽ sớm báo kết quả cho bạn."}],"level":"d1"},
{"word":"後日","reading":"ごじつ","meaning":"sau này, ngày khác","hanviet":"hậu nhật","antonym":"当日（とうじつ）: đúng ngày / 過日（かじつ）: hôm trước","antonym_hanviet":"đương nhật / quá nhật","note":"Hay đi với 後日改めて. Trang trọng.","example":"詳しいことは、後日改めてご連絡します。","example_reading":"くわしいことは、ごじつあらためてごれんらくします。","example_meaning":"Chi tiết tôi sẽ liên lạc lại vào ngày khác.","examples":[{"example":"詳しいことは、後日改めてご連絡します。","example_reading":"くわしいことは、ごじつあらためてごれんらくします。","example_meaning":"Chi tiết tôi sẽ liên lạc lại vào ngày khác."},{"example":"結果は後日、郵送でお知らせします。","example_reading":"けっかはごじつ、ゆうそうでおしらせします。","example_meaning":"Kết quả sẽ được báo qua đường bưu điện sau này."}],"level":"d1"},
{"word":"翌朝","reading":"よくあさ","meaning":"sáng hôm sau","hanviet":"dực triêu","note":"Sáng ngày liền sau.","example":"雪は降り続き、翌朝には一面の銀世界になっていた。","example_reading":"ゆきはふりつづき、よくあさにはいちめんのぎんせかいになっていた。","example_meaning":"Tuyết rơi mãi, sáng hôm sau đã thành một vùng trắng xóa.","examples":[{"example":"雪は降り続き、翌朝には一面の銀世界になっていた。","example_reading":"ゆきはふりつづき、よくあさにはいちめんのぎんせかいになっていた。","example_meaning":"Tuyết rơi mãi, sáng hôm sau đã thành một vùng trắng xóa."},{"example":"翌朝、早く起きて出発した。","example_reading":"よくあさ、はやくおきてしゅっぱつした。","example_meaning":"Sáng hôm sau tôi dậy sớm rồi lên đường."}],"level":"d1"},
{"word":"月々","reading":"つきづき","meaning":"mỗi tháng","hanviet":"nguyệt nguyệt","note":"Hay đi với の支払い, の収入.","example":"月々の支払いが、家計を圧迫している。","example_reading":"つきづきのしはらいが、かけいをあっぱくしている。","example_meaning":"Khoản thanh toán hằng tháng đang đè nặng lên chi tiêu gia đình.","examples":[{"example":"月々の支払いが、家計を圧迫している。","example_reading":"つきづきのしはらいが、かけいをあっぱくしている。","example_meaning":"Khoản thanh toán hằng tháng đang đè nặng lên chi tiêu gia đình."},{"example":"月々、少しずつ貯金している。","example_reading":"つきづき、すこしずつちょきんしている。","example_meaning":"Tháng nào tôi cũng tiết kiệm một ít."}],"level":"d1"},
{"word":"ちょっぴり","reading":"ちょっぴり","meaning":"một chút xíu","antonym":"たっぷり: đầy đặn / たくさん: nhiều","note":"Khẩu ngữ, dễ thương. Gần 少し.","example":"入れすぎたので、ちょっぴり塩辛くなってしまった。","example_reading":"いれすぎたので、ちょっぴりしおからくなってしまった。","example_meaning":"Cho hơi nhiều nên bị mặn một chút xíu.","examples":[{"example":"入れすぎたので、ちょっぴり塩辛くなってしまった。","example_reading":"いれすぎたので、ちょっぴりしおからくなってしまった。","example_meaning":"Cho hơi nhiều nên bị mặn một chút xíu."},{"example":"先生に褒められて、ちょっぴり嬉しかった。","example_reading":"せんせいにほめられて、ちょっぴりうれしかった。","example_meaning":"Được cô khen, tôi thấy vui một chút."}],"level":"d1"},
{"word":"大いに","reading":"おおいに","meaning":"rất, nhiều, hết mình","hanviet":"đại","antonym":"少し（すこし）: một ít / 少しも（すこしも）: một chút cũng không / やや: hơi","antonym_hanviet":"thiểu / thiểu / ","note":"Nhấn mạnh mức độ, thường là tích cực. Hay đi với 期待する, 楽しむ, 助かる, 驚く.","example":"今夜は大いに飲んで、大いに語りましょう。","example_reading":"こんやはおおいにのんで、おおいにかたりましょう。","example_meaning":"Tối nay chúng ta hãy uống thật thoải mái và trò chuyện thật nhiều nhé.","examples":[{"example":"今夜は大いに飲んで、大いに語りましょう。","example_reading":"こんやはおおいにのんで、おおいにかたりましょう。","example_meaning":"Tối nay chúng ta hãy uống thật thoải mái và trò chuyện thật nhiều nhé."},{"example":"この研究には、大いに期待しています。","example_reading":"このけんきゅうには、おおいにきたいしています。","example_meaning":"Tôi rất kỳ vọng vào nghiên cứu này."}],"level":"d1"},
{"word":"至る所に","reading":"いたるところに","meaning":"khắp mọi nơi","hanviet":"chí sở","note":"Hay đi với ある, 咲く, 見られる.","example":"春になると、街の至る所に桜が咲く。","example_reading":"はるになると、まちのいたるところにさくらがさく。","example_meaning":"Xuân đến, hoa anh đào nở khắp nơi trong phố.","examples":[{"example":"春になると、街の至る所に桜が咲く。","example_reading":"はるになると、まちのいたるところにさくらがさく。","example_meaning":"Xuân đến, hoa anh đào nở khắp nơi trong phố."},{"example":"部屋の至る所に、子どものおもちゃが散らかっている。","example_reading":"へやのいたるところに、こどものおもちゃがちらかっている。","example_meaning":"Đồ chơi của con vương vãi khắp phòng."}],"level":"d1"},
{"word":"未明に","reading":"みめいに","meaning":"rạng sáng, mờ sáng","hanviet":"vị minh","note":"Khoảng thời gian rất sớm khi trời còn tối, thường gặp trong bản tin.","example":"事故は、今日の未明に起きた。","example_reading":"じこは、きょうのみめいにおきた。","example_meaning":"Vụ tai nạn xảy ra vào rạng sáng hôm nay.","examples":[{"example":"事故は、今日の未明に起きた。","example_reading":"じこは、きょうのみめいにおきた。","example_meaning":"Vụ tai nạn xảy ra vào rạng sáng hôm nay."},{"example":"地震は、午前三時、まだ暗い未明に発生した。","example_reading":"じしんは、ごぜんさんじ、まだくらいみめいにはっせいした。","example_meaning":"Động đất xảy ra lúc rạng sáng, ba giờ khi trời còn tối."}],"level":"d1"},
{"word":"続けざまに","reading":"つづけざまに","meaning":"liên tục, nối tiếp","hanviet":"tục","note":"Hay đi với 起きる, 飲む, 打つ.","example":"彼は続けざまに三杯もお茶を飲んだ。","example_reading":"かれはつづけざまにさんばいもおちゃをのんだ。","example_meaning":"Anh ấy uống liên tục ba tách trà.","examples":[{"example":"彼は続けざまに三杯もお茶を飲んだ。","example_reading":"かれはつづけざまにさんばいもおちゃをのんだ。","example_meaning":"Anh ấy uống liên tục ba tách trà."},{"example":"続けざまに事故が起きて、道が大渋滞になった。","example_reading":"つづけざまにじこがおきて、みちがだいじゅうたいになった。","example_meaning":"Tai nạn xảy ra liên tiếp nên đường tắc nghẽn nặng."}],"level":"d1"},
{"word":"現時点で","reading":"げんじてんで","meaning":"tính đến thời điểm hiện tại","hanviet":"hiện thời điểm","note":"Hay đi với は, ～ない. Trang trọng.","example":"現時点で、新しい情報は入っていません。","example_reading":"げんじてんで、あたらしいじょうほうははいっていません。","example_meaning":"Tính đến thời điểm hiện tại chưa có thông tin mới.","examples":[{"example":"現時点で、新しい情報は入っていません。","example_reading":"げんじてんで、あたらしいじょうほうははいっていません。","example_meaning":"Tính đến thời điểm hiện tại chưa có thông tin mới."},{"example":"現時点では、原因はまだ特定されていない。","example_reading":"げんじてんでは、げんいんはまだとくていされていない。","example_meaning":"Hiện tại nguyên nhân vẫn chưa được xác định."}],"level":"d1"},
{"word":"幾分","reading":"いくぶん","meaning":"phần nào, một chút","hanviet":"kỷ phân","antonym":"大いに（おおいに）: rất nhiều / 非常に（ひじょうに）: cực kỳ","antonym_hanviet":"đại / phi thường","note":"Hay đi với 和らぐ, 軽くなる, か. Văn viết.","example":"昨日より、幾分寒さが和らいだようだ。","example_reading":"きのうより、いくぶんさむさがやわらいだようだ。","example_meaning":"So với hôm qua, cái lạnh có vẻ dịu đi phần nào.","examples":[{"example":"昨日より、幾分寒さが和らいだようだ。","example_reading":"きのうより、いくぶんさむさがやわらいだようだ。","example_meaning":"So với hôm qua, cái lạnh có vẻ dịu đi phần nào."},{"example":"薬を飲んだら、痛みが幾分軽くなった。","example_reading":"くすりをのんだら、いたみがいくぶんかるくなった。","example_meaning":"Uống thuốc xong cơn đau đã nhẹ đi phần nào."}],"level":"d1"},
{"word":"心持ち","reading":"こころもち","meaning":"hơi hơi, nhỉnh chút","hanviet":"tâm trì","antonym":"大幅に（おおはばに）: đáng kể","antonym_hanviet":"đại bức","note":"Hay đi với 大きく, 長く, 傾ける. Rất ít, vừa đủ nhận ra.","example":"心持ち、声を大きくして話してください。","example_reading":"こころもち、こえをおおきくしてはなしてください。","example_meaning":"Xin hãy nói to hơn một chút.","examples":[{"example":"心持ち、声を大きくして話してください。","example_reading":"こころもち、こえをおおきくしてはなしてください。","example_meaning":"Xin hãy nói to hơn một chút."},{"example":"彼は心持ち背を丸めて、歩いていた。","example_reading":"かれはこころもちせをまるめて、あるいていた。","example_meaning":"Anh ấy đi hơi khom lưng."}],"level":"d1"},
{"word":"極力","reading":"きょくりょく","meaning":"hết sức có thể, tối đa","hanviet":"cực lực","note":"Hay đi với 避ける, 減らす, 努力する.","example":"無駄な出費は、極力減らすようにしている。","example_reading":"むだなしゅっぴは、きょくりょくへらすようにしている。","example_meaning":"Tôi cố gắng hết sức cắt giảm chi tiêu lãng phí.","examples":[{"example":"無駄な出費は、極力減らすようにしている。","example_reading":"むだなしゅっぴは、きょくりょくへらすようにしている。","example_meaning":"Tôi cố gắng hết sức cắt giảm chi tiêu lãng phí."},{"example":"事故を防ぐために、極力慎重に作業を進めた。","example_reading":"じこをふせぐために、きょくりょくしんちょうにさぎょうをすすめた。","example_meaning":"Để ngăn tai nạn, tôi làm việc thận trọng hết mức."}],"level":"d1"},
{"word":"めいっぱい","reading":"めいっぱい","meaning":"hết mức, tối đa","antonym":"控えめに（ひかえめに）: vừa phải / ほどほどに: vừa phải","antonym_hanviet":"khống / ","note":"Hay đi với 遊ぶ, 詰まる, 使う. Khẩu ngữ. Dùng đến giới hạn.","example":"夏休みは、めいっぱい遊ぶつもりだ。","example_reading":"なつやすみは、めいっぱいあそぶつもりだ。","example_meaning":"Kỳ nghỉ hè tôi định chơi hết mức.","examples":[{"example":"夏休みは、めいっぱい遊ぶつもりだ。","example_reading":"なつやすみは、めいっぱいあそぶつもりだ。","example_meaning":"Kỳ nghỉ hè tôi định chơi hết mức."},{"example":"スケジュールがめいっぱい詰まっていて、休む暇がない。","example_reading":"スケジュールがめいっぱいつまっていて、やすむひまがない。","example_meaning":"Lịch trình kín mít nên chẳng có thời gian nghỉ."}],"level":"d1"},
{"word":"あまりにも","reading":"あまりにも","meaning":"quá (mức), quá đáng","note":"Mức độ vượt giới hạn, thường kèm sắc thái tiêu cực. Hay đi với ～すぎる／～ので.","example":"あまりにも急な話で、すぐには返事ができなかった。","example_reading":"あまりにもきゅうなはなしで、すぐにはへんじができなかった。","example_meaning":"Chuyện quá đột ngột nên tôi không trả lời ngay được.","examples":[{"example":"あまりにも急な話で、すぐには返事ができなかった。","example_reading":"あまりにもきゅうなはなしで、すぐにはへんじができなかった。","example_meaning":"Chuyện quá đột ngột nên tôi không trả lời ngay được."},{"example":"あまりにも疲れていたので、服のまま寝てしまった。","example_reading":"あまりにもつかれていたので、ふくのままねてしまった。","example_meaning":"Mệt quá nên tôi cứ thế mặc nguyên quần áo mà ngủ."}],"level":"d1"},
{"word":"ひどく","reading":"ひどく","meaning":"nặng, dữ dội, quá","note":"Mức độ cực đoan, thường mang nghĩa xấu. Hay đi với 疲れる, 痛む, 驚く, 落ち込む.","example":"昨日から頭がひどく痛む。","example_reading":"きのうからあたまがひどくいたむ。","example_meaning":"Từ hôm qua đầu tôi đau dữ dội.","examples":[{"example":"昨日から頭がひどく痛む。","example_reading":"きのうからあたまがひどくいたむ。","example_meaning":"Từ hôm qua đầu tôi đau dữ dội."},{"example":"彼は試験に落ちて、ひどく落ち込んでいる。","example_reading":"かれはしけんにおちて、ひどくおちこんでいる。","example_meaning":"Anh ấy trượt kỳ thi nên rất chán nản."}],"level":"d1"},
{"word":"同時に","reading":"どうじに","meaning":"đồng thời, cùng lúc","hanviet":"đồng thời","note":"Đọc どうじに. Hay đi với ～と同時に. Hai việc xảy ra cùng lúc hoặc song song.","antonym":"別々に（べつべつに）: riêng rẽ / 順番に（じゅんばんに）: lần lượt / 順々に（じゅんじゅんに）: lần lượt","antonym_hanviet":"biệt biệt / thuận phiên / thuận thuận","example":"ドアが開くと同時に、犬が飛び出してきた。","example_reading":"ドアがあくとどうじに、いぬがとびだしてきた。","example_meaning":"Cửa vừa mở, con chó lao ra ngay.","examples":[{"example":"ドアが開くと同時に、犬が飛び出してきた。","example_reading":"ドアがあくとどうじに、いぬがとびだしてきた。","example_meaning":"Cửa vừa mở, con chó lao ra ngay."},{"example":"二つのことを同時にするのは難しい。","example_reading":"ふたつのことをどうじにするのはむずかしい。","example_meaning":"Làm hai việc cùng lúc thì khó."}],"level":"d1"},
{"word":"一度に","reading":"いちどに","meaning":"một lần, cùng một lúc","hanviet":"nhất độ","antonym":"少しずつ（すこしずつ）: từng chút một / 一つ一つ（ひとつひとつ）: từng cái một","antonym_hanviet":"thiểu / nhất nhất","note":"Đọc いちどに. Hay đi với 運ぶ, 注文する, 利用する. Làm nhiều thứ trong một lần.","example":"荷物が多くて、一度に運べない。","example_reading":"にもつがおおくて、いちどにはこべない。","example_meaning":"Hành lý nhiều nên không mang hết trong một lần được.","examples":[{"example":"荷物が多くて、一度に運べない。","example_reading":"にもつがおおくて、いちどにはこべない。","example_meaning":"Hành lý nhiều nên không mang hết trong một lần được."},{"example":"これは一度に三人まで利用できます。","example_reading":"これはいちどにさんにんまでりようできます。","example_meaning":"Cái này mỗi lần chỉ tối đa ba người dùng."}],"level":"d1"},
{"word":"今後","reading":"こんご","meaning":"từ nay về sau","hanviet":"kim hậu","antonym":"以前（いぜん）: trước đây / かつて: từng / これまで: từ trước đến nay","antonym_hanviet":"dĩ tiền /  / ","note":"Đọc こんご. Hay đi với ～も／～は. Cũng là danh từ; dùng nhiều trong công việc.","example":"今後も、よろしくお願いします。","example_reading":"こんごも、よろしくおねがいします。","example_meaning":"Từ nay mong tiếp tục được giúp đỡ.","examples":[{"example":"今後も、よろしくお願いします。","example_reading":"こんごも、よろしくおねがいします。","example_meaning":"Từ nay mong tiếp tục được giúp đỡ."},{"example":"今後は、遅刻しないように気をつけます。","example_reading":"こんごは、ちこくしないようにきをつけます。","example_meaning":"Từ nay tôi sẽ chú ý không đi trễ."}],"level":"d1"},
{"word":"ある程度","reading":"あるていど","meaning":"ở mức độ nào đó","hanviet":"trình độ","note":"Hay đi với ～できる, 理解する, 終わる.","example":"ある程度の貯金がないと、不安だ。","example_reading":"あるていどのちょきんがないと、ふあんだ。","example_meaning":"Không có một khoản tiết kiệm nhất định thì thấy bất an.","examples":[{"example":"ある程度の貯金がないと、不安だ。","example_reading":"あるていどのちょきんがないと、ふあんだ。","example_meaning":"Không có một khoản tiết kiệm nhất định thì thấy bất an."},{"example":"準備はある程度終わったので、あとは本番を待つだけだ。","example_reading":"じゅんびはあるていどおわったので、あとはほんばんをまつだけだ。","example_meaning":"Chuẩn bị đã xong ở mức nào đó, giờ chỉ còn đợi buổi chính thức."}],"level":"d1"},
{"word":"昨今","reading":"さっこん","meaning":"dạo gần đây, thời nay","hanviet":"tạc kim","note":"Văn viết, nói về xu hướng xã hội gần đây.","example":"昨今、環境問題への関心が高まっている。","example_reading":"さっこん、かんきょうもんだいへのかんしんがたかまっている。","example_meaning":"Dạo gần đây sự quan tâm đến vấn đề môi trường đang tăng lên.","examples":[{"example":"昨今、環境問題への関心が高まっている。","example_reading":"さっこん、かんきょうもんだいへのかんしんがたかまっている。","example_meaning":"Dạo gần đây sự quan tâm đến vấn đề môi trường đang tăng lên."},{"example":"昨今の物価高で、家計が苦しい家庭も多い。","example_reading":"さっこんのぶっかだかで、かけいがくるしいかていもおおい。","example_meaning":"Do giá cả leo thang gần đây, nhiều gia đình thấy chật vật."}],"level":"d1"},
{"word":"瞬く間に","reading":"またたくまに","meaning":"trong nháy mắt","hanviet":"thuấn gian","antonym":"ゆっくり: chậm rãi / 長い間（ながいあいだ）: lâu","antonym_hanviet":" / trưởng gian","note":"Hay đi với 広まる, 売り切れる, 過ぎる.","example":"そのうわさは瞬く間に町中に広まった。","example_reading":"そのうわさはまたたくまにまちじゅうにひろまった。","example_meaning":"Tin đồn đó lan khắp thị trấn trong nháy mắt.","examples":[{"example":"そのうわさは瞬く間に町中に広まった。","example_reading":"そのうわさはまたたくまにまちじゅうにひろまった。","example_meaning":"Tin đồn đó lan khắp thị trấn trong nháy mắt."},{"example":"人気の商品は、瞬く間に売り切れてしまった。","example_reading":"にんきのしょうひんは、またたくまにうりきれてしまった。","example_meaning":"Sản phẩm hot đã bán hết sạch trong chớp mắt."}],"level":"d1"},
{"word":"誠に","reading":"まことに","meaning":"thật sự (lịch sự)","hanviet":"thành","note":"Dùng trong lời xin lỗi, cảm ơn trang trọng.","example":"ご迷惑をおかけして、誠に申し訳ございません。","example_reading":"ごめいわくをおかけして、まことにもうしわけございません。","example_meaning":"Thành thật xin lỗi vì đã gây phiền phức.","examples":[{"example":"ご迷惑をおかけして、誠に申し訳ございません。","example_reading":"ごめいわくをおかけして、まことにもうしわけございません。","example_meaning":"Thành thật xin lỗi vì đã gây phiền phức."},{"example":"本日は、誠にありがとうございました。","example_reading":"ほんじつは、まことにありがとうございました。","example_meaning":"Hôm nay thực sự xin cảm ơn quý vị."}],"level":"d1"},
{"word":"今しがた","reading":"いましがた","meaning":"vừa mới, ngay lúc nãy","hanviet":"kim","antonym":"後ほど（のちほど）: lát nữa","antonym_hanviet":"hậu","note":"Trang trọng hơn たった今.","example":"田中さんは、今しがた出かけたところです。","example_reading":"たなかさんは、いましがたでかけたところです。","example_meaning":"Anh Tanaka vừa mới ra ngoài.","examples":[{"example":"田中さんは、今しがた出かけたところです。","example_reading":"たなかさんは、いましがたでかけたところです。","example_meaning":"Anh Tanaka vừa mới ra ngoài."},{"example":"今しがた、荷物が届いた。","example_reading":"いましがた、にもつがとどいた。","example_meaning":"Hành lý vừa mới được giao tới."}],"level":"d1"},
{"word":"数々","reading":"かずかず","meaning":"nhiều, vô số","hanviet":"số số","note":"Hay đi với の. Nhiều loại cùng lúc.","example":"彼は数々の賞を受賞している。","example_reading":"かれはかずかずのしょうをじゅしょうしている。","example_meaning":"Anh ấy đã nhận vô số giải thưởng.","examples":[{"example":"彼は数々の賞を受賞している。","example_reading":"かれはかずかずのしょうをじゅしょうしている。","example_meaning":"Anh ấy đã nhận vô số giải thưởng."},{"example":"数々の困難を乗り越えて、夢を実現した。","example_reading":"かずかずのこんなんをのりこえて、ゆめをじつげんした。","example_meaning":"Vượt qua bao nhiêu khó khăn, anh ấy đã thực hiện được ước mơ."}],"level":"d1"},
{"word":"数多く","reading":"かずおおく","meaning":"nhiều","hanviet":"số đa","note":"Hay đi với の. Văn viết.","example":"この作家は、数多くの小説を書いている。","example_reading":"このさっかは、かずおおくのしょうせつをかいている。","example_meaning":"Nhà văn này đã viết rất nhiều tiểu thuyết.","examples":[{"example":"この作家は、数多くの小説を書いている。","example_reading":"このさっかは、かずおおくのしょうせつをかいている。","example_meaning":"Nhà văn này đã viết rất nhiều tiểu thuyết."},{"example":"数多くの人が、その事件に関心を寄せている。","example_reading":"かずおおくのひとが、そのじけんにかんしんをよせている。","example_meaning":"Rất nhiều người quan tâm đến vụ việc đó."}],"level":"d1"},
{"word":"早朝","reading":"そうちょう","meaning":"sáng sớm","hanviet":"tảo triêu","antonym":"深夜（しんや）: đêm khuya / 夕方（ゆうがた）: chiều tối","antonym_hanviet":"thâm dạ / tịch phương","note":"Giờ rất sớm trong ngày.","example":"早朝のジョギングは、とても気持ちがいい。","example_reading":"そうちょうのジョギングは、とてもきもちがいい。","example_meaning":"Chạy bộ buổi sáng sớm rất sảng khoái.","examples":[{"example":"早朝のジョギングは、とても気持ちがいい。","example_reading":"そうちょうのジョギングは、とてもきもちがいい。","example_meaning":"Chạy bộ buổi sáng sớm rất sảng khoái."},{"example":"飛行機は、早朝に空港へ到着した。","example_reading":"ひこうきは、そうちょうにくうこうへとうちゃくした。","example_meaning":"Máy bay đã đến sân bay vào sáng sớm."}],"level":"d1"},
{"word":"まずまず","reading":"まずまず","meaning":"tạm được, khá ổn","note":"Đánh giá khá tốt nhưng không xuất sắc.","example":"初めての料理にしては、まずまずの出来だ。","example_reading":"はじめてのりょうりにしては、まずまずのできだ。","example_meaning":"Với món nấu lần đầu thì cũng tạm được.","examples":[{"example":"初めての料理にしては、まずまずの出来だ。","example_reading":"はじめてのりょうりにしては、まずまずのできだ。","example_meaning":"Với món nấu lần đầu thì cũng tạm được."},{"example":"今年の売り上げは、まずまずだった。","example_reading":"ことしのうりあげは、まずまずだった。","example_meaning":"Doanh thu năm nay cũng khá ổn."}],"level":"d1"},
{"word":"間際に","reading":"まぎわに","meaning":"ngay trước lúc","hanviet":"gian tế","note":"Hay đi với の. Thời điểm sát ngay trước một sự việc.","example":"出発の間際に、忘れ物に気づいて引き返した。","example_reading":"しゅっぱつのまぎわに、わすれものにきづいてひきかえした。","example_meaning":"Ngay trước lúc khởi hành, tôi nhận ra quên đồ nên quay lại.","examples":[{"example":"出発の間際に、忘れ物に気づいて引き返した。","example_reading":"しゅっぱつのまぎわに、わすれものにきづいてひきかえした。","example_meaning":"Ngay trước lúc khởi hành, tôi nhận ra quên đồ nên quay lại."},{"example":"閉店間際に、駆け込みで客が入ってきた。","example_reading":"へいてんまぎわに、かけこみできゃくがはいってきた。","example_meaning":"Sát giờ đóng cửa, có khách chạy vội vào."}],"level":"d1"},
{"word":"終盤","reading":"しゅうばん","meaning":"giai đoạn cuối","hanviet":"chung bàn","antonym":"序盤（じょばん）: giai đoạn đầu","antonym_hanviet":"tự bàn","note":"Dùng cho trận đấu, câu chuyện, cuộc thi.","example":"マラソンの終盤で、彼は一気にスピードを上げた。","example_reading":"マラソンのしゅうばんで、かれはいっきにスピードをあげた。","example_meaning":"Ở chặng cuối cuộc marathon, anh ấy bất ngờ tăng tốc.","examples":[{"example":"マラソンの終盤で、彼は一気にスピードを上げた。","example_reading":"マラソンのしゅうばんで、かれはいっきにスピードをあげた。","example_meaning":"Ở chặng cuối cuộc marathon, anh ấy bất ngờ tăng tốc."},{"example":"物語は終盤に入り、真実が少しずつ明らかになる。","example_reading":"ものがたりはしゅうばんにはいり、しんじつがすこしずつあきらかになる。","example_meaning":"Câu chuyện bước vào hồi cuối, sự thật dần dần sáng tỏ."}],"level":"d1"},
{"word":"現状では","reading":"げんじょうでは","meaning":"với tình hình hiện nay","hanviet":"hiện trạng","note":"Hay đi với ～ない, 難しい. Dựa trên tình hình hiện tại.","example":"現状では、計画の変更は難しい。","example_reading":"げんじょうでは、けいかくのへんこうはむずかしい。","example_meaning":"Với tình hình hiện nay, việc thay đổi kế hoạch là khó.","examples":[{"example":"現状では、計画の変更は難しい。","example_reading":"げんじょうでは、けいかくのへんこうはむずかしい。","example_meaning":"Với tình hình hiện nay, việc thay đổi kế hoạch là khó."},{"example":"現状では、人手が足りず、新しい仕事は引き受けられない。","example_reading":"げんじょうでは、ひとでがたりず、あたらしいしごとはひきうけられない。","example_meaning":"Với tình hình hiện nay thiếu người nên không nhận thêm việc mới được."}],"level":"d1"},
{"word":"薄々","reading":"うすうす","meaning":"lờ mờ, phần nào đoán biết","hanviet":"bạc bạc","antonym":"はっきり: rõ ràng","note":"Hay đi với 気づく, 感じる, 知っている.","example":"彼が嘘をついていることは、薄々気づいていた。","example_reading":"かれがうそをついていることは、うすうすきづいていた。","example_meaning":"Tôi lờ mờ nhận ra anh ta đang nói dối.","examples":[{"example":"彼が嘘をついていることは、薄々気づいていた。","example_reading":"かれがうそをついていることは、うすうすきづいていた。","example_meaning":"Tôi lờ mờ nhận ra anh ta đang nói dối."},{"example":"薄々感じてはいたが、はっきり言われるとショックだ。","example_reading":"うすうすかんじてはいたが、はっきりいわれるとショックだ。","example_meaning":"Tôi đã lờ mờ cảm thấy nhưng nghe nói rõ ra thì vẫn sốc."}],"level":"d1"},
{"word":"ほのかに","reading":"ほのかに","meaning":"thoang thoảng, mờ mờ","antonym":"はっきり: rõ ràng","note":"Hay đi với 明るい, 香る, 見える. Rất nhẹ, khó nhận ra.","example":"東の空が、ほのかに明るくなってきた。","example_reading":"ひがしのそらが、ほのかにあかるくなってきた。","example_meaning":"Bầu trời phía đông bắt đầu sáng mờ mờ.","examples":[{"example":"東の空が、ほのかに明るくなってきた。","example_reading":"ひがしのそらが、ほのかにあかるくなってきた。","example_meaning":"Bầu trời phía đông bắt đầu sáng mờ mờ."},{"example":"暗闇の中に、ほのかに人影が見えた。","example_reading":"くらやみのなかに、ほのかにひとかげがみえた。","example_meaning":"Trong bóng tối, thoáng thấy bóng người mờ mờ."}],"level":"d1"},
{"word":"昔から","reading":"むかしから","meaning":"từ xưa","hanviet":"tích","antonym":"最近（さいきん）: dạo gần đây / 今から（いまから）: từ bây giờ","antonym_hanviet":"tối cận / kim","note":"Hay đi với 言われている, 好き, 苦手.","example":"この町は、昔から米作りで知られている。","example_reading":"このまちは、むかしからこめづくりでしられている。","example_meaning":"Thị trấn này từ xưa đã nổi tiếng về trồng lúa.","examples":[{"example":"この町は、昔から米作りで知られている。","example_reading":"このまちは、むかしからこめづくりでしられている。","example_meaning":"Thị trấn này từ xưa đã nổi tiếng về trồng lúa."},{"example":"私は昔から、人前で話すのが苦手だ。","example_reading":"わたしはむかしから、ひとまえではなすのがにがてだ。","example_meaning":"Từ xưa đến giờ tôi vẫn ngại nói trước đám đông."}],"level":"d1"},
{"word":"一々","reading":"いちいち","meaning":"từng cái một, mỗi việc","hanviet":"nhất nhất","antonym":"まとめて: gộp lại / 一括して（いっかつして）: gộp một lượt","antonym_hanviet":" / nhất quát","note":"Hay đi với ～ない, 文句を言う. Thường hàm ý phiền phức.","example":"一々説明しなくても、分かってくれるはずだ。","example_reading":"いちいちせつめいしなくても、わかってくれるはずだ。","example_meaning":"Không cần giải thích từng thứ, chắc anh ấy sẽ hiểu.","examples":[{"example":"一々説明しなくても、分かってくれるはずだ。","example_reading":"いちいちせつめいしなくても、わかってくれるはずだ。","example_meaning":"Không cần giải thích từng thứ, chắc anh ấy sẽ hiểu."},{"example":"彼は人のやることに、一々文句をつける。","example_reading":"かれはひとのやることに、いちいちもんくをつける。","example_meaning":"Anh ta cứ bắt bẻ từng việc người khác làm."}],"level":"d1"},
{"word":"毎度","reading":"まいど","meaning":"mỗi lần; xin cảm ơn quý khách","hanviet":"mỗi độ","note":"Cũng dùng chào khách: 毎度ありがとうございます.","example":"毎度のことながら、彼の遅刻には困ったものだ。","example_reading":"まいどのことながら、かれのちこくにはこまったものだ。","example_meaning":"Lần nào cũng vậy, anh ấy đi muộn thật khiến người ta khó xử.","examples":[{"example":"毎度のことながら、彼の遅刻には困ったものだ。","example_reading":"まいどのことながら、かれのちこくにはこまったものだ。","example_meaning":"Lần nào cũng vậy, anh ấy đi muộn thật khiến người ta khó xử."},{"example":"毎度ありがとうございます。またお越しください。","example_reading":"まいどありがとうございます。またおこしください。","example_meaning":"Xin cảm ơn quý khách luôn ủng hộ. Mời quý khách lần sau lại ghé."}],"level":"d1"},
{"word":"大量に","reading":"たいりょうに","meaning":"với số lượng lớn","hanviet":"đại lượng","antonym":"少量（しょうりょう）: lượng ít / わずか: ít ỏi","antonym_hanviet":"thiểu lượng / ","note":"Hay đi với 買う, 作る, 発生する.","example":"工場では、毎日大量に部品を作っている。","example_reading":"こうじょうでは、まいにちたいりょうにぶひんをつくっている。","example_meaning":"Nhà máy mỗi ngày sản xuất một lượng lớn linh kiện.","examples":[{"example":"工場では、毎日大量に部品を作っている。","example_reading":"こうじょうでは、まいにちたいりょうにぶひんをつくっている。","example_meaning":"Nhà máy mỗi ngày sản xuất một lượng lớn linh kiện."},{"example":"台風の前に、大量に水と食料を買っておいた。","example_reading":"たいふうのまえに、たいりょうにみずとしょくりょうをかっておいた。","example_meaning":"Trước bão, tôi đã mua sẵn nhiều nước và thực phẩm."}],"level":"d1"},
{"word":"引き続き","reading":"ひきつづき","meaning":"tiếp tục","hanviet":"dẫn tục","antonym":"中断して（ちゅうだんして）: gián đoạn / 打ち切って（うちきって）: chấm dứt","antonym_hanviet":"trung đoạn / đả thiết","note":"Tiếp nối việc đang làm. Hay đi với ご協力, お願いします. Cũng nghĩa \"ngay sau đó\" (trong chương trình).","example":"今後も引き続き、ご協力をお願いいたします。","example_reading":"こんごもひきつづき、ごきょうりょくをおねがいいたします。","example_meaning":"Mong tiếp tục nhận được sự hợp tác của quý vị trong thời gian tới.","examples":[{"example":"今後も引き続き、ご協力をお願いいたします。","example_reading":"こんごもひきつづき、ごきょうりょくをおねがいいたします。","example_meaning":"Mong tiếp tục nhận được sự hợp tác của quý vị trong thời gian tới."},{"example":"引き続きニュースをお伝えします。","example_reading":"ひきつづきニュースをおつたえします。","example_meaning":"Chúng tôi xin tiếp tục gửi đến quý vị bản tin."}],"level":"d1"},
{"word":"以前","reading":"いぜん","meaning":"trước đây","hanviet":"dĩ tiền","note":"Đọc いぜん. Hay đi với ～は／～より. Thời điểm trước hiện tại; cũng là danh từ.","antonym":"今後（こんご）: từ nay về sau / 近頃（ちかごろ）: dạo này","antonym_hanviet":"kim hậu / cận khoảnh","example":"以前、この町に住んでいたことがある。","example_reading":"いぜん、このまちにすんでいたことがある。","example_meaning":"Trước đây tôi từng sống ở thị trấn này.","examples":[{"example":"以前、この町に住んでいたことがある。","example_reading":"いぜん、このまちにすんでいたことがある。","example_meaning":"Trước đây tôi từng sống ở thị trấn này."},{"example":"この店は以前より料理が美味しくなった。","example_reading":"このみせはいぜんよりりょうりがおいしくなった。","example_meaning":"Quán này đồ ăn ngon hơn trước."}],"level":"d1"},
{"word":"いまだに","reading":"いまだに","meaning":"đến giờ vẫn, vẫn còn","antonym":"もはや: giờ đây không còn","note":"Việc kéo dài từ trước đến nay, thường kèm bất ngờ hoặc chê. Hay đi với ～ている／～ない.","example":"事故の原因は、いまだにわかっていない。","example_reading":"じこのげんいんは、いまだにわかっていない。","example_meaning":"Nguyên nhân vụ tai nạn đến giờ vẫn chưa rõ.","examples":[{"example":"事故の原因は、いまだにわかっていない。","example_reading":"じこのげんいんは、いまだにわかっていない。","example_meaning":"Nguyên nhân vụ tai nạn đến giờ vẫn chưa rõ."},{"example":"祖父はいまだに、毎朝畑に出ている。","example_reading":"そふはいまだに、まいあさはたけにでている。","example_meaning":"Ông tôi đến giờ vẫn ra đồng mỗi sáng."}],"level":"d1"},
{"word":"依然として","reading":"いぜんとして","meaning":"vẫn như cũ","hanviet":"y nhiên","antonym":"一変して（いっぺんして）: thay đổi hoàn toàn / がらり: thay đổi hẳn","antonym_hanviet":"nhất biến / ","note":"Tình trạng không thay đổi. Văn viết, tin tức. Hay đi với 続く, ～のままだ.","example":"失業率は、依然として高い水準にある。","example_reading":"しつぎょうりつは、いぜんとしてたかいすいじゅんにある。","example_meaning":"Tỷ lệ thất nghiệp vẫn ở mức cao.","examples":[{"example":"失業率は、依然として高い水準にある。","example_reading":"しつぎょうりつは、いぜんとしてたかいすいじゅんにある。","example_meaning":"Tỷ lệ thất nghiệp vẫn ở mức cao."},{"example":"行方不明の登山者は、依然として見つかっていない。","example_reading":"ゆくえふめいのとざんしゃは、いぜんとしてみつかっていない。","example_meaning":"Người leo núi mất tích vẫn chưa được tìm thấy."}],"level":"d1"},
{"word":"若干","reading":"じゃっかん","meaning":"một chút, chút ít","hanviet":"nhược can","antonym":"大幅に（おおはばに）: đáng kể, nhiều","antonym_hanviet":"đại bức","note":"Văn viết, công việc. Hay đi với 修正, 遅れる, 異なる. Số lượng ít, không xác định.","example":"予定より若干遅れて、電車が到着した。","example_reading":"よていよりじゃっかんおくれて、でんしゃがとうちゃくした。","example_meaning":"Tàu đến muộn hơn dự kiến một chút.","examples":[{"example":"予定より若干遅れて、電車が到着した。","example_reading":"よていよりじゃっかんおくれて、でんしゃがとうちゃくした。","example_meaning":"Tàu đến muộn hơn dự kiến một chút."},{"example":"結果は予想と若干異なっていた。","example_reading":"けっかはよそうとじゃっかんことなっていた。","example_meaning":"Kết quả hơi khác so với dự đoán."}],"level":"d1"},
{"word":"本来","reading":"ほんらい","meaning":"vốn dĩ, đúng ra","hanviet":"bản lai","note":"Hay đi với ～べきだ, ～はずだ. Chỉ trạng thái đúng ra phải thế.","example":"本来、これは私の仕事ではないはずだ。","example_reading":"ほんらい、これはわたしのしごとではないはずだ。","example_meaning":"Đúng ra đây không phải là việc của tôi.","examples":[{"example":"本来、これは私の仕事ではないはずだ。","example_reading":"ほんらい、これはわたしのしごとではないはずだ。","example_meaning":"Đúng ra đây không phải là việc của tôi."},{"example":"子どもは本来、遊びを通して学ぶものだ。","example_reading":"こどもはほんらい、あそびをつうじてまなぶものだ。","example_meaning":"Vốn dĩ trẻ em học thông qua vui chơi."}],"level":"d1"},
{"word":"大半","reading":"たいはん","meaning":"phần lớn","hanviet":"đại bán","antonym":"少数（しょうすう）: số ít / 一部（いちぶ）: một phần","antonym_hanviet":"thiểu số / nhất bộ","note":"Hay đi với を占める, の人. Hơn một nửa.","example":"参加者の大半は、二十代の若者だった。","example_reading":"さんかしゃのたいはんは、にじゅうだいのわかものだった。","example_meaning":"Phần lớn người tham gia là thanh niên ở độ tuổi hai mươi.","examples":[{"example":"参加者の大半は、二十代の若者だった。","example_reading":"さんかしゃのたいはんは、にじゅうだいのわかものだった。","example_meaning":"Phần lớn người tham gia là thanh niên ở độ tuổi hai mươi."},{"example":"夏休みの宿題は、大半が終わっている。","example_reading":"なつやすみのしゅくだいは、たいはんがおわっている。","example_meaning":"Bài tập hè đã làm xong phần lớn."}],"level":"d1"},
{"word":"年中","reading":"ねんじゅう","meaning":"quanh năm, lúc nào cũng","hanviet":"niên trung","note":"Hay đi với 忙しい, 無休.","example":"この店は年中無休で営業している。","example_reading":"このみせはねんじゅうむきゅうでえいぎょうしている。","example_meaning":"Cửa hàng này mở cửa quanh năm không nghỉ.","examples":[{"example":"この店は年中無休で営業している。","example_reading":"このみせはねんじゅうむきゅうでえいぎょうしている。","example_meaning":"Cửa hàng này mở cửa quanh năm không nghỉ."},{"example":"彼は年中、仕事の文句ばかり言っている。","example_reading":"かれはねんじゅう、しごとのもんくばかりいっている。","example_meaning":"Anh ta lúc nào cũng chỉ than phiền về công việc."}],"level":"d1"},
{"word":"随時","reading":"ずいじ","meaning":"bất cứ lúc nào, tùy thời","hanviet":"tùy thời","note":"Hay đi với 受け付ける, 募集する, 更新する.","example":"質問は随時受け付けています。","example_reading":"しつもんはずいじうけつけています。","example_meaning":"Chúng tôi tiếp nhận câu hỏi bất cứ lúc nào.","examples":[{"example":"質問は随時受け付けています。","example_reading":"しつもんはずいじうけつけています。","example_meaning":"Chúng tôi tiếp nhận câu hỏi bất cứ lúc nào."},{"example":"情報は随時更新されるので、こまめに確認してください。","example_reading":"じょうほうはずいじこうしんされるので、こまめにかくにんしてください。","example_meaning":"Thông tin được cập nhật liên tục nên hãy thường xuyên kiểm tra."}],"level":"d1"},
{"word":"再度","reading":"さいど","meaning":"một lần nữa","hanviet":"tái độ","antonym":"初めて（はじめて）: lần đầu tiên","antonym_hanviet":"sơ","note":"Trang trọng. Gần 再び.","example":"内容に誤りがありましたので、再度ご確認ください。","example_reading":"ないようにあやまりがありましたので、さいどごかくにんください。","example_meaning":"Nội dung có sai sót, xin vui lòng kiểm tra lại.","examples":[{"example":"内容に誤りがありましたので、再度ご確認ください。","example_reading":"ないようにあやまりがありましたので、さいどごかくにんください。","example_meaning":"Nội dung có sai sót, xin vui lòng kiểm tra lại."},{"example":"失敗したが、再度挑戦してみるつもりだ。","example_reading":"しっぱいしたが、さいどちょうせんしてみるつもりだ。","example_meaning":"Tôi thất bại nhưng định thử thách thêm lần nữa."}],"level":"d1"},
{"word":"過日","reading":"かじつ","meaning":"hôm trước","hanviet":"quá nhật","antonym":"後日（ごじつ）: ngày sau","antonym_hanviet":"hậu nhật","note":"Văn viết, thư từ trang trọng.","example":"過日は、お忙しい中お時間をいただき、ありがとうございました。","example_reading":"かじつは、おいそがしいなかおじかんをいただき、ありがとうございました。","example_meaning":"Hôm trước, cảm ơn anh/chị đã dành thời gian dù bận rộn.","examples":[{"example":"過日は、お忙しい中お時間をいただき、ありがとうございました。","example_reading":"かじつは、おいそがしいなかおじかんをいただき、ありがとうございました。","example_meaning":"Hôm trước, cảm ơn anh/chị đã dành thời gian dù bận rộn."},{"example":"過日お送りした書類は、届いておりますでしょうか。","example_reading":"かじつおおくりしたしょるいは、とどいておりますでしょうか。","example_meaning":"Không biết tài liệu tôi gửi hôm trước đã đến chưa ạ."}],"level":"d1"},
{"word":"随所に","reading":"ずいしょに","meaning":"khắp nơi","hanviet":"tùy sở","note":"Hay đi với 見られる, 残る, 散りばめる.","example":"この街の随所に、歴史を感じさせる建物が残っている。","example_reading":"このまちのずいしょに、れきしをかんじさせるたてものがのこっている。","example_meaning":"Khắp nơi trong thành phố còn những tòa nhà gợi nhớ lịch sử.","examples":[{"example":"この街の随所に、歴史を感じさせる建物が残っている。","example_reading":"このまちのずいしょに、れきしをかんじさせるたてものがのこっている。","example_meaning":"Khắp nơi trong thành phố còn những tòa nhà gợi nhớ lịch sử."},{"example":"彼の文章には、随所にユーモアが散りばめられている。","example_reading":"かれのぶんしょうには、ずいしょにユーモアがちりばめられている。","example_meaning":"Văn của anh ấy rải rác sự hài hước khắp nơi."}],"level":"d1"},
{"word":"辺り一面","reading":"あたりいちめん","meaning":"khắp xung quanh","hanviet":"biên nhất diện","note":"Hay đi với が, に. Toàn bộ vùng xung quanh.","example":"朝起きると、辺り一面が雪で真っ白だった。","example_reading":"あさおきると、あたりいちめんがゆきでまっしろだった。","example_meaning":"Sáng thức dậy, khắp xung quanh trắng xóa tuyết.","examples":[{"example":"朝起きると、辺り一面が雪で真っ白だった。","example_reading":"あさおきると、あたりいちめんがゆきでまっしろだった。","example_meaning":"Sáng thức dậy, khắp xung quanh trắng xóa tuyết."},{"example":"秋になって、辺り一面に落ち葉が積もった。","example_reading":"あきになって、あたりいちめんにおちばがつもった。","example_meaning":"Thu đến, lá rụng phủ kín khắp xung quanh."}],"level":"d1"},
{"word":"寸前に","reading":"すんぜんに","meaning":"ngay trước khi","hanviet":"thốn tiền","antonym":"直後に（ちょくごに）: ngay sau","antonym_hanviet":"trực hậu","note":"Hay đi với の. Sát ngay trước thời điểm.","example":"電車のドアが閉まる寸前に、何とか飛び乗った。","example_reading":"でんしゃのドアがしまるすんぜんに、なんとかとびのった。","example_meaning":"Ngay trước khi cửa tàu đóng, tôi vừa kịp nhảy lên.","examples":[{"example":"電車のドアが閉まる寸前に、何とか飛び乗った。","example_reading":"でんしゃのドアがしまるすんぜんに、なんとかとびのった。","example_meaning":"Ngay trước khi cửa tàu đóng, tôi vừa kịp nhảy lên."},{"example":"試合終了の寸前に、決勝点が入った。","example_reading":"しあいしゅうりょうのすんぜんに、けっしょうてんがはいった。","example_meaning":"Ngay trước khi trận đấu kết thúc, bàn thắng quyết định đã được ghi."}],"level":"d1"},
{"word":"序盤","reading":"じょばん","meaning":"giai đoạn đầu","hanviet":"tự bàn","antonym":"終盤（しゅうばん）: giai đoạn cuối","antonym_hanviet":"chung bàn","note":"Dùng cho trận đấu, ván cờ, câu chuyện.","example":"試合の序盤は、相手に押されっぱなしだった。","example_reading":"しあいのじょばんは、あいてにおされっぱなしだった。","example_meaning":"Giai đoạn đầu trận đấu, chúng tôi bị đối phương dồn ép liên tục.","examples":[{"example":"試合の序盤は、相手に押されっぱなしだった。","example_reading":"しあいのじょばんは、あいてにおされっぱなしだった。","example_meaning":"Giai đoạn đầu trận đấu, chúng tôi bị đối phương dồn ép liên tục."},{"example":"序盤でリードを奪えば、有利に進められる。","example_reading":"じょばんでリードをうばえば、ゆうりにすすめられる。","example_meaning":"Nếu giành thế dẫn trước từ đầu thì có lợi trong diễn biến sau."}],"level":"d1"},
{"word":"一挙に","reading":"いっきょに","meaning":"một lượt, một hơi","hanviet":"nhất cử","antonym":"少しずつ（すこしずつ）: từng chút / 徐々に（じょじょに）: dần dần / 段階的に（だんかいてきに）: từng giai đoạn","antonym_hanviet":"thiểu / từ từ / đoạn giai đích","note":"Hay đi với 解決する, 発売する, 増える.","example":"難しい問題が一挙に解決した。","example_reading":"むずかしいもんだいがいっきょにかいけつした。","example_meaning":"Vấn đề khó đã được giải quyết trong một lượt.","examples":[{"example":"難しい問題が一挙に解決した。","example_reading":"むずかしいもんだいがいっきょにかいけつした。","example_meaning":"Vấn đề khó đã được giải quyết trong một lượt."},{"example":"新製品を一挙に十種類発売する予定だ。","example_reading":"しんせいひんをいっきょにじっしゅるいはつばいするよていだ。","example_meaning":"Dự định tung ra một lượt mười loại sản phẩm mới."}],"level":"d1"},
{"word":"順々に","reading":"じゅんじゅんに","meaning":"lần lượt, theo thứ tự","hanviet":"thuận thuận","antonym":"一斉に（いっせいに）: đồng loạt / 同時に（どうじに）: đồng thời","antonym_hanviet":"nhất tề / đồng thời","note":"Gần 順番に, trang trọng hơn một chút.","example":"呼ばれた人から、順々に中へ入ってください。","example_reading":"よばれたひとから、じゅんじゅんになかへはいってください。","example_meaning":"Xin mời người được gọi lần lượt vào trong.","examples":[{"example":"呼ばれた人から、順々に中へ入ってください。","example_reading":"よばれたひとから、じゅんじゅんになかへはいってください。","example_meaning":"Xin mời người được gọi lần lượt vào trong."},{"example":"生徒たちは順々に前に出て、作文を読み上げた。","example_reading":"せいとたちはじゅんじゅんにまえにでて、さくぶんをよみあげた。","example_meaning":"Học sinh lần lượt lên trước đọc bài văn."}],"level":"d1"},
{"word":"いささか","reading":"いささか","meaning":"hơi, có phần","antonym":"大いに（おおいに）: rất / 非常に（ひじょうに）: cực kỳ","antonym_hanviet":"đại / phi thường","note":"Hay đi với 疲れる, 無理がある, 心配だ. Văn viết, hơi trang trọng.","example":"その提案には、いささか無理があるように思う。","example_reading":"そのていあんには、いささかむりがあるようにおもう。","example_meaning":"Tôi thấy đề xuất này có phần khiên cưỡng.","examples":[{"example":"その提案には、いささか無理があるように思う。","example_reading":"そのていあんには、いささかむりがあるようにおもう。","example_meaning":"Tôi thấy đề xuất này có phần khiên cưỡng."},{"example":"いささか疲れたので、少し休ませてください。","example_reading":"いささかつかれたので、すこしやすませてください。","example_meaning":"Tôi hơi mệt nên xin cho nghỉ một chút."}],"level":"d1"},
{"word":"すれすれ","reading":"すれすれ","meaning":"sát sạt","note":"Hay đi với の, に. Rất gần giới hạn hoặc bề mặt.","example":"車が、歩道すれすれを走っていった。","example_reading":"くるまが、ほどうすれすれをはしっていった。","example_meaning":"Chiếc xe chạy sát sạt vỉa hè.","examples":[{"example":"車が、歩道すれすれを走っていった。","example_reading":"くるまが、ほどうすれすれをはしっていった。","example_meaning":"Chiếc xe chạy sát sạt vỉa hè."},{"example":"締め切りすれすれに、レポートを提出した。","example_reading":"しめきりすれすれに、レポートをていしゅつした。","example_meaning":"Tôi nộp báo cáo sát giờ chót."}],"level":"d1"},
{"word":"定期的に","reading":"ていきてきに","meaning":"một cách định kỳ","hanviet":"định kỳ đích","antonym":"不定期に（ふていきに）: bất định kỳ / 不規則に（ふきそくに）: bất thường","antonym_hanviet":"bất định kỳ / bất quy tắc","note":"Hay đi với 検査する, 掃除する, 連絡する.","example":"健康のために、定期的に検査を受けている。","example_reading":"けんこうのために、ていきてきにけんさをうけている。","example_meaning":"Vì sức khỏe, tôi đi kiểm tra định kỳ.","examples":[{"example":"健康のために、定期的に検査を受けている。","example_reading":"けんこうのために、ていきてきにけんさをうけている。","example_meaning":"Vì sức khỏe, tôi đi kiểm tra định kỳ."},{"example":"部屋は定期的に換気したほうがいい。","example_reading":"へやはていきてきにかんきしたほうがいい。","example_meaning":"Nên thông gió phòng định kỳ."}],"level":"d1"},
{"word":"共に","reading":"ともに","meaning":"cùng nhau, cùng với","hanviet":"cộng","antonym":"単独で（たんどくで）: một mình / 別々に（べつべつに）: riêng rẽ","antonym_hanviet":"đơn độc / biệt biệt","note":"Văn viết. Hay dùng ～と共に: cùng với, theo cùng.","example":"彼とは学生時代を共に過ごした仲だ。","example_reading":"かれとはがくせいじだいをともにすごしたなかだ。","example_meaning":"Tôi với anh ấy là bạn cùng trải qua thời sinh viên.","examples":[{"example":"彼とは学生時代を共に過ごした仲だ。","example_reading":"かれとはがくせいじだいをともにすごしたなかだ。","example_meaning":"Tôi với anh ấy là bạn cùng trải qua thời sinh viên."},{"example":"年齢と共に、体力は少しずつ落ちていく。","example_reading":"ねんれいとともに、たいりょくはすこしずつおちていく。","example_meaning":"Cùng với tuổi tác, thể lực giảm dần từng chút."}],"level":"d1"},
{"word":"一層","reading":"いっそう","meaning":"hơn nữa, càng thêm","hanviet":"nhất tằng","note":"So với trước đó, mức độ tăng rõ. Trang trọng. Hay đi với 努力, 注意, 厳しい.","example":"試合に勝つために、一層努力しなければならない。","example_reading":"しあいにかつために、いっそうどりょくしなければならない。","example_meaning":"Để thắng trận đấu, chúng ta phải nỗ lực hơn nữa.","examples":[{"example":"試合に勝つために、一層努力しなければならない。","example_reading":"しあいにかつために、いっそうどりょくしなければならない。","example_meaning":"Để thắng trận đấu, chúng ta phải nỗ lực hơn nữa."},{"example":"雨のせいで、道路の渋滞は一層ひどくなった。","example_reading":"あめのせいで、どうろのじゅうたいはいっそうひどくなった。","example_meaning":"Vì mưa, tình trạng kẹt xe trên đường càng tồi tệ hơn."}],"level":"d1"},
{"word":"とりわけ","reading":"とりわけ","meaning":"nhất là, đặc biệt là","note":"Trang trọng hơn 特に. Văn viết.","example":"今年の夏は暑く、とりわけ八月は記録的な猛暑だった。","example_reading":"ことしのなつはあつく、とりわけはちがつはきろくてきなもうしょだった。","example_meaning":"Mùa hè năm nay nóng, nhất là tháng Tám nóng kỷ lục.","examples":[{"example":"今年の夏は暑く、とりわけ八月は記録的な猛暑だった。","example_reading":"ことしのなつはあつく、とりわけはちがつはきろくてきなもうしょだった。","example_meaning":"Mùa hè năm nay nóng, nhất là tháng Tám nóng kỷ lục."},{"example":"彼は語学が得意で、とりわけ中国語は母語のように話す。","example_reading":"かれはごがくがとくいで、とりわけちゅうごくごはぼごのようにはなす。","example_meaning":"Anh ấy giỏi ngoại ngữ, nhất là tiếng Trung thì nói như tiếng mẹ đẻ."}],"level":"d1"},
{"word":"はるかに","reading":"はるかに","meaning":"hơn hẳn, xa hơn nhiều; xa xăm","antonym":"わずかに: một chút ít","note":"So sánh: ～よりはるかに ～. Cũng dùng chỉ khoảng cách rất xa (はるか彼方).","example":"実際に食べてみると、写真で見るよりはるかにおいしかった。","example_reading":"じっさいにたべてみると、しゃしんでみるよりはるかにおいしかった。","example_meaning":"Ăn thử thật thì ngon hơn hẳn so với nhìn trong ảnh.","examples":[{"example":"実際に食べてみると、写真で見るよりはるかにおいしかった。","example_reading":"じっさいにたべてみると、しゃしんでみるよりはるかにおいしかった。","example_meaning":"Ăn thử thật thì ngon hơn hẳn so với nhìn trong ảnh."},{"example":"窓の外には、はるかに海が広がっている。","example_reading":"まどのそとには、はるかにうみがひろがっている。","example_meaning":"Ngoài cửa sổ, biển trải rộng xa tít tắp."}],"level":"d1"},
{"word":"頻繁に","reading":"ひんぱんに","meaning":"thường xuyên, liên tục","hanviet":"tần phồn","note":"Tần suất rất cao. Hay đi với 起こる, 連絡する, 行く.","antonym":"たまに: thỉnh thoảng / 久々に（ひさびさに）: lâu rồi mới / 久しぶりに（ひさしぶりに）: sau một thời gian dài","antonym_hanviet":" / cửu cửu / cửu","example":"最近、この交差点では事故が頻繁に起きている。","example_reading":"さいきん、このこうさてんではじこがひんぱんにおきている。","example_meaning":"Gần đây ở ngã tư này tai nạn xảy ra thường xuyên.","examples":[{"example":"最近、この交差点では事故が頻繁に起きている。","example_reading":"さいきん、このこうさてんではじこがひんぱんにおきている。","example_meaning":"Gần đây ở ngã tư này tai nạn xảy ra thường xuyên."},{"example":"祖母とは頻繁に電話で話している。","example_reading":"そぼとはひんぱんにでんわではなしている。","example_meaning":"Tôi thường xuyên nói chuyện điện thoại với bà."}],"level":"d1"},
{"word":"何度も","reading":"なんども","meaning":"nhiều lần","hanviet":"hà độ","antonym":"一度も（いちども）: chưa một lần / 一度（いちど）: lần","antonym_hanviet":"nhất độ / nhất độ","note":"Đọc なんども. Hay đi với 言う, 読む, 失敗する. Lặp lại nhiều lần.","example":"同じ説明を何度も繰り返した。","example_reading":"おなじせつめいをなんどもくりかえした。","example_meaning":"Tôi đã lặp lại cùng lời giải thích nhiều lần.","examples":[{"example":"同じ説明を何度も繰り返した。","example_reading":"おなじせつめいをなんどもくりかえした。","example_meaning":"Tôi đã lặp lại cùng lời giải thích nhiều lần."},{"example":"彼女に何度も電話したが、出なかった。","example_reading":"かのじょになんどもでんわしたが、でなかった。","example_meaning":"Tôi gọi cho cô ấy nhiều lần nhưng không bắt máy."}],"level":"d1"},
{"word":"いつしか","reading":"いつしか","meaning":"từ lúc nào không biết","note":"Văn viết. Thay đổi diễn ra dần dần.","example":"いつしか、季節は秋から冬へと変わっていた。","example_reading":"いつしか、きせつはあきからふゆへとかわっていた。","example_meaning":"Chẳng biết từ lúc nào, mùa đã chuyển từ thu sang đông.","examples":[{"example":"いつしか、季節は秋から冬へと変わっていた。","example_reading":"いつしか、きせつはあきからふゆへとかわっていた。","example_meaning":"Chẳng biết từ lúc nào, mùa đã chuyển từ thu sang đông."},{"example":"いつしか、二人は互いに惹かれ合うようになった。","example_reading":"いつしか、ふたりはたがいにひかれあうようになった。","example_meaning":"Chẳng biết từ khi nào, hai người dần cảm mến nhau."}],"level":"d1"},
{"word":"終始","reading":"しゅうし","meaning":"từ đầu đến cuối","hanviet":"chung thủy","antonym":"途中で（とちゅうで）: giữa chừng","antonym_hanviet":"đồ trung","note":"Hay đi với 笑顔, 無言, 穏やかに.","example":"彼は終始、穏やかな表情で話を聞いていた。","example_reading":"かれはしゅうし、おだやかなひょうじょうではなしをきいていた。","example_meaning":"Anh ấy nghe chuyện với nét mặt điềm đạm từ đầu đến cuối.","examples":[{"example":"彼は終始、穏やかな表情で話を聞いていた。","example_reading":"かれはしゅうし、おだやかなひょうじょうではなしをきいていた。","example_meaning":"Anh ấy nghe chuyện với nét mặt điềm đạm từ đầu đến cuối."},{"example":"会議は終始、和やかな雰囲気で行われた。","example_reading":"かいぎはしゅうし、なごやかなふんいきでおこなわれた。","example_meaning":"Cuộc họp diễn ra trong không khí hòa nhã từ đầu đến cuối."}],"level":"d1"},
{"word":"一貫して","reading":"いっかんして","meaning":"nhất quán, xuyên suốt","hanviet":"nhất quán","antonym":"気まぐれに（きまぐれに）: thất thường / 場当たり的に（ばあたりてきに）: tùy cơ","antonym_hanviet":"khí / trường đương đích","note":"Hay đi với 反対する, 主張する, こだわる.","example":"彼は一貫して、その計画に反対してきた。","example_reading":"かれはいっかんして、そのけいかくにはんたいしてきた。","example_meaning":"Anh ấy đã luôn nhất quán phản đối kế hoạch đó.","examples":[{"example":"彼は一貫して、その計画に反対してきた。","example_reading":"かれはいっかんして、そのけいかくにはんたいしてきた。","example_meaning":"Anh ấy đã luôn nhất quán phản đối kế hoạch đó."},{"example":"この店は、創業以来一貫して手作りにこだわっている。","example_reading":"このみせは、そうぎょういらいいっかんしててづくりにこだわっている。","example_meaning":"Quán này từ khi thành lập vẫn luôn trung thành với đồ thủ công."}],"level":"d1"},
{"word":"たびたび","reading":"たびたび","meaning":"nhiều lần, thường xuyên","antonym":"めったに: hiếm khi","note":"Tần suất khá cao. Văn viết hoặc nói lịch sự.","example":"たびたびご迷惑をおかけして、申し訳ありません。","example_reading":"たびたびごめいわくをおかけして、もうしわけありません。","example_meaning":"Tôi xin lỗi vì đã nhiều lần gây phiền hà.","examples":[{"example":"たびたびご迷惑をおかけして、申し訳ありません。","example_reading":"たびたびごめいわくをおかけして、もうしわけありません。","example_meaning":"Tôi xin lỗi vì đã nhiều lần gây phiền hà."},{"example":"彼女は出張で、たびたび海外へ行く。","example_reading":"かのじょはしゅっちょうで、たびたびかいがいへいく。","example_meaning":"Cô ấy hay đi nước ngoài vì công tác."}],"level":"d1"},
{"word":"大部分","reading":"だいぶぶん","meaning":"phần lớn","hanviet":"đại bộ phận","antonym":"一部（いちぶ）: một phần / 少数（しょうすう）: số ít","antonym_hanviet":"nhất bộ / thiểu số","note":"Gần 大半 nhưng nhấn mạnh tỷ lệ rất cao.","example":"試験問題の大部分は、授業で習った内容だった。","example_reading":"しけんもんだいのだいぶぶんは、じゅぎょうでならったないようだった。","example_meaning":"Phần lớn đề thi là nội dung đã học trên lớp.","examples":[{"example":"試験問題の大部分は、授業で習った内容だった。","example_reading":"しけんもんだいのだいぶぶんは、じゅぎょうでならったないようだった。","example_meaning":"Phần lớn đề thi là nội dung đã học trên lớp."},{"example":"森の大部分が、火事で焼けてしまった。","example_reading":"もりのだいぶぶんが、かじでやけてしまった。","example_meaning":"Phần lớn khu rừng đã bị lửa thiêu rụi."}],"level":"d1"},
{"word":"終日","reading":"しゅうじつ","meaning":"suốt ngày","hanviet":"chung nhật","note":"Văn viết, thường gặp trong dự báo thời tiết.","example":"明日は終日、雨が降るでしょう。","example_reading":"あしたはしゅうじつ、あめがふるでしょう。","example_meaning":"Ngày mai trời sẽ mưa suốt ngày.","examples":[{"example":"明日は終日、雨が降るでしょう。","example_reading":"あしたはしゅうじつ、あめがふるでしょう。","example_meaning":"Ngày mai trời sẽ mưa suốt ngày."},{"example":"日曜日は終日、家で読書をして過ごした。","example_reading":"にちようびはしゅうじつ、いえでどくしょをしてすごした。","example_meaning":"Chủ nhật tôi ở nhà đọc sách cả ngày."}],"level":"d1"},
{"word":"夜通し","reading":"よどおし","meaning":"thâu đêm, suốt đêm","hanviet":"dạ thông","note":"Hay đi với 歩く, 語り合う, 運転する.","example":"友達と夜通し語り合って、朝になってしまった。","example_reading":"ともだちとよどおしかたりあって、あさになってしまった。","example_meaning":"Nói chuyện với bạn thâu đêm, thế là trời sáng.","examples":[{"example":"友達と夜通し語り合って、朝になってしまった。","example_reading":"ともだちとよどおしかたりあって、あさになってしまった。","example_meaning":"Nói chuyện với bạn thâu đêm, thế là trời sáng."},{"example":"看病のために、母は夜通し起きていた。","example_reading":"かんびょうのために、はははよどおしおきていた。","example_meaning":"Để chăm bệnh, mẹ tôi thức suốt đêm."}],"level":"d1"},
{"word":"ばらばらに","reading":"ばらばらに","meaning":"rời rạc, tản mác","antonym":"一緒に（いっしょに）: cùng nhau / まとめて: gộp lại / 順番に（じゅんばんに）: lần lượt","antonym_hanviet":"nhất tự /  / thuận phiên","note":"Hay đi với 暮らす, 動く, 言う. Không thống nhất.","example":"家族は、仕事の都合でばらばらに暮らしている。","example_reading":"かぞくは、しごとのつごうでばらばらにくらしている。","example_meaning":"Cả nhà sống tản mác vì công việc.","examples":[{"example":"家族は、仕事の都合でばらばらに暮らしている。","example_reading":"かぞくは、しごとのつごうでばらばらにくらしている。","example_meaning":"Cả nhà sống tản mác vì công việc."},{"example":"みんながばらばらに意見を言って、話がまとまらない。","example_reading":"みんながばらばらにいけんをいって、はなしがまとまらない。","example_meaning":"Mỗi người nói một ý nên câu chuyện không đi đến đâu."}],"level":"d1"},
{"word":"古来","reading":"こらい","meaning":"từ xa xưa","hanviet":"cổ lai","antonym":"近年（きんねん）: những năm gần đây","antonym_hanviet":"cận niên","note":"Văn viết. Hay đi với ～てきた.","example":"この地方では、古来、米作りが盛んだった。","example_reading":"このちほうでは、こらい、こめづくりがさかんだった。","example_meaning":"Vùng này từ xa xưa đã thịnh trồng lúa.","examples":[{"example":"この地方では、古来、米作りが盛んだった。","example_reading":"このちほうでは、こらい、こめづくりがさかんだった。","example_meaning":"Vùng này từ xa xưa đã thịnh trồng lúa."},{"example":"日本人は古来、自然を大切にしてきた。","example_reading":"にほんじんはこらい、しぜんをたいせつにしてきた。","example_meaning":"Người Nhật từ xưa đã trân trọng thiên nhiên."}],"level":"d1"},
{"word":"時たま","reading":"ときたま","meaning":"thỉnh thoảng, đôi khi","hanviet":"thời","antonym":"頻繁に（ひんぱんに）: thường xuyên / いつも: luôn luôn / 連日（れんじつ）: ngày nào cũng","antonym_hanviet":"tần phồn /  / liên nhật","note":"Gần たまに, 時々.","example":"彼は時たま、思い出したように連絡をくれる。","example_reading":"かれはときたま、おもいだしたようにれんらくをくれる。","example_meaning":"Thỉnh thoảng anh ấy lại chợt nhớ ra mà liên lạc.","examples":[{"example":"彼は時たま、思い出したように連絡をくれる。","example_reading":"かれはときたま、おもいだしたようにれんらくをくれる。","example_meaning":"Thỉnh thoảng anh ấy lại chợt nhớ ra mà liên lạc."},{"example":"時たま、無性に甘いものが食べたくなる。","example_reading":"ときたま、むしょうにあまいものがたべたくなる。","example_meaning":"Thỉnh thoảng tôi bỗng thèm đồ ngọt kinh khủng."}],"level":"d1"},
{"word":"すこぶる","reading":"すこぶる","meaning":"rất, hết sức","note":"Văn viết, hơi cổ.","example":"昨日は食べすぎたが、今朝はすこぶる調子がいい。","example_reading":"きのうはたべすぎたが、けさはすこぶるちょうしがいい。","example_meaning":"Hôm qua ăn quá nhiều nhưng sáng nay tôi khỏe vô cùng.","examples":[{"example":"昨日は食べすぎたが、今朝はすこぶる調子がいい。","example_reading":"きのうはたべすぎたが、けさはすこぶるちょうしがいい。","example_meaning":"Hôm qua ăn quá nhiều nhưng sáng nay tôi khỏe vô cùng."},{"example":"この映画は、すこぶる評判がいい。","example_reading":"このえいがは、すこぶるひょうばんがいい。","example_meaning":"Bộ phim này được đánh giá cực tốt."}],"level":"d1"},
{"word":"隅々まで","reading":"すみずみまで","meaning":"đến từng ngóc ngách","hanviet":"ngung","note":"Hay đi với 掃除する, 調べる, 行き渡る.","example":"部屋の隅々まで、きれいに掃除した。","example_reading":"へやのすみずみまで、きれいにそうじした。","example_meaning":"Tôi dọn dẹp sạch sẽ đến từng ngóc ngách trong phòng.","examples":[{"example":"部屋の隅々まで、きれいに掃除した。","example_reading":"へやのすみずみまで、きれいにそうじした。","example_meaning":"Tôi dọn dẹp sạch sẽ đến từng ngóc ngách trong phòng."},{"example":"書類を隅々まで読んで、間違いを探した。","example_reading":"しょるいをすみずみまでよんで、まちがいをさがした。","example_meaning":"Tôi đọc kỹ giấy tờ từng chỗ để tìm lỗi sai."}],"level":"d1"},
{"word":"各々","reading":"おのおの","meaning":"mỗi người, mỗi cái","hanviet":"các các","note":"Trang trọng, hơi cổ.","example":"参加者は各々、自分の意見を述べた。","example_reading":"さんかしゃはおのおの、じぶんのいけんをのべた。","example_meaning":"Mỗi người tham gia đều nêu ý kiến của mình.","examples":[{"example":"参加者は各々、自分の意見を述べた。","example_reading":"さんかしゃはおのおの、じぶんのいけんをのべた。","example_meaning":"Mỗi người tham gia đều nêu ý kiến của mình."},{"example":"各々の責任において、行動してください。","example_reading":"おのおののせきにんにおいて、こうどうしてください。","example_meaning":"Xin hãy hành động theo trách nhiệm của từng người."}],"level":"d1"},
{"word":"全般的に","reading":"ぜんぱんてきに","meaning":"nhìn chung, nói chung","hanviet":"toàn ban đích","antonym":"部分的に（ぶぶんてきに）: một phần / 個別に（こべつに）: riêng lẻ","antonym_hanviet":"bộ phân đích / cá biệt","note":"Dùng khi đánh giá khái quát.","example":"全般的に見て、今年の成績は良かった。","example_reading":"ぜんぱんてきにみて、ことしのせいせきはよかった。","example_meaning":"Nhìn chung, thành tích năm nay khá tốt.","examples":[{"example":"全般的に見て、今年の成績は良かった。","example_reading":"ぜんぱんてきにみて、ことしのせいせきはよかった。","example_meaning":"Nhìn chung, thành tích năm nay khá tốt."},{"example":"この地域は、全般的に物価が安い。","example_reading":"このちいきは、ぜんぱんてきにぶっかがやすい。","example_meaning":"Khu vực này nhìn chung giá cả rẻ."}],"level":"d1"},
{"word":"交互に","reading":"こうごに","meaning":"luân phiên, xen kẽ","hanviet":"giao hỗ","antonym":"続けて（つづけて）: liên tục / 同時に（どうじに）: đồng thời","antonym_hanviet":"tục / đồng thời","note":"Hay đi với 行う, 出す, 使う.","example":"兄と私は交互に犬の散歩に行っている。","example_reading":"あにとわたしはこうごにいぬのさんぽにいっている。","example_meaning":"Anh trai và tôi luân phiên dắt chó đi dạo.","examples":[{"example":"兄と私は交互に犬の散歩に行っている。","example_reading":"あにとわたしはこうごにいぬのさんぽにいっている。","example_meaning":"Anh trai và tôi luân phiên dắt chó đi dạo."},{"example":"左右の足を交互に出して、前に進む。","example_reading":"さゆうのあしをこうごにだして、まえにすすむ。","example_meaning":"Đưa chân trái và chân phải luân phiên để tiến lên."}],"level":"d1"},
{"word":"しばしば","reading":"しばしば","meaning":"thường, nhiều lần","antonym":"めったに: hiếm khi","note":"Tần suất cao, văn viết hơn よく. Hay đi với 起こる, 見られる.","example":"この地方では、冬に大雪になることがしばしばある。","example_reading":"このちほうでは、ふゆにおおゆきになることがしばしばある。","example_meaning":"Ở vùng này, mùa đông thường hay có tuyết lớn.","examples":[{"example":"この地方では、冬に大雪になることがしばしばある。","example_reading":"このちほうでは、ふゆにおおゆきになることがしばしばある。","example_meaning":"Ở vùng này, mùa đông thường hay có tuyết lớn."},{"example":"彼は授業中にしばしば居眠りをしている。","example_reading":"かれはじゅぎょうちゅうにしばしばいねむりをしている。","example_meaning":"Anh ấy hay ngủ gật trong giờ học."}],"level":"d1"},
{"word":"今にも","reading":"いまにも","meaning":"sắp sửa, như sắp","hanviet":"kim","note":"Đi với ～そうだ／～ようだ. Cảm giác sắp xảy ra ngay.","example":"空は暗く、今にも雨が降り出しそうだ。","example_reading":"そらはくらく、いまにもあめがふりだしそうだ。","example_meaning":"Trời tối sầm, mưa như sắp rơi ngay.","examples":[{"example":"空は暗く、今にも雨が降り出しそうだ。","example_reading":"そらはくらく、いまにもあめがふりだしそうだ。","example_meaning":"Trời tối sầm, mưa như sắp rơi ngay."},{"example":"彼女は今にも泣き出しそうな顔をしていた。","example_reading":"かのじょはいまにもなきだしそうなかおをしていた。","example_meaning":"Cô ấy có vẻ mặt như sắp khóc ngay."}],"level":"d1"},
{"word":"いずれ","reading":"いずれ","meaning":"rồi sẽ, sớm muộn","note":"Việc xảy ra trong tương lai chưa rõ khi nào. Cũng nghĩa \"dù thế nào đi nữa\" (いずれにせよ).","example":"この問題には、いずれ答えが出るだろう。","example_reading":"このもんだいには、いずれこたえがでるだろう。","example_meaning":"Vấn đề này rồi sẽ có lời đáp.","examples":[{"example":"この問題には、いずれ答えが出るだろう。","example_reading":"このもんだいには、いずれこたえがでるだろう。","example_meaning":"Vấn đề này rồi sẽ có lời đáp."},{"example":"いずれにせよ、明日までに結論を出さなければならない。","example_reading":"いずれにせよ、あしたまでにけつろんをださなければならない。","example_meaning":"Dù thế nào đi nữa, đến ngày mai cũng phải có kết luận."}],"level":"d1"},
{"word":"そのうち","reading":"そのうち","meaning":"một ngày nào đó, sớm thôi","note":"Chưa xác định thời gian, mơ hồ. Khẩu ngữ. Hay đi với ～でしょう／～と思う／lời hẹn lấp lửng.","example":"そのうちまた遊びに来てください。","example_reading":"そのうちまたあそびにきてください。","example_meaning":"Lúc nào đó lại đến chơi nhé.","examples":[{"example":"そのうちまた遊びに来てください。","example_reading":"そのうちまたあそびにきてください。","example_meaning":"Lúc nào đó lại đến chơi nhé."},{"example":"心配しなくても、そのうち慣れますよ。","example_reading":"しんぱいしなくても、そのうちなれますよ。","example_meaning":"Đừng lo, rồi sẽ quen thôi."}],"level":"d1"},
{"word":"早めに","reading":"はやめに","meaning":"sớm hơn thường lệ, sớm","hanviet":"tảo","antonym":"遅めに（おそめに）: muộn hơn một chút / 土壇場で（どたんばで）: vào phút chót","antonym_hanviet":"trì / thổ đàn trường","note":"Đọc はやめに. Hay đi với 出る, 準備する, 連絡する. Chủ động làm trước hơn bình thường.","example":"混むので、早めに家を出たほうがいい。","example_reading":"こむので、はやめにいえをでたほうがいい。","example_meaning":"Vì sẽ đông nên nên ra khỏi nhà sớm.","examples":[{"example":"混むので、早めに家を出たほうがいい。","example_reading":"こむので、はやめにいえをでたほうがいい。","example_meaning":"Vì sẽ đông nên nên ra khỏi nhà sớm."},{"example":"風邪は、早めに薬を飲むと治りやすい。","example_reading":"かぜは、はやめにくすりをのむとなおりやすい。","example_meaning":"Cảm cúm nếu uống thuốc sớm thì dễ khỏi."}],"level":"d1"},
{"word":"日常的に","reading":"にちじょうてきに","meaning":"thường nhật, hằng ngày","hanviet":"nhật thường đích","antonym":"例外的に（れいがいてきに）: ngoại lệ / たまに: thỉnh thoảng","antonym_hanviet":"lệ ngoại đích / ","note":"Hay đi với 使う, 行う, 食べる. Việc làm đều đặn trong đời sống.","example":"彼は日常的に英語を使って仕事をしている。","example_reading":"かれはにちじょうてきにえいごをつかってしごとをしている。","example_meaning":"Anh ấy dùng tiếng Anh trong công việc hằng ngày.","examples":[{"example":"彼は日常的に英語を使って仕事をしている。","example_reading":"かれはにちじょうてきにえいごをつかってしごとをしている。","example_meaning":"Anh ấy dùng tiếng Anh trong công việc hằng ngày."},{"example":"野菜を日常的に食べるよう心がけている。","example_reading":"やさいをにちじょうてきにたべるようこころがけている。","example_meaning":"Tôi cố gắng ăn rau thường xuyên mỗi ngày."}],"level":"d1"},
{"word":"相次いで","reading":"あいついで","meaning":"liên tiếp, nối tiếp nhau","hanviet":"tương thứ","note":"Hay đi với 起こる, 発表する, オープンする. Văn viết, tin tức.","example":"台風が相次いで日本に上陸した。","example_reading":"たいふうがあいついでにほんにじょうりくした。","example_meaning":"Các cơn bão liên tiếp đổ bộ vào Nhật Bản.","examples":[{"example":"台風が相次いで日本に上陸した。","example_reading":"たいふうがあいついでにほんにじょうりくした。","example_meaning":"Các cơn bão liên tiếp đổ bộ vào Nhật Bản."},{"example":"駅前に新しい店が相次いでオープンした。","example_reading":"えきまえにあたらしいみせがあいついでオープンした。","example_meaning":"Trước ga, các cửa hàng mới lần lượt khai trương."}],"level":"d1"},
{"word":"土壇場で","reading":"どたんばで","meaning":"vào phút chót","hanviet":"thổ đàn trường","antonym":"早めに（はやめに）: sớm / 前もって（まえもって）: trước","antonym_hanviet":"tảo / tiền","note":"Hay đi với 逆転する, 気が変わる, 失敗する.","example":"彼は土壇場で気が変わって、計画を中止した。","example_reading":"かれはどたんばできがかわって、けいかくをちゅうしした。","example_meaning":"Vào phút chót anh ấy đổi ý và hủy kế hoạch.","examples":[{"example":"彼は土壇場で気が変わって、計画を中止した。","example_reading":"かれはどたんばできがかわって、けいかくをちゅうしした。","example_meaning":"Vào phút chót anh ấy đổi ý và hủy kế hoạch."},{"example":"土壇場で逆転して、チームは優勝した。","example_reading":"どたんばでぎゃくてんして、チームはゆうしょうした。","example_meaning":"Lật ngược thế cờ vào phút chót, đội đã vô địch."}],"level":"d1"},
{"word":"矢継ぎ早に","reading":"やつぎばやに","meaning":"dồn dập, liên hồi","hanviet":"thỉ kế tảo","note":"Hay đi với 質問する, 指示する. Hết cái này đến cái khác rất nhanh.","example":"記者たちは、矢継ぎ早に質問を浴びせた。","example_reading":"きしゃたちは、やつぎばやにしつもんをあびせた。","example_meaning":"Các phóng viên dồn dập tung ra câu hỏi.","examples":[{"example":"記者たちは、矢継ぎ早に質問を浴びせた。","example_reading":"きしゃたちは、やつぎばやにしつもんをあびせた。","example_meaning":"Các phóng viên dồn dập tung ra câu hỏi."},{"example":"矢継ぎ早に指示を出され、頭が混乱した。","example_reading":"やつぎばやにしじをだされ、あたまがこんらんした。","example_meaning":"Bị giao việc dồn dập, đầu óc tôi rối bời."}],"level":"d1"},
{"word":"四六時中","reading":"しろくじちゅう","meaning":"suốt hai mươi bốn giờ","hanviet":"tứ lục thời trung","antonym":"たまに: thỉnh thoảng / 時々（ときどき）: đôi khi","antonym_hanviet":" / thời thời","note":"Hay đi với 考える, ～ている. Lúc nào cũng, không dứt.","example":"彼は四六時中、ゲームのことばかり考えている。","example_reading":"かれはしろくじちゅう、ゲームのことばかりかんがえている。","example_meaning":"Anh ta lúc nào cũng chỉ nghĩ đến game.","examples":[{"example":"彼は四六時中、ゲームのことばかり考えている。","example_reading":"かれはしろくじちゅう、ゲームのことばかりかんがえている。","example_meaning":"Anh ta lúc nào cũng chỉ nghĩ đến game."},{"example":"赤ちゃんが生まれてから、四六時中世話に追われている。","example_reading":"あかちゃんがうまれてから、しろくじちゅうせわにおわれている。","example_meaning":"Từ khi có em bé, tôi lúc nào cũng bận chăm sóc."}],"level":"d1"},
{"word":"順次","reading":"じゅんじ","meaning":"lần lượt, tuần tự","hanviet":"thuận thứ","antonym":"一斉に（いっせいに）: đồng loạt / 同時に（どうじに）: đồng thời","antonym_hanviet":"nhất tề / đồng thời","note":"Hay đi với 発表する, 公開する, 進める.","example":"合格者には、順次連絡いたします。","example_reading":"ごうかくしゃには、じゅんじれんらくいたします。","example_meaning":"Chúng tôi sẽ lần lượt liên lạc với người trúng tuyển.","examples":[{"example":"合格者には、順次連絡いたします。","example_reading":"ごうかくしゃには、じゅんじれんらくいたします。","example_meaning":"Chúng tôi sẽ lần lượt liên lạc với người trúng tuyển."},{"example":"新しい店舗は、順次オープンする予定だ。","example_reading":"あたらしいてんぽは、じゅんじオープンするよていだ。","example_meaning":"Các cửa hàng mới dự định sẽ lần lượt khai trương."}],"level":"d1"},
{"word":"じかに","reading":"じかに","meaning":"trực tiếp (chạm thẳng, không qua trung gian)","antonym":"間接的に（かんせつてきに）: gián tiếp","antonym_hanviet":"gian tiếp đích","note":"Hay đi với 触る, 聞く, 座る. Nhấn mạnh tiếp xúc thẳng.","example":"現地で、職人の話をじかに聞くことができた。","example_reading":"げんちで、しょくにんのはなしをじかにきくことができた。","example_meaning":"Tại chỗ, tôi đã được nghe trực tiếp câu chuyện của người thợ.","examples":[{"example":"現地で、職人の話をじかに聞くことができた。","example_reading":"げんちで、しょくにんのはなしをじかにきくことができた。","example_meaning":"Tại chỗ, tôi đã được nghe trực tiếp câu chuyện của người thợ."},{"example":"暑かったので、床にじかに座って休んだ。","example_reading":"あつかったので、ゆかにじかにすわってやすんだ。","example_meaning":"Vì nóng nên tôi ngồi nghỉ thẳng xuống sàn."}],"level":"d1"},
{"word":"前もって","reading":"まえもって","meaning":"trước, sẵn","hanviet":"tiền","antonym":"後から（あとから）: sau đó / 不意に（ふいに）: đột ngột / ふらっと: tình cờ","antonym_hanviet":"hậu / bất ý / ","note":"Đọc まえもって. Hay đi với 連絡する, 準備する, 予約する. Gần あらかじめ nhưng khẩu ngữ hơn.","example":"来られない場合は、前もって連絡してください。","example_reading":"こられないばあいは、まえもってれんらくしてください。","example_meaning":"Nếu không thể đến, hãy báo trước.","examples":[{"example":"来られない場合は、前もって連絡してください。","example_reading":"こられないばあいは、まえもってれんらくしてください。","example_meaning":"Nếu không thể đến, hãy báo trước."},{"example":"前もって予約しておけば、待たずに入れる。","example_reading":"まえもってよやくしておけば、またずにはいれる。","example_meaning":"Nếu đặt chỗ trước thì không cần chờ mà vào được."}],"level":"d1"},
{"word":"あらかじめ","reading":"あらかじめ","meaning":"trước, từ trước","antonym":"後から（あとから）: sau đó","antonym_hanviet":"hậu","note":"Chuẩn bị trước. Hay đi với ～ておく／お知らせ／連絡.","example":"欠席する場合は、あらかじめ連絡してください。","example_reading":"けっせきするばあいは、あらかじめれんらくしてください。","example_meaning":"Nếu vắng mặt thì hãy liên lạc trước.","examples":[{"example":"欠席する場合は、あらかじめ連絡してください。","example_reading":"けっせきするばあいは、あらかじめれんらくしてください。","example_meaning":"Nếu vắng mặt thì hãy liên lạc trước."},{"example":"面接で聞かれそうなことを、あらかじめ考えておいた。","example_reading":"めんせつできかれそうなことを、あらかじめかんがえておいた。","example_meaning":"Tôi đã nghĩ trước những câu có thể bị hỏi khi phỏng vấn."}],"level":"d1"},
{"word":"先般","reading":"せんぱん","meaning":"hôm trước, vừa rồi","hanviet":"tiên ban","note":"Văn viết, thư từ trang trọng.","example":"先般は、大変お世話になりました。","example_reading":"せんぱんは、たいへんおせわになりました。","example_meaning":"Hôm trước tôi đã được giúp đỡ rất nhiều.","examples":[{"example":"先般は、大変お世話になりました。","example_reading":"せんぱんは、たいへんおせわになりました。","example_meaning":"Hôm trước tôi đã được giúp đỡ rất nhiều."},{"example":"先般お送りした資料について、ご確認をお願いします。","example_reading":"せんぱんおおくりしたしりょうについて、ごかくにんをおねがいします。","example_meaning":"Xin hãy xác nhận tài liệu đã gửi hôm trước."}],"level":"d1"},
{"word":"先頃","reading":"さきごろ","meaning":"gần đây, hôm trước","hanviet":"tiên khoảnh","note":"Văn viết.","example":"先頃発表された調査によると、利用者は増えているそうだ。","example_reading":"さきごろはっぴょうされたちょうさによると、りようしゃはふえているそうだ。","example_meaning":"Theo khảo sát công bố gần đây, người dùng đang tăng.","examples":[{"example":"先頃発表された調査によると、利用者は増えているそうだ。","example_reading":"さきごろはっぴょうされたちょうさによると、りようしゃはふえているそうだ。","example_meaning":"Theo khảo sát công bố gần đây, người dùng đang tăng."},{"example":"先頃、新しい法律が成立した。","example_reading":"さきごろ、あたらしいほうりつがせいりつした。","example_meaning":"Gần đây một đạo luật mới đã được thông qua."}],"level":"d1"},
{"word":"久しく","reading":"ひさしく","meaning":"từ lâu, đã lâu","hanviet":"cửu","note":"Hay đi với ～ない. Văn viết.","example":"久しく故郷には帰っていない。","example_reading":"ひさしくこきょうにはかえっていない。","example_meaning":"Đã lâu tôi không về quê.","examples":[{"example":"久しく故郷には帰っていない。","example_reading":"ひさしくこきょうにはかえっていない。","example_meaning":"Đã lâu tôi không về quê."},{"example":"久しく会っていなかった友人から、連絡が来た。","example_reading":"ひさしくあっていなかったゆうじんから、れんらくがきた。","example_meaning":"Người bạn lâu ngày không gặp đã liên lạc với tôi."}],"level":"d1"},
{"word":"なおも","reading":"なおも","meaning":"vẫn còn, tiếp tục","note":"Văn viết. Tình trạng tiếp diễn dù có thay đổi.","example":"雨は、なおも降り続いている。","example_reading":"あめは、なおもふりつづいている。","example_meaning":"Mưa vẫn tiếp tục rơi.","examples":[{"example":"雨は、なおも降り続いている。","example_reading":"あめは、なおもふりつづいている。","example_meaning":"Mưa vẫn tiếp tục rơi."},{"example":"彼は倒れても、なおも走り続けようとした。","example_reading":"かれはたおれても、なおもはしりつづけようとした。","example_meaning":"Dù ngã xuống, anh ấy vẫn cố tiếp tục chạy."}],"level":"d1"},
{"word":"大層","reading":"たいそう","meaning":"rất, vô cùng; to tát","hanviet":"đại tằng","note":"Văn viết, hơi cổ. Dạng 大層な = quá to tát.","example":"彼の演奏は、大層素晴らしかった。","example_reading":"かれのえんそうは、たいそうすばらしかった。","example_meaning":"Buổi biểu diễn của anh ấy tuyệt vời vô cùng.","examples":[{"example":"彼の演奏は、大層素晴らしかった。","example_reading":"かれのえんそうは、たいそうすばらしかった。","example_meaning":"Buổi biểu diễn của anh ấy tuyệt vời vô cùng."},{"example":"大層なものではありませんが、お受け取りください。","example_reading":"たいそうなものではありませんが、おうけとりください。","example_meaning":"Chẳng phải thứ gì to tát, xin hãy nhận cho."}],"level":"d1"},
{"word":"即日","reading":"そくじつ","meaning":"ngay trong ngày","hanviet":"tức nhật","note":"Hay đi với 発送, 発表, 決まる.","example":"申し込めば、即日発送してもらえる。","example_reading":"もうしこめば、そくじつはっそうしてもらえる。","example_meaning":"Nếu đăng ký thì sẽ được gửi ngay trong ngày.","examples":[{"example":"申し込めば、即日発送してもらえる。","example_reading":"もうしこめば、そくじつはっそうしてもらえる。","example_meaning":"Nếu đăng ký thì sẽ được gửi ngay trong ngày."},{"example":"結果は、即日発表される。","example_reading":"けっかは、そくじつはっぴょうされる。","example_meaning":"Kết quả được công bố ngay trong ngày."}],"level":"d1"},
{"word":"遅くとも","reading":"おそくとも","meaning":"chậm nhất là","hanviet":"trì","note":"Đọc おそくとも. Hay đi với ～までに. Giới hạn thời gian muộn nhất.","antonym":"早くとも（はやくとも）: sớm nhất là / 早くても（はやくても）: sớm nhất thì","antonym_hanviet":"tảo / tảo","example":"遅くとも五時までには戻ります。","example_reading":"おそくともごじまでにはもどります。","example_meaning":"Chậm nhất là năm giờ tôi sẽ quay lại.","examples":[{"example":"遅くとも五時までには戻ります。","example_reading":"おそくともごじまでにはもどります。","example_meaning":"Chậm nhất là năm giờ tôi sẽ quay lại."},{"example":"遅くとも来週中に返事をください。","example_reading":"おそくともらいしゅうちゅうにへんじをください。","example_meaning":"Chậm nhất trong tuần sau xin hãy trả lời."}],"level":"d1"},
{"word":"当面","reading":"とうめん","meaning":"trước mắt, tạm thời","hanviet":"đương diện","antonym":"長期的に（ちょうきてきに）: về lâu dài","antonym_hanviet":"trưởng kỳ đích","note":"Trong thời gian sắp tới. Văn viết, công việc. Hay đi với ～は／～の間.","example":"当面は、今の仕事を続けるつもりです。","example_reading":"とうめんは、いまのしごとをつづけるつもりです。","example_meaning":"Trước mắt tôi định tiếp tục công việc hiện tại.","examples":[{"example":"当面は、今の仕事を続けるつもりです。","example_reading":"とうめんは、いまのしごとをつづけるつもりです。","example_meaning":"Trước mắt tôi định tiếp tục công việc hiện tại."},{"example":"工事のため、この道は当面通行止めになります。","example_reading":"こうじのため、このみちはとうめんつうこうどめになります。","example_meaning":"Do thi công, đường này tạm thời bị cấm lưu thông."}],"level":"d1"},
{"word":"後ほど","reading":"のちほど","meaning":"lát nữa, sau đây","hanviet":"hậu","note":"Trang trọng, hứa sẽ làm hoặc liên lạc sau. Hay dùng trong kinh doanh: 後ほどご連絡いたします.","antonym":"直ちに（ただちに）: ngay tức khắc / さっき: lúc nãy / 今しがた（いましがた）: vừa mới","antonym_hanviet":"trực /  / kim","example":"詳細につきましては、後ほどご連絡いたします。","example_reading":"しょうさいにつきましては、のちほどごれんらくいたします。","example_meaning":"Về chi tiết, chúng tôi sẽ liên lạc sau.","examples":[{"example":"詳細につきましては、後ほどご連絡いたします。","example_reading":"しょうさいにつきましては、のちほどごれんらくいたします。","example_meaning":"Về chi tiết, chúng tôi sẽ liên lạc sau."},{"example":"担当の者が、後ほどご説明に伺います。","example_reading":"たんとうのものが、のちほどごせつめいにうかがいます。","example_meaning":"Người phụ trách sẽ đến giải thích sau."}],"level":"d1"},
{"word":"大幅に","reading":"おおはばに","meaning":"đáng kể, với biên độ lớn","hanviet":"đại bức","antonym":"わずかに: chỉ một chút / 多少（たしょう）: Ít nhiều / 若干（じゃっかん）: một chút","antonym_hanviet":" / đa thiểu / nhược can","note":"Con số thay đổi lớn. Hay đi với 値上がり, 減少, 遅れる. Hay gặp trong báo chí.","example":"原材料の高騰で、商品が大幅に値上がりした。","example_reading":"げんざいりょうのこうとうで、しょうひんがおおはばにねあがりした。","example_meaning":"Do nguyên liệu tăng giá, hàng hóa tăng giá đáng kể.","examples":[{"example":"原材料の高騰で、商品が大幅に値上がりした。","example_reading":"げんざいりょうのこうとうで、しょうひんがおおはばにねあがりした。","example_meaning":"Do nguyên liệu tăng giá, hàng hóa tăng giá đáng kể."},{"example":"雪のため、電車は大幅に遅れている。","example_reading":"ゆきのため、でんしゃはおおはばにおくれている。","example_meaning":"Vì tuyết, tàu điện đang chậm rất nhiều."}],"level":"d1"},
{"word":"常々","reading":"つねづね","meaning":"luôn luôn, thường ngày","hanviet":"thường","antonym":"たまに: thỉnh thoảng","note":"Hay đi với 思う, 言う, 感じる. Văn viết, trang trọng.","example":"親の苦労を、常々ありがたく思っています。","example_reading":"おやのくろうを、つねづねありがたくおもっています。","example_meaning":"Tôi luôn biết ơn sự vất vả của cha mẹ.","examples":[{"example":"親の苦労を、常々ありがたく思っています。","example_reading":"おやのくろうを、つねづねありがたくおもっています。","example_meaning":"Tôi luôn biết ơn sự vất vả của cha mẹ."},{"example":"先生は常々、基礎が大切だと言っていた。","example_reading":"せんせいはつねづね、きそがたいせつだといっていた。","example_meaning":"Thầy luôn nói rằng nền tảng cơ bản là quan trọng."}],"level":"d1"},
{"word":"適宜","reading":"てきぎ","meaning":"tùy thời, thích hợp","hanviet":"thích nghi","note":"Văn bản hành chính. Hay đi với 休憩する, 判断する, 対応する.","example":"作業中は、適宜休憩を取ってください。","example_reading":"さぎょうちゅうは、てきぎきゅうけいをとってください。","example_meaning":"Trong lúc làm việc, xin hãy nghỉ giải lao khi cần.","examples":[{"example":"作業中は、適宜休憩を取ってください。","example_reading":"さぎょうちゅうは、てきぎきゅうけいをとってください。","example_meaning":"Trong lúc làm việc, xin hãy nghỉ giải lao khi cần."},{"example":"状況に応じて、適宜対応をお願いします。","example_reading":"じょうきょうにおうじて、てきぎたいおうをおねがいします。","example_meaning":"Xin hãy ứng phó thích hợp tùy theo tình hình."}],"level":"d1"},
{"word":"逐一","reading":"ちくいち","meaning":"từng chút một, từng li từng tí","hanviet":"trục nhất","antonym":"大まかに（おおまかに）: đại khái / ざっと: sơ qua","antonym_hanviet":"đại / ","note":"Hay đi với 報告する, 確認する, 説明する.","example":"進み具合は、逐一報告してください。","example_reading":"すすみぐあいは、ちくいちほうこくしてください。","example_meaning":"Tình hình tiến độ xin hãy báo cáo chi tiết từng bước.","examples":[{"example":"進み具合は、逐一報告してください。","example_reading":"すすみぐあいは、ちくいちほうこくしてください。","example_meaning":"Tình hình tiến độ xin hãy báo cáo chi tiết từng bước."},{"example":"彼は私の行動を逐一チェックしている。","example_reading":"かれはわたしのこうどうをちくいちチェックしている。","example_meaning":"Anh ta kiểm tra từng hành động của tôi."}],"level":"d1"},
{"word":"至極","reading":"しごく","meaning":"cực kỳ, hết sức","hanviet":"chí cực","note":"Hay đi với 当然, 残念, 結構. Văn viết.","example":"彼が怒るのは至極当然のことだ。","example_reading":"かれがおこるのはしごくとうぜんのことだ。","example_meaning":"Anh ấy tức giận là điều hết sức hiển nhiên.","examples":[{"example":"彼が怒るのは至極当然のことだ。","example_reading":"かれがおこるのはしごくとうぜんのことだ。","example_meaning":"Anh ấy tức giận là điều hết sức hiển nhiên."},{"example":"子どもたちは、至極満足そうな顔をしていた。","example_reading":"こどもたちは、しごくまんぞくそうなかおをしていた。","example_meaning":"Bọn trẻ có vẻ mặt vô cùng hài lòng."}],"level":"d1"},
{"word":"重ねて","reading":"かさねて","meaning":"một lần nữa, lặp lại","hanviet":"trọng","note":"Hay đi với お願いする, お詫びする, お礼を言う. Trang trọng.","example":"重ねてお詫び申し上げます。","example_reading":"かさねておわびもうしあげます。","example_meaning":"Tôi xin một lần nữa gửi lời xin lỗi.","examples":[{"example":"重ねてお詫び申し上げます。","example_reading":"かさねておわびもうしあげます。","example_meaning":"Tôi xin một lần nữa gửi lời xin lỗi."},{"example":"彼女は先生に、重ねてお礼を述べた。","example_reading":"かのじょはせんせいに、かさねておれいをのべた。","example_meaning":"Cô ấy lại một lần nữa gửi lời cảm ơn đến thầy."}],"level":"d1"},
{"word":"後々","reading":"あとあと","meaning":"về sau, sau này","hanviet":"hậu hậu","note":"Hay đi với 困る, 響く, ～まで.","example":"今ちゃんと準備しておかないと、後々困ることになる。","example_reading":"いまちゃんとじゅんびしておかないと、あとあとこまることになる。","example_meaning":"Bây giờ không chuẩn bị cho kỹ thì sau này sẽ gặp rắc rối.","examples":[{"example":"今ちゃんと準備しておかないと、後々困ることになる。","example_reading":"いまちゃんとじゅんびしておかないと、あとあとこまることになる。","example_meaning":"Bây giờ không chuẩn bị cho kỹ thì sau này sẽ gặp rắc rối."},{"example":"この決断は、後々まで影響を残すだろう。","example_reading":"このけつだんは、あとあとまでえいきょうをのこすだろう。","example_meaning":"Quyết định này có lẽ sẽ để lại ảnh hưởng về lâu về dài."}],"level":"d1"},
{"word":"一足先に","reading":"ひとあしさきに","meaning":"đi trước một bước","hanviet":"nhất túc tiên","antonym":"一足遅れて（ひとあしおくれて）: chậm một bước","antonym_hanviet":"nhất túc trì","note":"Hay dùng khi xin phép về trước; làm trước người khác một chút.","example":"用事があるので、一足先に失礼します。","example_reading":"ようじがあるので、ひとあしさきにしつれいします。","example_meaning":"Tôi có việc nên xin phép đi trước một bước.","examples":[{"example":"用事があるので、一足先に失礼します。","example_reading":"ようじがあるので、ひとあしさきにしつれいします。","example_meaning":"Tôi có việc nên xin phép đi trước một bước."},{"example":"兄は私より一足先に社会人になった。","example_reading":"あにはわたしよりひとあしさきにしゃかいじんになった。","example_meaning":"Anh trai tôi đi làm sớm hơn tôi một bước."}],"level":"d1"},
{"word":"一律に","reading":"いちりつに","meaning":"đồng loạt, như nhau","hanviet":"nhất luật","antonym":"個別に（こべつに）: riêng từng cái / 差をつけて（さをつけて）: phân biệt","antonym_hanviet":"cá biệt / sai","note":"Hay đi với 扱う, 支給する, 決める. Áp dụng như nhau, không phân biệt.","example":"全員に一律に五千円が支給された。","example_reading":"ぜんいんにいちりつにごせんえんがしきゅうされた。","example_meaning":"Tất cả mọi người đều được cấp đồng loạt 5000 yên.","examples":[{"example":"全員に一律に五千円が支給された。","example_reading":"ぜんいんにいちりつにごせんえんがしきゅうされた。","example_meaning":"Tất cả mọi người đều được cấp đồng loạt 5000 yên."},{"example":"子どもを一律に扱うのではなく、個性を見るべきだ。","example_reading":"こどもをいちりつにあつかうのではなく、こせいをみるべきだ。","example_meaning":"Không nên đối xử với trẻ như nhau mà phải xem cá tính."}],"level":"d1"},
{"word":"長らく","reading":"ながらく","meaning":"từ lâu, lâu nay","hanviet":"trường","antonym":"短い間（みじかいあいだ）: một lúc ngắn / 最近（さいきん）: dạo gần đây","antonym_hanviet":"đoản gian / tối cận","note":"Đọc ながらく. Hay đi với お待たせしました, 続く. Trang trọng, chỉ thời gian dài.","example":"長らくお待たせして申し訳ありません。","example_reading":"ながらくおまたせしてもうしわけありません。","example_meaning":"Xin lỗi vì đã để quý khách chờ lâu.","examples":[{"example":"長らくお待たせして申し訳ありません。","example_reading":"ながらくおまたせしてもうしわけありません。","example_meaning":"Xin lỗi vì đã để quý khách chờ lâu."},{"example":"この店は、長らく地域の人に愛されてきた。","example_reading":"このみせは、ながらくちいきのひとにあいされてきた。","example_meaning":"Quán này từ lâu đã được người dân địa phương yêu mến."}],"level":"d1"},
{"word":"日々","reading":"ひび","meaning":"ngày ngày, hằng ngày","hanviet":"nhật nhật","note":"Đọc ひび. Hay đi với 努力する, 変化する, 過ごす. Văn viết, diễn tả từng ngày nối tiếp.","example":"日々の努力が、やがて結果につながる。","example_reading":"ひびのどりょくが、やがてけっかにつながる。","example_meaning":"Nỗ lực mỗi ngày rồi sẽ dẫn đến kết quả.","examples":[{"example":"日々の努力が、やがて結果につながる。","example_reading":"ひびのどりょくが、やがてけっかにつながる。","example_meaning":"Nỗ lực mỗi ngày rồi sẽ dẫn đến kết quả."},{"example":"技術は日々進歩している。","example_reading":"ぎじゅつはひびしんぽしている。","example_meaning":"Công nghệ tiến bộ từng ngày."}],"level":"d1"},
{"word":"絶えず","reading":"たえず","meaning":"không ngừng, liên tục","hanviet":"tuyệt","antonym":"たまに: thỉnh thoảng","note":"Không gián đoạn. Văn viết. Hay đi với ～ている／変化する.","example":"技術は絶えず進歩している。","example_reading":"ぎじゅつはたえずしんぽしている。","example_meaning":"Công nghệ không ngừng tiến bộ.","examples":[{"example":"技術は絶えず進歩している。","example_reading":"ぎじゅつはたえずしんぽしている。","example_meaning":"Công nghệ không ngừng tiến bộ."},{"example":"母は絶えず私の健康を気にかけてくれる。","example_reading":"はははたえずわたしのけんこうをきにかけてくれる。","example_meaning":"Mẹ lúc nào cũng quan tâm đến sức khỏe của tôi."}],"level":"d1"},
{"word":"しょっちゅう","reading":"しょっちゅう","meaning":"luôn luôn, hoài","note":"Khẩu ngữ, tần suất cao, thường hơi phàn nàn.","antonym":"めったに: hiếm khi","example":"弟はしょっちゅう携帯電話をなくす。","example_reading":"おとうとはしょっちゅうけいたいでんわをなくす。","example_meaning":"Em trai tôi hoài làm mất điện thoại.","examples":[{"example":"弟はしょっちゅう携帯電話をなくす。","example_reading":"おとうとはしょっちゅうけいたいでんわをなくす。","example_meaning":"Em trai tôi hoài làm mất điện thoại."},{"example":"あの二人は、しょっちゅうけんかをしている。","example_reading":"あのふたりは、しょっちゅうけんかをしている。","example_meaning":"Hai người đó lúc nào cũng cãi nhau."}],"level":"d1"},
{"word":"極めて","reading":"きわめて","meaning":"cực kỳ, vô cùng","hanviet":"cực","antonym":"少し（すこし）: một ít","antonym_hanviet":"thiểu","note":"Trang trọng, văn viết. Hay đi với 重要, 困難, 残念, 珍しい.","example":"これは極めて重要な問題です。","example_reading":"これはきわめてじゅうようなもんだいです。","example_meaning":"Đây là vấn đề cực kỳ quan trọng.","examples":[{"example":"これは極めて重要な問題です。","example_reading":"これはきわめてじゅうようなもんだいです。","example_meaning":"Đây là vấn đề cực kỳ quan trọng."},{"example":"その鳥は、日本では極めて珍しい。","example_reading":"そのとりは、にほんではきわめてめずらしい。","example_meaning":"Loài chim đó ở Nhật cực kỳ hiếm."}],"level":"d1"},
{"word":"継続的に","reading":"けいぞくてきに","meaning":"một cách liên tục, bền bỉ","hanviet":"kế tục đích","antonym":"断続的に（だんぞくてきに）: gián đoạn / 一時的に（いちじてきに）: tạm thời","antonym_hanviet":"đoạn tục đích / nhất thời đích","note":"Hay đi với 勉強する, 支援する, 行う.","example":"語学は継続的に勉強しないと、すぐに忘れてしまう。","example_reading":"ごがくはけいぞくてきにべんきょうしないと、すぐにわすれてしまう。","example_meaning":"Ngoại ngữ không học đều đặn thì quên ngay.","examples":[{"example":"語学は継続的に勉強しないと、すぐに忘れてしまう。","example_reading":"ごがくはけいぞくてきにべんきょうしないと、すぐにわすれてしまう。","example_meaning":"Ngoại ngữ không học đều đặn thì quên ngay."},{"example":"会社は被災地を継続的に支援している。","example_reading":"かいしゃはひさいちをけいぞくてきにしえんしている。","example_meaning":"Công ty hỗ trợ liên tục cho vùng bị thiên tai."}],"level":"d1"},
{"word":"均等に","reading":"きんとうに","meaning":"đồng đều, chia đều","hanviet":"quân đẳng","antonym":"不均等に（ふきんとうに）: không đều / 偏って（かたよって）: lệch / 重点的に（じゅうてんてきに）: có trọng tâm","antonym_hanviet":"bất quân đẳng / thiên / trọng điểm đích","note":"Hay đi với 分ける, かける, 配る.","example":"ケーキを四人で均等に分けた。","example_reading":"ケーキをよにんできんとうにわけた。","example_meaning":"Bốn người chia đều chiếc bánh.","examples":[{"example":"ケーキを四人で均等に分けた。","example_reading":"ケーキをよにんできんとうにわけた。","example_meaning":"Bốn người chia đều chiếc bánh."},{"example":"体重を両足に均等にかけて、まっすぐ立つ。","example_reading":"たいじゅうをりょうあしにきんとうにかけて、まっすぐたつ。","example_meaning":"Dồn trọng lượng đều lên hai chân và đứng thẳng."}],"level":"d1"},
{"word":"実に","reading":"じつに","meaning":"thật là, quả thực","hanviet":"thực","note":"Cảm thán, nhấn mạnh cảm nhận. Văn viết hoặc nói trang trọng. Hay đi với 面白い, すばらしい.","example":"この小説は実に面白かった。","example_reading":"このしょうせつはじつにおもしろかった。","example_meaning":"Cuốn tiểu thuyết này thật sự rất hay.","examples":[{"example":"この小説は実に面白かった。","example_reading":"このしょうせつはじつにおもしろかった。","example_meaning":"Cuốn tiểu thuyết này thật sự rất hay."},{"example":"十年ぶりの再会は、実に感慨深いものだった。","example_reading":"じゅうねんぶりのさいかいは、じつにかんがいふかいものだった。","example_meaning":"Cuộc gặp lại sau mười năm thật sự đầy xúc động."}],"level":"d1"},
{"word":"ひたすら","reading":"ひたすら","meaning":"chỉ một mực, miệt mài","note":"Hay đi với 走る, 謝る, 待つ, 練習する. Tập trung hoàn toàn vào một việc.","example":"彼は試験に向けて、ひたすら勉強を続けた。","example_reading":"かれはしけんにむけて、ひたすらべんきょうをつづけた。","example_meaning":"Anh ấy một mực học để chuẩn bị cho kỳ thi.","examples":[{"example":"彼は試験に向けて、ひたすら勉強を続けた。","example_reading":"かれはしけんにむけて、ひたすらべんきょうをつづけた。","example_meaning":"Anh ấy một mực học để chuẩn bị cho kỳ thi."},{"example":"ひたすら謝ったが、彼女は許してくれなかった。","example_reading":"ひたすらあやまったが、かのじょはゆるしてくれなかった。","example_meaning":"Tôi chỉ biết xin lỗi một mực nhưng cô ấy không tha thứ."}],"level":"d1"},
{"word":"著しく","reading":"いちじるしく","meaning":"rõ rệt, đáng kể","hanviet":"trứ","antonym":"わずかに: một chút ít","note":"Thay đổi rõ ràng. Hay đi với 増加, 低下, 変化, 進歩. Văn viết.","example":"最近、この地域の人口は著しく増加している。","example_reading":"さいきん、このちいきのじんこうはいちじるしくぞうかしている。","example_meaning":"Gần đây dân số khu vực này tăng rõ rệt.","examples":[{"example":"最近、この地域の人口は著しく増加している。","example_reading":"さいきん、このちいきのじんこうはいちじるしくぞうかしている。","example_meaning":"Gần đây dân số khu vực này tăng rõ rệt."},{"example":"運動不足で、体力が著しく低下した。","example_reading":"うんどうふそくで、たいりょくがいちじるしくていかした。","example_meaning":"Do thiếu vận động, thể lực giảm sút rõ rệt."}],"level":"d1"},
{"word":"圧倒的に","reading":"あっとうてきに","meaning":"áp đảo, vượt trội hẳn","hanviet":"áp đảo đích","antonym":"わずかに: một chút ít","note":"So sánh số lượng hoặc chất lượng chênh lệch lớn.","example":"若い世代では、スマホを使う人が圧倒的に多い。","example_reading":"わかいせだいでは、スマホをつかうひとがあっとうてきにおおい。","example_meaning":"Ở thế hệ trẻ, số người dùng điện thoại thông minh áp đảo.","examples":[{"example":"若い世代では、スマホを使う人が圧倒的に多い。","example_reading":"わかいせだいでは、スマホをつかうひとがあっとうてきにおおい。","example_meaning":"Ở thế hệ trẻ, số người dùng điện thoại thông minh áp đảo."},{"example":"決勝戦は、相手が圧倒的に有利だった。","example_reading":"けっしょうせんは、あいてがあっとうてきにゆうりだった。","example_meaning":"Trận chung kết, đối thủ chiếm ưu thế áp đảo."}],"level":"d1"},
{"word":"格段に","reading":"かくだんに","meaning":"vượt bậc, hơn hẳn","hanviet":"cách đoạn","antonym":"わずかに: một chút ít","note":"Khác biệt hoặc tiến bộ rõ rệt so với trước. Hay đi với よくなる, 進歩する, 向上する.","example":"新しいシステムのおかげで、作業の効率が格段によくなった。","example_reading":"あたらしいシステムのおかげで、さぎょうのこうりつがかくだんによくなった。","example_meaning":"Nhờ hệ thống mới, hiệu suất công việc tốt lên vượt bậc.","examples":[{"example":"新しいシステムのおかげで、作業の効率が格段によくなった。","example_reading":"あたらしいシステムのおかげで、さぎょうのこうりつがかくだんによくなった。","example_meaning":"Nhờ hệ thống mới, hiệu suất công việc tốt lên vượt bậc."},{"example":"彼女の日本語は、一年で格段に上達した。","example_reading":"かのじょのにほんごは、いちねんでかくだんにじょうたつした。","example_meaning":"Tiếng Nhật của cô ấy tiến bộ vượt bậc trong một năm."}],"level":"d1"},
{"word":"たちまち","reading":"たちまち","meaning":"chỉ trong chốc lát, thoắt cái","antonym":"ゆっくり: chậm rãi","note":"Biến đổi cực nhanh. Hay đi với 広がる, 売り切れる, 消える.","example":"噂はたちまち町中に広まった。","example_reading":"うわさはたちまちまちじゅうにひろまった。","example_meaning":"Tin đồn lan khắp thị trấn chỉ trong chốc lát.","examples":[{"example":"噂はたちまち町中に広まった。","example_reading":"うわさはたちまちまちじゅうにひろまった。","example_meaning":"Tin đồn lan khắp thị trấn chỉ trong chốc lát."},{"example":"新商品は、発売日にたちまち売り切れた。","example_reading":"しんしょうひんは、はつばいひにたちまちうりきれた。","example_meaning":"Sản phẩm mới bán hết veo ngay trong ngày phát hành."}],"level":"d1"},
{"word":"少なからず","reading":"すくなからず","meaning":"không ít","hanviet":"thiểu","note":"Văn viết. Hay đi với 影響を与える, 驚く, 心配する.","example":"その事件は、社会に少なからず影響を与えた。","example_reading":"そのじけんは、しゃかいにすくなからずえいきょうをあたえた。","example_meaning":"Vụ việc đó đã ảnh hưởng không ít đến xã hội.","examples":[{"example":"その事件は、社会に少なからず影響を与えた。","example_reading":"そのじけんは、しゃかいにすくなからずえいきょうをあたえた。","example_meaning":"Vụ việc đó đã ảnh hưởng không ít đến xã hội."},{"example":"彼の発言に、少なからず驚いた。","example_reading":"かれのはつげんに、すくなからずおどろいた。","example_meaning":"Tôi khá ngạc nhiên trước phát ngôn của anh ấy."}],"level":"d1"},
{"word":"一様に","reading":"いちように","meaning":"đồng nhất, giống nhau","hanviet":"nhất dạng","antonym":"様々に（さまざまに）: đa dạng / 異なって（ことなって）: khác nhau","antonym_hanviet":"dạng dạng / dị","note":"Hay đi với 暗い, 喜ぶ, 驚く. Cũng hay đi với phủ định ～ない (không thể đồng nhất).","example":"試合に負けて、選手たちは一様に暗い表情だった。","example_reading":"しあいにまけて、せんしゅたちはいちようにくらいひょうじょうだった。","example_meaning":"Thua trận, các cầu thủ đều có vẻ mặt u ám như nhau.","examples":[{"example":"試合に負けて、選手たちは一様に暗い表情だった。","example_reading":"しあいにまけて、せんしゅたちはいちようにくらいひょうじょうだった。","example_meaning":"Thua trận, các cầu thủ đều có vẻ mặt u ám như nhau."},{"example":"人の好みは一様に決められるものではない。","example_reading":"ひとのこのみはいちようにきめられるものではない。","example_meaning":"Sở thích của mỗi người không thể định ra giống nhau được."}],"level":"d1"},
{"word":"時には","reading":"ときには","meaning":"thỉnh thoảng, đôi khi","hanviet":"thời","antonym":"常に（つねに）: luôn luôn / いつも: luôn luôn","antonym_hanviet":"thường / ","note":"Đọc ときには. Hay đi với ～も大切だ, ～ことがある. Gần 時々 nhưng nhấn mạnh 'cũng có lúc'.","example":"時には、仕事を忘れてゆっくり休むことも大切だ。","example_reading":"ときには、しごとをわすれてゆっくりやすむこともたいせつだ。","example_meaning":"Thỉnh thoảng quên công việc và nghỉ ngơi thong thả cũng quan trọng.","examples":[{"example":"時には、仕事を忘れてゆっくり休むことも大切だ。","example_reading":"ときには、しごとをわすれてゆっくりやすむこともたいせつだ。","example_meaning":"Thỉnh thoảng quên công việc và nghỉ ngơi thong thả cũng quan trọng."},{"example":"いつも優しい彼も、時には厳しいことを言う。","example_reading":"いつもやさしいかれも、ときにはきびしいことをいう。","example_meaning":"Anh ấy lúc nào cũng hiền nhưng đôi khi cũng nói lời nghiêm khắc."}],"level":"d1"},
{"word":"時折","reading":"ときおり","meaning":"đôi khi, thỉnh thoảng","hanviet":"thời chiết","antonym":"常に（つねに）: luôn luôn","antonym_hanviet":"thường","note":"Văn viết hơn 時々. Hay đi với 見せる, 聞こえる.","example":"時折、遠くから犬の鳴き声が聞こえてきた。","example_reading":"ときおり、とおくからいぬのなきごえがきこえてきた。","example_meaning":"Thỉnh thoảng từ xa vọng lại tiếng chó sủa.","examples":[{"example":"時折、遠くから犬の鳴き声が聞こえてきた。","example_reading":"ときおり、とおくからいぬのなきごえがきこえてきた。","example_meaning":"Thỉnh thoảng từ xa vọng lại tiếng chó sủa."},{"example":"彼女は時折、寂しそうな表情を見せた。","example_reading":"かのじょはときおり、さびしそうなひょうじょうをみせた。","example_meaning":"Thỉnh thoảng cô ấy lộ vẻ cô đơn."}],"level":"d1"},
{"word":"時々","reading":"ときどき","meaning":"thỉnh thoảng","hanviet":"thời thời","antonym":"いつも: luôn luôn / 四六時中（しろくじちゅう）: suốt hai mươi bốn giờ","antonym_hanviet":" / tứ lục thời trung","note":"Tần suất vừa phải.","example":"休みの日は、時々友達と映画を見に行きます。","example_reading":"やすみのひは、ときどきともだちとえいがをみにいきます。","example_meaning":"Ngày nghỉ, thỉnh thoảng tôi đi xem phim với bạn.","examples":[{"example":"休みの日は、時々友達と映画を見に行きます。","example_reading":"やすみのひは、ときどきともだちとえいがをみにいきます。","example_meaning":"Ngày nghỉ, thỉnh thoảng tôi đi xem phim với bạn."},{"example":"時々、昔の夢を見ることがある。","example_reading":"ときどき、むかしのゆめをみることがある。","example_meaning":"Thỉnh thoảng tôi mơ thấy chuyện ngày xưa."}],"level":"d1"},
{"word":"たまに","reading":"たまに","meaning":"hiếm hoi mới, thỉnh thoảng","antonym":"頻繁に（ひんぱんに）: thường xuyên / 常に（つねに）: luôn luôn / 絶えず（たえず）: không ngừng","antonym_hanviet":"tần phồn / thường / tuyệt","note":"Tần suất thấp. Khẩu ngữ. Hay đi với ～と／～ならいい.","example":"たまに外食するのも楽しいものだ。","example_reading":"たまにがいしょくするのもたのしいものだ。","example_meaning":"Thỉnh thoảng đi ăn ngoài cũng vui.","examples":[{"example":"たまに外食するのも楽しいものだ。","example_reading":"たまにがいしょくするのもたのしいものだ。","example_meaning":"Thỉnh thoảng đi ăn ngoài cũng vui."},{"example":"普段は料理をしないが、たまに作ると楽しい。","example_reading":"ふだんはりょうりをしないが、たまにつくるとたのしい。","example_meaning":"Bình thường tôi không nấu ăn nhưng thỉnh thoảng nấu thì thấy vui."}],"level":"d1"},
{"word":"わずかに","reading":"わずかに","meaning":"chỉ một chút, ít ỏi","antonym":"大幅に（おおはばに）: đáng kể / たっぷり: Đầy đặn / 非常に（ひじょうに）: cực kỳ","antonym_hanviet":"đại bức /  / phi thường","note":"Số lượng hoặc mức độ rất nhỏ. Hay đi với 残る, 違う, 動く.","example":"財布にはわずかに千円しか残っていなかった。","example_reading":"さいふにはわずかにせんえんしかのこっていなかった。","example_meaning":"Trong ví chỉ còn lại vỏn vẹn một nghìn yên.","examples":[{"example":"財布にはわずかに千円しか残っていなかった。","example_reading":"さいふにはわずかにせんえんしかのこっていなかった。","example_meaning":"Trong ví chỉ còn lại vỏn vẹn một nghìn yên."},{"example":"地面がわずかに揺れたような気がした。","example_reading":"じめんがわずかにゆれたようなきがした。","example_meaning":"Tôi có cảm giác mặt đất rung nhẹ một chút."}],"level":"d1"},
{"word":"かねて","reading":"かねて","meaning":"từ trước","note":"Hay đi với かねてより／かねてから. Trang trọng.","example":"かねてから計画していた旅行に、ようやく出発した。","example_reading":"かねてからけいかくしていたりょこうに、ようやくしゅっぱつした。","example_meaning":"Cuối cùng tôi cũng lên đường chuyến du lịch đã lên kế hoạch từ lâu.","examples":[{"example":"かねてから計画していた旅行に、ようやく出発した。","example_reading":"かねてからけいかくしていたりょこうに、ようやくしゅっぱつした。","example_meaning":"Cuối cùng tôi cũng lên đường chuyến du lịch đã lên kế hoạch từ lâu."},{"example":"社長はかねてより海外進出を考えていた。","example_reading":"しゃちょうはかねてよりかいがいしんしゅつをかんがえていた。","example_meaning":"Giám đốc từ trước đã nghĩ đến việc mở rộng ra nước ngoài."}],"level":"d1"},
{"word":"一時的に","reading":"いちじてきに","meaning":"một cách tạm thời","hanviet":"nhất thời đích","note":"Đọc いちじてきに. Hay đi với 止まる, 休む, 借りる. Chỉ trong thời gian ngắn.","antonym":"継続的に（けいぞくてきに）: liên tục / 持続的に（じぞくてきに）: bền vững / いつまでも: mãi mãi","antonym_hanviet":"kế tục đích / trì tục đích / ","example":"工事のため、道が一時的に通れなくなる。","example_reading":"こうじのため、みちがいちじてきにとおれなくなる。","example_meaning":"Do thi công, đường tạm thời không đi được.","examples":[{"example":"工事のため、道が一時的に通れなくなる。","example_reading":"こうじのため、みちがいちじてきにとおれなくなる。","example_meaning":"Do thi công, đường tạm thời không đi được."},{"example":"この薬で、痛みを一時的に抑えることができる。","example_reading":"このくすりで、いたみをいちじてきにおさえることができる。","example_meaning":"Thuốc này có thể tạm thời giảm cơn đau."}],"level":"d1"},
{"word":"極端に","reading":"きょくたんに","meaning":"cực đoan, quá mức","hanviet":"cực đoan","note":"Mức độ lệch hẳn về một phía (thường tiêu cực).","antonym":"適度に（てきどに）: vừa phải","antonym_hanviet":"thích độ","example":"彼は極端に人見知りで、初対面の人とは話せない。","example_reading":"かれはきょくたんにひとみしりで、はつたいめんのひととははなせない。","example_meaning":"Anh ấy cực kỳ nhút nhát, không nói chuyện được với người mới gặp.","examples":[{"example":"彼は極端に人見知りで、初対面の人とは話せない。","example_reading":"かれはきょくたんにひとみしりで、はつたいめんのひととははなせない。","example_meaning":"Anh ấy cực kỳ nhút nhát, không nói chuyện được với người mới gặp."},{"example":"ダイエットのために、極端に食事を減らすのは危険だ。","example_reading":"ダイエットのために、きょくたんにしょくじをへらすのはきけんだ。","example_meaning":"Giảm ăn quá mức để giảm cân là nguy hiểm."}],"level":"d1"},
{"word":"一段と","reading":"いちだんと","meaning":"hơn hẳn một bậc, càng thêm","hanviet":"nhất đoạn","note":"Mức độ tăng lên một cấp so với trước. Hay đi với 寒さ, 美しい, 強まる.","example":"十二月に入ってから、寒さが一段と厳しくなった。","example_reading":"じゅうにがつにはいってから、さむさがいちだんときびしくなった。","example_meaning":"Từ khi sang tháng Mười hai, cái lạnh càng khắc nghiệt hơn.","examples":[{"example":"十二月に入ってから、寒さが一段と厳しくなった。","example_reading":"じゅうにがつにはいってから、さむさがいちだんときびしくなった。","example_meaning":"Từ khi sang tháng Mười hai, cái lạnh càng khắc nghiệt hơn."},{"example":"着物姿の彼女は、一段と美しく見えた。","example_reading":"きものすがたのかのじょは、いちだんとうつくしくみえた。","example_meaning":"Cô ấy trong bộ kimono trông đẹp hơn hẳn."}],"level":"d1"},
{"word":"今や","reading":"いまや","meaning":"giờ đây, bây giờ thì","hanviet":"kim","antonym":"かつて: từng, ngày trước","note":"Tình hình hiện tại đã khác hẳn trước. Văn viết. Hay đi với ～だ／～ている.","example":"スマートフォンは、今や生活に欠かせない道具だ。","example_reading":"スマートフォンは、いまやせいかつにかかせないどうぐだ。","example_meaning":"Điện thoại thông minh giờ đây đã là vật không thể thiếu trong cuộc sống.","examples":[{"example":"スマートフォンは、今や生活に欠かせない道具だ。","example_reading":"スマートフォンは、いまやせいかつにかかせないどうぐだ。","example_meaning":"Điện thoại thông minh giờ đây đã là vật không thể thiếu trong cuộc sống."},{"example":"彼は今や世界的に有名な歌手になった。","example_reading":"かれはいまやせかいてきにゆうめいなかしゅになった。","example_meaning":"Anh ấy giờ đã trở thành ca sĩ nổi tiếng thế giới."}],"level":"d1"},
{"word":"日頃","reading":"ひごろ","meaning":"thường ngày, bấy lâu nay","hanviet":"nhật khoảnh","note":"Đọc ひごろ. Hay đi với ～から, お世話になる, 心がける. Dùng nhiều trong lời cảm ơn.","example":"日頃から健康に気をつけています。","example_reading":"ひごろからけんこうにきをつけています。","example_meaning":"Thường ngày tôi vẫn chú ý đến sức khỏe.","examples":[{"example":"日頃から健康に気をつけています。","example_reading":"ひごろからけんこうにきをつけています。","example_meaning":"Thường ngày tôi vẫn chú ý đến sức khỏe."},{"example":"日頃の感謝を込めて、プレゼントを贈った。","example_reading":"ひごろのかんしゃをこめて、プレゼントをおくった。","example_meaning":"Tôi tặng quà để gửi gắm lòng biết ơn bấy lâu nay."}],"level":"d1"},
{"word":"再三","reading":"さいさん","meaning":"nhiều lần, lặp đi lặp lại","hanviet":"tái tam","antonym":"一度だけ（いちどだけ）: chỉ một lần","antonym_hanviet":"nhất độ","note":"Đã làm nhiều lần mà không hiệu quả. Hay đi với 注意, 忠告, 頼む.","example":"再三注意したのに、彼は遅刻をやめなかった。","example_reading":"さいさんちゅういしたのに、かれはちこくをやめなかった。","example_meaning":"Dù đã nhắc nhiều lần, anh ấy vẫn không bỏ thói đi muộn.","examples":[{"example":"再三注意したのに、彼は遅刻をやめなかった。","example_reading":"さいさんちゅういしたのに、かれはちこくをやめなかった。","example_meaning":"Dù đã nhắc nhiều lần, anh ấy vẫn không bỏ thói đi muộn."},{"example":"担当者に再三お願いしたが、返事はもらえなかった。","example_reading":"たんとうしゃにさいさんおねがいしたが、へんじはもらえなかった。","example_meaning":"Tôi đã nhờ người phụ trách nhiều lần nhưng không nhận được hồi âm."}],"level":"d1"},
{"word":"往々にして","reading":"おうおうにして","meaning":"thường hay, không hiếm khi","hanviet":"vãng vãng","antonym":"めったに: hiếm khi","note":"Việc dễ xảy ra (thường tiêu cực), mang tính quy luật. Hay đi với ～がちだ／～ことがある.","example":"慣れてきたときに、往々にしてミスは起きるものだ。","example_reading":"なれてきたときに、おうおうにしてミスはおきるものだ。","example_meaning":"Lỗi thường hay xảy ra vào lúc đã quen việc.","examples":[{"example":"慣れてきたときに、往々にしてミスは起きるものだ。","example_reading":"なれてきたときに、おうおうにしてミスはおきるものだ。","example_meaning":"Lỗi thường hay xảy ra vào lúc đã quen việc."},{"example":"初めての海外旅行では、往々にしてトラブルが起こる。","example_reading":"はじめてのかいがいりょこうでは、おうおうにしてトラブルがおこる。","example_meaning":"Chuyến du lịch nước ngoài đầu tiên thường hay xảy ra rắc rối."}],"level":"d1"},
{"word":"始終","reading":"しじゅう","meaning":"suốt, luôn luôn","hanviet":"thủy chung","antonym":"たまに: thỉnh thoảng","note":"Đọc しじゅう. Hay đi với ～ている. Thường kèm ý phàn nàn; gần しょっちゅう.","example":"うちの子は始終ゲームばかりしている。","example_reading":"うちのこはしじゅうゲームばかりしている。","example_meaning":"Con nhà tôi suốt ngày chỉ chơi game.","examples":[{"example":"うちの子は始終ゲームばかりしている。","example_reading":"うちのこはしじゅうゲームばかりしている。","example_meaning":"Con nhà tôi suốt ngày chỉ chơi game."},{"example":"あの部署は始終人が入れ替わっている。","example_reading":"あのぶしょはしじゅうひとがいれかわっている。","example_meaning":"Bộ phận đó người ra vào thay đổi liên tục."}],"level":"d1"},
{"word":"しきりに","reading":"しきりに","meaning":"liên tục, hối hả","antonym":"たまに: thỉnh thoảng","note":"Hành động lặp lại dồn dập. Hay đi với 話す, 勧める, 気にする.","example":"彼は先ほどから、しきりに時計を気にしている。","example_reading":"かれはさきほどから、しきりにとけいをきにしている。","example_meaning":"Từ nãy giờ anh ấy liên tục để ý đồng hồ.","examples":[{"example":"彼は先ほどから、しきりに時計を気にしている。","example_reading":"かれはさきほどから、しきりにとけいをきにしている。","example_meaning":"Từ nãy giờ anh ấy liên tục để ý đồng hồ."},{"example":"店員にしきりに勧められて、つい買ってしまった。","example_reading":"てんいんにしきりにすすめられて、ついかってしまった。","example_meaning":"Bị nhân viên mời chào liên tục nên tôi lỡ mua."}],"level":"d1"},
{"word":"至って","reading":"いたって","meaning":"rất, hết sức","hanviet":"chí","note":"Hay dùng với 元気, 普通, 簡単, 健康 (cụm cố định). Văn viết.","example":"医者は「至って健康です」と言った。","example_reading":"いしゃは「いたってけんこうです」といった。","example_meaning":"Bác sĩ nói \"Hoàn toàn khỏe mạnh\".","examples":[{"example":"医者は「至って健康です」と言った。","example_reading":"いしゃは「いたってけんこうです」といった。","example_meaning":"Bác sĩ nói \"Hoàn toàn khỏe mạnh\"."},{"example":"操作は至って簡単ですので、誰でもすぐ使えます。","example_reading":"そうさはいたってかんたんですので、だれでもすぐつかえます。","example_meaning":"Thao tác cực kỳ đơn giản nên ai cũng dùng được ngay."}],"level":"d1"},
{"word":"甚だ","reading":"はなはだ","meaning":"rất, quá mức","hanviet":"thậm","antonym":"わずかに: một chút ít","note":"Văn viết, hay đi với từ chê trách: 甚だ迷惑, 甚だ遺憾.","example":"約束を破るとは、甚だ遺憾です。","example_reading":"やくそくをやぶるとは、はなはだいかんです。","example_meaning":"Việc thất hứa thật sự đáng tiếc vô cùng.","examples":[{"example":"約束を破るとは、甚だ遺憾です。","example_reading":"やくそくをやぶるとは、はなはだいかんです。","example_meaning":"Việc thất hứa thật sự đáng tiếc vô cùng."},{"example":"夜中に大声を出すのは、甚だ迷惑だ。","example_reading":"よなかにおおごえをだすのは、はなはだめいわくだ。","example_meaning":"Hét to giữa đêm khuya thật sự rất phiền."}],"level":"d1"},
{"word":"たぶん","reading":"たぶん","meaning":"có lẽ, chắc là","antonym":"絶対に（ぜったいに）: tuyệt đối","antonym_hanviet":"tuyệt đối","note":"Suy đoán (khoảng 60-70%). Hay đi với ～だろう／～でしょう／～と思う.","example":"明日はたぶん雨でしょう。","example_reading":"あしたはたぶんあめでしょう。","example_meaning":"Ngày mai có lẽ trời sẽ mưa.","examples":[{"example":"明日はたぶん雨でしょう。","example_reading":"あしたはたぶんあめでしょう。","example_meaning":"Ngày mai có lẽ trời sẽ mưa."},{"example":"たぶん彼は、この話をまだ知らないと思う。","example_reading":"たぶんかれは、このはなしをまだしらないとおもう。","example_meaning":"Tôi nghĩ có lẽ anh ấy chưa biết chuyện này."}],"level":"e1"},
{"word":"おそらく","reading":"おそらく","meaning":"có lẽ, nhiều khả năng","antonym":"絶対に（ぜったいに）: tuyệt đối","antonym_hanviet":"tuyệt đối","note":"Suy đoán chắc hơn たぶん, trang trọng hơn. Đi với ～だろう／～でしょう／～と思われる.","example":"彼はおそらく今夜には着くだろう。","example_reading":"かれはおそらくこんやにはつくだろう。","example_meaning":"Có lẽ tối nay anh ấy sẽ đến nơi.","examples":[{"example":"彼はおそらく今夜には着くだろう。","example_reading":"かれはおそらくこんやにはつくだろう。","example_meaning":"Có lẽ tối nay anh ấy sẽ đến nơi."},{"example":"この計画は、おそらく来年になっても実現しないと思われる。","example_reading":"このけいかくは、おそらくらいねんになってもじつげんしないとおもわれる。","example_meaning":"Có thể đến năm sau kế hoạch này vẫn chưa thực hiện được."}],"level":"e1"},
{"word":"だから","reading":"だから","meaning":"vì vậy, cho nên","antonym":"しかし: tuy nhiên / それなのに: vậy mà / だが: nhưng","note":"Khẩu ngữ, đứng đầu câu. Nối lý do với kết quả.","example":"雨が降っている。だから、今日は出かけない。","example_reading":"あめがふっている。だから、きょうはでかけない。","example_meaning":"Trời đang mưa. Vì vậy hôm nay tôi không ra ngoài.","examples":[{"example":"雨が降っている。だから、今日は出かけない。","example_reading":"あめがふっている。だから、きょうはでかけない。","example_meaning":"Trời đang mưa. Vì vậy hôm nay tôi không ra ngoài."},{"example":"彼は毎日練習した。だから、試合に勝てたのだ。","example_reading":"かれはまいにちれんしゅうした。だから、しあいにかてたのだ。","example_meaning":"Anh ấy luyện tập mỗi ngày. Cho nên mới thắng được trận đấu."}],"level":"e1"},
{"word":"きっと","reading":"きっと","meaning":"chắc chắn, nhất định","antonym":"もしかしたら: biết đâu / もしかすると: biết đâu","note":"Suy đoán hoặc tin tưởng mạnh (khoảng 90%). Đi với ～だろう／～でしょう／～と思う. Cũng dùng khi hứa hẹn.","example":"今は大変でも、努力すればきっと報われますよ。","example_reading":"いまはたいへんでも、どりょくすればきっとむくわれますよ。","example_meaning":"Bây giờ dù vất vả, nếu nỗ lực thì chắc chắn sẽ được đền đáp.","examples":[{"example":"今は大変でも、努力すればきっと報われますよ。","example_reading":"いまはたいへんでも、どりょくすればきっとむくわれますよ。","example_meaning":"Bây giờ dù vất vả, nếu nỗ lực thì chắc chắn sẽ được đền đáp."},{"example":"約束するよ。きっと迎えに行くから。","example_reading":"やくそくするよ。きっとむかえにいくから。","example_meaning":"Anh hứa đấy. Nhất định anh sẽ đến đón em."}],"level":"e1"},
{"word":"そして","reading":"そして","meaning":"và, rồi","note":"Nối câu, dùng liệt kê hoặc nối hành động theo thời gian.","example":"朝起きて顔を洗った。そして、朝ご飯を食べた。","example_reading":"あさおきてかおをあらった。そして、あさごはんをたべた。","example_meaning":"Sáng dậy tôi rửa mặt. Rồi ăn sáng.","examples":[{"example":"朝起きて顔を洗った。そして、朝ご飯を食べた。","example_reading":"あさおきてかおをあらった。そして、あさごはんをたべた。","example_meaning":"Sáng dậy tôi rửa mặt. Rồi ăn sáng."},{"example":"彼は優しい。そして、とても頭がいい。","example_reading":"かれはやさしい。そして、とてもあたまがいい。","example_meaning":"Anh ấy hiền lành. Và còn rất thông minh."}],"level":"e1"},
{"word":"やはり","reading":"やはり","meaning":"quả nhiên, rốt cuộc vẫn","antonym":"意外にも（いがいにも）: bất ngờ / 案外（あんがい）: không ngờ","antonym_hanviet":"ý ngoại / án ngoại","note":"Đúng như dự đoán, hoặc quay về điều dự kiến ban đầu. Khẩu ngữ: やっぱり.","example":"天気予報どおり、やはり午後から雨が降り出した。","example_reading":"てんきよほうどおり、やはりごごからあめがふりだした。","example_meaning":"Đúng như dự báo thời tiết, chiều đến quả nhiên trời mưa.","examples":[{"example":"天気予報どおり、やはり午後から雨が降り出した。","example_reading":"てんきよほうどおり、やはりごごからあめがふりだした。","example_meaning":"Đúng như dự báo thời tiết, chiều đến quả nhiên trời mưa."},{"example":"いろいろ悩んだが、やはりこの仕事を続けることにした。","example_reading":"いろいろなやんだが、やはりこのしごとをつづけることにした。","example_meaning":"Tôi đã băn khoăn nhiều, nhưng rốt cuộc vẫn quyết định tiếp tục công việc này."}],"level":"e1"},
{"word":"しかし","reading":"しかし","meaning":"tuy nhiên","antonym":"だから: vì vậy / それで: thế nên / そこで: do đó","note":"Nối ý trái ngược. Dùng nhiều trong cả nói và viết.","example":"努力した。しかし、結果は出なかった。","example_reading":"どりょくした。しかし、けっかはでなかった。","example_meaning":"Tôi đã nỗ lực. Tuy nhiên chưa có kết quả.","examples":[{"example":"努力した。しかし、結果は出なかった。","example_reading":"どりょくした。しかし、けっかはでなかった。","example_meaning":"Tôi đã nỗ lực. Tuy nhiên chưa có kết quả."},{"example":"この方法は簡単だ。しかし、時間がかかる。","example_reading":"このほうほうはかんたんだ。しかし、じかんがかかる。","example_meaning":"Cách này đơn giản. Tuy nhiên tốn thời gian."}],"level":"e1"},
{"word":"やっぱり","reading":"やっぱり","meaning":"quả nhiên, vẫn là","antonym":"意外にも（いがいにも）: bất ngờ / 案外（あんがい）: không ngờ","antonym_hanviet":"ý ngoại / án ngoại","note":"Khẩu ngữ của やはり. Hay đi với ～た／～ね. Đúng như dự đoán hoặc vẫn như cũ.","example":"やっぱり私が思ったとおりだった。","example_reading":"やっぱりわたしがおもったとおりだった。","example_meaning":"Quả nhiên đúng như tôi nghĩ.","examples":[{"example":"やっぱり私が思ったとおりだった。","example_reading":"やっぱりわたしがおもったとおりだった。","example_meaning":"Quả nhiên đúng như tôi nghĩ."},{"example":"いろいろ考えたが、やっぱりこの仕事を続けたい。","example_reading":"いろいろかんがえたが、やっぱりこのしごとをつづけたい。","example_meaning":"Đã nghĩ nhiều nhưng tôi vẫn muốn tiếp tục công việc này."}],"level":"e1"},
{"word":"それで","reading":"それで","meaning":"vì vậy, thế là","antonym":"しかし: tuy nhiên / だが: nhưng / でも: nhưng mà","note":"Nối kết quả. Cũng dùng để giục người nghe kể tiếp: それで？","example":"電車が止まった。それで、会議に遅れてしまった。","example_reading":"でんしゃがとまった。それで、かいぎにおくれてしまった。","example_meaning":"Tàu bị dừng. Thế là tôi đến họp muộn.","examples":[{"example":"電車が止まった。それで、会議に遅れてしまった。","example_reading":"でんしゃがとまった。それで、かいぎにおくれてしまった。","example_meaning":"Tàu bị dừng. Thế là tôi đến họp muộn."},{"example":"「昨日、財布を落としてしまって。」「それで、どうしたの？」","example_reading":"「きのう、さいふをおとしてしまって。」「それで、どうしたの？」","example_meaning":"\"Hôm qua mình làm rơi ví.\" \"Rồi sau đó thì sao?\""}],"level":"e1"},
{"word":"結局","reading":"けっきょく","meaning":"rốt cuộc, cuối cùng","hanviet":"kết cục","note":"Kết quả sau cả quá trình dài. Thường dùng với kết quả không như ý.","example":"三時間も話し合ったが、結局何も決まらなかった。","example_reading":"さんじかんもはなしあったが、けっきょくなにもきまらなかった。","example_meaning":"Bàn bạc tận ba tiếng mà rốt cuộc chẳng quyết định được gì.","examples":[{"example":"三時間も話し合ったが、結局何も決まらなかった。","example_reading":"さんじかんもはなしあったが、けっきょくなにもきまらなかった。","example_meaning":"Bàn bạc tận ba tiếng mà rốt cuộc chẳng quyết định được gì."},{"example":"迷った末、結局いつもの店で昼食をとった。","example_reading":"まよったすえ、けっきょくいつものみせでちゅうしょくをとった。","example_meaning":"Sau khi phân vân, cuối cùng tôi vẫn ăn trưa ở quán quen."}],"level":"e1"},
{"word":"それから","reading":"それから","meaning":"sau đó, và rồi","note":"Nối hành động diễn ra theo thứ tự thời gian.","example":"まず手を洗って、それから食事の準備をした。","example_reading":"まずてをあらって、それからしょくじのじゅんびをした。","example_meaning":"Trước hết rửa tay, sau đó chuẩn bị bữa ăn.","examples":[{"example":"まず手を洗って、それから食事の準備をした。","example_reading":"まずてをあらって、それからしょくじのじゅんびをした。","example_meaning":"Trước hết rửa tay, sau đó chuẩn bị bữa ăn."},{"example":"切符を買って、それから改札を通った。","example_reading":"きっぷをかって、それからかいさつをとおった。","example_meaning":"Mua vé xong, sau đó đi qua cổng soát vé."}],"level":"e1"},
{"word":"実際","reading":"じっさい","meaning":"thực tế, quả thật","hanviet":"thực tế","antonym":"理論上（りろんじょう）: trên lý thuyết","antonym_hanviet":"lý luận thượng","note":"Đọc じっさい. Hay đi với 実際に～, 実際～. Nêu thực tế đối lập với dự đoán, hoặc xác nhận.","example":"難しいと聞いていたが、実際にやってみると簡単だった。","example_reading":"むずかしいときいていたが、じっさいにやってみるとかんたんだった。","example_meaning":"Nghe nói khó nhưng thực tế làm thử lại dễ.","examples":[{"example":"難しいと聞いていたが、実際にやってみると簡単だった。","example_reading":"むずかしいときいていたが、じっさいにやってみるとかんたんだった。","example_meaning":"Nghe nói khó nhưng thực tế làm thử lại dễ."},{"example":"彼は実際、とても優秀な社員だ。","example_reading":"かれはじっさい、とてもゆうしゅうなしゃいんだ。","example_meaning":"Thực tế, anh ấy là một nhân viên rất xuất sắc."}],"level":"e1"},
{"word":"実は","reading":"じつは","meaning":"thật ra thì, nói thật","hanviet":"thực","antonym":"表向きは（おもてむきは）: bề ngoài thì / 一見（いっけん）: thoạt nhìn","antonym_hanviet":"biểu hướng / nhất kiến","note":"Mở đầu lời thú nhận hoặc tiết lộ điều bất ngờ.","example":"実は、来月からアメリカに転勤することになりました。","example_reading":"じつは、らいげつからアメリカにてんきんすることになりました。","example_meaning":"Thật ra từ tháng sau tôi sẽ chuyển công tác sang Mỹ.","examples":[{"example":"実は、来月からアメリカに転勤することになりました。","example_reading":"じつは、らいげつからアメリカにてんきんすることになりました。","example_meaning":"Thật ra từ tháng sau tôi sẽ chuyển công tác sang Mỹ."},{"example":"彼は無口だが、実はとても親切な人だ。","example_reading":"かれはむくちだが、じつはとてもしんせつなひとだ。","example_meaning":"Anh ấy ít nói nhưng thật ra là người rất tốt bụng."}],"level":"e1"},
{"word":"つまり","reading":"つまり","meaning":"tức là, nói cách khác","note":"Nối ý, diễn đạt lại hoặc tóm gọn. Đặt đầu câu hoặc giữa câu.","example":"彼は父の弟、つまり私の叔父にあたります。","example_reading":"かれはちちのおとうと、つまりわたしのおじにあたります。","example_meaning":"Anh ấy là em trai của bố, tức là chú của tôi.","examples":[{"example":"彼は父の弟、つまり私の叔父にあたります。","example_reading":"かれはちちのおとうと、つまりわたしのおじにあたります。","example_meaning":"Anh ấy là em trai của bố, tức là chú của tôi."},{"example":"今日は定休日、つまり店は閉まっているということだ。","example_reading":"きょうはていきゅうひ、つまりみせはしまっているということだ。","example_meaning":"Hôm nay là ngày nghỉ định kỳ, tức là cửa hàng đóng cửa."}],"level":"e1"},
{"word":"さて","reading":"さて","meaning":"nào, vậy thì","note":"Chuyển sang phần tiếp theo trong lời nói hoặc văn bản.","example":"さて、そろそろ本題に入りましょう。","example_reading":"さて、そろそろほんだいにはいりましょう。","example_meaning":"Nào, bây giờ ta vào vấn đề chính nhé.","examples":[{"example":"さて、そろそろ本題に入りましょう。","example_reading":"さて、そろそろほんだいにはいりましょう。","example_meaning":"Nào, bây giờ ta vào vấn đề chính nhé."},{"example":"準備が終わりました。さて、始めましょうか。","example_reading":"じゅんびがおわりました。さて、はじめましょうか。","example_meaning":"Chuẩn bị xong rồi. Nào, bắt đầu thôi."}],"level":"e1"},
{"word":"それでは","reading":"それでは","meaning":"vậy thì","note":"Dùng khi bắt đầu, kết thúc hoặc kết luận. Thân mật: じゃあ.","example":"それでは、会議を始めます。","example_reading":"それでは、かいぎをはじめます。","example_meaning":"Vậy thì, tôi xin bắt đầu cuộc họp.","examples":[{"example":"それでは、会議を始めます。","example_reading":"それでは、かいぎをはじめます。","example_meaning":"Vậy thì, tôi xin bắt đầu cuộc họp."},{"example":"時間になりましたので、それでは失礼いたします。","example_reading":"じかんになりましたので、それではしつれいいたします。","example_meaning":"Đã đến giờ nên tôi xin phép cáo từ."}],"level":"e1"},
{"word":"ですから","reading":"ですから","meaning":"vì thế (lịch sự)","note":"Lịch sự hơn だから. Hay dùng khi giải thích hoặc nhắc lại lý do.","example":"何度も説明しました。ですから、もう一度説明する必要はありません。","example_reading":"なんどもせつめいしました。ですから、もういちどせつめいするひつようはありません。","example_meaning":"Tôi đã giải thích nhiều lần. Vì vậy không cần giải thích lại.","examples":[{"example":"何度も説明しました。ですから、もう一度説明する必要はありません。","example_reading":"なんどもせつめいしました。ですから、もういちどせつめいするひつようはありません。","example_meaning":"Tôi đã giải thích nhiều lần. Vì vậy không cần giải thích lại."},{"example":"当店は禁煙です。ですから、お煙草はご遠慮ください。","example_reading":"とうてんはきんえんです。ですから、おたばこはごえんりょください。","example_meaning":"Cửa hàng chúng tôi cấm hút thuốc. Vì vậy xin quý khách vui lòng không hút."}],"level":"e1"},
{"word":"本当に","reading":"ほんとうに","meaning":"thật sự, quả thật","hanviet":"bản đương","note":"Đọc ほんとうに. Nhấn mạnh sự thật hoặc cảm xúc. Khẩu ngữ: ほんとに.","example":"本当にありがとうございました。","example_reading":"ほんとうにありがとうございました。","example_meaning":"Thật sự cảm ơn rất nhiều.","examples":[{"example":"本当にありがとうございました。","example_reading":"ほんとうにありがとうございました。","example_meaning":"Thật sự cảm ơn rất nhiều."},{"example":"この景色は本当にきれいですね。","example_reading":"このけしきはほんとうにきれいですね。","example_meaning":"Phong cảnh này thật sự đẹp nhỉ."}],"level":"e1"},
{"word":"なるほど","reading":"なるほど","meaning":"ra vậy, quả là","note":"Dùng khi đồng tình hoặc hiểu ra điều người khác nói. Hay đi với ～ね／～と思う.","example":"なるほど、そういう理由だったのか。","example_reading":"なるほど、そういうりゆうだったのか。","example_meaning":"Ra vậy, lý do là thế à.","examples":[{"example":"なるほど、そういう理由だったのか。","example_reading":"なるほど、そういうりゆうだったのか。","example_meaning":"Ra vậy, lý do là thế à."},{"example":"彼の意見はなるほど筋が通っている。","example_reading":"かれのいけんはなるほどすじがとおっている。","example_meaning":"Ý kiến của anh ấy quả là có lý."}],"level":"e1"},
{"word":"確かに","reading":"たしかに","meaning":"quả thật, đúng là","hanviet":"xác","note":"Thừa nhận điều người khác nói. Hay đi trước が／けど để nhượng bộ rồi nêu ý trái lại.","example":"確かに、あなたの言うとおりかもしれません。","example_reading":"たしかに、あなたのいうとおりかもしれません。","example_meaning":"Quả thật có lẽ đúng như bạn nói.","examples":[{"example":"確かに、あなたの言うとおりかもしれません。","example_reading":"たしかに、あなたのいうとおりかもしれません。","example_meaning":"Quả thật có lẽ đúng như bạn nói."},{"example":"確かにこの店は安いが、味はあまりよくない。","example_reading":"たしかにこのみせはやすいが、あじはあまりよくない。","example_meaning":"Đúng là quán này rẻ nhưng vị không ngon lắm."}],"level":"e1"},
{"word":"もちろん","reading":"もちろん","meaning":"tất nhiên","note":"Hiển nhiên, không cần nói. Hay đi với ～はもちろん／～だけでなく.","example":"「手伝おうか。」「もちろん、お願いします。」","example_reading":"「てつだおうか。」「もちろん、おねがいします。」","example_meaning":"\"Để tôi giúp nhé?\" \"Tất nhiên rồi, nhờ bạn.\"","examples":[{"example":"「手伝おうか。」「もちろん、お願いします。」","example_reading":"「てつだおうか。」「もちろん、おねがいします。」","example_meaning":"\"Để tôi giúp nhé?\" \"Tất nhiên rồi, nhờ bạn.\""},{"example":"彼は英語はもちろん、フランス語も話せる。","example_reading":"かれはえいごはもちろん、フランスごもはなせる。","example_meaning":"Anh ấy không chỉ tiếng Anh mà tiếng Pháp cũng nói được."}],"level":"e1"},
{"word":"とにかく","reading":"とにかく","meaning":"dù sao đi nữa, trước hết cứ","note":"Gạt chi tiết sang bên để làm điều quan trọng trước. Hay đi với ～てみる／～てください.","example":"細かいことはいいから、とにかくやってみよう。","example_reading":"こまかいことはいいから、とにかくやってみよう。","example_meaning":"Chuyện chi tiết khỏi bàn, cứ làm thử đã.","examples":[{"example":"細かいことはいいから、とにかくやってみよう。","example_reading":"こまかいことはいいから、とにかくやってみよう。","example_meaning":"Chuyện chi tiết khỏi bàn, cứ làm thử đã."},{"example":"とにかく、今日中に結論を出す必要がある。","example_reading":"とにかく、きょうじゅうにけつろんをだすひつようがある。","example_meaning":"Dù sao thì cần đưa ra kết luận trong hôm nay."}],"level":"e1"},
{"word":"それに","reading":"それに","meaning":"hơn nữa, vả lại","note":"Thêm lý do hoặc ý bổ sung cùng hướng.","example":"この店は安いし、それに味もいい。","example_reading":"このみせはやすいし、それにあじもいい。","example_meaning":"Quán này rẻ, hơn nữa vị cũng ngon.","examples":[{"example":"この店は安いし、それに味もいい。","example_reading":"このみせはやすいし、それにあじもいい。","example_meaning":"Quán này rẻ, hơn nữa vị cũng ngon."},{"example":"今日は寒いし、それに雨も降っている。","example_reading":"きょうはさむいし、それにあめもふっている。","example_meaning":"Hôm nay lạnh, mà còn đang mưa nữa."}],"level":"e1"},
{"word":"例えば","reading":"たとえば","meaning":"ví dụ, chẳng hạn","hanviet":"lệ","note":"Đưa ví dụ minh họa. Hay đi với ～など／～のような.","example":"例えば、野菜ならトマトやきゅうりがおすすめです。","example_reading":"たとえば、やさいならトマトやきゅうりがおすすめです。","example_meaning":"Ví dụ như rau thì tôi gợi ý cà chua hoặc dưa chuột.","examples":[{"example":"例えば、野菜ならトマトやきゅうりがおすすめです。","example_reading":"たとえば、やさいならトマトやきゅうりがおすすめです。","example_meaning":"Ví dụ như rau thì tôi gợi ý cà chua hoặc dưa chuột."},{"example":"日本の伝統文化、例えば茶道や華道に興味があります。","example_reading":"にほんのでんとうぶんか、たとえばさどうやかどうにきょうみがあります。","example_meaning":"Tôi quan tâm đến văn hóa truyền thống Nhật Bản, chẳng hạn như trà đạo hay hoa đạo."}],"level":"e1"},
{"word":"むしろ","reading":"むしろ","meaning":"ngược lại, đúng hơn là, thà là","note":"So sánh hai vế và chọn vế sau. Hay đi với ～より(も)／～ではなく／～どころか.","example":"この仕事は難しいというより、むしろ面倒だ。","example_reading":"このしごとはむずかしいというより、むしろめんどうだ。","example_meaning":"Công việc này nói là khó thì đúng hơn là phiền phức.","examples":[{"example":"この仕事は難しいというより、むしろ面倒だ。","example_reading":"このしごとはむずかしいというより、むしろめんどうだ。","example_meaning":"Công việc này nói là khó thì đúng hơn là phiền phức."},{"example":"彼は怒るどころか、むしろ笑っていた。","example_reading":"かれはおこるどころか、むしろわらっていた。","example_meaning":"Anh ấy không những không giận mà ngược lại còn cười."}],"level":"e1"},
{"word":"もしかしたら","reading":"もしかしたら","meaning":"biết đâu, có thể là","antonym":"きっと: chắc chắn / 間違いなく（まちがいなく）: không sai","antonym_hanviet":" / gian vi","note":"Suy đoán khả năng không chắc. Đi với ～かもしれない. Biến thể: もしかすると／もしかして.","example":"もしかしたら、彼はもう帰ったのかもしれない。","example_reading":"もしかしたら、かれはもうかえったのかもしれない。","example_meaning":"Biết đâu anh ấy đã về rồi.","examples":[{"example":"もしかしたら、彼はもう帰ったのかもしれない。","example_reading":"もしかしたら、かれはもうかえったのかもしれない。","example_meaning":"Biết đâu anh ấy đã về rồi."},{"example":"もしかしたら、この道は間違っているのではないか。","example_reading":"もしかしたら、このみちはまちがっているのではないか。","example_meaning":"Có thể con đường này sai rồi chăng?"}],"level":"e1"},
{"word":"どうやら","reading":"どうやら","meaning":"có vẻ như, hình như","note":"Suy đoán dựa vào bằng chứng quan sát. Đi với ～ようだ／～らしい／～そうだ.","example":"どうやら、私は電車を間違えたようだ。","example_reading":"どうやら、わたしはでんしゃをまちがえたようだ。","example_meaning":"Có vẻ như tôi đã đi nhầm tàu.","examples":[{"example":"どうやら、私は電車を間違えたようだ。","example_reading":"どうやら、わたしはでんしゃをまちがえたようだ。","example_meaning":"Có vẻ như tôi đã đi nhầm tàu."},{"example":"どうやら明日は、台風が上陸するらしい。","example_reading":"どうやらあしたは、たいふうがじょうりくするらしい。","example_meaning":"Hình như ngày mai bão sẽ đổ bộ."}],"level":"e1"},
{"word":"だが","reading":"だが","meaning":"nhưng","antonym":"だから: vì vậy / それで: thế nên / そこで: do đó","note":"Văn viết hoặc khẩu ngữ nam giới. Nối ý trái ngược, cứng hơn しかし.","example":"計画は完璧だった。だが、実行する時間がなかった。","example_reading":"けいかくはかんぺきだった。だが、じっこうするじかんがなかった。","example_meaning":"Kế hoạch hoàn hảo. Nhưng không có thời gian thực hiện.","examples":[{"example":"計画は完璧だった。だが、実行する時間がなかった。","example_reading":"けいかくはかんぺきだった。だが、じっこうするじかんがなかった。","example_meaning":"Kế hoạch hoàn hảo. Nhưng không có thời gian thực hiện."},{"example":"彼は貧しかった。だが、心はいつも豊かだった。","example_reading":"かれはまずしかった。だが、こころはいつもゆたかだった。","example_meaning":"Anh ấy nghèo. Nhưng tâm hồn luôn giàu có."}],"level":"e1"},
{"word":"けれども","reading":"けれども","meaning":"nhưng, tuy vậy","antonym":"だから: vì vậy / それで: thế nên / そこで: do đó","note":"Nối ý trái ngược. Mềm hơn しかし, cũng có dạng けど, けれど.","example":"値段は高い。けれども、品質は申し分ない。","example_reading":"ねだんはたかい。けれども、ひんしつはもうしぶんない。","example_meaning":"Giá đắt. Nhưng chất lượng thì không chê vào đâu được.","examples":[{"example":"値段は高い。けれども、品質は申し分ない。","example_reading":"ねだんはたかい。けれども、ひんしつはもうしぶんない。","example_meaning":"Giá đắt. Nhưng chất lượng thì không chê vào đâu được."},{"example":"何度も練習した。けれども、うまくできなかった。","example_reading":"なんどもれんしゅうした。けれども、うまくできなかった。","example_meaning":"Tôi đã luyện tập nhiều lần. Nhưng vẫn không làm tốt được."}],"level":"e1"},
{"word":"それとも","reading":"それとも","meaning":"hay là","note":"Câu hỏi lựa chọn: A それとも B.","example":"コーヒーにしますか、それとも紅茶にしますか。","example_reading":"コーヒーにしますか、それともこうちゃにしますか。","example_meaning":"Bạn dùng cà phê hay là trà?","examples":[{"example":"コーヒーにしますか、それとも紅茶にしますか。","example_reading":"コーヒーにしますか、それともこうちゃにしますか。","example_meaning":"Bạn dùng cà phê hay là trà?"},{"example":"今日行きますか、それとも明日にしますか。","example_reading":"きょういきますか、それともあしたにしますか。","example_meaning":"Bạn đi hôm nay hay để ngày mai?"}],"level":"e1"},
{"word":"無論","reading":"むろん","meaning":"dĩ nhiên, tất nhiên","hanviet":"vô luận","note":"Đọc むろん. Hay đi với ～だ／～が、～. Văn viết, trang trọng hơn もちろん.","example":"無論、私も参加するつもりです。","example_reading":"むろん、わたしもさんかするつもりです。","example_meaning":"Dĩ nhiên tôi cũng định tham gia.","examples":[{"example":"無論、私も参加するつもりです。","example_reading":"むろん、わたしもさんかするつもりです。","example_meaning":"Dĩ nhiên tôi cũng định tham gia."},{"example":"無論、費用は会社が負担する。","example_reading":"むろん、ひようはかいしゃがふたんする。","example_meaning":"Dĩ nhiên chi phí do công ty chịu."}],"level":"e1"},
{"word":"当然","reading":"とうぜん","meaning":"đương nhiên, dĩ nhiên","hanviet":"đương nhiên","antonym":"意外にも（いがいにも）: bất ngờ / 案外（あんがい）: không ngờ","antonym_hanviet":"ý ngoại / án ngoại","note":"Việc lẽ tất nhiên. Hay đi với ～だ／～ものだ／～のも当然だ.","example":"彼は当然、会議に出席するものだと思っていた。","example_reading":"かれはとうぜん、かいぎにしゅっせきするものだとおもっていた。","example_meaning":"Tôi đã nghĩ đương nhiên anh ấy sẽ tham dự cuộc họp.","examples":[{"example":"彼は当然、会議に出席するものだと思っていた。","example_reading":"かれはとうぜん、かいぎにしゅっせきするものだとおもっていた。","example_meaning":"Tôi đã nghĩ đương nhiên anh ấy sẽ tham dự cuộc họp."},{"example":"外はこんなに暑いのだから、のどが渇くのも当然だ。","example_reading":"そとはこんなにあついのだから、のどがかわくのもとうぜんだ。","example_meaning":"Bên ngoài nóng thế này thì khát nước là đương nhiên."}],"level":"e1"},
{"word":"さすが","reading":"さすが","meaning":"quả không hổ là","note":"Khen ngợi phù hợp với danh tiếng. Hay đi với ～だ／～は. Dạng さすがに: \"quả thật cũng (phải ～)\".","example":"優勝するなんて、さすがプロの選手だ。","example_reading":"ゆうしょうするなんて、さすがプロのせんしゅだ。","example_meaning":"Vô địch được đúng là quả không hổ danh vận động viên chuyên nghiệp.","examples":[{"example":"優勝するなんて、さすがプロの選手だ。","example_reading":"ゆうしょうするなんて、さすがプロのせんしゅだ。","example_meaning":"Vô địch được đúng là quả không hổ danh vận động viên chuyên nghiệp."},{"example":"毎日残業が続いて、さすがに疲れてきた。","example_reading":"まいにちざんぎょうがつづいて、さすがにつかれてきた。","example_meaning":"Ngày nào cũng tăng ca, quả thật tôi cũng bắt đầu thấy mệt."}],"level":"e1"},
{"word":"ともかく","reading":"ともかく","meaning":"bỏ qua chuyện đó, dù sao","note":"Gần とにかく nhưng trang trọng hơn. Hay đi với ～はともかく (chưa bàn đến).","example":"結果はともかく、努力したことは認めよう。","example_reading":"けっかはともかく、どりょくしたことはみとめよう。","example_meaning":"Chưa nói đến kết quả, hãy công nhận là đã nỗ lực.","examples":[{"example":"結果はともかく、努力したことは認めよう。","example_reading":"けっかはともかく、どりょくしたことはみとめよう。","example_meaning":"Chưa nói đến kết quả, hãy công nhận là đã nỗ lực."},{"example":"ともかく、無事で何よりだ。","example_reading":"ともかく、ぶじでなによりだ。","example_meaning":"Dù sao đi nữa, bình an là điều quý nhất."}],"level":"e1"},
{"word":"そこで","reading":"そこで","meaning":"do đó, thế nên","antonym":"しかし: tuy nhiên / だが: nhưng / けれども: nhưng","note":"Làm một việc đáp lại tình huống vừa nêu. Cũng có nghĩa \"ở đó\".","example":"売り上げが落ちた。そこで、新しい広告を出すことにした。","example_reading":"うりあげがおちた。そこで、あたらしいこうこくをだすことにした。","example_meaning":"Doanh thu giảm. Do đó chúng tôi quyết định đăng quảng cáo mới.","examples":[{"example":"売り上げが落ちた。そこで、新しい広告を出すことにした。","example_reading":"うりあげがおちた。そこで、あたらしいこうこくをだすことにした。","example_meaning":"Doanh thu giảm. Do đó chúng tôi quyết định đăng quảng cáo mới."},{"example":"道が分からなかった。そこで、近くの人に尋ねてみた。","example_reading":"みちがわからなかった。そこで、ちかくのひとにたずねてみた。","example_meaning":"Tôi không biết đường. Nên đã hỏi một người ở gần đó."}],"level":"e1"},
{"word":"もしかすると","reading":"もしかすると","meaning":"biết đâu, có thể","antonym":"きっと: chắc chắn / 間違いなく（まちがいなく）: không sai","antonym_hanviet":" / gian vi","note":"Đi với ～かもしれない. Gần もしかしたら.","example":"もしかすると、彼は私のことを忘れているのかもしれない。","example_reading":"もしかすると、かれはわたしのことをわすれているのかもしれない。","example_meaning":"Biết đâu anh ấy đã quên tôi rồi.","examples":[{"example":"もしかすると、彼は私のことを忘れているのかもしれない。","example_reading":"もしかすると、かれはわたしのことをわすれているのかもしれない。","example_meaning":"Biết đâu anh ấy đã quên tôi rồi."},{"example":"もしかすると、明日は雪になるかもしれません。","example_reading":"もしかすると、あしたはゆきになるかもしれません。","example_meaning":"Có thể ngày mai sẽ có tuyết."}],"level":"e1"},
{"word":"一応","reading":"いちおう","meaning":"tạm, cho chắc, sơ qua","hanviet":"nhất ứng","antonym":"徹底的に（てっていてきに）: triệt để","antonym_hanviet":"triệt để đích","note":"Làm ở mức tối thiểu hoặc để cho chắc. Khẩu ngữ, rất hay gặp.","example":"使えるかどうか、一応確認しておいてください。","example_reading":"つかえるかどうか、いちおうかくにんしておいてください。","example_meaning":"Hãy kiểm tra qua cho chắc xem có dùng được không.","examples":[{"example":"使えるかどうか、一応確認しておいてください。","example_reading":"つかえるかどうか、いちおうかくにんしておいてください。","example_meaning":"Hãy kiểm tra qua cho chắc xem có dùng được không."},{"example":"まだ完璧ではありませんが、一応できました。","example_reading":"まだかんぺきではありませんが、いちおうできました。","example_meaning":"Chưa hoàn hảo nhưng tạm thời đã xong."}],"level":"e1"},
{"word":"ただ","reading":"ただ","meaning":"chỉ là, có điều","note":"Thêm điều kiện hoặc lưu ý. Cũng có nghĩa \"chỉ\".","example":"この店は安くておいしい。ただ、いつも混んでいる。","example_reading":"このみせはやすくておいしい。ただ、いつもこんでいる。","example_meaning":"Quán này rẻ và ngon. Có điều lúc nào cũng đông.","examples":[{"example":"この店は安くておいしい。ただ、いつも混んでいる。","example_reading":"このみせはやすくておいしい。ただ、いつもこんでいる。","example_meaning":"Quán này rẻ và ngon. Có điều lúc nào cũng đông."},{"example":"彼は優秀だ。ただ、少し頑固なところがある。","example_reading":"かれはゆうしゅうだ。ただ、すこしがんこなところがある。","example_meaning":"Anh ấy giỏi. Có điều hơi cứng đầu một chút."}],"level":"e1"},
{"word":"実を言うと","reading":"じつをいうと","meaning":"nói thật ra thì","hanviet":"thực ngôn","antonym":"表向きは（おもてむきは）: bề ngoài thì","antonym_hanviet":"biểu hướng","note":"Đọc じつをいうと. Hay đi với ～んだ／～のです. Mở đầu lời thú nhận, tương tự 実は.","example":"実を言うと、私は辛い料理が苦手です。","example_reading":"じつをいうと、わたしはからいりょうりがにがてです。","example_meaning":"Nói thật ra thì tôi không giỏi ăn đồ cay.","examples":[{"example":"実を言うと、私は辛い料理が苦手です。","example_reading":"じつをいうと、わたしはからいりょうりがにがてです。","example_meaning":"Nói thật ra thì tôi không giỏi ăn đồ cay."},{"example":"実を言うと、昨日の試験は全然できなかった。","example_reading":"じつをいうと、きのうのしけんはぜんぜんできなかった。","example_meaning":"Nói thật ra thì bài thi hôm qua tôi làm không được."}],"level":"e1"},
{"word":"正直","reading":"しょうじき","meaning":"nói thật, thành thật mà nói","hanviet":"chính trực","note":"Đọc しょうじき. Hay đi với 正直(に)言って, 正直なところ. Mở đầu lời nói thẳng.","antonym":"嘘つき（うそつき）: kẻ nói dối","antonym_hanviet":"hư","example":"正直、この仕事は私には難しすぎる。","example_reading":"しょうじき、このしごとはわたしにはむずかしすぎる。","example_meaning":"Thành thật mà nói, công việc này quá khó với tôi.","examples":[{"example":"正直、この仕事は私には難しすぎる。","example_reading":"しょうじき、このしごとはわたしにはむずかしすぎる。","example_meaning":"Thành thật mà nói, công việc này quá khó với tôi."},{"example":"正直なところ、彼の話は信じられない。","example_reading":"しょうじきなところ、かれのはなしはしんじられない。","example_meaning":"Nói thật lòng, tôi không tin chuyện anh ấy kể."}],"level":"e1"},
{"word":"本当は","reading":"ほんとうは","meaning":"thật ra, thực ra thì","hanviet":"bản đương","antonym":"表向きは（おもてむきは）: bề ngoài thì","antonym_hanviet":"biểu hướng","note":"Khác với bề ngoài hoặc lời nói. Cũng dùng trong ～たかった (tiếc nuối).","example":"本当は、今日の会には行きたくなかったのです。","example_reading":"ほんとうは、きょうのかいにはいきたくなかったのです。","example_meaning":"Thật ra tôi không muốn đến buổi họp hôm nay.","examples":[{"example":"本当は、今日の会には行きたくなかったのです。","example_reading":"ほんとうは、きょうのかいにはいきたくなかったのです。","example_meaning":"Thật ra tôi không muốn đến buổi họp hôm nay."},{"example":"彼は強そうに見えるが、本当は気が弱い。","example_reading":"かれはつよそうにみえるが、ほんとうはきがよわい。","example_meaning":"Anh ấy trông có vẻ mạnh mẽ nhưng thực ra tính rất yếu đuối."}],"level":"e1"},
{"word":"逆に","reading":"ぎゃくに","meaning":"ngược lại","hanviet":"nghịch","note":"Nêu điều trái với dự tính hoặc điều vừa nói.","antonym":"そのまま: giữ nguyên","example":"親切のつもりで言ったのに、逆に怒られてしまった。","example_reading":"しんせつのつもりでいったのに、ぎゃくにおこられてしまった。","example_meaning":"Tôi nói với ý tốt vậy mà ngược lại bị giận.","examples":[{"example":"親切のつもりで言ったのに、逆に怒られてしまった。","example_reading":"しんせつのつもりでいったのに、ぎゃくにおこられてしまった。","example_meaning":"Tôi nói với ý tốt vậy mà ngược lại bị giận."},{"example":"忙しい日のほうが、逆に仕事がはかどる。","example_reading":"いそがしいひのほうが、ぎゃくにしごとがはかどる。","example_meaning":"Những ngày bận thì ngược lại công việc lại trôi chảy hơn."}],"level":"e1"},
{"word":"ところで","reading":"ところで","meaning":"nhân tiện, mà này","note":"Chuyển sang chủ đề khác, không liên quan đến nội dung trước.","example":"今日はありがとう。ところで、来週の予定はどうなっている？","example_reading":"きょうはありがとう。ところで、らいしゅうのよていはどうなっている？","example_meaning":"Hôm nay cảm ơn nhé. À mà, lịch tuần sau thế nào rồi?","examples":[{"example":"今日はありがとう。ところで、来週の予定はどうなっている？","example_reading":"きょうはありがとう。ところで、らいしゅうのよていはどうなっている？","example_meaning":"Hôm nay cảm ơn nhé. À mà, lịch tuần sau thế nào rồi?"},{"example":"ところで、田中さんは最近お元気ですか。","example_reading":"ところで、たなかさんはさいきんおげんきですか。","example_meaning":"Nhân tiện, gần đây anh Tanaka có khỏe không?"}],"level":"e1"},
{"word":"まさに","reading":"まさに","meaning":"chính là, đúng là","note":"Hay đi với ～だ, ～の時. Nhấn mạnh sự việc đúng như thế.","example":"それはまさに私が言いたかったことだ。","example_reading":"それはまさにわたしがいいたかったことだ。","example_meaning":"Đó chính là điều tôi muốn nói.","examples":[{"example":"それはまさに私が言いたかったことだ。","example_reading":"それはまさにわたしがいいたかったことだ。","example_meaning":"Đó chính là điều tôi muốn nói."},{"example":"今こそ、まさに行動すべき時だ。","example_reading":"いまこそ、まさにこうどうすべきときだ。","example_meaning":"Chính lúc này là lúc cần hành động."}],"level":"e1"},
{"word":"次に","reading":"つぎに","meaning":"tiếp theo","hanviet":"thứ","antonym":"まず: trước tiên / 最初に（さいしょに）: đầu tiên","antonym_hanviet":" / tối sơ","note":"Nối bước tiếp theo trong trình tự.","example":"次に、野菜を細かく切ってください。","example_reading":"つぎに、やさいをこまかくきってください。","example_meaning":"Tiếp theo, hãy thái nhỏ rau.","examples":[{"example":"次に、野菜を細かく切ってください。","example_reading":"つぎに、やさいをこまかくきってください。","example_meaning":"Tiếp theo, hãy thái nhỏ rau."},{"example":"次に、今後の予定についてご説明します。","example_reading":"つぎに、こんごのよていについてごせつめいします。","example_meaning":"Tiếp theo, tôi xin giải thích về lịch trình sắp tới."}],"level":"e1"},
{"word":"でも","reading":"でも","meaning":"nhưng mà","antonym":"だから: vì vậy / それで: thế nên","note":"Khẩu ngữ. Nối ý trái ngược.","example":"行きたい。でも、お金がない。","example_reading":"いきたい。でも、おかねがない。","example_meaning":"Muốn đi. Nhưng mà không có tiền.","examples":[{"example":"行きたい。でも、お金がない。","example_reading":"いきたい。でも、おかねがない。","example_meaning":"Muốn đi. Nhưng mà không có tiền."},{"example":"頑張った。でも、うまくいかなかった。","example_reading":"がんばった。でも、うまくいかなかった。","example_meaning":"Tôi đã cố gắng. Nhưng không suôn sẻ."}],"level":"e1"},
{"word":"わざわざ","reading":"わざわざ","meaning":"có công, mất công","antonym":"ついでに: nhân tiện / 何気なく（なにげなく）: vô tình","antonym_hanviet":" / hà khí","note":"Hay đi với ～てくれる／～する. Biết ơn hoặc châm biếm.","example":"遠いところを、わざわざ来てくださってありがとうございます。","example_reading":"とおいところを、わざわざきてくださってありがとうございます。","example_meaning":"Cảm ơn anh đã mất công đến từ nơi xa.","examples":[{"example":"遠いところを、わざわざ来てくださってありがとうございます。","example_reading":"とおいところを、わざわざきてくださってありがとうございます。","example_meaning":"Cảm ơn anh đã mất công đến từ nơi xa."},{"example":"わざわざ行かなくても、電話で済むよ。","example_reading":"わざわざいかなくても、でんわですむよ。","example_meaning":"Không cần mất công đi, gọi điện là xong mà."}],"level":"e1"},
{"word":"そういえば","reading":"そういえば","meaning":"à mà, nhắc mới nhớ","note":"Nhớ ra điều liên quan khi nghe hay nghĩ về một việc.","example":"そういえば、昨日田中さんから連絡があったよ。","example_reading":"そういえば、きのうたなかさんかられんらくがあったよ。","example_meaning":"À nhắc mới nhớ, hôm qua anh Tanaka có liên lạc đấy.","examples":[{"example":"そういえば、昨日田中さんから連絡があったよ。","example_reading":"そういえば、きのうたなかさんかられんらくがあったよ。","example_meaning":"À nhắc mới nhớ, hôm qua anh Tanaka có liên lạc đấy."},{"example":"そういえば、来週は祝日で会社が休みだった。","example_reading":"そういえば、らいしゅうはしゅくじつでかいしゃがやすみだった。","example_meaning":"À mà, tuần sau là ngày lễ nên công ty nghỉ."}],"level":"e1"},
{"word":"反対に","reading":"はんたいに","meaning":"ngược lại","hanviet":"phản đối","antonym":"同様に（どうように）: tương tự","antonym_hanviet":"đồng dạng","note":"Đọc はんたいに. Hay đi với ～ではなく／～のに. Nêu kết quả hoặc tình huống trái ngược.","example":"彼は注意するどころか、反対に私を責めた。","example_reading":"かれはちゅういするどころか、はんたいにわたしをせめた。","example_meaning":"Anh ta không những không nhắc nhở mà ngược lại còn trách tôi.","examples":[{"example":"彼は注意するどころか、反対に私を責めた。","example_reading":"かれはちゅういするどころか、はんたいにわたしをせめた。","example_meaning":"Anh ta không những không nhắc nhở mà ngược lại còn trách tôi."},{"example":"薬を飲んだら、反対に具合が悪くなった。","example_reading":"くすりをのんだら、はんたいにぐあいがわるくなった。","example_meaning":"Uống thuốc xong tình trạng lại tệ đi."}],"level":"e1"},
{"word":"かえって","reading":"かえって","meaning":"ngược lại, lại càng","antonym":"予想通り（よそうどおり）: đúng như dự đoán / 案の定（あんのじょう）: đúng như dự đoán","antonym_hanviet":"dự tưởng thông / án định","note":"Kết quả trái với mong đợi (thường xấu). Hay đi với ～てしまった／～くなる.","example":"急いだせいで、かえって時間がかかってしまった。","example_reading":"いそいだせいで、かえってじかんがかかってしまった。","example_meaning":"Vì vội mà ngược lại tốn thêm thời gian.","examples":[{"example":"急いだせいで、かえって時間がかかってしまった。","example_reading":"いそいだせいで、かえってじかんがかかってしまった。","example_meaning":"Vì vội mà ngược lại tốn thêm thời gian."},{"example":"薬を飲み過ぎると、かえって体に悪い。","example_reading":"くすりをのみすぎると、かえってからだにわるい。","example_meaning":"Uống thuốc quá nhiều thì ngược lại có hại cho cơ thể."}],"level":"e1"},
{"word":"そもそも","reading":"そもそも","meaning":"vốn dĩ, ngay từ đầu","note":"Hay đi với ～が／～は, ～のか. Quay về nguồn gốc, tiền đề ban đầu.","example":"そもそも、この計画に無理があったのだ。","example_reading":"そもそも、このけいかくにむりがあったのだ。","example_meaning":"Ngay từ đầu kế hoạch này đã có điều bất hợp lý.","examples":[{"example":"そもそも、この計画に無理があったのだ。","example_reading":"そもそも、このけいかくにむりがあったのだ。","example_meaning":"Ngay từ đầu kế hoạch này đã có điều bất hợp lý."},{"example":"そもそも彼は、なぜこの会社に入ったのだろう。","example_reading":"そもそもかれは、なぜこのかいしゃにはいったのだろう。","example_meaning":"Vốn dĩ vì sao anh ấy lại vào công ty này nhỉ."}],"level":"e1"},
{"word":"結論として","reading":"けつろんとして","meaning":"kết luận lại, tóm lại","hanviet":"kết luận","note":"Đọc けつろんとして. Hay đi với ～と言える／～べきだ. Mở đầu phần kết luận trong văn viết.","example":"結論として、この計画は実行すべきだと考える。","example_reading":"けつろんとして、このけいかくはじっこうすべきだとかんがえる。","example_meaning":"Kết luận lại, tôi cho rằng nên thực hiện kế hoạch này.","examples":[{"example":"結論として、この計画は実行すべきだと考える。","example_reading":"けつろんとして、このけいかくはじっこうすべきだとかんがえる。","example_meaning":"Kết luận lại, tôi cho rằng nên thực hiện kế hoạch này."},{"example":"調査の結果、結論として原因は不明だった。","example_reading":"ちょうさのけっか、けつろんとしてげんいんはふめいだった。","example_meaning":"Kết quả điều tra, kết luận là chưa rõ nguyên nhân."}],"level":"e1"},
{"word":"確か","reading":"たしか","meaning":"hình như, nếu tôi nhớ đúng","hanviet":"xác","note":"Hay đi với ～はずだ, ～だったと思う. Khác 確かに (đúng là, quả thật).","example":"確か、駅の近くに郵便局があったはずだ。","example_reading":"たしか、えきのちかくにゆうびんきょくがあったはずだ。","example_meaning":"Nếu tôi nhớ không nhầm, gần ga có một bưu điện.","examples":[{"example":"確か、駅の近くに郵便局があったはずだ。","example_reading":"たしか、えきのちかくにゆうびんきょくがあったはずだ。","example_meaning":"Nếu tôi nhớ không nhầm, gần ga có một bưu điện."},{"example":"彼の誕生日は、確か三月だったと思う。","example_reading":"かれのたんじょうびは、たしかさんがつだったとおもう。","example_meaning":"Sinh nhật anh ấy hình như là tháng Ba."}],"level":"e1"},
{"word":"それでも","reading":"それでも","meaning":"dù vậy, dẫu thế","note":"Vẫn làm hoặc xảy ra dù tình huống trước bất lợi.","example":"反対された。それでも、私は自分の考えを変えなかった。","example_reading":"はんたいされた。それでも、わたしはじぶんのかんがえをかえなかった。","example_meaning":"Tôi bị phản đối. Dù vậy tôi vẫn không đổi ý.","examples":[{"example":"反対された。それでも、私は自分の考えを変えなかった。","example_reading":"はんたいされた。それでも、わたしはじぶんのかんがえをかえなかった。","example_meaning":"Tôi bị phản đối. Dù vậy tôi vẫn không đổi ý."},{"example":"疲れていた。それでも、彼は最後まで走り続けた。","example_reading":"つかれていた。それでも、かれはさいごまではしりつづけた。","example_meaning":"Anh ấy mệt. Dù vậy vẫn chạy đến cùng."}],"level":"e1"},
{"word":"間違いなく","reading":"まちがいなく","meaning":"chắc chắn, không sai","hanviet":"gian vi","antonym":"もしかしたら: biết đâu / ひょっとしたら: biết đâu / もしかすると: biết đâu","note":"Hay đi với ～はずだ, お届けする. Khẳng định chắc chắn.","example":"この荷物は、間違いなくお届けします。","example_reading":"このにもつは、まちがいなくおとどけします。","example_meaning":"Hành lý này chắc chắn sẽ được giao đến.","examples":[{"example":"この荷物は、間違いなくお届けします。","example_reading":"このにもつは、まちがいなくおとどけします。","example_meaning":"Hành lý này chắc chắn sẽ được giao đến."},{"example":"彼は間違いなく、明日の会議に来るはずだ。","example_reading":"かれはまちがいなく、あしたのかいぎにくるはずだ。","example_meaning":"Chắc chắn anh ấy sẽ đến cuộc họp ngày mai."}],"level":"e1"},
{"word":"だとすれば","reading":"だとすれば","meaning":"nếu vậy thì","note":"Dựa vào điều vừa nói để suy luận tiếp.","example":"彼が犯人ではない。だとすれば、真犯人は誰なのか。","example_reading":"かれがはんにんではない。だとすれば、しんはんにんはだれなのか。","example_meaning":"Anh ta không phải thủ phạm. Nếu vậy thì thủ phạm thật là ai?","examples":[{"example":"彼が犯人ではない。だとすれば、真犯人は誰なのか。","example_reading":"かれがはんにんではない。だとすれば、しんはんにんはだれなのか。","example_meaning":"Anh ta không phải thủ phạm. Nếu vậy thì thủ phạm thật là ai?"},{"example":"この道が通れないとする。だとすれば、遠回りするしかない。","example_reading":"このみちがとおれないとする。だとすれば、とおまわりするしかない。","example_meaning":"Giả sử đường này không đi được. Vậy thì chỉ còn cách đi đường vòng."}],"level":"e1"},
{"word":"だって","reading":"だって","meaning":"vì mà, tại vì (bào chữa)","note":"Khẩu ngữ, thân mật hoặc trẻ con.","example":"「なぜ食べないの？」「だって、嫌いなんだもん。」","example_reading":"「なぜたべないの？」「だって、きらいなんだもん。」","example_meaning":"\"Sao con không ăn?\" \"Tại vì con ghét mà.\"","examples":[{"example":"「なぜ食べないの？」「だって、嫌いなんだもん。」","example_reading":"「なぜたべないの？」「だって、きらいなんだもん。」","example_meaning":"\"Sao con không ăn?\" \"Tại vì con ghét mà.\""},{"example":"だって、仕方がなかったんだよ。","example_reading":"だって、しかたがなかったんだよ。","example_meaning":"Nhưng mà, đâu còn cách nào khác."}],"level":"e1"},
{"word":"おかげで","reading":"おかげで","meaning":"nhờ vậy mà","antonym":"せいで: tại vì (kết quả xấu)","note":"Thường tích cực; cũng dùng mỉa (おかげで失敗した).","example":"先生のおかげで、試験に合格できました。","example_reading":"せんせいのおかげで、しけんにごうかくできました。","example_meaning":"Nhờ thầy mà em đã đỗ kỳ thi.","examples":[{"example":"先生のおかげで、試験に合格できました。","example_reading":"せんせいのおかげで、しけんにごうかくできました。","example_meaning":"Nhờ thầy mà em đã đỗ kỳ thi."},{"example":"早く寝たおかげで、今朝は気分がいい。","example_reading":"はやくねたおかげで、けさはきぶんがいい。","example_meaning":"Nhờ ngủ sớm mà sáng nay tôi thấy khỏe."}],"level":"e1"},
{"word":"予想以上に","reading":"よそういじょうに","meaning":"hơn dự đoán","hanviet":"dự tưởng dĩ thượng","antonym":"予想通り（よそうどおり）: đúng như dự đoán / 予想以下に（よそういかに）: kém dự đoán","antonym_hanviet":"dự tưởng thông / dự tưởng dĩ hạ","note":"Hay đi với 売れる, 暑い, 増える.","example":"今年の夏は、予想以上に暑かった。","example_reading":"ことしのなつは、よそういじょうにあつかった。","example_meaning":"Mùa hè năm nay nóng hơn dự đoán.","examples":[{"example":"今年の夏は、予想以上に暑かった。","example_reading":"ことしのなつは、よそういじょうにあつかった。","example_meaning":"Mùa hè năm nay nóng hơn dự đoán."},{"example":"新商品は予想以上に売れて、在庫がなくなった。","example_reading":"しんしょうひんはよそういじょうにうれて、ざいこがなくなった。","example_meaning":"Sản phẩm mới bán chạy hơn dự đoán nên hết hàng tồn."}],"level":"e1"},
{"word":"大抵","reading":"たいてい","meaning":"thường, hầu hết","hanviet":"đại để","antonym":"稀に（まれに）: hiếm khi / めったに: hiếm khi","antonym_hanviet":"(không có âm Hán Việt) / ","note":"Hay đi với ～だ, ～の人. 大抵の人 = hầu hết mọi người.","example":"休日は大抵、家で本を読んでいる。","example_reading":"きゅうじつはたいてい、いえでほんをよんでいる。","example_meaning":"Ngày nghỉ tôi thường ở nhà đọc sách.","examples":[{"example":"休日は大抵、家で本を読んでいる。","example_reading":"きゅうじつはたいてい、いえでほんをよんでいる。","example_meaning":"Ngày nghỉ tôi thường ở nhà đọc sách."},{"example":"大抵の人は、最初は失敗するものだ。","example_reading":"たいていのひとは、さいしょはしっぱいするものだ。","example_meaning":"Hầu hết mọi người lúc đầu đều thất bại."}],"level":"e1"},
{"word":"要するに","reading":"ようするに","meaning":"tóm lại","hanviet":"yếu","antonym":"詳しく言えば（くわしくいえば）: nói chi tiết","antonym_hanviet":"tường ngôn","note":"Tóm tắt ý chính ở cuối câu hoặc đoạn.","example":"要するに、この計画には反対だということですね。","example_reading":"ようするに、このけいかくにははんたいだということですね。","example_meaning":"Tóm lại là bạn phản đối kế hoạch này, đúng không?","examples":[{"example":"要するに、この計画には反対だということですね。","example_reading":"ようするに、このけいかくにははんたいだということですね。","example_meaning":"Tóm lại là bạn phản đối kế hoạch này, đúng không?"},{"example":"長々と話していたが、要するにお金を貸してほしいのだ。","example_reading":"ながながとはなしていたが、ようするにおかねをかしてほしいのだ。","example_meaning":"Nói dài dòng nhưng tóm lại là muốn mượn tiền."}],"level":"e1"},
{"word":"しかも","reading":"しかも","meaning":"hơn nữa, lại còn","note":"Nối thêm thông tin cùng chiều, thường bổ sung điểm nổi bật. Đặt đầu câu hoặc giữa câu.","example":"この店は安くて、しかも味がいい。","example_reading":"このみせはやすくて、しかもあじがいい。","example_meaning":"Quán này rẻ mà lại còn ngon.","examples":[{"example":"この店は安くて、しかも味がいい。","example_reading":"このみせはやすくて、しかもあじがいい。","example_meaning":"Quán này rẻ mà lại còn ngon."},{"example":"昨日は遅刻をして、しかも大事な書類を忘れてしまった。","example_reading":"きのうはちこくをして、しかもだいじなしょるいをわすれてしまった。","example_meaning":"Hôm qua tôi đi muộn, lại còn quên mất tài liệu quan trọng."}],"level":"e1"},
{"word":"ちなみに","reading":"ちなみに","meaning":"nhân tiện, tiện thể","note":"Bổ sung thông tin phụ. Đặt đầu câu.","example":"来週は連休です。ちなみに、私は旅行に行く予定です。","example_reading":"らいしゅうはれんきゅうです。ちなみに、わたしはりょこうにいくよていです。","example_meaning":"Tuần sau là kỳ nghỉ dài. Nhân tiện, tôi dự định đi du lịch.","examples":[{"example":"来週は連休です。ちなみに、私は旅行に行く予定です。","example_reading":"らいしゅうはれんきゅうです。ちなみに、わたしはりょこうにいくよていです。","example_meaning":"Tuần sau là kỳ nghỉ dài. Nhân tiện, tôi dự định đi du lịch."},{"example":"今日の会議は三時からです。ちなみに、場所は第二会議室です。","example_reading":"きょうのかいぎはさんじからです。ちなみに、ばしょはだいにかいぎしつです。","example_meaning":"Cuộc họp hôm nay bắt đầu lúc 3 giờ. Tiện thể, địa điểm là phòng họp số 2."}],"level":"e1"},
{"word":"ところが","reading":"ところが","meaning":"thế nhưng, nào ngờ","note":"Hay đi với ～た. Nối câu: kết quả trái với mong đợi.","example":"早く出発した。ところが、道が混んでいて遅れてしまった。","example_reading":"はやくしゅっぱつした。ところが、みちがこんでいておくれてしまった。","example_meaning":"Tôi xuất phát sớm. Thế nhưng đường kẹt nên bị muộn.","examples":[{"example":"早く出発した。ところが、道が混んでいて遅れてしまった。","example_reading":"はやくしゅっぱつした。ところが、みちがこんでいておくれてしまった。","example_meaning":"Tôi xuất phát sớm. Thế nhưng đường kẹt nên bị muộn."},{"example":"簡単だと思っていた。ところが、実際にやってみると難しかった。","example_reading":"かんたんだとおもっていた。ところが、じっさいにやってみるとむずかしかった。","example_meaning":"Tôi tưởng dễ. Nào ngờ làm thử mới thấy khó."}],"level":"e1"},
{"word":"言い換えると","reading":"いいかえると","meaning":"nói cách khác","hanviet":"ngôn hoán","note":"Gần 言い換えれば. Diễn đạt lại điều vừa nói.","example":"彼は何も言わなかった。言い換えると、賛成も反対もしなかった。","example_reading":"かれはなにもいわなかった。いいかえると、さんせいもはんたいもしなかった。","example_meaning":"Anh ấy không nói gì. Nói cách khác, không tán thành cũng không phản đối.","examples":[{"example":"彼は何も言わなかった。言い換えると、賛成も反対もしなかった。","example_reading":"かれはなにもいわなかった。いいかえると、さんせいもはんたいもしなかった。","example_meaning":"Anh ấy không nói gì. Nói cách khác, không tán thành cũng không phản đối."},{"example":"これは値上げ、言い換えると実質的な負担増だ。","example_reading":"これはねあげ、いいかえるとじっしつてきなふたんぞうだ。","example_meaning":"Đây là tăng giá, nói cách khác là gánh nặng tăng thêm trên thực tế."}],"level":"e1"},
{"word":"すると","reading":"すると","meaning":"thế là, ngay sau đó","note":"Diễn tả kết quả hoặc phát hiện xảy ra ngay sau hành động.","example":"ドアを開けた。すると、猫が飛び出してきた。","example_reading":"ドアをあけた。すると、ねこがとびだしてきた。","example_meaning":"Tôi mở cửa. Thế là con mèo lao ra.","examples":[{"example":"ドアを開けた。すると、猫が飛び出してきた。","example_reading":"ドアをあけた。すると、ねこがとびだしてきた。","example_meaning":"Tôi mở cửa. Thế là con mèo lao ra."},{"example":"窓を開けてみた。すると、涼しい風が入ってきた。","example_reading":"まどをあけてみた。すると、すずしいかぜがはいってきた。","example_meaning":"Tôi thử mở cửa sổ. Lập tức gió mát lùa vào."}],"level":"e1"},
{"word":"なぜか","reading":"なぜか","meaning":"không hiểu sao","note":"Hay đi với 気がする, 涙が出る. Có cảm giác nhưng không rõ lý do.","example":"今日はなぜか朝から気分が優れない。","example_reading":"きょうはなぜかあさからきぶんがすぐれない。","example_meaning":"Hôm nay không hiểu sao từ sáng đã thấy khó ở.","examples":[{"example":"今日はなぜか朝から気分が優れない。","example_reading":"きょうはなぜかあさからきぶんがすぐれない。","example_meaning":"Hôm nay không hiểu sao từ sáng đã thấy khó ở."},{"example":"その歌を聞くと、なぜか涙が出てくる。","example_reading":"そのうたをきくと、なぜかなみだがでてくる。","example_meaning":"Nghe bài hát đó, không hiểu sao tôi lại rơi nước mắt."}],"level":"e1"},
{"word":"普通は","reading":"ふつうは","meaning":"bình thường thì","hanviet":"phổ thông","antonym":"例外的に（れいがいてきに）: ngoại lệ / 特別に（とくべつに）: đặc biệt","antonym_hanviet":"lệ ngoại đích / đặc biệt","note":"Nêu điều thông thường, thường đối lập với trường hợp đặc biệt.","example":"普通は、そんなことをしないはずだ。","example_reading":"ふつうは、そんなことをしないはずだ。","example_meaning":"Bình thường thì chẳng ai làm chuyện như thế.","examples":[{"example":"普通は、そんなことをしないはずだ。","example_reading":"ふつうは、そんなことをしないはずだ。","example_meaning":"Bình thường thì chẳng ai làm chuyện như thế."},{"example":"普通は、会議の前に資料を読んでおくものだ。","example_reading":"ふつうは、かいぎのまえにしりょうをよんでおくものだ。","example_meaning":"Thông thường, người ta đọc tài liệu trước cuộc họp."}],"level":"e1"},
{"word":"付け加えると","reading":"つけくわえると","meaning":"thêm vào đó","hanviet":"phụ gia","note":"Bổ sung thông tin vào điều vừa nói.","example":"付け加えると、この製品は保証期間が二年ある。","example_reading":"つけくわえると、このせいひんはほしょうきかんがにねんある。","example_meaning":"Thêm vào đó, sản phẩm này có thời hạn bảo hành hai năm.","examples":[{"example":"付け加えると、この製品は保証期間が二年ある。","example_reading":"つけくわえると、このせいひんはほしょうきかんがにねんある。","example_meaning":"Thêm vào đó, sản phẩm này có thời hạn bảo hành hai năm."},{"example":"付け加えると、会議は来週にも開かれる予定だ。","example_reading":"つけくわえると、かいぎはらいしゅうにもひらかれるよていだ。","example_meaning":"Thêm nữa, cuộc họp dự kiến cũng sẽ mở vào tuần sau."}],"level":"e1"},
{"word":"できれば","reading":"できれば","meaning":"nếu có thể","note":"Hay đi với ～たい, ～ほしい, ください. Nói nhẹ nhàng nguyện vọng.","example":"できれば、今日中に返事がほしい。","example_reading":"できれば、きょうじゅうにへんじがほしい。","example_meaning":"Nếu được, tôi muốn có câu trả lời trong hôm nay.","examples":[{"example":"できれば、今日中に返事がほしい。","example_reading":"できれば、きょうじゅうにへんじがほしい。","example_meaning":"Nếu được, tôi muốn có câu trả lời trong hôm nay."},{"example":"できれば、窓側の席にしてください。","example_reading":"できれば、まどがわのせきにしてください。","example_meaning":"Nếu được, xin cho tôi ngồi cạnh cửa sổ."}],"level":"e1"},
{"word":"だけど","reading":"だけど","meaning":"nhưng","note":"Khẩu ngữ, mềm hơn だが.","example":"彼は有名だ。だけど、偉そうにしない。","example_reading":"かれはゆうめいだ。だけど、えらそうにしない。","example_meaning":"Anh ấy nổi tiếng. Nhưng không hề tỏ ra hợm hĩnh.","examples":[{"example":"彼は有名だ。だけど、偉そうにしない。","example_reading":"かれはゆうめいだ。だけど、えらそうにしない。","example_meaning":"Anh ấy nổi tiếng. Nhưng không hề tỏ ra hợm hĩnh."},{"example":"分かってはいる。だけど、どうしてもできない。","example_reading":"わかってはいる。だけど、どうしてもできない。","example_meaning":"Tôi biết chứ. Nhưng làm thế nào cũng không được."}],"level":"e1"},
{"word":"予想通り","reading":"よそうどおり","meaning":"đúng như dự đoán","hanviet":"dự tưởng thông","antonym":"予想外に（よそうがいに）: ngoài dự đoán / 意外にも（いがいにも）: bất ngờ / 思いのほか: ngoài dự kiến","antonym_hanviet":"dự tưởng ngoại / ý ngoại / tư","note":"Hay đi với ～に. Kết quả không ngoài dự đoán.","example":"予想通り、試合は彼のチームが勝った。","example_reading":"よそうどおり、しあいはかれのチームがかった。","example_meaning":"Đúng như dự đoán, đội của anh ấy thắng trận.","examples":[{"example":"予想通り、試合は彼のチームが勝った。","example_reading":"よそうどおり、しあいはかれのチームがかった。","example_meaning":"Đúng như dự đoán, đội của anh ấy thắng trận."},{"example":"結果は予想通りで、特に驚きはなかった。","example_reading":"けっかはよそうどおりで、とくにおどろきはなかった。","example_meaning":"Kết quả đúng như dự đoán nên không có gì bất ngờ."}],"level":"e1"},
{"word":"何となく","reading":"なんとなく","meaning":"không hiểu sao, tự nhiên","hanviet":"hà","note":"Cảm giác mơ hồ, không rõ lý do.","example":"何となく、今日はいいことがありそうな気がする。","example_reading":"なんとなく、きょうはいいことがありそうなきがする。","example_meaning":"Không hiểu sao tôi có cảm giác hôm nay sẽ có chuyện tốt.","examples":[{"example":"何となく、今日はいいことがありそうな気がする。","example_reading":"なんとなく、きょうはいいことがありそうなきがする。","example_meaning":"Không hiểu sao tôi có cảm giác hôm nay sẽ có chuyện tốt."},{"example":"何となく見ていたテレビで、昔の友人を見つけた。","example_reading":"なんとなくみていたテレビで、むかしのゆうじんをみつけた。","example_meaning":"Tôi tình cờ thấy bạn cũ trên chiếc tivi xem vu vơ."}],"level":"e1"},
{"word":"わざと","reading":"わざと","meaning":"cố ý","antonym":"うっかり: vô ý / 思わず（おもわず）: bất giác / 偶然に（ぐうぜんに）: tình cờ","antonym_hanviet":" / tư / ngẫu nhiên","note":"Gần 故意に nhưng khẩu ngữ hơn. Hay đi với ～ない.","example":"彼はわざと負けて、子どもを喜ばせた。","example_reading":"かれはわざとまけて、こどもをよろこばせた。","example_meaning":"Anh ấy cố tình thua để làm đứa bé vui.","examples":[{"example":"彼はわざと負けて、子どもを喜ばせた。","example_reading":"かれはわざとまけて、こどもをよろこばせた。","example_meaning":"Anh ấy cố tình thua để làm đứa bé vui."},{"example":"わざと聞こえないふりをした。","example_reading":"わざときこえないふりをした。","example_meaning":"Tôi cố ý giả vờ không nghe thấy."}],"level":"e1"},
{"word":"思い切って","reading":"おもいきって","meaning":"quyết tâm, dám làm","hanviet":"tư thiết","antonym":"ためらって: do dự / 遠慮して（えんりょして）: ngại ngần","antonym_hanviet":" / viễn lự","note":"Hay đi với ～してみる, 言う, 辞める.","example":"思い切って、彼女に気持ちを伝えてみた。","example_reading":"おもいきって、かのじょにきもちをつたえてみた。","example_meaning":"Tôi đánh liều nói ra tình cảm với cô ấy.","examples":[{"example":"思い切って、彼女に気持ちを伝えてみた。","example_reading":"おもいきって、かのじょにきもちをつたえてみた。","example_meaning":"Tôi đánh liều nói ra tình cảm với cô ấy."},{"example":"思い切って、会社を辞めて留学することにした。","example_reading":"おもいきって、かいしゃをやめてりゅうがくすることにした。","example_meaning":"Tôi quyết tâm nghỉ việc để đi du học."}],"level":"e1"},
{"word":"精一杯","reading":"せいいっぱい","meaning":"hết sức mình","hanviet":"tinh nhất bôi","antonym":"手を抜いて（てをぬいて）: làm qua loa / 適当に（てきとうに）: qua loa","antonym_hanviet":"thủ bạt / thích đương","note":"Hay đi với 頑張る, やる.","example":"結果はどうあれ、精一杯頑張るつもりだ。","example_reading":"けっかはどうあれ、せいいっぱいがんばるつもりだ。","example_meaning":"Dù kết quả thế nào, tôi vẫn định cố gắng hết sức.","examples":[{"example":"結果はどうあれ、精一杯頑張るつもりだ。","example_reading":"けっかはどうあれ、せいいっぱいがんばるつもりだ。","example_meaning":"Dù kết quả thế nào, tôi vẫn định cố gắng hết sức."},{"example":"私にできるのは、精一杯やることだけだ。","example_reading":"わたしにできるのは、せいいっぱいやることだけだ。","example_meaning":"Điều tôi có thể làm chỉ là cố hết sức."}],"level":"e1"},
{"word":"一方","reading":"いっぽう","meaning":"mặt khác, trong khi đó","hanviet":"nhất phương","note":"Đọc いっぽう. Hay đi với ～一方で／～一方、. Đối chiếu hai mặt hoặc hai sự việc song song.","example":"この製品は便利な一方、値段が高い。","example_reading":"このせいひんはべんりないっぽう、ねだんがたかい。","example_meaning":"Sản phẩm này tiện lợi nhưng mặt khác giá lại cao.","examples":[{"example":"この製品は便利な一方、値段が高い。","example_reading":"このせいひんはべんりないっぽう、ねだんがたかい。","example_meaning":"Sản phẩm này tiện lợi nhưng mặt khác giá lại cao."},{"example":"兄は社交的だ。一方、弟は内向的だ。","example_reading":"あにはしゃこうてきだ。いっぽう、おとうとはないこうてきだ。","example_meaning":"Anh trai hòa đồng. Trái lại, em trai hướng nội."}],"level":"e1"},
{"word":"だとしても","reading":"だとしても","meaning":"dù là vậy đi nữa","note":"Chấp nhận điều trước nhưng vẫn phản bác.","example":"忙しいのは分かる。だとしても、連絡くらいはできたはずだ。","example_reading":"いそがしいのはわかる。だとしても、れんらくくらいはできたはずだ。","example_meaning":"Tôi hiểu là bận. Dù vậy, ít ra cũng có thể liên lạc.","examples":[{"example":"忙しいのは分かる。だとしても、連絡くらいはできたはずだ。","example_reading":"いそがしいのはわかる。だとしても、れんらくくらいはできたはずだ。","example_meaning":"Tôi hiểu là bận. Dù vậy, ít ra cũng có thể liên lạc."},{"example":"彼が悪かったとしよう。だとしても、あんな言い方はないと思う。","example_reading":"かれがわるかったとしよう。だとしても、あんないいかたはないとおもう。","example_meaning":"Cứ cho là anh ấy sai. Dù vậy, tôi nghĩ cũng không nên nói như thế."}],"level":"e1"},
{"word":"そうなると","reading":"そうなると","meaning":"nếu thế thì","note":"Nêu kết quả tất yếu của tình huống vừa nói.","example":"雨が降るかもしれない。そうなると、試合は延期になる。","example_reading":"あめがふるかもしれない。そうなると、しあいはえんきになる。","example_meaning":"Có thể trời sẽ mưa. Nếu thế thì trận đấu sẽ hoãn.","examples":[{"example":"雨が降るかもしれない。そうなると、試合は延期になる。","example_reading":"あめがふるかもしれない。そうなると、しあいはえんきになる。","example_meaning":"Có thể trời sẽ mưa. Nếu thế thì trận đấu sẽ hoãn."},{"example":"彼が辞めたら、人手が足りなくなる。そうなると、新しい人を雇うしかない。","example_reading":"かれがやめたら、ひとでがたりなくなる。そうなると、あたらしいひとをやとうしかない。","example_meaning":"Nếu anh ấy nghỉ thì thiếu người. Khi đó chỉ còn cách thuê người mới."}],"level":"e1"},
{"word":"正直なところ","reading":"しょうじきなところ","meaning":"nói thật","hanviet":"chính trực","antonym":"建前では（たてまえでは）: trên danh nghĩa / 表向きは（おもてむきは）: bề ngoài","antonym_hanviet":"kiến tiền / biểu hướng","note":"Dùng khi thú nhận suy nghĩ thật.","example":"正直なところ、この仕事は私には荷が重い。","example_reading":"しょうじきなところ、このしごとはわたしにはにがおもい。","example_meaning":"Nói thật, công việc này quá sức với tôi.","examples":[{"example":"正直なところ、この仕事は私には荷が重い。","example_reading":"しょうじきなところ、このしごとはわたしにはにがおもい。","example_meaning":"Nói thật, công việc này quá sức với tôi."},{"example":"正直なところ、まだ自信がありません。","example_reading":"しょうじきなところ、まだじしんがありません。","example_meaning":"Nói thật, tôi vẫn chưa tự tin."}],"level":"e1"},
{"word":"簡単に言えば","reading":"かんたんにいえば","meaning":"nói đơn giản","hanviet":"giản đơn ngôn","antonym":"詳しく言えば（くわしくいえば）: nói chi tiết","antonym_hanviet":"tường ngôn","note":"Tóm lại một cách dễ hiểu.","example":"簡単に言えば、この制度は税金を減らす仕組みだ。","example_reading":"かんたんにいえば、このせいどはぜいきんをへらすしくみだ。","example_meaning":"Nói đơn giản, chế độ này là cơ chế giảm thuế.","examples":[{"example":"簡単に言えば、この制度は税金を減らす仕組みだ。","example_reading":"かんたんにいえば、このせいどはぜいきんをへらすしくみだ。","example_meaning":"Nói đơn giản, chế độ này là cơ chế giảm thuế."},{"example":"簡単に言えば、もっと練習が必要だということだ。","example_reading":"かんたんにいえば、もっとれんしゅうがひつようだということだ。","example_meaning":"Nói đơn giản là cần luyện tập nhiều hơn."}],"level":"e1"},
{"word":"補足すると","reading":"ほそくすると","meaning":"bổ sung thêm","hanviet":"bổ túc","note":"Dùng để thêm thông tin phụ giúp hiểu rõ hơn.","example":"補足すると、この規則は例外もあります。","example_reading":"ほそくすると、このきそくはれいがいもあります。","example_meaning":"Bổ sung thêm, quy tắc này cũng có ngoại lệ.","examples":[{"example":"補足すると、この規則は例外もあります。","example_reading":"ほそくすると、このきそくはれいがいもあります。","example_meaning":"Bổ sung thêm, quy tắc này cũng có ngoại lệ."},{"example":"補足すると、費用は全て会社が負担します。","example_reading":"ほそくすると、ひようはすべてかいしゃがふたんします。","example_meaning":"Xin bổ sung, toàn bộ chi phí do công ty chịu."}],"level":"e1"},
{"word":"具体的には","reading":"ぐたいてきには","meaning":"cụ thể là","hanviet":"cụ thể đích","antonym":"抽象的には（ちゅうしょうてきには）: nói trừu tượng / 大まかに言えば（おおまかにいえば）: nói đại khái","antonym_hanviet":"trừu tượng đích / đại ngôn","note":"Dùng để chuyển sang giải thích chi tiết.","example":"具体的には、どのような対策を考えていますか。","example_reading":"ぐたいてきには、どのようなたいさくをかんがえていますか。","example_meaning":"Cụ thể thì bạn đang nghĩ tới đối sách nào?","examples":[{"example":"具体的には、どのような対策を考えていますか。","example_reading":"ぐたいてきには、どのようなたいさくをかんがえていますか。","example_meaning":"Cụ thể thì bạn đang nghĩ tới đối sách nào?"},{"example":"具体的には、来月から新しい制度が始まります。","example_reading":"ぐたいてきには、らいげつからあたらしいせいどがはじまります。","example_meaning":"Cụ thể là từ tháng sau chế độ mới sẽ bắt đầu."}],"level":"e1"},
{"word":"場合によっては","reading":"ばあいによっては","meaning":"tùy trường hợp thì","hanviet":"trường hợp","note":"Hay đi với ～こともある, ～かもしれない.","example":"場合によっては、予定を変更することもある。","example_reading":"ばあいによっては、よていをへんこうすることもある。","example_meaning":"Tùy trường hợp, đôi khi chúng tôi thay đổi kế hoạch.","examples":[{"example":"場合によっては、予定を変更することもある。","example_reading":"ばあいによっては、よていをへんこうすることもある。","example_meaning":"Tùy trường hợp, đôi khi chúng tôi thay đổi kế hoạch."},{"example":"天候が悪いと、場合によっては出発が遅れます。","example_reading":"てんこうがわるいと、ばあいによってはしゅっぱつがおくれます。","example_meaning":"Nếu thời tiết xấu, tùy trường hợp việc khởi hành sẽ bị chậm."}],"level":"e1"},
{"word":"なぜなら","reading":"なぜなら","meaning":"bởi vì, lý do là","note":"Thường đi với ～からだ／～ためだ ở cuối câu. Nêu lý do cho điều vừa nói. Văn viết.","example":"私はこの案に反対です。なぜなら、費用が高すぎるからです。","example_reading":"わたしはこのあんにはんたいです。なぜなら、ひようがたかすぎるからです。","example_meaning":"Tôi phản đối đề án này. Bởi vì chi phí quá cao.","examples":[{"example":"私はこの案に反対です。なぜなら、費用が高すぎるからです。","example_reading":"わたしはこのあんにはんたいです。なぜなら、ひようがたかすぎるからです。","example_meaning":"Tôi phản đối đề án này. Bởi vì chi phí quá cao."},{"example":"彼は休んだ。なぜなら、熱があったからだ。","example_reading":"かれはやすんだ。なぜなら、ねつがあったからだ。","example_meaning":"Anh ấy nghỉ. Bởi vì anh ấy bị sốt."}],"level":"e1"},
{"word":"ただし","reading":"ただし","meaning":"tuy nhiên, có điều là","note":"Thêm điều kiện hoặc ngoại lệ. Văn viết, hay thấy trong quy định.","example":"入場は無料です。ただし、飲み物は各自でご用意ください。","example_reading":"にゅうじょうはむりょうです。ただし、のみものはかくじでごよういください。","example_meaning":"Vào cửa miễn phí. Tuy nhiên, đồ uống xin mỗi người tự chuẩn bị.","examples":[{"example":"入場は無料です。ただし、飲み物は各自でご用意ください。","example_reading":"にゅうじょうはむりょうです。ただし、のみものはかくじでごよういください。","example_meaning":"Vào cửa miễn phí. Tuy nhiên, đồ uống xin mỗi người tự chuẩn bị."},{"example":"明日は晴れるでしょう。ただし、夜は雨になるかもしれません。","example_reading":"あしたははれるでしょう。ただし、よるはあめになるかもしれません。","example_meaning":"Ngày mai trời sẽ nắng. Có điều, buổi tối có thể mưa."}],"level":"e1"},
{"word":"いずれにしても","reading":"いずれにしても","meaning":"dù thế nào đi nữa","note":"Hay đi với ～必要がある, ～てください. Bỏ qua khác biệt để đi đến kết luận chung. Cũng nói いずれにせよ.","example":"いずれにしても、明日までに結論を出さなければならない。","example_reading":"いずれにしても、あしたまでにけつろんをださなければならない。","example_meaning":"Dù thế nào đi nữa, phải đưa ra kết luận trước ngày mai.","examples":[{"example":"いずれにしても、明日までに結論を出さなければならない。","example_reading":"いずれにしても、あしたまでにけつろんをださなければならない。","example_meaning":"Dù thế nào đi nữa, phải đưa ra kết luận trước ngày mai."},{"example":"理由はいずれにしても、遅刻は許されない。","example_reading":"りゆうはいずれにしても、ちこくはゆるされない。","example_meaning":"Dù lý do gì đi nữa, đi trễ cũng không được phép."}],"level":"e1"},
{"word":"あるいは","reading":"あるいは","meaning":"hoặc là; có lẽ","note":"Hay đi với A、あるいはB. Nêu lựa chọn; cũng nghĩa 'có khi' đi với ～かもしれない.","example":"電話、あるいはメールでご連絡ください。","example_reading":"でんわ、あるいはメールでごれんらくください。","example_meaning":"Xin liên lạc qua điện thoại hoặc email.","examples":[{"example":"電話、あるいはメールでご連絡ください。","example_reading":"でんわ、あるいはメールでごれんらくください。","example_meaning":"Xin liên lạc qua điện thoại hoặc email."},{"example":"彼は病気か、あるいは忘れているのかもしれない。","example_reading":"かれはびょうきか、あるいはわすれているのかもしれない。","example_meaning":"Anh ấy có thể bị bệnh, hoặc cũng có thể là quên."}],"level":"e1"},
{"word":"それなら","reading":"それなら","meaning":"nếu vậy thì","note":"Đưa ra lời khuyên hoặc đề nghị dựa trên điều người kia vừa nói.","example":"「頭が痛いんです。」「それなら、早く帰ったほうがいいよ。」","example_reading":"「あたまがいたいんです。」「それなら、はやくかえったほうがいいよ。」","example_meaning":"\"Em đau đầu.\" \"Nếu vậy thì nên về sớm đi.\"","examples":[{"example":"「頭が痛いんです。」「それなら、早く帰ったほうがいいよ。」","example_reading":"「あたまがいたいんです。」「それなら、はやくかえったほうがいいよ。」","example_meaning":"\"Em đau đầu.\" \"Nếu vậy thì nên về sớm đi.\""},{"example":"駅まで行くんですか。それなら、一緒に行きましょう。","example_reading":"えきまでいくんですか。それなら、いっしょにいきましょう。","example_meaning":"Bạn đi đến ga à? Nếu vậy thì cùng đi nhé."}],"level":"e1"},
{"word":"ある意味","reading":"あるいみ","meaning":"theo một nghĩa nào đó","hanviet":"ý vị","note":"Hay dùng ある意味で／ある意味では. Nhìn từ một góc độ, không phải toàn bộ.","example":"ある意味、失敗したことが良い経験になった。","example_reading":"あるいみ、しっぱいしたことがよいけいけんになった。","example_meaning":"Theo một nghĩa nào đó, thất bại lại thành kinh nghiệm tốt.","examples":[{"example":"ある意味、失敗したことが良い経験になった。","example_reading":"あるいみ、しっぱいしたことがよいけいけんになった。","example_meaning":"Theo một nghĩa nào đó, thất bại lại thành kinh nghiệm tốt."},{"example":"それはある意味、仕方のないことかもしれない。","example_reading":"それはあるいみ、しかたのないことかもしれない。","example_meaning":"Điều đó theo một nghĩa nào đó có thể là bất khả kháng."}],"level":"e1"},
{"word":"それにしても","reading":"それにしても","meaning":"dù vậy thì, mà này (ngạc nhiên)","note":"Bày tỏ ngạc nhiên hoặc bất mãn dù đã chấp nhận điều trước.","example":"遅れるのは仕方ない。それにしても、連絡くらいほしかった。","example_reading":"おくれるのはしかたない。それにしても、れんらくくらいほしかった。","example_meaning":"Đến muộn thì đành chịu. Dù vậy, ít ra cũng nên báo cho tôi.","examples":[{"example":"遅れるのは仕方ない。それにしても、連絡くらいほしかった。","example_reading":"おくれるのはしかたない。それにしても、れんらくくらいほしかった。","example_meaning":"Đến muộn thì đành chịu. Dù vậy, ít ra cũng nên báo cho tôi."},{"example":"それにしても、今日は暑いですね。","example_reading":"それにしても、きょうはあついですね。","example_meaning":"Mà này, hôm nay nóng thật nhỉ."}],"level":"e1"},
{"word":"念のため","reading":"ねんのため","meaning":"để cho chắc","hanviet":"niệm","note":"Hay đi với ～ておく, ～てください. Cũng nói ねんのために.","example":"念のため、もう一度確認してください。","example_reading":"ねんのため、もういちどかくにんしてください。","example_meaning":"Để cho chắc, xin hãy kiểm tra lại một lần nữa.","examples":[{"example":"念のため、もう一度確認してください。","example_reading":"ねんのため、もういちどかくにんしてください。","example_meaning":"Để cho chắc, xin hãy kiểm tra lại một lần nữa."},{"example":"雨が降るかもしれないので、念のため傘を持っていく。","example_reading":"あめがふるかもしれないので、ねんのためかさをもっていく。","example_meaning":"Có thể mưa nên tôi mang ô theo cho chắc."}],"level":"e1"},
{"word":"いずれにせよ","reading":"いずれにせよ","meaning":"dù sao đi nữa","note":"Gần いずれにしても nhưng trang trọng hơn.","example":"いずれにせよ、準備だけは早めに始めておこう。","example_reading":"いずれにせよ、じゅんびだけははやめにはじめておこう。","example_meaning":"Dù sao đi nữa, cứ bắt đầu chuẩn bị sớm đã.","examples":[{"example":"いずれにせよ、準備だけは早めに始めておこう。","example_reading":"いずれにせよ、じゅんびだけははやめにはじめておこう。","example_meaning":"Dù sao đi nữa, cứ bắt đầu chuẩn bị sớm đã."},{"example":"理由はいずれにせよ、遅刻は遅刻だ。","example_reading":"りゆうはいずれにせよ、ちこくはちこくだ。","example_meaning":"Dù lý do là gì, đến muộn vẫn là đến muộn."}],"level":"e1"},
{"word":"逆に言えば","reading":"ぎゃくにいえば","meaning":"nói ngược lại","hanviet":"nghịch ngôn","note":"Nêu mặt đối lập của điều vừa nói.","example":"欠点が多い。逆に言えば、伸びしろがあるということだ。","example_reading":"けってんがおおい。ぎゃくにいえば、のびしろがあるということだ。","example_meaning":"Nhiều khuyết điểm. Nói ngược lại, tức là còn nhiều dư địa phát triển.","examples":[{"example":"欠点が多い。逆に言えば、伸びしろがあるということだ。","example_reading":"けってんがおおい。ぎゃくにいえば、のびしろがあるということだ。","example_meaning":"Nhiều khuyết điểm. Nói ngược lại, tức là còn nhiều dư địa phát triển."},{"example":"安い商品は、逆に言えば品質が低い可能性もある。","example_reading":"やすいしょうひんは、ぎゃくにいえばひんしつがひくいかのうせいもある。","example_meaning":"Hàng rẻ, nói ngược lại cũng có khả năng chất lượng thấp."}],"level":"e1"},
{"word":"まとめると","reading":"まとめると","meaning":"tóm lại","antonym":"詳しく言えば（くわしくいえば）: nói chi tiết","antonym_hanviet":"tường ngôn","note":"Khẩu ngữ. Tóm gọn nội dung.","example":"まとめると、今回の会議の結論は二つある。","example_reading":"まとめると、こんかいのかいぎのけつろんはふたつある。","example_meaning":"Tóm lại, cuộc họp lần này có hai kết luận.","examples":[{"example":"まとめると、今回の会議の結論は二つある。","example_reading":"まとめると、こんかいのかいぎのけつろんはふたつある。","example_meaning":"Tóm lại, cuộc họp lần này có hai kết luận."},{"example":"まとめると、準備不足が失敗の原因だった。","example_reading":"まとめると、じゅんびぶそくがしっぱいのげんいんだった。","example_meaning":"Tóm lại, thiếu chuẩn bị là nguyên nhân thất bại."}],"level":"e1"},
{"word":"通常は","reading":"つうじょうは","meaning":"thông thường","hanviet":"thông thường","antonym":"例外的に（れいがいてきに）: ngoại lệ","antonym_hanviet":"lệ ngoại đích","note":"Trang trọng. Dùng nói về quy trình, thời gian thông thường.","example":"通常は、返事に三日ほどかかります。","example_reading":"つうじょうは、へんじにみっかほどかかります。","example_meaning":"Thông thường phải mất khoảng ba ngày để trả lời.","examples":[{"example":"通常は、返事に三日ほどかかります。","example_reading":"つうじょうは、へんじにみっかほどかかります。","example_meaning":"Thông thường phải mất khoảng ba ngày để trả lời."},{"example":"通常は午前九時に開店するが、今日は休みだ。","example_reading":"つうじょうはごぜんくじにかいてんするが、きょうはやすみだ。","example_meaning":"Thường thì cửa hàng mở lúc chín giờ sáng, nhưng hôm nay nghỉ."}],"level":"e1"},
{"word":"ひょっとしたら","reading":"ひょっとしたら","meaning":"biết đâu","antonym":"間違いなく（まちがいなく）: chắc chắn","antonym_hanviet":"gian vi","note":"Đi với ～かもしれない. Khả năng thấp nhưng có thể.","example":"ひょっとしたら、彼は来ないかもしれない。","example_reading":"ひょっとしたら、かれはこないかもしれない。","example_meaning":"Biết đâu anh ấy sẽ không đến.","examples":[{"example":"ひょっとしたら、彼は来ないかもしれない。","example_reading":"ひょっとしたら、かれはこないかもしれない。","example_meaning":"Biết đâu anh ấy sẽ không đến."},{"example":"ひょっとしたら、あの人は私の叔父かもしれない。","example_reading":"ひょっとしたら、あのひとはわたしのおじかもしれない。","example_meaning":"Biết đâu người đó là chú tôi."}],"level":"e1"},
{"word":"実際のところ","reading":"じっさいのところ","meaning":"thực tế thì","hanviet":"thực tế","antonym":"理想を言えば（りそうをいえば）: nếu nói lý tưởng","antonym_hanviet":"lý tưởng ngôn","note":"Dùng khi nói sự thật khác với vẻ ngoài.","example":"実際のところ、売り上げは思ったほど伸びていない。","example_reading":"じっさいのところ、うりあげはおもったほどのびていない。","example_meaning":"Thực tế thì doanh thu không tăng như đã nghĩ.","examples":[{"example":"実際のところ、売り上げは思ったほど伸びていない。","example_reading":"じっさいのところ、うりあげはおもったほどのびていない。","example_meaning":"Thực tế thì doanh thu không tăng như đã nghĩ."},{"example":"実際のところ、彼がどう考えているのかは分からない。","example_reading":"じっさいのところ、かれがどうかんがえているのかはわからない。","example_meaning":"Thực ra tôi không biết anh ấy nghĩ thế nào."}],"level":"e1"},
{"word":"現実には","reading":"げんじつには","meaning":"trên thực tế","hanviet":"hiện thực","antonym":"理論上は（りろんじょうは）: về lý thuyết / 理想を言えば（りそうをいえば）: nếu nói lý tưởng","antonym_hanviet":"lý luận thượng / lý tưởng ngôn","note":"Đối lập với lý tưởng hoặc kế hoạch.","example":"計画は立派だが、現実には実行が難しい。","example_reading":"けいかくはりっぱだが、げんじつにはじっこうがむずかしい。","example_meaning":"Kế hoạch thì hay nhưng trên thực tế khó thực hiện.","examples":[{"example":"計画は立派だが、現実には実行が難しい。","example_reading":"けいかくはりっぱだが、げんじつにはじっこうがむずかしい。","example_meaning":"Kế hoạch thì hay nhưng trên thực tế khó thực hiện."},{"example":"現実には、すべての人が同じ条件で働けるわけではない。","example_reading":"げんじつには、すべてのひとがおなじじょうけんではたらけるわけではない。","example_meaning":"Trên thực tế, không phải ai cũng làm việc trong cùng điều kiện."}],"level":"e1"},
{"word":"全体として","reading":"ぜんたいとして","meaning":"nhìn chung","hanviet":"toàn thể","antonym":"部分的には（ぶぶんてきには）: xét từng phần / 個別には（こべつには）: xét riêng","antonym_hanviet":"bộ phân đích / cá biệt","note":"Đánh giá toàn bộ, không đi vào chi tiết.","example":"全体として、今回の結果には満足している。","example_reading":"ぜんたいとして、こんかいのけっかにはまんぞくしている。","example_meaning":"Nhìn chung, tôi hài lòng với kết quả lần này.","examples":[{"example":"全体として、今回の結果には満足している。","example_reading":"ぜんたいとして、こんかいのけっかにはまんぞくしている。","example_meaning":"Nhìn chung, tôi hài lòng với kết quả lần này."},{"example":"全体として、計画は予定どおりに進んでいる。","example_reading":"ぜんたいとして、けいかくはよていどおりにすすんでいる。","example_meaning":"Nhìn chung, kế hoạch đang tiến hành đúng dự kiến."}],"level":"e1"},
{"word":"または","reading":"または","meaning":"hoặc","note":"Nối hai lựa chọn tương đương, thường dùng trong văn viết, thông báo.","example":"現金またはカードでお支払いください。","example_reading":"げんきんまたはカードでおしはらいください。","example_meaning":"Xin thanh toán bằng tiền mặt hoặc thẻ.","examples":[{"example":"現金またはカードでお支払いください。","example_reading":"げんきんまたはカードでおしはらいください。","example_meaning":"Xin thanh toán bằng tiền mặt hoặc thẻ."},{"example":"申し込みは、電話または窓口で受け付けます。","example_reading":"もうしこみは、でんわまたはまどぐちでうけつけます。","example_meaning":"Đơn đăng ký được nhận qua điện thoại hoặc tại quầy."}],"level":"e1"},
{"word":"もしくは","reading":"もしくは","meaning":"hoặc là (trang trọng)","note":"Trang trọng hơn または. Hay dùng trong văn bản, quy định.","example":"身分証明書、もしくはパスポートを持参してください。","example_reading":"みぶんしょうめいしょ、もしくはパスポートをじさんしてください。","example_meaning":"Xin mang theo giấy tờ tùy thân hoặc hộ chiếu.","examples":[{"example":"身分証明書、もしくはパスポートを持参してください。","example_reading":"みぶんしょうめいしょ、もしくはパスポートをじさんしてください。","example_meaning":"Xin mang theo giấy tờ tùy thân hoặc hộ chiếu."},{"example":"この書類は、本人もしくは代理人が提出すること。","example_reading":"このしょるいは、ほんにんもしくはだいりにんがていしゅつすること。","example_meaning":"Hồ sơ này do bản thân hoặc người đại diện nộp."}],"level":"e1"},
{"word":"もっとも","reading":"もっとも","meaning":"tuy vậy, có điều (bổ sung hạn chế)","note":"Bổ sung ý hạn chế cho điều vừa nói. Đặt đầu câu. Còn nghĩa \"hợp lý\" (もっともだ).","example":"誰でも参加できます。もっとも、事前の申し込みは必要ですが。","example_reading":"だれでもさんかできます。もっとも、じぜんのもうしこみはひつようですが。","example_meaning":"Ai cũng có thể tham gia. Có điều cần đăng ký trước.","examples":[{"example":"誰でも参加できます。もっとも、事前の申し込みは必要ですが。","example_reading":"だれでもさんかできます。もっとも、じぜんのもうしこみはひつようですが。","example_meaning":"Ai cũng có thể tham gia. Có điều cần đăng ký trước."},{"example":"この店は人気がある。もっとも、私は一度しか行ったことがないが。","example_reading":"このみせはにんきがある。もっとも、わたしはいちどしかいったことがないが。","example_meaning":"Quán này nổi tiếng. Có điều tôi mới đi đúng một lần."}],"level":"e1"},
{"word":"なお","reading":"なお","meaning":"ngoài ra, hơn nữa; vẫn còn","note":"Bổ sung thông báo (văn viết trang trọng). Cũng nghĩa \"vẫn\" giống まだ.","example":"会議は十時に始まります。なお、資料は当日配布いたします。","example_reading":"かいぎはじゅうじにはじまります。なお、しりょうはとうじつはいふいたします。","example_meaning":"Cuộc họp bắt đầu lúc 10 giờ. Ngoài ra, tài liệu sẽ được phát vào ngày họp.","examples":[{"example":"会議は十時に始まります。なお、資料は当日配布いたします。","example_reading":"かいぎはじゅうじにはじまります。なお、しりょうはとうじつはいふいたします。","example_meaning":"Cuộc họp bắt đầu lúc 10 giờ. Ngoài ra, tài liệu sẽ được phát vào ngày họp."},{"example":"医者に止められても、彼はなお仕事を続けた。","example_reading":"いしゃにとめられても、かれはなおしごとをつづけた。","example_meaning":"Dù bác sĩ ngăn cản, anh ấy vẫn tiếp tục làm việc."}],"level":"e1"},
{"word":"何と","reading":"なんと","meaning":"thật là, không ngờ","hanviet":"hà","note":"Dùng khi ngạc nhiên. Hay có dạng 何と～のだろう.","example":"何と美しい景色だろう。","example_reading":"なんとうつくしいけしきだろう。","example_meaning":"Phong cảnh đẹp làm sao!","examples":[{"example":"何と美しい景色だろう。","example_reading":"なんとうつくしいけしきだろう。","example_meaning":"Phong cảnh đẹp làm sao!"},{"example":"開けてみると、何と中は空っぽだった。","example_reading":"あけてみると、なんとなかはからっぽだった。","example_meaning":"Mở ra xem thì không ngờ bên trong trống rỗng."}],"level":"e1"},
{"word":"それなのに","reading":"それなのに","meaning":"vậy mà","antonym":"だから: vì vậy","note":"Nối kết quả trái với kỳ vọng, hàm ý tiếc nuối hoặc bất mãn.","example":"毎日勉強した。それなのに、試験に落ちてしまった。","example_reading":"まいにちべんきょうした。それなのに、しけんにおちてしまった。","example_meaning":"Tôi học mỗi ngày. Vậy mà vẫn thi trượt.","examples":[{"example":"毎日勉強した。それなのに、試験に落ちてしまった。","example_reading":"まいにちべんきょうした。それなのに、しけんにおちてしまった。","example_meaning":"Tôi học mỗi ngày. Vậy mà vẫn thi trượt."},{"example":"約束をした。それなのに、彼は来なかった。","example_reading":"やくそくをした。それなのに、かれはこなかった。","example_meaning":"Đã hẹn rồi. Vậy mà anh ấy không đến."}],"level":"e1"},
{"word":"第一に","reading":"だいいちに","meaning":"thứ nhất, trước hết","hanviet":"đệ nhất","note":"Đi với 第二に. Dùng liệt kê lý do hoặc điểm quan trọng.","example":"第一に、安全を確保しなければならない。","example_reading":"だいいちに、あんぜんをかくほしなければならない。","example_meaning":"Trước hết, phải đảm bảo an toàn.","examples":[{"example":"第一に、安全を確保しなければならない。","example_reading":"だいいちに、あんぜんをかくほしなければならない。","example_meaning":"Trước hết, phải đảm bảo an toàn."},{"example":"この計画には反対だ。第一に、費用が高すぎる。","example_reading":"このけいかくにははんたいだ。だいいちに、ひようがたかすぎる。","example_meaning":"Tôi phản đối kế hoạch này. Thứ nhất, chi phí quá cao."}],"level":"e1"},
{"word":"思いがけず","reading":"おもいがけず","meaning":"bất ngờ, không dè","hanviet":"tư","antonym":"予想通り（よそうどおり）: đúng như dự đoán / 案の定（あんのじょう）: đúng như dự đoán","antonym_hanviet":"dự tưởng thông / án định","note":"Hay đi với 会う, 手に入る, 誘われる.","example":"駅で思いがけず、昔の友人に会った。","example_reading":"えきでおもいがけず、むかしのゆうじんにあった。","example_meaning":"Ở ga, tôi tình cờ gặp lại người bạn cũ.","examples":[{"example":"駅で思いがけず、昔の友人に会った。","example_reading":"えきでおもいがけず、むかしのゆうじんにあった。","example_meaning":"Ở ga, tôi tình cờ gặp lại người bạn cũ."},{"example":"思いがけず、新しい仕事の誘いを受けた。","example_reading":"おもいがけず、あたらしいしごとのさそいをうけた。","example_meaning":"Tôi bất ngờ nhận được lời mời làm việc mới."}],"level":"e1"},
{"word":"それはさておき","reading":"それはさておき","meaning":"chuyện đó để sau, quay lại chính","note":"Dùng khi gác chuyện đang nói để chuyển sang việc quan trọng hơn.","example":"それはさておき、本題に入りましょう。","example_reading":"それはさておき、ほんだいにはいりましょう。","example_meaning":"Chuyện đó để sau, ta vào vấn đề chính nhé.","examples":[{"example":"それはさておき、本題に入りましょう。","example_reading":"それはさておき、ほんだいにはいりましょう。","example_meaning":"Chuyện đó để sau, ta vào vấn đề chính nhé."},{"example":"それはさておき、明日の準備はできていますか。","example_reading":"それはさておき、あしたのじゅんびはできていますか。","example_meaning":"Chuyện đó gác lại, bạn đã chuẩn bị xong cho ngày mai chưa?"}],"level":"e1"},
{"word":"ともあれ","reading":"ともあれ","meaning":"dù sao đi nữa","note":"Đứng đầu câu, gác lại chi tiết. Gần とにかく.","example":"ともあれ、無事に着いてよかった。","example_reading":"ともあれ、ぶじについてよかった。","example_meaning":"Dù sao thì đến nơi bình an là tốt rồi.","examples":[{"example":"ともあれ、無事に着いてよかった。","example_reading":"ともあれ、ぶじについてよかった。","example_meaning":"Dù sao thì đến nơi bình an là tốt rồi."},{"example":"ともあれ、詳しい話は明日聞くことにしよう。","example_reading":"ともあれ、くわしいはなしはあしたきくことにしよう。","example_meaning":"Dù sao, chuyện chi tiết mai hãy nghe."}],"level":"e1"},
{"word":"思いのほか","reading":"おもいのほか","meaning":"ngoài dự kiến","hanviet":"tư","antonym":"予想通り（よそうどおり）: đúng như dự đoán / 案の定（あんのじょう）: đúng như dự đoán","antonym_hanviet":"dự tưởng thông / án định","note":"Hay đi với 簡単, 高い, 早い. Gần 思ったより.","example":"試験は思いのほか簡単だった。","example_reading":"しけんはおもいのほかかんたんだった。","example_meaning":"Kỳ thi dễ hơn tôi nghĩ.","examples":[{"example":"試験は思いのほか簡単だった。","example_reading":"しけんはおもいのほかかんたんだった。","example_meaning":"Kỳ thi dễ hơn tôi nghĩ."},{"example":"この店は、思いのほか値段が高かった。","example_reading":"このみせは、おもいのほかねだんがたかかった。","example_meaning":"Quán này giá đắt hơn tôi tưởng."}],"level":"e1"},
{"word":"さもないと","reading":"さもないと","meaning":"nếu không thì","note":"Khẩu ngữ hơn さもなければ. Cảnh báo hậu quả.","example":"急いで。さもないと、間に合わないよ。","example_reading":"いそいで。さもないと、まにあわないよ。","example_meaning":"Nhanh lên. Không thì sẽ không kịp đâu.","examples":[{"example":"急いで。さもないと、間に合わないよ。","example_reading":"いそいで。さもないと、まにあわないよ。","example_meaning":"Nhanh lên. Không thì sẽ không kịp đâu."},{"example":"ちゃんと薬を飲みなさい。さもないと、治らないよ。","example_reading":"ちゃんとくすりをのみなさい。さもないと、なおらないよ。","example_meaning":"Hãy uống thuốc đàng hoàng. Không thì sẽ không khỏi đâu."}],"level":"e1"},
{"word":"その反面","reading":"そのはんめん","meaning":"mặt khác","hanviet":"phản diện","note":"Đối lập với điều vừa nói về cùng một sự vật.","example":"都会は便利だ。その反面、家賃が高い。","example_reading":"とかいはべんりだ。そのはんめん、やちんがたかい。","example_meaning":"Thành phố tiện lợi. Mặt khác, tiền nhà đắt.","examples":[{"example":"都会は便利だ。その反面、家賃が高い。","example_reading":"とかいはべんりだ。そのはんめん、やちんがたかい。","example_meaning":"Thành phố tiện lợi. Mặt khác, tiền nhà đắt."},{"example":"彼は優しい。その反面、優柔不断なところがある。","example_reading":"かれはやさしい。そのはんめん、ゆうじゅうふだんなところがある。","example_meaning":"Anh ấy hiền. Mặt khác, lại hay do dự."}],"level":"e1"},
{"word":"ましてや","reading":"ましてや","meaning":"huống chi","note":"Đi với ～ない／～のだから. Nếu điều nhẹ còn khó thì điều nặng càng khó.","example":"大人でも難しいのだから、ましてや子どもには無理だ。","example_reading":"おとなでもむずかしいのだから、ましてやこどもにはむりだ。","example_meaning":"Người lớn còn thấy khó, huống chi trẻ con thì không thể.","examples":[{"example":"大人でも難しいのだから、ましてや子どもには無理だ。","example_reading":"おとなでもむずかしいのだから、ましてやこどもにはむりだ。","example_meaning":"Người lớn còn thấy khó, huống chi trẻ con thì không thể."},{"example":"簡単な漢字も書けないのに、ましてや難しい文章など書けるはずがない。","example_reading":"かんたんなかんじもかけないのに、ましてやむずかしいぶんしょうなどかけるはずがない。","example_meaning":"Chữ Hán đơn giản còn không viết được, huống chi bài văn khó."}],"level":"e1"},
{"word":"本音を言えば","reading":"ほんねをいえば","meaning":"nói thật lòng","hanviet":"bản âm","antonym":"建前では（たてまえでは）: trên danh nghĩa / 表向きは（おもてむきは）: bề ngoài","antonym_hanviet":"kiến tiền / biểu hướng","note":"Hay đi với ～たい, ～ない. Thổ lộ cảm nghĩ thật.","example":"本音を言えば、もう少し休みたい。","example_reading":"ほんねをいえば、もうすこしやすみたい。","example_meaning":"Nói thật lòng, tôi muốn nghỉ thêm chút nữa.","examples":[{"example":"本音を言えば、もう少し休みたい。","example_reading":"ほんねをいえば、もうすこしやすみたい。","example_meaning":"Nói thật lòng, tôi muốn nghỉ thêm chút nữa."},{"example":"本音を言えば、この案には賛成できない。","example_reading":"ほんねをいえば、このあんにはさんせいできない。","example_meaning":"Nói thật lòng, tôi không thể đồng ý với phương án này."}],"level":"e1"},
{"word":"率直に言えば","reading":"そっちょくにいえば","meaning":"nói thẳng","hanviet":"suất trực","antonym":"遠回しに言えば（とおまわしにいえば）: nói vòng vo","antonym_hanviet":"viễn hồi ngôn","note":"Dùng khi nói thẳng ý kiến, nhất là chê.","example":"率直に言えば、今回の企画は失敗だった。","example_reading":"そっちょくにいえば、こんかいのきかくはしっぱいだった。","example_meaning":"Nói thẳng, kế hoạch lần này đã thất bại.","examples":[{"example":"率直に言えば、今回の企画は失敗だった。","example_reading":"そっちょくにいえば、こんかいのきかくはしっぱいだった。","example_meaning":"Nói thẳng, kế hoạch lần này đã thất bại."},{"example":"率直に言えば、君の意見には無理がある。","example_reading":"そっちょくにいえば、きみのいけんにはむりがある。","example_meaning":"Nói thẳng ra, ý kiến của cậu có điểm khiên cưỡng."}],"level":"e1"},
{"word":"最悪の場合","reading":"さいあくのばあい","meaning":"trong trường hợp xấu nhất","hanviet":"tối ác trường hợp","antonym":"最良の場合（さいりょうのばあい）: trường hợp tốt nhất","antonym_hanviet":"tối lương trường hợp","note":"Hay đi với ～かもしれない, 備える.","example":"最悪の場合、会社が倒産するかもしれない。","example_reading":"さいあくのばあい、かいしゃがとうさんするかもしれない。","example_meaning":"Trong trường hợp xấu nhất, công ty có thể phá sản.","examples":[{"example":"最悪の場合、会社が倒産するかもしれない。","example_reading":"さいあくのばあい、かいしゃがとうさんするかもしれない。","example_meaning":"Trong trường hợp xấu nhất, công ty có thể phá sản."},{"example":"最悪の場合に備えて、予備の資金を用意しておく。","example_reading":"さいあくのばあいにそなえて、よびのしきんをよういしておく。","example_meaning":"Để phòng trường hợp xấu nhất, tôi chuẩn bị sẵn khoản dự phòng."}],"level":"e1"},
{"word":"最低でも","reading":"さいていでも","meaning":"ít nhất thì","hanviet":"tối đê","antonym":"最高でも（さいこうでも）: tối đa cũng / せいぜい: cùng lắm / 多くても（おおくても）: nhiều lắm thì","antonym_hanviet":"tối cao /  / đa","note":"Hay đi với かかる, 必要だ. Giới hạn dưới.","example":"この仕事を終えるには、最低でも三日はかかる。","example_reading":"このしごとをおえるには、さいていでもみっかはかかる。","example_meaning":"Để xong việc này, ít nhất cũng mất ba ngày.","examples":[{"example":"この仕事を終えるには、最低でも三日はかかる。","example_reading":"このしごとをおえるには、さいていでもみっかはかかる。","example_meaning":"Để xong việc này, ít nhất cũng mất ba ngày."},{"example":"最低でも八時間は眠るようにしている。","example_reading":"さいていでもはちじかんはねむるようにしている。","example_meaning":"Tôi cố gắng ngủ ít nhất tám tiếng."}],"level":"e1"},
{"word":"常識的に考えて","reading":"じょうしきてきにかんがえて","meaning":"nghĩ theo lẽ thường","hanviet":"thường thức đích","note":"Dùng đưa ra phán đoán dựa trên lẽ thường.","example":"常識的に考えて、こんな時間に電話するのは失礼だ。","example_reading":"じょうしきてきにかんがえて、こんなじかんにでんわするのはしつれいだ。","example_meaning":"Nghĩ theo lẽ thường, gọi điện vào giờ này là thiếu lịch sự.","examples":[{"example":"常識的に考えて、こんな時間に電話するのは失礼だ。","example_reading":"じょうしきてきにかんがえて、こんなじかんにでんわするのはしつれいだ。","example_meaning":"Nghĩ theo lẽ thường, gọi điện vào giờ này là thiếu lịch sự."},{"example":"常識的に考えて、一日でこの量を終えるのは無理だ。","example_reading":"じょうしきてきにかんがえて、いちにちでこのりょうをおえるのはむりだ。","example_meaning":"Nghĩ theo lẽ thường, hoàn thành chừng này trong một ngày là không thể."}],"level":"e1"},
{"word":"見たところ","reading":"みたところ","meaning":"nhìn qua thì","hanviet":"kiến","note":"Hay đi với ～ようだ, ～らしい. Nhận định từ bề ngoài.","example":"見たところ、あの店は繁盛しているようだ。","example_reading":"みたところ、あのみせははんじょうしているようだ。","example_meaning":"Nhìn qua thì có vẻ quán đó làm ăn phát đạt.","examples":[{"example":"見たところ、あの店は繁盛しているようだ。","example_reading":"みたところ、あのみせははんじょうしているようだ。","example_meaning":"Nhìn qua thì có vẻ quán đó làm ăn phát đạt."},{"example":"見たところ、彼はまだ二十代のようだ。","example_reading":"みたところ、かれはまだにじゅうだいのようだ。","example_meaning":"Nhìn qua có vẻ anh ấy vẫn ở độ tuổi hai mươi."}],"level":"e1"},
{"word":"おまけに","reading":"おまけに","meaning":"hơn nữa, thêm vào đó","note":"Thêm điều bất lợi (thường là tiêu cực) vào điều trước.","example":"道に迷った。おまけに、雨まで降ってきた。","example_reading":"みちにまよった。おまけに、あめまでふってきた。","example_meaning":"Tôi bị lạc đường. Đã thế còn mưa nữa.","examples":[{"example":"道に迷った。おまけに、雨まで降ってきた。","example_reading":"みちにまよった。おまけに、あめまでふってきた。","example_meaning":"Tôi bị lạc đường. Đã thế còn mưa nữa."},{"example":"寝坊した。おまけに、財布も忘れてしまった。","example_reading":"ねぼうした。おまけに、さいふもわすれてしまった。","example_meaning":"Tôi ngủ quên. Đã thế còn quên ví."}],"level":"e1"},
{"word":"原則として","reading":"げんそくとして","meaning":"về nguyên tắc","hanviet":"nguyên tắc","antonym":"例外として（れいがいとして）: như một ngoại lệ","antonym_hanviet":"lệ ngoại","note":"Hay đi với ～ない, ～禁止. Có thể có ngoại lệ.","example":"原則として、返品はお受けできません。","example_reading":"げんそくとして、へんぴんはおうけできません。","example_meaning":"Về nguyên tắc, chúng tôi không nhận trả hàng.","examples":[{"example":"原則として、返品はお受けできません。","example_reading":"げんそくとして、へんぴんはおうけできません。","example_meaning":"Về nguyên tắc, chúng tôi không nhận trả hàng."},{"example":"この会社では、原則として残業は禁止されている。","example_reading":"このかいしゃでは、げんそくとしてざんぎょうはきんしされている。","example_meaning":"Ở công ty này, về nguyên tắc cấm làm thêm giờ."}],"level":"e1"},
{"word":"話は変わりますが","reading":"はなしはかわりますが","meaning":"nhân tiện đổi chủ đề","hanviet":"thoại biến","note":"Dùng lịch sự để chuyển sang chủ đề mới.","example":"話は変わりますが、来週の予定はどうなっていますか。","example_reading":"はなしはかわりますが、らいしゅうのよていはどうなっていますか。","example_meaning":"Nhân tiện đổi chủ đề, lịch tuần sau thế nào rồi?","examples":[{"example":"話は変わりますが、来週の予定はどうなっていますか。","example_reading":"はなしはかわりますが、らいしゅうのよていはどうなっていますか。","example_meaning":"Nhân tiện đổi chủ đề, lịch tuần sau thế nào rồi?"},{"example":"話は変わりますが、駅前に新しい店ができましたね。","example_reading":"はなしはかわりますが、えきまえにあたらしいみせができましたね。","example_meaning":"Nhân tiện, trước nhà ga có cửa hàng mới mở nhỉ."}],"level":"e1"},
{"word":"それはそうと","reading":"それはそうと","meaning":"à mà","note":"Khẩu ngữ. Chuyển chủ đề đột ngột.","example":"それはそうと、来月の旅行はどうなりましたか。","example_reading":"それはそうと、らいげつのりょこうはどうなりましたか。","example_meaning":"À mà, chuyến du lịch tháng sau thế nào rồi?","examples":[{"example":"それはそうと、来月の旅行はどうなりましたか。","example_reading":"それはそうと、らいげつのりょこうはどうなりましたか。","example_meaning":"À mà, chuyến du lịch tháng sau thế nào rồi?"},{"example":"それはそうと、お母さんの具合はいかがですか。","example_reading":"それはそうと、おかあさんのぐあいはいかがですか。","example_meaning":"À mà, sức khỏe của mẹ bạn thế nào rồi?"}],"level":"e1"},
{"word":"どちらにしても","reading":"どちらにしても","meaning":"dù là cách nào","note":"Nối với kết luận không đổi dù chọn phương án nào.","example":"どちらにしても、明日までに決めなければならない。","example_reading":"どちらにしても、あしたまでにきめなければならない。","example_meaning":"Dù chọn cách nào, đến mai cũng phải quyết định.","examples":[{"example":"どちらにしても、明日までに決めなければならない。","example_reading":"どちらにしても、あしたまでにきめなければならない。","example_meaning":"Dù chọn cách nào, đến mai cũng phải quyết định."},{"example":"行くにしても行かないにしても、どちらにしても連絡はしておこう。","example_reading":"いくにしてもいかないにしても、どちらにしてもれんらくはしておこう。","example_meaning":"Đi hay không đi, dù sao cũng cứ liên lạc trước."}],"level":"e1"},
{"word":"結果として","reading":"けっかとして","meaning":"kết quả là","hanviet":"kết quả","note":"Hay đi với ～になる. Nêu kết cục cuối cùng.","example":"結果として、計画は大成功に終わった。","example_reading":"けっかとして、けいかくはだいせいこうにおわった。","example_meaning":"Kết quả là kế hoạch đã thành công lớn.","examples":[{"example":"結果として、計画は大成功に終わった。","example_reading":"けっかとして、けいかくはだいせいこうにおわった。","example_meaning":"Kết quả là kế hoạch đã thành công lớn."},{"example":"彼の努力が、結果として会社を救うことになった。","example_reading":"かれのどりょくが、けっかとしてかいしゃをすくうことになった。","example_meaning":"Nỗ lực của anh ấy rốt cuộc đã cứu được công ty."}],"level":"e1"},
{"word":"正確に言えば","reading":"せいかくにいえば","meaning":"nói chính xác","hanviet":"chính xác ngôn","antonym":"大まかに言えば（おおまかにいえば）: nói đại khái","antonym_hanviet":"đại ngôn","note":"Dùng đính chính hoặc làm rõ.","example":"正確に言えば、彼は医者ではなく看護師だ。","example_reading":"せいかくにいえば、かれはいしゃではなくかんごしだ。","example_meaning":"Nói chính xác thì anh ấy không phải bác sĩ mà là y tá.","examples":[{"example":"正確に言えば、彼は医者ではなく看護師だ。","example_reading":"せいかくにいえば、かれはいしゃではなくかんごしだ。","example_meaning":"Nói chính xác thì anh ấy không phải bác sĩ mà là y tá."},{"example":"正確に言えば、今日で入社三年目になる。","example_reading":"せいかくにいえば、きょうでにゅうしゃさんねんめになる。","example_meaning":"Nói chính xác thì hôm nay là năm thứ ba tôi vào công ty."}],"level":"e1"},
{"word":"一言で言うと","reading":"ひとことでいうと","meaning":"nói trong một câu","hanviet":"nhất ngôn","note":"Khẩu ngữ hơn 一言で言えば.","example":"一言で言うと、この映画は感動的だ。","example_reading":"ひとことでいうと、このえいがはかんどうてきだ。","example_meaning":"Nói gọn trong một câu, bộ phim này rất cảm động.","examples":[{"example":"一言で言うと、この映画は感動的だ。","example_reading":"ひとことでいうと、このえいがはかんどうてきだ。","example_meaning":"Nói gọn trong một câu, bộ phim này rất cảm động."},{"example":"彼の性格を一言で言うと、頑固だ。","example_reading":"かれのせいかくをひとことでいうと、がんこだ。","example_meaning":"Nói một câu về tính cách anh ấy thì là cứng đầu."}],"level":"e1"},
{"word":"だからといって","reading":"だからといって","meaning":"nhưng không có nghĩa là","note":"Thừa nhận lý do nhưng không chấp nhận kết luận.","example":"忙しい。だからといって、約束を忘れていいわけではない。","example_reading":"いそがしい。だからといって、やくそくをわすれていいわけではない。","example_meaning":"Bận thật. Nhưng không có nghĩa là được quên lời hẹn.","examples":[{"example":"忙しい。だからといって、約束を忘れていいわけではない。","example_reading":"いそがしい。だからといって、やくそくをわすれていいわけではない。","example_meaning":"Bận thật. Nhưng không có nghĩa là được quên lời hẹn."},{"example":"彼は優秀だ。だからといって、全てを任せるのは危険だ。","example_reading":"かれはゆうしゅうだ。だからといって、すべてをまかせるのはきけんだ。","example_meaning":"Anh ấy giỏi. Nhưng giao hết mọi thứ thì nguy hiểm."}],"level":"e1"},
{"word":"そうは言っても","reading":"そうはいっても","meaning":"tuy nói vậy","hanviet":"ngôn","note":"Thừa nhận ý trước nhưng nêu ngoại lệ hoặc thực tế.","example":"そうは言っても、現実は厳しいものだ。","example_reading":"そうはいっても、げんじつはきびしいものだ。","example_meaning":"Tuy nói vậy, thực tế vẫn khắc nghiệt.","examples":[{"example":"そうは言っても、現実は厳しいものだ。","example_reading":"そうはいっても、げんじつはきびしいものだ。","example_meaning":"Tuy nói vậy, thực tế vẫn khắc nghiệt."},{"example":"そうは言っても、やってみなければ分からない。","example_reading":"そうはいっても、やってみなければわからない。","example_meaning":"Tuy nói thế, không thử thì không biết được."}],"level":"e1"},
{"word":"見る限り","reading":"みるかぎり","meaning":"theo những gì tôi thấy","hanviet":"kiến hạn","note":"Hay đi với ～ようだ, ～そうだ. Phán đoán dựa trên quan sát.","example":"見る限り、この店は人気があるようだ。","example_reading":"みるかぎり、このみせはにんきがあるようだ。","example_meaning":"Theo những gì thấy thì quán này có vẻ đông khách.","examples":[{"example":"見る限り、この店は人気があるようだ。","example_reading":"みるかぎり、このみせはにんきがあるようだ。","example_meaning":"Theo những gì thấy thì quán này có vẻ đông khách."},{"example":"私の見る限り、問題はなさそうだ。","example_reading":"わたしのみるかぎり、もんだいはなさそうだ。","example_meaning":"Theo những gì tôi thấy thì có vẻ không có vấn đề."}],"level":"e1"},
{"word":"結局のところ","reading":"けっきょくのところ","meaning":"rốt cuộc thì","hanviet":"kết cục","note":"Nhấn mạnh kết luận cuối cùng, gần 結局.","example":"結局のところ、最後は自分で決めるしかない。","example_reading":"けっきょくのところ、さいごはじぶんできめるしかない。","example_meaning":"Rốt cuộc thì cuối cùng chỉ có thể tự mình quyết định.","examples":[{"example":"結局のところ、最後は自分で決めるしかない。","example_reading":"けっきょくのところ、さいごはじぶんできめるしかない。","example_meaning":"Rốt cuộc thì cuối cùng chỉ có thể tự mình quyết định."},{"example":"結局のところ、彼の案が一番現実的だった。","example_reading":"けっきょくのところ、かれのあんがいちばんげんじつてきだった。","example_meaning":"Cuối cùng thì phương án của anh ấy là thực tế nhất."}],"level":"e1"},
{"word":"最終的に","reading":"さいしゅうてきに","meaning":"cuối cùng thì","hanviet":"tối chung đích","antonym":"当初は（とうしょは）: ban đầu / 最初は（さいしょは）: lúc đầu / 暫定的に（ざんていてきに）: tạm thời","antonym_hanviet":"đương sơ / tối sơ / tạm định đích","note":"Chỉ kết quả sau cân nhắc hoặc quá trình.","example":"悩んだ末、最終的に私は留学を選んだ。","example_reading":"なやんだすえ、さいしゅうてきにわたしはりゅうがくをえらんだ。","example_meaning":"Sau khi băn khoăn, cuối cùng tôi đã chọn đi du học.","examples":[{"example":"悩んだ末、最終的に私は留学を選んだ。","example_reading":"なやんだすえ、さいしゅうてきにわたしはりゅうがくをえらんだ。","example_meaning":"Sau khi băn khoăn, cuối cùng tôi đã chọn đi du học."},{"example":"最終的に、会議では彼の案が採用された。","example_reading":"さいしゅうてきに、かいぎではかれのあんがさいようされた。","example_meaning":"Cuối cùng, phương án của anh ấy được chọn trong cuộc họp."}],"level":"e1"},
{"word":"少なくとも","reading":"すくなくとも","meaning":"ít nhất, tối thiểu","hanviet":"thiểu","antonym":"せいぜい: cùng lắm / たかだか: cùng lắm / 多くても（おおくても）: nhiều lắm thì","antonym_hanviet":" /  / đa","note":"Mức tối thiểu. Đi với số lượng hoặc điều kiện.","example":"この仕事を終えるには、少なくとも三日はかかる。","example_reading":"このしごとをおえるには、すくなくともみっかはかかる。","example_meaning":"Để xong việc này thì ít nhất cũng mất ba ngày.","examples":[{"example":"この仕事を終えるには、少なくとも三日はかかる。","example_reading":"このしごとをおえるには、すくなくともみっかはかかる。","example_meaning":"Để xong việc này thì ít nhất cũng mất ba ngày."},{"example":"少なくとも、謝るぐらいはすべきだった。","example_reading":"すくなくとも、あやまるぐらいはすべきだった。","example_meaning":"Ít nhất thì cũng nên xin lỗi."}],"level":"e1"},
{"word":"せいぜい","reading":"せいぜい","meaning":"cùng lắm, tối đa chỉ","antonym":"少なくとも（すくなくとも）: ít nhất / 最低でも（さいていでも）: ít nhất thì","antonym_hanviet":"thiểu / tối đê","note":"Chỉ giới hạn trên (thấp). Đi với ～だ／～しかない／～ぐらい.","example":"私にできるのは、せいぜい書類を整理することぐらいだ。","example_reading":"わたしにできるのは、せいぜいしょるいをせいりすることぐらいだ。","example_meaning":"Việc tôi làm được cùng lắm chỉ là sắp xếp tài liệu.","examples":[{"example":"私にできるのは、せいぜい書類を整理することぐらいだ。","example_reading":"わたしにできるのは、せいぜいしょるいをせいりすることぐらいだ。","example_meaning":"Việc tôi làm được cùng lắm chỉ là sắp xếp tài liệu."},{"example":"この辺りの店は、せいぜい十人しか入れない。","example_reading":"このあたりのみせは、せいぜいじゅうにんしかいれない。","example_meaning":"Quán quanh đây cùng lắm chỉ chứa được mười người."}],"level":"e1"},
{"word":"中でも","reading":"なかでも","meaning":"đặc biệt là, trong số đó","hanviet":"trung","note":"Nêu mục nổi bật nhất trong một nhóm.","example":"果物が好きで、中でもりんごが一番好きだ。","example_reading":"くだものがすきで、なかでもりんごがいちばんすきだ。","example_meaning":"Tôi thích trái cây, đặc biệt thích nhất là táo.","examples":[{"example":"果物が好きで、中でもりんごが一番好きだ。","example_reading":"くだものがすきで、なかでもりんごがいちばんすきだ。","example_meaning":"Tôi thích trái cây, đặc biệt thích nhất là táo."},{"example":"日本料理は、中でも寿司が外国人に人気だ。","example_reading":"にほんりょうりは、なかでもすしががいこくじんににんきだ。","example_meaning":"Trong ẩm thực Nhật, đặc biệt sushi được người nước ngoài ưa chuộng."}],"level":"e1"},
{"word":"運良く","reading":"うんよく","meaning":"may mắn là","hanviet":"vận lương","antonym":"運悪く（うんわるく）: xui xẻo","antonym_hanviet":"vận ác","note":"Gần 幸い, thiên về may mắn tình cờ.","example":"運良く、終電に間に合った。","example_reading":"うんよく、しゅうでんにまにあった。","example_meaning":"May mắn là tôi kịp chuyến tàu cuối.","examples":[{"example":"運良く、終電に間に合った。","example_reading":"うんよく、しゅうでんにまにあった。","example_meaning":"May mắn là tôi kịp chuyến tàu cuối."},{"example":"運良く、財布は交番に届けられていた。","example_reading":"うんよく、さいふはこうばんにとどけられていた。","example_meaning":"May mắn là chiếc ví đã được nộp tại đồn công an."}],"level":"e1"},
{"word":"反面","reading":"はんめん","meaning":"mặt khác (trong cùng sự vật)","hanviet":"phản diện","note":"Đi sau mệnh đề: ～反面, ～。 Nêu hai mặt trái ngược của một thứ.","example":"この仕事はやりがいがある反面、体力的にきつい。","example_reading":"このしごとはやりがいがあるはんめん、たいりょくてきにきつい。","example_meaning":"Công việc này đáng làm nhưng mặt khác lại nặng về thể lực.","examples":[{"example":"この仕事はやりがいがある反面、体力的にきつい。","example_reading":"このしごとはやりがいがあるはんめん、たいりょくてきにきつい。","example_meaning":"Công việc này đáng làm nhưng mặt khác lại nặng về thể lực."},{"example":"便利な反面、使いすぎると健康に悪い。","example_reading":"べんりなはんめん、つかいすぎるとけんこうにわるい。","example_meaning":"Tiện lợi nhưng mặt khác dùng quá nhiều sẽ hại sức khỏe."}],"level":"e1"},
{"word":"多くても","reading":"おおくても","meaning":"nhiều lắm thì","hanviet":"đa","antonym":"少なくとも（すくなくとも）: ít nhất / 最低でも（さいていでも）: ít nhất cũng","antonym_hanviet":"thiểu / tối đê","note":"Hay đi với ～ほど, ～しか. Giới hạn trên.","example":"参加者は、多くても二十人ほどだろう。","example_reading":"さんかしゃは、おおくてもにじゅうにんほどだろう。","example_meaning":"Số người tham gia nhiều lắm cũng khoảng hai mươi người.","examples":[{"example":"参加者は、多くても二十人ほどだろう。","example_reading":"さんかしゃは、おおくてもにじゅうにんほどだろう。","example_meaning":"Số người tham gia nhiều lắm cũng khoảng hai mươi người."},{"example":"多くても、月に二回しか会えない。","example_reading":"おおくても、つきににかいしかあえない。","example_meaning":"Nhiều lắm thì một tháng cũng chỉ gặp được hai lần."}],"level":"e1"},
{"word":"早くても","reading":"はやくても","meaning":"sớm nhất thì","hanviet":"tảo","antonym":"遅くても（おそくても）: muộn nhất / 遅くとも（おそくとも）: chậm nhất là","antonym_hanviet":"trì / trì","note":"Hay đi với ～になる. Giới hạn sớm nhất.","example":"早くても、完成は来月の末になる。","example_reading":"はやくても、かんせいはらいげつのすえになる。","example_meaning":"Sớm nhất thì cuối tháng sau mới xong.","examples":[{"example":"早くても、完成は来月の末になる。","example_reading":"はやくても、かんせいはらいげつのすえになる。","example_meaning":"Sớm nhất thì cuối tháng sau mới xong."},{"example":"結果が出るのは、早くても明日の夕方だ。","example_reading":"けっかがでるのは、はやくてもあしたのゆうがただ。","example_meaning":"Kết quả sớm nhất cũng phải chiều mai mới có."}],"level":"e1"},
{"word":"遅くても","reading":"おそくても","meaning":"muộn nhất thì","hanviet":"trì","antonym":"早くても（はやくても）: sớm nhất","antonym_hanviet":"tảo","note":"Hay đi với ～までに. Giới hạn muộn nhất.","example":"遅くても、明日の朝までには連絡します。","example_reading":"おそくても、あしたのあさまでにはれんらくします。","example_meaning":"Muộn nhất là sáng mai tôi sẽ liên lạc.","examples":[{"example":"遅くても、明日の朝までには連絡します。","example_reading":"おそくても、あしたのあさまでにはれんらくします。","example_meaning":"Muộn nhất là sáng mai tôi sẽ liên lạc."},{"example":"遅くても、三時には出発しなければならない。","example_reading":"おそくても、さんじにはしゅっぱつしなければならない。","example_meaning":"Muộn nhất là ba giờ chúng ta phải xuất phát."}],"level":"e1"},
{"word":"冷静に考えれば","reading":"れいせいにかんがえれば","meaning":"bình tĩnh nghĩ lại thì","hanviet":"lãnh tĩnh","antonym":"感情的に考えれば（かんじょうてきにかんがえれば）: nghĩ theo cảm xúc","antonym_hanviet":"cảm tình đích khảo","note":"Dùng để đánh giá lại khi đã bớt cảm xúc.","example":"冷静に考えれば、あんなことをするはずがない。","example_reading":"れいせいにかんがえれば、あんなことをするはずがない。","example_meaning":"Bình tĩnh nghĩ lại thì anh ấy không thể làm chuyện như thế.","examples":[{"example":"冷静に考えれば、あんなことをするはずがない。","example_reading":"れいせいにかんがえれば、あんなことをするはずがない。","example_meaning":"Bình tĩnh nghĩ lại thì anh ấy không thể làm chuyện như thế."},{"example":"冷静に考えれば、この条件は悪くない。","example_reading":"れいせいにかんがえれば、このじょうけんはわるくない。","example_meaning":"Bình tĩnh suy xét thì điều kiện này không tệ."}],"level":"e1"},
{"word":"いずれにしろ","reading":"いずれにしろ","meaning":"dù sao đi nữa","note":"Gần いずれにしても. Dù chọn cách nào kết quả vẫn thế.","example":"いずれにしろ、結果は来週には分かる。","example_reading":"いずれにしろ、けっかはらいしゅうにはわかる。","example_meaning":"Dù sao đi nữa, kết quả tuần sau sẽ biết.","examples":[{"example":"いずれにしろ、結果は来週には分かる。","example_reading":"いずれにしろ、けっかはらいしゅうにはわかる。","example_meaning":"Dù sao đi nữa, kết quả tuần sau sẽ biết."},{"example":"理由はともかく、いずれにしろ遅刻は許されない。","example_reading":"りゆうはともかく、いずれにしろちこくはゆるされない。","example_meaning":"Dù lý do là gì, đi muộn cũng không được tha thứ."}],"level":"e1"},
{"word":"要約すると","reading":"ようやくすると","meaning":"tóm tắt lại","hanviet":"yếu ước","antonym":"詳しく言えば（くわしくいえば）: nói chi tiết","antonym_hanviet":"tường ngôn","note":"Dùng khi rút gọn nội dung dài.","example":"要約すると、この記事は環境問題の重要性を訴えている。","example_reading":"ようやくすると、このきじはかんきょうもんだいのじゅうようせいをうったえている。","example_meaning":"Tóm tắt lại, bài báo này nhấn mạnh tầm quan trọng của vấn đề môi trường.","examples":[{"example":"要約すると、この記事は環境問題の重要性を訴えている。","example_reading":"ようやくすると、このきじはかんきょうもんだいのじゅうようせいをうったえている。","example_meaning":"Tóm tắt lại, bài báo này nhấn mạnh tầm quan trọng của vấn đề môi trường."},{"example":"要約すると、次の三点が重要だ。","example_reading":"ようやくすると、つぎのさんてんがじゅうようだ。","example_meaning":"Tóm lại, có ba điểm quan trọng sau."}],"level":"e1"},
{"word":"端的に言えば","reading":"たんてきにいえば","meaning":"nói thẳng ra","hanviet":"đoan đích ngôn","antonym":"遠回しに言えば（とおまわしにいえば）: nói vòng vo","antonym_hanviet":"viễn hồi ngôn","note":"Dùng nói thẳng kết luận.","example":"端的に言えば、君は準備が足りない。","example_reading":"たんてきにいえば、きみはじゅんびがたりない。","example_meaning":"Nói thẳng ra, cậu chuẩn bị chưa đủ.","examples":[{"example":"端的に言えば、君は準備が足りない。","example_reading":"たんてきにいえば、きみはじゅんびがたりない。","example_meaning":"Nói thẳng ra, cậu chuẩn bị chưa đủ."},{"example":"端的に言えば、問題は人手不足にある。","example_reading":"たんてきにいえば、もんだいはひとでぶそくにある。","example_meaning":"Nói thẳng ra, vấn đề nằm ở thiếu nhân lực."}],"level":"e1"},
{"word":"言ってみれば","reading":"いってみれば","meaning":"có thể nói là","hanviet":"ngôn kiến","note":"Dùng ví von để diễn tả ngắn gọn.","example":"言ってみれば、彼は私の恩人だ。","example_reading":"いってみれば、かれはわたしのおんじんだ。","example_meaning":"Có thể nói anh ấy là ân nhân của tôi.","examples":[{"example":"言ってみれば、彼は私の恩人だ。","example_reading":"いってみれば、かれはわたしのおんじんだ。","example_meaning":"Có thể nói anh ấy là ân nhân của tôi."},{"example":"この仕事は、言ってみればパズルのようなものだ。","example_reading":"このしごとは、いってみればパズルのようなものだ。","example_meaning":"Công việc này nói ví von thì giống một trò xếp hình."}],"level":"e1"},
{"word":"かといって","reading":"かといって","meaning":"tuy vậy cũng không thể","note":"Hay đi với ～ない. Phủ định cả hai khả năng đối lập.","example":"今のままでは困る。かといって、すぐに変えるのも難しい。","example_reading":"いまのままではこまる。かといって、すぐにかえるのもむずかしい。","example_meaning":"Cứ thế này thì khó. Nhưng đổi ngay cũng khó.","examples":[{"example":"今のままでは困る。かといって、すぐに変えるのも難しい。","example_reading":"いまのままではこまる。かといって、すぐにかえるのもむずかしい。","example_meaning":"Cứ thế này thì khó. Nhưng đổi ngay cũng khó."},{"example":"贅沢はしたくない。かといって、我慢ばかりも辛い。","example_reading":"ぜいたくはしたくない。かといって、がまんばかりもつらい。","example_meaning":"Không muốn xa xỉ. Nhưng cứ nhịn mãi cũng khổ."}],"level":"e1"},
{"word":"運悪く","reading":"うんわるく","meaning":"xui xẻo là","hanviet":"vận ác","antonym":"運良く（うんよく）: may mắn / 幸いにも（さいわいにも）: may thay","antonym_hanviet":"vận lương / hạnh","note":"Trái nghĩa với 運良く.","example":"運悪く、出かけた途端に雨が降り出した。","example_reading":"うんわるく、でかけたとたんにあめがふりだした。","example_meaning":"Xui xẻo là vừa ra khỏi nhà thì trời mưa.","examples":[{"example":"運悪く、出かけた途端に雨が降り出した。","example_reading":"うんわるく、でかけたとたんにあめがふりだした。","example_meaning":"Xui xẻo là vừa ra khỏi nhà thì trời mưa."},{"example":"運悪く、その日は店が休みだった。","example_reading":"うんわるく、そのひはみせがやすみだった。","example_meaning":"Xui là hôm đó cửa hàng nghỉ."}],"level":"e1"},
{"word":"何気なく","reading":"なにげなく","meaning":"vô tình, một cách tự nhiên","hanviet":"hà khí","antonym":"わざと: cố ý / 意図的に（いとてきに）: có chủ ý / わざわざ: có công","antonym_hanviet":" / ý đồ đích / ","note":"Không có chủ ý đặc biệt.","example":"何気なく窓の外を見ると、虹が出ていた。","example_reading":"なにげなくまどのそとをみると、にじがでていた。","example_meaning":"Tôi vô tình nhìn ra ngoài cửa sổ thì thấy cầu vồng.","examples":[{"example":"何気なく窓の外を見ると、虹が出ていた。","example_reading":"なにげなくまどのそとをみると、にじがでていた。","example_meaning":"Tôi vô tình nhìn ra ngoài cửa sổ thì thấy cầu vồng."},{"example":"何気なく言った一言が、彼を傷つけてしまった。","example_reading":"なにげなくいったひとことが、かれをきずつけてしまった。","example_meaning":"Một câu nói vô tình đã làm tổn thương anh ấy."}],"level":"e1"},
{"word":"どうせ","reading":"どうせ","meaning":"dù sao cũng, kiểu gì cũng","note":"Kết luận không thay đổi, thường kèm cảm giác buông xuôi. Đi với ～から／～なら／～だろう.","example":"どうせ行っても、会えないだろう。","example_reading":"どうせいっても、あえないだろう。","example_meaning":"Dù sao có đi cũng không gặp được đâu.","examples":[{"example":"どうせ行っても、会えないだろう。","example_reading":"どうせいっても、あえないだろう。","example_meaning":"Dù sao có đi cũng không gặp được đâu."},{"example":"どうせ作るなら、おいしいものを作りたい。","example_reading":"どうせつくるなら、おいしいものをつくりたい。","example_meaning":"Đã nấu thì tôi muốn nấu món ngon."}],"level":"e1"},
{"word":"そのうえ","reading":"そのうえ","meaning":"hơn thế nữa, thêm vào đó","note":"Cộng thêm yếu tố khác (thường cùng chiều). Đặt đầu câu hoặc giữa câu.","example":"今日は雨が降り、そのうえ風も強い。","example_reading":"きょうはあめがふり、そのうえかぜもつよい。","example_meaning":"Hôm nay trời mưa, hơn nữa gió còn mạnh.","examples":[{"example":"今日は雨が降り、そのうえ風も強い。","example_reading":"きょうはあめがふり、そのうえかぜもつよい。","example_meaning":"Hôm nay trời mưa, hơn nữa gió còn mạnh."},{"example":"道に迷い、そのうえ財布まで落としてしまった。","example_reading":"みちにまよい、そのうえさいふまでおとしてしまった。","example_meaning":"Tôi bị lạc đường, thêm vào đó còn làm rơi cả ví."}],"level":"e1"},
{"word":"とはいえ","reading":"とはいえ","meaning":"tuy nói vậy, dù vậy","note":"Thừa nhận điều trước nhưng nêu ý hạn chế. Văn viết, trang trọng.","example":"試験は終わった。とはいえ、まだ油断はできない。","example_reading":"しけんはおわった。とはいえ、まだゆだんはできない。","example_meaning":"Kỳ thi đã xong. Tuy vậy vẫn chưa thể lơ là.","examples":[{"example":"試験は終わった。とはいえ、まだ油断はできない。","example_reading":"しけんはおわった。とはいえ、まだゆだんはできない。","example_meaning":"Kỳ thi đã xong. Tuy vậy vẫn chưa thể lơ là."},{"example":"安いのは確かだ。とはいえ、品質に問題があるのでは困る。","example_reading":"やすいのはたしかだ。とはいえ、ひんしつにもんだいがあるのではこまる。","example_meaning":"Rẻ thì đúng là rẻ. Tuy vậy chất lượng có vấn đề thì phiền."}],"level":"e1"},
{"word":"幸いにも","reading":"さいわいにも","meaning":"may mắn thay","hanviet":"hạnh","antonym":"不幸にも（ふこうにも）: chẳng may / 運悪く（うんわるく）: xui xẻo / 残念ながら（ざんねんながら）: đáng tiếc là","antonym_hanviet":"bất hạnh / vận ác / tàn niệm","note":"Gần 幸い, nhấn mạnh sự may mắn.","example":"幸いにも、けが人は一人も出なかった。","example_reading":"さいわいにも、けがにんはひとりもでなかった。","example_meaning":"May mắn thay, không có ai bị thương.","examples":[{"example":"幸いにも、けが人は一人も出なかった。","example_reading":"さいわいにも、けがにんはひとりもでなかった。","example_meaning":"May mắn thay, không có ai bị thương."},{"example":"幸いにも、天気に恵まれて遠足は無事に終わった。","example_reading":"さいわいにも、てんきにめぐまれてえんそくはぶじにおわった。","example_meaning":"May mắn có thời tiết đẹp nên chuyến dã ngoại kết thúc suôn sẻ."}],"level":"e1"},
{"word":"意外にも","reading":"いがいにも","meaning":"thật bất ngờ là","hanviet":"ý ngoại","antonym":"案の定（あんのじょう）: đúng như dự đoán / やはり: quả nhiên / やっぱり: quả nhiên","antonym_hanviet":"án định /  / ","note":"Đọc いがいにも. Hay đi với ～た. Nêu kết quả trái dự đoán. Văn viết.","example":"意外にも、彼は料理がとても上手だった。","example_reading":"いがいにも、かれはりょうりがとてもじょうずだった。","example_meaning":"Thật bất ngờ, anh ấy nấu ăn rất giỏi.","examples":[{"example":"意外にも、彼は料理がとても上手だった。","example_reading":"いがいにも、かれはりょうりがとてもじょうずだった。","example_meaning":"Thật bất ngờ, anh ấy nấu ăn rất giỏi."},{"example":"意外にも、そのチームは一回戦で負けてしまった。","example_reading":"いがいにも、そのチームはいっかいせんでまけてしまった。","example_meaning":"Thật bất ngờ, đội đó thua ngay vòng một."}],"level":"e1"},
{"word":"加えて","reading":"くわえて","meaning":"thêm vào đó","hanviet":"gia","note":"Đọc くわえて. Hay đi với ～に加えて. Bổ sung lý do hoặc điều kiện; văn viết.","example":"雨が降っていた。加えて、風も強かった。","example_reading":"あめがふっていた。くわえて、かぜもつよかった。","example_meaning":"Trời đang mưa. Thêm vào đó gió cũng mạnh.","examples":[{"example":"雨が降っていた。加えて、風も強かった。","example_reading":"あめがふっていた。くわえて、かぜもつよかった。","example_meaning":"Trời đang mưa. Thêm vào đó gió cũng mạnh."},{"example":"加えて、来月から料金も上がる予定だ。","example_reading":"くわえて、らいげつからりょうきんもあがるよていだ。","example_meaning":"Thêm vào đó, từ tháng sau giá cũng dự kiến tăng."}],"level":"e1"},
{"word":"あいにく","reading":"あいにく","meaning":"tiếc là, không may","antonym":"幸い（さいわい）: may mắn là","antonym_hanviet":"hạnh","note":"Gặp hoàn cảnh không thuận (hay dùng khi từ chối lịch sự). Hay đi với ～ですが／～でした.","example":"あいにく、今日は店が休みでした。","example_reading":"あいにく、きょうはみせがやすみでした。","example_meaning":"Không may là hôm nay quán nghỉ.","examples":[{"example":"あいにく、今日は店が休みでした。","example_reading":"あいにく、きょうはみせがやすみでした。","example_meaning":"Không may là hôm nay quán nghỉ."},{"example":"あいにく、その日は先約がありまして。","example_reading":"あいにく、そのひはせんやくがありまして。","example_meaning":"Tiếc là hôm đó tôi đã có hẹn trước."}],"level":"e1"},
{"word":"さもなければ","reading":"さもなければ","meaning":"nếu không thì","note":"Cảnh báo hậu quả nếu không làm theo.","example":"早く出発しなさい。さもなければ、電車に乗り遅れるよ。","example_reading":"はやくしゅっぱつしなさい。さもなければ、でんしゃにのりおくれるよ。","example_meaning":"Hãy xuất phát sớm. Nếu không sẽ lỡ tàu đấy.","examples":[{"example":"早く出発しなさい。さもなければ、電車に乗り遅れるよ。","example_reading":"はやくしゅっぱつしなさい。さもなければ、でんしゃにのりおくれるよ。","example_meaning":"Hãy xuất phát sớm. Nếu không sẽ lỡ tàu đấy."},{"example":"約束は守ること。さもなければ、信用を失うことになる。","example_reading":"やくそくはまもること。さもなければ、しんようをうしなうことになる。","example_meaning":"Phải giữ lời hứa. Nếu không sẽ mất uy tín."}],"level":"e1"},
{"word":"結論から言えば","reading":"けつろんからいえば","meaning":"nói kết luận trước","hanviet":"kết luận ngôn","note":"Đưa kết luận trước rồi giải thích sau.","example":"結論から言えば、この計画は実行すべきではない。","example_reading":"けつろんからいえば、このけいかくはじっこうすべきではない。","example_meaning":"Nói kết luận trước, không nên thực hiện kế hoạch này.","examples":[{"example":"結論から言えば、この計画は実行すべきではない。","example_reading":"けつろんからいえば、このけいかくはじっこうすべきではない。","example_meaning":"Nói kết luận trước, không nên thực hiện kế hoạch này."},{"example":"結論から言えば、彼の考えは正しかった。","example_reading":"けつろんからいえば、かれのかんがえはただしかった。","example_meaning":"Nói thẳng kết luận, suy nghĩ của anh ấy đã đúng."}],"level":"e1"},
{"word":"何はともあれ","reading":"なにはともあれ","meaning":"trước hết, dù thế nào","hanviet":"hà","note":"Gác mọi chuyện để nêu điều quan trọng nhất.","example":"何はともあれ、元気そうで安心した。","example_reading":"なにはともあれ、げんきそうであんしんした。","example_meaning":"Dù thế nào, thấy bạn khỏe tôi cũng yên tâm.","examples":[{"example":"何はともあれ、元気そうで安心した。","example_reading":"なにはともあれ、げんきそうであんしんした。","example_meaning":"Dù thế nào, thấy bạn khỏe tôi cũng yên tâm."},{"example":"何はともあれ、まずは食事にしましょう。","example_reading":"なにはともあれ、まずはしょくじにしましょう。","example_meaning":"Trước hết cứ ăn cơm đã nhé."}],"level":"e1"},
{"word":"本来なら","reading":"ほんらいなら","meaning":"lẽ ra thì","hanviet":"bản lai","note":"Hay đi với ～はずだ, ～べきだ. Đúng ra nhưng thực tế khác.","example":"本来なら、私が謝りに行くべきだった。","example_reading":"ほんらいなら、わたしがあやまりにいくべきだった。","example_meaning":"Lẽ ra tôi phải đến xin lỗi.","examples":[{"example":"本来なら、私が謝りに行くべきだった。","example_reading":"ほんらいなら、わたしがあやまりにいくべきだった。","example_meaning":"Lẽ ra tôi phải đến xin lỗi."},{"example":"本来なら今日は休みのはずだが、急に仕事が入った。","example_reading":"ほんらいならきょうはやすみのはずだが、きゅうにしごとがはいった。","example_meaning":"Lẽ ra hôm nay được nghỉ nhưng bỗng có việc đột xuất."}],"level":"e1"},
{"word":"欲を言えば","reading":"よくをいえば","meaning":"nếu tham một chút","hanviet":"dục ngôn","note":"Hay đi với ～たい, ～がいい. Nêu mong muốn cao hơn.","example":"欲を言えば、もう少し広い部屋がいい。","example_reading":"よくをいえば、もうすこしひろいへやがいい。","example_meaning":"Nếu tham một chút, tôi muốn phòng rộng hơn.","examples":[{"example":"欲を言えば、もう少し広い部屋がいい。","example_reading":"よくをいえば、もうすこしひろいへやがいい。","example_meaning":"Nếu tham một chút, tôi muốn phòng rộng hơn."},{"example":"欲を言えば、もう一人手伝ってくれる人がほしい。","example_reading":"よくをいえば、もうひとりてつだってくれるひとがほしい。","example_meaning":"Nếu tham một chút, tôi muốn có thêm một người giúp."}],"level":"e1"},
{"word":"そればかりか","reading":"そればかりか","meaning":"không những thế","note":"Nêu điều nghiêm trọng hơn điều trước.","example":"彼は遅刻した。そればかりか、大事な書類も忘れてきた。","example_reading":"かれはちこくした。そればかりか、だいじなしょるいもわすれてきた。","example_meaning":"Anh ta đến muộn. Không những thế còn quên tài liệu quan trọng.","examples":[{"example":"彼は遅刻した。そればかりか、大事な書類も忘れてきた。","example_reading":"かれはちこくした。そればかりか、だいじなしょるいもわすれてきた。","example_meaning":"Anh ta đến muộn. Không những thế còn quên tài liệu quan trọng."},{"example":"この店は安い。そればかりか、味も絶品だ。","example_reading":"このみせはやすい。そればかりか、あじもぜっぴんだ。","example_meaning":"Quán này rẻ. Không những thế vị còn tuyệt hảo."}],"level":"e1"},
{"word":"大まかに言えば","reading":"おおまかにいえば","meaning":"nói đại khái","hanviet":"đại","antonym":"厳密に言えば（げんみつにいえば）: nói chính xác / 正確に言えば（せいかくにいえば）: nói chính xác / 具体的には（ぐたいてきには）: cụ thể là","antonym_hanviet":"nghiêm mật ngôn / chính xác ngôn / cụ thể đích","note":"Tóm khái quát, không đi vào chi tiết.","example":"大まかに言えば、この町は農業が中心だ。","example_reading":"おおまかにいえば、このまちはのうぎょうがちゅうしんだ。","example_meaning":"Nói đại khái, thị trấn này lấy nông nghiệp làm trọng tâm.","examples":[{"example":"大まかに言えば、この町は農業が中心だ。","example_reading":"おおまかにいえば、このまちはのうぎょうがちゅうしんだ。","example_meaning":"Nói đại khái, thị trấn này lấy nông nghiệp làm trọng tâm."},{"example":"大まかに言えば、費用は百万円ほどかかる。","example_reading":"おおまかにいえば、ひようはひゃくまんえんほどかかる。","example_meaning":"Nói đại khái, chi phí khoảng một triệu yên."}],"level":"e1"},
{"word":"理論上は","reading":"りろんじょうは","meaning":"về lý thuyết","hanviet":"lý luận thượng","antonym":"実際には（じっさいには）: trên thực tế / 現実には（げんじつには）: trên thực tế","antonym_hanviet":"thực tế / hiện thực","note":"Hay đi với ～が, 実際には. Đối lập với thực tế.","example":"理論上は可能だが、実際にやってみると難しい。","example_reading":"りろんじょうはかのうだが、じっさいにやってみるとむずかしい。","example_meaning":"Về lý thuyết thì khả thi nhưng thực hiện mới thấy khó.","examples":[{"example":"理論上は可能だが、実際にやってみると難しい。","example_reading":"りろんじょうはかのうだが、じっさいにやってみるとむずかしい。","example_meaning":"Về lý thuyết thì khả thi nhưng thực hiện mới thấy khó."},{"example":"理論上は、この方法で解決できるはずだ。","example_reading":"りろんじょうは、このほうほうでかいけつできるはずだ。","example_meaning":"Về lý thuyết thì phương pháp này giải quyết được."}],"level":"e1"},
{"word":"以下のとおり","reading":"いかのとおり","meaning":"như sau","hanviet":"dĩ hạ","note":"Dùng trước khi liệt kê nội dung bên dưới.","antonym":"前述のとおり（ぜんじゅつのとおり）: như đã nói ở trên","antonym_hanviet":"tiền thuật","example":"会議の日程は、以下のとおりです。","example_reading":"かいぎのにっていは、いかのとおりです。","example_meaning":"Lịch trình cuộc họp như sau.","examples":[{"example":"会議の日程は、以下のとおりです。","example_reading":"かいぎのにっていは、いかのとおりです。","example_meaning":"Lịch trình cuộc họp như sau."},{"example":"結果は以下のとおり報告します。","example_reading":"けっかはいかのとおりほうこくします。","example_meaning":"Tôi xin báo cáo kết quả như sau."}],"level":"e1"},
{"word":"さらには","reading":"さらには","meaning":"hơn nữa, thậm chí","note":"Thêm điều mạnh hơn nữa vào chuỗi trước.","example":"風邪を引き、さらには熱まで出てしまった。","example_reading":"かぜをひき、さらにはねつまででてしまった。","example_meaning":"Bị cảm, thậm chí còn phát sốt nữa.","examples":[{"example":"風邪を引き、さらには熱まで出てしまった。","example_reading":"かぜをひき、さらにはねつまででてしまった。","example_meaning":"Bị cảm, thậm chí còn phát sốt nữa."},{"example":"彼は日本語、英語、さらには中国語も話せる。","example_reading":"かれはにほんご、えいご、さらにはちゅうごくごもはなせる。","example_meaning":"Anh ấy nói được tiếng Nhật, tiếng Anh và thậm chí cả tiếng Trung."}],"level":"e1"},
{"word":"というのも","reading":"というのも","meaning":"bởi vì","note":"Giải thích lý do cho điều vừa nêu; câu thường kết bằng ～からだ.","example":"今日は早く帰ります。というのも、母が病気だからです。","example_reading":"きょうははやくかえります。というのも、ははがびょうきだからです。","example_meaning":"Hôm nay tôi về sớm. Bởi vì mẹ tôi bị ốm.","examples":[{"example":"今日は早く帰ります。というのも、母が病気だからです。","example_reading":"きょうははやくかえります。というのも、ははがびょうきだからです。","example_meaning":"Hôm nay tôi về sớm. Bởi vì mẹ tôi bị ốm."},{"example":"彼は驚いていた。というのも、誰も彼に知らせていなかったからだ。","example_reading":"かれはおどろいていた。というのも、だれもかれにしらせていなかったからだ。","example_meaning":"Anh ấy ngạc nhiên. Bởi vì chẳng ai báo cho anh ấy."}],"level":"e1"},
{"word":"残念ながら","reading":"ざんねんながら","meaning":"đáng tiếc là","hanviet":"tàn niệm","antonym":"幸い（さいわい）: may mắn là / 幸いにも（さいわいにも）: may mắn thay","antonym_hanviet":"hạnh / hạnh","note":"Mở đầu thông tin không mong muốn.","example":"残念ながら、今回は不合格となりました。","example_reading":"ざんねんながら、こんかいはふごうかくとなりました。","example_meaning":"Đáng tiếc là lần này bạn đã không đạt.","examples":[{"example":"残念ながら、今回は不合格となりました。","example_reading":"ざんねんながら、こんかいはふごうかくとなりました。","example_meaning":"Đáng tiếc là lần này bạn đã không đạt."},{"example":"楽しみにしていたが、残念ながら雨で中止になった。","example_reading":"たのしみにしていたが、ざんねんながらあめでちゅうしになった。","example_meaning":"Tôi đã mong chờ nhưng đáng tiếc là bị hủy vì mưa."}],"level":"e1"},
{"word":"案外","reading":"あんがい","meaning":"không ngờ, bất ngờ","hanviet":"án ngoại","antonym":"予想どおり（よそうどおり）: đúng như dự kiến / やはり: quả nhiên / やっぱり: quả nhiên","antonym_hanviet":"dự tưởng /  / ","note":"Đọc あんがい. Hay đi với ～た／～だ. Kết quả khác dự đoán; ít trang trọng hơn 意外にも.","example":"難しそうだったが、やってみると案外簡単だった。","example_reading":"むずかしそうだったが、やってみるとあんがいかんたんだった。","example_meaning":"Tưởng khó nhưng làm thử lại không ngờ dễ.","examples":[{"example":"難しそうだったが、やってみると案外簡単だった。","example_reading":"むずかしそうだったが、やってみるとあんがいかんたんだった。","example_meaning":"Tưởng khó nhưng làm thử lại không ngờ dễ."},{"example":"彼は案外、細かいことを気にする人だ。","example_reading":"かれはあんがい、こまかいことをきにするひとだ。","example_meaning":"Anh ấy lại là người để ý chuyện nhỏ nhặt."}],"level":"e1"},
{"word":"にもかかわらず","reading":"にもかかわらず","meaning":"mặc dù vậy","note":"Trang trọng. Nối điều trái với kỳ vọng.","example":"大雨だった。にもかかわらず、多くの人が集まった。","example_reading":"おおあめだった。にもかかわらず、おおくのひとがあつまった。","example_meaning":"Trời mưa lớn. Mặc vậy nhiều người vẫn tụ tập.","examples":[{"example":"大雨だった。にもかかわらず、多くの人が集まった。","example_reading":"おおあめだった。にもかかわらず、おおくのひとがあつまった。","example_meaning":"Trời mưa lớn. Mặc vậy nhiều người vẫn tụ tập."},{"example":"注意された。にもかかわらず、彼は同じ間違いを繰り返した。","example_reading":"ちゅういされた。にもかかわらず、かれはおなじまちがいをくりかえした。","example_meaning":"Anh ấy đã bị nhắc nhở. Mặc vậy vẫn lặp lại lỗi cũ."}],"level":"e1"},
{"word":"まさしく","reading":"まさしく","meaning":"đúng là, chính xác là","note":"Văn viết, nhấn mạnh hơn まさに.","example":"これはまさしく、彼が書いた手紙だ。","example_reading":"これはまさしく、かれがかいたてがみだ。","example_meaning":"Đây đích thị là bức thư anh ấy viết.","examples":[{"example":"これはまさしく、彼が書いた手紙だ。","example_reading":"これはまさしく、かれがかいたてがみだ。","example_meaning":"Đây đích thị là bức thư anh ấy viết."},{"example":"その光景は、まさしく地獄のようだった。","example_reading":"そのこうけいは、まさしくじごくのようだった。","example_meaning":"Quang cảnh đó thật sự giống như địa ngục."}],"level":"e1"},
{"word":"どのみち","reading":"どのみち","meaning":"dù thế nào cũng","note":"Hay đi với ～だろう, ～ない. Kết quả không đổi dù chọn cách nào.","example":"どのみち行くのだから、早く支度をしよう。","example_reading":"どのみちいくのだから、はやくしたくをしよう。","example_meaning":"Dù sao cũng phải đi nên mau chuẩn bị thôi.","examples":[{"example":"どのみち行くのだから、早く支度をしよう。","example_reading":"どのみちいくのだから、はやくしたくをしよう。","example_meaning":"Dù sao cũng phải đi nên mau chuẩn bị thôi."},{"example":"今から急いでも、どのみち間に合わない。","example_reading":"いまからいそいでも、どのみちまにあわない。","example_meaning":"Giờ có vội thì cũng không kịp."}],"level":"e1"},
{"word":"実のところ","reading":"じつのところ","meaning":"thực ra thì","hanviet":"thực","note":"Dùng khi nói điều thật lòng hoặc sự thật ít ai biết.","example":"実のところ、私はこの仕事を辞めたいと思っている。","example_reading":"じつのところ、わたしはこのしごとをやめたいとおもっている。","example_meaning":"Thực ra tôi đang muốn nghỉ công việc này.","examples":[{"example":"実のところ、私はこの仕事を辞めたいと思っている。","example_reading":"じつのところ、わたしはこのしごとをやめたいとおもっている。","example_meaning":"Thực ra tôi đang muốn nghỉ công việc này."},{"example":"実のところ、まだ何も決まっていないんです。","example_reading":"じつのところ、まだなにもきまっていないんです。","example_meaning":"Thực ra thì vẫn chưa quyết định được gì cả."}],"level":"e1"},
{"word":"理想を言えば","reading":"りそうをいえば","meaning":"nếu nói lý tưởng","hanviet":"lý tưởng ngôn","antonym":"現実には（げんじつには）: trên thực tế / 実際のところ（じっさいのところ）: thực tế thì","antonym_hanviet":"hiện thực / thực tế","note":"Hay đi với ～たい. Nêu mong muốn lý tưởng nhưng khó thành.","example":"理想を言えば、駅に近くて静かな家に住みたい。","example_reading":"りそうをいえば、えきにちかくてしずかないえにすみたい。","example_meaning":"Lý tưởng nhất là tôi muốn sống ở căn nhà gần ga mà yên tĩnh.","examples":[{"example":"理想を言えば、駅に近くて静かな家に住みたい。","example_reading":"りそうをいえば、えきにちかくてしずかないえにすみたい。","example_meaning":"Lý tưởng nhất là tôi muốn sống ở căn nhà gần ga mà yên tĩnh."},{"example":"理想を言えば、全員が納得できる結論を出したい。","example_reading":"りそうをいえば、ぜんいんがなっとくできるけつろんをだしたい。","example_meaning":"Lý tưởng nhất là đưa ra kết luận mà ai cũng đồng ý."}],"level":"e1"},
{"word":"状況次第では","reading":"じょうきょうしだいでは","meaning":"tùy tình hình thì","hanviet":"trạng huống thứ đệ","note":"Hay đi với ～かもしれない, ～必要がある.","example":"状況次第では、予定を変更するかもしれない。","example_reading":"じょうきょうしだいでは、よていをへんこうするかもしれない。","example_meaning":"Tùy tình hình, có thể tôi sẽ thay đổi kế hoạch.","examples":[{"example":"状況次第では、予定を変更するかもしれない。","example_reading":"じょうきょうしだいでは、よていをへんこうするかもしれない。","example_meaning":"Tùy tình hình, có thể tôi sẽ thay đổi kế hoạch."},{"example":"状況次第では、全員で対応する必要がある。","example_reading":"じょうきょうしだいでは、ぜんいんでたいおうするひつようがある。","example_meaning":"Tùy tình hình, cần cả nhóm cùng ứng phó."}],"level":"e1"},
{"word":"それはそれとして","reading":"それはそれとして","meaning":"chuyện đó gác lại","note":"Tạm gác chuyện trước để nói chuyện khác.","example":"それはそれとして、今日の議題に戻りましょう。","example_reading":"それはそれとして、きょうのぎだいにもどりましょう。","example_meaning":"Chuyện đó gác lại, ta quay về chủ đề hôm nay.","examples":[{"example":"それはそれとして、今日の議題に戻りましょう。","example_reading":"それはそれとして、きょうのぎだいにもどりましょう。","example_meaning":"Chuyện đó gác lại, ta quay về chủ đề hôm nay."},{"example":"それはそれとして、お昼はどこで食べますか。","example_reading":"それはそれとして、おひるはどこでたべますか。","example_meaning":"Chuyện đó để đó, trưa nay ăn ở đâu?"}],"level":"e1"},
{"word":"報道によると","reading":"ほうどうによると","meaning":"theo báo chí","hanviet":"báo đạo","note":"Hay đi với ～そうだ, ～らしい. Dẫn thông tin từ tin tức.","example":"報道によると、今回の事故で十人がけがをしたそうだ。","example_reading":"ほうどうによると、こんかいのじこでじゅうにんがけがをしたそうだ。","example_meaning":"Theo báo chí, vụ tai nạn này có mười người bị thương.","examples":[{"example":"報道によると、今回の事故で十人がけがをしたそうだ。","example_reading":"ほうどうによると、こんかいのじこでじゅうにんがけがをしたそうだ。","example_meaning":"Theo báo chí, vụ tai nạn này có mười người bị thương."},{"example":"報道によると、新しい空港が来年開港する予定だ。","example_reading":"ほうどうによると、あたらしいくうこうがらいねんかいこうするよていだ。","example_meaning":"Theo báo chí, sân bay mới dự kiến khai trương năm sau."}],"level":"e1"},
{"word":"それゆえ","reading":"それゆえ","meaning":"vì vậy, do đó","note":"Văn viết, trang trọng.","example":"彼は経験が豊富だ。それゆえ、皆から信頼されている。","example_reading":"かれはけいけんがほうふだ。それゆえ、みなからしんらいされている。","example_meaning":"Anh ấy giàu kinh nghiệm. Vì vậy được mọi người tin tưởng.","examples":[{"example":"彼は経験が豊富だ。それゆえ、皆から信頼されている。","example_reading":"かれはけいけんがほうふだ。それゆえ、みなからしんらいされている。","example_meaning":"Anh ấy giàu kinh nghiệm. Vì vậy được mọi người tin tưởng."},{"example":"資源には限りがある。それゆえ、大切に使わなければならない。","example_reading":"しげんにはかぎりがある。それゆえ、たいせつにつかわなければならない。","example_meaning":"Tài nguyên có hạn. Do đó phải dùng cho cẩn thận."}],"level":"e1"},
{"word":"見方を変えれば","reading":"みかたをかえれば","meaning":"nhìn từ góc độ khác thì","hanviet":"kiến phương biến","note":"Hay đi với ～になる. Đưa ra cách nhìn mới.","example":"見方を変えれば、これは大きなチャンスだ。","example_reading":"みかたをかえれば、これはおおきなチャンスだ。","example_meaning":"Nhìn từ góc độ khác, đây là cơ hội lớn.","examples":[{"example":"見方を変えれば、これは大きなチャンスだ。","example_reading":"みかたをかえれば、これはおおきなチャンスだ。","example_meaning":"Nhìn từ góc độ khác, đây là cơ hội lớn."},{"example":"失敗も、見方を変えれば貴重な経験になる。","example_reading":"しっぱいも、みかたをかえればきちょうなけいけんになる。","example_meaning":"Thất bại, nhìn theo cách khác cũng là kinh nghiệm quý."}],"level":"e1"},
{"word":"表向きは","reading":"おもてむきは","meaning":"bề ngoài thì","hanviet":"biểu hướng","antonym":"本音を言えば（ほんねをいえば）: nói thật lòng / 実は（じつは）: thật ra / 正直なところ（しょうじきなところ）: nói thật","antonym_hanviet":"bản âm ngôn / thực / chính trực","note":"Hay đi với ～が, 本心は. Đối lập với suy nghĩ thật.","example":"表向きは賛成しているが、本心は違うようだ。","example_reading":"おもてむきはさんせいしているが、ほんしんはちがうようだ。","example_meaning":"Bề ngoài thì đồng ý nhưng lòng thật có vẻ khác.","examples":[{"example":"表向きは賛成しているが、本心は違うようだ。","example_reading":"おもてむきはさんせいしているが、ほんしんはちがうようだ。","example_meaning":"Bề ngoài thì đồng ý nhưng lòng thật có vẻ khác."},{"example":"彼は表向きは穏やかだが、内心では怒っている。","example_reading":"かれはおもてむきはおだやかだが、ないしんではおこっている。","example_meaning":"Bề ngoài anh ấy điềm đạm nhưng trong lòng đang giận."}],"level":"e1"},
{"word":"長くても","reading":"ながくても","meaning":"dài lắm thì","hanviet":"trường","antonym":"短くても（みじかくても）: ngắn nhất","antonym_hanviet":"đoản","note":"Hay đi với ～まで, ～ほど. Giới hạn trên về độ dài.","example":"打ち合わせは、長くても一時間で終わらせたい。","example_reading":"うちあわせは、ながくてもいちじかんでおわらせたい。","example_meaning":"Cuộc bàn bạc, tôi muốn kết thúc trong một giờ là cùng.","examples":[{"example":"打ち合わせは、長くても一時間で終わらせたい。","example_reading":"うちあわせは、ながくてもいちじかんでおわらせたい。","example_meaning":"Cuộc bàn bạc, tôi muốn kết thúc trong một giờ là cùng."},{"example":"この薬の効果は、長くても半日ほどしか続かない。","example_reading":"このくすりのこうかは、ながくてもはんにちほどしかつづかない。","example_meaning":"Hiệu quả của thuốc này kéo dài lắm cũng chỉ nửa ngày."}],"level":"e1"},
{"word":"裏を返せば","reading":"うらをかえせば","meaning":"nói ngược lại thì","hanviet":"lý","note":"Chỉ ý ngầm trái ngược với điều vừa nói.","example":"彼が反対しないのは、裏を返せば賛成していないということだ。","example_reading":"かれがはんたいしないのは、うらをかえせばさんせいしていないということだ。","example_meaning":"Anh ấy không phản đối, nói ngược lại là cũng không tán thành.","examples":[{"example":"彼が反対しないのは、裏を返せば賛成していないということだ。","example_reading":"かれがはんたいしないのは、うらをかえせばさんせいしていないということだ。","example_meaning":"Anh ấy không phản đối, nói ngược lại là cũng không tán thành."},{"example":"「忙しい」と言うのは、裏を返せば余裕がないということだ。","example_reading":"「いそがしい」というのは、うらをかえせばよゆうがないということだ。","example_meaning":"Nói \"bận\", suy ra nghĩa là không còn dư dả."}],"level":"e1"},
{"word":"最低限","reading":"さいていげん","meaning":"tối thiểu","hanviet":"tối đê hạn","antonym":"最大限（さいだいげん）: tối đa","antonym_hanviet":"tối đại hạn","note":"Hay đi với 必要な, 守る, 持つ.","example":"最低限のマナーは守ってほしい。","example_reading":"さいていげんのマナーはまもってほしい。","example_meaning":"Tôi mong bạn giữ phép lịch sự tối thiểu.","examples":[{"example":"最低限のマナーは守ってほしい。","example_reading":"さいていげんのマナーはまもってほしい。","example_meaning":"Tôi mong bạn giữ phép lịch sự tối thiểu."},{"example":"旅行には最低限の荷物だけ持っていく。","example_reading":"りょこうにはさいていげんのにもつだけもっていく。","example_meaning":"Đi du lịch tôi chỉ mang hành lý tối thiểu."}],"level":"e1"},
{"word":"最大限","reading":"さいだいげん","meaning":"tối đa","hanviet":"tối đại hạn","antonym":"最低限（さいていげん）: tối thiểu","antonym_hanviet":"tối đê hạn","note":"Hay đi với 活用する, 努力する, 生かす.","example":"与えられた時間を、最大限に活用したい。","example_reading":"あたえられたじかんを、さいだいげんにかつようしたい。","example_meaning":"Tôi muốn tận dụng tối đa thời gian được cho.","examples":[{"example":"与えられた時間を、最大限に活用したい。","example_reading":"あたえられたじかんを、さいだいげんにかつようしたい。","example_meaning":"Tôi muốn tận dụng tối đa thời gian được cho."},{"example":"事故を防ぐため、最大限の努力をしている。","example_reading":"じこをふせぐため、さいだいげんのどりょくをしている。","example_meaning":"Chúng tôi đang nỗ lực hết mức để ngăn ngừa tai nạn."}],"level":"e1"},
{"word":"意外と","reading":"いがいと","meaning":"không ngờ, hơn tưởng tượng","hanviet":"ý ngoại","antonym":"予想どおり（よそうどおり）: đúng như dự kiến","antonym_hanviet":"dự tưởng","note":"Đọc いがいと. Hay đi với 簡単, 高い, 多い. Khẩu ngữ, gần 案外.","example":"この料理は意外と作るのが簡単だ。","example_reading":"このりょうりはいがいとつくるのがかんたんだ。","example_meaning":"Món này không ngờ làm khá dễ.","examples":[{"example":"この料理は意外と作るのが簡単だ。","example_reading":"このりょうりはいがいとつくるのがかんたんだ。","example_meaning":"Món này không ngờ làm khá dễ."},{"example":"彼は意外と泣き虫なんだよ。","example_reading":"かれはいがいとなきむしなんだよ。","example_meaning":"Anh ấy hóa ra lại hay khóc nhè đấy."}],"level":"e1"},
{"word":"幸い","reading":"さいわい","meaning":"may mắn là","hanviet":"hạnh","antonym":"不幸にも（ふこうにも）: chẳng may / あいにく: tiếc là / 残念ながら（ざんねんながら）: Đáng tiếc là","antonym_hanviet":"bất hạnh /  / tàn niệm","note":"Mở đầu điều may mắn trong rủi ro. Hay đi với ～ことに／～にも.","example":"事故にあったが、幸い怪我はなかった。","example_reading":"じこにあったが、さいわいけがはなかった。","example_meaning":"Tôi bị tai nạn nhưng may mắn là không bị thương.","examples":[{"example":"事故にあったが、幸い怪我はなかった。","example_reading":"じこにあったが、さいわいけがはなかった。","example_meaning":"Tôi bị tai nạn nhưng may mắn là không bị thương."},{"example":"幸い、天気に恵まれて、運動会は無事に開催された。","example_reading":"さいわい、てんきにめぐまれて、うんどうかいはぶじにかいさいされた。","example_meaning":"May mắn thời tiết đẹp nên hội thao đã được tổ chức suôn sẻ."}],"level":"e1"},
{"word":"不幸にも","reading":"ふこうにも","meaning":"chẳng may, thật không may","hanviet":"bất hạnh","antonym":"幸い（さいわい）: may mắn là / 無事に（ぶじに）: bình an / 幸いにも（さいわいにも）: may mắn thay","antonym_hanviet":"hạnh / vô sự / hạnh","note":"Đọc ふこうにも. Hay đi với ～た. Văn viết; trái nghĩa 幸い／幸いにも.","example":"不幸にも、その事故で三人が亡くなった。","example_reading":"ふこうにも、そのじこでさんにんがなくなった。","example_meaning":"Thật không may, ba người đã thiệt mạng trong vụ tai nạn đó.","examples":[{"example":"不幸にも、その事故で三人が亡くなった。","example_reading":"ふこうにも、そのじこでさんにんがなくなった。","example_meaning":"Thật không may, ba người đã thiệt mạng trong vụ tai nạn đó."},{"example":"不幸にも、彼は試合の前日に怪我をしてしまった。","example_reading":"ふこうにも、かれはしあいのぜんじつにけがをしてしまった。","example_meaning":"Chẳng may, anh ấy bị thương vào ngày trước trận đấu."}],"level":"e1"},
{"word":"案の定","reading":"あんのじょう","meaning":"đúng như dự đoán","hanviet":"án định","antonym":"意外にも（いがいにも）: thật bất ngờ là / かえって: ngược lại / 思いがけず（おもいがけず）: bất ngờ","antonym_hanviet":"ý ngoại /  / tư","note":"Kết quả đúng như đã lo ngại (thường là điều xấu).","example":"案の定、彼は約束の時間に遅れてやって来た。","example_reading":"あんのじょう、かれはやくそくのじかんにおくれてやってきた。","example_meaning":"Đúng như dự đoán, anh ta đến muộn so với giờ hẹn.","examples":[{"example":"案の定、彼は約束の時間に遅れてやって来た。","example_reading":"あんのじょう、かれはやくそくのじかんにおくれてやってきた。","example_meaning":"Đúng như dự đoán, anh ta đến muộn so với giờ hẹn."},{"example":"無理な計画だと思っていたが、案の定、途中で失敗した。","example_reading":"むりなけいかくだとおもっていたが、あんのじょう、とちゅうでしっぱいした。","example_meaning":"Tôi đã nghĩ kế hoạch này vô lý, và đúng như dự đoán nó thất bại giữa chừng."}],"level":"e1"},
{"word":"とにもかくにも","reading":"とにもかくにも","meaning":"dù thế nào đi nữa","note":"Nhấn mạnh việc cần làm trước.","example":"とにもかくにも、まず体を休めることが大切だ。","example_reading":"とにもかくにも、まずからだをやすめることがたいせつだ。","example_meaning":"Dù thế nào, điều quan trọng trước hết là nghỉ ngơi.","examples":[{"example":"とにもかくにも、まず体を休めることが大切だ。","example_reading":"とにもかくにも、まずからだをやすめることがたいせつだ。","example_meaning":"Dù thế nào, điều quan trọng trước hết là nghỉ ngơi."},{"example":"とにもかくにも、行ってみなければ分からない。","example_reading":"とにもかくにも、いってみなければわからない。","example_meaning":"Dù thế nào, không đi thử thì không biết được."}],"level":"e1"},
{"word":"のみならず","reading":"のみならず","meaning":"không chỉ","note":"Văn viết, hay đi với ～も. Nêu phạm vi rộng hơn.","example":"彼は、国内のみならず海外でも有名だ。","example_reading":"かれは、こくないのみならずかいがいでもゆうめいだ。","example_meaning":"Anh ấy nổi tiếng không chỉ trong nước mà cả nước ngoài.","examples":[{"example":"彼は、国内のみならず海外でも有名だ。","example_reading":"かれは、こくないのみならずかいがいでもゆうめいだ。","example_meaning":"Anh ấy nổi tiếng không chỉ trong nước mà cả nước ngoài."},{"example":"この問題は、経済のみならず社会全体に影響する。","example_reading":"このもんだいは、けいざいのみならずしゃかいぜんたいにえいきょうする。","example_meaning":"Vấn đề này ảnh hưởng không chỉ đến kinh tế mà cả toàn xã hội."}],"level":"e1"},
{"word":"言うなれば","reading":"いうなれば","meaning":"nói ví von thì","hanviet":"ngôn","note":"Dùng so sánh hình ảnh để mô tả.","example":"彼は、言うなれば町の人気者だ。","example_reading":"かれは、いうなればまちのにんきものだ。","example_meaning":"Anh ấy nói ví von là người nổi tiếng nhất vùng.","examples":[{"example":"彼は、言うなれば町の人気者だ。","example_reading":"かれは、いうなればまちのにんきものだ。","example_meaning":"Anh ấy nói ví von là người nổi tiếng nhất vùng."},{"example":"この本は、言うなれば人生の教科書のようなものだ。","example_reading":"このほんは、いうなればじんせいのきょうかしょのようなものだ。","example_meaning":"Cuốn sách này nói ví von thì giống như sách giáo khoa của cuộc đời."}],"level":"e1"},
{"word":"噂によると","reading":"うわさによると","meaning":"theo tin đồn","hanviet":"đồn","note":"Hay đi với ～らしい, ～そうだ. Nguồn tin không chính thức.","example":"噂によると、駅前に新しいデパートができるらしい。","example_reading":"うわさによると、えきまえにあたらしいデパートができるらしい。","example_meaning":"Theo tin đồn, trước nhà ga sẽ có trung tâm thương mại mới.","examples":[{"example":"噂によると、駅前に新しいデパートができるらしい。","example_reading":"うわさによると、えきまえにあたらしいデパートができるらしい。","example_meaning":"Theo tin đồn, trước nhà ga sẽ có trung tâm thương mại mới."},{"example":"噂によると、社長が交代するそうだ。","example_reading":"うわさによると、しゃちょうがこうたいするそうだ。","example_meaning":"Nghe đồn giám đốc sắp được thay."}],"level":"e1"},
{"word":"余談ながら","reading":"よだんながら","meaning":"nói ngoài lề","hanviet":"dư đàm","note":"Văn viết, trang trọng. Thêm chuyện không chính.","example":"余談ながら、この店は昔、本屋だったそうです。","example_reading":"よだんながら、このみせはむかし、ほんやだったそうです。","example_meaning":"Nói ngoài lề, nghe nói cửa hàng này trước kia là hiệu sách.","examples":[{"example":"余談ながら、この店は昔、本屋だったそうです。","example_reading":"よだんながら、このみせはむかし、ほんやだったそうです。","example_meaning":"Nói ngoài lề, nghe nói cửa hàng này trước kia là hiệu sách."},{"example":"余談ながら、この作品は実話に基づいている。","example_reading":"よだんながら、このさくひんはじつわにもとづいている。","example_meaning":"Nói thêm, tác phẩm này dựa trên chuyện có thật."}],"level":"e1"},
{"word":"不思議と","reading":"ふしぎと","meaning":"lạ thay, kỳ lạ là","hanviet":"bất tư nghị","note":"Hay đi với 気がする, 落ち着く. Việc xảy ra khác thường, không giải thích được.","example":"不思議と、あの店に行くといつも良いことがある。","example_reading":"ふしぎと、あのみせにいくといつもよいことがある。","example_meaning":"Lạ thay, hễ đến quán đó là luôn có chuyện tốt.","examples":[{"example":"不思議と、あの店に行くといつも良いことがある。","example_reading":"ふしぎと、あのみせにいくといつもよいことがある。","example_meaning":"Lạ thay, hễ đến quán đó là luôn có chuyện tốt."},{"example":"緊張すると思ったが、不思議と落ち着いていた。","example_reading":"きんちょうするとおもったが、ふしぎとおちついていた。","example_meaning":"Tôi tưởng sẽ căng thẳng, nhưng lạ là lại bình tĩnh."}],"level":"e1"},
{"word":"ひょっとして","reading":"ひょっとして","meaning":"biết đâu, hay là","note":"Suy đoán bất ngờ, hay dùng trong câu hỏi ～ですか. Khẩu ngữ. Biến thể: ひょっとしたら.","example":"ひょっとして、あなたは田中さんのお姉さんですか。","example_reading":"ひょっとして、あなたはたなかさんのおねえさんですか。","example_meaning":"Hay là bạn là chị của anh Tanaka?","examples":[{"example":"ひょっとして、あなたは田中さんのお姉さんですか。","example_reading":"ひょっとして、あなたはたなかさんのおねえさんですか。","example_meaning":"Hay là bạn là chị của anh Tanaka?"},{"example":"ひょっとして、私の話を聞いていなかったのですか。","example_reading":"ひょっとして、わたしのはなしをきいていなかったのですか。","example_meaning":"Hay là bạn đã không nghe tôi nói?"}],"level":"e1"},
{"word":"紛れもなく","reading":"まぎれもなく","meaning":"rõ ràng, không thể nhầm lẫn","hanviet":"phân","note":"Dùng khẳng định điều hiển nhiên.","example":"これは紛れもなく、彼が書いた文字だ。","example_reading":"これはまぎれもなく、かれがかいたもじだ。","example_meaning":"Đây rõ ràng là chữ do anh ấy viết.","examples":[{"example":"これは紛れもなく、彼が書いた文字だ。","example_reading":"これはまぎれもなく、かれがかいたもじだ。","example_meaning":"Đây rõ ràng là chữ do anh ấy viết."},{"example":"彼女は紛れもなく、この大会の優勝者だ。","example_reading":"かのじょはまぎれもなく、このたいかいのゆうしょうしゃだ。","example_meaning":"Cô ấy chính là nhà vô địch của giải này, không thể nhầm."}],"level":"e1"},
{"word":"疑いなく","reading":"うたがいなく","meaning":"không nghi ngờ gì","hanviet":"nghi","note":"Khẳng định chắc chắn. Văn viết.","example":"彼女の才能は、疑いなく本物だ。","example_reading":"かのじょのさいのうは、うたがいなくほんものだ。","example_meaning":"Tài năng của cô ấy chắc chắn là thật.","examples":[{"example":"彼女の才能は、疑いなく本物だ。","example_reading":"かのじょのさいのうは、うたがいなくほんものだ。","example_meaning":"Tài năng của cô ấy chắc chắn là thật."},{"example":"これが、疑いなく最良の方法だと思う。","example_reading":"これが、うたがいなくさいりょうのほうほうだとおもう。","example_meaning":"Tôi nghĩ đây chắc chắn là phương pháp tốt nhất."}],"level":"e1"},
{"word":"考えようによっては","reading":"かんがえようによっては","meaning":"tùy cách nghĩ thì","hanviet":"khảo","note":"Hay đi với ～とも言える. Nêu cách nhìn khác.","example":"考えようによっては、今の状況はそれほど悪くない。","example_reading":"かんがえようによっては、いまのじょうきょうはそれほどわるくない。","example_meaning":"Tùy cách nghĩ, tình hình hiện tại không đến nỗi tệ.","examples":[{"example":"考えようによっては、今の状況はそれほど悪くない。","example_reading":"かんがえようによっては、いまのじょうきょうはそれほどわるくない。","example_meaning":"Tùy cách nghĩ, tình hình hiện tại không đến nỗi tệ."},{"example":"考えようによっては、これは幸運だったとも言える。","example_reading":"かんがえようによっては、これはこううんだったともいえる。","example_meaning":"Tùy cách nghĩ, cũng có thể nói đây là điều may."}],"level":"e1"},
{"word":"半面","reading":"はんめん","meaning":"mặt khác","hanviet":"bán diện","note":"Gần 反面. Nêu mặt còn lại của cùng sự vật.","example":"彼は厳しい半面、とても面倒見がいい。","example_reading":"かれはきびしいはんめん、とてもめんどうみがいい。","example_meaning":"Anh ấy nghiêm khắc, nhưng mặt khác lại rất chu đáo.","examples":[{"example":"彼は厳しい半面、とても面倒見がいい。","example_reading":"かれはきびしいはんめん、とてもめんどうみがいい。","example_meaning":"Anh ấy nghiêm khắc, nhưng mặt khác lại rất chu đáo."},{"example":"成功の半面、失ったものも多い。","example_reading":"せいこうのはんめん、うしなったものもおおい。","example_meaning":"Bên cạnh thành công là nhiều thứ đã mất."}],"level":"e1"},
{"word":"ひょっとすると","reading":"ひょっとすると","meaning":"biết đâu, có khi","note":"Hay đi với ～かもしれない. Khả năng thấp nhưng có thể xảy ra; gần ひょっとして.","example":"ひょっとすると、彼は来ないかもしれない。","example_reading":"ひょっとすると、かれはこないかもしれない。","example_meaning":"Biết đâu anh ấy sẽ không đến.","examples":[{"example":"ひょっとすると、彼は来ないかもしれない。","example_reading":"ひょっとすると、かれはこないかもしれない。","example_meaning":"Biết đâu anh ấy sẽ không đến."},{"example":"ひょっとすると、あの人が犯人なのかもしれない。","example_reading":"ひょっとすると、あのひとがはんにんなのかもしれない。","example_meaning":"Có khi người đó chính là thủ phạm."}],"level":"e1"},
{"word":"とかく","reading":"とかく","meaning":"hay, thường (xu hướng không tốt)","note":"Đi với ～がちだ, ～ものだ.","example":"若いうちは、とかく無理をしがちだ。","example_reading":"わかいうちは、とかくむりをしがちだ。","example_meaning":"Khi còn trẻ, người ta hay có xu hướng cố quá sức.","examples":[{"example":"若いうちは、とかく無理をしがちだ。","example_reading":"わかいうちは、とかくむりをしがちだ。","example_meaning":"Khi còn trẻ, người ta hay có xu hướng cố quá sức."},{"example":"とかく世間は噂が好きなものだ。","example_reading":"とかくせけんはうわさがすきなものだ。","example_meaning":"Thiên hạ vốn hay thích bàn tán tin đồn."}],"level":"e1"},
{"word":"どことなく","reading":"どことなく","meaning":"phảng phất, thoáng","note":"Hay đi với 似ている, 寂しい, 違う.","example":"彼はどことなく父に似ている。","example_reading":"かれはどことなくちちににている。","example_meaning":"Anh ấy phảng phất giống bố tôi.","examples":[{"example":"彼はどことなく父に似ている。","example_reading":"かれはどことなくちちににている。","example_meaning":"Anh ấy phảng phất giống bố tôi."},{"example":"秋の夕方は、どことなく寂しい気持ちになる。","example_reading":"あきのゆうがたは、どことなくさびしいきもちになる。","example_meaning":"Chiều thu khiến lòng tôi thoáng chút buồn."}],"level":"e1"},
{"word":"さりげなく","reading":"さりげなく","meaning":"một cách tự nhiên, khéo léo","antonym":"露骨に（ろこつに）: lộ liễu / わざとらしく: giả tạo","antonym_hanviet":"lộ cốt / ","note":"Làm mà không để lộ ý. Dùng cho hành động tinh tế.","example":"彼はさりげなく、私のかばんを持ってくれた。","example_reading":"かれはさりげなく、わたしのかばんをもってくれた。","example_meaning":"Anh ấy khéo léo xách giúp tôi cái cặp.","examples":[{"example":"彼はさりげなく、私のかばんを持ってくれた。","example_reading":"かれはさりげなく、わたしのかばんをもってくれた。","example_meaning":"Anh ấy khéo léo xách giúp tôi cái cặp."},{"example":"さりげなく話題を変えて、気まずい空気を避けた。","example_reading":"さりげなくわだいをかえて、きまずいくうきをさけた。","example_meaning":"Tôi khéo léo đổi chủ đề để tránh bầu không khí khó xử."}],"level":"e1"},
{"word":"あくまで","reading":"あくまで","meaning":"đến cùng, chỉ là","note":"Nhấn mạnh lập trường: bám đến cùng, hoặc \"chỉ là\". Dạng あくまでも. Hay đi với ～だ／～と主張する.","example":"これはあくまで私の個人的な意見です。","example_reading":"これはあくまでわたしのこじんてきないけんです。","example_meaning":"Đây chỉ là ý kiến cá nhân của tôi.","examples":[{"example":"これはあくまで私の個人的な意見です。","example_reading":"これはあくまでわたしのこじんてきないけんです。","example_meaning":"Đây chỉ là ý kiến cá nhân của tôi."},{"example":"彼はあくまで自分の考えを貫くつもりだ。","example_reading":"かれはあくまでじぶんのかんがえをつらぬくつもりだ。","example_meaning":"Anh ấy định bám đến cùng quan điểm của mình."}],"level":"e1"},
{"word":"聞くところによると","reading":"きくところによると","meaning":"theo như nghe nói","hanviet":"văn","note":"Hay đi với ～そうだ, ～らしい. Dẫn thông tin nghe được.","example":"聞くところによると、彼は来月結婚するそうだ。","example_reading":"きくところによると、かれはらいげつけっこんするそうだ。","example_meaning":"Nghe nói anh ấy sẽ kết hôn vào tháng sau.","examples":[{"example":"聞くところによると、彼は来月結婚するそうだ。","example_reading":"きくところによると、かれはらいげつけっこんするそうだ。","example_meaning":"Nghe nói anh ấy sẽ kết hôn vào tháng sau."},{"example":"聞くところによると、あの店は来年閉店するらしい。","example_reading":"きくところによると、あのみせはらいねんへいてんするらしい。","example_meaning":"Theo nghe nói, cửa hàng đó sẽ đóng cửa năm sau."}],"level":"e1"},
{"word":"概ね","reading":"おおむね","meaning":"đại thể, nhìn chung","hanviet":"khái","antonym":"細かく（こまかく）: chi tiết / 厳密には（げんみつには）: nói chính xác","antonym_hanviet":"tế / nghiêm mật","note":"Đọc おおむね. Hay đi với ～良好だ, ～予定どおり, ～賛成. Gần およそ nhưng dùng khi đánh giá chung; văn viết.","example":"工事は概ね予定どおりに進んでいる。","example_reading":"こうじはおおむねよていどおりにすすんでいる。","example_meaning":"Công trình nhìn chung đang tiến hành đúng kế hoạch.","examples":[{"example":"工事は概ね予定どおりに進んでいる。","example_reading":"こうじはおおむねよていどおりにすすんでいる。","example_meaning":"Công trình nhìn chung đang tiến hành đúng kế hoạch."},{"example":"アンケートの結果は、概ね良好だった。","example_reading":"アンケートのけっかは、おおむねりょうこうだった。","example_meaning":"Kết quả khảo sát nhìn chung là tốt."}],"level":"e1"},
{"word":"なおかつ","reading":"なおかつ","meaning":"hơn nữa, vừa… lại","note":"Nối hai tính chất tốt cùng lúc. Văn viết.","example":"この製品は安く、なおかつ品質も高い。","example_reading":"このせいひんはやすく、なおかつひんしつもたかい。","example_meaning":"Sản phẩm này rẻ mà chất lượng cũng cao.","examples":[{"example":"この製品は安く、なおかつ品質も高い。","example_reading":"このせいひんはやすく、なおかつひんしつもたかい。","example_meaning":"Sản phẩm này rẻ mà chất lượng cũng cao."},{"example":"彼は優秀で、なおかつ誰にでも親切だ。","example_reading":"かれはゆうしゅうで、なおかつだれにでもしんせつだ。","example_meaning":"Anh ấy giỏi mà lại thân thiện với mọi người."}],"level":"e1"},
{"word":"およそ","reading":"およそ","meaning":"khoảng, đại khái; nói chung","antonym":"正確に（せいかくに）: chính xác","antonym_hanviet":"chính xác","note":"Ước lượng số lượng, hoặc \"nói chung／hoàn toàn\" (đi với ない). Văn viết.","example":"ここから駅まで、およそ十分かかります。","example_reading":"ここからえきまで、およそじっぷんかかります。","example_meaning":"Từ đây đến ga mất khoảng mười phút.","examples":[{"example":"ここから駅まで、およそ十分かかります。","example_reading":"ここからえきまで、およそじっぷんかかります。","example_meaning":"Từ đây đến ga mất khoảng mười phút."},{"example":"およそ人間である以上、誰にでも欠点がある。","example_reading":"およそにんげんであるいじょう、だれにでもけってんがある。","example_meaning":"Đã là con người thì ai cũng có khuyết điểm."}],"level":"e1"},
{"word":"一般に","reading":"いっぱんに","meaning":"nói chung, thông thường","hanviet":"nhất ban","antonym":"特に（とくに）: đặc biệt","antonym_hanviet":"đặc","note":"Đọc いっぱんに. Hay đi với ～と言われている, ～ことが多い. Nói về xu hướng chung.","example":"一般に、冬は夏より電気代が高くなる。","example_reading":"いっぱんに、ふゆはなつよりでんきだいがたかくなる。","example_meaning":"Nói chung, mùa đông tiền điện cao hơn mùa hè.","examples":[{"example":"一般に、冬は夏より電気代が高くなる。","example_reading":"いっぱんに、ふゆはなつよりでんきだいがたかくなる。","example_meaning":"Nói chung, mùa đông tiền điện cao hơn mùa hè."},{"example":"この病気は、一般に子どもに多いとされる。","example_reading":"このびょうきは、いっぱんにこどもにおおいとされる。","example_meaning":"Bệnh này thường được cho là hay gặp ở trẻ em."}],"level":"e1"},
{"word":"長い目で見れば","reading":"ながいめでみれば","meaning":"nhìn về lâu dài thì","hanviet":"trường mục kiến","note":"Hay đi với ～役に立つ, ～損ではない.","example":"長い目で見れば、今の苦労は必ず役に立つ。","example_reading":"ながいめでみれば、いまのくろうはかならずやくにたつ。","example_meaning":"Nhìn về lâu dài, nỗi vất vả hiện tại chắc chắn sẽ có ích.","examples":[{"example":"長い目で見れば、今の苦労は必ず役に立つ。","example_reading":"ながいめでみれば、いまのくろうはかならずやくにたつ。","example_meaning":"Nhìn về lâu dài, nỗi vất vả hiện tại chắc chắn sẽ có ích."},{"example":"長い目で見れば、この投資は損にはならないだろう。","example_reading":"ながいめでみれば、このとうしはそんにはならないだろう。","example_meaning":"Về lâu dài, khoản đầu tư này có lẽ sẽ không lỗ."}],"level":"e1"},
{"word":"主に","reading":"おもに","meaning":"chủ yếu","hanviet":"chủ","antonym":"副次的に（ふくじてきに）: thứ yếu","antonym_hanviet":"phó thứ đích","note":"Đọc おもに. Hay đi với 使われる, 担当する. Phần lớn, trọng tâm.","example":"この薬は主に頭痛のときに使われる。","example_reading":"このくすりはおもにずつうのときにつかわれる。","example_meaning":"Thuốc này chủ yếu dùng khi đau đầu.","examples":[{"example":"この薬は主に頭痛のときに使われる。","example_reading":"このくすりはおもにずつうのときにつかわれる。","example_meaning":"Thuốc này chủ yếu dùng khi đau đầu."},{"example":"私は主に営業を担当しています。","example_reading":"わたしはおもにえいぎょうをたんとうしています。","example_meaning":"Tôi chủ yếu phụ trách bán hàng."}],"level":"e1"},
{"word":"基本的に","reading":"きほんてきに","meaning":"về cơ bản","hanviet":"cơ bản đích","antonym":"例外的に（れいがいてきに）: ngoại lệ","antonym_hanviet":"lệ ngoại đích","note":"Đọc きほんてきに. Hay đi với ～は, ～ない. Nguyên tắc chung, có thể có ngoại lệ.","example":"基本的に、土日は休みです。","example_reading":"きほんてきに、どにちはやすみです。","example_meaning":"Về cơ bản, thứ Bảy Chủ nhật là ngày nghỉ.","examples":[{"example":"基本的に、土日は休みです。","example_reading":"きほんてきに、どにちはやすみです。","example_meaning":"Về cơ bản, thứ Bảy Chủ nhật là ngày nghỉ."},{"example":"彼の意見には基本的に賛成だ。","example_reading":"かれのいけんにはきほんてきにさんせいだ。","example_meaning":"Về cơ bản tôi tán thành ý kiến của anh ấy."}],"level":"e1"},
{"word":"惜しくも","reading":"おしくも","meaning":"tiếc thay","hanviet":"tích","note":"Hay đi với 敗れる, 逃す, 二位.","example":"惜しくも、決勝で一点差で敗れた。","example_reading":"おしくも、けっしょうでいってんさでやぶれた。","example_meaning":"Tiếc thay, chúng tôi thua chung kết chỉ kém một điểm.","examples":[{"example":"惜しくも、決勝で一点差で敗れた。","example_reading":"おしくも、けっしょうでいってんさでやぶれた。","example_meaning":"Tiếc thay, chúng tôi thua chung kết chỉ kém một điểm."},{"example":"彼は惜しくも二位に終わった。","example_reading":"かれはおしくもにいにおわった。","example_meaning":"Anh ấy tiếc thay chỉ về nhì."}],"level":"e1"},
{"word":"思う存分","reading":"おもうぞんぶん","meaning":"thỏa thích","hanviet":"tư tồn phân","antonym":"控えめに（ひかえめに）: vừa phải / 遠慮がちに（えんりょがちに）: dè dặt","antonym_hanviet":"khống / viễn lự","note":"Hay đi với 楽しむ, 食べる, 暴れる.","example":"久しぶりの休みに、思う存分眠った。","example_reading":"ひさしぶりのやすみに、おもうぞんぶんねむった。","example_meaning":"Được nghỉ sau thời gian dài, tôi ngủ thỏa thích.","examples":[{"example":"久しぶりの休みに、思う存分眠った。","example_reading":"ひさしぶりのやすみに、おもうぞんぶんねむった。","example_meaning":"Được nghỉ sau thời gian dài, tôi ngủ thỏa thích."},{"example":"広い公園で、思う存分走り回った。","example_reading":"ひろいこうえんで、おもうぞんぶんはしりまわった。","example_meaning":"Trong công viên rộng, tôi chạy nhảy thỏa thích."}],"level":"e1"},
{"word":"総じて","reading":"そうじて","meaning":"nhìn chung","hanviet":"tổng","antonym":"個別に（こべつに）: riêng từng cái","antonym_hanviet":"cá biệt","note":"Đánh giá khái quát. Văn viết.","example":"今年の新入社員は、総じて真面目だ。","example_reading":"ことしのしんにゅうしゃいんは、そうじてまじめだ。","example_meaning":"Nhân viên mới năm nay nhìn chung đều chăm chỉ.","examples":[{"example":"今年の新入社員は、総じて真面目だ。","example_reading":"ことしのしんにゅうしゃいんは、そうじてまじめだ。","example_meaning":"Nhân viên mới năm nay nhìn chung đều chăm chỉ."},{"example":"総じて、今回の調査結果は良好だった。","example_reading":"そうじて、こんかいのちょうさけっかはりょうこうだった。","example_meaning":"Nhìn chung, kết quả khảo sát lần này tốt."}],"level":"e1"},
{"word":"事によると","reading":"ことによると","meaning":"biết đâu, có thể","hanviet":"sự","note":"Đi với ～かもしれない. Văn viết, gần もしかすると.","example":"事によると、計画は中止になるかもしれない。","example_reading":"ことによると、けいかくはちゅうしになるかもしれない。","example_meaning":"Biết đâu kế hoạch sẽ bị hủy.","examples":[{"example":"事によると、計画は中止になるかもしれない。","example_reading":"ことによると、けいかくはちゅうしになるかもしれない。","example_meaning":"Biết đâu kế hoạch sẽ bị hủy."},{"example":"この天気だと、事によると飛行機が飛ばないかもしれない。","example_reading":"このてんきだと、ことによるとひこうきがとばないかもしれない。","example_meaning":"Thời tiết thế này, có thể máy bay sẽ không cất cánh."}],"level":"e1"},
{"word":"ないしは","reading":"ないしは","meaning":"hoặc là","note":"Văn viết, pháp lý. Gần ないし.","example":"書面ないしは口頭で、申し込んでください。","example_reading":"しょめんないしはこうとうで、もうしこんでください。","example_meaning":"Xin đăng ký bằng văn bản hoặc bằng lời.","examples":[{"example":"書面ないしは口頭で、申し込んでください。","example_reading":"しょめんないしはこうとうで、もうしこんでください。","example_meaning":"Xin đăng ký bằng văn bản hoặc bằng lời."},{"example":"参加者は、学生ないしは社会人に限る。","example_reading":"さんかしゃは、がくせいないしはしゃかいじんにかぎる。","example_meaning":"Người tham gia chỉ giới hạn ở sinh viên hoặc người đi làm."}],"level":"e1"},
{"word":"十中八九","reading":"じゅっちゅうはっく","meaning":"tám chín phần mười","hanviet":"thập trung bát cửu","note":"Hay đi với ～だ, 間違いない. Gần như chắc chắn.","example":"この様子だと、十中八九、試合は中止になる。","example_reading":"このようすだと、じゅっちゅうはっく、しあいはちゅうしになる。","example_meaning":"Tình hình này thì tám chín phần mười trận đấu sẽ bị hủy.","examples":[{"example":"この様子だと、十中八九、試合は中止になる。","example_reading":"このようすだと、じゅっちゅうはっく、しあいはちゅうしになる。","example_meaning":"Tình hình này thì tám chín phần mười trận đấu sẽ bị hủy."},{"example":"彼が犯人であることは、十中八九間違いない。","example_reading":"かれがはんにんであることは、じゅっちゅうはっくまちがいない。","example_meaning":"Anh ta là thủ phạm gần như chắc chắn."}],"level":"e1"},
{"word":"想像するに","reading":"そうぞうするに","meaning":"tôi đoán rằng","hanviet":"tưởng tượng","note":"Văn viết. Đưa ra suy đoán.","example":"想像するに、彼は何か事情があって遅れたのだろう。","example_reading":"そうぞうするに、かれはなにかじじょうがあっておくれたのだろう。","example_meaning":"Tôi đoán anh ấy bị chậm vì có lý do gì đó.","examples":[{"example":"想像するに、彼は何か事情があって遅れたのだろう。","example_reading":"そうぞうするに、かれはなにかじじょうがあっておくれたのだろう。","example_meaning":"Tôi đoán anh ấy bị chậm vì có lý do gì đó."},{"example":"想像するに、彼女はすでに結論を出しているはずだ。","example_reading":"そうぞうするに、かのじょはすでにけつろんをだしているはずだ。","example_meaning":"Tôi đoán cô ấy đã có kết luận rồi."}],"level":"e1"},
{"word":"及び","reading":"および","meaning":"và, cùng với","hanviet":"cập","note":"Văn bản hành chính, pháp lý. Nối danh từ ngang hàng.","example":"参加者の氏名、及び連絡先を記入してください。","example_reading":"さんかしゃのしめい、およびれんらくさきをきにゅうしてください。","example_meaning":"Xin hãy ghi họ tên và thông tin liên lạc của người tham gia.","examples":[{"example":"参加者の氏名、及び連絡先を記入してください。","example_reading":"さんかしゃのしめい、およびれんらくさきをきにゅうしてください。","example_meaning":"Xin hãy ghi họ tên và thông tin liên lạc của người tham gia."},{"example":"本製品は国内、及び海外で販売されている。","example_reading":"ほんせいひんはこくない、およびかいがいではんばいされている。","example_meaning":"Sản phẩm này được bán trong nước và ở nước ngoài."}],"level":"e1"},
{"word":"つまるところ","reading":"つまるところ","meaning":"nói cho cùng","note":"Gần 結局のところ, nhấn mạnh bản chất.","example":"つまるところ、大切なのは本人のやる気だ。","example_reading":"つまるところ、たいせつなのはほんにんのやるきだ。","example_meaning":"Nói cho cùng, điều quan trọng là ý chí của chính người đó.","examples":[{"example":"つまるところ、大切なのは本人のやる気だ。","example_reading":"つまるところ、たいせつなのはほんにんのやるきだ。","example_meaning":"Nói cho cùng, điều quan trọng là ý chí của chính người đó."},{"example":"つまるところ、彼は私に謝ってほしかっただけなのだ。","example_reading":"つまるところ、かれはわたしにあやまってほしかっただけなのだ。","example_meaning":"Nói cho cùng, anh ấy chỉ muốn tôi xin lỗi mà thôi."}],"level":"e1"},
{"word":"結果的に","reading":"けっかてきに","meaning":"kết cục là, rốt cuộc","hanviet":"kết quả đích","antonym":"意図的に（いとてきに）: có chủ ý","antonym_hanviet":"ý đồ đích","note":"Đọc けっかてきに. Hay đi với ～た. Nhìn lại kết quả sau cùng, dù ban đầu không định.","example":"遠回りをしたが、結果的に早く着いた。","example_reading":"とおまわりをしたが、けっかてきにはやくついた。","example_meaning":"Tuy đi đường vòng nhưng rốt cuộc lại đến sớm.","examples":[{"example":"遠回りをしたが、結果的に早く着いた。","example_reading":"とおまわりをしたが、けっかてきにはやくついた。","example_meaning":"Tuy đi đường vòng nhưng rốt cuộc lại đến sớm."},{"example":"結果的に、この選択は正しかった。","example_reading":"けっかてきに、このせんたくはただしかった。","example_meaning":"Rốt cuộc lựa chọn này là đúng."}],"level":"e1"},
{"word":"前述のとおり","reading":"ぜんじゅつのとおり","meaning":"như đã nói ở trên","hanviet":"tiền thuật","note":"Văn bản, báo cáo. Nhắc lại điều đã nêu.","antonym":"以下のとおり（いかのとおり）: như sau","antonym_hanviet":"dĩ hạ","example":"前述のとおり、この制度には問題がある。","example_reading":"ぜんじゅつのとおり、このせいどにはもんだいがある。","example_meaning":"Như đã nêu ở trên, chế độ này có vấn đề.","examples":[{"example":"前述のとおり、この制度には問題がある。","example_reading":"ぜんじゅつのとおり、このせいどにはもんだいがある。","example_meaning":"Như đã nêu ở trên, chế độ này có vấn đề."},{"example":"前述のとおり、申し込みは来週までです。","example_reading":"ぜんじゅつのとおり、もうしこみはらいしゅうまでです。","example_meaning":"Như đã nói ở trên, hạn đăng ký là đến tuần sau."}],"level":"e1"},
{"word":"周知のとおり","reading":"しゅうちのとおり","meaning":"như mọi người đã biết","hanviet":"chu tri","note":"Dùng khi nêu điều ai cũng biết.","example":"周知のとおり、この地域は地震が多い。","example_reading":"しゅうちのとおり、このちいきはじしんがおおい。","example_meaning":"Như mọi người đã biết, khu vực này hay có động đất.","examples":[{"example":"周知のとおり、この地域は地震が多い。","example_reading":"しゅうちのとおり、このちいきはじしんがおおい。","example_meaning":"Như mọi người đã biết, khu vực này hay có động đất."},{"example":"周知のとおり、彼は優れた研究者だ。","example_reading":"しゅうちのとおり、かれはすぐれたけんきゅうしゃだ。","example_meaning":"Như ai cũng biết, anh ấy là một nhà nghiên cứu xuất sắc."}],"level":"e1"},
{"word":"名目上","reading":"めいもくじょう","meaning":"trên danh nghĩa","hanviet":"danh mục thượng","antonym":"実質的に（じっしつてきに）: về thực chất / 事実上（じじつじょう）: trên thực tế","antonym_hanviet":"thực chất đích / sự thực thượng","note":"Hay đi với は, の. Danh nghĩa khác với thực chất.","example":"彼は名目上は社長だが、実権は持っていない。","example_reading":"かれはめいもくじょうはしゃちょうだが、じっけんはもっていない。","example_meaning":"Anh ta trên danh nghĩa là giám đốc nhưng không có thực quyền.","examples":[{"example":"彼は名目上は社長だが、実権は持っていない。","example_reading":"かれはめいもくじょうはしゃちょうだが、じっけんはもっていない。","example_meaning":"Anh ta trên danh nghĩa là giám đốc nhưng không có thực quyền."},{"example":"名目上の理由は出張だが、実は旅行に行っている。","example_reading":"めいもくじょうのりゆうはしゅっちょうだが、じつはりょこうにいっている。","example_meaning":"Lý do danh nghĩa là đi công tác, nhưng thực ra là đi du lịch."}],"level":"e1"},
{"word":"形式上","reading":"けいしきじょう","meaning":"về mặt hình thức","hanviet":"hình thức thượng","antonym":"実質的に（じっしつてきに）: về thực chất / 実際には（じっさいには）: trên thực tế","antonym_hanviet":"thực chất đích / thực tế","note":"Hay đi với は, の. Hình thức khác với nội dung.","example":"形式上は、私が責任者ということになっている。","example_reading":"けいしきじょうは、わたしがせきにんしゃということになっている。","example_meaning":"Về mặt hình thức, tôi là người chịu trách nhiệm.","examples":[{"example":"形式上は、私が責任者ということになっている。","example_reading":"けいしきじょうは、わたしがせきにんしゃということになっている。","example_meaning":"Về mặt hình thức, tôi là người chịu trách nhiệm."},{"example":"形式上の手続きを済ませただけで、中身はまだ決まっていない。","example_reading":"けいしきじょうのてつづきをすませただけで、なかみはまだきまっていない。","example_meaning":"Mới chỉ xong thủ tục hình thức, nội dung vẫn chưa định."}],"level":"e1"},
{"word":"大局的に見れば","reading":"たいきょくてきにみれば","meaning":"nhìn tổng thể đại cục thì","hanviet":"đại cục đích","antonym":"局所的に見れば（きょくしょてきにみれば）: nhìn cục bộ / 細かく見れば（こまかくみれば）: nhìn chi tiết","antonym_hanviet":"cục sở đích kiến / tế kiến","note":"Nhìn toàn cảnh, không sa vào chi tiết.","example":"大局的に見れば、今回の失敗は小さな問題だ。","example_reading":"たいきょくてきにみれば、こんかいのしっぱいはちいさなもんだいだ。","example_meaning":"Nhìn tổng thể, thất bại lần này chỉ là vấn đề nhỏ.","examples":[{"example":"大局的に見れば、今回の失敗は小さな問題だ。","example_reading":"たいきょくてきにみれば、こんかいのしっぱいはちいさなもんだいだ。","example_meaning":"Nhìn tổng thể, thất bại lần này chỉ là vấn đề nhỏ."},{"example":"大局的に見れば、景気は回復に向かっている。","example_reading":"たいきょくてきにみれば、けいきはかいふくにむかっている。","example_meaning":"Nhìn đại cục, nền kinh tế đang hướng tới hồi phục."}],"level":"e1"},
{"word":"概して","reading":"がいして","meaning":"nhìn chung, đại thể","hanviet":"khái","antonym":"個別に（こべつに）: riêng từng cái","antonym_hanviet":"cá biệt","note":"Đánh giá tổng thể, kèm khả năng có ngoại lệ. Văn viết.","example":"日本人は概して時間に正確だと言われる。","example_reading":"にほんにんはがいしてじかんにせいかくだといわれる。","example_meaning":"Người ta nói người Nhật nhìn chung rất đúng giờ.","examples":[{"example":"日本人は概して時間に正確だと言われる。","example_reading":"にほんにんはがいしてじかんにせいかくだといわれる。","example_meaning":"Người ta nói người Nhật nhìn chung rất đúng giờ."},{"example":"概して、都会の人のほうが歩くのが速い。","example_reading":"がいして、とかいのひとのほうがあるくのがはやい。","example_meaning":"Nhìn chung, người thành phố đi bộ nhanh hơn."}],"level":"e1"},
{"word":"殊に","reading":"ことに","meaning":"đặc biệt là","hanviet":"thù","note":"Văn viết. Nêu điều nổi bật hơn cả.","example":"この地方は夏が暑く、殊に八月は厳しい。","example_reading":"このちほうはなつがあつく、ことにはちがつはきびしい。","example_meaning":"Vùng này mùa hè nóng, đặc biệt tháng Tám rất khắc nghiệt.","examples":[{"example":"この地方は夏が暑く、殊に八月は厳しい。","example_reading":"このちほうはなつがあつく、ことにはちがつはきびしい。","example_meaning":"Vùng này mùa hè nóng, đặc biệt tháng Tám rất khắc nghiệt."},{"example":"彼女は音楽、殊にピアノが得意だ。","example_reading":"かのじょはおんがく、ことにピアノがとくいだ。","example_meaning":"Cô ấy giỏi âm nhạc, nhất là piano."}],"level":"e1"},
{"word":"並びに","reading":"ならびに","meaning":"và, cũng như","hanviet":"tịnh","note":"Văn bản pháp lý, hành chính; nối nhóm lớn hơn 及び.","example":"氏名、住所、並びに電話番号を記入してください。","example_reading":"しめい、じゅうしょ、ならびにでんわばんごうをきにゅうしてください。","example_meaning":"Xin ghi họ tên, địa chỉ và cả số điện thoại.","examples":[{"example":"氏名、住所、並びに電話番号を記入してください。","example_reading":"しめい、じゅうしょ、ならびにでんわばんごうをきにゅうしてください。","example_meaning":"Xin ghi họ tên, địa chỉ và cả số điện thoại."},{"example":"本校の教職員、並びに生徒に適用される。","example_reading":"ほんこうのきょうしょくいん、ならびにせいとにてきようされる。","example_meaning":"Áp dụng cho giáo viên, nhân viên cũng như học sinh của trường."}],"level":"e1"},
{"word":"察するに","reading":"さっするに","meaning":"đoán chừng","hanviet":"sát","note":"Văn viết. Suy đoán từ tình hình.","example":"察するに、彼は本当のことを言っていない。","example_reading":"さっするに、かれはほんとうのことをいっていない。","example_meaning":"Đoán chừng anh ta không nói thật.","examples":[{"example":"察するに、彼は本当のことを言っていない。","example_reading":"さっするに、かれはほんとうのことをいっていない。","example_meaning":"Đoán chừng anh ta không nói thật."},{"example":"察するに、二人の間に何かあったようだ。","example_reading":"さっするに、ふたりのあいだになにかあったようだ。","example_meaning":"Đoán chừng giữa hai người đã có chuyện gì đó."}],"level":"e1"},
{"word":"願わくは","reading":"ねがわくは","meaning":"mong rằng","hanviet":"nguyện","note":"Văn viết cổ. Bày tỏ mong ước.","example":"願わくは、この平和がいつまでも続くように。","example_reading":"ねがわくは、このへいわがいつまでもつづくように。","example_meaning":"Mong rằng hòa bình này kéo dài mãi mãi.","examples":[{"example":"願わくは、この平和がいつまでも続くように。","example_reading":"ねがわくは、このへいわがいつまでもつづくように。","example_meaning":"Mong rằng hòa bình này kéo dài mãi mãi."},{"example":"願わくは、皆さんの笑顔が絶えませんように。","example_reading":"ねがわくは、みなさんのえがおがたえませんように。","example_meaning":"Mong nụ cười của mọi người không bao giờ tắt."}],"level":"e1"},
{"word":"ともすれば","reading":"ともすれば","meaning":"dễ có xu hướng, hay","note":"Đi với ～がちだ. Xu hướng thường thiên về tiêu cực.","example":"忙しいと、ともすれば食事がおろそかになりがちだ。","example_reading":"いそがしいと、ともすればしょくじがおろそかになりがちだ。","example_meaning":"Khi bận, bữa ăn dễ bị bỏ bê.","examples":[{"example":"忙しいと、ともすれば食事がおろそかになりがちだ。","example_reading":"いそがしいと、ともすればしょくじがおろそかになりがちだ。","example_meaning":"Khi bận, bữa ăn dễ bị bỏ bê."},{"example":"慣れてくると、ともすれば基本を忘れてしまう。","example_reading":"なれてくると、ともすればきほんをわすれてしまう。","example_meaning":"Quen rồi thì dễ quên mất điều cơ bản."}],"level":"e1"},
{"word":"えてして","reading":"えてして","meaning":"thường hay, dễ","note":"Đi với ～がちだ, ～ものだ. Xu hướng thường gặp.","example":"完璧を求めすぎると、えてして失敗する。","example_reading":"かんぺきをもとめすぎると、えてしてしっぱいする。","example_meaning":"Đòi hỏi quá mức hoàn hảo thì thường dễ thất bại.","examples":[{"example":"完璧を求めすぎると、えてして失敗する。","example_reading":"かんぺきをもとめすぎると、えてしてしっぱいする。","example_meaning":"Đòi hỏi quá mức hoàn hảo thì thường dễ thất bại."},{"example":"簡単そうに見えることほど、えてして難しいものだ。","example_reading":"かんたんそうにみえることほど、えてしてむずかしいものだ。","example_meaning":"Việc trông có vẻ dễ thường lại khó."}],"level":"e1"},
{"word":"ざっと","reading":"ざっと","meaning":"sơ qua, khoảng chừng","antonym":"詳しく（くわしく）: chi tiết / じっくり: kỹ lưỡng / 逐一（ちくいち）: từng chút một","antonym_hanviet":"tường /  / trục nhất","note":"Xem lướt hoặc ước lượng đại khái. Khẩu ngữ.","example":"資料にはざっと目を通しておきました。","example_reading":"しりょうにはざっとめをとおしておきました。","example_meaning":"Tôi đã xem lướt qua tài liệu.","examples":[{"example":"資料にはざっと目を通しておきました。","example_reading":"しりょうにはざっとめをとおしておきました。","example_meaning":"Tôi đã xem lướt qua tài liệu."},{"example":"参加者は、ざっと三百人はいただろう。","example_reading":"さんかしゃは、ざっとさんびゃくにんはいただろう。","example_meaning":"Người tham gia chắc phải khoảng ba trăm người."}],"level":"e1"},
{"word":"他方","reading":"たほう","meaning":"mặt khác, bên kia","hanviet":"tha phương","note":"Đọc たほう. Văn viết, đối lập hai phía; gần 一方. Hay dùng sau 一方は～.","example":"一方は賛成し、他方は反対した。","example_reading":"いっぽうはさんせいし、たほうははんたいした。","example_meaning":"Một bên tán thành, bên kia phản đối.","examples":[{"example":"一方は賛成し、他方は反対した。","example_reading":"いっぽうはさんせいし、たほうははんたいした。","example_meaning":"Một bên tán thành, bên kia phản đối."},{"example":"他方、環境への影響も考えなければならない。","example_reading":"たほう、かんきょうへのえいきょうもかんがえなければならない。","example_meaning":"Mặt khác, cũng phải xét đến ảnh hưởng với môi trường."}],"level":"e1"},
{"word":"かつ","reading":"かつ","meaning":"đồng thời, vừa… vừa","note":"Văn viết. Nối hai tính chất cùng tồn tại.","example":"この計画は実現可能、かつ効果的だ。","example_reading":"このけいかくはじつげんかのう、かつこうかてきだ。","example_meaning":"Kế hoạch này khả thi và đồng thời hiệu quả.","examples":[{"example":"この計画は実現可能、かつ効果的だ。","example_reading":"このけいかくはじつげんかのう、かつこうかてきだ。","example_meaning":"Kế hoạch này khả thi và đồng thời hiệu quả."},{"example":"審査は公正、かつ迅速に行われた。","example_reading":"しんさはこうせい、かつじんそくにおこなわれた。","example_meaning":"Việc thẩm định được tiến hành công bằng và nhanh chóng."}],"level":"e1"},
{"word":"驚くべきことに","reading":"おどろくべきことに","meaning":"đáng ngạc nhiên là","hanviet":"kinh","note":"Mở đầu câu để nhấn mạnh điều bất ngờ.","example":"驚くべきことに、彼は一人でその山を登りきった。","example_reading":"おどろくべきことに、かれはひとりでそのやまをのぼりきった。","example_meaning":"Đáng ngạc nhiên là anh ấy đã một mình leo hết ngọn núi đó.","examples":[{"example":"驚くべきことに、彼は一人でその山を登りきった。","example_reading":"おどろくべきことに、かれはひとりでそのやまをのぼりきった。","example_meaning":"Đáng ngạc nhiên là anh ấy đã một mình leo hết ngọn núi đó."},{"example":"驚くべきことに、その薬はわずか三日で効果を示した。","example_reading":"おどろくべきことに、そのくすりはわずかみっかでこうかをしめした。","example_meaning":"Đáng ngạc nhiên là loại thuốc đó có tác dụng chỉ sau ba ngày."}],"level":"e1"},
{"word":"一言で言えば","reading":"ひとことでいえば","meaning":"nói tóm gọn","hanviet":"nhất ngôn","note":"Dùng để tóm tắt bản chất trong một câu.","example":"一言で言えば、この計画は時期尚早だ。","example_reading":"ひとことでいえば、このけいかくはじきしょうそうだ。","example_meaning":"Nói gọn lại, kế hoạch này còn quá sớm.","examples":[{"example":"一言で言えば、この計画は時期尚早だ。","example_reading":"ひとことでいえば、このけいかくはじきしょうそうだ。","example_meaning":"Nói gọn lại, kế hoạch này còn quá sớm."},{"example":"彼の性格を一言で言えば、真面目だ。","example_reading":"かれのせいかくをひとことでいえば、まじめだ。","example_meaning":"Nếu nói gọn tính cách anh ấy thì là nghiêm túc."}],"level":"e1"},
{"word":"実質的に","reading":"じっしつてきに","meaning":"về thực chất","hanviet":"thực chất đích","antonym":"名目上（めいもくじょう）: trên danh nghĩa / 形式上（けいしきじょう）: về mặt hình thức","antonym_hanviet":"danh mục thượng / hình thức thượng","note":"Hay đi với 同じ, 運営する. Nhìn vào thực tế bên trong, không phải hình thức.","example":"この制度は、実質的には値上げと同じだ。","example_reading":"このせいどは、じっしつてきにはねあげとおなじだ。","example_meaning":"Chế độ này về thực chất giống như tăng giá.","examples":[{"example":"この制度は、実質的には値上げと同じだ。","example_reading":"このせいどは、じっしつてきにはねあげとおなじだ。","example_meaning":"Chế độ này về thực chất giống như tăng giá."},{"example":"彼は実質的にこの会社を動かしている。","example_reading":"かれはじっしつてきにこのかいしゃをうごかしている。","example_meaning":"Anh ấy trên thực tế đang điều hành công ty này."}],"level":"e1"},
{"word":"従って","reading":"したがって","meaning":"do đó, vì vậy","hanviet":"tòng","antonym":"しかし: tuy nhiên","note":"Đọc したがって. Hay đi với ～である。従って～. Văn viết, đưa ra kết luận hợp lý.","example":"この製品は安全性が高い。従って、多くの学校で使われている。","example_reading":"このせいひんはあんぜんせいがたかい。したがって、おおくのがっこうでつかわれている。","example_meaning":"Sản phẩm này có độ an toàn cao. Do đó nhiều trường học đang dùng.","examples":[{"example":"この製品は安全性が高い。従って、多くの学校で使われている。","example_reading":"このせいひんはあんぜんせいがたかい。したがって、おおくのがっこうでつかわれている。","example_meaning":"Sản phẩm này có độ an toàn cao. Do đó nhiều trường học đang dùng."},{"example":"道が混んでいる。従って、電車で行ったほうがいい。","example_reading":"みちがこんでいる。したがって、でんしゃでいったほうがいい。","example_meaning":"Đường đang kẹt. Vì vậy nên đi bằng tàu."}],"level":"e1"},
{"word":"換言すれば","reading":"かんげんすれば","meaning":"nói cách khác","hanviet":"hoán ngôn","note":"Văn viết. Gần 言い換えれば.","example":"換言すれば、この制度は失敗だったということだ。","example_reading":"かんげんすれば、このせいどはしっぱいだったということだ。","example_meaning":"Nói cách khác, chế độ này đã thất bại.","examples":[{"example":"換言すれば、この制度は失敗だったということだ。","example_reading":"かんげんすれば、このせいどはしっぱいだったということだ。","example_meaning":"Nói cách khác, chế độ này đã thất bại."},{"example":"彼の主張は、換言すれば責任の放棄だ。","example_reading":"かれのしゅちょうは、かんげんすればせきにんのほうきだ。","example_meaning":"Lập luận của anh ta, nói cách khác, là từ bỏ trách nhiệm."}],"level":"e1"},
{"word":"ややもすれば","reading":"ややもすれば","meaning":"dễ, hay (thiên về xấu)","note":"Tương tự ともすれば nhưng cổ hơn. Đi với ～がちだ.","example":"成功すると、ややもすれば人は慢心しがちだ。","example_reading":"せいこうすると、ややもすればひとはまんしんしがちだ。","example_meaning":"Khi thành công, người ta dễ sinh ra tự mãn.","examples":[{"example":"成功すると、ややもすれば人は慢心しがちだ。","example_reading":"せいこうすると、ややもすればひとはまんしんしがちだ。","example_meaning":"Khi thành công, người ta dễ sinh ra tự mãn."},{"example":"ややもすれば、自分のことだけを考えてしまう。","example_reading":"ややもすれば、じぶんのことだけをかんがえてしまう。","example_meaning":"Con người dễ chỉ nghĩ đến bản thân."}],"level":"e1"},
{"word":"あまつさえ","reading":"あまつさえ","meaning":"hơn thế nữa","note":"Văn viết cổ. Nêu điều tệ hơn.","example":"彼は借金を返さず、あまつさえ新たな借金を重ねた。","example_reading":"かれはしゃっきんをかえさず、あまつさえあらたなしゃっきんをかさねた。","example_meaning":"Anh ta không trả nợ, hơn thế còn vay thêm nợ mới.","examples":[{"example":"彼は借金を返さず、あまつさえ新たな借金を重ねた。","example_reading":"かれはしゃっきんをかえさず、あまつさえあらたなしゃっきんをかさねた。","example_meaning":"Anh ta không trả nợ, hơn thế còn vay thêm nợ mới."},{"example":"雨が降り、あまつさえ風まで強くなってきた。","example_reading":"あめがふり、あまつさえかぜまでつよくなってきた。","example_meaning":"Mưa đã rơi, hơn nữa gió cũng mạnh lên."}],"level":"e1"},
{"word":"平たく言えば","reading":"ひらたくいえば","meaning":"nói đơn giản","hanviet":"bình ngôn","antonym":"厳密には（げんみつには）: nói chính xác","antonym_hanviet":"nghiêm mật","note":"Dùng giải thích dễ hiểu.","example":"平たく言えば、これは値上げのお知らせだ。","example_reading":"ひらたくいえば、これはねあげのおしらせだ。","example_meaning":"Nói đơn giản, đây là thông báo tăng giá.","examples":[{"example":"平たく言えば、これは値上げのお知らせだ。","example_reading":"ひらたくいえば、これはねあげのおしらせだ。","example_meaning":"Nói đơn giản, đây là thông báo tăng giá."},{"example":"平たく言えば、もっと勉強しろということだ。","example_reading":"ひらたくいえば、もっとべんきょうしろということだ。","example_meaning":"Nói đơn giản, nghĩa là hãy học nhiều hơn."}],"level":"e1"},
{"word":"要は","reading":"ようは","meaning":"tóm lại, điều cốt lõi là","hanviet":"yếu","note":"Rút gọn vấn đề chính, khẩu ngữ hơn 要するに. Hay đi với ～ということだ／～かだ.","example":"要は、やる気があるかどうかの問題だ。","example_reading":"ようは、やるきがあるかどうかのもんだいだ。","example_meaning":"Tóm lại là vấn đề ở chỗ có quyết tâm hay không.","examples":[{"example":"要は、やる気があるかどうかの問題だ。","example_reading":"ようは、やるきがあるかどうかのもんだいだ。","example_meaning":"Tóm lại là vấn đề ở chỗ có quyết tâm hay không."},{"example":"要は、気持ちの持ち方が大切なのだ。","example_reading":"ようは、きもちのもちかたがたいせつなのだ。","example_meaning":"Điều cốt lõi là cách giữ tinh thần mới quan trọng."}],"level":"e1"},
{"word":"同様に","reading":"どうように","meaning":"tương tự, giống như vậy","hanviet":"đồng dạng","antonym":"反対に（はんたいに）: ngược lại","antonym_hanviet":"phản đối","note":"Đọc どうように. Hay đi với ～と同様に, ～も同様に. Nối ý giống nhau.","example":"去年と同様に、今年も売り上げは好調だ。","example_reading":"きょねんとどうように、ことしもうりあげはこうちょうだ。","example_meaning":"Giống năm ngoái, năm nay doanh thu cũng tốt.","examples":[{"example":"去年と同様に、今年も売り上げは好調だ。","example_reading":"きょねんとどうように、ことしもうりあげはこうちょうだ。","example_meaning":"Giống năm ngoái, năm nay doanh thu cũng tốt."},{"example":"彼女は母親と同様に、料理が上手だ。","example_reading":"かのじょははははおやとどうように、りょうりがじょうずだ。","example_meaning":"Giống mẹ, cô ấy nấu ăn giỏi."}],"level":"e1"},
{"word":"いわば","reading":"いわば","meaning":"nói cách khác là, có thể nói là","note":"Ví von để dễ hiểu. Hay đi với ～ようなものだ／～だ.","example":"彼は私にとって、いわば命の恩人だ。","example_reading":"かれはわたしにとって、いわばいのちのおんじんだ。","example_meaning":"Với tôi, anh ấy có thể nói là ân nhân cứu mạng.","examples":[{"example":"彼は私にとって、いわば命の恩人だ。","example_reading":"かれはわたしにとって、いわばいのちのおんじんだ。","example_meaning":"Với tôi, anh ấy có thể nói là ân nhân cứu mạng."},{"example":"この仕事は、いわば縁の下の力持ちのようなものだ。","example_reading":"このしごとは、いわばえんのしたのちからもちのようなものだ。","example_meaning":"Công việc này có thể nói giống như người âm thầm hỗ trợ phía sau."}],"level":"e1"},
{"word":"ないし","reading":"ないし","meaning":"từ… đến; hoặc","note":"Văn bản pháp lý, hành chính. Hay ～ないし～: từ… đến…, hoặc.","example":"応募者は二名ないし三名を選ぶ予定だ。","example_reading":"おうぼしゃはにめいないしさんめいをえらぶよていだ。","example_meaning":"Dự kiến chọn từ hai đến ba người trong số ứng viên.","examples":[{"example":"応募者は二名ないし三名を選ぶ予定だ。","example_reading":"おうぼしゃはにめいないしさんめいをえらぶよていだ。","example_meaning":"Dự kiến chọn từ hai đến ba người trong số ứng viên."},{"example":"電話、ないしメールでご連絡ください。","example_reading":"でんわ、ないしメールでごれんらくください。","example_meaning":"Xin hãy liên hệ bằng điện thoại hoặc email."}],"level":"e1"},
{"word":"言わずもがな","reading":"いわずもがな","meaning":"khỏi cần nói","hanviet":"ngôn","note":"Hay đi với だ, のこと. Điều hiển nhiên không cần nói. Văn viết.","example":"子どもでさえ知っているのだから、大人は言わずもがなだ。","example_reading":"こどもでさえしっているのだから、おとなはいわずもがなだ。","example_meaning":"Đến trẻ con còn biết, người lớn thì khỏi phải nói.","examples":[{"example":"子どもでさえ知っているのだから、大人は言わずもがなだ。","example_reading":"こどもでさえしっているのだから、おとなはいわずもがなだ。","example_meaning":"Đến trẻ con còn biết, người lớn thì khỏi phải nói."},{"example":"言わずもがなのことだが、念のため伝えておく。","example_reading":"いわずもがなのことだが、ねんのためつたえておく。","example_meaning":"Chuyện này khỏi cần nói nhưng tôi vẫn nhắc cho chắc."}],"level":"e1"},
{"word":"厳密には","reading":"げんみつには","meaning":"nói chính xác thì","hanviet":"nghiêm mật","antonym":"大まかに言えば（おおまかにいえば）: nói đại khái / 概ね（おおむね）: đại thể / 平たく言えば（ひらたくいえば）: nói đơn giản","antonym_hanviet":"đại ngôn / khái / bình ngôn","note":"Dùng khi đính chính hoặc nói rõ hơn điều vừa nêu.","example":"厳密には、これは事故ではなく故意の行為だ。","example_reading":"げんみつには、これはじこではなくこいのこういだ。","example_meaning":"Nói chính xác thì đây không phải tai nạn mà là hành vi cố ý.","examples":[{"example":"厳密には、これは事故ではなく故意の行為だ。","example_reading":"げんみつには、これはじこではなくこいのこういだ。","example_meaning":"Nói chính xác thì đây không phải tai nạn mà là hành vi cố ý."},{"example":"厳密には、まだ契約が成立したわけではない。","example_reading":"げんみつには、まだけいやくがせいりつしたわけではない。","example_meaning":"Nói cho chính xác thì hợp đồng vẫn chưa được ký kết."}],"level":"e1"},
{"word":"本質的に","reading":"ほんしつてきに","meaning":"về bản chất","hanviet":"bản chất đích","antonym":"表面的に（ひょうめんてきに）: bề ngoài","antonym_hanviet":"biểu diện đích","note":"Hay đi với 違う, 同じ. Nhìn vào cốt lõi.","example":"この二つの問題は、本質的には同じものだ。","example_reading":"このふたつのもんだいは、ほんしつてきにはおなじものだ。","example_meaning":"Hai vấn đề này về bản chất là một.","examples":[{"example":"この二つの問題は、本質的には同じものだ。","example_reading":"このふたつのもんだいは、ほんしつてきにはおなじものだ。","example_meaning":"Hai vấn đề này về bản chất là một."},{"example":"彼の考え方は、本質的に私とは違う。","example_reading":"かれのかんがえかたは、ほんしつてきにわたしとはちがう。","example_meaning":"Cách nghĩ của anh ấy về bản chất khác tôi."}],"level":"e1"},
{"word":"図らずも","reading":"はからずも","meaning":"không ngờ, tình cờ","hanviet":"đồ","antonym":"意図的に（いとてきに）: có chủ ý / 故意に（こいに）: cố ý / わざと: cố ý","antonym_hanviet":"ý đồ đích / cố ý / ","note":"Văn viết. Việc xảy ra ngoài ý định.","example":"図らずも、旧友と再会することになった。","example_reading":"はからずも、きゅうゆうとさいかいすることになった。","example_meaning":"Không ngờ, tôi lại gặp lại người bạn cũ.","examples":[{"example":"図らずも、旧友と再会することになった。","example_reading":"はからずも、きゅうゆうとさいかいすることになった。","example_meaning":"Không ngờ, tôi lại gặp lại người bạn cũ."},{"example":"図らずも、彼の意見が採用される結果となった。","example_reading":"はからずも、かれのいけんがさいようされるけっかとなった。","example_meaning":"Ngoài dự định, ý kiến của anh ấy lại được chọn."}],"level":"e1"},
{"word":"故意に","reading":"こいに","meaning":"cố ý, cố tình","hanviet":"cố ý","antonym":"偶然に（ぐうぜんに）: tình cờ / うっかり: vô ý / 図らずも（はからずも）: không ngờ","antonym_hanviet":"ngẫu nhiên /  / đồ","note":"Văn viết, pháp lý. Gần わざと.","example":"彼は故意に規則を破ったわけではない。","example_reading":"かれはこいにきそくをやぶったわけではない。","example_meaning":"Anh ấy không phải cố ý phá luật.","examples":[{"example":"彼は故意に規則を破ったわけではない。","example_reading":"かれはこいにきそくをやぶったわけではない。","example_meaning":"Anh ấy không phải cố ý phá luật."},{"example":"資料を故意に隠すのは、重大な違反だ。","example_reading":"しりょうをこいにかくすのは、じゅうだいないはんだ。","example_meaning":"Cố tình giấu tài liệu là vi phạm nghiêm trọng."}],"level":"e1"},
{"word":"何より","reading":"なにより","meaning":"hơn hết, quan trọng nhất","hanviet":"hà","note":"Đọc なにより. Hay đi với ～だ／何よりです. Điều quan trọng hoặc đáng mừng nhất.","example":"合格できて、何より嬉しい。","example_reading":"ごうかくできて、なによりうれしい。","example_meaning":"Đỗ được là điều tôi vui nhất.","examples":[{"example":"合格できて、何より嬉しい。","example_reading":"ごうかくできて、なによりうれしい。","example_meaning":"Đỗ được là điều tôi vui nhất."},{"example":"元気そうで、何よりです。","example_reading":"げんきそうで、なによりです。","example_meaning":"Thấy bạn khỏe là điều đáng mừng nhất."}],"level":"e1"},
{"word":"何しろ","reading":"なにしろ","meaning":"dù sao thì, vì dù gì","hanviet":"hà","note":"Giải thích lý do, nhấn mạnh hoàn cảnh đặc thù. Hay đi với ～から／～ので／～のだ.","example":"何しろ十年ぶりの帰国だから、緊張している。","example_reading":"なにしろじゅうねんぶりのきこくだから、きんちょうしている。","example_meaning":"Dù sao cũng là lần về nước sau mười năm nên tôi hồi hộp.","examples":[{"example":"何しろ十年ぶりの帰国だから、緊張している。","example_reading":"なにしろじゅうねんぶりのきこくだから、きんちょうしている。","example_meaning":"Dù sao cũng là lần về nước sau mười năm nên tôi hồi hộp."},{"example":"何しろ急な話だったので、準備が間に合わなかった。","example_reading":"なにしろきゅうなはなしだったので、じゅんびがまにあわなかった。","example_meaning":"Vì dù sao chuyện cũng quá đột ngột nên tôi không kịp chuẩn bị."}],"level":"e1"},
{"word":"事実","reading":"じじつ","meaning":"thực tế là, quả thật","hanviet":"sự thực","note":"Đọc じじつ. Hay đi với 事実、～. Xác nhận bằng sự thật; cũng là danh từ 'sự thật'.","example":"彼は事実、一人で全部やり遂げた。","example_reading":"かれはじじつ、ひとりでぜんぶやりとげた。","example_meaning":"Thực tế anh ấy đã một mình hoàn thành tất cả.","examples":[{"example":"彼は事実、一人で全部やり遂げた。","example_reading":"かれはじじつ、ひとりでぜんぶやりとげた。","example_meaning":"Thực tế anh ấy đã một mình hoàn thành tất cả."},{"example":"事実、この方法で多くの人が成功している。","example_reading":"じじつ、このほうほうでおおくのひとがせいこうしている。","example_meaning":"Thực tế, nhiều người đã thành công bằng cách này."}],"level":"e1"},
{"word":"事実上","reading":"じじつじょう","meaning":"trên thực tế, về mặt thực chất","hanviet":"sự thực thượng","antonym":"形式上（けいしきじょう）: về mặt hình thức / 名目上（めいもくじょう）: trên danh nghĩa","antonym_hanviet":"hình thức thượng / danh mục thượng","note":"Đọc じじつじょう. Hay đi với ～と言える／～と同じだ. Khác với hình thức bề ngoài.","example":"この契約は、事実上の解約と同じだ。","example_reading":"このけいやくは、じじつじょうのかいやくとおなじだ。","example_meaning":"Hợp đồng này thực chất giống với việc hủy hợp đồng.","examples":[{"example":"この契約は、事実上の解約と同じだ。","example_reading":"このけいやくは、じじつじょうのかいやくとおなじだ。","example_meaning":"Hợp đồng này thực chất giống với việc hủy hợp đồng."},{"example":"彼は事実上、この会社の社長だ。","example_reading":"かれはじじつじょう、このかいしゃのしゃちょうだ。","example_meaning":"Trên thực tế, anh ấy là giám đốc của công ty này."}],"level":"e1"},
{"word":"言うまでもなく","reading":"いうまでもなく","meaning":"không cần nói cũng biết","hanviet":"ngôn","note":"Hay đi với ～は, ～も. Nêu điều hiển nhiên. Đọc いうまでもなく.","example":"言うまでもなく、健康が一番大切だ。","example_reading":"いうまでもなく、けんこうがいちばんたいせつだ。","example_meaning":"Không cần nói cũng biết, sức khỏe là quan trọng nhất.","examples":[{"example":"言うまでもなく、健康が一番大切だ。","example_reading":"いうまでもなく、けんこうがいちばんたいせつだ。","example_meaning":"Không cần nói cũng biết, sức khỏe là quan trọng nhất."},{"example":"この仕事が大変なことは、言うまでもなく、みんな知っている。","example_reading":"このしごとがたいへんなことは、いうまでもなく、みんなしっている。","example_meaning":"Công việc này vất vả thì khỏi phải nói, ai cũng biết."}],"level":"e1"},
{"word":"現に","reading":"げんに","meaning":"thực tế là, ngay thực tế","hanviet":"hiện","note":"Dẫn chứng thực tế để chứng minh. Hay đi với ～ている／～た.","example":"夜に歩くのは危険だ。現に、先週も事件があった。","example_reading":"よるにあるくのはきけんだ。げんに、せんしゅうもじけんがあった。","example_meaning":"Đi bộ ban đêm rất nguy hiểm. Thực tế tuần trước cũng đã xảy ra vụ việc.","examples":[{"example":"夜に歩くのは危険だ。現に、先週も事件があった。","example_reading":"よるにあるくのはきけんだ。げんに、せんしゅうもじけんがあった。","example_meaning":"Đi bộ ban đêm rất nguy hiểm. Thực tế tuần trước cũng đã xảy ra vụ việc."},{"example":"彼は現に、先月まで海外で働いていた。","example_reading":"かれはげんに、せんげつまでかいがいではたらいていた。","example_meaning":"Thực tế là anh ấy đã làm việc ở nước ngoài cho đến tháng trước."}],"level":"e1"},
{"word":"それどころか","reading":"それどころか","meaning":"không những thế, trái lại","note":"Phủ định điều trước để nêu điều mạnh hơn hoặc ngược hẳn. Hay đi với ～ない／～ばかりか.","example":"「手伝ってくれた？」「それどころか、邪魔ばかりしていたよ。」","example_reading":"「てつだってくれた？」「それどころか、じゃまばかりしていたよ。」","example_meaning":"\"Anh ấy có giúp không?\" \"Không những thế, còn toàn cản trở nữa.\"","examples":[{"example":"「手伝ってくれた？」「それどころか、邪魔ばかりしていたよ。」","example_reading":"「てつだってくれた？」「それどころか、じゃまばかりしていたよ。」","example_meaning":"\"Anh ấy có giúp không?\" \"Không những thế, còn toàn cản trở nữa.\""},{"example":"薬を飲んでも治らなかった。それどころか、前より悪くなった。","example_reading":"くすりをのんでもなおらなかった。それどころか、まえよりわるくなった。","example_meaning":"Uống thuốc mà không khỏi. Không những thế, còn nặng hơn trước."}],"level":"e1"},
{"word":"ひいては","reading":"ひいては","meaning":"hơn nữa, rộng ra là","note":"Hay đi với ～ことは, ～につながる. Từ việc nhỏ mở rộng đến hệ quả lớn hơn. Văn viết.","example":"この研究は、人々の健康、ひいては社会全体の発展につながる。","example_reading":"このけんきゅうは、ひとびとのけんこう、ひいてはしゃかいぜんたいのはってんにつながる。","example_meaning":"Nghiên cứu này góp phần vào sức khỏe con người, rộng ra là sự phát triển của cả xã hội.","examples":[{"example":"この研究は、人々の健康、ひいては社会全体の発展につながる。","example_reading":"このけんきゅうは、ひとびとのけんこう、ひいてはしゃかいぜんたいのはってんにつながる。","example_meaning":"Nghiên cứu này góp phần vào sức khỏe con người, rộng ra là sự phát triển của cả xã hội."},{"example":"自分のため、ひいては家族のためにも、健康に気をつけよう。","example_reading":"じぶんのため、ひいてはかぞくのためにも、けんこうにきをつけよう。","example_meaning":"Vì bản thân, rộng ra là vì gia đình nữa, hãy chú ý sức khỏe."}],"level":"e1"},
{"word":"さぞ","reading":"さぞ","meaning":"hẳn là, chắc hẳn","note":"Suy đoán cảm xúc của người khác. Đi với ～だろう／～でしょう／～ことと思う. Dạng さぞかし.","example":"長旅で、さぞお疲れでしょう。","example_reading":"ながたびで、さぞおつかれでしょう。","example_meaning":"Đi đường xa chắc hẳn anh mệt lắm.","examples":[{"example":"長旅で、さぞお疲れでしょう。","example_reading":"ながたびで、さぞおつかれでしょう。","example_meaning":"Đi đường xa chắc hẳn anh mệt lắm."},{"example":"合格の知らせを聞いて、ご両親もさぞ喜ばれたことでしょう。","example_reading":"ごうかくのしらせをきいて、ごりょうしんもさぞよろこばれたことでしょう。","example_meaning":"Nghe tin đỗ, chắc hẳn bố mẹ bạn cũng vui lắm."}],"level":"e1"},
{"word":"言い換えれば","reading":"いいかえれば","meaning":"nói cách khác","hanviet":"ngôn hoán","note":"Đọc いいかえれば. Hay đi với ～ということだ. Diễn đạt lại ý đã nêu.","example":"彼は努力家だ。言い換えれば、決してあきらめない人だ。","example_reading":"かれはどりょくかだ。いいかえれば、けっしてあきらめないひとだ。","example_meaning":"Anh ấy là người chăm chỉ. Nói cách khác là người không bao giờ bỏ cuộc.","examples":[{"example":"彼は努力家だ。言い換えれば、決してあきらめない人だ。","example_reading":"かれはどりょくかだ。いいかえれば、けっしてあきらめないひとだ。","example_meaning":"Anh ấy là người chăm chỉ. Nói cách khác là người không bao giờ bỏ cuộc."},{"example":"言い換えれば、これは時間の問題だ。","example_reading":"いいかえれば、これはじかんのもんだいだ。","example_meaning":"Nói cách khác, đây chỉ là vấn đề thời gian."}],"level":"e1"},
{"word":"すなわち","reading":"すなわち","meaning":"tức là, nghĩa là","note":"Giải thích sự đồng nhất, văn viết trang trọng.","example":"彼女は六月、すなわち来月に結婚する予定だ。","example_reading":"かのじょはろくがつ、すなわちらいげつにけっこんするよていだ。","example_meaning":"Cô ấy dự định kết hôn vào tháng Sáu, tức là tháng sau.","examples":[{"example":"彼女は六月、すなわち来月に結婚する予定だ。","example_reading":"かのじょはろくがつ、すなわちらいげつにけっこんするよていだ。","example_meaning":"Cô ấy dự định kết hôn vào tháng Sáu, tức là tháng sau."},{"example":"東京、すなわち日本の首都は人口が最も多い。","example_reading":"とうきょう、すなわちにほんのしゅとはじんこうがもっともおおい。","example_meaning":"Tokyo, tức thủ đô của Nhật Bản, có dân số đông nhất."}],"level":"e1"},
{"word":"故に","reading":"ゆえに","meaning":"cho nên, vì thế","hanviet":"cố","note":"Đọc ゆえに. Hay đi với ～である。故に～. Rất trang trọng, văn chương.","example":"彼は正直な人である。故に、誰からも信頼されている。","example_reading":"かれはしょうじきなひとである。ゆえに、だれからもしんらいされている。","example_meaning":"Anh ấy là người thật thà. Vì vậy ai cũng tin cậy.","examples":[{"example":"彼は正直な人である。故に、誰からも信頼されている。","example_reading":"かれはしょうじきなひとである。ゆえに、だれからもしんらいされている。","example_meaning":"Anh ấy là người thật thà. Vì vậy ai cũng tin cậy."},{"example":"水は生命の源である。故に、大切に守らなければならない。","example_reading":"みずはせいめいのみなもとである。ゆえに、たいせつにまもらなければならない。","example_meaning":"Nước là nguồn sống. Cho nên phải giữ gìn cẩn thận."}],"level":"e1"},
{"word":"強いて","reading":"しいて","meaning":"cố mà nói, nếu buộc phải","hanviet":"cưỡng","note":"Nói khi bị ép phải chọn. Hay đi với ～ば／～なら／～ない.","example":"強いて言えば、私は夏より冬のほうが好きだ。","example_reading":"しいていえば、わたしはなつよりふゆのほうがすきだ。","example_meaning":"Nếu buộc phải nói thì tôi thích mùa đông hơn mùa hè.","examples":[{"example":"強いて言えば、私は夏より冬のほうが好きだ。","example_reading":"しいていえば、わたしはなつよりふゆのほうがすきだ。","example_meaning":"Nếu buộc phải nói thì tôi thích mùa đông hơn mùa hè."},{"example":"強いて欠点を挙げるなら、少し値段が高いことだ。","example_reading":"しいてけってんをあげるなら、すこしねだんがたかいことだ。","example_meaning":"Nếu cố nêu khuyết điểm thì là giá hơi cao."}],"level":"e1"}
],
"grammar": [
{"pattern":"［ナ形・名詞］＋と","usage":"tự khắc, theo lẽ tự nhiên (tiến trình, quy luật)","example":"悲しくて、自然と涙が出てきた。","example_reading":"かなしくて、しぜんとなみだがでてきた。","example_meaning":"Buồn quá, nước mắt tự khắc trào ra."},
{"pattern":"［ナ形・名詞］＋に","usage":"một cách ~ (cách thức, trạng thái của hành động)","example":"自然に話してください。","example_reading":"しぜんにはなしてください。","example_meaning":"Hãy nói chuyện một cách tự nhiên."}
]
};
